INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ankara! Ankara!', 'ankara-ankara-turgay-akbulut-5xjwx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ankara! Ankara! 

Kaldır kafanı bak etrafa

Soyulan bankaların, çıkıyor faturası halka

Kaldır kafanı bak! 

Yapılan zamlarla, incir ağacı diktin

Fakir halkın ocağına

Bak! 

Sabahın köründeki, ucuz ekmek kuyruğuna

Bak! 

Van daki çocukların, çöplükteki yaşamına

Kaybolma! İhtişamlı binalarında

Sanma! 

Her yer Ankara! 

Ekonomi siyaset girmiş kolkola

Yolsuzlukla mücadele; 

Oldu rafadan yumurta

Nasıl yaptın borç bukadar! 

Çocukların geleceği; girdi ipotek altına

Birtek yürek Onda var! 

Helal olsun Tantan''a

Ankara! Ankara! 

Kaldır kafanı bak etrafa

Kulak ver! Umutları tükenen insanlara

Bir bir atlıyor; Boğazın derin sularına

Kaldır kafanı bak! 

Çığ gibi büyüyen, işsizlik ordusuna

Kaldır bedeni! 

Yapışma! 

Ceylan derisi koltuğuna...

...Haziran 2001...', 'Ankara! Ankara!  Kaldır kafanı bak etrafa Soyulan bankaların, çıkıyor faturası halka Kaldır kafanı bak!  Yapılan zamlarla, incir ağacı dikti...', ARRAY['Türk Edebiyatı','Şiir','Turgay Akbulut']::text[], 8.5, '{"poet":"Turgay Akbulut","poet_slug":"turgay-akbulut","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ankara-ankara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuklar', 'cocuklar-yasar-karaman-r4ry7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Küçük dünyalarınız

Melekler kadar temiz

Siz kaynak suları gibi berrak

Çiçek kadar güzelsiniz, 

Hep masallarda kalın

Göklerde çınlasın coşkulu sesleriniz

Oyuncaklarınızı almasınlar elinizden

Keşke büyümeseniz.

Nereden duymuşlarsa bir gün

Susardım sorsalar

Nasıl anlatırdım size ölümü

Çocukları artık ağlatmasalar.', 'Küçük dünyalarınız Melekler kadar temiz Siz kaynak suları gibi berrak Çiçek kadar güzelsiniz,  Hep masallarda kalın Göklerde çınlasın coşkul...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Karaman']::text[], 8.5, '{"poet":"Yaşar Karaman","poet_slug":"yasar-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cocuklar-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'RESİM', 'resi-m-samet-cetin-nkdk5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bana ait olan 

bir resim çizsene kendince

umduğun birşey olmasın yalnız

yaşanmış gerçekler olsun

halen yaşamakta olduğum

beni anlatan var olana dair

hiçbirşeye deva olmayan

sözlerin üstünü örtelim

bir müddet sessiz kalarak

perdelerini aralayalım gözlerin

işte sen o zaman başla

dumanını çizmeye yalnızlığın

izmaritleriyle başımı ağrıtan

kalabalıkları göster mesela

dünden kalma yorgun adımlarımı

anlaşılmayan bakışlarımı gör

bakıldıkça yanlış yorumlanan

kayıp arayışlarımı çiz

sitemkar efkarımla süsle

çıkmazlardan arta kalanları

hüznümü yansıt resmince

güneşli bir güne olan hasretimi

sırtlayışımı vurulmuş fikirleri

kanter içinde kalışımı

savaş meydanlarındaki tedirginliğimi

kırmızıya boya hünerince

kan renginde olsun yeryüzü

gökyüzünü damıtarak kara bulutlara

aç gözlü toprağı doyur yeşile

bin parçaya bölerek avuçlarımda sararmış mutluluğu

gözlerimi kapat ellerinle

kimse görmesin ağladığımı

herkes mutlu sansın beni

usulca gölgeleyip güneşi

dökülmüş yapraklarıyla baharı soldur

ve bırakta fotoğraflarda kalsın tebessümüm

sen yarım kalmış gülüşlerimi resmet

hayat hikayem eksik kalmasın diye

devamını arayabilirsin ikinci kişiliklerde

untkan bilmesinler beni

eş dostu topla etrafıma

ardımda attıkları kahkahalarla

mezarlarını göster, eskiden sevdiklerimi

hep karamsarlık olacak değilya

birde hoşlandığım şeyleri çiz

meçhul meddahları tarihten

bana yol-yordam gösterenlerden

çiçekleri, kuşları, suyu ve özgürlüğü

bir kitabın sayfaları arasından koparıp

görünmeyen sevdalarıma bak

ihaneti, mutsuzluğu ve hüznü çiz biraz

dedimya sözcükler ağır mesaide

sen ressamsın 

bilinmeyen yanlarımı renklerle boyala

yaşanmış saymadığım bir ömrü

bırakarak ardımda

ölümden tanımaya çalış beni

                            davut ekinci''nin anısına

                            30.03.2003', 'bana ait olan  bir resim çizsene kendince umduğun birşey olmasın yalnız yaşanmış gerçekler olsun halen yaşamakta olduğum beni anlatan var ol...', ARRAY['Türk Edebiyatı','Şiir','Samet Çetin']::text[], 8.5, '{"poet":"Samet Çetin","poet_slug":"samet-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/resim-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yollarım', 'yollarim-arif-arslan-gw6s8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'YOLLARIM

Yollarım, yollarım benim yollarım...

Dilerim kapanmaz açık kollarım...

Ulaşır Mevla’ya tüm dualarım...

Yollarım, yollarım benim yollarım... 

Ekim 2004', 'YOLLARIM Yollarım, yollarım benim yollarım... Dilerim kapanmaz açık kollarım... Ulaşır Mevla’ya tüm dualarım... Yollarım, yollarım benim yol...', ARRAY['Türk Edebiyatı','Şiir','Arif Arslan']::text[], 8.5, '{"poet":"Arif Arslan","poet_slug":"arif-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yollarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BAŞKA BİR ŞEY DEMEDİ', 'baska-bi-r-sey-demedi-arif-arslan-wg51j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'BAŞKA BİR ŞEY DEMEDİ

Yıkıldı, düşerken “Allah” diyordu, 

Doğruldu, kalkarken “Allah” diyordu.

Onun kapısında geçti de ömrü; 

Tükendi, yine de “Allah” diyordu.

Saçları ağardı, beli büküldü, 

Gözleri ağardı, dişi döküldü.

“Hizmet” derken ciğerleri söküldü; 

Yine de bıkmadan “Allah” diyordu.

Hakaret ettiler, tebessüm etti, 

Kıymet bilmediler, sineye çekti.

Dalaşmamak için yurdu terk etti; 

Oralarda bile “Allah” diyordu.

Her türlü çileye göğsünü gerdi, 

İsteyen herkese sultanlık verdi.

Bir gaye uğruna yanıp tükendi; 

Son nefeste bile “Allah” diyordu.

12 Ekim 2001', 'BAŞKA BİR ŞEY DEMEDİ Yıkıldı, düşerken “Allah” diyordu,  Doğruldu, kalkarken “Allah” diyordu. Onun kapısında geçti de ömrü;  Tükendi, yine d...', ARRAY['Türk Edebiyatı','Şiir','Arif Arslan']::text[], 8.5, '{"poet":"Arif Arslan","poet_slug":"arif-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/baska-bir-sey-demedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ELBETTE BİRİ VARDIR', 'elbette-bi-ri-vardir-arif-arslan-1i2r5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ELBETTE BİRİ VARDIR

Hep sevilip özlenen daima biri vardır; 

Yıllar boyu gözlenen daima biri vardır

Yüreklerde hasreti, durmadan körüklenen; 

Gelir diye beklenen daima biri vardır.

Kaderimize giren, yolsuza yol gösteren; 

Yanmışlara su veren daima biri vardır.

Bizi bize benzeten, bizi her an gözeten; 

Kendisini özleten daima biri vardır. 

Bir garip olsa bile, yaşasa da gurbette; 

Her an yüreğimizde daima biri vardır.

7 Haziran ‘01', 'ELBETTE BİRİ VARDIR Hep sevilip özlenen daima biri vardır;  Yıllar boyu gözlenen daima biri vardır Yüreklerde hasreti, durmadan körüklenen; ...', ARRAY['Türk Edebiyatı','Şiir','Arif Arslan']::text[], 8.5, '{"poet":"Arif Arslan","poet_slug":"arif-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/elbette-biri-vardir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Akşam', 'ay-aksam-erol-nacar-9n382', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her 

Ay akşamında

Bir

Soru işaretisin! 

Yıllardır bekliyorum...

Her

An

Çıkabilirsin

Bir

Taşın altında.

Benim 

İnce, 

Uzun boylu, 

Kıvrak belli; 

'' S '' leri uzatarak söyleyen sevgilim! ...', 'Her  Ay akşamında Bir Soru işaretisin!  Yıllardır bekliyorum... Her An Çıkabilirsin Bir Taşın altında. Benim  İnce,  Uzun boylu,  Kıvrak bel...', ARRAY['Türk Edebiyatı','Şiir','Erol Nacar']::text[], 8.5, '{"poet":"Erol Nacar","poet_slug":"erol-nacar","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ay-aksam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BiR NiSAN iKi BiN üÇ', 'bir-nisan-iki-bin-uc-salman-celik-kmqd8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'az kaldı köpürecek içimde deniz 

aşklar mı bitti, umutlar mı azaldı 

anlatacak şey yok mu ya da çok mu 

ne varsa gidecek içimden

kafama bir arı girerdi

şüpheleri getirirdi beraberinde

şimdi sadece güldürüüyor beni 

bu kış öyle soğuktu ki, 

gözyaşımı dondurmuş

bahara girerken baktım aynaya

ayrılıklar zinciri, 

gökuşakları, 

köpürmüş denizler

neler gördüm kendi gözlerimde neler

hasretler mi, üzüntüler mi

haykırası sevinçler mi dersiniz

hovardalıklar mı 

her çeşitten bir nevi haykırıştı hepsi

hepsi bir anda yansıdı gözlerimde

yeni bir umuttur bahar bana

yılda dört kere umutlansamda

vazgeçmem

umut güzel şey kayda değer şey

inat olsun umutlanmam lazım

bahar bana ateşleri getirse de

defalarca ölsem de

umutla girmeliyim yaza

hayat aşkıyla girmeliyim

neye yarar yaşamım sonra

esli, işe yaramaz sandalyeden farkım ne olur

şu kağıt andım olsun ki, 

umutla gireceğim yaza', 'az kaldı köpürecek içimde deniz  aşklar mı bitti, umutlar mı azaldı  anlatacak şey yok mu ya da çok mu  ne varsa gidecek içimden kafama bir ...', ARRAY['Türk Edebiyatı','Şiir','Salman Çelik']::text[], 8.5, '{"poet":"Salman Çelik","poet_slug":"salman-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/bir-nisan-iki-bin-uc-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıranlara Selam Olsun', 'kiranlara-selam-olsun-ulku-tamer-x43wz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Selam olsun dağa taşa 

Yaranlara selam olsun

Ormandaki kurda kuşa 

Cerenlere selam olsun

Dünya üstü kara zindan

boynumuzda yağlı urgan 

Yolculardan hancılardan

Soranlara selam olsun

Ölüm canın has yoldaşı 

Diken gülün gönül eşi

Kar altında deniz düşü

Kuranlara selam olsun

Kağıdımız çaput bizim

Kefenimiz bulut bizim

Mesleğimiz umut bizim

Kıranlara selam olsun', 'Selam olsun dağa taşa  Yaranlara selam olsun Ormandaki kurda kuşa  Cerenlere selam olsun Dünya üstü kara zindan boynumuzda yağlı urgan  Yolc...', ARRAY['Türk Edebiyatı','Şiir','Ülkü Tamer']::text[], 8.5, '{"poet":"Ülkü Tamer","poet_slug":"ulku-tamer","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kiranlara-selam-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ODAM VE BEN', 'odam-ve-ben-salman-celik-nqdsf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu akşam ytüm ışıklar söndüğünde

Odamın kapısını rahatlıkla buldum 

öylesi alıştım ki düzenine

girerken solumdaki lambaya elim uzandı 

ama yakmadım

sonra yürüdüm ve açtım penceremi

ay ışığı odamdaydı

odam deniz olmuş ay ışığı ise mehtap 

mehtapta baktım odama 

duvardaki hayranlıklarımı gördüm 

posterlerimi, şiir kartonlarımı

sonra onlara dalıp, düşündüm biraz

çocukluğum, gençliğim

aslında her kiside sürüyordu

bazen hala çocuk ve bir o kadar da

delikanlı hissediyordum kendimi 

yatağıma baktım

gecelerce uyuyamadığım günleri hatırladım 

unuttum sonra...

sonra açtım dolabımı, kitaplarımı gördüm

içinden seçtim herhangi birini 

okumak geldi ya içimden bir kere

ışığı yakmak istemedim 

uzandım yatağıma 

denizde mehtap ve yatağım  sal gibiydi

çok değil beş on dakika okudum 

sonra düşündüm yine 

odam benim her halimle olduğum tek mekandı 

kendi iç dünyamdı 

umutlarımın saklı, sevgilerimin yaşandığı yerdi 

odamla barış içindeydim

bu bana huzur veriyor

hayatı sevmemi sağlıyordu', 'Bu akşam ytüm ışıklar söndüğünde Odamın kapısını rahatlıkla buldum  öylesi alıştım ki düzenine girerken solumdaki lambaya elim uzandı  ama y...', ARRAY['Türk Edebiyatı','Şiir','Salman Çelik']::text[], 8.5, '{"poet":"Salman Çelik","poet_slug":"salman-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/odam-ve-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HAYAL', 'hayal-salman-celik-tdmzp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir yıldız gördüm kör karanlıkta

elleri titreyen bir kız gördüm yağmur altında

çok uzak değil

iki sokak arkada bir oğlan gördüm gözleri yaşlı

usanmadım yürüdüm o karanlıkta

derken 

bir kuş gördüm

üşüyordu

elleri titriyor gibiydi onun da 

onunda gözleri yaşlı olmalıydı

derken şafak söktü, güneş aydınlattı sokakları 

acılı insanlar karanlıkta yok olmuş gibiydiler

penceremin önünden dışarı baktım 

kuş sevinç çığlıklarıyla, kanat çırpıyor

elleri titreyen o masum kız

iki sokak arkada 

diğer çocugun ellerini tutuyordu 

bir anda haykırdım içimden 

neden bu kadar geçici hayat diye

derken hatırladım 

bende bir zamanlar sokakta yatmıştım 

hayat insana her gün aynı şekilde gelmez...', 'Bir yıldız gördüm kör karanlıkta elleri titreyen bir kız gördüm yağmur altında çok uzak değil iki sokak arkada bir oğlan gördüm gözleri yaşl...', ARRAY['Türk Edebiyatı','Şiir','Salman Çelik']::text[], 8.5, '{"poet":"Salman Çelik","poet_slug":"salman-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/hayal-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YEDi OCAK iKi BiN üÇ', 'yedi-ocak-iki-bin-uc-salman-celik-45chs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir Şiir yazamadım şöyle edebince

satırlarım gözlerime dokunup durdu

kalemim umutsuzken mi benimleydi

neden unuttum umutları yaşarken şiirleri

şiir hep kötülük mü anlatacaktı bana

ızdırap, olanaksızlık ve benzwe bir sürü umutsuzluk

umut ve sevgiyi yaşarken şiirler uzaktı bana

yokuşta binip

inişte indiğim arabalar gibi

şidi kırmalıyım bu oluşumu, istiyorum

sana güveniyorum kalemim

sana güveniyorum kağıdım 

anlatacaksın kalbimde oluşan kıpırtıyı, fırtınaları

tasviriyle, mecazıyla tüm güzellikleriyle

hayır, olmuyor

ne yapsam anlatamıyorum sevgi dağarcıklarımı 

anlatacak kadar yoklarmı 

ya da anlatamayacak kadar çoklarmı 

işte bir anda yine bir çıkmaza girdim

tan yine yokuşa geldim derken 

son yazdığım şiiri okudum 

derinden derine sevgi yazıyordu aslında

umduğum bir dünya görebiliyordum 

ve bir amatör şair olarak

şiirimi kağıda dökmeyi başaramadığıma 

sevindim

çünkü

sevgim kağıda anlamlanamayacak kadar

anlatılmaz be büyüktü...', 'Bir Şiir yazamadım şöyle edebince satırlarım gözlerime dokunup durdu kalemim umutsuzken mi benimleydi neden unuttum umutları yaşarken şiirle...', ARRAY['Türk Edebiyatı','Şiir','Salman Çelik']::text[], 8.5, '{"poet":"Salman Çelik","poet_slug":"salman-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/yedi-ocak-iki-bin-uc-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerine Gömdüm Yüreğimi', 'ellerine-gomdum-yuregimi-mine-ozdemirtas-idm6d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Git yolcu

Yolumuz açık olsun. Seninleyim.Sen de beni sakladım

İnanmazsan... yokla bak

Dudaklarının kıvrımına asılmış.... sallanıyor dudaklarım.

Sevdayı katladım  valizine koydum özenle.

Ve Az önce 

o ıssız peronda.... Sana son kez sarıldığımda

Bir de.....Yüreğimi gömdüm ellerine.

Kilometreler aramıza acımasızca yerleşiyor diye 

Sakın üzülme.... Biliyorsun ki 

Yolumuza çıkan gece sisleri Ve o  sisin  gizledikleri.

Sonsuza dek bağladı bizi.

Şimdi......Daya başını arkaya.... kapat gözlerini.

Usulca dolanacağım bedenine.... anılardaki gibi.

Örtüşüp teninle.....Sarıp, sarmalayacağım seni.

Ve sen; yollardaki sevgili... sana....andım olsun ki

Bir an bile...... bensiz kalmayacaksın

Geri döndüğünde ise...... seni bekliyor olacağım.

Yeter ki gel...Gel ve...... bana.... bir seni getir geri.

Bir de..... ellerine gömdüğüm yüreğimi.

.', 'Git yolcu Yolumuz açık olsun. Seninleyim.Sen de beni sakladım İnanmazsan... yokla bak Dudaklarının kıvrımına asılmış.... sallanıyor dudaklar...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ellerine-gomdum-yuregimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostum Dediğim', 'dostum-dedigim-salih-ozalasan-oveso', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dost, dost diye çokça boğuldum gözyaşına

Her döndüğümde arkamı, bıçağı yedim sırtıma

Kader şimdi seni çıkardı benim karşıma

Bilirim ki “Mehmet” asla ihanet etmez dostuna

Bir kardeştir, yüreği yüreğimle bir atar

Yıkılıp düşsem yerlere, beni ilk o kucaklar

Aramızda olsa da aşılmaz sıra dağlar

Canım acısa, bilirim  Mehmet’inde canı yanar

Canıma candır, kanımdan kan misali

Bilirim ki oda bir kardeş bilir Salih’i

Sanırım bende yendim, sonunda kör talihi

Benimde bir dostum var açabileceğim kalbimi

Adana Seyhan’dır onun  mekanı

Belki haritaya baksa bulamaz Bursa Akçaları

Ama biz yok saydık aradaki dağları

Ben bilirim o bilir bizi bir nebze kıranı

Merttir sözünü hiç esirgemez

Ben onu çok severim, ama o beni benden az sevmez

Dilerim bu dostluk mahşere dek bitmez

Yüreğimiz bir atar aramıza kolay, kolay girilmez

Sözümüz birdir, özümüz birdir

Bizde ser verilir sır verilmez

Böyle bir dost dostlar başına

Salih’in sırtı asla yere gelmez

“ Tek dostum Mavardi’ ye armağan”

Yazım tarihi 05-04-2003 Saat 13,30

Salih ÖZALAŞAN', 'Dost, dost diye çokça boğuldum gözyaşına Her döndüğümde arkamı, bıçağı yedim sırtıma Kader şimdi seni çıkardı benim karşıma Bilirim ki “Mehm...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/dostum-dedigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Sıyrığı', 'gece-siyrigi-hamdi-topcu-g0jum', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir deli su isem ben de 

                   Akmam mı hercai

	   Sesimi şamdanların 

                   Şavkında durultup

                   Uyur bırakıp  geceyi

                    Hamağında gelgitlerin

                    Sığınır kuytularına

                    Benim en güzel gemilerim

                    Dul kuşların  tüneğidir

                    Yüreğimin penceresine

                    - Bir  serçe-  konmuşsan 

                    Sabah tez gelir 

                    Ben sana sende gelirim.

                 

                    Bu cama bendoldum

                    Gece sıyrığı gönlüm                    

                    Tövbeye varmaz 

                     Karanfilin sarhoş

                     Kokun mahrem 

                     Bırak kirpiklerim

                     Koynunda ter tarasın senin', 'Bir deli su isem ben de                     Akmam mı hercai 	   Sesimi şamdanların                     Şavkında durultup                    ...', ARRAY['Türk Edebiyatı','Şiir','Hamdi Topçu']::text[], 8.5, '{"poet":"Hamdi Topçu","poet_slug":"hamdi-topcu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gece-siyrigi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazamadığım Mektuplar', 'yazamadigim-mektuplar-salih-ozalasan-8n5v8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yazmadıklarımı yazsam

Aklımdan, yüreğimden geçip yazamadıklarımı

Hayallerimi bir, bir sıralasam

Düşlerimin dışında yapamadıklarımı

Sayfalara sığar mı, alt alta koysam

Bir türlü sana anlatamadıklarımı

Ve bir gün karşına geçip okusam

Yüzüne karşı bir türlü konuşamadıklarımı

Ya ellerim titrer sayfayı tutamazsam

Dilim tutulup okuyamazsam yazdıklarımı

Bilmem ki nasıl yazıp okusam

Gözlerine baktığımda, tenimin alev, alev yandığını

Karşına bu niyetle ne zaman dursam

Kalp atışımın inanılmaz hızlandığını

Yüzümün aldan mora, mordan ala döndüğünü

Görmedim ki bir günde kızarmadığını

Sanırım yazamayacağım ve okuyamayacağım

Sende asla öğrenemeyeceksin yazamadıklarımı

Ve ben kalbimde saklayacağım

Yazamadıklarımla dolu mektuplarımı

Yazım tari.30 03 2003 Saat 12.10

Salih ÖZALAŞAN', 'Yazmadıklarımı yazsam Aklımdan, yüreğimden geçip yazamadıklarımı Hayallerimi bir, bir sıralasam Düşlerimin dışında yapamadıklarımı Sayfalara...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yazamadigim-mektuplar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasak Aşk', 'yasak-ask-salih-ozalasan-al9ox', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nasıl bir sevdaya düşmüş yüreğim

Cehennem ateşiyle yanıyor, yanıyorum

Kavuşmaya yok bir nebze ümidim

Yüreğim kangren kanıyor, kanıyorum

Sevmek yetmiyor çok sevilseniz de

Kimseye seni sevdiğimi diyemiyorum

Siz adına yasak aşk deseniz de

Kalbime vurulmuş kelepçe kırılmıyor, kıramıyorum

Kalbimin sahibi başka dinlemez ferman

Bedenim belki yasta, sende gel diyemiyorum

Bir yanda hayatımı paylaştığım kadınım

Bir yanda canımın içi, vazgeçilmiyor, vazgeçemiyorum

Keşke hiç doğmasaydım, elimde değildi ki

Kaderim baştan yazılmış silemiyorum

Hem sen mutsuz, hem o bu adil değil ki

Kahretsin ölmek istiyorum, bir türlü ölemiyorum

Yazım tarihi 05,04,2003 Saat 13,30

Salih ÖZALAŞAN', 'Nasıl bir sevdaya düşmüş yüreğim Cehennem ateşiyle yanıyor, yanıyorum Kavuşmaya yok bir nebze ümidim Yüreğim kangren kanıyor, kanıyorum Sevm...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yasak-ask-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Olan', 'guzel-olan-salih-ozalasan-ohkj6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevmek; güzel olan seni sevmek

Ölmek; güzel olan seninle ölmek

Gezmek; güzel olan senin kolunda gezmek

Öpmek; güzel olan seni alnından öpmek! 

Yaşamak; güzel olan hayatı seninle sürmek

Ağlamak; güzel olan gözyaşımı ellerinle silmek

Görmek; güzel olan her an seni görmek

Bilmek; güzel olan senin sevdiğini bilmek

Güzel, acı, tatlı, dert, hüzün, say sayabildiğince

Güzel olanı sen varsan katlanabilmek

Hayatımı sana bağlamışım alabildiğince

Yok bir değeri, senin elinde değerlendirmek

Sen bir yana dünya bir yana

Binlerce güzel var ya, zor olan senin kalbine girmek

Başım ersede delip arşı göğe

Önemli olan ölmeden sana ermek

Yazım tarihi 05-04-2003 Saat 15,40', 'Sevmek; güzel olan seni sevmek Ölmek; güzel olan seninle ölmek Gezmek; güzel olan senin kolunda gezmek Öpmek; güzel olan seni alnından öpmek...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/guzel-olan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmurlu Bir Gündü', 'yagmurlu-bir-gundu-ozcan-nevres-lp5uq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yağmurlu Bir Gündü

Nedensiz ayrılmamızda bendim suçlu olan

Gurur denilen saçmalığın esiri olan

Yağmurlu bir gündü hiç unutamam

Yeter artık bitsin demiştim

Vaz geçelim bu sevdadan

Kıskançlığına daha fazla dayanamam

Kollarını dolamıştın boynuma

Demiştin aldırma sen kıskançlığıma

Yürekten seven kıskanır bunu unutma

Gözlerinden yaşlar süzülüyordu

Camda süzülen yağmur damlaları gibi

Çekip gitmiştim göz yaşlarına aldırmadan

Camda süzülüp akan yağmur damlaları

Alıp götürdü beni o mutlu günlerimize

Yüreğime çöktü derin bir sızı

Pişmanlık dağ dağ çöktü yüreğime

Gözlerimden yaşlar süzüldü

Camda süzülen damlalara eşlik edercesine

			Özcan Nevres', 'Yağmurlu Bir Gündü Nedensiz ayrılmamızda bendim suçlu olan Gurur denilen saçmalığın esiri olan Yağmurlu bir gündü hiç unutamam Yeter artık b...', ARRAY['Türk Edebiyatı','Şiir','Özcan Nevres']::text[], 8.5, '{"poet":"Özcan Nevres","poet_slug":"ozcan-nevres","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yagmurlu-bir-gundu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söylenmesi Gereken Ne Varsa', 'soylenmesi-gereken-ne-varsa-melih-coskun-6drl9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mutlaka söylenecek bir gün 

Söylenmesi gereken ne varsa 

Ömür yetmese de

Toprağımda bir bahar günü

Göğsümü yırtıp açan çiçeğin 

Yaprağına bak 

Onda ben konuşuyor olacağım 

Mahşere de kalsa söylenecek her şey 

Sırat’ tan geçerken bir fısıltı çalınacak olursa kulağına 

Bil ki benim sesimdir...

20 Şubat 2003

20: 18', 'Mutlaka söylenecek bir gün  Söylenmesi gereken ne varsa  Ömür yetmese de Toprağımda bir bahar günü Göğsümü yırtıp açan çiçeğin  Yaprağına ba...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/soylenmesi-gereken-ne-varsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BeşYüzeLLi', 'besyuzelli-bulend-b-ki-oylk4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hasret yakar duman eder başımı,

Uyku tutmaz deli gönül kuşumu,

Sabreylesem sıkıversem dişimi,

Beşyüzelli biter beni bitirir! ...', 'Hasret yakar duman eder başımı, Uyku tutmaz deli gönül kuşumu, Sabreylesem sıkıversem dişimi, Beşyüzelli biter beni bitirir! ......', ARRAY['Türk Edebiyatı','Şiir','Bülend Bâki']::text[], 8.5, '{"poet":"Bülend Bâki","poet_slug":"bulend-b-ki","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/besyuzelli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Romantik', 'romantik-murad-guner-v6oep', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kibarca öpülür sizin dudaklarınız

Yıldızlararası yalnızlığınızı ürkütmeden

Tanrı korusun, ürkütmeden

O sıra siz yaz kokarsınız

Duymazsınız belki ama

Yaz kokarsınız

Siz uzun kaldırımlar boyunca

Yollar boyunca sonra

Sonra boyunca sonra

Tadınıza boyayarak hayatı

Haberiniz yokmuş gibi sahiden

Suçsuz bakarsınız', 'Kibarca öpülür sizin dudaklarınız Yıldızlararası yalnızlığınızı ürkütmeden Tanrı korusun, ürkütmeden O sıra siz yaz kokarsınız Duymazsınız b...', ARRAY['Türk Edebiyatı','Şiir','Murad Güner']::text[], 8.5, '{"poet":"Murad Güner","poet_slug":"murad-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/romantik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Paradoks', 'paradoks-murad-guner-ak216', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Koca bir kenti yığdın içime

Şimdi gitmeye kalksam

Nasıl taşınır? 

Şimdi kalmaya kalksam 

Bu yükle 

Nasıl yaşanır?', 'Koca bir kenti yığdın içime Şimdi gitmeye kalksam Nasıl taşınır?  Şimdi kalmaya kalksam  Bu yükle  Nasıl yaşanır?...', ARRAY['Türk Edebiyatı','Şiir','Murad Güner']::text[], 8.5, '{"poet":"Murad Güner","poet_slug":"murad-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/paradoks-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kış Saati', 'kis-saati-murad-guner-27r53', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Söyle de kuşlarına saçlarının

Uçarken Taksim’den denize

-Büyürüm saksımdan ben o sıra-

Beni de alsınlar

Sonyazdır azlığı kalabalığımın

Serince, virgüllü, kendinden yana

Beklerken ortasında dünyanın

Sarı, kızıl ve elma ekşisi bakarak böyle

Kızıyorum aslında günlerin kısalmasına', 'Söyle de kuşlarına saçlarının Uçarken Taksim’den denize -Büyürüm saksımdan ben o sıra- Beni de alsınlar Sonyazdır azlığı kalabalığımın Serin...', ARRAY['Türk Edebiyatı','Şiir','Murad Güner']::text[], 8.5, '{"poet":"Murad Güner","poet_slug":"murad-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kis-saati-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'doğuyor', 'doguyor-kemal-aslan-zhe1j', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'karşılamıyor yeni bir sabahı gözleri çocukların

başlamıyor yeni bir güne kadınlar

ölüyor ulusların kaderi 

ölüyor içişlerine karışmama

doğuyor göz önünde barbarlık', 'karşılamıyor yeni bir sabahı gözleri çocukların başlamıyor yeni bir güne kadınlar ölüyor ulusların kaderi  ölüyor içişlerine karışmama doğuy...', ARRAY['Türk Edebiyatı','Şiir','Kemal Aslan']::text[], 8.5, '{"poet":"Kemal Aslan","poet_slug":"kemal-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/doguyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş', 'dus-murad-guner-26swl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir araba alıp götürüyor bizi

