INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyku', 'uyku-murad-guner-x3s87', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yine geleceksen şimdi buyur git

Nasıl olsa sevmezsin oldun olası ilkbaharı

Çamaşırlar kurur, akşam olur, yemek yenir

Üstüne bir güzel uyunmaz belki bu günün

Yok emin ol uyunmaz

Ama uyku değil mi

Geri geldiğinde uyunur o da', 'Yine geleceksen şimdi buyur git Nasıl olsa sevmezsin oldun olası ilkbaharı Çamaşırlar kurur, akşam olur, yemek yenir Üstüne bir güzel uyunma...', ARRAY['Türk Edebiyatı','Şiir','Murad Güner']::text[], 8.5, '{"poet":"Murad Güner","poet_slug":"murad-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/uyku-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tedavi', 'tedavi-murad-guner-23b0r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hepsi püfür püfür bir sabaha doğrunun ettirdiği 

Olacağı yokken bu grip

Akacağı yokken bu burun

Üstelik tam sigara şartken bu öksürük! 

Aşkın semptomatik tedavisinde

Kaç şekerli içilmeli ıhlamur?', 'Hepsi püfür püfür bir sabaha doğrunun ettirdiği  Olacağı yokken bu grip Akacağı yokken bu burun Üstelik tam sigara şartken bu öksürük!  Aşkı...', ARRAY['Türk Edebiyatı','Şiir','Murad Güner']::text[], 8.5, '{"poet":"Murad Güner","poet_slug":"murad-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/tedavi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BAŞLIKSIZ', 'basliksiz-demiray-talay-2ns8l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '....yazmak gelmiyor içimden ölmek istediğimi, 

....ama ölmek geliyor içimden yaşayamadığım ve yazamadığım için istediklerimi.

..

....koşmak gelmiyor içimden, 

....şehrinboş sokaklarında, 

....koşmak gelmiyor içimden bakışları anlamsız insanlara, 

....kırmak geliyor demirleri, 

....yakmak geliyor içimden, 

....odaları çiçeklerle süslenmiş bu hapishaneyi', '....yazmak gelmiyor içimden ölmek istediğimi,  ....ama ölmek geliyor içimden yaşayamadığım ve yazamadığım için istediklerimi. .. ....koşmak ...', ARRAY['Türk Edebiyatı','Şiir','Demiray Talay']::text[], 8.5, '{"poet":"Demiray Talay","poet_slug":"demiray-talay","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/basliksiz-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duvar', 'duvar-mehmet-ali-kepez-q76rt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kalın    duvar''lar la kör bir  pencere

Sılamı  anarım  gùnde kaç kere

Bilene  bilene  döndùm  hançere

Ey yıkılası  duvar  dost  bekler beni

Yıkılsın koğuşun viran  kalasın

Sen neyin sebebi  kimde yanasın

Hakkın  neferleri  yılmaz bilesin

Ey  yıkılası  duvar  yar  bekler beni

Çatlamış  suratın sıvan dökùlmùş

Niçe saray  paşasıyla yıkılmış

Nerde  gördùn yiğit kolu  bùkùlmùş

Ey yıkılası  duvar halk  bekler beni

Sanmaki  yılmışım ap  aktır içim

Köyùmù özledim bilsen  ne  biçim

Gùn gelir aklanır  bugùnkù  suçum

Ey yıkılası  duvar  can bekler  beni', 'Kalın    duvar''lar la kör bir  pencere Sılamı  anarım  gùnde kaç kere Bilene  bilene  döndùm  hançere Ey yıkılası  duvar  dost  bekler beni ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kepez']::text[], 8.5, '{"poet":"Mehmet Ali Kepez","poet_slug":"mehmet-ali-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/duvar-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarmal', 'sarmal-sair-vagabond-t6zuj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Rahatla

 Gözlerini kapa

   Yere düştüğünü düşün

       Ayakların var ama basamıyorsun

           Ellerin var ama tutunamıyorsun

               Ve yere düştüğünde çaresizlik yerine 

                   Düşüş anının estetiğini, zerafetini düşün

                       Ve yerden yükselmeye başladığını hayal et

                          Ağırlıksızsın artık, uzayda yer kaplamıyorsun

                            Doğrusu Hayat Çekiminden kurtulmuşsun

                           Renkler hayallerinden çok farklılaşacak

                         Çiçekler sadece çicek gibi kokacak

                    Hayat daha basitleşecek

                Korkular anlamsızlaşacak

            Kalıplar şekilsizleşecek

        Bacaklarını hissedeceksin

    Ellerini farkedeceksin

 Güleceksin 

Öleceksin

 Yok olmayacaksın

    Yol almayacaksın

        Hep arayacaksın

            Hiç bulmayacaksın

                Mekanın olmayacak

                    Zamanın olmayacak

                        Kırılgan olmayacaksın

                            Alıngan olmayacaksın

                               Sen olmayacaksın

                             Hıçkırarak aglayacaksın

                        Tarif edemediklerini algilayacaksin

                     Bakmadan göreceksin

                 Duymadan bileceksin

             Yeni formuna karar vereceksin

        Bildiklerini unutacaksın

     Bedenini sececeksin

 Ruhuna yol vereceksin

Doğacaksın', 'Rahatla  Gözlerini kapa    Yere düştüğünü düşün        Ayakların var ama basamıyorsun            Ellerin var ama tutunamıyorsun             ...', ARRAY['Türk Edebiyatı','Şiir','Şair Vagabond']::text[], 8.5, '{"poet":"Şair Vagabond","poet_slug":"sair-vagabond","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/sarmal-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İç seslerim...', 'i-c-seslerim-sair-vagabond-yaq4c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yorgunum, nedensiz ve eylemsiz

Yorgunum, isteksiz ve sessiz

İçimdeki sesler kaybolmuş

Dışımdaki sesler içime girme uğraşında

Kulaklarımdan sızıyorlar

Kafam uğulduyor

Susadım

Uyumam lazım

Uyumam, rüya görmem lazım

Küçük bir kız çocuğu belki

Kendi güzel, bahtı kara

Işıltılı, gülen gözlerinde geleceğini gördüğüm

Yoksul, çaresiz ve güzel

Masumiyetin nefis giysisi üstünde

Oyunu, hayalleri

Oyuncakları olmayacak hiç

Bana bir türkü söyleyecek

O yaşadıkça ölmeyecek

Toprağa kavuşmuş babası ile anası için

----O----

Akşam güneşi ala kesmiş

Gündüz bitmiş gece gelmiş

Babam, anam uzaklarda

Gitmiş de gelmezlermiş

Anam babama eş

Babam anama kardeş

Bana bir kez daha sarılsalar ne olur

Aman güneş, güzel güneş

Karanlık bana kardeş

Toprak gözyaşlarıma eş

Bana son kez göstersen anamı ne olur

Aman güneş, güzel güneş

----O----

Hıçkırıklarla uyanacağım

Küçük kızın titrek sesi kulaklarımda

    Bana son kez göstersen anamı ne olur

    Aman güneş, güzel güneş

Küçük kızın hıçkırıkları karışmış benimkilere

    Bana bir kez daha sarılsalar ne olur

    Aman güneş güzel güneş

İçimde yine sesler

İçimde yine iç seslerim

Dışımdaki sesler sadece kulaklarımda

Küçük kızın sesi kalbimde

Gözyaşlarımda', 'Yorgunum, nedensiz ve eylemsiz Yorgunum, isteksiz ve sessiz İçimdeki sesler kaybolmuş Dışımdaki sesler içime girme uğraşında Kulaklarımdan s...', ARRAY['Türk Edebiyatı','Şiir','Şair Vagabond']::text[], 8.5, '{"poet":"Şair Vagabond","poet_slug":"sair-vagabond","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/ic-seslerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İç seslerim (iyi ki susmuyorlar) ...', 'i-c-seslerim-iyi-ki-susmuyorlar-sair-vagabond-fmvz9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gece bitecek mi acaba bugün de

Tan ağırıp, şafak sökecek mi yine

Ben görecek miyim ışığı

Duyacak mıyım Mavi''nin türküsünü

Ya sen

Sabahın serinliğinde ürperecek misin

Benim gibi

Mavi''nin türküsünü duyarsan

Gökova''ya gidecek misin, ben hep içinde

Göreceğim senin gözlerinle

Gökova''ya gidersem sensiz, sen hep içimde

Gösterecegim sana kendi gözlerimle

Duyacak mıyız Mavi''nin türküsünü

Duyacak ve yaratılışa şükredecek miyiz? 

Sabah olmadı bir türlü

Sigaralar bitti, gece bitmedi

Göz kapaklarım yorgun ama korkuyor kapanmaya

Mavi''nin türküsü içimde

Ya uyursam da susarsa

Ya O da duyuyorsa ve ben uyursam

Herşeyi bırakıp gitme zamanı yakın yine

Mavi''nin türküsü kulaklarımda

O''nun hayali her baktığım yerde.

Ya da O sadece bir hayal, ama ne önemi var

Baktığım herşey O, gördüğüm herşey O olduktan sonra

Inti Illimani dinlemek istiyorum...', 'Gece bitecek mi acaba bugün de Tan ağırıp, şafak sökecek mi yine Ben görecek miyim ışığı Duyacak mıyım Mavi''nin türküsünü Ya sen Sabahın ser...', ARRAY['Türk Edebiyatı','Şiir','Şair Vagabond']::text[], 8.5, '{"poet":"Şair Vagabond","poet_slug":"sair-vagabond","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ic-seslerim-iyi-ki-susmuyorlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmurda gezinti, yağmurla gezinti...', 'yagmurda-gezinti-yagmurla-gezinti-sair-vagabond-u9dvg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güneş ateşi düşmüştü içimize

Buharlaştık

Beyaz bir bulut olduk

Gül parmaklı şafakla dost

Güneşe aşık

Geceleri döşeğimiz sonsuz gökyüzü

Yorganımız yıldızlar

Rüzgarlar kılavuzumuz

Rüzgarlar serseri ruhumuz

Derken hava soğudu sokulduk birbirimize

Korkumuz şimşek oldu aydınlattı yeryüzünü

Korkumuz gökgürültüsü oldu ürküttü tekmil canlıları

Sonra hepimiz birer damla olduk

Aslımıza döndük

Yalnızdık

Kopup bulutumuzdan

Düşmeye başladık ayrı ayrı

Hepimiz aynı yere koştuk

Hepimiz ayrı ayrı koştuk

Çok kalabalıktık

Çok yalnızdık

Korkuyorduk

Yalnızdık ve korkuyorduk

Sonra o geldi yanıma

Ürkütücü rüzgarın bir armağanı gibi

Yalnızlık diğer damlalara doğru uzaklaşmıştı

Gök tanrının şimşekleri korkutmuyordu artık

Sonsuz hızla yaklaşan yeryüzü ise çok uzaklarda kalmıştı

Hafif dokunuşlarla tanıdık birbirimizi

Tanıdık ve çok sevdik birbirimizi

Ve sonunda

Sarıldık birbirimize

İki damla, iki aşık

Tek damla, tek vücut

Her saniye sonsuzdu

Her saniye bitimsiz ve tarifsiz

Sanki güneş yine dolmuştu içimize

Sanki yine buhar olmuş yükseliyorduk kusursuz gökyüzüne

Tam değecekken çimen kokulu toprağa

Bana iki kelime fısıldadı

Ve iki kelime duydu benden

Seni seviyorum

Kahverengi toprak kapladı etrafımızı birden

Biz yine tek vücut, biz yine aşık

Köklerinde bulduk kendimizi kıpkırmızı bir gülün

Tomurcularına koşmaya hazır

Güneşe birlikte selam vermeye sabırsızlanan

Onun ateşinde birlikte ısınmayı dileyen

Artık

Gül daha kırmızı

    Gül daha alımlı

        Gül daha aşık', 'Güneş ateşi düşmüştü içimize Buharlaştık Beyaz bir bulut olduk Gül parmaklı şafakla dost Güneşe aşık Geceleri döşeğimiz sonsuz gökyüzü Yorga...', ARRAY['Türk Edebiyatı','Şiir','Şair Vagabond']::text[], 8.5, '{"poet":"Şair Vagabond","poet_slug":"sair-vagabond","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/yagmurda-gezinti-yagmurla-gezinti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonunda (Epitelous)', 'sonunda-epitelous-sair-vagabond-6nywh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hepsini denemek lazım elbette çok sürpriz birşey de olabilir. Yine de muhteşem bir şarkı. Merhaba Keti, Kalimera Natasha...

-----O-----

Yani belki böyle bir ''sonunda'': 

Bitimsiz sanırdım aşkını

Dedikodular boşuna, inanmam

Öğütler anlamsız, dinlemem

Bir tek sen vardın benim için

Bir tek senin sonsuz aşkın

Hani biz bir olacaktık

Hani sadece beni sevecektin

Sonunda

Öylece çekip gittin

Son bir öpücük bile vermeden

Bir sabah yanımda yoktun

Kalbimde sıcaklığını özlerken

Yatağımda üşüyorum

Sonunda

Yalnızım ve üşüyorum

-----O-----

Belki de böyle bir ''sonunda'': 

Kalbim yalnızlığa alıştı

Sadece sevgiye özlem

Sadece hüzün var benim için

Dostlarım çaresiz avutmakta

Avunabilmem imkansız yalnızlıkta

Yalnızım ve üşüyorum

Sonunda

Seni gördüm karşımda

Gerçek olmayacak kadar güzel

Hayallerim gibi sevgi dolu

Bir küçük öpücük ve tatlı uyku gözlerimde

Şafak uykuyu alınca gözlerimden

İlk gördüğüm senin güzel yüzün

Sonunda

Aşık oldum

Sonsuza kadar aşık kalacağım

-----O-----

Ya da böyle bir ''sonunda'': 

Aşk bana uzak dedim

Hep iş, hep güç, hep para

Varsa yoksa çalışmak

En güzel arabalar altımda

En güzel kadınlar kolumda

En güzel iltifatlar hakkımda

Sonunda

Bir dost aradım yanımda

Paramda gözü olmayan

Beni ben olarak seven

Bulamadım

Bana aşık bir kadın istedim

Sadece beni sevecek olan

Bulamadım

Sonunda

Mutsuz oldum

Sevgisiz, sevgiye hasret kaldım

-----O-----

Nedir bilemiyorum ama benim için şöyle bir ''sonunda'' bu galiba: 

Aşktan kaçar olmuştum

İncinmekten kaçar

İncitmekten kaçar

Sevdiğimi söyleyemez

Sevildiğimi dinleyemez

Of be korkak gönül

Yen artık korkunu diyordum

Of be küskün gönül

Barış kendinle diyordum

Sonunda

Sen karşımda duruyordun

Sonunda

Sen kalbimde duruyordun

Ayrılık bile olsa sonunda

Kalp kırılığı bile olsa sonunda

Of be cancağızım

Ne olursa olsun sonunda

Kalbim yeniden çarpıyor seninle

Kalbim yine barışık kendiyle

Sonunda

Kalbim yine dolu sevgiyle

-----O-----', 'Hepsini denemek lazım elbette çok sürpriz birşey de olabilir. Yine de muhteşem bir şarkı. Merhaba Keti, Kalimera Natasha... -----O----- Yani...', ARRAY['Türk Edebiyatı','Şiir','Şair Vagabond']::text[], 8.5, '{"poet":"Şair Vagabond","poet_slug":"sair-vagabond","theme":"Türk Şiiri","is_hero":false,"total_lines":79,"source_url":"https://www.antoloji.com/sonunda-epitelous-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Felekle sohbet', 'felekle-sohbet-aydin-bayrakdar-uvlf2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Felekle sohbet

Sevda denizine düşersem bir gün, 

Dalgalar boyumu aşar mı felek? 

Çilesi çok derler kara sevdanın, 

Sevmeyen kul acep yaşar mı felek? 

Aksini diyenler gelsinler beri, 

Gösterin sevgisiz huzurlu yeri! ..

Kim kimi seviyor, kim kimin yari, 

Bana da bir güzel düşer mi felek? 

Tut ki şansım var, birini sevdim, 

Aşktan önce fildim, sonra da devdim, 

Muhabbet anında kelamı gevdim, 

Hiç sebebsiz akıl şaşar mı felek? 

Kısmetimde ne var? Erken ver haber! 

Varsın da çilesi olsun tuz biber, 

Ya o vurulduğum sarışın dilber, 

Evlenmeden beni boşar mı felek? 

Ya karşılık alamazsam sevgime, 

Yalvarırım bakıp gülme halime! 

Bulamazsam anlatmaya kelime, 

Beynim, kalbim, dilim şişer mi felek?', 'Felekle sohbet Sevda denizine düşersem bir gün,  Dalgalar boyumu aşar mı felek?  Çilesi çok derler kara sevdanın,  Sevmeyen kul acep yaşar m...', ARRAY['Türk Edebiyatı','Şiir','Aydın Bayrakdar']::text[], 8.5, '{"poet":"Aydın Bayrakdar","poet_slug":"aydin-bayrakdar","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/felekle-sohbet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bıçak Sırtı', 'bicak-sirti-i-hsan-uncuoglu-ubfw0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bıçak Sırtı 

Kanıt Bıçaksırtı Anı Sanı 

Gerçek erkek nerde kaldı, 

Temelde çok açık Kanıt yoksa Anı, Sanı`dan 

Mutlak ya bir masal ya kuru bir kuruntu çıkar 

Hep olmazları çarpıtır o hayaldir zaman kurdu 

Sap saman dumandan temelsiz yaşamda olur bu. 

*** 

Ölçü tartı yok yalanlarla derya kalkar havaya 

Gerçek dışı falda kaç rüya açılır avuçtan uyuyana 

Her rüyadan ayak üstü yanlı yalan masal ne çook 

Bir aldatmaca dünyası ya zarara koşar ya faydaya. 

*** 

Yaşamdan ne olmaz parça yapışır bak aynalara 

Kimi akıldan sapmış iyi görmez düz anlar eğriyi 

Hangi ölçek güvenli sorsan bilemez ki değerini 

Yerde iken kuş gibi yukarda güvenli bir dal arar 

Sanı`sı kanıtsız aç tavuk ambarda görür kendini. 

*** 

Ölçü yanlış sağ eli sol beyazı''da kara yapar 

Kanarya''ya kartal der gündüz görmez gözleri 

O bir çuval pirinçten çakmak taşı arar işlemeli 

Heryerde kararsız ayarsızdır ters anlar herşeyi 

Gerçek bilime duyarsız kör aklına ne yerler arar 

Kanıtsız! çeşit sanı''larda karanlıkta yaşar aymazlar! .', 'Bıçak Sırtı  Kanıt Bıçaksırtı Anı Sanı  Gerçek erkek nerde kaldı,  Temelde çok açık Kanıt yoksa Anı, Sanı`dan  Mutlak ya bir masal ya kuru b...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bicak-sirti-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KACIYORUM', 'kaciyorum-seref-kaya-yqb70', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kaciyorum, kaciyorum, 

kaciyorum sevgin den.

Artik seni istemiyorum

Bahsetme bana kendinden.

Seni özlemek, söyle dursun

Bir daha seversem, askim yok olsun

SEni seversem askima nalet olsun

Kaciyorum sende, kaciyorum haberin olsun.

Kulaklarimi tikiyorum, isitmemek icin sesini

Gözlerimi kapatiyorum.görmemek icin sulietini

Seni sevmemek icin, terk ettim kent imi

Kaciyorum senden, unutmak icin sevgini.

                                                                      (foca seref kaya)', 'Kaciyorum, kaciyorum,  kaciyorum sevgin den. Artik seni istemiyorum Bahsetme bana kendinden. Seni özlemek, söyle dursun Bir daha seversem, a...', ARRAY['Türk Edebiyatı','Şiir','Şeref Kaya']::text[], 8.5, '{"poet":"Şeref Kaya","poet_slug":"seref-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kaciyorum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'VATAN HASRETI', 'vatan-hasreti-seref-kaya-9lsoj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mektup, selam söyle bizden vatan a

Söyle benim icin güller aglasin

Gözü yasli düstüm zindana

Iraktir aramiz yollar aglasin.

Silanin cevresi bahceler, baglar

Oturmus Analar ogul der aglar

Gözümüze perde olmus yikilsin daglar

Halimizi soran diller aglasin.

                                                    seref kaya', 'Mektup, selam söyle bizden vatan a Söyle benim icin güller aglasin Gözü yasli düstüm zindana Iraktir aramiz yollar aglasin. Silanin cevresi ...', ARRAY['Türk Edebiyatı','Şiir','Şeref Kaya']::text[], 8.5, '{"poet":"Şeref Kaya","poet_slug":"seref-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/vatan-hasreti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HATIRLIYACAKSIN', 'hatirliyacaksin-seref-kaya-c6885', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yagmursuz, pazarlarda olucak, 

O zaman, kime kabahat bulacaksin.

Gelmeyisimi o gün de

Bakalim neye yoracaksin.

Gururunu yine, her seyden üstün tutup

Belki! aglamiyacaksin ama, 

Derinden gelen, o sese kulak verip

Beni yitirdigini anliyacaksin.

Beni, soracaklar arkadaslarin, 

Rastladiklari zamanlar, 

Ne söyliyecegini; sasiracaksin.

Kizarip solacaksin.

Daha bir cok yagmurlu pazarlar

Daha bir cok yagmurlu, günler olucak.

Ve topragi islatan, damlada ilk gelmeyisimi, 

-Gözlerin nemli, SEN hatirliyacaksin.

                                                                    seref kaya', 'Yagmursuz, pazarlarda olucak,  O zaman, kime kabahat bulacaksin. Gelmeyisimi o gün de Bakalim neye yoracaksin. Gururunu yine, her seyden üst...', ARRAY['Türk Edebiyatı','Şiir','Şeref Kaya']::text[], 8.5, '{"poet":"Şeref Kaya","poet_slug":"seref-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hatirliyacaksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BU KÖY', 'bu-koy-seref-kaya-nj937', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kagnilar gicir, gicir

Asiktir köyün yolari bu sese.

Küncü icinde, cir, cir böcekleri

Ötmese cir cir ötmese.

Cicekler syöliyecekler belki! 

Icinde sakladigini, 

Bana diyecekler, 

Sularin duruldugunu.

Degistirecek kuslar yerini, 

Bu köyden göc edip, gidecekler, 

Daglarda kekik kokusu, 

Icimdedir, kaybolu vermek korkusu.

                                                                  seref kaya', 'Kagnilar gicir, gicir Asiktir köyün yolari bu sese. Küncü icinde, cir, cir böcekleri Ötmese cir cir ötmese. Cicekler syöliyecekler belki!  I...', ARRAY['Türk Edebiyatı','Şiir','Şeref Kaya']::text[], 8.5, '{"poet":"Şeref Kaya","poet_slug":"seref-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bu-koy-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Affet', 'affet-bucak-sicak-1hmls', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne güzeli, ne çirkini

Hiçbiri düşünmedi

Bencilce yaşadılar

Bir tohum ekilmedi

O dedi nasıl ezerim

Bu dedi nasıl küserim

Ben dedim Allah Kerim

Hiçbiri dinlemedi

Kader böyle yazılmış

İyiler hep ezilmiş

Tüm ağaçlar kesilmiş

Bir fidan dikilmedi

Gözüm arkada giderim

Sadece dua ederim

Allah’ım affet derim

Kıymetin bilinmedi', 'Ne güzeli, ne çirkini Hiçbiri düşünmedi Bencilce yaşadılar Bir tohum ekilmedi O dedi nasıl ezerim Bu dedi nasıl küserim Ben dedim Allah Keri...', ARRAY['Türk Edebiyatı','Şiir','Bucak Sıcak']::text[], 8.5, '{"poet":"Bucak Sıcak","poet_slug":"bucak-sicak","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/affet-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YANAN YÜREKLER', 'yanan-yurekler-ozan-rari-fd6oy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'En büyüğüdür evlat acısı, 

En içten yaralayanı, 

En yürek parçalayanı...

Bir baba; 

Önünde bir tabut, 

İçinde 3 tane çocuğu var

2,3,5 li yaşlarda. 

Kanlı ellerini açmış yalvarıyor baba

Son defa yavrularını sarmıştı o eller

Şimdi ise isyanlarda.

Masum ve günahsız 3 tane çocuk

Daha da birçoğu...

Anneler, babalar bir daha alamayacak yavrularını kucağına

Saramayacaklar doyasıya, 

Sevemiyecekler yürekten, 

Kapanmayacak sürülen bu yaralar...

Olmasın artık bu kavga, bu savaş

Kendi menfaatleri ve mutlulukları için 

Başka bir ülkeyi yıkmalar, 

Bir çok günahsız cana kıymalar.

Yazık, 

Günah artık...

Acımanız yok biliyoruz 

Ama; 

Vicdanınızda mı yok sizlerin? 

O güzelim, masum, saf yavrucaklara

En güzel yaşlarında  oyuncak oynamaları gerekirken

Kefeni giydirdiniz, 

Büyüklerin onlara gelecek vaadetmeleri gerekirken 

Tabut başında gözyaşları ve feryatlar içinde bıraktınız. 

Eğer HUZUR VERMEYE niyetiniz yoksa sizlerin; 

O zaman tek diyeceğim, 

TANRI''DAN KORKUN...! 

(Artık çocuklar ölmesin, umutlarımız sönmesin...06/04/2003)', 'En büyüğüdür evlat acısı,  En içten yaralayanı,  En yürek parçalayanı... Bir baba;  Önünde bir tabut,  İçinde 3 tane çocuğu var 2,3,5 li yaş...', ARRAY['Türk Edebiyatı','Şiir','Ozan Rari']::text[], 8.5, '{"poet":"Ozan Rari","poet_slug":"ozan-rari","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/yanan-yurekler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arama artık', 'arama-artik-ali-umran-sonmez-3t4ex', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni görmeyi istemiyorum, 

Arama artık beni ne olur.

Yüzün silindi hayallerimden, 

Arama artık beni ne olur.

Resmini çıkardım albümlerden, 

Adına çizik attım defterden, 

Gönlümde yer yok sana yeniden, 

Arama artık beni ne olur.', 'Seni görmeyi istemiyorum,  Arama artık beni ne olur. Yüzün silindi hayallerimden,  Arama artık beni ne olur. Resmini çıkardım albümlerden,  ...', ARRAY['Türk Edebiyatı','Şiir','Ali Ümran Sönmez']::text[], 8.5, '{"poet":"Ali Ümran Sönmez","poet_slug":"ali-umran-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/arama-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'söğüde ezgi', 'sogude-ezgi-kamil-colak-xnxam', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yağmur şarkılarıyla sen

yeşil kurdelalar takarsın saçlarına

yorgun kalkan kervanlar tutarsın

gölgenin derinliklerinde

aşıklara  göndoğar 

boylarını çizerler sevgililerinin

senden misal alarak

en ince sesleri bulur bestekarlar

seher yeliyle söyleşirken yaprakların

gün ışıkları ağarır damla damla

yapraklarına tutunan kuşların sesleriyle

gölgende kalır ağır hükümler

gün doğandan gün batana

bulvarları ele veren güzelliğinle', 'yağmur şarkılarıyla sen yeşil kurdelalar takarsın saçlarına yorgun kalkan kervanlar tutarsın gölgenin derinliklerinde aşıklara  göndoğar  bo...', ARRAY['Türk Edebiyatı','Şiir','Kamil Çolak']::text[], 8.5, '{"poet":"Kamil Çolak","poet_slug":"kamil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sogude-ezgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nüveyrem', 'nuveyrem-riza-polat-akkoyunlu-s7972', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uslu dur Nüveyrem çıldırtma beni

Ben artık bildiğin o eski ben değilim.

Bir başka yağmurla ıslak mendilim.

Kapa pancurları ört pencereni

Uslu dur Nüveyre''m çıldırtma beni.

Neyleyim gözlerin hala yeşilse

Ve hala saçların altın sarısı...

Gel gör ki tükendi ömrün yarısı.

Bilmiyor acımı Nüveyre''m bilmiyor kimse

Neyleyim gözlerin hala yeşilse...', 'Uslu dur Nüveyrem çıldırtma beni Ben artık bildiğin o eski ben değilim. Bir başka yağmurla ıslak mendilim. Kapa pancurları ört pencereni Usl...', ARRAY['Türk Edebiyatı','Şiir','Rıza Polat Akkoyunlu']::text[], 8.5, '{"poet":"Rıza Polat Akkoyunlu","poet_slug":"riza-polat-akkoyunlu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/nuveyrem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-sunay-akin-nuvk5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İki rayı gibiyiz

bir tren yolunun

yakın olması

neyi değiştirir

son istasyonun', 'İki rayı gibiyiz bir tren yolunun yakın olması neyi değiştirir son istasyonun...', ARRAY['Türk Edebiyatı','Şiir','Sunay Akın']::text[], 8.5, '{"poet":"Sunay Akın","poet_slug":"sunay-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ayrilik-103-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Korku Kimin', 'bu-korku-kimin-yasin-tahtali-rgdhv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kimin korkusuydu yaşadığımız

bir türlü anlayamadığımız

Ne kadarı bize ait

kafamızda tasarladığımız

Neydi yüklenen bize 

sırtımızdan atamadığımız

Kimin bu korku 

hesaplaşamadığımız

Ne kadarı gerçekti 

hangisiydi dayatılan

Bu güne ait olan neydi

geçmişten devralınan

Nasıl bir tutsaklık bu

karşı konulamayan

Kimin bu korku 

hesaplaşılamayan', 'Kimin korkusuydu yaşadığımız bir türlü anlayamadığımız Ne kadarı bize ait kafamızda tasarladığımız Neydi yüklenen bize  sırtımızdan atamadığ...', ARRAY['Türk Edebiyatı','Şiir','Yasin Tahtalı']::text[], 8.5, '{"poet":"Yasin Tahtalı","poet_slug":"yasin-tahtali","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bu-korku-kimin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SENSİZKEN', 'sensi-zken-asik-ahmet-hsy6b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sensizken hep seni düşünüyorum

İlerde sensiz nasıl olabileceğimi düşünüyorum

Hayattan korkmaya başlıyorum sensizken

Geleceği düşünüp ürperiyorum

Sensiz hayatımın nasıl olacağını düşünüyorum

Ve içime acı bir his geliyor

Sanki karanlık bir gecenin yarısında

Kabus görüp terlerle uyanmış gibi...

Sensizken karanlıktan korkuyorum

Seni düşündüğüm an yok olan karanlık

Sensizken içine alıp boğuyor beni

Çırpınıyorum karanlığın içinde, boğuşuyorum

Ama birden salıveriyorum kendimi...

Sensizken bedenimdeki direnç bitiyor

Seni düşünürken dağları delebilecek vücudum

Sensizken sanki tamamen ölüyor

Yaşarken ölüyorum sensizken

Hasret yavaş yavaş kemiriyor içimi

Bense olduğum yerde yavaşça eriyorum

Sensizken ölüyor tüm hislerim

Daima kokunu hissederken

Hep gözlerine bakarken

Sesini duyarken çalışan organlarım

Odundan bir kuklanınkiler gibi

Cansızlaşıyor sensizken...

Herşeyi güzel yönden düşünen aklım

En kötüyü düşünmeye başlıyor sensizken

Aşkım...

Canım sıkılıyor, bedenim ölüyor, 

Dünya duruyor, hasret içimi kemiriyor, 

Zaman ilerlemiyor, gurbet bitmiyor, 

HAYAT BANA ZİNDAN OLUYOR SENSİZKEN...', 'Sensizken hep seni düşünüyorum İlerde sensiz nasıl olabileceğimi düşünüyorum Hayattan korkmaya başlıyorum sensizken Geleceği düşünüp ürperiy...', ARRAY['Türk Edebiyatı','Şiir','Aşık Ahmet']::text[], 8.5, '{"poet":"Aşık Ahmet","poet_slug":"asik-ahmet","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sensizken-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'birde benden olsun', 'birde-benden-olsun-aydin-karatay-rsylm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'BİRDE BENDEN OLSUN 

NEDEN HER SEVMEK İSTEYİŞİMDE 

KAÇIYORSUN BENDEN 

BAZEN DALGA GEÇİYORM KENDİMLE 

BAZENDE GÜLÜP GEÇİYORUM KENDİME 

İŞİM GÜÇÜM HEP SEN OLMUŞ 

VAKİT ÇOK GEÇ BELLİ DÖNMÜYORSUN GERİ

HADİ GİT 

BUDA BENDEN OLSUN 

HADİ KAYBOL KARANLIKTA 

GÖLGEN YOLLARA DURSUN 

BELKİ ARAMAYA CIKARIM SENİ

HELE BİR SABAH OLSUN 

HADİ GİT 

AMA BU SON OLSUN ACILARIM BİR SON BULSUN 

BEDENİM TOPRAKLA BULUŞSUN 

BUDA BENDEN OLSUN

ŞİMDİ SIRLARA KAPLADIM YÜREGİMİ

AÇMIYORUM KİSEYE 

DİLİN KONUŞMASIN ACITMASIN BENİ

ZATEN YOKLUĞUN BİR DAR AĞACI 

YALAN SÖZLERİN ASMASIN BENİ

HADİ GİT 

BUDA BENDEN OLSUN 

HADİ GİT GİT 

DURMA SAKIN KALBİM TUTSUN 

BİR KAÇAKTIN ZATEN SENİ BULDUĞUMDA 

ÖZGÜRLÜĞÜN SENİN OLSUN...! 

BİRDE BENDEN OLSUN

AYDIN KARATAY', 'BİRDE BENDEN OLSUN  NEDEN HER SEVMEK İSTEYİŞİMDE  KAÇIYORSUN BENDEN  BAZEN DALGA GEÇİYORM KENDİMLE  BAZENDE GÜLÜP GEÇİYORUM KENDİME  İŞİM GÜ...', ARRAY['Türk Edebiyatı','Şiir','Aydın Karatay']::text[], 8.5, '{"poet":"Aydın Karatay","poet_slug":"aydin-karatay","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/birde-benden-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'mavi', 'mavi-nilgun-erdogan-7lo8y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gözlerin dönüp dolaşıyor

gök mavisi

zümrüt mavisi

deniz mavisi

ama yine mavi.

ve düşleyip düşleyip büyüttük hüznümüzü

hüznümüz kömür mavisi.', 'gözlerin dönüp dolaşıyor gök mavisi zümrüt mavisi deniz mavisi ama yine mavi. ve düşleyip düşleyip büyüttük hüznümüzü hüznümüz kömür mavisi....', ARRAY['Türk Edebiyatı','Şiir','Nilgün Erdoğan']::text[], 8.5, '{"poet":"Nilgün Erdoğan","poet_slug":"nilgun-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/mavi-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ANLATAMIYORUM SANA', 'anlatamiyorum-sana-asik-ahmet-eltp4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Duygularımı anlatamıyorum sana

Hislerimi açıklayamıyorum

İçimden geçenleri, gelecekten isteklerimi, 

Sensizlikten, seni kaybetmekten korkumu

Anlatamıyorum sana...

Gösteremiyorum sana sevgimi

Sensizken döktüğüm gözyaşlarımı

Bu gözyaşlarının her bitanesinin 

Benim için değerini

Anlatamıyorum sana...

Sensizken geçen zamanımda yaşadığım hasreti

Katlanmak zorunda olduğum zalim gurbeti

Memleketime, aileme, sana olan özlemimi

Anlatamıyorum sana...

Benim için ne kadar değerli olduğunu

Kaderim olduğun için seni bulduğumu

Ne kadar çok sevdiğimi 

Anlatamıyorum sana...

Sevginin bence ne anlama geldiğini

Sana olan aşkımın hayatımdaki yerini

Seninle düşlediğim geleceğimdeki hayallerimi

Anlatamıyorum sana...

Sana ne kadar ihtiyacım olduğunu

Seni kaybetmekten çok korktuğumu

Ben nasıl hissediyorum yokluğunu 

Anlatamıyorun sana...

Geceleri sensiz daha karanlık olduğunu

Gündüzlerin renksiz, güneşsizliğini

Hayatımın nasıl bittiğini

ANLATAMIYORUM SANA...', 'Duygularımı anlatamıyorum sana Hislerimi açıklayamıyorum İçimden geçenleri, gelecekten isteklerimi,  Sensizlikten, seni kaybetmekten korkumu...', ARRAY['Türk Edebiyatı','Şiir','Aşık Ahmet']::text[], 8.5, '{"poet":"Aşık Ahmet","poet_slug":"asik-ahmet","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/anlatamiyorum-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'geri gelmesin diye geçen zaman', 'geri-gelmesin-diye-gecen-zaman-nilgun-erdogan-3hqn1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'çocukluğumun dut ağacı

en koyu rengi yalnızlığımın

en büyük yalanı ömrümün

söyle bana, 

koparılmış takvim yaprakları

yanmalı mı mutlaka her şeyi yakar gibi

kırmızı bir ateşin içinde günah kılıfıyla

bir daha geri gelmesin diye geçen zaman?', 'çocukluğumun dut ağacı en koyu rengi yalnızlığımın en büyük yalanı ömrümün söyle bana,  koparılmış takvim yaprakları yanmalı mı mutlaka her ...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Erdoğan']::text[], 8.5, '{"poet":"Nilgün Erdoğan","poet_slug":"nilgun-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/geri-gelmesin-diye-gecen-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nilim ben', 'nilim-ben-nilgun-erdogan-fdqft', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'delice akan bir nehir gibi

geçtiği yerlerden ne bulduysa götürüyor yanında; 

kum da taş da beraber.

Nilim ben

içimde balıklar yaşıyor

yosunlar bitiyor taşlaşan yerlerinde yüreğimin.

nilim ben

bir deli nehirim.

adına nehir denmiş bir selim aslında.

içimde sevdaların en karası

maviyim

kendime, 

kendime, 

kendime rağmen! 

Nilim ben

içimde insanlar ölüyor.', 'delice akan bir nehir gibi geçtiği yerlerden ne bulduysa götürüyor yanında;  kum da taş da beraber. Nilim ben içimde balıklar yaşıyor yosunl...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Erdoğan']::text[], 8.5, '{"poet":"Nilgün Erdoğan","poet_slug":"nilgun-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nilim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'yanılgı', 'yanilgi-nilgun-erdogan-oaj33', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yoksan, 

yoksun sanıyorsam

ve bu bir yanılgı değilse

neredesin?', 'yoksan,  yoksun sanıyorsam ve bu bir yanılgı değilse neredesin?...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Erdoğan']::text[], 8.5, '{"poet":"Nilgün Erdoğan","poet_slug":"nilgun-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yanilgi-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'bana dönen aşkın ıssızlığıdır', 'bana-donen-askin-issizligidir-nilgun-erdogan-n8smg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kestim saçlarımı, 

kırdım tırnaklarımı.

bütün fotoğraflarını yaktım.

çıkarıp attım çöpe

en sevdiğin kazağımı.

bir daha hiç gitmedim

oturduğun o eve.

önünden bile geçmedim

seni hatırlatır diye.

senden bana kalan yalnız gözyaşlarıdır.

bu aşktan arta kalan

gecenin karanlığıdır.

hakırdım dağlarda

anlamsız kalabalıklarda

bana dönen aşkın ıssızlığıdır.', 'kestim saçlarımı,  kırdım tırnaklarımı. bütün fotoğraflarını yaktım. çıkarıp attım çöpe en sevdiğin kazağımı. bir daha hiç gitmedim oturduğu...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Erdoğan']::text[], 8.5, '{"poet":"Nilgün Erdoğan","poet_slug":"nilgun-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bana-donen-askin-issizligidir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'herkes gitsin', 'herkes-gitsin-nilgun-erdogan-fhaqa', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'giden gitsin

kalan da gitsin.

artık bu youn bitsin.

ne katıksız sevgiyle donanmış bir dost

ne kırmızı güllerle kapıma gelcek bir sevgili...

hepsi gitti.

yalancı yüzler de gitsin.

artık bu çirkin oyun bitsin.

sana verecek bir şeyim kalmadı

günler aylar gitsin

bu çirkin oyun bitsin

çünkü sen

hayatımda sadece parazitsin.', 'giden gitsin kalan da gitsin. artık bu youn bitsin. ne katıksız sevgiyle donanmış bir dost ne kırmızı güllerle kapıma gelcek bir sevgili... ...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Erdoğan']::text[], 8.5, '{"poet":"Nilgün Erdoğan","poet_slug":"nilgun-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/herkes-gitsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'seni özledim', 'seni-ozledim-nilgun-erdogan-g3tpa', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gözlerin bir sızı oldu içimde

baktıkça ağlamak istediğim.

gözlerin bir nehir gözlerimde

baktıkça yandı içim.

bir gece bir yıldız düştü

gökten kalbime, 

bir ormanı ateşe verdi

her gün deli rüzgarlarla savruldu küllerim.

bir üşüdü, bir yandı ellerim.

ateşten bir gömlek imiş sevmek

zalim bir kral imiş

kolaymış her şeyi ateşe vermek...', 'gözlerin bir sızı oldu içimde baktıkça ağlamak istediğim. gözlerin bir nehir gözlerimde baktıkça yandı içim. bir gece bir yıldız düştü gökte...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Erdoğan']::text[], 8.5, '{"poet":"Nilgün Erdoğan","poet_slug":"nilgun-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seni-ozledim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SEN', 'sen-esin-utas-emqk8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir garip olurum hazan akşamları

Rüzgar savururken yaprakları

Cama düşen iki damla seni hatırlatır.

Uzayıp giden yola baktıkça

Hayatım gelir aklıma

Ağaçlar yolun iki yanında

Çıplak ve yalnız

Bir ordu içinde tek başıma gibiyim

Yanımda gözlerin ve nefesin

Kokun gelir burnuma

İsterim seni içime çekeyim.

Sigaramda dumanım tüter

Düşer kırılır bir bir şişeler

Sensizlik ve sessizlik alır gider

Bırakır beni boş bir yerlere

Yavaştan katarlar geçer bir garip içim 

Yatağım dar gelir deliririm

Bedenimi kaplar sonsuz bir kahır

Birden vakit gelir aklıma

Bakarım ki

Gün doğmada ağır ağır 

Ve ben hala seni düşünmedeyim!', 'Bir garip olurum hazan akşamları Rüzgar savururken yaprakları Cama düşen iki damla seni hatırlatır. Uzayıp giden yola baktıkça Hayatım gelir...', ARRAY['Türk Edebiyatı','Şiir','Esin Utaş']::text[], 8.5, '{"poet":"Esin Utaş","poet_slug":"esin-utas","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sen-240-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SON', 'son-esin-utas-oomoh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aldanmak mıydı hatam yine, 

Yoksa ateşe mi atladım bile bile? 

Zaman geçiyor hızla

Dakikalar tedirginlik içinde.

Eldekilerin kıymetini bilmemenin

Önündeki güzellikleri görmemenin

Seni sevenleri sevmemenin 

                      cezası bu belki de! 

Mutluluk... Uzak kaldı bana, 

Sevenlerim azalıyor

Artık yoklar yanımda.

Yalnızlık yaklaşıyor adım adım, 

Arkamda dağ, 

Önümde deniz, 

Uçurumlardayım.

Ayrılık zamanı geldi çattı

Yok artık hüzün

Yok artık ağlamak.

Daha önce de çok acılar gördün

Dayan kalbim dayan bir kez daha

Benden sana söz

Bu son 

Bundan sonra ASLA...', 'Aldanmak mıydı hatam yine,  Yoksa ateşe mi atladım bile bile?  Zaman geçiyor hızla Dakikalar tedirginlik içinde. Eldekilerin kıymetini bilme...', ARRAY['Türk Edebiyatı','Şiir','Esin Utaş']::text[], 8.5, '{"poet":"Esin Utaş","poet_slug":"esin-utas","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/son-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GURUR', 'gurur-esin-utas-jrhi2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Artık yoksun yanımda 

Gördüğüm herkesi insan sanıyorum

Dört elle sarılıyorum onlara.

Ama kimse senin gibi değil

Kimse senin gibi davranmıyor bana.

Bense değiştirmeye çalışıyorum onları

Bilinmez bir hepsini sana benzetme çabası! 

‘Neden gittin o zaman’ diyeceksin

‘Madem böyle özleyecektin? ’

Bilemedim seni bu kadar sevdiğimi, 

Sana bu kadar değer verdiğimi, 

Bilemedim senin kıymetini...

Gururum dönme diyor kalbim senden yana

Bir kez daha gönlüm yenik düşüyor gururuma

Ölürüm dönmem dersem sana

Bil ki ölüm bana senden yakın

Gururum mutlu, kalbim yenik, ecel o an kapımda...', 'Artık yoksun yanımda  Gördüğüm herkesi insan sanıyorum Dört elle sarılıyorum onlara. Ama kimse senin gibi değil Kimse senin gibi davranmıyor...', ARRAY['Türk Edebiyatı','Şiir','Esin Utaş']::text[], 8.5, '{"poet":"Esin Utaş","poet_slug":"esin-utas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gurur-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BEKLEYECEĞİM', 'bekleyecegi-m-esin-utas-ocnpy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'SANA YOK SİTEMİM

GEÇ OLAN SEN DEĞİLSİN 

SADECE BEN ERKENCİYİM

BİR SABRIM KALDI BENDEN SANA

BİR DE ŞU KOCA ANKARA’YA SIĞMAYACAK AŞKIM

ALIP BAŞIMI GİTMEYECEĞİM

BEKLEYECEĞİM SENİ

SEN DOLU BU ŞEHRİ TERKETMEYECEĞİM! 

BİR GÜN GİDERSEM BURALARDAN

YANIMDA SEN OLACAKSIN

YA DA MEKANIM TOPRAK

ÇOK GÖRDÜĞÜN ''EVET''İ DUYMAK

SENİ SENSİZ YAŞAMAMAK İÇİN

BEKLEYECEĞİM!', 'SANA YOK SİTEMİM GEÇ OLAN SEN DEĞİLSİN  SADECE BEN ERKENCİYİM BİR SABRIM KALDI BENDEN SANA BİR DE ŞU KOCA ANKARA’YA SIĞMAYACAK AŞKIM ALIP BA...', ARRAY['Türk Edebiyatı','Şiir','Esin Utaş']::text[], 8.5, '{"poet":"Esin Utaş","poet_slug":"esin-utas","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bekleyecegim-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖLÜM', 'olum-esin-utas-qxcru', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İlk defa başımı huzurlu koyuyorum yastığa

Hava soğuk, mevsimlerden sonbahar galiba.

Düşen sarı yapraklar

Esen deli rüzgar! 

Birileri etrafımda

Duymuyorlar beni

Bağırsam da! 

Bir ıslaklık yüzümde

Yağmur mu yağıyor acaba? 

Ağlamalar duyuyorum

Bilmediğim kelimeler ağızlarında.

Bir sevgili ağlıyor bir de çocuk yanında

Umutları bitmiş

Sanki sevinçleri kalmış yarıda

Bir ben mutluyum

Gülümsüyorum ama yarım ağızla

Sevdiğime uzatıyorum elimi

Nafile

O da gelmiyor yanıma! ! !', 'İlk defa başımı huzurlu koyuyorum yastığa Hava soğuk, mevsimlerden sonbahar galiba. Düşen sarı yapraklar Esen deli rüzgar!  Birileri etrafım...', ARRAY['Türk Edebiyatı','Şiir','Esin Utaş']::text[], 8.5, '{"poet":"Esin Utaş","poet_slug":"esin-utas","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/olum-76-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HAYAT', 'hayat-esin-utas-43v3q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'O kadar ümidim oldu ki 

Gerçekleşeceğini sandığım

Takıldım hepsinin peşine

Ümidim kalmadı çok kırıldım.

O kadar sevgilim oldu ki

Sevdiğimi sandığım

Beni gerçekten seveni

Yitirdiğimde anladım.

O kadar dünüm oldu ki

Unuttuğumu sandığım

Her yeni doğan günde

Bir öncesini hatırladığım.

O kadar yalanım oldu ki

İnandırdığımı sandığım

Bir gün gerçeklerle karşılaştığımda

Kendim bile inandığım.

O kadar galibiyetim oldu ki

Kazandığımı sandığım

Kaybettiğimi anladığımda ise

Hep tek başına yalnızdım.

O kadar hatam oldu ki

Hepsini doğru sandığım

Cezalarını çektikçe bir bir

Yüreğime taş bastığım.

O kadar mutlu günlerim oldu ki

Yaşamdan tad aldığım

Hayat da bir masalmış

Onu da kaybettiğimde anlayacağım! ! ! ! ! !', 'O kadar ümidim oldu ki  Gerçekleşeceğini sandığım Takıldım hepsinin peşine Ümidim kalmadı çok kırıldım. O kadar sevgilim oldu ki Sevdiğimi s...', ARRAY['Türk Edebiyatı','Şiir','Esin Utaş']::text[], 8.5, '{"poet":"Esin Utaş","poet_slug":"esin-utas","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/hayat-87-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİLEMEDİM', 'bi-lemedi-m-atila-gunal-nxe4b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Saklambaç oynuyoruz sanmıştım, 

Köşe başına saklanışını.

Deve kuşu gibi kafanı kuma gömmüşsün, 

Seni görmediğimi düşünerek, 

Çocuksu muzurluğun sanmıştım.

Sobe, demek istedim, 

Geç anladım.

Saklanışın oyun değil

Görmek istemeyişinmiş beni

Bilemedim. 

2003-04-06', 'Saklambaç oynuyoruz sanmıştım,  Köşe başına saklanışını. Deve kuşu gibi kafanı kuma gömmüşsün,  Seni görmediğimi düşünerek,  Çocuksu muzurlu...', ARRAY['Türk Edebiyatı','Şiir','Atila Günal']::text[], 8.5, '{"poet":"Atila Günal","poet_slug":"atila-gunal","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bilemedim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilirmisin', 'bilirmisin-agah-ozbek-m1mxp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen bilirmisin arkadaş

Toprağın karasabanla işlendiğini

Bilirmisin sen

Bir ekmek için ne güçlükler çekildiğini

Hiç sabırsızlıkla bekledinmi

Yatağına uzanmayı

Aç yattınmı baz geceler

Kurulu saatin çalabilir korkusuyla

Uyuya bildinmi soğuk gecelerde

Ve hiç ağladınmı sen

Yanlızlığın kahredici hastalığına

Sen

Düşledinmi bir gun

Sıcak oda sıcak çorba

Ve sadık bir arkadaş...

                                        12-1981-Magosa', 'Sen bilirmisin arkadaş Toprağın karasabanla işlendiğini Bilirmisin sen Bir ekmek için ne güçlükler çekildiğini Hiç sabırsızlıkla bekledinmi ...', ARRAY['Türk Edebiyatı','Şiir','Agah Özbek']::text[], 8.5, '{"poet":"Agah Özbek","poet_slug":"agah-ozbek","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bilirmisin-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'git', 'git-agah-ozbek-ds62q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir gün geriye dönüp bakarsan

Uzun bir yol katettiğini 

Anlayacaksın

Alıpta getiremediğin hatıralarına

Dönmek isteyeceksin

Fakat

İş işten geçmiş olacak

Şimdi düşün birkez

Götürmek için hatıralarını

Topla daha değişik

Ölüm varken yaşamda

Düşünüp durmak neye

Ölmeden ölümsüz hatırayı

Kalplere gömde git...

                                              4-1982-Magosa', 'Bir gün geriye dönüp bakarsan Uzun bir yol katettiğini  Anlayacaksın Alıpta getiremediğin hatıralarına Dönmek isteyeceksin Fakat İş işten ge...', ARRAY['Türk Edebiyatı','Şiir','Agah Özbek']::text[], 8.5, '{"poet":"Agah Özbek","poet_slug":"agah-ozbek","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/git-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhaba Ankara', 'merhaba-ankara-agah-ozbek-s3wqs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Soğuk bir kışın hazırlığında

Geniş kaldırımlarda hızlı adımlar

Küçük havuzların buz tutuşu

Otomobillerin buharlı öksürüşleri

Ve düşlerimin şehri

Akşam olmadan karanlığı bastıran kirli hava

Sis.

Yüksek binaların kalorifer bacası

Gözlerimin arayıpta bulamadığı

Kuşlar, 

Köşe başlarında piyango satan

Memurlar.

Büyük Ankara

                                             2-1973-Ankara', 'Soğuk bir kışın hazırlığında Geniş kaldırımlarda hızlı adımlar Küçük havuzların buz tutuşu Otomobillerin buharlı öksürüşleri Ve düşlerimin ş...', ARRAY['Türk Edebiyatı','Şiir','Agah Özbek']::text[], 8.5, '{"poet":"Agah Özbek","poet_slug":"agah-ozbek","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/merhaba-ankara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son gece', 'son-gece-agah-ozbek-icahs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Birgün öyle bir akşamdıki

Tavandaki arıstak kırk mumluk ampulle sallanıyordu

Radyodaki parçalar sessizliği yok ediyordu

Bizi gören sadece duvarlardaki resimlerdi

O resim çıblak bir kadındı

Pencere perdelerle kapalı

Dışardaki karanlığı gizliyordu

Masada son kalan iki düble rakı

Ve iki dilim domatesti

Ağzına kadar dolu kültablası

İki sıgarayı

İçine almak için mücadele ediyordu

Odada üç şahıstan biri

Uykuyla başbaşaydı

Zaman

Gece yarısı idi...

                               Fikret-Oykut-Ben-1-1981Adana', 'Birgün öyle bir akşamdıki Tavandaki arıstak kırk mumluk ampulle sallanıyordu Radyodaki parçalar sessizliği yok ediyordu Bizi gören sadece du...', ARRAY['Türk Edebiyatı','Şiir','Agah Özbek']::text[], 8.5, '{"poet":"Agah Özbek","poet_slug":"agah-ozbek","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/son-gece-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hey Dost-2+', 'hey-dost-2-bayram-tunca-d0p8q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hey dost, şöyle dediğini duyar gibiyim

Gülmek sadaka hükmündedir ey beyim

Ben de derim ki, çektiklerimi çekseydin

Sen de benim gibi çok ağlar/az gülerdin

Benim yaram bugünden değil dündendir

Benim çilem, edalı bir yârin yüzündendir

Sitemlerimse, onun vefasız oluşundandır

Gülmeyişim ise kem talihli oluşumdandır

05.04.2003-14:05

Aşk Ateşten Gömlek', 'Hey dost, şöyle dediğini duyar gibiyim Gülmek sadaka hükmündedir ey beyim Ben de derim ki, çektiklerimi çekseydin Sen de benim gibi çok ağla...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/hey-dost-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamansız istek', 'zamansiz-istek-agah-ozbek-0p45a', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir kahkaha atmak geldi içimden

Son dubleyi çekerken

Bir hıçkırık geldi içimden

Çekmekte olduğum sıgarayı  içerkek

Neden sona erdi içki masası

Yoksa zamanmı durdu

Henüz erken vakit

Zamandan habersiz saat

Bire çeyrek vardı...

                                    1-1981-Adana', 'Bir kahkaha atmak geldi içimden Son dubleyi çekerken Bir hıçkırık geldi içimden Çekmekte olduğum sıgarayı  içerkek Neden sona erdi içki masa...', ARRAY['Türk Edebiyatı','Şiir','Agah Özbek']::text[], 8.5, '{"poet":"Agah Özbek","poet_slug":"agah-ozbek","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/zamansiz-istek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dosta Öğütler', 'dosta-ogutler-oguzhan-tas-6km3y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kim yaşadığı aşkı unutmuş ki, 

Sadece unutmaya çalışırsın, 

Acını hafifletmek için, 

Zamana bırakırsın herşeyi.

Kendin teslim olursun hayatin akışına.

Onun hayalini zamanla silip, 

Kendini düşünmeye başlarsın, 

Eğer uzaklaşır ve onu görmezsen, 

Herşey daha kolay olur.

Yoksa acılarını dindiremezsin, 

Kendi duygularında boğulursun.

Silinsede izi kalır sevdanın, 

Çünkü her sevda kalbe kazınır.

Ufak çizikler aldıysan, 

Bunlar silinmesi kolaydır, 

zaten onlar aşk değildir ki.

En iyisi dostum artık geç oldu, 

Sen kendini bitirmeyi bırak 

ve yaşamaya yeniden başla.

Binlerce kere ölsen de 

Yaşamak zorundasın dünyada.

İşte insan olmanın tek zor yanı

ölmek değil budur.

Başka insanlara bakma, 

bunu sadece duygusallar yaşar 

sen de öylesin, değişemezsin.

Seni seven diğer insanları bırakıp, 

Bir zalim yüzünden 

Kapıyı çarpıp gidemezsin.', 'Kim yaşadığı aşkı unutmuş ki,  Sadece unutmaya çalışırsın,  Acını hafifletmek için,  Zamana bırakırsın herşeyi. Kendin teslim olursun hayati...', ARRAY['Türk Edebiyatı','Şiir','Oğuzhan Taş']::text[], 8.5, '{"poet":"Oğuzhan Taş","poet_slug":"oguzhan-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/dosta-ogutler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Virtüel', 'virtuel-sair-lolan-bl2py', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Virtüel

Virtüel masalarımız var atık

Gitmediğimiz sahillerin o kıyılarında

Göz göze değil her şey ruh ruha artık 

Söz sadece yansıyor ekranda

Uzakları silip süpürdük iki dakikada

Sınırda kalmadı şu ihtiyar kıtalarda

Virtüel sevişiyoruz artık semalarda

Canımız Anka kuşlarının kanatlarında

Hala olan savaşların anlamı kalmadı

Yarın petrol içmeyeceğiz biz

Geleceğin güneşinde yalan kalmadı

Yarın bankalara gitmeyeceğiz biz

Yarını biz seçeceğiz kendimiz için

Kopmuş olarak değerlerinizden

Kehanete tuzlu göz yaşlarımız için

Kopacağız kirli tekliflerimizden

Virtüel masalarımız var atık

Gitmediğimiz sahillerin o kıyılarında

Göz göze değil her şey ruh ruha artık 

Söz sadece yansıyor ekranda

Yalanları arayıp bulduk

Asker olmayacak hiç birimiz

Al Kanlara artık doyduk

Başka renk istiyor meridyenimiz

	LOLAN', 'Virtüel Virtüel masalarımız var atık Gitmediğimiz sahillerin o kıyılarında Göz göze değil her şey ruh ruha artık  Söz sadece yansıyor ekrand...', ARRAY['Türk Edebiyatı','Şiir','Şair Lolan']::text[], 8.5, '{"poet":"Şair Lolan","poet_slug":"sair-lolan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/virtuel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benercinin Heybesi', 'benercinin-heybesi-sair-lolan-cg6qk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Benercinin Heybesi

	Umut dostuma ve Nazım ustada

İnsanlar  yüreği yanan insanlar

Solgun dudaklarında

Hıçkırıklarını susturan insanlar

İnat olsun diye gülüp

İnadına sevinip seven

Yürekli insanlar

Anlı ter

Sırtı ter

Yüreği ter olan insanlar

Soğan gibi soyulmuş

Sahte umutlara boğulmuş

Biber gibi doğranmış

Acı ezme yürekli insanlar

Hak adına

Vatan adına

Aşk adına

Aldatılmış insanlar

Köyünden kovulmuş

Evinden atılmış

Onursuzca satılmış insanlar

İnsanlar

Kendi vatanında hain

Kendi vatanında lakin

Düşman ilan edilmiş

Kalbur yürekli insanlar

Ve bir gece

Ansızın kaybolmuş

Mezarı bulunmayan

Gölgesi olmayan insanlar

İhanet tadında

Bu hayat gibi

Düş kırıklarında

Yüreği yanan insanlar

İnsanlar

Bizim insanımız

Böyle mi susmalı 

Böyle mi imanımız

Böylesine ihanete uğramış

Yine böylesine onurlu

Bizim insanlarımız

Yüreğinde kan pıtısıyla

Bu günü yarına bırakan

Bizim insanlarımız

Eylülleri çıkarın bu mevsimlerden

Eylülde doğmuş olsam da

Eylülde sana aşık olmuş olsam da

Eylülde elimi tutmuş olsan da

Artık sevmiyorum eylülleri

Eylülleri 

	Çıkarın

Bu mevsimlerin içinden

	LOLAN', 'Benercinin Heybesi 	Umut dostuma ve Nazım ustada İnsanlar  yüreği yanan insanlar Solgun dudaklarında Hıçkırıklarını susturan insanlar İnat o...', ARRAY['Türk Edebiyatı','Şiir','Şair Lolan']::text[], 8.5, '{"poet":"Şair Lolan","poet_slug":"sair-lolan","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/benercinin-heybesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zencefil', 'zencefil-ozcelik-peker-3goza', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen bir potsun

Ustaca kırılmış

Konuştukça büyüyen

Sayıldıkça çoğalan

Nar tanelerisin

Sıkınca ellerini boyayan

Ustaca atılmış bir iddia

Gözle görülür bir suçlu korkusu

Yelkovanla akrebin

Üstünden geçmediği

On üç uğursuz sayısısın

Deliksiz bir uyku

Kestane şekeri tadında bir şey

Nesin sen biliyorsun musun? 

Sen benim tatlı zencefilimsin

Sabah erkenden açan

Yaprakları aşka mehilli.

09.02.2002', 'Sen bir potsun Ustaca kırılmış Konuştukça büyüyen Sayıldıkça çoğalan Nar tanelerisin Sıkınca ellerini boyayan Ustaca atılmış bir iddia Gözle...', ARRAY['Türk Edebiyatı','Şiir','Özçelik Peker']::text[], 8.5, '{"poet":"Özçelik Peker","poet_slug":"ozcelik-peker","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/zencefil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yardımsız', 'yardimsiz-ozcelik-peker-krf5o', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Acil tedaviye ihtiyacım var

Ona değdim çabuk

Onunla olmak bulaştı

Virüs değil bulaşıcı bir duygu

Gözleri değdi gözlerime diyorum

Ya izi çıktıysa silinmezse

Sevmek zorunda kalırsam

Mecburiyeti sevmem

Bulaşmış gibi ölecek miyim doktor? 

Hayır her gün ölerek yaşayacaksın

Seke seke yürür

Öle öle yaşar, sever gibi

15.02.2002', 'Acil tedaviye ihtiyacım var Ona değdim çabuk Onunla olmak bulaştı Virüs değil bulaşıcı bir duygu Gözleri değdi gözlerime diyorum Ya izi çıkt...', ARRAY['Türk Edebiyatı','Şiir','Özçelik Peker']::text[], 8.5, '{"poet":"Özçelik Peker","poet_slug":"ozcelik-peker","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yardimsiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm İşleri A.Ş.', 'olum-i-sleri-a-s-ozcelik-peker-gw4xx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Azrail hastalanmış

Evde ecelde ona bakıyor

İyileşince elinde kalmış

Zamanı gecikmiş işleri bitirecek

Ölümden bahsedince

Allah korusun deniyor

Bunu yapan zaten o

Kıyacaksa neden korusun? 

İlaçlarla kaldırdık yatağından

Sonra sevdiklerimi verdim yanına

Dans ederken en iyi partner

Sensin sanma

Eşlik eden en iyi kişi

Azrail’dir sana

Keşke bir kurum olsaydı

Şu ölüm işi

Günde on iki saat çalışır

Bırakırdı işi

Geceleri kimse ölmezdi

Ama deliler çoğalırdı akşam üstleri

17.01.2001', 'Azrail hastalanmış Evde ecelde ona bakıyor İyileşince elinde kalmış Zamanı gecikmiş işleri bitirecek Ölümden bahsedince Allah korusun deniyo...', ARRAY['Türk Edebiyatı','Şiir','Özçelik Peker']::text[], 8.5, '{"poet":"Özçelik Peker","poet_slug":"ozcelik-peker","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/olum-isleri-a-s-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mezarcı', 'mezarci-ozcelik-peker-dqrfb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İnsanlar bir yerden

Bir başka yere giderler

Ben son durağım

Uzun büyük başlangıcın

17.10.2001', 'İnsanlar bir yerden Bir başka yere giderler Ben son durağım Uzun büyük başlangıcın 17.10.2001...', ARRAY['Türk Edebiyatı','Şiir','Özçelik Peker']::text[], 8.5, '{"poet":"Özçelik Peker","poet_slug":"ozcelik-peker","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/mezarci-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'World Trade Center', 'world-trade-center-ozcelik-peker-a1f8r', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '(TWİN TOWERS)

YÜKSEK BİNALAR

IŞIKLARI GÖĞE ERER

RÜZGARIN ÖNÜNÜ KESER

GÖZÜMÜ ALAMAM ONLARDAN

PARILTILI BİR ELMAS

FAKAT ASLA SAHTE OLMAYAN

RÜYA ŞEHİRLERİNİ

ŞEHİR IŞIKLARINI

HAYALLERİ, İNANÇLARI

HEP ONLAR YAPAR.

01.01.2003 sa: 03.40', '(TWİN TOWERS) YÜKSEK BİNALAR IŞIKLARI GÖĞE ERER RÜZGARIN ÖNÜNÜ KESER GÖZÜMÜ ALAMAM ONLARDAN PARILTILI BİR ELMAS FAKAT ASLA SAHTE OLMAYAN RÜY...', ARRAY['Türk Edebiyatı','Şiir','Özçelik Peker']::text[], 8.5, '{"poet":"Özçelik Peker","poet_slug":"ozcelik-peker","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/world-trade-center-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kitap', 'kitap-musa-ozkan-g4ggj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kalbimde bir kitap vardır, 

Her harfinde bir tat vardır, 

O''nu nakşeyleyen kalbe, 

Rabbimden bir hitap vardır.

O Rabbimin Kitabıdır, 

Kullarına hitabıdır, 

Sevgi dolu şefkat dolu, 

Yüce Hak''ın ihsanıdır.

O''nun yolu Hak yoludur, 

Kadir-i Mutlak yoludur, 

O''nu hıfzeyleyen kalbte, 

Merhamet şefkat doludur.

O''nun yolu yollar hası, 

Hasta kalblerin şifası, 

O''nu nakşeyleyen kalbler, 

Sanırsın ki, Nur deryası.

Yüce Hak''ka eren kullar, 

O''nun yoluyla ermişler, 

Hakikatı gören gözler, 

O''nun nuruyla görmüşler.

Yüce Hakkı seven kullar, 

Sevgiyi O''ndan almışlar, 

Yüce Hakkın kapısını, 

O''nun yoluyla bulmuşlar.

Dil konuşur yürek ağlar, 

HAK ateşi yürek dağlar, 

O''nun yüce mucizesi, 

Kulunu rabbine bağlar.

Dinle Hakkın fermanını, 

Her dertlerin dermanını, 

Gösterdiği Nurlu yoldan, 

Ruhun bulsun Ramanını.

O''na sarılan Nurlu eller, 

Onu tilavet eden diller, 

Yokluk deryasında yüzer, 

O''ndan ilham alan kullar.

Yüce Hakkın sözü onda, 

Hak yolunu izi onda, 

Sağda Solda ne ararsın, 

Hakikatın ÖZ''ü onda.

Her harfi bir nur çeşmesi, 

Muminler kalbine akar, 

O''nun aktığı kalblerde, 

Misk-ü Amberler kokar.

Gül Kahya''nın bülbülleri, 

Hangi dalda ötüşürler, 

Gönül derdi Hak ateşi, 

Yanıp yanıp tutuşurlar.', 'Kalbimde bir kitap vardır,  Her harfinde bir tat vardır,  O''nu nakşeyleyen kalbe,  Rabbimden bir hitap vardır. O Rabbimin Kitabıdır,  Kullar...', ARRAY['Türk Edebiyatı','Şiir','Musa Özkan']::text[], 8.5, '{"poet":"Musa Özkan","poet_slug":"musa-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/kitap-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Memişin Para Bilgisi', 'memisin-para-bilgisi-i-hsan-uncuoglu-rbcg6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bilimin en zengini

Asırların gözdesi 

Paranın bir tanesi

Selam sana ey Peri! , 

Başkasına ama hiç aldırmayan memiş 

Netsin çare bu anda gücü yok bilgisiz

Karşısında belli bilgin kendisin geçmiş 

Seçkin zengin başkanlar cepleri dolu para

Uçakla savaşır şaşırtırlar her cahili baştan kara, 

***

Alemlerde çok kabadayı dünyaya fal açar 

Zevkten sefadan ayrılmaz seçkin adamlar 

Kimin umurunda bir bir yaslı analar ağlar

Ölen gence takılsa yetmez düzineyle madalyonlar 

Başkan bakanlardan nutuklarla mutlu yaşar insanlar! , 

*** 

Ana yar kalbi dayanmaz ağlar

Her devirde her kılıkta odur gaddar 

Masum insanları aldatan o yoz kapital 

Neresinden bakarsan zararlı günahkar 

Cıvık cıvık kirli  zevk-i sefa hesabın yapar, 

***

Eğitime yeniliğe boş verirse bir iktidar

Mutlak kapı aralarında döner petrodolarlar 

Allah der düşman sürmeyi gözden çalar durur

Dinlerde yalan yoktur nice insanı yobazdır soğutur 

Cehalettir her kim körüklerse orada ot yeşermez kurur

Düşman affetmez bilgisile alnın ortasından insan vurur! , ,', 'Bilimin en zengini Asırların gözdesi  Paranın bir tanesi Selam sana ey Peri! ,  Başkasına ama hiç aldırmayan memiş  Netsin çare bu anda gücü...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/memisin-para-bilgisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Zamanlar', 'bir-zamanlar-sait-faik-abasiyanik-j9xed', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bazı akşam üsteleri, oturur

Hikayeler yazardım, deli gibi! 

Ben hikaye yazarken

Kafamdaki insanlar

Balığa çıkarlardı.

Kadınlar, kahve cezvelerini ısıtan,

Mavi ışıklı ispirto lambalarını yakarlardı.', 'Bazı akşam üsteleri, oturur Hikayeler yazardım, deli gibi!  Ben hikaye yazarken Kafamdaki insanlar Balığa çıkarlardı. Kadınlar, kahve cezvel...', ARRAY['Türk Edebiyatı','Şiir','Sait Faik Abasıyanık']::text[], 8.5, '{"poet":"Sait Faik Abasıyanık","poet_slug":"sait-faik-abasiyanik","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bir-zamanlar-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adını Sen Koy', 'adini-sen-koy-mehmet-green-txk60', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zamannın kuytuluğunda hayalinle yaşamak, 

Yalnızlığın iç çekişini duymak, 

Ölümle yaşam arasında gidip gelen düşünceler, 

Gözyaşlarımla yazdığım şiirler, 

Çaresizliğimi apaçık gösteriyor.

Hayal denizinde rüzgarsız bir gün, 

Seni düşünmeye demir attım.

Karabulutların arkasındaki ay ışığı

Ve kabuslarımı görüyorum

Ağlamaklı oluyor gözlerim

Sensizliğin yürek yakan acısını

Anlatmaya yetmiyor.

Sevmek, umut ve kısmakmak

Hazan şöleni olmuş, 

Kopuyor gönlümden 

Sana olan duygularımı bilmiyorum, 

Adını sen koy...', 'Zamannın kuytuluğunda hayalinle yaşamak,  Yalnızlığın iç çekişini duymak,  Ölümle yaşam arasında gidip gelen düşünceler,  Gözyaşlarımla yazd...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Green']::text[], 8.5, '{"poet":"Mehmet Green","poet_slug":"mehmet-green","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/adini-sen-koy-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Endişe', 'endise-suleyman-kizil-faogd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bazen Bir Köşede Oturur Dururum

Bazen Gizice Seni Seyrederim

Seni Kaybetmek Endişesiyle

Yanıp Tutuşurum

Dünyam Yıkılır Seni Görmezsem

Hayatım Tükenir Yanımda Olmazsan

Yaşamak Neye Yarar

Sen Beni Sevmezsen

Kurşun Bile Vız Gelir Deli Gönlüme

Ben Bir Seni Sevdim

Bir de Sabah Rüzgarının Yaydıgı Kokunu

Üzülme Sen 

Sen Üzülmeki

Yüzünde Tebessüm Eksik Olmasın

Hep, 

Hep Gülsün O Güzel Gamzelerin', 'Bazen Bir Köşede Oturur Dururum Bazen Gizice Seni Seyrederim Seni Kaybetmek Endişesiyle Yanıp Tutuşurum Dünyam Yıkılır Seni Görmezsem Hayatı...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Kızıl']::text[], 8.5, '{"poet":"Süleyman Kızıl","poet_slug":"suleyman-kizil","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/endise-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğim Bağdat', 'yuregim-bagdat-omer-sevim-ek93o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uçak seslerine karışıyor ninniler

Tank paletlerinin gıcırtısına

Feryatlar karışıyor

Yanıyor yüreğim

Bombalar patlıyor yüreğimde

Yüreğim Bağdat

Gözlerimin önünden gitmiyor

Narkozsuz bıçak altına giren anneler

Kaçırıyorum gözlerimi

Utanıyorum başı sargılı çocuktan

Gözlerim isyan gözlerim nefret

Gözlerim Bağdat

Sam yelleri esmez oldu

Sussuz Kerbela çölleri kanla doldu

Bedenim ruhumu taşıyamaz oldu

Bedenim Kerbela çöllerinde yalnız

Bedenim paramparça

Bedenim Bağdat...', 'Uçak seslerine karışıyor ninniler Tank paletlerinin gıcırtısına Feryatlar karışıyor Yanıyor yüreğim Bombalar patlıyor yüreğimde Yüreğim Bağd...', ARRAY['Türk Edebiyatı','Şiir','Ömer Sevim']::text[], 8.5, '{"poet":"Ömer Sevim","poet_slug":"omer-sevim","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yuregim-bagdat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Romanı', 'sevda-romani-taskin-su-fwixk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne kalemimin mürekkebi

Ne kağıdın beyazı

Ne de benim bildiğim kelimeler

Yetmez bu sevda romanına', 'Ne kalemimin mürekkebi Ne kağıdın beyazı Ne de benim bildiğim kelimeler Yetmez bu sevda romanına...', ARRAY['Türk Edebiyatı','Şiir','Taşkın Su']::text[], 8.5, '{"poet":"Taşkın Su","poet_slug":"taskin-su","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sevda-romani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Benim Yorgun Bir Sabah Başkaldırışımsın', 'sen-benim-yorgun-bir-sabah-baskaldirisimsin-melih-coskun-ofqfo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yine yorgun bir sabaha merhaba diyecek gözlerim

Cesur bir gecenin sabahına uyanacağım 

Bitkin ve çaresiz 

Oysa dün gece yine avcumun içinde sıkıp bunaltmıştım evreni 

Öyle başı dik 

Öyle yenilmez 

Ve öyle gururlu 

Kıpkırmızı gözlerle gülümseyip hüznün yüzüne 

Dünyanın ötesinde bir yoldaşa merhaba dedim 

Belki ruhsuz beton yığınları arasında dolaşıyordu 

Belki Konya’nın sonsuz sarıları içinde bir beyaz mendildi 

Öptü usulca beynimde  dolaşan 

İnce ayaklı  evcil geyiği gözlerinden 

Belki şu anda kan ve ter içinde bir gecenin sabahına uyanmaktadır

Karlı tepeler ardında ışıl ışıl gözleriyle ışığı beklemektedir 

Yanı başımdadır belki de 

Soluğumun sıcaklığını alnında hissedecek kadar 

Gözlerimin içine bakmaktadır    

Yıldızlar kadar uzaktadır 

Veya nefesin sıcaklığı kadar yakın 

Nerede olursa olsun 

Beynimde yanandır o benim

Ruhumda yanan

Alevler içinde koşuyorum 

Yıkıyorum zulmün harcıyla örülmüş duvarları 

Koşuyorum 

Çünkü 

Ruhumda alevlenensin sensin benim 

Hücre hücre 

Organ organ örgütleyen bedenimi 

Sen benim yorgun bir sabaha başkaldırışımsın...

25 Şubat 2003

01: 59', 'Yine yorgun bir sabaha merhaba diyecek gözlerim Cesur bir gecenin sabahına uyanacağım  Bitkin ve çaresiz  Oysa dün gece yine avcumun içinde ...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/sen-benim-yorgun-bir-sabah-baskaldirisimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm Anı', 'olum-ani-salih-ozalasan-xad4b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ölümü gördüm bugün, yaşlı gözlerde

Bir bedenin candan ayrılışını, umutsuz titremelerle

Direnişi gördüm bugün, kapalı gözlerde

Bedenin toprağa dönüşünü, ruhun başka bir aleme

Kanım dondu, nefesim boğazıma takılı kaldı

Geldiği yere dönüşe belki bir nefes vardı

O nefesi alıp vermek istemeyen bir beden

Başucunda feryat figan eşi dostları

Belki özlemişti fani beden toprağı

Yavaş, yavaş terk ediyor bir can

Yıllarca kullandığı bir bedeni

Havasını kokladığı, suyunu içtiği mekanı

Zavallıydı, güçsüzdü, çaresizdi, yorgun beden

Belki de hiç terk etmeyecek sanmıştı bedenini canı

Ben sanırdım zor olan insanın doğum anı

Dokuz ay bekleyiş sonra görmek Dünyanı

Oysa ölüm dokuz bin yıl gibi uzun

Can çıkarken perişan ediyor insanı

Tutunacağın ne bir dal, ne bir dost

Bekleme kimseden medet ummanı

Nasıl ki bir çığlık sesi, ve ağlayış

Sevenlerin hoş geldin diye sunuyorsa sana dünyanı

Yine bir ağlayış, hıçkırık sesleri

Bu defa belki can gülerek terk ediyor dünyanı

Ve son nefes, kimsenin kalmamış

Seni geldiğin yere göndermekten başka yapacağı

Artık sensiz tütecek

Senin neslin yakacak bu ocağı

Seni bekliyor bu kara toprak

Özlemiş, sanki ardına kadar açılmış kucağı

Ruhun şad olsun, cennettir inşallah

O tatlı canın ebedi mekanı

Ve ben ölene kadar hatırlayacağım

Bedeni ter eden bir ruhun ardından baka kalmamı

Kara toprak ne olur incitme

Sağlığında hep çile çeken amcamı

“31 martta ölen amcam anısına”

Yazım tarihi 05-04-2003 Saat 14,20

Salih ÖZALAŞAN', 'Ölümü gördüm bugün, yaşlı gözlerde Bir bedenin candan ayrılışını, umutsuz titremelerle Direnişi gördüm bugün, kapalı gözlerde Bedenin toprağ...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/olum-ani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaktaki ben', 'uzaktaki-ben-agah-ozbek-643kl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uzun konuşmaların kısaldığı gece

Rüyasız, düşsüz yatak yorgan

Uykusuz gece

Yıldızlar yön değiştirmiş Küçük Ayı, Çoban Yıldızı

Yerde geziyor Büyük Ayı, Samanyolu..

Bu kabus bu korku

Birazdan bombalar dökülecek üzerlerine

İpekyolunun.

Unutulmuşken savaşın çığırtkanlığı

Teknoljinin yardımıyla donatılırken uçaklar...

İskenderun Limanı dikenli tellerle kaplı

Brandalar çekilmiş içeride gizlilik

Dışarda kum kamyonlarının taşıdığı cipler

Kılıflarla kamufilaj edilmiş uzaktan kumandalı füzeler

Saatler yaklaşıyor yokoluşun sınırına

Ve İncirlikte son komut.

İstanbul Borsası akıtıyor salyasını kontrolsuz

€ 1660, $ 1770 milyon Türk Lirası

Ya sınır otesinde savaş

Anadoluda pahalılık korku, kargaşa

Yinede herşeyden habersiz devam ediyor savaş

Irakta kan var, Irakta barut kokusu

Çocuklar ölüyor, akşamın karanlığı

Kum fırtınası, kahrolasıca soğuk, açlık

Savaşa hayır dedi milyonlarca insan

Devletler yarış yaptı kendi sokaklarında

Onurumuz oldu verilmeyen Teskere

Türkiye Büyük Millet Meclisi şaşırtı tüm Dünyayı

Kim sallar güçlünün önünde beşik

O cebime değil koy şu cebime

Oradan değil gel burdan

Ben gitme desemde sen git

Uzakta silahlar patlıyor

Bombalar dökülüyor Teyyarelerden

Ses yok canlıdan yana

Sen yine çal türkülerini

Çek halayını yudumla içkini

Uzan koltuğunda seyret olanları 

Ve benim beynim Irakta

Neden savaş, niçin savaş, niye savaş...

Iraktaki ben...

                                                         20-03-2003-Wuppertal', 'Uzun konuşmaların kısaldığı gece Rüyasız, düşsüz yatak yorgan Uykusuz gece Yıldızlar yön değiştirmiş Küçük Ayı, Çoban Yıldızı Yerde geziyor ...', ARRAY['Türk Edebiyatı','Şiir','Agah Özbek']::text[], 8.5, '{"poet":"Agah Özbek","poet_slug":"agah-ozbek","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/uzaktaki-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlık', 'karanlik-agah-ozbek-zrtrv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bilirimki insanlık duru su gibidir

Kaynağı derin yatağı soğuk

Kaynaşıp girip tabiyatın bağrına

Kavak dipleri, salkım söğüt

Daralıpta dökülüp taşların arasından

Sessizliğe bir kurşun sesi

Senmisin dökülen ellerime su tanecikleri

Babam, annem ve ben

Kısa taşların üzerinden sekerek

Gaz feneri ışığında zifir karanlık

Uzaklardan gelen köpek havlamaları ve çirkin soğuk

Eskidendi olup bitenler

Zaman neçabuk geçti

Şimdi ölümle karşı karşıyayım

Ölümün arkası karanlık...

                                            10-02-2003 -Wuppertal', 'Bilirimki insanlık duru su gibidir Kaynağı derin yatağı soğuk Kaynaşıp girip tabiyatın bağrına Kavak dipleri, salkım söğüt Daralıpta dökülüp...', ARRAY['Türk Edebiyatı','Şiir','Agah Özbek']::text[], 8.5, '{"poet":"Agah Özbek","poet_slug":"agah-ozbek","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/karanlik-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'seni', 'seni-agah-ozbek-dxupr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni yazmak istiyorum

Kalem gibi, şiir gibi, şarkı gibi

Seni yazmak istiyorum

Anamın yazmaya işlediği

Nakış gibi

Seni yazarak sürdürmek istiyorum

Sonsuz bir çizgi gibi

Ama kaybetmek var

Şiirdeki son nakarat gibi

Çünki bozuldu artık gitmez

Kalemdeki boya bitti...

                                                       10-01-1981-Adana', 'Seni yazmak istiyorum Kalem gibi, şiir gibi, şarkı gibi Seni yazmak istiyorum Anamın yazmaya işlediği Nakış gibi Seni yazarak sürdürmek isti...', ARRAY['Türk Edebiyatı','Şiir','Agah Özbek']::text[], 8.5, '{"poet":"Agah Özbek","poet_slug":"agah-ozbek","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seni-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siyahı Bırakıyorum Sana!', 'siyahi-birakiyorum-sana-naime-erlacin-sbcih', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'koptuysam eğer gerçeklikten

''geçmişe dair'' olduysam kendimce

boşuna arama beni odalarda

anıları topla

iyi bak! 

belki kalmıştır bir parçam 

içine düştüğüm aynalarda

tutuyorsam yolu ardıma bakmadan

bütün köprüleri yıkarak

açıyorsam yelkeni sonsuza 

artık duymasan da olur sesimi

o sevdiğin kokumu

olsa olsa kalmıştır belki 

saçımın bir teli buruşuk yastığında

ihtimal yorgun düştüm yorulmaktan

güzelce toplayıp 

çıkınıma koydum yaşamı 

''anca giderim'' deyip koyuldum yola

yüreğimdeki çocuğun elini tutarak

sen şimdi baharı bekle 

çiçeklerin açmasını ruhunda

tomurcuklarım yalnızca bana ait

bana açacak bundan sonra 

nereye döndüysem siyah

nereye gittiysem akşamdı 

oysa gün 

her dem taze olmalı

gündoğumuna dönmeli dünya

her şafakta kalbim yerinden oynamalı

bedenim bir bakışta aşka uyanmalı

gidiyorum! 

pembeler 

yeşiller 

ölümsüz mavilerle kol kola

sana kalan yalnızca siyah

siyahı bırakıyorum sana 

(06 Nisan 2003)', 'koptuysam eğer gerçeklikten ''geçmişe dair'' olduysam kendimce boşuna arama beni odalarda anıları topla iyi bak!  belki kalmıştır bir parçam  ...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/siyahi-birakiyorum-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'gozunu-toprak-doyursun', 'gozunu-toprak-doyursun-emine-sumra-w4uc1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mezar sessizliğine bürünmüş yüreğim

       Ölü yürekleri nereye gömerler bir bilen var mı? .

       Sahipsiz bir ölü gibi götürüp gömeyim yüreğimi

       Ne dua eden bir hoca, nede cemaat bulunsun

       Saf tutacak birkaç anı, mutlu birkaç gün belki

       Ne çok cemaat oluşturur acılarda eklenirse

       Kişiyi nasıl bilirdiniz diye kim soracak                                                                                                                                                                                              

       Kim iyi bilirdik  gömün gitsin diyecek?                                                                                                                                                                                                         Vazgeçtim yüreğimi yalnız gömmekten

       En azından bir imam bulunsun 

       Bu dünyada doymadın  yüreğim

       Bari gözünü toprak doyursun.', 'Mezar sessizliğine bürünmüş yüreğim        Ölü yürekleri nereye gömerler bir bilen var mı? .        Sahipsiz bir ölü gibi götürüp gömeyim yü...', ARRAY['Türk Edebiyatı','Şiir','Emine Sumra']::text[], 8.5, '{"poet":"Emine Sumra","poet_slug":"emine-sumra","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gozunu-toprak-doyursun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yal(n) an Mumlar', 'yal-n-an-mumlar-reha-basogul-e2yjw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ışık nesebinden büyük sayılırmışsın 

ama gece hakkında ipe sapa gelmez konuşuyor

davet ettiğin gözlerinin doğumgününde

sayacağım bakalım üstünde yal(n) an mumların yaşını

zaten artık yüreğimde kimse onlar kadar uzun yaşamıyor', 'ışık nesebinden büyük sayılırmışsın  ama gece hakkında ipe sapa gelmez konuşuyor davet ettiğin gözlerinin doğumgününde sayacağım bakalım üst...', ARRAY['Türk Edebiyatı','Şiir','Reha Başoğul']::text[], 8.5, '{"poet":"Reha Başoğul","poet_slug":"reha-basogul","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yal-n-an-mumlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kukla', 'kukla-reha-basogul-cvw5u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kaç saatte büyüttüm seni bir bilsen

bakmazdın bana, sıradan bir sahip gibi

kaç gece oynatmamı istedi seni benden bir bilsen

saklardın beni ketumluğunun altına, savaştan kaçar gibi

ellerim kaçtı

kasıklarım şaştı

sesim rüzgarı aştı

basılı bir kor tanesinde

iplerim bağışlasın beni

kusurlu aşklar çeşmesinde

bedevi kaldım

sabrım taştı

yerin kurudu

sen dağıttın oynar başını

ılık ülkenin bahar akşamında konuşan

yapraklı yollarda alnıma mine koyan

ey duyuların koruyucusu! 

ey erkekliğin münzevisi! 

yaklaş bana! 

bu kuklanın kiriyle

nasıl yıkanır aşk 

nasıl imbatlara sarılır

uçar ininden

karanlık niye susmaz ki yerinden

sazını ozana bırakmaz

gözünü sakınmaz tenden

öğret böceklerin dilini

çamura karışayım yarın

kapat kuklamın perdesini

yüzüne bakayım yarın', 'Kaç saatte büyüttüm seni bir bilsen bakmazdın bana, sıradan bir sahip gibi kaç gece oynatmamı istedi seni benden bir bilsen saklardın beni k...', ARRAY['Türk Edebiyatı','Şiir','Reha Başoğul']::text[], 8.5, '{"poet":"Reha Başoğul","poet_slug":"reha-basogul","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/kukla-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkım', 'askim-osman-i-nci-4nkzz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mevsimler içinde, 

Soğuk kış olsan, 

Dertlerin içinde, 

Ecelim olsan, 

Sevmişim bir kere, 

Vazgeçemem ki...

İdamım yazılsa, 

Celladım olsan, 

Mezarım kazılsa, 

Kefenim olsan, 

Sevmişim bir kere, 

Vazgeçemem ki...', 'Mevsimler içinde,  Soğuk kış olsan,  Dertlerin içinde,  Ecelim olsan,  Sevmişim bir kere,  Vazgeçemem ki... İdamım yazılsa,  Celladım olsan,...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/askim-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuğu beyazı yüzeyine ayın', 'kugu-beyazi-yuzeyine-ayin-baris-yavuz-04sj3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kuğu beyazı yüzeyine ayın

sen ve ben aynı anda bakmışız dün gece

	şımarık birer çocuk gibi saklanbaç oynarlarken, 

	      bir görünüp bir kaybolarak 

	            ay ve yaramaz bulutlar semada	

	sen evinde cam kenarında 

		buğulu gözlerle 

	ben evimin yolunda cam kenarında minibüsün 

		yorgun gözlerle  		

	beklemişiz suretlerimiz görünsün üzerinde diye.

	Hani birde söz vermiştim ki kendi kendime 

		bulutlar çekip gidince

		    yıldızları toka yapacaktım saçına kendimce

amma velakin sıcak bir çaya düşen iki şeker misali

	eriyip yokoldu hayallerim

		kaybolan suretinle birlikte.

İşte o vakit

	yazdım nemli mendilime; 

			

kuğu beyazı yüzeyine ayın

	devasa bir ayna yerleştirmeli.

o ayna öyle olmalı ki; 

	    bakıldığı vakit yanlız ve yanlız

	  	sonsuz aşkların saf temiz aşıklarının, 

	    	    yani bizlerin görebileceği. 

o ayna öyle olmalı ki; 

hervakit baktığımda ona 

  sevdiğimi görebileyim

 	nefes alışını, gülen gözlerini, 

		ak yastıkta saçlarını, küçücük ipeksi ellerini

		  			

o ayna öyle olmalı ki; 

beş bin ışık yılı ötede parlayan gezegeni

	keşfeden astronomlar bile kıskanmalı benı 

	    böyle güzelini göremedik diye	 

O yaramaz bulutlara da soylemeli

	yok burda yerleri 

	   önerirdik hep mutlu olabilecekleri

		hani güneşin hiç batmadığı o krallıkları.

güneş mi? 

varsayalım ki 

	ayrı kalaçagım senden aylarca 

Ah sevgilim, bilmezmisin sen beni...

	ondan da vazgeçerdim hani

 		sırf bu özlemim uğrunda

			senden uzakta olsamda yaşamak seninle

			   hemde an ve an

			        görebilmek seni semada  

					hissedebilmek seni yanımda

(Istanbul 10/01/2003)', 'Kuğu beyazı yüzeyine ayın sen ve ben aynı anda bakmışız dün gece 	şımarık birer çocuk gibi saklanbaç oynarlarken,  	      bir görünüp bir ka...', ARRAY['Türk Edebiyatı','Şiir','Barış Yavuz']::text[], 8.5, '{"poet":"Barış Yavuz","poet_slug":"baris-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/kugu-beyazi-yuzeyine-ayin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allah Yolunda Gafletlerdeyiz', 'allah-yolunda-gafletlerdeyiz-ahmet-agdere-fvzey', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaşamak varken her soluk ve adımda, 

Yaratılan sıfatıyla, yaratanın adıyla; 

Boşuna çabalar ve nefeslerdeyiz, 

Bir nevi en büyük gafletteyiz...

Bilmem selam kime, nasılsın niçin? 

Seni seviyorum diye, kime sesleniriz kime? 

Dil kimin? Yar kimin? Dünya kimin? 

Kesmek için dilimi, verin baltayı elime! 

Ömrümüz fizik, kimya ve matematik, 

Din dersimiz yok ki, o da olsun kritik! 

Hocalar ölmüş, yaşasın artık öğretmenler! 

Fark etmeden kalınmışız ziyankar ve bitik! 

Hanımlar rahatsızmış, kıssınlar ezanın sesini! 

Bilmezler bu vatanı kurtaranın kendisini! 

Haaşa ilah yaptılar Tarkan''ı ve Nez''i, 

Kurtarsınlar şimdi de görelim memleketi! 

Spor tüm branşlarda sürüp gidiyor, 

İsim isim tüm sporcular biliniyor.

Hani ya Mukaddes Kitap''ın sureleri? 

Çarşamba''yı sel almış onu da götürüyor! 

Güzelim teknoloji gelişmiş neye yarar? 

Tv''yi, radyoyu, pc''yi ateşler sarar! 

Akıllı bombalar atılır Irak semalarında, 

Ah be teknoloji ah, yüreğim kanar! 

Dinimiz emreder yaşamayı kardeşçe! 

Olur mu hep böyle izlemek kalleşçe! 

''Yetiş Muhammed, yetiş Ali! '' miz beste, 

Sakız gibi geveler dururuz günlerce! 

Bir ömür ki gaflet içinde gaflet! 

Ahır zaman gelmiş, yetiş Muhammet! 

Zaman haramdır, fiiller ise günah kesesi, 

Yarattığın ruh hatrına, rabbim bizi affet!', 'Yaşamak varken her soluk ve adımda,  Yaratılan sıfatıyla, yaratanın adıyla;  Boşuna çabalar ve nefeslerdeyiz,  Bir nevi en büyük gafletteyiz...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/allah-yolunda-gafletlerdeyiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Berzah', 'berzah-ahmet-agdere-xvo0q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Berzah, açıl biraz daraltma beni! 

Ay yüzlü yarimden ayırma beni! 

Dokunayım tenine, elin degmesin yüreğime; 

Eğ başını önüne, çıldırtma beni!', 'Berzah, açıl biraz daraltma beni!  Ay yüzlü yarimden ayırma beni!  Dokunayım tenine, elin degmesin yüreğime;  Eğ başını önüne, çıldırtma ben...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/berzah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasamak', 'yasamak-baris-yavuz-f9q8c', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bugun bir kiz gordum 

birlikte bindik alemdag otobusune 

ben oturdum o ayakta, 

belliki garip, ama hayata bagli.

nerden anladin dersen, boyamis ayakkabisini 

kapamamis dikisi atan kismini 

apacik meydanda giydigi siyah corabi 

belli ki hayata bagli, tutmus bir ucundan hayallerinin 

asmis hamagini bir cift yildiza. 

kisadan hisse derim ki; 

insanoglu ademden bu yana 

aramali sadece guzeli, sevgiyi 

olsa ki aradigi o astigi hamakta 

bilse ki onlar o kadar erisilmez 

yasamayi denemeli yine de 

sevdiklerini mutlu etme ugruna 

(Istanbul 12/23/2002)', 'bugun bir kiz gordum  birlikte bindik alemdag otobusune  ben oturdum o ayakta,  belliki garip, ama hayata bagli. nerden anladin dersen, boya...', ARRAY['Türk Edebiyatı','Şiir','Barış Yavuz']::text[], 8.5, '{"poet":"Barış Yavuz","poet_slug":"baris-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yasamak-53-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk''a', 'ask-a-ahmet-agdere-b5ptr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir kelimesin lakin, üç harften ibaretsin,

Bir gönüle girer de, çıkışı bilemezsin. 

Kördür gözlerin ama, hür gönülle yaşarsın,

Tasmasız, sahipsiz şu dünyada gezinirsin! 

Dağılmışsın hücreler misali yeryüzüne; 

Sayende eğilir gönüller güzel yüzüne, 

Neyse ki tek bir kul için yaratılmamışsın; 

Nasıl verirdin hesabını kendi kendine? 

Bir tarafında cennet, diğerinde cehennem; 

Bulunmaz açtığın bir yaraya, tek bir merhem! 

Dolanırsın ha bir nefste, ha ruhun içinde; 

Öyle baş döndürürsün ki, nerdesin bilemem! 

Sadakat, düşünce ve sevgi hep sana dair! 

Kaç asır düşürmüşsün ardına nice şair! 

Zaman senin için, duygu senin için, kader… 

Gizlerin içinde gizsin, sırrın bile zahir! ...', 'Bir kelimesin lakin, üç harften ibaretsin, Bir gönüle girer de, çıkışı bilemezsin.  Kördür gözlerin ama, hür gönülle yaşarsın, Tasmasız, sah...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ask-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaradan...', 'yaradan-seref-tan-690mb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kim bestelemiş kim, kim ötüşünü bülbülün? 

Kim kondurmuş üstüne hicap rengini gülün? 

Kin nektar, polen kimyasını okutmuş arıya? 

Kim ne için ağla demiş, yeni doğan yavruya? 

                                                      (Elazığ)', 'Kim bestelemiş kim, kim ötüşünü bülbülün?  Kim kondurmuş üstüne hicap rengini gülün?  Kin nektar, polen kimyasını okutmuş arıya?  Kim ne içi...', ARRAY['Türk Edebiyatı','Şiir','Şeref Tan']::text[], 8.5, '{"poet":"Şeref Tan","poet_slug":"seref-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yaradan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçen Zaman', 'gecen-zaman-yasar-karaman-q5yqo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Eskiyen eşyaları yenilerken

Farkına varmadınız geçen zamanın

Nisan ya da Eylül, yağmurlar yağıyordu

Sokakta oynayan aynı çocuktu

Öyle sandınız.

Oysa ben, ah neler umuyordum

İnsan yitip gidenlerin geç farkına varıyor

Ben seni seviyordum.', 'Eskiyen eşyaları yenilerken Farkına varmadınız geçen zamanın Nisan ya da Eylül, yağmurlar yağıyordu Sokakta oynayan aynı çocuktu Öyle sandın...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Karaman']::text[], 8.5, '{"poet":"Yaşar Karaman","poet_slug":"yasar-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gecen-zaman-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BEN RAZIYIM ÖLÜME', 'ben-raziyim-olume-zafer-uzunhasan-ldq2q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben Razıyım

Karanlıklar ülkesinde geçsede ömrüm, 

Ben karanlığa alışırım gülüm. 

Sensiz geçecekse ömrüm, 

Bilki ben ölüme razıyım gülüm. 

Mazi olursa günler, 

Solarsa bana verdiğin güller, 

Sensiz geçecekse günler 

Ben ölüme razıyım susmasın bülbüller. 

Mutsuz geçecekse günlerin, 

Tutmayacaksa ellerimi ellerin 

Bana yalan söyleyecekse dilin 

Ben razıyım kör olsun gözlerim. 

Bırakıp gideceksen beni, 

Tutmayacaksan ellerimi 

Sevmiyorum diyeceksen seni 

Ben razıyım ölüme sen yeter ki sev beni', 'Ben Razıyım Karanlıklar ülkesinde geçsede ömrüm,  Ben karanlığa alışırım gülüm.  Sensiz geçecekse ömrüm,  Bilki ben ölüme razıyım gülüm.  Ma...', ARRAY['Türk Edebiyatı','Şiir','Zafer Uzunhasan']::text[], 8.5, '{"poet":"Zafer Uzunhasan","poet_slug":"zafer-uzunhasan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ben-raziyim-olume-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Affet', 'affet-arzu-dincer-t85yy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Affet beni kardeşim, 

Dünyanın neresindeysen.

Şiir tadında bir yaşam

Çalınıyorken hayatından

Açlıktan 

Ve 

Ateş toplarında

Yakalanıyorken 

Ölüme

Çaresiz bırakıldığın için, 

Ve 

Gözyaşların, 

Gözyaşlarıma kavuşuyorken, 

Kader çizgin, 

Sebepsiz ölümlerle kesiliyorken, 

Affet...biçare halimi

Ürkek bir av gibi bırakıldığın için, 

Ve umut

Tankla, tüfekle sunuluyorken

Seyirci bırakıldığım için

Affet...

Çiçek  demeti tazeliğinde

Sunuluyorken kan kusan teknoloji

Ambargo şemsiyesinde

İlaçsız, ekmeksiz bırakıldığın için

Bebelerin koparıldığı için yaşamdan

Affet...

Anam, babam, bacım

Ne ise sıfatın 

Ya da ne olmasını istiyorsan

Affet...

Günah çıkarmak değil, 

Yüreğim 

Yüreksiz bırakıldığı

Ellerim

Bağlandığı için

Türkülerin dilinde

Kardeşlik adına

Affet', 'Affet beni kardeşim,  Dünyanın neresindeysen. Şiir tadında bir yaşam Çalınıyorken hayatından Açlıktan  Ve  Ateş toplarında Yakalanıyorken  Ö...', ARRAY['Türk Edebiyatı','Şiir','Arzu Dinçer']::text[], 8.5, '{"poet":"Arzu Dinçer","poet_slug":"arzu-dincer","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/affet-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üç Nokta', 'uc-nokta-melek-midikoglu-rcxk0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yolun sonu, aşk mı? Var mı? 

Bilemezken, 

Çıkamamıştık sokağın başına.

Dağ çocuklarının günlük çeşme başı; 

Kurulamaz hayaldi, 

Bizde sene başı...

Ben hayallerimize umut serdim

Sonra kuramadım topladım, 

Birdaha serdim.

Niye mi

Çıkmaz sokağa varmıştık, 

Çok ıslanmıştık.

03.04.2003', 'Yolun sonu, aşk mı? Var mı?  Bilemezken,  Çıkamamıştık sokağın başına. Dağ çocuklarının günlük çeşme başı;  Kurulamaz hayaldi,  Bizde sene b...', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/uc-nokta-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Askerlik*', 'askerlik-bayram-tunca-k6lu7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Geldi çattı askerlik çağı

Beni bekler asker ocağı

Ah ne sıcaktı, o anne kucağı

Ama, kışla peygamber ocağı

Veda edip, düştüm gurbet yoluna

Hasret kaldım, sevdiğimin koluna

Söyleyin, dua etsinler tüm askere

İnşallah nasip olur bize o tezkere

Gidip devir alacağım şanlı sancağı

Şehit de olsam, bırakmam sancağı

Uğurunda akıtılmış, nice şehit kanı 

Uğrunda vermeye hazırım, bu canı

Başımdaki saç adedince başım olsaydı

Her gün vatan uğrunda birisi alınsaydı

Yine de uğrunda şehit olmaya değerdi

Ne kadar isterdim uğrunda ölebilmeyi

14.02.2003.-14.14', 'Geldi çattı askerlik çağı Beni bekler asker ocağı Ah ne sıcaktı, o anne kucağı Ama, kışla peygamber ocağı Veda edip, düştüm gurbet yoluna Ha...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/askerlik-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kır Şiiri', 'kir-siiri-arzu-dincer-lhf1h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Erguvanlar kaplamış kırları, 

Kırlar, adı sanı olmayan, memleket misali

Kendi yaşamına sahip çıkmış

Lavantalar çiçek açmış

Mis kokuları sarmış

Koynunda milyonlarca canlı

Öyle anaç

Öyle nazlı

Kendi kuralları

Kurallar içinde 

Uygulamalı öğreniyor

Yeni doğan yaşamı..

Güçlü hayatta, 

Güçsüz

Yenik düşüyor kurala

Kırlar, adı sanı olmayan, memleket misali

Doğaca yaşamı güzel kılıyor.

Kendi sesi, kendi kokusu

Kendi dokusu ile

Özbenliği yaşıyor

Ne kimya tanıyorlar renkte, 

Ne de tıp bilgisi ile harmanlı

Doğumu, yaşamı, ölümü..

Saf 

Ve bir o kadar

Gerçek 

Kırlar, adı sanı olmayan, memleket misali

Kitapları yok onların, 

Yobazlıkları, hırsları...

Tankları, tüfekleri...

Toprağın 

Ve 

Göğün verdiği

Can ile 

Yaşıyorlar yaşamı

Kırlar, adı sanı olmayan, memleket misali', 'Erguvanlar kaplamış kırları,  Kırlar, adı sanı olmayan, memleket misali Kendi yaşamına sahip çıkmış Lavantalar çiçek açmış Mis kokuları sarm...', ARRAY['Türk Edebiyatı','Şiir','Arzu Dinçer']::text[], 8.5, '{"poet":"Arzu Dinçer","poet_slug":"arzu-dincer","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/kir-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'marks a ağıt', 'marks-a-agit-cetin-isik-ftv99', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'beni buraya kim getirdi? 

neden? 

olbilemem

neden yaşadığımı bilmeden...

olmuşum, gelmişim.bırakın.

ne olabileceğimi tasarlayayım, 

geçip, yitmeden

kim? 

ve neyle savaştığını

bilmeyenlerle

savaşmak zorunda bırakıyor

beni...

neden? 

bilmek istiyorum, 

kim için savaştığımı.

kabul, kendim için

ama, niçin

uff! anlatması çok zor

çok büyük bir düzen, 

herkesi düşünen bir patron. 

ve kademe kademe

bizler, işçiler, öğrenciler, memurlar

yoksullar, yoksunlar.

üretiyoruz...üretiyoruz.

bizler için

ama daha çok kimin için

anlatması zor! gözlerini kapat

ya da yıldızlara bak...

biraz kafanı yor

göreceksin, 

benim gibi

çözemeyeceksin

ve çözülmeyenlere karşı 

çözüleceksin.

bu kendini bulman için

diyalektliğe başvurmanın 

ilk kapısıdır

GİRECEKSİN....', 'beni buraya kim getirdi?  neden?  olbilemem neden yaşadığımı bilmeden... olmuşum, gelmişim.bırakın. ne olabileceğimi tasarlayayım,  geçip, y...', ARRAY['Türk Edebiyatı','Şiir','Çetin Işık']::text[], 8.5, '{"poet":"Çetin Işık","poet_slug":"cetin-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/marks-a-agit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belâ hastası', 'bel-hastasi-serdar-tuncer-z7pfn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Haykırır sükûtu, surdadır nöbet

Ölüm kement atıp, güler ölüme 

Son durak ezelde, ilk nasıl ebet? 

İç kendi kanını, çıldır kelime! 

Akıl sudan kova, hakikat kuyu

Çözdüğüm her suâl, cevaba perde

Yaktım da suları yıkayan suyu

Güneşi ıslatan o ateş nerde? 

Ara dur kendini belâ hastası 

Sen varsın yokluğu çıldırtan yokta

Rûhun bedenine deli yaftası 

Yay sensin kendine çevrilen okta! 

(26/06/1997 Kayseri)', 'Haykırır sükûtu, surdadır nöbet Ölüm kement atıp, güler ölüme  Son durak ezelde, ilk nasıl ebet?  İç kendi kanını, çıldır kelime!  Akıl suda...', ARRAY['Türk Edebiyatı','Şiir','Serdar Tuncer']::text[], 8.5, '{"poet":"Serdar Tuncer","poet_slug":"serdar-tuncer","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bela-hastasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gültanem 16', 'gultanem-16-feyza-kalender-403kj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'halim nedir bana sorma

ben, benden bihaberim

anlık yaşıyorum, tıpkı 

seni yaşadığım gibi.

irdelemedim, senden

ne aldığımı, ne verdiğimi sana

hesap tutmadım kara kuytularda

    *    *    *

çelik mavisi gök, yosun yeşili bir göl

belki karakalem bir müsvedde, 

olsun da bir gömlek kolu dirsekte.

hırçın çağalyan bie nehirden 

bir ince sızıntıya döndüm.

aktığım yol değişti, yön değişti, 

kudrudum da bir damla suya döndüm.

seni kaldırdığımdan beri, resmin bana 

dosttan düşmana döndü.

içmediğin bir damla sudan sonra

kendimi kendimden sakınır oldum.

                05.04.2003   feyza kalender', 'halim nedir bana sorma ben, benden bihaberim anlık yaşıyorum, tıpkı  seni yaşadığım gibi. irdelemedim, senden ne aldığımı, ne verdiğimi sana...', ARRAY['Türk Edebiyatı','Şiir','Feyza Kalender']::text[], 8.5, '{"poet":"Feyza Kalender","poet_slug":"feyza-kalender","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gultanem-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sensiz Yaşamak II', 'seni-sensiz-yasamak-ii-serdar-tuncer-m7d6j', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Esir güneş pervanedir hürriyet gecesine 

Yakamozlar göz kırpmaz, öldürürsen şarkımı 

Kulak verir kâtiller, kurbanının sesine 

Umut mudur ellerin, avuçların korku mu? 

Esir güneş pervanedir hürriyet gecesine...

Demin akrep boğuldu, şimdi susuz yelkovan

Ya gel de bengisu ol, ya deryaya dalsana 

Sen zamansız ölüsünü, kalbimde senli zaman 

Ölümsüz saatlerde aşk türküsü çal bana 

Demin akrep boğuldu, şimdi susuz yelkovan...

Rüyamda rüzgâr eser, ben öldürdüm kuşları 

Kanlı yola hediyen, mâsun ayak izlerim

Gözlerin işlese de alnımdaki suçları 

Celladım sen olursan, söz adını gizlerim

Rüyamda rüzgâr eser, ben öldürdüm kuşları...

Aşk nakışlı bûseyi yeter ki ver giderim, 

İsyankâr gecelerin en hüzzam şafağında.

Gözlerinde dalıp da belki bir ''âh'' ederim, 

Hicran sözlü yolların nihâvent sokağında.

Sende bir ''sen'' olmayı, sensizlikle öderim, 

Aynalarda sen varsın, ben yokluk otağında.

Devâsâ bir sevdâya elvedâdır kaderim, 

Seni sensiz yaşamanın, müebbetlik çağında...

İ', 'Esir güneş pervanedir hürriyet gecesine  Yakamozlar göz kırpmaz, öldürürsen şarkımı  Kulak verir kâtiller, kurbanının sesine  Umut mudur ell...', ARRAY['Türk Edebiyatı','Şiir','Serdar Tuncer']::text[], 8.5, '{"poet":"Serdar Tuncer","poet_slug":"serdar-tuncer","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/seni-sensiz-yasamak-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya', 'ruya-mahir-kurt-toslr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Suda bir balık, balıkta yara

Suda bir balık daha.

Karşılaştılar iki balık suda, 

Sordu; o yarayı kim verdi sana? 

Ne önemi var, geçer dedi bu yara.

Yaralı ama yardım istemiyor balık, 

Ne olmuştu acaba? 

Havada bir kuş, kuşta yara

Havada bir kuş daha.

Karşılaştılar iki kuş havada, 

Sordu; o yarayı kim verdi sana? 

Ne önemi var, geçer dedi bu yara.

Yaralı ama yardım istemiyor kuş, 

Ne olmuştu acaba? 

Birden uyandı uykusundan; 

Anlamıştı yaptığı hatayı, 

Sarıldı sevgilisinin kollarına

Tekrar uykuya daldı.', 'Suda bir balık, balıkta yara Suda bir balık daha. Karşılaştılar iki balık suda,  Sordu; o yarayı kim verdi sana?  Ne önemi var, geçer dedi b...', ARRAY['Türk Edebiyatı','Şiir','Mahir Kurt']::text[], 8.5, '{"poet":"Mahir Kurt","poet_slug":"mahir-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ruya-72-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bütün', 'butun-mahir-kurt-2nad5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yaşanması lazım bazı şeyler, 

O zaman öğrenilir gerçekler.

Tutmadan elini, elini tuttuğumu düşünmek, 

Kızarmısın bilmiyorum ama sevgi bu olsa gerek.

Konuşmak seninle rüya aleminde, 

Görmek saçlarının dalgalandığını, bu alemin rüzgarlarında.

Dokunmadan saçlarına, saçlarına dokunduğumu düşünmek, 

Kızarmısın bilmiyorum ama sevgi bu olsa gerek.

Sonra bu alemin en güzel yerinde, oturmak seninle, 

İzlemek batan güneşi bu güzel yerde.

Bakmadan gözlerine, gözlerine baktığımı düşünmek, 

Kızarmısın bilmiyorum ama sevgi bu olsa gerek.

Ellerin, saçların ve gözlerin

Tutamamak, dokunamamak ve bakamamak

İsterim hepsi olsun gerçek

Kızarmısın bilmiyorum ama sevgi bu olsa gerek.', 'Yaşanması lazım bazı şeyler,  O zaman öğrenilir gerçekler. Tutmadan elini, elini tuttuğumu düşünmek,  Kızarmısın bilmiyorum ama sevgi bu ols...', ARRAY['Türk Edebiyatı','Şiir','Mahir Kurt']::text[], 8.5, '{"poet":"Mahir Kurt","poet_slug":"mahir-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/butun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öylesine', 'oylesine-fazil-husnu-cakiroglu-gmxsf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Korku dilsiz öfke sagirken, 

Cekip gitmek var öylesine.

Herseyi birakip, 

Uzun bir carsafa dolanip.

Yasanmisliklari yok sayan

Uzakliklara inat.

Öylesine gitmek

Avaz avaz yada dilsiz lal.

Bükemedigin demiri, 

Tutamadigin eli, 

Öpemedigin bebegi, 

Egdim sayip.

Tuttum sayip.

Öptüm sayip.

Cekip gitmek öylesine

Bagíra bagira avaz avaz

Uzun bir carsafa dolanip

Apansiz yola alip, 

Cekip gitmek var ölesiye.

Avaz avaz yada dilsiz lal.', 'Korku dilsiz öfke sagirken,  Cekip gitmek var öylesine. Herseyi birakip,  Uzun bir carsafa dolanip. Yasanmisliklari yok sayan Uzakliklara in...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Çakıroğlu']::text[], 8.5, '{"poet":"Fazıl Hüsnü Çakıroğlu","poet_slug":"fazil-husnu-cakiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/oylesine-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılığa Sitem', 'ayriliga-sitem-riza-gunes-62d39', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir gül kızıllığında sevmek

Ve yaprağın düşüşünde bulmak kendini

Çalmak umutlarını yarınlardan

Bulup sevmelerin ilk tılsımını

Geçen zamana karşı

(Ağrı, Nisan 2002)', 'Bir gül kızıllığında sevmek Ve yaprağın düşüşünde bulmak kendini Çalmak umutlarını yarınlardan Bulup sevmelerin ilk tılsımını Geçen zamana k...', ARRAY['Türk Edebiyatı','Şiir','Rıza Güneş']::text[], 8.5, '{"poet":"Rıza Güneş","poet_slug":"riza-gunes","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ayriliga-sitem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SÖĞÜT DALLARI', 'sogut-dallari-cezmi-cetinel-6yvwm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'SÖĞÜT DALLARI

Bir sonbahar akşamı karsımda söğüt dalları

Üstümde ise yağan yağmur damlaları

Seyrediyorum denizdeki köpüklü dalgaları

Hayal ediyorum senin o dalgalı saçları

Hafif hafif esiyor karşımda sarı saçları

Oysaki seyrettiğim söğüt yaprakları

Kapatmak istiyorum yüreğimde açtığın derin yaraları

Mazide bırakmak isterim bana bıraktığın kötü anıları

Hatırlıyorum bana söylediğin süslü yalanları

Kanıyor hep yüreğim andıkça anıları

Aldırma diyor bana dost olduğum söğüt dalları

Unut gitsin sana yapılan acı anıları ve hatıraları', 'SÖĞÜT DALLARI Bir sonbahar akşamı karsımda söğüt dalları Üstümde ise yağan yağmur damlaları Seyrediyorum denizdeki köpüklü dalgaları Hayal e...', ARRAY['Türk Edebiyatı','Şiir','Cezmi Çetinel']::text[], 8.5, '{"poet":"Cezmi Çetinel","poet_slug":"cezmi-cetinel","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sogut-dallari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günümüzde Savaş*', 'gunumuzde-savas-bayram-tunca-wxums', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Canlılar, ne yuva, ne yavru yaptı

Ekinler başağa gelmeden sarardı

Zaten güller solunca neye yarardı

Irak’ta nice kulun dünyası karardı

Rahmet değil, gözyaşı ıslattı toprağı

Fırat’tan akan su değil kanlı gözyaşı

Dört bir yandan düşman sardı Irak’ı

Şehit düşenler, kolay geçerler sıratı

Böl parçala yut prensibi uygulanıyor

Bizden koparılanlar bir bir yutuluyor

Halklar, demokrasi adına uyutuluyor

Ülkenin zenginlikleri de yok ediliyor

Kalmadı, denenmedik ölümcül silah

Nedense daha gelmedi onlara felah

Akıllı silah akılsızların eline geçince

Masum insanlar hedef oldu binlerce

Yeni silahlara kobay yapıldı insanlar

Yurtsuz yuvasız kaldı binlerce kullar

Gözyaşlarıyla sulandı Irak’ta toprak

Aylarca kanlı aktı Dicle ile Fırat bak

Göktaşı gibi yağdı gökten bombalar

Şehit düştü on binlerce ana/babalar

Viran oldu, sayısız tarihî eser/obalar

Öksüz/yetim kaldı, binlerce çocuklar

Canlı yayında izledik bu çirkin savaşı

İzlerken de her an yaşadık bu savaşı

Rahmet misali suladı toprağı gözyaşı

Toprak oldu nice insanoğlunun naaşı

İğrenir oldum artık şu fani dünyadan

Nereye baksam, her daim akıyor kan

Akan kan, bir yerde daha kurumadan

Bir başka yerde başlıyor akmaya kan

Bu savaş hamur misali çok su götürür

Nice masum ademoğluna köksöktürür

Söz de, özgürlük adına akıtıldı nice kan

Bu vahşet ve dehşete nasıl dayanır can

Bir yanda mazlum insanların gözyaşları

Diğer yanda mağrur insanların salyaları

Bir yanda teknolojiyle donatılmış güçler

Diğer yanda şehadet için mevzilenenler

Arz toz duman, sema kasvet yüklü duman

Bu ne acı ne gözyaşı aman Rabb’im aman

Milyonlarca masum insanın hali ne yaman

Ya Rab masum insanların felahı ne zaman

04.04.2003-19.04', 'Canlılar, ne yuva, ne yavru yaptı Ekinler başağa gelmeden sarardı Zaten güller solunca neye yarardı Irak’ta nice kulun dünyası karardı Rahme...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/gunumuzde-savas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalem', 'kalem-arzu-dincer-n4zuw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Heyecanlar yarattın yüreklerde, 

Kimi ilk kez buluşturduğu için, 

Kalem ile kağıdı, 

Kimi aşk dizelerini döktüğü için

Yürek burukluğu yarattın

Ayrılıklarda, 

Kötü haber ilettiler 

Sözün yetmediği yerde

Kimi kırıldın, 

Düştün ateş misali ocaklara

Kimi dil oldun, 

Dilin dönmediği mevzulara

Kah ağlattın 

Kah güldürdün

Varlığın ile 

Sınırları bitirdin

İnsanoğlunun

Seninle başladı tarihi

Kalem kalem

Sen nelere kadisin...', 'Heyecanlar yarattın yüreklerde,  Kimi ilk kez buluşturduğu için,  Kalem ile kağıdı,  Kimi aşk dizelerini döktüğü için Yürek burukluğu yaratt...', ARRAY['Türk Edebiyatı','Şiir','Arzu Dinçer']::text[], 8.5, '{"poet":"Arzu Dinçer","poet_slug":"arzu-dincer","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kalem-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Düşündüm', 'seni-dusundum-elif-hatice-gencer-eahd2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Andım seni yine bir ah çektim de

Yar dedim, şimdi kim bilir ne halde

Belki bir dostuyla koyu sohbette

Belki de dalmıştır yine derin düşüncelere

Pencereden daldım etrafı seyre

Kar yağarken usulca caddelere, 

Benzeyecek bu şehir beyaz geline

Elde değil işte insan kapılıyor, 

Söz geçmiyor ki deli gönüle, 

Sarılıyor olmayacak hayallere...

Bir mutluluk oyunu oynadığımız seninle, 

Bambaşka bir dünya kurduk kendimizce

Bazen kapılıp coşkun sellere, 

Bazen de küseriz işte öylesine....

Ne gerek var yersiz sitemlere, 

Yaşayalım bu aşkı delicesine.

Bu sevdaya karışamaz hiç kimse

Zaman geçse de, yollar değişse de

Sen hep varolacaksın; 

Gördüğüm en güzel düşte, 

İçinde aşk geçen her sözde, 

Sevgilim diye bahsettiğim her şiirde.', 'Andım seni yine bir ah çektim de Yar dedim, şimdi kim bilir ne halde Belki bir dostuyla koyu sohbette Belki de dalmıştır yine derin düşüncel...', ARRAY['Türk Edebiyatı','Şiir','Elif Hatice Gencer']::text[], 8.5, '{"poet":"Elif Hatice Gencer","poet_slug":"elif-hatice-gencer","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/seni-dusundum-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sitem', 'sitem-elif-hatice-gencer-xtpce', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu akşam daha bir farklısın sanki

Gözlerinde aşkın pırıltısı daha fazla

Özlemin dağ gibi olmuş zirvedesin

Daha sıkı sarılmalıydın bugün bana

Ben sitem etmek isterken sana

Sen yakınır oldun yalnızlıktan yana

Halbuki biz artık yalnız değiliz anlasana! 

İçimizde sevgimiz, günümüz gecemiz bir, 

Konuşmadığımız dakikalar, 

Görüşemediğimiz soğuk akşamlar, 

Anlamsız geliyor önceki yaşamlar.

Seni öpmeye, seni sevmeye doyamazken

Daha sitem etmek inan ki çok erken 

Gönlüm senin, aşkım senin, tenim senin

Bir ben daha olsaydı eğer, benden öte

İnan ki tereddütsüz canım, O da senin....', 'Bu akşam daha bir farklısın sanki Gözlerinde aşkın pırıltısı daha fazla Özlemin dağ gibi olmuş zirvedesin Daha sıkı sarılmalıydın bugün bana...', ARRAY['Türk Edebiyatı','Şiir','Elif Hatice Gencer']::text[], 8.5, '{"poet":"Elif Hatice Gencer","poet_slug":"elif-hatice-gencer","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sitem-52-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin', 'gozlerin-bekir-oguzbasaran-i60mm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerinden giriliyor ülkene

Aklıma en önce gelen gözlerin

Kuş bile kondurtmam kutsal gölgene

Kanayan kalbimi çelen gözlerin

Gözlerin giriyor önce kanıma

Gözlerin veriyor hayat canıma

Gözlerin geliyor gece yanıma

Beni bin parçaya bölen gözlerin

Beni benden alan ceylan bakışın

Sessiz nehir gibi gönle akışın

İliklere kadar ruhu yakışın

İçimden geçeni bilen gözlerin

Can yakmak kâr kalmaz, bunu böyle bil

Adalet önünde el bağla, eğil

Zamana direnmek kolay iş değil

Takvimden yılları silen gözlerin

Yeşil gözlerine dalmak isterim

Yıllarca içinde kalmak isterim

Onun tapusunu almak isterim

Perişan halime gülen gözlerin...

Kayseri,6.4.2002 Cumartesi

BEKİR OĞUZBAŞARAN', 'Gözlerinden giriliyor ülkene Aklıma en önce gelen gözlerin Kuş bile kondurtmam kutsal gölgene Kanayan kalbimi çelen gözlerin Gözlerin giriyo...', ARRAY['Türk Edebiyatı','Şiir','Bekir Oğuzbaşaran']::text[], 8.5, '{"poet":"Bekir Oğuzbaşaran","poet_slug":"bekir-oguzbasaran","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gozlerin-65-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özledim Seni', 'ozledim-seni-elif-hatice-gencer-3oyz1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'BİR SES VERDE BİLEYİM UNUTMADIĞINI, 

NEFESİNİ HALA TENİMDE HİSSEDİYORUM, 

ELLERİN ZATEN DÜNDEN BERİ ELLERİMDE, 

BUSELERİN MÜHÜR OLDU DUDAKLARIMA, 

ÖZLEDİM SENİ, İLİKLERİME KADAR

DIŞARDA SONBAHAR YAĞMURLARI, 

SOĞUK BÜSBÜTÜN SARMIŞ VÜCUDUMU, 

SICAKLIĞIN OLMASA DAYANILMAZ, 

NE BU SOĞUK HAVA, NE DE BU DELİ ŞEHİR, 

AYNAYA BAKTIĞIM VAKİT BANA EMANET VERDİĞİN, 

İÇİMİ ISITAN GÖZLERİNİN BAKIŞINI GÖRÜYORUM, 

SICAK MEVSİMLERDE SÖYLENEN ŞARKILAR GİBİ, 

İSMİNİ HAYKIRIYORUM İÇİME, HER HECESİNİ SÜSLÜYORUM, 

TOZLU KİTAPLAR OLUR YA TAVAN ARASINDA UNUTULMUŞ, 

ÜSTÜNDEKİ TOZLAR ALINIR, PARLATILIR, SAYFA SAYFA OKUNUR, 

İŞTE BEN HER OKUDUĞUM SATIRDA, 

İÇİMDEKİ SENİ YA DA SENDEKİ BENİ BULUR OLDUM, 

BÜYÜK TABLOLARDA GİZLENMİŞ EN GİZLİ RENK, 

BAKTIĞINDA BULAMAYACAĞIN, 

BULDUĞUNDA İFADE EDEMEYECEĞİN BİR RENK, 

YEŞİLİN HUZURUNU, MAVİNİN DERİNLİĞİNİ BULDUĞUM YÜZÜNÜN; 

HER ÇİZGİSİNİ EZBERLEMEK, SENİ KEŞFETMEK İSTİYORUM, 

GÜN BİTİYOR, AKŞAM OLDU, 

ZAMAN AKREPLE YELKOVANI DEĞİL, 

BANA SARILDIĞIN DÜNKÜ BU SAATLERİ GÖSTERİYOR, 

MİNİK BİR KUŞ DEĞİL PENCEREDEKİ, 

BU SES YAKININDAKİ UZAKLIKTAN, 

ÇOŞKUN KALBİMİN DELİ ATIŞLARI, 

BİR ŞARKININ NAKARATINI SÖYLER GİBİ BU AKŞAM, 

SENİ ÖZLÜYORUM DİYORUM, SENİ ÖZLÜYORUM DİYORUM', 'BİR SES VERDE BİLEYİM UNUTMADIĞINI,  NEFESİNİ HALA TENİMDE HİSSEDİYORUM,  ELLERİN ZATEN DÜNDEN BERİ ELLERİMDE,  BUSELERİN MÜHÜR OLDU DUDAKLA...', ARRAY['Türk Edebiyatı','Şiir','Elif Hatice Gencer']::text[], 8.5, '{"poet":"Elif Hatice Gencer","poet_slug":"elif-hatice-gencer","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ozledim-seni-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Sensizken', 'ben-sensizken-i-dris-uygun-ca9jt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gün batımında üstüme çökerken arsız karanlık

bir korku kaplar içmi kaçamam, heryanımı sarar yanlızlık

kipriklerimi titrettiğinde rüzgar, 

Ve yıldızlar düştüğünde bir bir gök yüzüne...

asilerin isyancısı olurum

BEN sensizken öksüzüm...

ben gece olduğunda ölümsüzüm...

BEN hergüneş doğduğunda

özgürlük için VE! ...SENİN için ölürüm

ay ışığına inat yolalırım karanlık ufuklara

yol alırım gözlerimle beraber

özgürlük için, özgürlüğümüz için

her güneş doğuşunda meydan okurum ölümlere', 'gün batımında üstüme çökerken arsız karanlık bir korku kaplar içmi kaçamam, heryanımı sarar yanlızlık kipriklerimi titrettiğinde rüzgar,  Ve...', ARRAY['Türk Edebiyatı','Şiir','İdris Uygun']::text[], 8.5, '{"poet":"İdris Uygun","poet_slug":"i-dris-uygun","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ben-sensizken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anadolum', 'anadolum-yasar-karaman-woqml', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir çoban kavalısın dertlerimi dinleten

Avuç, avuç pınarsın, içimi serinleten, 

Gururumu dağlarından almışım

Dik başlı, geçit vermez

Sendendir yalnızlığım

Kuş uçmaz, kervan geçmez.

Tarihsin, efsanesin

Sevgisin kucak, kucak

Yarın neler olacak

Bekle ey anadolum.', 'Bir çoban kavalısın dertlerimi dinleten Avuç, avuç pınarsın, içimi serinleten,  Gururumu dağlarından almışım Dik başlı, geçit vermez Sendend...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Karaman']::text[], 8.5, '{"poet":"Yaşar Karaman","poet_slug":"yasar-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/anadolum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gül Düştü', 'bir-gul-dustu-bekir-oguzbasaran-y9tnz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bilmiyorum nerde, nasıl

Omuzuma bir gül düştü

Bir ağaçtan usul usul

Omuzuma bir gül düştü

Derinleri kımıldattı

Günüme mutluluk kattı

Dikeni elime battı

Omuzuma bir gül düştü

Rengi kandan kırmızıydı

Doğanın nazlı kızıydı

Yüreğimdeki sızıydı

Omuzuma bir gül düştü 

İncelik derseniz onda

Goncalık derseniz onda

Ecelik derseniz onda

Omuzuma bir gül düştü

Arı ona üşüşmüştü

Bülbüllerle görüşmüştü

Gizli gizli öpüşmüştü

Omuzuma bir gül düştü…', 'Bilmiyorum nerde, nasıl Omuzuma bir gül düştü Bir ağaçtan usul usul Omuzuma bir gül düştü Derinleri kımıldattı Günüme mutluluk kattı Dikeni ...', ARRAY['Türk Edebiyatı','Şiir','Bekir Oğuzbaşaran']::text[], 8.5, '{"poet":"Bekir Oğuzbaşaran","poet_slug":"bekir-oguzbasaran","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bir-gul-dustu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Rüzgarları Anlat', 'bana-ruzgarlari-anlat-yasar-karaman-duc4x', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bana rüzgarları anlat

Karlı dağları koy avuçlarıma

Bir senin pınarlarında diner susuzluğum.

Karanlık gecelerde saçlarımı okşarken

Esmer dizine koyup da başımı

Ancak böyle geçer uykusuzluğum.

Üşürsem üstümü ört, yapraklarınla

Sev beni doğa ana

Ben küçük bir çocuğum.', 'Bana rüzgarları anlat Karlı dağları koy avuçlarıma Bir senin pınarlarında diner susuzluğum. Karanlık gecelerde saçlarımı okşarken Esmer dizi...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Karaman']::text[], 8.5, '{"poet":"Yaşar Karaman","poet_slug":"yasar-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bana-ruzgarlari-anlat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaldı mı Zaman', 'kaldi-mi-zaman-yasar-karaman-9pmbt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Onca yaşanmamış şey

Kaldı mı zaman? 

Solarken resimler gibi her şey

Boşalmış şişelerdir, gerçek o an.

Artık ne ümit, ne arzu, ne de yorum

Yok artık gelecekle ilgili

Mişli geçmişlere içiyorum.', 'Onca yaşanmamış şey Kaldı mı zaman?  Solarken resimler gibi her şey Boşalmış şişelerdir, gerçek o an. Artık ne ümit, ne arzu, ne de yorum Yo...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Karaman']::text[], 8.5, '{"poet":"Yaşar Karaman","poet_slug":"yasar-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kaldi-mi-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrık Otları', 'ayrik-otlari-yasar-karaman-7uotm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Pahalı parfümler nasıl kokar bilirsin

Sevilmiş kadınlar nasıl yürür sokakta

Parıltılı vitrinlere bakakalırım.

Sihirini düşünürken bin yıldır

Güzeller güzeli nazlı orkidenin

Bir yağmur sonrası, bir akşam üstü

Ayağımın dibinde beliriveren

Arsız otlara şaşakalırım.', 'Pahalı parfümler nasıl kokar bilirsin Sevilmiş kadınlar nasıl yürür sokakta Parıltılı vitrinlere bakakalırım. Sihirini düşünürken bin yıldır...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Karaman']::text[], 8.5, '{"poet":"Yaşar Karaman","poet_slug":"yasar-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ayrik-otlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşke', 'keske-yasar-karaman-md725', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çoğu düşünmekten başlayamadım

Kalın kitaplar yüzünden

Ben eskiden

Güzel kadınları

Korkardım sevmekten.

Düşünürdüm, 

Herhalde kızardı biri

Koca, koca kapılardan

küçülür, giremezdim içeri.

Ah keşke, neyi geri getirir

Her şey eskidi işte bu zaman telaşında

Düşündükçe bir sonsuz boşluğa düşüyorum

Ya herşeyi unutsam, yeniden doğsam ya da...', 'Çoğu düşünmekten başlayamadım Kalın kitaplar yüzünden Ben eskiden Güzel kadınları Korkardım sevmekten. Düşünürdüm,  Herhalde kızardı biri Ko...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Karaman']::text[], 8.5, '{"poet":"Yaşar Karaman","poet_slug":"yasar-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/keske-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-sair-orzalam-qneg0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yokken yoktun, 

  sorun yoktu; 

varken yok oldun, 

 sorun doğdu.', 'Yokken yoktun,    sorun yoktu;  varken yok oldun,   sorun doğdu....', ARRAY['Türk Edebiyatı','Şiir','Şair Orzalam']::text[], 8.5, '{"poet":"Şair Orzalam","poet_slug":"sair-orzalam","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sen-241-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siz Ondan Haber verin', 'siz-ondan-haber-verin-yasar-karaman-janhb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Eve ekmek düşünmezdim, 

Çaya şeker, çorbaya tuz

Derbederdim bir zamanlar

Siz yoktunuz.

Ev kurmak da neki

İki gönül bir olunca, 

Bir masa, üç iskemle

Basma perde, kalınca.

Bir de yatak serdik mi

Akşam saatlerinde, serin

Beni seviyor musunuz? 

Siz ondan haber verin.', 'Eve ekmek düşünmezdim,  Çaya şeker, çorbaya tuz Derbederdim bir zamanlar Siz yoktunuz. Ev kurmak da neki İki gönül bir olunca,  Bir masa, üç...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Karaman']::text[], 8.5, '{"poet":"Yaşar Karaman","poet_slug":"yasar-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/siz-ondan-haber-verin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vefa', 'vefa-yasar-karaman-iwo4p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Acını çabuk unuttuk

Meyhane masasında

Vur patlasın, çal oynasın

Orada öyle şey oluyorsa

Kulakların çınlasın.', 'Acını çabuk unuttuk Meyhane masasında Vur patlasın, çal oynasın Orada öyle şey oluyorsa Kulakların çınlasın....', ARRAY['Türk Edebiyatı','Şiir','Yaşar Karaman']::text[], 8.5, '{"poet":"Yaşar Karaman","poet_slug":"yasar-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/vefa-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adamın Biri', 'adamin-biri-yasar-karaman-agaf3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Söyleyecek nesi var? 

Bakıyor ya, görmüyor

Güneşin tam altına oturmuş da adam

Gölgesi içinden geçiyor.', 'Söyleyecek nesi var?  Bakıyor ya, görmüyor Güneşin tam altına oturmuş da adam Gölgesi içinden geçiyor....', ARRAY['Türk Edebiyatı','Şiir','Yaşar Karaman']::text[], 8.5, '{"poet":"Yaşar Karaman","poet_slug":"yasar-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/adamin-biri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günün Birinde', 'gunun-birinde-yasar-karaman-m25xb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir gün ninenin biri, 

Bir masal anlatacaktır

Bayraklar üzerine, savaşlar üzerine

Beyaz, esmer tenli, kızılderili

Çocuklar şaşırıp kalacaktır.', 'Bir gün ninenin biri,  Bir masal anlatacaktır Bayraklar üzerine, savaşlar üzerine Beyaz, esmer tenli, kızılderili Çocuklar şaşırıp kalacaktı...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Karaman']::text[], 8.5, '{"poet":"Yaşar Karaman","poet_slug":"yasar-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gunun-birinde-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-yasar-karaman-nrxtg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Zaman kimseyi beklemedi

İyi korunmuş eşyalardan başka

Eski tanrılar birer, birer öldüler.', 'Zaman kimseyi beklemedi İyi korunmuş eşyalardan başka Eski tanrılar birer, birer öldüler....', ARRAY['Türk Edebiyatı','Şiir','Yaşar Karaman']::text[], 8.5, '{"poet":"Yaşar Karaman","poet_slug":"yasar-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/zaman-64-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meçhul Çağrı', 'mechul-cagri-serdar-tuncer-qpcmq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yüreğim sevdaya açılan gemi

Yolculuk nereye sor sevdiceğim

Yıldızlar altında mahzûn gölgemi

Yaşlı gözlerinle sar sevdiceğim.

Çözümsüz bilmece aşkın esrârı

Çileyle yıkanmak sevenin kârı

Eserse çöllerden vuslat rüzgârı

Kalbini kumlara ser sevdiceğim.

Hicranlar kül eder gönül dağını, 

Yağmur mu öpecek, gül dudağını 

Âşık kelebeğin ölüm ağını

Bir hüzzam besteyle, ör sevdiceğim.

Yanmayı bilince buzlarda duran

Güneşi görünce geceyi saran

Günün her ânında hasreti vuran 

Saati sevgiye kur sevdiceğim.

Vermedin hâtıra yırtık resmini

Gözyaşlarım sustu, nânkör ismini 

Görmek istiyorsan, aşkın cismini

Kalbimi ikiye yar sevdiceğim. 

Aşkım kıvranırken gül pençesinde

Sana serenât var, bülbül sesinde

Hâkim sensin artık aşk celsesinde

Kalemi ortadan, kır sevdiceğim.

Zehiri tadınca küsersin bala 

Bir meçhûl çağrıyla düşersin yola

Sensizliğe mahkûm harâbe kula 

Çaldığın yılları ver sevdiceğim.

(22/07/1997)    Ankara', 'Yüreğim sevdaya açılan gemi Yolculuk nereye sor sevdiceğim Yıldızlar altında mahzûn gölgemi Yaşlı gözlerinle sar sevdiceğim. Çözümsüz bilmec...', ARRAY['Türk Edebiyatı','Şiir','Serdar Tuncer']::text[], 8.5, '{"poet":"Serdar Tuncer","poet_slug":"serdar-tuncer","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/mechul-cagri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin', 'gozlerin-elif-kerenciler-9z1f2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'maviyi sevdim

gördüğüm ve görmediğim 

tüm renkler içinden

dahasının derinliklerine inmeden

vazgeçtim hepsinden

maviyi seçtim

ama seçimsiz kaldığım için değil

gözlerindi, 

sendin mavi...

maviyi  hep sevdim

7 nisan 2003

Biga

11: 00', 'maviyi sevdim gördüğüm ve görmediğim  tüm renkler içinden dahasının derinliklerine inmeden vazgeçtim hepsinden maviyi seçtim ama seçimsiz ka...', ARRAY['Türk Edebiyatı','Şiir','Elif Kerenciler']::text[], 8.5, '{"poet":"Elif Kerenciler","poet_slug":"elif-kerenciler","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gozlerin-66-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş Kulesi', 'dus-kulesi-petek-isik-3kdam', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kahraman şövalyeler yarattık kendimize

Birbirine değen sıcak dost eller düşledik

Yüreğimizi ısıtan bir gülüşü özledik

Sonra; 

Kara yeller kopardı sığınağımızdan

Düş kulemizin penceresinden düşerken

Acılar kanatsız bıraktı bizi.

Çakıldık toprağa bir taş gibi

Öldük hayallerimiz gibi.

                                     (Ayvalık-Mayıs 2000)', 'Kahraman şövalyeler yarattık kendimize Birbirine değen sıcak dost eller düşledik Yüreğimizi ısıtan bir gülüşü özledik Sonra;  Kara yeller ko...', ARRAY['Türk Edebiyatı','Şiir','Petek Işık']::text[], 8.5, '{"poet":"Petek Işık","poet_slug":"petek-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/dus-kulesi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkı Yaşamak İçin', 'aski-yasamak-i-cin-bayram-tunca-g22cl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Senelerce hülyalarımda konuk ettim

Kavuşmak için koşucu gibi seğirttim

Aşk ateşiyle yanan, ne ilk/ne tektim

Ah bi bilseniz, aşktan ne çok çektim

Bazen gecemden gündüzüme kattım

Bazen gündüzümden geceme kattım 

Aşkı doymak için durmadan çalıştım

Ama aşktan yana da karaydı bahtım

B. Tunca/06.04.2003-16.04', 'Senelerce hülyalarımda konuk ettim Kavuşmak için koşucu gibi seğirttim Aşk ateşiyle yanan, ne ilk/ne tektim Ah bi bilseniz, aşktan ne çok çe...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/aski-yasamak-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÜMİT', 'umi-t-mehmet-ali-cibikli-491b6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Neden bu sitemler, bu surat niçin? 

Varsa bir nedeni, ben de bileyim.

Koşarak gelmiştim, ben senin için, 

''Öl'' de uğrunda ben, hemen öleyim.

Neden bu davranış, neden bu sitem? 

Birer yabancıyız, sanki ikimiz.

Bir bilmece sanki, nedendir bilmem, 

Hani nerde kaldı, bitmez sevgimiz? 

Sıkıntılar seni, boğmasın böyle, 

Anlat ki derdine, çare bulayım.

Derdine çareyim, derdini söyle, 

Senin dertlerine, derman olayım.

Yeter ki üzülme, üzme gönlünü, 

Yüzünden dökülmüş, bin parça keder.

Derdine dermanım, dinle sözümü, 

Yüzün gülsün artık, bu bana yeter.

''Sevgilim'' de bana, ''seviyorum'' de, 

Mutlu kıl dünyamı, karanlık gitsin.

Sen iste yeter ki, severim ben de, 

Karanlık dünyamda, sen bir ümitsin.', 'Neden bu sitemler, bu surat niçin?  Varsa bir nedeni, ben de bileyim. Koşarak gelmiştim, ben senin için,  ''Öl'' de uğrunda ben, hemen öleyim....', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Çıbıklı']::text[], 8.5, '{"poet":"Mehmet Ali Çıbıklı","poet_slug":"mehmet-ali-cibikli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/umit-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin', 'gozlerin-osman-i-nci-2kgxg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Benliğimi alıp ta, götürür uzaklara, 

Düşürür beni, bilmediğim tuzaklara, 

Boyun eğmez, bu saçma yasaklara, 

Kalbimi delen, bir oktur gözlerin...

Ne baharı-yazı bilir, nede hazanı, 

Tanımaz buyruğu, ferman yazanı, 

Kafası bozulunca, kaldırır kazanı, 

İçerimi sızlatan, hançer gözlerin...

Öyle bir bakar ki, derin mi derin, 

Yıldızları ona, karanfil diye verin, 

Getirin kardelenleri, yoluna serin, 

Kanımı kaynatan, güneş gözlerin...

Anlatamam onu, hiçbir kelime ile, 

Çirkin kalır yanında, Afrodit bile, 

En basit sözler olsun, zor gelir dile, 

Dilimi bağlayan, büyülü gözlerin...', 'Benliğimi alıp ta, götürür uzaklara,  Düşürür beni, bilmediğim tuzaklara,  Boyun eğmez, bu saçma yasaklara,  Kalbimi delen, bir oktur gözler...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gozlerin-67-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahtım', 'bahtim-osman-i-nci-ieocr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sözlüğe baktım, 

Yazmıyor seni, 

Telefon rehberinde, 

Adın yok...

Sordum soruşturdum, 

Bilen çıkmadı, 

Ne tanıyan var, 

Nede gören...

Nasıl bulurum seni, 

Bilemiyorum...', 'Sözlüğe baktım,  Yazmıyor seni,  Telefon rehberinde,  Adın yok... Sordum soruşturdum,  Bilen çıkmadı,  Ne tanıyan var,  Nede gören... Nasıl ...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bahtim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hadi Gari', 'hadi-gari-mehmet-ali-cibikli-g26zx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Rüyalarımda bile, 

Bana düşman gibisin.

Ve beni sevdiğine, 

Sanki pişman gibisin.

''Beni benimle böyle, 

Bırakma sakın'' dedim.

Sensiz kaldım bu yerde, 

Her gün kafayı yedim.

Çıkmadın telefona, 

Sesini duyamadım.

Ömür boyu hayatta, 

Ben sana doyamadım.

Her an seni düşünüp, 

Hep seni hayalledim.

Yoksun diye üzülüp, 

Yollarını gözledim.

Sen seni sevmiyorsan, 

Beni sev biraz bari.

Mutluluk istiyorsan, 

Bana gel hadi gari.', 'Rüyalarımda bile,  Bana düşman gibisin. Ve beni sevdiğine,  Sanki pişman gibisin. ''Beni benimle böyle,  Bırakma sakın'' dedim. Sensiz kaldım ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Çıbıklı']::text[], 8.5, '{"poet":"Mehmet Ali Çıbıklı","poet_slug":"mehmet-ali-cibikli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hadi-gari-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sultan', 'sultan-mehmet-ali-cibikli-qsgm8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaşamak istiyorsan, 

Mutluluğu benimle.

Gururunu bırak sen, 

Duygularını dinle.

Gel gidelim birlikte, 

Uzaklara kaçalım.

Bilinmeyen bir yerde, 

Aşka kucak açalım.

Sevda tohumlarını, 

Ekelim birer birer.

Yeşeren fidanları, 

Tüm dostlarımız sever.

Aşkları, sevdaları, 

Sevgiyle yoğuralım.

Özlenen umutları, 

Birlikte doğuralım.

Karşılıklı sevelim, 

Doya doya biz bizi.

Dost düşman demeyelim, 

Bilsinler sevgimizi.

Bilinmeyen bir yerde, 

Herkes bizi tanısın.

Bütün ümitler sende, 

Gönlümün sultanısın.', 'Yaşamak istiyorsan,  Mutluluğu benimle. Gururunu bırak sen,  Duygularını dinle. Gel gidelim birlikte,  Uzaklara kaçalım. Bilinmeyen bir yerd...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Çıbıklı']::text[], 8.5, '{"poet":"Mehmet Ali Çıbıklı","poet_slug":"mehmet-ali-cibikli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sultan-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Çölleri', 'sevda-colleri-mehmet-ali-cibikli-6qmcf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben sevmekten vazgeçtim, 

Seni sevmek boşuna.

Sana sevgim kalmadı, 

Gitmese de hoşuna.

Beni benimle bırak, 

Kendimle dertleşeyim.

Dertlerimin içinde, 

Kaybolmuş bir neşeyim.

Sildim anılarımı, 

Kafamdan birer birer.

Kolay olmadı ama, 

Rahatladım bu sefer.

Bu sevdanın çölleri, 

Bana arkadaş oldu.

Sevemedim gülleri, 

Ulaşamadım, soldu.', 'Ben sevmekten vazgeçtim,  Seni sevmek boşuna. Sana sevgim kalmadı,  Gitmese de hoşuna. Beni benimle bırak,  Kendimle dertleşeyim. Dertlerimi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Çıbıklı']::text[], 8.5, '{"poet":"Mehmet Ali Çıbıklı","poet_slug":"mehmet-ali-cibikli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevda-colleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YUNUS', 'yunus-gunes-yagmur-smi8s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerin, bu gözler koca bir ömre bedeller

Alamıyorum gözlerimi gözlerinden fotoğrafta bile olsa

Masmavi bir denizde yüzüyor gibiyim bakarken

Zalim dalgalarla boğuşurcasına

İşi hoplayıp zıplamak olan bir yunus gördüm o denizde

Şimdi ağlıyor, hoplamak zıplamaktan bıkmışçasına

İstemiyor artık eğlenmek, belli ki yorulmuş

Masmavi sulara gömülmek istiyor belki de kim bilir?', 'Gözlerin, bu gözler koca bir ömre bedeller Alamıyorum gözlerimi gözlerinden fotoğrafta bile olsa Masmavi bir denizde yüzüyor gibiyim bakarke...', ARRAY['Türk Edebiyatı','Şiir','Güneş Yağmur']::text[], 8.5, '{"poet":"Güneş Yağmur","poet_slug":"gunes-yagmur","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yunus-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-mehmet-ali-cibikli-lse49', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben sevginden üşüdüm, 

Ateşin hiç yakmıyor.

Ağlamaktan tükendi, 

Gözyaşlarım akmıyor.

Acı nedir bilmezdim, 

Sen tattırdın acıyı.

İçimde aşk sancısı, 

Dindirmedin sancıyı.

Bilsen aşk yarasını, 

Ne derindir ne derin.

Ben sana tutsak oldum, 

Esir etti gözlerin.

Gözlerine bakınca, 

Rüyalara dalmışım.

Sanki ıssız bir çölde, 

Yapayalnız kalmışım.

Bakışların olmasa, 

Seni sevmem mümkün mü? 

Ümitlerim kaybolsa, 

Sana gelmem mümkün mü? 

Hatıramda sen varsın, 

Hayalimde yine sen.

Benim için baharsın, 

Gönlümde hiç bitmeyen.', 'Ben sevginden üşüdüm,  Ateşin hiç yakmıyor. Ağlamaktan tükendi,  Gözyaşlarım akmıyor. Acı nedir bilmezdim,  Sen tattırdın acıyı. İçimde aşk ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Çıbıklı']::text[], 8.5, '{"poet":"Mehmet Ali Çıbıklı","poet_slug":"mehmet-ali-cibikli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sen-242-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Irakta Cocuklar Ciglik Atarken', 'irakta-cocuklar-ciglik-atarken-guner-kaymak-eqccv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Irakta cocuklar ciglik atarken

Sinsi sinsi siritiyor bu iblis

Irakli bacim yerde baygin yatarken

gurur duyup siritiyor bu iblis

Alay ediyorlar muslumanin haline

Dolamislar demokrasiyi diline

Sadik namussuzlar inancina dinine

Sinsi sinsi siritiyor bu iblis

Gozu donmus cani kana doymuyor

Yillanmis kinini iraklidan aliyor

Araplari bolup parca parca vuruyor

Sinsi sinsi siritiyor bu iblis

Nerde kemik orda yerin aliyor

Yoksul Somalide bile gozu kaliyor

Sirplar kendi irkinda pek aldirmiyor

Sinsi sinsi siritiyor bu iblis

Bu iblis dunyayi hice sayiyor

Kararini vermis kimseye danismiyor

Cekinmiyor araptan birseye saymiyor

Sinsi sinsi siritiyor bu iblis

Filistinli kan kusarken gormuyor

Yahudiden tek kelime sormuyor

Babasindan hicte geri kalmiyor

Sinsi sinsi siritiyor bu iblis

Her cesit silahi irakta denedi

Kadin yasli cocuk ayirt etmedi

Yakti yikti zalim yazik demedi

Sinsi sinsi siritiyor bi iblis

Tabiata bile zulum eyledi

Hayvanlarin dahi neslini tuketti

Boyle iblisi yeryuzu hic gormedi

Sinsi sinsi siritiyor bu iblis

Ozan Guner derki gozyasim dinmez

Nasil gozki iraktaki vahseti gormez

Ne malum Irana Suriyeye sira gelmez

Sinsi sinsi siritiyor bu iblis

Amsterdam/7.4.2003', 'Irakta cocuklar ciglik atarken Sinsi sinsi siritiyor bu iblis Irakli bacim yerde baygin yatarken gurur duyup siritiyor bu iblis Alay ediyorl...', ARRAY['Türk Edebiyatı','Şiir','Güner Kaymak']::text[], 8.5, '{"poet":"Güner Kaymak","poet_slug":"guner-kaymak","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/irakta-cocuklar-ciglik-atarken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'hani', 'hani-ali-gencay-lsaji', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'hani bir yanım siyahtı ya

hani beyaz onu tamamlardı ya

hani derin derin nefes alışlar vardı ya

hani dalıp gitmeler

hani suskunluk da duymalar

hani elif vardı ya

hani be si benimdim

hani korkuları vardı çocukça

hani hayalleri tavana asılmış

hani uykusuz geçen o güzel geceler

hani zümrütdü o

hani denizde acemi balık

hani nerde o sarı odalar

hani nerdesin...', 'hani bir yanım siyahtı ya hani beyaz onu tamamlardı ya hani derin derin nefes alışlar vardı ya hani dalıp gitmeler hani suskunluk da duymala...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hani-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'azad ediyorum', 'azad-ediyorum-ali-gencay-0nt5s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'son  sıcakları mevsimin

hunharca esen bir yel

savrulan sarı yapraklar

kah savrulur

kah sürünür

bu son sevdası gönlümün

hunharca geçen bunca yıllar

kah sever kah ayrılır

son mısrası bu ilhamımın

hunharca yazan kalem

kah titrer

kah kırılır

azad ediyorum düşlerimi

savrulduğu yerde

azad ediyorum kalbimi

tükendiği yerde

azad ediyorum kalemimi

kırıldığı yerde 

a.gencay', 'son  sıcakları mevsimin hunharca esen bir yel savrulan sarı yapraklar kah savrulur kah sürünür bu son sevdası gönlümün hunharca geçen bunca ...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/azad-ediyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'bana', 'bana-ali-gencay-euuu0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'aşkın resmini çizeyim

rengini sen ver bana

uzaklara gideyim

ellerini ver bana

sana söyleyeceklerim var

kulaklarını ver bana

kuruyan dudaklarım var

dudaklarını ver bana

yıldızlar fal tutsun

hayallerini ver bana

gezeyim düşlerinde bir peri ol

sihrini ver bana

halen bilmiyorum nerde olduğunu

gelmek için sana

yollarını ver bana

bir bahçe kurayım

çiçeklerini ver bana

kokunu içime çekeyim

nefesini ver bana

öle yorgun ki tenim

öle halsiz

duanı ver bana

beni sende buldum

seni ver bana

...

a.gençay 7.4.03', 'aşkın resmini çizeyim rengini sen ver bana uzaklara gideyim ellerini ver bana sana söyleyeceklerim var kulaklarını ver bana kuruyan dudaklar...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bana-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'fikrin', 'fikrin-ali-gencay-rq1w0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'dün gece yine 

gözlerimi tavana diktim

elimde sigaram

dilimde Ahmet kaya''dan kalma

bir kaç mısra

bil ki senin fikrin

yüreğimde...

''''akşam olur ay gecede

çiğdem çiçek şenlenir

vallah düşünmesem seni

derdime dert eklenir, , 

dalıp gidiyorsam, 

ellerim buz kesiyorsa, 

gözlerimi dikmişsem kirişlere, 

yağmura rağmen dudaklarım kuruyorsa, 

ansızın ellerim saçlarımdaysa, 

bil ki senin fikrin 

yüreğimde...

şimdi perdemi sıyırıp

ay ışığını izliyorum geceye inat

öle ışıtıyor ki yeryüzünü

hani diyorum ki

kalabalığa inat

bil ki sensin tek

yüreğimde...

seni özlememek mümkün mü

gelmeyeceğini bilerek

yolarına bakmamak mümkün mü

gözleri kapayıp hayelere dalmak

göz kapaklarını kaldırmak mümkün mü

özlem

hasret

hayal

bil ki senin fikrin

yüreğimde...              aligencay 25/03/2003', 'dün gece yine  gözlerimi tavana diktim elimde sigaram dilimde Ahmet kaya''dan kalma bir kaç mısra bil ki senin fikrin yüreğimde... ''''akşam ol...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/fikrin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'hayallerim', 'hayallerim-ali-gencay-s9vvl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yaşanacakları art arda koysam

yaşadıklarımla karşılasam

sonra derin bir iç çekip

sigara dumanına yazsam

bir de asıp suçlarımı

kodes yerine kalbime gömsem

tek isteğim

duyulmak ağzımı açmadan

haykırmadan

ellerim kaleme varmadan

yazsa tüm şairler mısralarımı

acı çekmeden yaşasa sevdamı aşıklar

bir dağ gibi

büyütsem yükseklerde umutları

sonra

sen bir ürkek ceylan olsan

durup öylece

dinlesen beni

yıldız kayarken eteklerime

seni saklasam sinemde

bir karanfil açsa

koklasam koklasam

sabaha ermese gece

ceylan ürkmeden yaşasa sevdamı

işte bu hayallerim

dağ şair 

sinesi mısra 

hayali ceylan 

ve karanfil

...

a.gençay 7.4.03', 'yaşanacakları art arda koysam yaşadıklarımla karşılasam sonra derin bir iç çekip sigara dumanına yazsam bir de asıp suçlarımı kodes yerine k...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/hayallerim-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'herşeye inat', 'herseye-inat-ali-gencay-1jbi1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'güneşe bakıyorum gözlerimi kırpmadan

ayaklarım çıplak yürüyorum

buz kesmiş kaldırımlarda

hiç bir korku yüklenmeden

geceye dalıyorum

bir çocuk ürpertisiyle

şarkılar söylüyorum

adımlarımı

sertçe vuruyorum taşlara

acıyı hissedercesine

sokak lambalarını sayıyorum

uyumak istercesine

ay gök yüzünü arşınlamış 

kaçarcasına

bense onu bekliyorum

dönecekmişçesine

sonra biri sesleniyor ardımdan 

dönüp bakamıyorum

duruyorum

işte o an

topuklarım kanıyor

sokak lambaları sönüyor

şarkının sonu aklıma gelmiyor

sonra dönüp bakıyorum

tüm korkularımı

silkinip bırakıyorum kaldırımlara

loş bir sokakta elinde bir karanfil

kokusu burnumda

yaklaşmak istediğim kadar yakınsın

uzansa da ellerim

dokunamıyorum yakınlığına

ah diyorum

neden döndüm

neden karardı sokak lambaları

neden acıyor topuklarım

koşmak isterken çakılmak kaldırıma

görmek isterken  sitemim lambalara

sonra ellerini uzatıyorsun bana

dokunuyorsun imkansızcasına

sıcaklığın avuçlarımda

sonra gözlerin karanlığa inat

sabahım oluyorsun geceye inat

seni seviyorum diyorsun yalnızlığa inat

sen osun işte

adımlanan 

kanayan 

sönen 

her şeye 

inat

... a.gençay 7.4.03', 'güneşe bakıyorum gözlerimi kırpmadan ayaklarım çıplak yürüyorum buz kesmiş kaldırımlarda hiç bir korku yüklenmeden geceye dalıyorum bir çocu...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/herseye-inat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'istanbul', 'istanbul-ali-gencay-6mpfw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İstanbul’u hiç yaşamadım

hele İstanbul’da hiç..

sevdayı yedi tepesine yaydım 

yalnızlığımı kız kulesine

''istanbul''da sonbahar

kız kulesi ve adalar, 

bu benim 

benim bu 

yaşananlar

gönlümü yediye böldüm

hertepesine beni gömdüm

haliç''de kızıl bir akşam

Yedikule zindanı göğsüm

Istanbul’u hiç yaşamadım

hele ıstanbul’da hiç..

sevdayı yedi tepesine yaydım 

yalnızlığımı kız kulesine a.gençay', 'İstanbul’u hiç yaşamadım hele İstanbul’da hiç.. sevdayı yedi tepesine yaydım  yalnızlığımı kız kulesine ''istanbul''da sonbahar kız kulesi ve ...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/istanbul-78-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'seni düşünüyorum', 'seni-dusunuyorum-ali-gencay-u0qwy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'seni düşlüyorum falezlerin kıyısında

yüzün güneşe dönük

sırtın hayata

saçların dalgalanmıyor

gözün yeşil bakmıyor

bahar yağmurları gibi yağıyor

hüzün gözlerinden

seni düşünüyorum falezlerin kıyısınsa

bana dönüp bakmıyorsun

sesleniyorum

nafile

kulağında denizin fısltısı

gözlerinde ayışığından kalma 

yakamoz parılıtısı

seni seyrediyorum falezlerin kıyısında

çıkıp gelmişsin romanlardan

boğuyorsun batan güneşi

saçlarının kızıllığı ile

ve gözlerinde

yüzyılardan kalma 

mermer heykeler gibi

ağlıyorsun....

a.gencay', 'seni düşlüyorum falezlerin kıyısında yüzün güneşe dönük sırtın hayata saçların dalgalanmıyor gözün yeşil bakmıyor bahar yağmurları gibi yağı...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/seni-dusunuyorum-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'sen ben', 'sen-ben-ali-gencay-tu7ef', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen ve ben

biz hüznü geceden aldık

yalnızlığı yıldızlardan çaldık

yaşamak deyince

masallar yazdık

ölüm değince 

ayrılıklar

biz sevdayı efsanelerle yaşadık

ölümü hançerledik yüreğimizde

neden  yazıyoruz diye çok düşündüm

sebebi: 

kalemimizi dört nala koşturmak

cesurca bir iş

fakat beceremiyoruz sözcükleri

bir araya getirip konuşmayı

kelimelerimiz cesurca

 yalın

keskin bir kılıç

ama sözcüklerimiz

korkak..

 ürkek...

a.gencay   

 21/03/2003', 'Sen ve ben biz hüznü geceden aldık yalnızlığı yıldızlardan çaldık yaşamak deyince masallar yazdık ölüm değince  ayrılıklar biz sevdayı efsan...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sen-ben-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pul Biber', 'pul-biber-refik-recep-pelit-3ub97', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Midemde bir sızı derlerki buna sebep pulbiber

Pul bibersiz bir hayat olurmu acep muteber, 

Kalp acısını unutturur biran da ezer geçer, 

Pulbibersiz bir hayat bilki ölümden beter.', 'Midemde bir sızı derlerki buna sebep pulbiber Pul bibersiz bir hayat olurmu acep muteber,  Kalp acısını unutturur biran da ezer geçer,  Pulb...', ARRAY['Türk Edebiyatı','Şiir','Refik Recep Pelit']::text[], 8.5, '{"poet":"Refik Recep Pelit","poet_slug":"refik-recep-pelit","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/pul-biber-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çölde Gece', 'colde-gece-ozgur-hatem-37tro', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ay çocukların

	gözlerinde 

	          büyüyor; 

Korku, 

yarım uykularda...

Yolda  kervan 

Göç 

      Göçük 

               Gömük 

Çölde postal izi 

	“made in” yeni dünya 

Kandan kınalanmış taşların yazgısı 

Orada yıkılan 

Hep birlikte altında kaldığımız devran. 

(Size  kurşun   değmedi mi? 

Ya   şarapnel

alevden rüzgar yalamadı mı yüzünüzü?) 

Çölde gece

İstasyondaydım. 

Vagonların birinde yüreğim, 

diğerinde ağrım kaldı. 

Gök gürültüsünde ahım... 

Ay çöldeydi

	 utandı 

Cansız çocukların 

Kapalı  gözlerine saklandı. 

Sesimi koparamadım kendimden. 

İmgelerim eksik gedik 

Çölün gecesine ay doğmuş 

Küsmüş başka dağlara. 

Çöldeydim. 

Ay gecenin yüreğinde 

(Elimi kuma kaptırdım 

Ağrımı rüzgara) 

Düşüme uçan kuşların, 

Irağımdan taşıdığı fırtına. 

 (Mersin 06.04.2003)', 'Ay çocukların 	gözlerinde  	          büyüyor;  Korku,  yarım uykularda... Yolda  kervan  Göç        Göçük                 Gömük  Çölde post...', ARRAY['Türk Edebiyatı','Şiir','Özgür Hatem']::text[], 8.5, '{"poet":"Özgür Hatem","poet_slug":"ozgur-hatem","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/colde-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklenen Ses', 'beklenen-ses-i-smail-kirgil-ih7fn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bırak bu süslü lafları! 

Biraz da insanlardan bahset

Odunsuz kömürsüz kara kışları

Sabırla geçirenlerden bahset

Yıldızlar parlaktır herkes bilir

Perşembe''den sonra günlerden Cuma gelir

Her Cuma garipler cami önlerinde birikir

El açıp ta dilenenlerden bahset

Tepeden bakarken yeşil ağaçlar baharda

Kışın yaprak dökmüş çıplak ağaçlardan bahset

Lalesi karanfili elüstünde tutulurken dükkanlarda

savunmasız tepelenen çimenlerden bahset

Her söz söyleyeni asmak mı gerek

Her doğru diyeni kovmak mı gerek

Bir inanç uğruna ölüme gülerek

Başı dimdik gidenlerden bahset! 

                                     (27,03,2003 balıkesir)', 'Bırak bu süslü lafları!  Biraz da insanlardan bahset Odunsuz kömürsüz kara kışları Sabırla geçirenlerden bahset Yıldızlar parlaktır herkes b...', ARRAY['Türk Edebiyatı','Şiir','İsmail Kırgıl']::text[], 8.5, '{"poet":"İsmail Kırgıl","poet_slug":"i-smail-kirgil","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/beklenen-ses-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar Geldi', 'bahar-geldi-i-smail-kirgil-jwn7c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir dileğin vardı

İşte oldu

Bahar diyordun

İşte geldi...

Kapında bekliyor şimdi

Aç ta girsin içeri

Çiçek kokularıyla karışık

Bir bahar esintisi

Duyuyormusun bak! 

Ilık bir yağmur yağıyor

Ya çocukların sesini? 

Neşe içinde koşuşuyor...

Şurda yıkık bir ev vardı

Hergün kavga çıkardı

Bir de ayyaşın teki

Hergün nara atardı...

                   (08,03,2003 balıkesir)', 'Bir dileğin vardı İşte oldu Bahar diyordun İşte geldi... Kapında bekliyor şimdi Aç ta girsin içeri Çiçek kokularıyla karışık Bir bahar esint...', ARRAY['Türk Edebiyatı','Şiir','İsmail Kırgıl']::text[], 8.5, '{"poet":"İsmail Kırgıl","poet_slug":"i-smail-kirgil","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bahar-geldi-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şairlerin Tersanesi İstanbul', 'sairlerin-tersanesi-i-stanbul-turgay-akbulut-0okkb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İstanbul dan geçiyorum

Sıra sıra ışıklar

Işıklar arsında Otobüs, asvaltı yalar

Atıyorsun sırtından, 

Ne çabuk geçtik Tarabya dan, Boğaz dan

Sana yapılmış vefasız otobanlar

Hey kaptan! Biraz yavaş

Geçemezsin öyle hoyratça, İstanbul dan

Burada yarım kalmış sevdalar, 

Ölümsüz aşklar var

En güzel şarkılar burada yazıldı

En büyük aşklar burada yaşandı

Bütün özlemlerde, bütün ayrılıklarda, 

Bütün umutlarda, 

Onun adı var

Hala sokaklarında, Orhan Veli

Adalarında, Sait Faik yaşar

Bu şehir sevdalıların şantiyesi, 

Şairlerin tersanesi

En güzel hatıralar, en güzel şiirler

Burada inşa edildi

Geçemezsin öyle hoyratça, İstanbul dan

Burada gençliğimin hatırası var

İstanbul dan geçiyorum

İçinde Sen var

İçimde Sen vardın...

Yüreğim sızlar

Boynuna dolanmış altın sarısı ışıklar

Işıklar arasında, anılar 

El sallar..........

(mart 2003)', 'İstanbul dan geçiyorum Sıra sıra ışıklar Işıklar arsında Otobüs, asvaltı yalar Atıyorsun sırtından,  Ne çabuk geçtik Tarabya dan, Boğaz dan ...', ARRAY['Türk Edebiyatı','Şiir','Turgay Akbulut']::text[], 8.5, '{"poet":"Turgay Akbulut","poet_slug":"turgay-akbulut","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/sairlerin-tersanesi-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'bilmesende', 'bilmesende-tayfun-kasapoglu-fyccq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'küçük sevdalardan 

değil sadece ellerinin

vazgeçip

geldim

beni sevdiğini bile bile

kendime yalan söyledim

cesaret edemediğimden

hem sana hemde

kendime zehir ettim, 

işte bak kabulde 

ettim

dön deseydin

şimşek gibi

belki dolunay gibi

düşecektim

kimsenin tutmadığı

yıldız gözlerini

vede bütün haliyle hatırımda

olan ellerini öpecektim...

yanlışı mı

seçtin

beni viraneye döndürüp

adını sildin

bu şiirde değil

gerçekte

binlerce kez geberdim

ve sen, 

bende yaşayacaksın bilmeden

bilinmeden

gözlerini

vede hançerini emanetten

almıyorum

bilmeni isterim', 'küçük sevdalardan  değil sadece ellerinin vazgeçip geldim beni sevdiğini bile bile kendime yalan söyledim cesaret edemediğimden hem sana hem...', ARRAY['Türk Edebiyatı','Şiir','Tayfun Kasapoğlu']::text[], 8.5, '{"poet":"Tayfun Kasapoğlu","poet_slug":"tayfun-kasapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/bilmesende-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Biraz Sevsen?', 'beni-biraz-sevsen-i-smail-kirgil-rkfs0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Unutmaya çalışma hisset biraz

Hele bir düşün

Senin için nelerden vazgeçti

Bu fedakar insan...

Önce uykusuz kaldı çok zaman

Sonra katlandı çocuksu nazına

Ve yaşamın tadına

Varamadı doyasıya...

Ölesiye sevdi seni

Çölde ölümü bekleyen

Yarı kurumuş

Yarı canlı bir ağaç gibi...

Bu aşkın ıstırabını bile bile

Göre göre sevdi seni...

Ve şimdi boynunda halat

Can çekişiyor

Seni düşündükçe.

Gözleri donuk

Hali berbat! 

Ölüm

İki eliyle tutmuş yakasından

Konuşamayan dillerinde SEN

Ah! diyor

Ah...! gelsen

Beni biraz sevsen....

          (06,04,2003  balıkesir)', 'Unutmaya çalışma hisset biraz Hele bir düşün Senin için nelerden vazgeçti Bu fedakar insan... Önce uykusuz kaldı çok zaman Sonra katlandı ço...', ARRAY['Türk Edebiyatı','Şiir','İsmail Kırgıl']::text[], 8.5, '{"poet":"İsmail Kırgıl","poet_slug":"i-smail-kirgil","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/beni-biraz-sevsen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
