INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GidiyoruM', 'gidiyorum-tayfun-kasapoglu-gco2m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'şimdi gidiyorum

belki seni bir pusuda

bekleyerek 

aklının alamayacağı

tuhaf bir yolculuğa gidiyorum

bana senli hatıraları bırakıp

gülüşünü yüreğime hapsedip

sensiz geçen 

zamanları parçalayıp

gidiyorum

düşüncelerimi 

bu şiirde bırakarak 

belki yana yana

belkide kendime 

gelmeyi beceremeden 

gidiyorum

bilmiyorum 

ne hayatın anlamsızlığını 

ne de minik ellerini 

kazımaya çalışıyorum aklımdan sanki

sen korkup kaçarken 

bende seni bitirmeye 

and içiyorum.....

boşuna bir sevdayı

kovalıyorum

ve zamansız gelen

rüyaları

zor oluyor be

sen yokken bu şehir

helede bakışların yoksa

kuruyan bir yaprak gibi

yavaş yavaş düşüyorum

belkide 

irtifa kaybediyorum 

gözlerinden

ama ne olursa olsun 

bir şarjörle 

dağıtarak sensizliği

bela gibi gözlerinden 

müthiş bir şekilde kaçıyorum 

belkide 

bu şehirden gidiyorum

               ''''bu şiir giden bir sevgiliye ağıttır''''', 'şimdi gidiyorum belki seni bir pusuda bekleyerek  aklının alamayacağı tuhaf bir yolculuğa gidiyorum bana senli hatıraları bırakıp gülüşünü y...', ARRAY['Türk Edebiyatı','Şiir','Tayfun Kasapoğlu']::text[], 8.5, '{"poet":"Tayfun Kasapoğlu","poet_slug":"tayfun-kasapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/gidiyorum-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HASRETİM SANA', 'hasreti-m-sana-asik-ahmet-zci7w', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hasretim sana bitanem

Yuvasından ayrılmış kartal gibi

Eşini arayan ceylan gibi

Hasretim sana...

Gurbette seni arıyorum

Daima seni düşünüyorum

Çok ama çok özlüyorum

Hasretimi anlatamıyorum sana

Bazı duygular anlatılmıyor

Sadece yaşadığın zaman anlaşılıyor

Yanında olamıyorum

Sevgimi, duygularımı, hislerimi

Hiçbişey gösteremiyorum sana

Sana olan hasretim

İçimde akan bir volkan gibi

Eritiyor zamanla yavaş yavaş

Sana olan hasretim

Korkutuyor beni

Hayattan korkutuyor

Sana olan hasretim

Sana olan sevgimi, aşkımı

Tüm duygularımı zirveye taşıyor

Sana olan hasretim

Hayata bağlıyor beni 

Zor olan o hayata

Yaşanması zorunlu o hayata

Dertleri, sıkıntısıyla

İstekleri, tutkuları, gerçekleriyle

Herşeyiyle var olan HAYATA BAĞLIYOR...', 'Hasretim sana bitanem Yuvasından ayrılmış kartal gibi Eşini arayan ceylan gibi Hasretim sana... Gurbette seni arıyorum Daima seni düşünüyoru...', ARRAY['Türk Edebiyatı','Şiir','Aşık Ahmet']::text[], 8.5, '{"poet":"Aşık Ahmet","poet_slug":"asik-ahmet","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/hasretim-sana-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SEN', 'sen-gokcegul-ozbek-t3chl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her yerde hayaller konuşur sen gidince 

İçime hasretin düşer

Laflarım, sözlerim seni arar

Adını ezbere bilir rehberim

Lahzaları ararım içinde sen olan', 'Her yerde hayaller konuşur sen gidince  İçime hasretin düşer Laflarım, sözlerim seni arar Adını ezbere bilir rehberim Lahzaları ararım içind...', ARRAY['Türk Edebiyatı','Şiir','Gökçegül Özbek']::text[], 8.5, '{"poet":"Gökçegül Özbek","poet_slug":"gokcegul-ozbek","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sen-246-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geldiğimiz Yere Bak', 'geldigimiz-yere-bak-bir-mim-kemal-ertugrul-eeghi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İliklerine işlemiş korku

Son onbeş yıldır harflerin

Ve dili tutulmuş sözcüklerin

Konuşan diller konuşmaz oldu

Birer ikişer susturuldu yazan kalemler

Harfler olsun ve sözcükler

O günden beri

K-E-K-E-L-E-R  hala korkudan.....', 'İliklerine işlemiş korku Son onbeş yıldır harflerin Ve dili tutulmuş sözcüklerin Konuşan diller konuşmaz oldu Birer ikişer susturuldu yazan ...', ARRAY['Türk Edebiyatı','Şiir','Bir Mim Kemal Ertuğrul']::text[], 8.5, '{"poet":"Bir Mim Kemal Ertuğrul","poet_slug":"bir-mim-kemal-ertugrul","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/geldigimiz-yere-bak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BEN', 'ben-gokcegul-ozbek-kj85l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ümitler sarmış hayatımı

