INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklıma Esenler-5', 'aklima-esenler-5-atila-gunal-z2nbk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Toplumun kendi içinde yarattığı yasakları, yazılı kurallarla düzeltmeye kalkmak, onları yasak olmaktan çıkarmaz...', 'Toplumun kendi içinde yarattığı yasakları, yazılı kurallarla düzeltmeye kalkmak, onları yasak olmaktan çıkarmaz......', ARRAY['Türk Edebiyatı','Şiir','Atila Günal']::text[], 8.5, '{"poet":"Atila Günal","poet_slug":"atila-gunal","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/aklima-esenler-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'AYRILMAYALIM', 'ayrilmayalim-cengiz-oyke-kldbl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevenler mutlaka ayrılır derler

Ne olursun  canım ayrılmayalım

Herkesler ayrılır gözüyle baksa

Hasret ateşiyle kavrulmayalım

Bensiz de yaşarsın deme sevgilim 

Sensiz bir hayatı düşünmüyorum

Ayrılık bu kadar kolay olamaz

Sevgilim seni ben çok seviyorum

Hiç kimse elimden alamaz seni 

Başkasının değil  birtek  benimsin

Mevlam ne olursun ayırma bizi

Ayrılık kanunu bizden silinsin

                              Cengiz ÖYKE', 'Sevenler mutlaka ayrılır derler Ne olursun  canım ayrılmayalım Herkesler ayrılır gözüyle baksa Hasret ateşiyle kavrulmayalım Bensiz de yaşar...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Öyke']::text[], 8.5, '{"poet":"Cengiz Öyke","poet_slug":"cengiz-oyke","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ayrilmayalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabah Uykusu', 'sabah-uykusu-yucel-arzen-mzx7c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güneşi küstürsek bir daha sabah olmasa hain

Hiç yataktan çıkmasak, üstümüze doğmasa zalim

Bugün erken kalkmışım canım zaten burnumda

Param yokmuş, yoktu zaten kimin umrunda

Bir sabah uykusuna bir sana dayanamam

hasrete değil ama yokluğa katlanamam', 'Güneşi küstürsek bir daha sabah olmasa hain Hiç yataktan çıkmasak, üstümüze doğmasa zalim Bugün erken kalkmışım canım zaten burnumda Param y...', ARRAY['Türk Edebiyatı','Şiir','Yücel Arzen']::text[], 8.5, '{"poet":"Yücel Arzen","poet_slug":"yucel-arzen","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sabah-uykusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ayrılık', 'ayrilik-kaan-tekin-op2qw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ayrılık diyorlar senlen ayrılmamıza

peki ölüm nedir, soruyorum

ayrılıpta halen yaşayanlara', 'ayrılık diyorlar senlen ayrılmamıza peki ölüm nedir, soruyorum ayrılıpta halen yaşayanlara...', ARRAY['Türk Edebiyatı','Şiir','Kaan Tekin']::text[], 8.5, '{"poet":"Kaan Tekin","poet_slug":"kaan-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/ayrilik-105-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılıklar Nikotin Taşır', 'ayriliklar-nikotin-tasir-umut-ulbegi-z9dio', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İsteksizce 

okşadım tenini

dün gece son kez

karşılaştı buharlı trenler

''Ayrılıklar 

yüklerini de yanlarında götürür

Bilmez miyiz

bile bile döndüğümüzü''

dedi

meyhaneyi son terkedenler.

İsteksizce

kalkıp bir sigara yaktım

kubbenin en parlağının suratına

dibine kadar içilmiş 

dilsiz izmariti fırlattım

''Katran, fare zehiri, nikotin

bağımlıları derinden yaralar

akciğerleri karalar''

dedi

canlı yayın savcılarım

Onlara inat

bir tane daha parlattım

İsteksizce

okşadım tenini dün gece

ilk kez söndü gözlerimiz

gölgeler görünmez oldu ilk kez

Dün gece

istedim de

öldürdüm seni

Sen son sigarasısın

bu ayrılığın.', 'İsteksizce  okşadım tenini dün gece son kez karşılaştı buharlı trenler ''Ayrılıklar  yüklerini de yanlarında götürür Bilmez miyiz bile bile d...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/ayriliklar-nikotin-tasir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Trakya''nın Gülleri', 'trakya-nin-gulleri-turgay-akbulut-r0fkq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yol; 

Bir ip gibi gerili Trakya’nın ortasından

İpe dizili mandal mandal ilçeler

İllere inat nasılda gelişmişler

Mevsim; 

En güzel renktedir şimdi

Yeşil ve sarı

Hepsi güneşe tutkun güneşe sevdalı

Trakya’nın Gülleri

Trakya da bir sevdanın adı

Bir bilseler sevdanın azizliğini 

Bir bilseler solan renklerin sebebini

Güz mevsiminde dökülecek, tane tane kelleleri

Trakya’nın gülleri

Tane tane milyonlar olcak, 

Süslenecek rakı masaları

Hasibe nin düğününde savrulacak, 

Hasadın son kalanları

Baharla birlikte serpilecek, yeniden

Sevda tohumları

Yeniden yeşerecek yamaçları ovaları

Dağ taş dere tepe, günebakan la

Süslenecek Trakya

İçlerinden biri, güneşe inat bakarsa

İşte o yabani çiçek benim

Beni bir göçmen güzeline verin

Koparsın güllerimi tane tane, 

Bahtını çeker gibi

Tane tane ayırsın, tane tane serpsin, 

Tane tane çitlesin

Kasap havasında oynar gibi

Trakya’nın Gülleri

En güzel renktedir şimdi....

(haziran 2002)', 'Yol;  Bir ip gibi gerili Trakya’nın ortasından İpe dizili mandal mandal ilçeler İllere inat nasılda gelişmişler Mevsim;  En güzel renktedir ...', ARRAY['Türk Edebiyatı','Şiir','Turgay Akbulut']::text[], 8.5, '{"poet":"Turgay Akbulut","poet_slug":"turgay-akbulut","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/trakya-nin-gulleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İNADINA UMUT', 'i-nadina-umut-ali-i-hsan-konuklu-i7mna', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Diner göz yaşları bakarsın çocukların, 

yanakları artık cılız akarsu yataklarına benzemez.

Öksüz kalmaz, sürülmezler belki sevgi uzaklarına. 

Bakarsın yarınları olur, 

güleç kalkarlar sabahlara umutlu. 

Belki ölmezler savaşlarında büyüklerinin. 

Bakarsın kuş olurlar, 

zeytin dalı taşırlar inadına.... 

                                        A.konuklu', 'Diner göz yaşları bakarsın çocukların,  yanakları artık cılız akarsu yataklarına benzemez. Öksüz kalmaz, sürülmezler belki sevgi uzaklarına....', ARRAY['Türk Edebiyatı','Şiir','Ali İhsan Konuklu']::text[], 8.5, '{"poet":"Ali İhsan Konuklu","poet_slug":"ali-i-hsan-konuklu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/inadina-umut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SULAR TERSİNE AKIYOR', 'sular-tersi-ne-akiyor-halil-kocaman-ivum4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'soğuk bir zamanda yağan

karlar herkesi yakıyor

sular tersine akıyor

nazlı bülbül gülde değil 

kuru bir dalda şakıyor

sular yokuşa akıyor

bir avcı gelirmi diye 

kuşlar hep yola bakıyor

sular tersine akıyor

tüm düzenler yer değişmiş

çivi çekici çakıyor

sular tersine akıyor

sel olmuş akıp gidiyor

kanlı yaşlar göz döküyor

sular yokuşa akıyor

sarp dağlara duman değil 

dumanlara dağ çöküyor 

sular yokuşa akıyor

dertlenmeyim diye nazar 

nazar boncuğu takıyor

sular tersine akıyor...

Halil Kocaman

(Akhisar-MANİSA  2001)', 'soğuk bir zamanda yağan karlar herkesi yakıyor sular tersine akıyor nazlı bülbül gülde değil  kuru bir dalda şakıyor sular yokuşa akıyor bir...', ARRAY['Türk Edebiyatı','Şiir','Halil Kocaman']::text[], 8.5, '{"poet":"Halil Kocaman","poet_slug":"halil-kocaman","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sular-tersine-akiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HERŞEYİ SENDE BIRAKTIM', 'herseyi-sende-biraktim-halil-kocaman-fc208', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Selendi: senin sevdiğin şehir

benimse kurban olduğum Selendi.

sen şimdi Selendi''nin dar sokaklarında

bense düştüm gurbetin yoluna 

seni Selendi''de bıraktım

herşeyi sende bıraktım

ışığı, güneşi, sevinci, aylar süren hasretimi

neyim var ise herşeyimi

herşeyimi selendide bıraktım

seni de herşeyimi bıraktığım

Selendi''de bıraktım.

olmayacak bir daha senle anılarım

yürüyemeyeceğiz Selendi''nin

dar sokaklarında, gece lambalarının altında

yürüyemeyeceğiz bir daha.

ben bir daha olmayacağım selendide

yalnız sen varsın o suskun şehirde

yalnız seni bıraktım orda

seni yalnız bıraktım orda

seni Selendi''de bıraktım

herşeyi sende bıraktım.

umutları, ışığı, güneşi, 

tüm sevinçleri ve aylar süren hasretimi

herşeyi selendide bıraktım

yalnız acıları, özlemleri, geceleri

sevda ateşinde yanan yüreğimi

ve bitmeyecek olan yeni bir hasreti

götürüyorum yanımda 

seni Selendi''de bıraktım

herşeyimi sende bıraktım...

Halil Kocaman  Selendi-MANİSA

(3 aralık 2003 Selendi yolu)', 'Selendi: senin sevdiğin şehir benimse kurban olduğum Selendi. sen şimdi Selendi''nin dar sokaklarında bense düştüm gurbetin yoluna  seni Sele...', ARRAY['Türk Edebiyatı','Şiir','Halil Kocaman']::text[], 8.5, '{"poet":"Halil Kocaman","poet_slug":"halil-kocaman","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/herseyi-sende-biraktim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BURDA GÜNDÜZLER DE KARANLIK', 'burda-gunduzler-de-karanlik-halil-kocaman-hfqwi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ben gecelerin içinde 

kaybolmuş bir avareyim.

yalnızlığın bile olmadığı 

yapayalnız bir diyardayım.

her sabah güneş doğuyor ama

neden beni aydınlatmıyor? 

neden karanlıktık geceler? 

adı gece diye mi? 

oysa ne geceler gördüm

gündüzlerden aydınlık

burdaysa gündüzler 

gecelerden de karanlık

burda günler geçmiyor

dağların ardı görünmüyor

her sabah güneş doğuyor ama

beni hiç aydınlatmıyor.

Halil Kocaman

Kasım 2002 Konya', 'ben gecelerin içinde  kaybolmuş bir avareyim. yalnızlığın bile olmadığı  yapayalnız bir diyardayım. her sabah güneş doğuyor ama neden beni a...', ARRAY['Türk Edebiyatı','Şiir','Halil Kocaman']::text[], 8.5, '{"poet":"Halil Kocaman","poet_slug":"halil-kocaman","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/burda-gunduzler-de-karanlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'FELEKTEN ÇEKTİKLERİM', 'felekten-cekti-kleri-m-cengiz-oyke-vohma', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sefalet zincirini boynuma vurmuşlar

Adımı sonra Cengiz koymuşlar

Garip geldim dünyaya garip gidiyorum

Ne halimi   ne de  hatrımı sormuşlar

Karanlıktı bahtım daha kararttılar

Değersiz diye bir köşeye attılar

Kimileri dert ortağı oldu bana

Kimileri de derdime dert kattılar

Mizan terazisi kurulur birgün

Bana yapılanlar sorulur birgün

Cehennemden sesleri duyulur birgün

Gönlüm işte huzur bulur o gün

                                 Cengiz ÖYKE', 'Sefalet zincirini boynuma vurmuşlar Adımı sonra Cengiz koymuşlar Garip geldim dünyaya garip gidiyorum Ne halimi   ne de  hatrımı sormuşlar K...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Öyke']::text[], 8.5, '{"poet":"Cengiz Öyke","poet_slug":"cengiz-oyke","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/felekten-cektiklerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HASRETİM SEVGİLİM ELA GÖZÜNE', 'hasreti-m-sevgi-li-m-ela-gozune-cengiz-oyke-v2o5u', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne olur gül biraz melek yüzünle 

Kendine bağladın beni bir çift sözünle

Öyle bir baktın ki gönlüme işledin

Hasretim sevgilim ela gözüne

Leylamısın şirinmisin belli değil ki

Nden sevmezsin beni yaşım elli değil ki 

Aşkımı anlatsa sazım dilli  değil ki 

Hasretim sevgilim ela gözüne

Yanağında güller açmış koklasam biraz

Solma sen sevgilim hiç gelmese yaz

Gitsem uzaklara da  özlesen biraz

Hasretim sevgilim ela gözüne

O güzel gözlerin beni benden alır

Beni benden alınca söyle bana  ne kalır

Kıskanırım gözlerine bakanlar olur

Hasretim sevgilim ela gözüne

                              Cengiz ÖYKE', 'Ne olur gül biraz melek yüzünle  Kendine bağladın beni bir çift sözünle Öyle bir baktın ki gönlüme işledin Hasretim sevgilim ela gözüne Leyl...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Öyke']::text[], 8.5, '{"poet":"Cengiz Öyke","poet_slug":"cengiz-oyke","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hasretim-sevgilim-ela-gozune-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Yağmurla Dökülürsün', 'yagmurla-dokulursun-yusuf-gencal-wsmjp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aylardan mart

Yağmur yağıyor sağnak

Baharın yeşil  başına                              

Yağmur olur dökülürsün              

Rüzgar olur sokulursun

Yüreğimin yanına

Çırılçıplak kalır düşlerim

Gecelerin kimsesizliği

Çöker omuzlarıma                 

Sen yanımda yoksun

Kollarında değilim şimdi

                                

26/3/2002k', 'Aylardan mart Yağmur yağıyor sağnak Baharın yeşil  başına                               Yağmur olur dökülürsün               Rüzgar olur sok...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Gençal']::text[], 8.5, '{"poet":"Yusuf Gençal","poet_slug":"yusuf-gencal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yagmurla-dokulursun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızca ''HİÇ'' mi Yoksa', 'yalnizca-hi-c-mi-yoksa-naime-erlacin-uoi12', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yolculuk 

ayrılığın hazin başlangıcı

ilk merhabadadır veda haykırışı

başlarken bitişin sesini duyarım

doğarken ölümün kulağımda

yalnızca zaman mıdır yitirilen 

bir dolu hüzün müdür arkada kalan? 

geceler uykusuz geçmese

acılar çekilmese 

kana dönüşmese gözyaşı

girişmesek kayıp savaşlara

varışlar olmasa

dönüşler olmasa 

olur mu acaba? 

bağ bozumundayız hiçliğin

dolunay yitik 

nilüfer firarda

anlamsız şimdi gelincik aramak

sevdanın sürgün kovuğunda

hiç''ten yola koyulup

hiç'' varmakta mı gizlidir 

utangaç bir merhaba? 

derbeder nöbetlerde 

hiç''le tanışmak

hiç''le kutsanmak ilkten

hiç''e selam durmak

olacak iş mi

olur mu acaba? 

.....

Söyleyecek sözüm var hayata dair! 

(13 Nisan 2003)', 'yolculuk  ayrılığın hazin başlangıcı ilk merhabadadır veda haykırışı başlarken bitişin sesini duyarım doğarken ölümün kulağımda yalnızca zam...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/yalnizca-hic-mi-yoksa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir zamanlar Istanbul', 'bir-zamanlar-istanbul-nevin-kalafatoglu-uik3s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir biskuvi fabrikasi, 

bir cukulata kokusu 

caddelerde.. 

bir tarafi ''alyans apartmanlari''.. 

karsida bos bir arsa, 

''ercan han'' kösede. 

bir zincirlikuyu, 

bir amerikan dükkani, 

bir jimmy hendrix dansı, 

bir grup zenci asker amerikan, 

arkadaslar kizlar oglanlar... 

bir ben. 

bir kafe mola, 

bir basket potası, 

bir hydromel, 

carsamba matinası... 

mini etekler, 

sütyensiz protest kızlar, 

sasirmis delikanlılar... 

sinemalar; kent, fitas, dunya, 

dostlar tiyatrosu, 

sarkılar sarkılar... 

etiler''in yokusu, 

bebek sırtlarının çimenleri, 

sefertası askları... 

levent''e moğollar. 

bebek, 

ozdemir asaf kafesi, 

kofteci alibaba, 

tekneler sıram sıram... 

tarabya, 

fisneli dondurma, 

cepte bikiniler, 

gitanne sigaralar 

veya birinci, 

bitpazarından jean''ler, 

mudo kadife pantalonlar pasajdan... 

haspapiler, 

baba atletinden 

batik yaptıgımız t-shirt''ler, 

bilezikler gümüs, 

küpeler bakır... 

silebezi bol elbiseler, 

basmalar koylu pazarı kapalı çarsı, 

çiçekli sapkalar... 

dudaklarda; 

hair, aquarias, tommy 

ve biz kayıp kusağin gencligi... 

cicekli kagitlarla kaplanmis 

yasak kitaplar, 

okulda duvar gazetesi, 

altında fuzuli yazan nazim''in siirleri.. 

you got a friend, killing me softly 

''öyle uzak ki yerim, benimle oynarmisin'' 

dinlenen sarkılar... 

humeyra, bulent ortacgil, esin afsar, tanju okan 

timur selcuk ezgileri... 

okullarda; kavga dögüs, silah, ölüm! 

ben resim yapmak, siir yazmak isterdim... 

gulçin lisan oğrenmek, 

özay sarkı soylemek... 

simdi özay''ı dinliyorum cd''de 

caz söylüyor. 

ben biliyorum sarkilarini, yasiyorum 

ve agliyorum... 

kolay olacakken hersey, 

zorları yasayan bizler... 

ve sarkisinda söylüyor 

''en güzel cocuk henuz doğmadı'' 

ücümüzünde cocuklari olmadi... 

sevmediler dünyayi, gelmedıler, 

en güzele ulasamadık! 

gec te olsa kendimize ulastık. 

özay sarki söylüyor newyork''ta.. 

gülcin Nazim''i cevirdi almanca''ya berlin''de.. 

bense, ancak yaziyorum yazilarimi, siirlerimi 

beydağlarının eteklerinde... 

Istanbul eskidi artık, 

biz gec kaldık....

(10.03.2003)', 'bir biskuvi fabrikasi,  bir cukulata kokusu  caddelerde..  bir tarafi ''alyans apartmanlari''..  karsida bos bir arsa,  ''ercan han'' kösede.  b...', ARRAY['Türk Edebiyatı','Şiir','Nevin Kalafatoğlu']::text[], 8.5, '{"poet":"Nevin Kalafatoğlu","poet_slug":"nevin-kalafatoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":80,"source_url":"https://www.antoloji.com/bir-zamanlar-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'istanbul yalnız', 'istanbul-yalniz-i-kbal-senturk-yev9v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'siz gidince

evin camlarına

karanlık yerleşiyor

arabanın durduğu yere

küçük bir kızın

gözyaşları...

istanbul yalnız kalıyor

geceleri korkuyorum

üşüyorum 

yokluğunuzda

biraz da ağlıyorum

hepsi bu...', 'siz gidince evin camlarına karanlık yerleşiyor arabanın durduğu yere küçük bir kızın gözyaşları... istanbul yalnız kalıyor geceleri korkuyor...', ARRAY['Türk Edebiyatı','Şiir','İkbal Şentürk']::text[], 8.5, '{"poet":"İkbal Şentürk","poet_slug":"i-kbal-senturk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/istanbul-yalniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerinde Ben', 'gozlerinde-ben-hayrettin-turk-w5ape', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sonsuzlaştırıp saniyeleri

Eriyip asırlar boyunca

Bazen bir kahkanın parlaklığında

Bazen bir ortak hüznün buğusunda

Gözlerinde ben

Erimek için yaratılmışım...

Gözlerinde ben

Erimek için yaratılmışım

Kandil gibi

Zamanla yitirip parlaklığını

Tükenip tükenip

Gözlerinde ben

Dirilmek için yaratılmışım...

1986', 'Sonsuzlaştırıp saniyeleri Eriyip asırlar boyunca Bazen bir kahkanın parlaklığında Bazen bir ortak hüznün buğusunda Gözlerinde ben Erimek içi...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Türk']::text[], 8.5, '{"poet":"Hayrettin Türk","poet_slug":"hayrettin-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gozlerinde-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbahar', 'sonbahar-hayrettin-turk-e0yw7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşılmaz  sandığım o engelleri

Bir martının kanadında geçmişim

Dalgalı bir gül kondurup eylüle

Kıyıda sonbahar, seni seçmişim...

Isınmışım soğuk rüzgarlarında

Gecelerden gündüzlere ermişim

Bir zaman öğrenirken mevsimleri

Ben hep sonbahar, sonbahar dermişim...

Aşıp nice acımaz baharları

Bir eylül günü kapına gelmişim

Ayrılıkların mevsimi olan sen

Acımışsın bana, sende sevmişim...

06.10.1986', 'Aşılmaz  sandığım o engelleri Bir martının kanadında geçmişim Dalgalı bir gül kondurup eylüle Kıyıda sonbahar, seni seçmişim... Isınmışım so...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Türk']::text[], 8.5, '{"poet":"Hayrettin Türk","poet_slug":"hayrettin-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sonbahar-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ask kalemine ağııt', 'ask-kalemine-agiit-nevin-kalafatoglu-6ox4w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1. 

ben bir koç burcuyum... 

hersey dibine kadar yasanır hayatımda.... 

bazen canım sekerek yurumek ister yollarda... 

bazen surunurum. 

coğu zaman gunesi ozlerim. 

bulutlar ağlatır beni. 

deniz ozgurlugum 

tekneler  kurtulus simgem, 

benim. 

birgun binip bir tekneye 

tek basima, ufka gidip, 

gunese varacağım 

sarılıp o na 

kizilların icinde yok olacağım... 

siirlerim kalacak... 

birgun baska bir asık kadın 

okuyacak, 

kendini bulacak... 

hayatının siiirlerini ve kendi 

tekrarını yasayacak, 

hep yanlız olarak. 

bu siir, 

tum asklara kalacak. 

2. 

koç bir adam, 

yıkık asklarını dusleyecek, 

gunlerin gecelerinde, 

siirler yazacak kalemiyle, 

laleler sulayacak acsinlar diye. 

kalacak sayfalarında isyanlar kitapların, 

kavgalar benliginde, 

cinayetler isleyecek yureğinde... 

ben 

onun siirlerinden, 

acılarının, hasretlerinin, ozlemlerinin, 

parçalarını bir koyda, 

cakıltaslarına birakacagım. 

dunya donecek yıldizlar değisecek, 

kulaginda, 

unutulamayan bir sozcukle. 

adam, 

siyah saçlarıni sivazlarken, 

gunesin denize vardığı zaman, 

sahilde, 

benden bir armağan bulacak, 

dudaklarında huzunlu bir tebessumle. 

lalenin bıraktığı armağanları 

cakıl taslarının içinde. 

hatırlayacak... 

olimpos''ta 

sonsuz atesin sıcaklığını, 

vucudunda hissettigi anlari. 

gunese bakacak uzun uzun, 

gunesin kendisini cektigini, 

anlar gibi olacak, 

laleli kadınını... 

hep, hep orada olacağım, . 

o an bir meltem estıreceğım denizden 

yayılacak askın kokusu 

yazacak orada 

bir siir 

içinde ben olacağım.

28.03.2003', '1.  ben bir koç burcuyum...  hersey dibine kadar yasanır hayatımda....  bazen canım sekerek yurumek ister yollarda...  bazen surunurum.  coğ...', ARRAY['Türk Edebiyatı','Şiir','Nevin Kalafatoğlu']::text[], 8.5, '{"poet":"Nevin Kalafatoğlu","poet_slug":"nevin-kalafatoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/ask-kalemine-agiit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
