INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kudüs Fareleri', 'kudus-fareleri-ece-ayhan-dwc35', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dördüncü konuşmamızda

(ben neredeyim?)

isa''dan önce bu kentte

bir karınca taciri

