INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benlegönül', 'benlegonul-salih-cakir-97lio', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben derim; bu kadar etme eziyet, 

İşlediğin reva mıdır? Hak mıdır? 

Kurban olduğunda ne ki meziyet? 

Etle kemik sende dahi yok mudur? 

Gönül der: Gamzesi mest eder beni, 

Cümle varlık ile dost eder beni, 

Kederlense bir an hast''eder beni, 

Böylesine vurulmuşum çok mudur? 

(Samsun,14.04.2003)', 'Ben derim; bu kadar etme eziyet,  İşlediğin reva mıdır? Hak mıdır?  Kurban olduğunda ne ki meziyet?  Etle kemik sende dahi yok mudur?  Gönül...', ARRAY['Türk Edebiyatı','Şiir','Salih Çakır']::text[], 8.5, '{"poet":"Salih Çakır","poet_slug":"salih-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/benlegonul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuz Ask', 'sonsuz-ask-baris-yavuz-9d9pb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'tabiat anam, 

dogan gunes safak diyen bir askerin, 

yillar sonra kizina kavusan bir babanin, 

baris odulu alan yetmisindeki bir insanin, 

olumcul bir hastaligi yenen bir hastanin, 

anasinin kokusunu taniyip kucaginda gozleri gulen bir bebegin

tarif edilmez mutluluklarini

bir potada eritip bana icirdigini dun gece

bilmem ki fark ettin mi? 

                           

yorucu gunler, haftalardan sonra, 

bas ucumda pempe zarfta buldugum siirin ile      

dedim ki kendi kendime 

demek su dari dunyada 

varmis bizi de tabiat gibi, toprak, su hava gibi seven biri.

hani oyle ki; 

deseler ay, gunes hepsi yok olacak, 

tabiat ters duz olacak, 

ama o hep seninle olacak 

belliki bir dakika dusunmeyecek

kabullenecek.

bazen insanoglu unutur, 

hatirlatmak gerek ara sira, 

bir cimcik atip uyandirmak gerek onu ki bilsin

devinen tabiat gibi, 

bitmez bu dunyanin ne isi ne kavgasi, 

basladigin yere donersin sonunda

bir istisna disinda; 

...

bunu doldurmasi size duser ey dostlar, 

her beser, 

varir dogruya yani basina bakarsa eger.', 'tabiat anam,  dogan gunes safak diyen bir askerin,  yillar sonra kizina kavusan bir babanin,  baris odulu alan yetmisindeki bir insanin,  ol...', ARRAY['Türk Edebiyatı','Şiir','Barış Yavuz']::text[], 8.5, '{"poet":"Barış Yavuz","poet_slug":"baris-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/sonsuz-ask-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutların Kayboluşu', 'umutlarin-kaybolusu-mehmet-bakir-g3uqv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çocukken uçurtmaları kaçırdım elimden, 

Büyüdüğümde, sevdaları, 

Koşamadım peşinden, 

Tutamadım onları...

Ya bir bakış kesti iplerimi, 

Ya da bir rüzgar esti derinden...

Koparmak istedim ipleri, 

İstedim ki uçurtmalarım götürmesin beni uzaklara, 

İstedim ki bir bakışla yıkılmayayım, 

Ama yapamadım, 

Sevda beni o kadar sarmıştı ki, 

Ta kalbimden, 

Kalbimin tam orta yerinden...', 'Çocukken uçurtmaları kaçırdım elimden,  Büyüdüğümde, sevdaları,  Koşamadım peşinden,  Tutamadım onları... Ya bir bakış kesti iplerimi,  Ya d...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bakır']::text[], 8.5, '{"poet":"Mehmet Bakır","poet_slug":"mehmet-bakir","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/umutlarin-kaybolusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzünsevgi', 'huzunsevgi-sule-aydemir-i26mx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sarıp sarmalamış ya hüzünsevgi acı rengi kızıl

kapılar kapanmış ya köşkümde sanki vakit dar

soğuk vurmuşta kalmış ya tomurcuk dallarda

avucumda yüreğimi almışsın ya bende kal

kalmış bogum bogum arzular esir

sormusta kendine istediğin sevgi nedir

kaybolmuş gitmiş bir kaldırım mazgalında

kayıp giden sağnakta bir damla yağmur gibi

ilk kez korkmamış oysa bebeğini sever gibi

sevgisi şeker karası hüzün 

uyut bu yüreği', 'sarıp sarmalamış ya hüzünsevgi acı rengi kızıl kapılar kapanmış ya köşkümde sanki vakit dar soğuk vurmuşta kalmış ya tomurcuk dallarda avucu...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/huzunsevgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yılkı Atına Dönüşmeden', 'yilki-atina-donusmeden-naime-erlacin-f9cdi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '...evvel zaman içinde....

sar beni gönlüne 

''hüzün''den olsun biraz 

uzat bana duygularını

al koynuna

biraz bakışalım...ağlaşalım 

birlikte mahzunlaşalım

sar beni gönlüne 

''tutku''dan olsun biraz 

dokun tenime

yolcuymuşum gibi bu akşam

hani konuşmasak da olur derken

önce çekingenleşip 

ırmaklaşalım sonra

birlikte taşıp çılgınlaşalım

sar beni gönlüne 

''aşk''tan olsun biraz 

sözler verelim titreyerek karşılıklı

hercaileşelim...tartışalım...nazlanalım

pusu kuralım bir diğerimize

sonra barışıp kucaklaşalım

sar beni gönlüne 

''sevda''dan olsun biraz 

unutulsun ödenmemiş hesaplar

dikilelim kavgaya karşı 

sırları keşfe çıkıp bahçemizde

rasgele kanat çırpalım uçsuz evrende

uçalım 

deli kuşlardan azade

gökyüzünde destanlaşalım 

Anka Kuşu gibi öykülerde

.....diyordu ademoğlu, yılkı atına dönüşmeden önce....eyvahlar olsun sevmeyi bilmeyene! 

Söyleyecek sözüm var insana dair! 

(14 Nisan 2003)', '...evvel zaman içinde.... sar beni gönlüne  ''hüzün''den olsun biraz  uzat bana duygularını al koynuna biraz bakışalım...ağlaşalım  birlikte m...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/yilki-atina-donusmeden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutlarım', 'umutlarim-derya-yalcin-y1dye', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Siz alkanımızı pompalarken depolarınıza, 

ben yaşlı gözlerle ne olduğunu anlamaya çalışan bir savaş çocuğu gibi bakacağım size; 

ve neden diye sesleneceğim  ölü bedenleri arasındayken sevdiklerimin, 

gözyaşlarım taşıp dökülecek toprağa, onlar yeşertecek umutlarımı.

umutlarım yeşertecek bu dünyayı.', 'Siz alkanımızı pompalarken depolarınıza,  ben yaşlı gözlerle ne olduğunu anlamaya çalışan bir savaş çocuğu gibi bakacağım size;  ve neden di...', ARRAY['Türk Edebiyatı','Şiir','Derya Yalcın']::text[], 8.5, '{"poet":"Derya Yalcın","poet_slug":"derya-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/umutlarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Niye?', 'niye-bayram-tunca-ijnq5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Niye, şu âdemoğlu almıyor kıssadan hisse

Öncekilerinki gibi kâr etmiyor ne dedimse

Nedense kıssadan hisse almıyor hiç kimse

Eğer varsa gelsin canımı vereyim o kimse

14.04.2003-14.04', 'Niye, şu âdemoğlu almıyor kıssadan hisse Öncekilerinki gibi kâr etmiyor ne dedimse Nedense kıssadan hisse almıyor hiç kimse Eğer varsa gelsi...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/niye-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HANİ BENZİYORDUK YA İKİMİZ', 'hani-benzi-yorduk-ya-i-ki-mi-z-nail-demirciler-u61zu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hani isimlerimizi kazıdığım ağaç varya, 

İki tane yaprak kalmış, 

O asırlık ağaçtan geriye.

Ben o yaprağın bir tanesini bana, 

Bir tanesini sana, 

Dalarını aşkımıza, kökünü hayata benzettim.

Ağacın kökü aşkımıza mutluluk veren bir nesneydi

Şimdi  o da yok

Ve ben sensizim.', 'Hani isimlerimizi kazıdığım ağaç varya,  İki tane yaprak kalmış,  O asırlık ağaçtan geriye. Ben o yaprağın bir tanesini bana,  Bir tanesini ...', ARRAY['Türk Edebiyatı','Şiir','Nail Demirciler']::text[], 8.5, '{"poet":"Nail Demirciler","poet_slug":"nail-demirciler","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hani-benziyorduk-ya-ikimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabah Çağrısı', 'sabah-cagrisi-ozel-arabul-llvfe', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uyan şimdi uyan tam gümüş vakti

Bir su tomurcuğu patlar mavide

Açılır göğsünde gün, görkemli diri

Ne varsa kırlangıca dönüşmen için

Belki biraz Sümerlisin, yüzün uykuda Sümerli

Bir sarnıç başında yüzün

İpek sarılır, toprak yırtılır, bir yıldız düşer

Sabah üstümüzde zeytin yeşili

Düştür bu, başka türlü olamaz düştür bu

Damar damar açılan gökyüzünü

Nerdeyse tırpan gibi biçiyor ellerin

Çok yaşadığım, daha yaşadığım

Bir sandal ayrıldı sahilimizden

Uyan şimdi uyan uyandır beni', 'Uyan şimdi uyan tam gümüş vakti Bir su tomurcuğu patlar mavide Açılır göğsünde gün, görkemli diri Ne varsa kırlangıca dönüşmen için Belki bi...', ARRAY['Türk Edebiyatı','Şiir','Özel Arabul']::text[], 8.5, '{"poet":"Özel Arabul","poet_slug":"ozel-arabul","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sabah-cagrisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can hasan''a', 'can-hasan-a-yakup-caglayan-c9bfp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bayburt''tan Amasya''ya bir can Hasan yolladık

Yolladık ama arkasından hatırını kolladık

Bir öğlen vakti şehid oldu haberini aldık

       Sen düşürdün bizi yasa mateme

       Sen düşürdün bizi gama kedere

Seni çok severdik ama nafile

Her gelmende sohbet ederdik samimiyetle

Arkadaşlığın bir başkaydı vede sevgiyle

       Sen düşürdün bizi yasa mateme

       Sen düşürdün bizi gama kedere

Hasan''ı kaybettik, Hüseyinle geldik yanına

Ordaki arkadaşların almışlar seni kucağına

Alın götürün dediler toprağın kara bağrına

        Sen düşürdün bizi yasa mateme

        Sen düşürdün bizigama kedere

Bütün eşin dostun geldiler dörtbir yandan

Tabutuna el attılar, inanki hepsi candan

ALLAH Rahmetini versin bol tarafından

        Sen düşürdün bizi yasa mateme

        Sen düşürdün bizi gama kedere

Çoluk çocuğun sanmaki kaldı ortada

Yüce ALLAH yetimini kollar herbir alanda

Sen şehidliğin sefasını sür, biz kaldık sahada

         Sen düşürdün bizi yasa mateme

         Sen düşürdün bizi gama kedere

Hazreti Azrail buldu seni o diyarda

Yakup bundan sen ibret alda, kalma feryada

Unutmayacağım seni olsamda fizanda

          Sen düşürdün bizi yasa mateme

          Sen düşürdün bizi gama kedere.', 'Bayburt''tan Amasya''ya bir can Hasan yolladık Yolladık ama arkasından hatırını kolladık Bir öğlen vakti şehid oldu haberini aldık        Sen ...', ARRAY['Türk Edebiyatı','Şiir','Yakup Çağlayan']::text[], 8.5, '{"poet":"Yakup Çağlayan","poet_slug":"yakup-caglayan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/can-hasan-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DOSTUM', 'dostum-ozel-arabul-8s8e1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '-Günüm karardığında

gecem uzadığında seni düşünürüm- 

Bir şiir söylenir dünyaya, payıma düşeni alırım

Bir renk atılır fırçayla, ışığı yakalarım 

Şarkı söyler bir kadın, dağılır yalnızlığım

Ve dimdik duruyorsa bir insan onca kavgada

Ödünsüz ve kararlı

Korkumdan utanırım 

Ne omzunu isterim başımı yaslayacak

Ne ellerini, ellerimde tutacak 

Varsın uzaktan savrulsun gülüşü 

Hiç olmasın gölgesi yanıbaşımda 

Sabahları bahçemde açan gül gibi 

Soluğu karışıp gitsin havaya 

Olması gereken yerde durur o 

Yani hayatın tam ortasında 

Bana kendimi sevdirmek için', '-Günüm karardığında gecem uzadığında seni düşünürüm-  Bir şiir söylenir dünyaya, payıma düşeni alırım Bir renk atılır fırçayla, ışığı yakala...', ARRAY['Türk Edebiyatı','Şiir','Özel Arabul']::text[], 8.5, '{"poet":"Özel Arabul","poet_slug":"ozel-arabul","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dostum-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İtiraf ve Pişmanlık*', 'i-tiraf-ve-pismanlik-bayram-tunca-d40il', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Düşünmekten kendi kendimi yiyip bitirdim

Ah o gençliğimi nasıl da çarçabuk yitirdim

Aah aldandım şu fani dünyayı baki sandım

Bu zan sebebiyle de gençliğimi heba ettim

14.04.2003-14.04', 'Düşünmekten kendi kendimi yiyip bitirdim Ah o gençliğimi nasıl da çarçabuk yitirdim Aah aldandım şu fani dünyayı baki sandım Bu zan sebebiyl...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/itiraf-ve-pismanlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırağı', 'kiragi-agah-ozbek-extir', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Belki bu beklenti

Güneş kadar sıcak

Kar kadar soğuk, 

Sabahın sessizliği

Bazen bir ömür kadar

Güzel...

                          15-02-1978-Çepni', 'Belki bu beklenti Güneş kadar sıcak Kar kadar soğuk,  Sabahın sessizliği Bazen bir ömür kadar Güzel...                           15-02-1978-...', ARRAY['Türk Edebiyatı','Şiir','Agah Özbek']::text[], 8.5, '{"poet":"Agah Özbek","poet_slug":"agah-ozbek","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kiragi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukluğum', 'cocuklugum-agah-ozbek-mqjoe', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çocukluğum tüm çocuklar gibi

Coşkulu temiz, 

Uğraşım elbetteki değişiktir

Bazı çocuklardan.

Çevrem kırsal

Sevgiden uzak

Yapay bir mutluluk vardır gönlümde

Sahte oyuncaklar

Ve

Yiyecek.

Güneşin doğuşu, akşamın karanlığı

Neyime

Neyime günleri saymak

Ve beklemek

Çünki daha çok erken

Yaşama mücadele vermek...

                                          12-12-1978 Adana', 'Çocukluğum tüm çocuklar gibi Coşkulu temiz,  Uğraşım elbetteki değişiktir Bazı çocuklardan. Çevrem kırsal Sevgiden uzak Yapay bir mutluluk v...', ARRAY['Türk Edebiyatı','Şiir','Agah Özbek']::text[], 8.5, '{"poet":"Agah Özbek","poet_slug":"agah-ozbek","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/cocuklugum-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korku', 'korku-agah-ozbek-46yvn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir noktaya

Dalıyor gözlerim.

Dalıyor gözlerim duvardaki noktaya, 

Baktıkca deliyor sanki

Ve geliyor üzerime duvarlar...

Bir örümcek acelece örüyor ağını, 

Korunmak için

Sinekten, sivrisinekten.

Neden korkmasın

Kartalda korkuyor artık serçeden.

Sen korkmuyormusun

Sanki, 

Korkmuyormusun benden.

                                 12-07-1983 Adana', 'Bir noktaya Dalıyor gözlerim. Dalıyor gözlerim duvardaki noktaya,  Baktıkca deliyor sanki Ve geliyor üzerime duvarlar... Bir örümcek acelece...', ARRAY['Türk Edebiyatı','Şiir','Agah Özbek']::text[], 8.5, '{"poet":"Agah Özbek","poet_slug":"agah-ozbek","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/korku-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Arkandan', 'senin-arkandan-ozel-arabul-337wa', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bu koltuk daha öncede burdaydı

köşede bücür ağaç

sen gidince ardından

kırdı kökleriyle saksıyı

koltuk bir genişledi hiç sorma

odalar almadı

neydi bizi ürküten

yanyana gelince

gözlerim baktığı yerde

kıvılcımlı bakır deli

avunmak için bir yer gerek bize

bir isim

sevgiyle tamamlayan kendi kendini

uysal bir rüzgar hiç köpürtmeyen

aramızdaki denizi', 'bu koltuk daha öncede burdaydı köşede bücür ağaç sen gidince ardından kırdı kökleriyle saksıyı koltuk bir genişledi hiç sorma odalar almadı ...', ARRAY['Türk Edebiyatı','Şiir','Özel Arabul']::text[], 8.5, '{"poet":"Özel Arabul","poet_slug":"ozel-arabul","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/senin-arkandan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim İnanır', 'kim-i-nanir-ozel-arabul-uf107', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'öyle uzun zaman geçti ki üstünden

kim bana benziyor şimdi

kim artık senin çizginde

izlermiş gibi çiçek açmış ağacı

kalakaldık düşlerimizin önünde

hiç sorduk mu neden bu kadar yakınız

uzak kaldıkça birbirimize

yazıktır tek başına bir bulutun

tepeleri sarması

taşır sürekli serinliğine

paylaşılmayan yalnızlığını

bu yüzdendir hüzün

gökyüzünün en eski parçası

yine de senin her gidişinde

açılmadan içine kapanır yüzüm

nasıl bıraktıysan senin renginde

peki ama sen ne zaman gelmiştin

söylesem kim inanır gittiğine', 'öyle uzun zaman geçti ki üstünden kim bana benziyor şimdi kim artık senin çizginde izlermiş gibi çiçek açmış ağacı kalakaldık düşlerimizin ö...', ARRAY['Türk Edebiyatı','Şiir','Özel Arabul']::text[], 8.5, '{"poet":"Özel Arabul","poet_slug":"ozel-arabul","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kim-inanir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acıdan Çok Kırgınlık Kalır', 'acidan-cok-kirginlik-kalir-ozel-arabul-93flj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '-Baise Korkmaz’a-

Yüzünü çevirsen

Bütün öfkem ayaklanır

Yani hepimizin içinde

Sınırsız bir korkunun

Paniği vardır

İki uyku arasında

Ansızın bir çeşme açılmış gibi

Ya da yaşlı bir kadının

Tülbenti kaymış gibi başından

Zaman çoğu kez

Bizden habersiz

Üstümüzden devrilir

Gidenin ardından

Ne kadar çok sevdiysek

Yaşamadıklarımız bir o kadar

Bu yüzdendir belki de

Acıdan çok kırgınlık kalır', '-Baise Korkmaz’a- Yüzünü çevirsen Bütün öfkem ayaklanır Yani hepimizin içinde Sınırsız bir korkunun Paniği vardır İki uyku arasında Ansızın ...', ARRAY['Türk Edebiyatı','Şiir','Özel Arabul']::text[], 8.5, '{"poet":"Özel Arabul","poet_slug":"ozel-arabul","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/acidan-cok-kirginlik-kalir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çaresizliğe Yumruk', 'caresizlige-yumruk-agah-ozbek-blvts', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Avcı namlusunda atıyor canım

Hoyrat rüzgarlar kol geziyor yüreğimde gayri

Kapkara bulutlar sarmalamış ruhumu ufka inat

Kan rengi sabahların ellerinde can veriyorum

Gökyüzüne açılan ellerime dert yağdı mevsimler boyu

Umutlarım güz gelmeden soldu sarardı.

Her gün yeni bir derdin bağrımı delişini seyrediyorum

Çaresizliğe açık tüm yürek kapılarım

Yaradana

Yaradılışıma içerliyorum.

Taze, saf ve temiz sayfalara

Hayatımın çilesini

Titreyerek

Ve korkarak yazıyorum...

                                 Yazıyorum.

                             22-01-1981 Adana', 'Avcı namlusunda atıyor canım Hoyrat rüzgarlar kol geziyor yüreğimde gayri Kapkara bulutlar sarmalamış ruhumu ufka inat Kan rengi sabahların ...', ARRAY['Türk Edebiyatı','Şiir','Agah Özbek']::text[], 8.5, '{"poet":"Agah Özbek","poet_slug":"agah-ozbek","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/caresizlige-yumruk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçindekini Dinle', 'i-cindekini-dinle-tarkan-ceper-ijnog', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '''dostum üveys akıncı''ya''

bazılarına ters gelse de bu iş eninde sonunda böyle

deyiverdiklerinde bakıp da yüzümüze: söylenecek hiçbir

söz yok artık gerçeğin gölgesinde. yani buymuş meğerse

aradığımız yıllardır hayatın anlamı: hesaptan düşülmesi gereken

bir azınlık düşü olsa olsa karışan sessizliğe; hep en derinden

başlayan iç döküşlerin aldatıcı, umursamaz ve düş bozuğu

sûretinde. sonra biz, durup kalıyoruz nedense, durup dururken

öyle kirli, öyle hesapsız ve öyle dalgın savrulurken geceye.

ruh, dolaşır durur ve çoğu zaman karşılaşamaz ikiziyle

yüzeyinde kirlendiğimiz şu umarsız gezegende: garip! oysa

böyle düşlememiştik hiç incitilmiş bir çocukluk yitiminde. kendi

yarasından beslenip büyürmüş bir gezginin acısı: anımsanır kimi

zaman uzun suskunluğumuz sancıyan göğsümüzde; acıtmıyor

epeydir koyu kanlı bir alışkanlık biçiminde yayıldığından beridir

gövdemize. sonra biz, gülüp kalıyoruz nedense, hiç nedensiz

öyle suskun, öyle şüpheli ve öyle şaşkın sokulurken gerçeğe.

insanın insana duyduğu güven bekârete benzer belli yönleriyle

ve yitirilirse bir şey konmaz yerine: yine de hayatın tuhaf, 

beklenmedik sürprizleri var işte. bütün ömre yetermiş sahi

yeniden bulunmuş bir dostluğun anısı: ama hâlâ lacivert

bir duman gibi yükseliyor kafileler halinde; bütün neftî

gece yarıları ister istemez filizlenerek bilincimizin bilemediğimiz

derininde. sonra biz, ölüp kalıyoruz nedense, hiç anlamadan

öyle paslı, öyle bitmemiş ve öyle kumral dağılırken geçmişe.', '''dostum üveys akıncı''ya'' bazılarına ters gelse de bu iş eninde sonunda böyle deyiverdiklerinde bakıp da yüzümüze: söylenecek hiçbir söz yok ...', ARRAY['Türk Edebiyatı','Şiir','Tarkan Çeper']::text[], 8.5, '{"poet":"Tarkan Çeper","poet_slug":"tarkan-ceper","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/icindekini-dinle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köpüklü Hüzün', 'kopuklu-huzun-erdinc-ozdemir-jgsq8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni son kez

Vapur iskelesinde görmüştüm

Üstünde bir türlü alışamadığım

Manton vardı

Göz göze gelince

Önce anılar geçti gözlerinden

Sonra bulutlar ve yağmur

Ama vapura binmezlik etmedin

İzmir- Siyah Beyaz Bir Film', 'Seni son kez Vapur iskelesinde görmüştüm Üstünde bir türlü alışamadığım Manton vardı Göz göze gelince Önce anılar geçti gözlerinden Sonra bu...', ARRAY['Türk Edebiyatı','Şiir','Erdinç Özdemir']::text[], 8.5, '{"poet":"Erdinç Özdemir","poet_slug":"erdinc-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kopuklu-huzun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Olmasa', 'ask-olmasa-eyup-kisa-lg8hb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gündüzün gecesi olmasa, 

gecenin yildizi, 

yildizin ayi olmasa, 

ayin günesi, 

günesin isigi olmasa, 

yine sana bakarmiydim? 

kirlar denize muhtaç olmasa, 

deniz yagmura, 

yagmur buluta, 

bulut beyaza, 

beyaz teninde olmasa, 

yine seni öpermiydim? 

gölgeli agaç olmasa, 

agacin dali, 

dalin bülbülü olmasa, 

bülbülün gülü, 

gülün kokusu olmasa, 

yine seni koklarmiydim? 

bahar olmasa, 

baharin çiçegi olmasa, 

çiçegin arisi olmasa, 

arinin bali, 

bal dilinde olmasa, 

yine seni dinlermiydim? 

beden olmasa, 

bedenin cani, 

canin gönlü olmasa, 

gönlün âski olmasa, 

âskin derdi olmasa, 

yine seni severmiydim?', 'gündüzün gecesi olmasa,  gecenin yildizi,  yildizin ayi olmasa,  ayin günesi,  günesin isigi olmasa,  yine sana bakarmiydim?  kirlar denize ...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Kısa']::text[], 8.5, '{"poet":"Eyüp Kısa","poet_slug":"eyup-kisa","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ask-olmasa-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstirahat- şiir fotoğraf -', 'i-stirahat-siir-fotograf-erdinc-ozdemir-hgscs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir sandalye 

Başka bir sandalyede

oturuyor', 'Bir sandalye  Başka bir sandalyede oturuyor...', ARRAY['Türk Edebiyatı','Şiir','Erdinç Özdemir']::text[], 8.5, '{"poet":"Erdinç Özdemir","poet_slug":"erdinc-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/istirahat-siir-fotograf-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz', 'deniz-mukerrem-mete-dj677', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen karalarda gezinirsin

Dağlar akarsularla kutlar bunu

Gök rüzgarıyla dokunur sana

Yağmur olur sevinci

Ama efkarlı deniz mahrumdur senden

Bu yüzden tuzludur suyu

Göz yaşları gibi', 'Sen karalarda gezinirsin Dağlar akarsularla kutlar bunu Gök rüzgarıyla dokunur sana Yağmur olur sevinci Ama efkarlı deniz mahrumdur senden B...', ARRAY['Türk Edebiyatı','Şiir','Mükerrem Mete']::text[], 8.5, '{"poet":"Mükerrem Mete","poet_slug":"mukerrem-mete","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/deniz-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakın Şehirlerimi', 'yakin-sehirlerimi-mukerrem-mete-qba2s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'çakmak gözlü bir güzel

tutuştursun ucundan

baştan başa benzin dökün 

yakın şehirlerimi

yağmalayın tahtı tacı

saltanatımı yıkın

bana ait ne varsa

mülküm tarumar olsun

kovun beni diyarımdan

yeter ki dostlar

ümit var olsun', 'çakmak gözlü bir güzel tutuştursun ucundan baştan başa benzin dökün  yakın şehirlerimi yağmalayın tahtı tacı saltanatımı yıkın bana ait ne v...', ARRAY['Türk Edebiyatı','Şiir','Mükerrem Mete']::text[], 8.5, '{"poet":"Mükerrem Mete","poet_slug":"mukerrem-mete","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yakin-sehirlerimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalanmış Unutmak', 'yalanmis-unutmak-hikmet-tugrul-tekeli-8e3x6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dün seni gördüm

İçimde buruk bir acı 

Seni bana taşıdı

Nasılda yalanmış unutmak

Bir anda herşeyi silip atmak

Kolaymış yaa! ! 

Bir bakış 

Hatta küçücük bir tebessümdü

Yüreğimin ormanlarını yakan

Umursamaz tavırlarındı 

Beni benden alan

Dünyamı karanlıklara boğan

Bir gülümsemenle hapsettin çaresizliğe

Kabustu rüyalarımda gördüğüm

Gözlerin aldı ruhumu 

Sakladı karanlığa

Doğmadı güneş sensiz gecelere

Dinmedi yağmur yokluğunda 

Silinmedi, 

Ne acısı yüreğimin

Nede buğusu penceremin

Kurduğun hayalleri yaşatıyorum şimdilerde

İnadına suluyorum çiçekleri

Nöbetlerdeyim sabahlara dek

Bir doldurup bir boşaltıyorum yüreğimi

Anlıyorum

Yalanmış unutmak

Yalanmış bir anda herşeyi silip atmak

Kolaymış yaaa! !', 'Dün seni gördüm İçimde buruk bir acı  Seni bana taşıdı Nasılda yalanmış unutmak Bir anda herşeyi silip atmak Kolaymış yaa! !  Bir bakış  Hat...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Tuğrul Tekeli']::text[], 8.5, '{"poet":"Hikmet Tuğrul Tekeli","poet_slug":"hikmet-tugrul-tekeli","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/yalanmis-unutmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cansın', 'cansin-salih-kabakcioglu-qwx3j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Cansın canımdım, canım olarakda kalacacaksın

Şunu bilki her zaman canlı yanım kalacaksın

Hayatta ciddi yaptığım tek işti seni sevmek 

Hayatım artık bunun üzerine kuruldu

Seni sevmek veya sevmemek

Hayatımsın, canımsın, cansınımsın

Gözlerine bakarken korkuyorum kırılcak diye

Ellerini tutarken korkuyorum incincek diye 

Tek bir şeyden kormuyorum Cansınım

Seni sevmekten', 'Cansın canımdım, canım olarakda kalacacaksın Şunu bilki her zaman canlı yanım kalacaksın Hayatta ciddi yaptığım tek işti seni sevmek  Hayatı...', ARRAY['Türk Edebiyatı','Şiir','Salih Kabakçıoğlu']::text[], 8.5, '{"poet":"Salih Kabakçıoğlu","poet_slug":"salih-kabakcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/cansin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mihriban’ın Cevabı..Hece', 'mihriban-in-cevabi-hece-hidir-cam-1qu5k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '.... bir de kadın yüreği var ağızsız, dilsiz.....

Unutursun demek dillere kolay

Unutamıyorum gül yüzlü Alim

Ben tutsak Mihriban, evim bir saray

Avunamıyorum gül yüzlü Alim

Davulla, zurnayla silindi güya

En güzel duygular daldı uykuya

Cemreler düştükçe toprağa, suya

Uyutamıyorum gül yüzlü Alim

Gözlerim kör olmuş bakmaz yabana

Sevgin silinmiyor tutmuyor yama

Kendimi unuttum, unuttum ama

Seni unutamadım gül yüzlü Alim

Çizgiler yüzümde süs desen, desen

Çizgiler ne yazar bir bilebilsen

Yazdıran kör kader yazılan da sen

Silemiyorum gül yüzlü Alim

Şiirler yazmışsın yanık mı yanık

Türküler yakmışsın turnalar tanık

Sensiz geçen yıllar zifir karanlık

Uyuyamıyorum gül yüzlü Alim

Ne bir haber aldım, ne de bir selam

Doğmadan alnıma yazılmış belam

Ellerim titriyor yazmıyor kalem

Anlatamıyorum gül yüzlü Alim

Unutursun demek kolaydır dile

Oğlun kızın olsun demiştin hele

Dileklerin tuttu fallara göre

Yine unutamadım gül yüzlü Alim

Gömmeden bu aşkı kazmayla kürek

Ellerin elime dokunsa gerek

Bebe değil ki bu, bir yanık yürek

Avutamıyorum gül yüzlü Alim

Gördüğüm bir düş mü yok mu süresi

Boynumda zincir mi aşkın çilesi

Ayrılıktan ölüme sınır neresi

Çizemiyorum gül yüzlü Alim

Sevda çekmeyene bir aşk masalı

Bir bedende gizli çift can misali

Neresi Mihriban, neresi Ali

Çözemiyorum gül yüzlü Alim', '.... bir de kadın yüreği var ağızsız, dilsiz..... Unutursun demek dillere kolay Unutamıyorum gül yüzlü Alim Ben tutsak Mihriban, evim bir sa...', ARRAY['Türk Edebiyatı','Şiir','Hıdır Çam']::text[], 8.5, '{"poet":"Hıdır Çam","poet_slug":"hidir-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/mihriban-in-cevabi-hece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dom Dom Kurşunu', 'dom-dom-kursunu-mahzuni-serif-lblk8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kaşların arasından

Domdom kurşunu değdi

Bir avcı vurdu beni

Bin avcı beni yedi

Ah dedim ağladım

Yaremi bağladım

Eğdi yar boynun eğdi

Mevlam Kerim’sin dedi

Hançer yarası değil

Domdom kurşunu değdi

Gel gel gümle gel

Gel gel gümle gel

Gel böğrüme domdom kurşunu

Bugünüm harap oldu

Dünden iyi midir ki

Doktor hasta ben hasta

Benden iyi midir ki

Ah dedim ağladım

Yaremi bağladım

Eğdi yar boynun eğdi

Mevlam Kerim’sin dedi

Hançer yarası değil

Domdom kurşunu değdi

Gel gel gümle gel

Gel gel gümle gel

Gel böğrüme domdom kurşunu

Mahzuni yar benim

Halimi anlasaydı

Bütün dertliler gibi

İnleyip dinleseydi

Ah dedim ağladım

Yaremi bağladım

Eğdi yar boynun eğdi

Mevlam Kerim’sin dedi

Hançer yarası değil

Domdom kurşunu değdi

Gel gel gümle gel

Gel gel gümle gel

Gel böğrüme domdom kurşunu', 'Kaşların arasından Domdom kurşunu değdi Bir avcı vurdu beni Bin avcı beni yedi Ah dedim ağladım Yaremi bağladım Eğdi yar boynun eğdi Mevlam ...', ARRAY['Türk Edebiyatı','Şiir','Mahzuni Şerif']::text[], 8.5, '{"poet":"Mahzuni Şerif","poet_slug":"mahzuni-serif","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/dom-dom-kursunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünün Hikayesi', 'dunun-hikayesi-cengiz-oyke-t4fgd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dün yine sahillerde gezdim sevgilim 

Kıyıya çarpan dalgalarda seni aradım

Yolun düşerse gezersen sahillerde 

Belki  bir umut sorarsın  beni sende 

Martılara, dalgalara, balıklara haber bıraktım

Rüzgarlıydı hava esiyordu her taraftan

Fırtınalar, tayfunlar, tufanlar kopuyordu dertli başımda

Göğsüme çarpan o sert  rüzgarlara

Seninde yanından eserler diye belki

Lodosa,  poyraza, meltemlere kokumu bıraktım

Hayaller alemine  dalıyordum  bazen 

Bir geçmişe gidiyordum bir de geleceğe

Günler aylar geçiyordu o hayal aleminde sanki 

Belki  sende yaşarsın o anı diye

Haber bıraktım dünkü gündüz ile, yarınki geceye

Saatler ilerliyordu  hiç ummadığın bir anda 

Geceyle gündüzün birleştiği, o alacakaranlıkta

Sen beliriyordun birden bana gel, gel, gel diyordun

Koşuyordum sana olanca gücümle Koşuyordum,  koşuyordum

Tam ellerimiz birbirine deyeceği anda kayboluyordun

Dün dünyayı gezdim sevgilim

Aradım seni aradım,  hiç bir yerde bulamadım

Bir ihtimal karşılaşırsınız diye

Toprağa, suya, buluta haber bıraktım

Vazgeçtim seni aramaktan, seni bulamayacağımı anladım.', 'Dün yine sahillerde gezdim sevgilim  Kıyıya çarpan dalgalarda seni aradım Yolun düşerse gezersen sahillerde  Belki  bir umut sorarsın  beni ...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Öyke']::text[], 8.5, '{"poet":"Cengiz Öyke","poet_slug":"cengiz-oyke","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/dunun-hikayesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Emperyalizminin Sömürgesi', 'ask-emperyalizminin-somurgesi-melih-coskun-nvgro', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen aşk emperyalizminin 

En zayıf düşmüş sömürgesi; 

Topraklarında yalancı bir gülümseme

Yabanın postal izi var yüreğinde

Ve ihtilaldir artık bu yaşanılan, 

Yüreğinin askerleri çoktan zaptetmiştir 

Beyninin kalelerini

O gözler 146. Maddeden daha acımasızdır artık

Sözlerin darbeci generallerin buyrukları gibi

Beynin kaybetti iktidarını 

Sen artık yüreğinin sömürgesisin 

Sen artık uzak diyarlara gidip de

Dönemeyişin diğer adısın 

Sen artık özgür olduğunu sanıp ta

Esir düşmenin en büyük tanığısın 

Yürek himayeyi kabul etti

Düştü beyninin toprakları 

Aşksızlığın dağlarında 

Özgür türküler söylemek varken 

Bu beden mavi bir bayrak altında 

Yaşamayı kayıtsız şartsız kabul etti... 

Yürek mandayı kabul etti

Ve esirdir artık beyin...

22 Şubat 2003

19: 42', 'Sen aşk emperyalizminin  En zayıf düşmüş sömürgesi;  Topraklarında yalancı bir gülümseme Yabanın postal izi var yüreğinde Ve ihtilaldir artı...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ask-emperyalizminin-somurgesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün Sana Yakışıyor', 'huzun-sana-yakisiyor-melih-coskun-6922t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hüzün sana yakışıyor çocuk 

Gülüşünde geçmişin bıçak yarası 

Yüzünün değişen her kıvrımında 

Kalp ağrısı gibi sancıyan bir halk

Gülüşünde sakladığın bir şeyler var 

Derinlerde bir yerde hiç gülmeyen bir çocuk 

Gözlerinden taşan kederin dağlar 

Sevincin deryalar kadar...

Hüzün sana yakışıyor çocuk 

Akan her gözyaşında 

Dar sokaklarda düşen bir yoldaş

Her kahkahanda 

Sömürüsüz bir geleceğin pembe düşü

Gülebilseydin sende 

Seni ağlatanlar kadar 

Gülebilseydi eğer bir halk

Gülmekte yakışırdı sana 

En az ağlayışın kadar...

29 Ocak 2003

21: 36', 'Hüzün sana yakışıyor çocuk  Gülüşünde geçmişin bıçak yarası  Yüzünün değişen her kıvrımında  Kalp ağrısı gibi sancıyan bir halk Gülüşünde sa...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/huzun-sana-yakisiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yok Tanımı Acının', 'yok-tanimi-acinin-melih-coskun-1ipla', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'I.

Yok tanımı acının 

Hiçbir dilde, 

Farklı yaşanır her ölüm 

Her hayatta

Hiçbir kitabın tozlu sayfasında yazmaz 

İçinde bir yerinde bu bedenin 

Binlerce bıçak saplanmışçasına sızlayan bu yara 

II.

Çılgınca korktuğumuz her keder 

Ve Ölüm, 

Hayatı daha iyi yaşa diye bağırıyor sana

Yarın yok belki de diyor

Oysa bugün daha çok şeylere gebe

En azından bu dünyanın sızısını götürme yanında 

Yaşa, denizlerin coşup da dalgakıranları parçalaması gibi

Yaşa, ırmakların yüzlerce metreden koşup ta

Tuzlu sulara karışması gibi 

Yaşa yasak bir şarkının

Gizli gizli her gün söylenmesi gibi

III.

Korkma kaybetmekten 

Yaşanması gereken ne varsa yaşanmalı ömründe 

Unutma ki ertelemek hayatı her gün biraz daha kaybetmektir

Kotalar konmuş şu ömrümüzde, 

Sınırı yok içindeki heyecanın 

Yok hiçbir tel örgü, hiçbir sınır 

Kafatasında uçsuz bucaksız 

Alabildiğine koskoca bir dünya 

Yok hesabı sorulamayacak hiçbir haksızlık

Sorulamayacak hiçbir soru yok 

Söylenemeyecek hiçbir söz... 

IV.

Rüyalardaki kadar insaflı değil hayat

Derin boşluklara düşerken 

Ve birkaç metre kalmışken ölümüne 

Kan ter içinde yatağından fırlayacak kadar 

İyimser değil hiçbir gerçek 

Ölüm, 

Bedeninden daha çok 

Eksik kalmış sevgilerin gömülmesiydi 

Yada umudun 

Ölüm en çok yaşayamadıklarının gömülmesiydi 

Yazılmamış bir şiirin 

Hiç dinlenememiş bir türkünün gömülmesiydi ölüm

V.

Madem ki yürekli bir sevda kuşandın bu akşam 

Yürü üstüne kederin 

Unutma ki 

Bir şairi şair yapan en çok ta acılardır

Aşktan da öte, 

Bize düşen aklamaktı aşkı 

Karanlık 

	    Karanlık 	

		Karanlıklar içinde yitirdik günlerimizi

VI.

Aslında şairin gönlündeki aşk 

En çok da özlemdi geleceğe dair

Kelimelere sığmayan 

Anlatılamayan hiçbir resimde 

Hiçbir tarih kitabının yazmadığı 

Ve yazamayacağı

Hiçbir tasvirin anlatamadığı 

Hiçbir ansiklopedide tanımı geçmeyen

En çok da bunun için anlamadılar bizi...

Ve Öyle kirlettiler ki aşkı 

Ve öyle kirlettiler ki bizi 

Yüreğimi söküp kaldırsam havaya 

Artık bana kimseler inanmayacak...

VII.

Nerelere kayboldular

O kuralları koyanlar 

O güçlü olduğu için haklı olanlar 

O para babaları 

Yağlı saçlarıyla çantacılar 

O kan emiciler 

Bağlımıydı elleriniz kollarınız 

Sürgünlerde miydiniz

Yoksa dipsiz kuyularda mı 

Kara kalemlerle çizerlerken üzerini geleceğinizin 

VIII.

Hal böyleyken aşkı anlatamadık onlara 

Anlatamadık gece yarıları

Düşlemek varken kendi sevdalarımızı, 

Cam silerken arabalar altında biten bir çocukluğa 

Döktüğümüz yaşları gece yarılarında...

IX.

Aklandı nice karalı yürekleri haramilerin 

Aklandı kendini karanlığa adamışların kanlı gömlekleri

Meşru müdafaadan saydılar

Onlarca kurşun yarası göğsünde 

Hesaplandı aylar boyu optimum ceset sayıları 

Sığınaklarda çocuk cesetleri 

Aklandı tüm katliamlar 

Sevdamız karanlıkta kaldı 

Sevdamız karartmalar altında

Biz aşkı aklayamadık hiç

Kirleten biz değildik oysa 

Nerede ve ne zaman bitti 

Yazmadı hiçbir takvim yaprağı

Nasıl bitti o sevda...

X.

Nefret dolu bakan bu yüzler 

Sizi,  kendinizi tanıdığınızdan daha iyi tanıyorum artık

Onun için bu kırılganlığım, 

Soluksuz kalışım ondan 

Hepimize yetecek bir gökyüzü varken tepemizde...

XI. 

Adaletin hileli terazisinde 

Kötü olan baskın gelirken iyi olana

Karanlık aydınlığa, 

Çıkmaz sokaklarda yürüdük hep 

Yeniden kurulur diye bu şehirler

Belki ağır basar kavgamız diye bir gün

Göğümüzün altına duvarlar ördüler

Çevirdiler yeşil bahçeleri tel örgülerle 

XII. 

Aşk kirlendi 

Ve kirlendi bu diyarların temiz yüzlü çocukları 

Büyümek, kirletmekti ruhumuzu

Hep çocuk kalalım istedik

Küçük kalıp yüreğimizi büyütmek için 

Ancak büyüdük ve yüreğimizi küçülttük

Aşkı aklayamadık

Karanlıklar içinde kaybettik günlerimizi

Yüreğimi söküp kaldırsam havaya

Artık bana kimseler ama kimseler inanmayacak...

Aşkı kimse anlayamayacak! ..

4 Mart 2003

19: 10', 'I. Yok tanımı acının  Hiçbir dilde,  Farklı yaşanır her ölüm  Her hayatta Hiçbir kitabın tozlu sayfasında yazmaz  İçinde bir yerinde bu bede...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":130,"source_url":"https://www.antoloji.com/yok-tanimi-acinin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tabu', 'tabu-i-rfan-unubol-1v3a3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uzatıyor elimi, 

Sana değemiyorum. 

Koşsam da hiç durmadan, 

Sana eremiyorum. 

Kime sorsam halini? 

Sana soramıyorum. 

Açıyor kollarımı, 

Seni saramıyorum. 

Her yerde ve her zaman, 

Seni anamıyorum. 

İçmeyince elinden, 

Suya kanamıyorum. 

Arıyorum her yerde, 

Seni göremiyorum. 

Has bahçemin gülünü, 

Sana veremiyorum. 

Her gün tekrar yanıyor, 

Bir gün sönemiyorum, 

Sana gelen bu yoldan, 

İnan dönemiyorum. 

Açıl diyor hep duygu, 

Ona uyamıyorum. 

Dinlediğim her seste, 

Seni duyamıyorum. 

Sen bakarken gözüme, 

Sana bakamıyorum. 

Bekleyen aşk mumunu, 

İnan yakamıyorum.', 'Uzatıyor elimi,  Sana değemiyorum.  Koşsam da hiç durmadan,  Sana eremiyorum.  Kime sorsam halini?  Sana soramıyorum.  Açıyor kollarımı,  Se...', ARRAY['Türk Edebiyatı','Şiir','İrfan Ünübol']::text[], 8.5, '{"poet":"İrfan Ünübol","poet_slug":"i-rfan-unubol","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/tabu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal', 'hayal-i-rfan-unubol-fve44', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Olsun ya şu kısa arkadaşlığımız helal, 

Belki üzüleceksin ama hepsi hayal. 

Hiç istemezdim böyle bitsin bu iş, 

Fakat ne yapalım bu gidiş kötü gidiş. 

Belkisi fazla arkadaşım üzüleceğim elbet, 

İlk mi yapışacak yüreğime köz gibi gurbet. 

Kötüyümdür belki de bu yolda herkesten ben, 

Ama sen ne diyeceksin bu işe söyle sen! 

Sen put olsan karşında ben de putperest, 

Yine diyeceksin o zaman bu adam hayalperest. 

Aslında hayaller hepsinden de temizse,

Günler boyu sürecek umut yüklü gerçeğin, 

Aşk uğruna verilen güzel sözler tavizse, 

Ne önemi kalır sanki aranılan gerçeğin. 

Yine de kabulümdür benim olsan hayaller, 

Sende istersen hep katı gerçekle yaşa.

Zamanla tükenirse başımdaki o yeller, 

Vurur musun başını sertçe gerçek bir taşa? 

Diyeceğim buraya başlangıcın sonudur, 

Sevgi vaadederek kurulacak her hayal. 

Sorayım son kez sana vaad ettiğin bu mudur? 

Hayal, Hayal ve hep Hayal! ! !', 'Olsun ya şu kısa arkadaşlığımız helal,  Belki üzüleceksin ama hepsi hayal.  Hiç istemezdim böyle bitsin bu iş,  Fakat ne yapalım bu gidiş kö...', ARRAY['Türk Edebiyatı','Şiir','İrfan Ünübol']::text[], 8.5, '{"poet":"İrfan Ünübol","poet_slug":"i-rfan-unubol","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/hayal-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Telepati', 'telepati-i-rfan-unubol-y5c32', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bakıyorum, bakıyorum, bakıyorum, 

Bakıyorsun, bakıyorsun. 

Görmüyorsun, 

Ama biliyorsun.

Söylüyorum, söylüyorum, söylüyorum, 

Dinliyorsun, dinliyorsun. 

Duymuyorsun,

Ama anlıyorsun. 

Yazıyorum, yazıyorum, yazıyorum,

Okuyorsun, okuyorsun.

Hep susuyorsun,

Ama hissediyorsun. 

Bekliyorum, bekliyorum, bekliyorum, 

Gelmiyorsun, gelmiyorsun. 

İstiyorsun,

Ama korkuyorsun. 

Özlüyorum, özlüyorum, özlüyorum, 

Özlüyorsun, özlüyorsun. 

Söz veriyorsun, 

Ama gelmiyorsun. 

Seviyorum, seviyorum, seviyorum, 

Seviyorsun, seviyorsun. 

Bunu bir tek ben,

Bir de sen biliyorsun.', 'Bakıyorum, bakıyorum, bakıyorum,  Bakıyorsun, bakıyorsun.  Görmüyorsun,  Ama biliyorsun. Söylüyorum, söylüyorum, söylüyorum,  Dinliyorsun, d...', ARRAY['Türk Edebiyatı','Şiir','İrfan Ünübol']::text[], 8.5, '{"poet":"İrfan Ünübol","poet_slug":"i-rfan-unubol","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/telepati-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dilektir Bu', 'bir-dilektir-bu-bilgun-gungor-j3tut', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir şarkı tutturmuşum 

Gözden uzak köşelerde 

Dilimde aynı nağmeler 

Susturulmayı bekliyorum.

Bir tomurcuk gül açmış 

Zifiri avucumda 

Dikenli ellerimle 

Koparılmayı bekliyorum

Bir cılız sevgim kalmış 

Yaşamla birlikte 

Yaşama ait 

Acısını yüreğimde hissediyorum.

Ve bir garip ben kalmış 

Benden ziyade 

‘’ O ben’’in

Ben olmasını diliyorum.

                             29.3.2000', 'Bir şarkı tutturmuşum  Gözden uzak köşelerde  Dilimde aynı nağmeler  Susturulmayı bekliyorum. Bir tomurcuk gül açmış  Zifiri avucumda  Diken...', ARRAY['Türk Edebiyatı','Şiir','Bilgün Güngör']::text[], 8.5, '{"poet":"Bilgün Güngör","poet_slug":"bilgun-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-dilektir-bu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman Geceye Sustu', 'zaman-geceye-sustu-yakup-i-ncegul-4z2if', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '/Kader gecenin zehri/

Kuşluk vakti görülen rüya

susmuş bir şehre boşalıyor

gidişiyle korkular dilleniyor Yakup’un gözlerinde

Hangi zamanı kucaklasam

yüzler saklanıyor ölümün kovuklarına

Çekiliyor Yusuf kuyudan

köle diye satılıyor ihanetle

işte bir ömrün ilk perdesi..

Göklerin göğe sustuğu yerde

yağmalanan birşeydi yıldızlar..

Anlat Züleyha.! 

şimdi isyan vaktidir biliyorum

haykır Yusuf’un ızdırabını

işgal edilmiş dillerle konuş

kuşatılmış bir boşluktan bak gökyüzüne! 

Mısır’ın çocukları ölüme 

aç

mahzun şimdi

yalanlarla yıkanıyor saraylar

Şehri acıtıyor gövdem

Ve hasretler dağılıyor

gözleri kör eden...', '/Kader gecenin zehri/ Kuşluk vakti görülen rüya susmuş bir şehre boşalıyor gidişiyle korkular dilleniyor Yakup’un gözlerinde Hangi zamanı ku...', ARRAY['Türk Edebiyatı','Şiir','Yakup İncegül']::text[], 8.5, '{"poet":"Yakup İncegül","poet_slug":"yakup-i-ncegul","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/zaman-geceye-sustu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Künyem Zevaldir Benim', 'kunyem-zevaldir-benim-yakup-i-ncegul-8710z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '/Seher vakti zemheri aralıyor kapımı/

Ömrüm güz yaşıyor

isyanımın koyu deminde

Karanfil güzelliği

kumsallara düşüyor

Çağıldıyor âkıbetim bulanık nehirlerde

yargılıyorum dev dişlerini insanlığımın

Şehre kar yağıyor

kum fırtınası dualar iniyor ruhuma

Ay yorgunu bir gözle

Yaşama göz kırpıyor  bedenim

Yazgımdan başkasına çağrılmadım

Kahra gömdüm gözlerimi

Gönlümün söküğünü dikiyor melekler

Gün devrildi..! 

İhanetime vurdum kalbimi

gamzeler çakıyor yenilmişliğim

Sabır sandıklarına koyup çocukluğumu

özgürlüğü arıyorum tutsaklardan...', '/Seher vakti zemheri aralıyor kapımı/ Ömrüm güz yaşıyor isyanımın koyu deminde Karanfil güzelliği kumsallara düşüyor Çağıldıyor âkıbetim bul...', ARRAY['Türk Edebiyatı','Şiir','Yakup İncegül']::text[], 8.5, '{"poet":"Yakup İncegül","poet_slug":"yakup-i-ncegul","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kunyem-zevaldir-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YÜREĞİNE ŞERH DÜŞÜYORUM FİGANIMI', 'yuregi-ne-serh-dusuyorum-fi-ganimi-yakup-i-ncegul-26jj8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'YÜREĞİNE ŞERH DÜŞÜYORUM FİGANIMI

                                                  “Her ayrılışta en az hüzün vardır”

                                                                                    B.Necatigil

/İçimde bir vakti yaktılar/

ölüm haberleri gelir hala gelir hala evimden

yalnızlığı kuşanır bir adam

derinimin içine uzanan mavilerim

bildik ve onurlu bir acıyla değişir ansızın

eksik ve haydut yanlarım

kalın ve bembeyaz bir urganla bağlanır yüreklere

bütün uçurtmalar

bir mektup yollar öteye inat

kanlı bir bıçak gibidir

bir şafakta sökün eder topraktan

bizi dağdan geceye indirir', 'YÜREĞİNE ŞERH DÜŞÜYORUM FİGANIMI                                                   “Her ayrılışta en az hüzün vardır”                       ...', ARRAY['Türk Edebiyatı','Şiir','Yakup İncegül']::text[], 8.5, '{"poet":"Yakup İncegül","poet_slug":"yakup-i-ncegul","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yuregine-serh-dusuyorum-figanimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YOL-CU', 'yol-cu-yakup-i-ncegul-a0ffq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uçsuz bucaksız yalnızlıklarımla 

şehri terkediyor güneş

sahte mutluluklara koşuyor çocuklar

ateşler yakıyor bedenleri

devriliyor kelimeler ruhuma

Biliyorum cennete dönmeyecek baharım

bitecek elbet beklediğim çiçekler

Susmaklığım uyuyor

hayatın şerhidir kelimelerim

okyanus uçlarından çıkardığım kelimeler

tufanımın sesine katılıyor

Şiir zulüm değil

yaşamın arkasına yazılan

Granit düşlere dalmışım deniz kıyısında 

kuşluk vakti kutsuyorum tüm yıldızları

nisan yağmurlarından kalma düşlerim

Kırlangıç yuvalarına tutunmuş yeryüzü

Simurg’un külleri uçuşuyor ölüm çığlığıyla

Karanlığa gömdüm nehirlerimi

yordam bilmeyen şiirler düştü yangıllarıma

yaşamak tükenmekti

insanlar ölümde hala...

/bin yıllık zaman da boğuluyor fırtınalarımda/', 'Uçsuz bucaksız yalnızlıklarımla  şehri terkediyor güneş sahte mutluluklara koşuyor çocuklar ateşler yakıyor bedenleri devriliyor kelimeler r...', ARRAY['Türk Edebiyatı','Şiir','Yakup İncegül']::text[], 8.5, '{"poet":"Yakup İncegül","poet_slug":"yakup-i-ncegul","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yol-cu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nedendir', 'nedendir-arzu-kurt-5ystn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nedendir güneşin doğuşunu

Coşkun dalgaları, yamaçları sevişim

Nedendir yakamozları gördüğümde 

Ya da ıssız bir kumsalı, içimde beliren derinlik alameti

Göz pınarlarıma doluşan elmas yalnızlığı 

Nedendir..

Nedendir bir lale bahçesinin ruhuma sapladığı hançer

Ve akşam kızıllığının denizde

Yaşlı denize bakan yalnız deniz fenerlerinin, 

Sarı sonbahar caddelerinin.

Nedendir eski bir köprünün ıslak ayaklarının nemi yüreğimde

Yağmurun tuhaf kokusu papatyalarda kalan

Sakin bir göle yansıyan sonsuzluk hissi

Nedendir...

Nedendir mayıs akşamları bahar kokunca 

Ve uçurtmalar çocukların elinde dalgalanınca

Böğürtlen toplarken yol kenarlarında

Kır çiçeklerini başıma taç yapınca sersemliğim

Nedendir başımı döndürüşü, beni alıp bırakmayışı 

Nedendir hayatın bu yüzüne bakınca

İçimin ölümsüz kuşlar gibi havalanışı...

Şiir yazmanın mecbur oluşu

Nedendir...', 'Nedendir güneşin doğuşunu Coşkun dalgaları, yamaçları sevişim Nedendir yakamozları gördüğümde  Ya da ıssız bir kumsalı, içimde beliren derin...', ARRAY['Türk Edebiyatı','Şiir','Arzu Kurt']::text[], 8.5, '{"poet":"Arzu Kurt","poet_slug":"arzu-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/nedendir-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuklar, yetim...', 'cocuklar-yetim-arzu-kurt-bpbgp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hüzünlü olur yüzü yetim çocukların 

Yitirilmiş yanları bilinmezde saklıdır

Bir şarkı kesik kesik söylenir dillerinde

Her şiir yarım kalır, yıkık iki dizede...

Hüzünlü olur yüzü yetim çocukların 

Bütün anneler annelerini anlatır

Her çiçek ve gözyaşı, her ev yemeği tadı

Her sevinç kursaklarında takılı kalır

Hüzünlü olur yüzü yetim çocukların 

Acı, söz almaya alışıktır bakışlarında

Kıskanan gözlerini ancak gözyaşı saklar

Ve belki bir kedi yavrusundan örneğin.

Hüzünlü olur yüzü yetim çocukların

Kavuşmalar bir sırdır, sonrasız içlerinde

Özlemse sarılmayan yaradır

Üstü örtüldükçe daha kanayan

Hüzünlü olur yüzü yetim çocukların

Büyüseler de, yüzleri yetim kalır!', 'Hüzünlü olur yüzü yetim çocukların  Yitirilmiş yanları bilinmezde saklıdır Bir şarkı kesik kesik söylenir dillerinde Her şiir yarım kalır, y...', ARRAY['Türk Edebiyatı','Şiir','Arzu Kurt']::text[], 8.5, '{"poet":"Arzu Kurt","poet_slug":"arzu-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/cocuklar-yetim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lösemili Çocuklara', 'losemili-cocuklara-aysenur-yazici-w3wxr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '''Yeryüzü meleği'' diyor annem bana

Kanatlarım incecik, kırılgan..

Çırparken yoruluyorum

Bütün gün köşemde oturuşum işte bundan! 

       Sabahların yaşam kokan havasını odama almak

       Pencereyi açmak yasak..

       Yasak koşmak, ağlamak, koklamak..

                     Üzülmek yasak! 

Şekerlemeler dilimde erimez, 

Gözümde kalır benim

Bedenim denizi özler..vazgeçerim

Karlara bulanmak isterim, 

Bulutları, sırtım çimende seyretmek..Yasak..

Şarkı söylerim

Kendi kendine çırpar ellerim

Kimseye darılmaz, 

Gözüme bir çiçek hapseder..

Günlerce onu seyrederim... 

   

            Yunuslar avcumdaki suda oynar

            Tenimde ıslak kalmış terim..Yasak! 

            Gemiler hep uzak geçer bana

            Ömür nedir ki? ..anlamaz gülümserim.

            ''Yeryüzü meleği'' diyor annem bana 

            Kanatlarım incecik, kırılgan...

Yaşamın ne olduğunu anlamayışım..

..İşte bundan..! 

          25.05.1999

          (12.30)', '''Yeryüzü meleği'' diyor annem bana Kanatlarım incecik, kırılgan.. Çırparken yoruluyorum Bütün gün köşemde oturuşum işte bundan!         Sabah...', ARRAY['Türk Edebiyatı','Şiir','Ayşenur Yazıcı']::text[], 8.5, '{"poet":"Ayşenur Yazıcı","poet_slug":"aysenur-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/losemili-cocuklara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Canlı İlk İnsan', 'tek-canli-i-lk-i-nsan-aysenur-yazici-1t9zy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İncecik bir kar süzülüyor yatağıma

Kollarıma değip eriyor

Soğuk bir ürperti dağılıyor boynumdan

...Aylardan haziran...

           Kiralık odasında sefil bir dul, 

           Yurt köşesinde yoksul bir öksüz, 

           Hastalıktan küflenmiş bir iskelet

         ..Ve daha da beteri

           Dünyada kalan tek canlıymış gibiyim..yazık

Oluk oluk yağmur iniyor yatağıma

Yüzüme çarpıp kulaklarıma doluyor

Sıkıcı bir ferahlık var bedenimde..

..Günlerden perşembe...

              Evladını öldüren bir anne, 

              Körü tekmeleyen bir çocuk, 

              İdamından utanmayan bir mahkum, 

            ...Ve çok daha da beteri, 

             İnsanlardan umduğunu bulamayan

             ''İlk'' insan gibiyim...yazık...! 

03.Haziran 1982', 'İncecik bir kar süzülüyor yatağıma Kollarıma değip eriyor Soğuk bir ürperti dağılıyor boynumdan ...Aylardan haziran...            Kiralık od...', ARRAY['Türk Edebiyatı','Şiir','Ayşenur Yazıcı']::text[], 8.5, '{"poet":"Ayşenur Yazıcı","poet_slug":"aysenur-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/tek-canli-ilk-insan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalkıyorum Artık', 'kalkiyorum-artik-aysenur-yazici-8cfe3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ellerimi koyuyorum bugün yere

..Ve itiyorum toprağı tüm gücümle

Ayaklarım tutar sanarak..

Yere kapaklanıyorum yine.

Buzdan yokuşlar çıktım bugüne dek, 

Kah kayarak, kah emekleyerek

Kalkıyorum artık, 

Topraktan yukarıda başım.

...Ama sendeleyerek..

  

                 31.Ekim 1982', 'Ellerimi koyuyorum bugün yere ..Ve itiyorum toprağı tüm gücümle Ayaklarım tutar sanarak.. Yere kapaklanıyorum yine. Buzdan yokuşlar çıktım b...', ARRAY['Türk Edebiyatı','Şiir','Ayşenur Yazıcı']::text[], 8.5, '{"poet":"Ayşenur Yazıcı","poet_slug":"aysenur-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kalkiyorum-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dinle', 'dinle-aysenur-yazici-lmt6c', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dinle beni bi mührü saki, biraz dinle

İştiyak katre katre azab oldu gönle

Ben kailim, lakin gönlüm sayru ve bunlu

Ve beden derd-mend, ilacı da al bade

                   24.Temmuz 1974', 'Dinle beni bi mührü saki, biraz dinle İştiyak katre katre azab oldu gönle Ben kailim, lakin gönlüm sayru ve bunlu Ve beden derd-mend, ilacı ...', ARRAY['Türk Edebiyatı','Şiir','Ayşenur Yazıcı']::text[], 8.5, '{"poet":"Ayşenur Yazıcı","poet_slug":"aysenur-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/dinle-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vapur', 'vapur-aysenur-yazici-tyae9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Soğuk acıyor yüzümde

İnsanlar itiş kakış

Ve yedi vapuruna yetiştim..

Kalbim boynumda atıyor

Ayaklarım buz, mevsim kış! 

Gözlerim bekleşiyor aralarında

Put gibi kağıt insanların..

Neredesiniz bu akşam 

Yeşil mantolu adam? 

Sizinle dalıyordu yalnızlığım

İş dönüşü akşam denizinde..

İnandım, kalabalıklarda sevgisizdiniz

Yalnızlığınıza dokundum sizin

...Çok sessizdiniz..

Saçlarımız  beyazlanırken gençleştik sizinle

Düşlerimizde nerelerde dolaştık! 

O kadar sevdiniz ki beni

İçim ''hiç''e boşaldı mutluluktan

..Ve derken işte bu akşam

Vapur bomboş..Bir ben

..Bir de o pencere kanarı boş! 

Baktım giderken

Gözümden yaş düştü iskeleye

Elim elimi tuttu

Gönlüm yeşil mantolu adamı unuttu! 

               05.Ocak.1989', 'Soğuk acıyor yüzümde İnsanlar itiş kakış Ve yedi vapuruna yetiştim.. Kalbim boynumda atıyor Ayaklarım buz, mevsim kış!  Gözlerim bekleşiyor ...', ARRAY['Türk Edebiyatı','Şiir','Ayşenur Yazıcı']::text[], 8.5, '{"poet":"Ayşenur Yazıcı","poet_slug":"aysenur-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/vapur-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karşıyaka''da Gece', 'karsiyaka-da-gece-aysenur-yazici-qmx3o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Binlerce metre kumaş sermiş ay

  ..Deniz üstünde herşey yaldız...

           Rüzgar dalgalandırıyor ilmeklerini

                Bense garip kız..

                     Körfezde yalnız

                              06.Haziran 1983', 'Binlerce metre kumaş sermiş ay   ..Deniz üstünde herşey yaldız...            Rüzgar dalgalandırıyor ilmeklerini                 Bense garip ...', ARRAY['Türk Edebiyatı','Şiir','Ayşenur Yazıcı']::text[], 8.5, '{"poet":"Ayşenur Yazıcı","poet_slug":"aysenur-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/karsiyaka-da-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya Sev Yada Öldür', 'ya-sev-yada-oldur-osman-i-nci-r24f8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yılların birikimi, bir hasretle, 

Tarifi imkânsız, sonsuz özlemle, 

Karşılık beklediğim, bu sevgimle, 

Geldim işte; ya sev yada öldür...

Aldım yanıma, bütün umutlarımı, 

Yükledim sırtıma, dert çuvalımı, 

Anlatmak için, sana bu sevdamı, 

Geldim işte; ya sev yada öldür...

Aşkınla volkan misali, yana yana, 

Düştüm senin için, gurbet yoluna, 

Bunca diyar geçtim, nihayet sana, 

Geldim işte; ya sev yada öldür...

Gözümden, kanlı yaşlar dökerek, 

Bütün engellere, göğüs gererek, 

Bilemezsin, ne çileler çekerek, 

Geldim işte; ya sev yada öldür...', 'Yılların birikimi, bir hasretle,  Tarifi imkânsız, sonsuz özlemle,  Karşılık beklediğim, bu sevgimle,  Geldim işte; ya sev yada öldür... Ald...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ya-sev-yada-oldur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bıkmadı Deli Gönlüm', 'bikmadi-deli-gonlum-osman-i-nci-qtfh5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sana aşık olalı, gönlüm açmış bahar, 

Hep seni anlatır, içimdeki duygular, 

Gökten düşmekten, bıktı da yağmurlar, 

Islanmaktan, bıkmadı deli gönlüm...

Her zaman, sonsuzmudur bu sevgiler, 

Böyle delicesine, taparmı sevenler, 

Seni yazmaktan, yoruldu da kalemler, 

Okumaktan, bıkmadı deli gönlüm...

Gözümde canlanır, bir bir anılar, 

Aklıma gelir, yaşanan tüm acılar, 

Seni çalmaktan, usanmış şarkılar, 

Dinlemekten bıkmadı deli gönlüm...

Dilimden düşmez, bir an bile ismin, 

Kalbime sığmaz olmuş, inan sevgin, 

Seyredilmekten, eskidi de o resmin, 

Bakmaktan, bıkmadı deli gönlüm...', 'Sana aşık olalı, gönlüm açmış bahar,  Hep seni anlatır, içimdeki duygular,  Gökten düşmekten, bıktı da yağmurlar,  Islanmaktan, bıkmadı deli...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bikmadi-deli-gonlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'oldurur-beni', 'oldurur-beni-osman-i-nci-26d3l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne varmış gözlerinde, anlayamadım, 

Gözümü onlardan, bir an ayıramadım, 

Günlerce baktımda, yine doyamadım, 

O içli bakışların, öldürür beni...

Kucağında oyuncak, bebek gibisin, 

Öylesine zarif, güllerden güzelsin, 

İnanki güzelim, beni hasta edersin, 

Bu sevdanda birgün, öldürür beni...

Bir tutam perçemin, örtmüş kaşını, 

Yakışıyor sana, kestirme o saçını, 

Bir derdinmi var, eğmişsin başını, 

O mahsun duruşun, öldürür beni...

Dalgın oturmuşsun, ne düşünürsün, 

Bilemiyorum sen, neden üzülürsün, 

Bu halinle beni, derde düşürürsün, 

İçimdeki hasretin, öldürür beni...', 'Ne varmış gözlerinde, anlayamadım,  Gözümü onlardan, bir an ayıramadım,  Günlerce baktımda, yine doyamadım,  O içli bakışların, öldürür beni...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/oldurur-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Şu Geceler', 'ah-su-geceler-osman-i-nci-skvmn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir kâbus gibi, çöker üstüme, 

Birazcık uyku, girmez gözüme, 

Dert ile kederi, salar üstüme, 

Ah şu geceler, zalim geceler...

Bu durgunluğu, ruhumu sıkar, 

Zincir olur, bedenimi sarar, 

Bin derdime, bin daha katar, 

Ah şu geceler, uzun geceler...

Öyle karanlık, öylede esrarlı, 

Her anında, bin bir dert saklı, 

Sabahı ederim, gözlerim yaşlı, 

Ah şu geceler, sessiz geceler...

Mazimi hece hece, önüme serer, 

Anılar yaşandıkça, artar dertler, 

Bir cellat olurda, işkence eder, 

Ah şu geceler, bitmez geceler...', 'Bir kâbus gibi, çöker üstüme,  Birazcık uyku, girmez gözüme,  Dert ile kederi, salar üstüme,  Ah şu geceler, zalim geceler... Bu durgunluğu,...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ah-su-geceler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanımaz Oldu', 'tanimaz-oldu-osman-i-nci-nhfbg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir kor gibiydi, nazlı bakışın, 

İlk görüşümde, kalbimi yaktın, 

İnan, öyle değiştirdiki aşkın, 

Meyhaneci beni, tanımaz oldu...

Dertleşip, hal-hatır sorduğum, 

Kederi unutup, huzur bulduğum, 

Saatler boyu, yalnız oturduğum, 

Masa bile beni, tanımaz oldu...

Senden önceki, vefakâr aşığım, 

Her gece, hasretle sarıldığım, 

Karşısında, beraber ağladığım, 

Şişeler de beni, tanımaz oldu...

Geceleri, derdimi anlattığım, 

Benim, herşeyimi paylaştığım, 

Can yoldaşım ve dert ortağım, 

Kadeh bile beni, tanımaz oldu...', 'Bir kor gibiydi, nazlı bakışın,  İlk görüşümde, kalbimi yaktın,  İnan, öyle değiştirdiki aşkın,  Meyhaneci beni, tanımaz oldu... Dertleşip, ...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tanimaz-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Olur Yaşatın', 'ne-olur-yasatin-yasar-karaman-n8e2q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Takvimler çılgın gibi, acımasız aynalar

Ruhum hatıralarda teselli arar

Yağmurlarla çöreklenir içime

Yapraklar dökülür, heyhat sonbahar.

Böyle başlar kış, mahzun, tedirgin

Irmaklar hüzünlü, denizler engin

Kararıyor ufuklar, fırtına yaklaşmakta

Su almakta yaşlı tekne, son yol belirgin.

Kuruyan ağaçlara bakamıyorum

Sormaktan korkar gibi yaşlı dostları

Çocuklar masallardan yoksun kalmasın

Ne olur yaşatın hatıraları.', 'Takvimler çılgın gibi, acımasız aynalar Ruhum hatıralarda teselli arar Yağmurlarla çöreklenir içime Yapraklar dökülür, heyhat sonbahar. Böyl...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Karaman']::text[], 8.5, '{"poet":"Yaşar Karaman","poet_slug":"yasar-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ne-olur-yasatin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-yasar-karaman-2uyq4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gizemli rüyalardan sonra başlayan sabah

İçinden çıkılmaz düşüncelerim

Sanki anılarımda  bir sisten duvar.

Sabah serinliğinde bir bahçedeyim

Tanıdık ağaçlar, ıslanmış otlar

Bir kuyu başındayım, karanlık, derin

Bu sular, aynı sular.

Sisler içinde bir ev, kapısı açık

Gıcırdayan merdiven, bu ses aşina

Solgun bir kilim, kenarı yırtık

Zamanın kokusu sinmiş sofaya.

Usulca bir kapıyı aralıyorum

Dantel perde, ceviz sandık, hepsi gün görmüş

Anneme sesleniyorum, cevap vermiyor

Babam gibi o da ölmüş.', 'Gizemli rüyalardan sonra başlayan sabah İçinden çıkılmaz düşüncelerim Sanki anılarımda  bir sisten duvar. Sabah serinliğinde bir bahçedeyim ...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Karaman']::text[], 8.5, '{"poet":"Yaşar Karaman","poet_slug":"yasar-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ozlem-99-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanıksama', 'kaniksama-yasar-karaman-1h4xt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her gün baklava, börek

Severdim oysa

İnsan zamanla herşeye kanıksıyor.

Aynı şarkı nasıl bıkkınlık verir

Tozlu bir taş plakta

Hatıradır, saklarsın.

İşte gene akşam oldu kadınım

Birazdan, uzanıp yatacaksın

Yeni heyecanlar istiyor kalbim

Asırlardır çıplaksın.', 'Her gün baklava, börek Severdim oysa İnsan zamanla herşeye kanıksıyor. Aynı şarkı nasıl bıkkınlık verir Tozlu bir taş plakta Hatıradır, sakl...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Karaman']::text[], 8.5, '{"poet":"Yaşar Karaman","poet_slug":"yasar-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kaniksama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acılarımı Zamana Devrettim', 'acilarimi-zamana-devrettim-refik-durbas-51az2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir ses olsun isterdim hatıramda

senin sesin...

Günlerdir bir odaya kitledim bedenimi

hiçbir sokağa düşmüyor gölgem

Günün ve gecenin kapısını kapattım

Alanlara çıkmaktan korkuyorum

bütün anılarımı hapsettim

bir pencerenin pervazına

Kendimi senin sesine...

Dünyanın bütün sesleri 

silinsin isterdim

hatıramdan ve hafızamdan

seninki hariç....

O sese sarınır uyurdum kış geceleri

Yaz serinliğim olurdu o ses

denizlerimin imbatı

dağlarımın meltemi

Bütün bir gün beklemiştim o su kıyısında

su kıyısı dediğim bütün bir dünya

yaşanmış nice hayatlar ve hatıralar.......

Bir başıma, bir ses bekliyordum

bir çalı dibine sığınmıştı bedenim

kalbim sana sığınmıştı

Doğa susmuştu

dağları, vadileri ve ovaları ile

gökyüzü susmuştu

Su susmuştu

Böcekler ve kuşlar ve ağaçlar

ve ağaçların kurumuş dalları da...

Ben sana hapsedilmiştim

Ah! Bir ses olsaydı

ben, bir ses olsaydım

ses olup suda, dağda, ovada

bir de gökyüzünde dursaydım

Sen, kalbimde dursaydın....

Ne kadar bekledim, kim bilir? 

Su ve toprak ve hava

bir de zaman

gökyüzüne ağlıyordu sanki

İşte o an, kalbimi kalbine nakışlayan

sesin geldi, sen geldin

sessizliğin kabuğu çatladı

ve ben de bir ses olarak

aksimi buldum suda ve toprakta

dağda ve ovada ve göklerin yüzünde......

Ses oldum, aksimi buldum sende.....', 'Bir ses olsun isterdim hatıramda senin sesin... Günlerdir bir odaya kitledim bedenimi hiçbir sokağa düşmüyor gölgem Günün ve gecenin kapısın...', ARRAY['Türk Edebiyatı','Şiir','Refik Durbaş']::text[], 8.5, '{"poet":"Refik Durbaş","poet_slug":"refik-durbas","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/acilarimi-zamana-devrettim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akasya', 'akasya-refik-durbas-yn74u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kaderime sardım seni

Memelerinin akasyası

değer değmez dilime

Yüzün düştü yüzüme

Saçlarının kına kokusu

kalbime keder kuyusu

Cinnetin renginde teni

sevdama hazan uykusu

Hüznün düştü hüznüme

O kuyuda uyumak isterdim

cehennem ve cennetini

Ömrüme bakiye çünkü

teninin he zerresi

Kirpiğinde sakla beni

Günün düştü günüme

Yıllar ve yıllar değil

bir bakışınla yaktın

Alevi ayrılığın

anıların minesini

Ah! Acılar hediyesi

Ömrün düştü ömrüme

Kaderine sardın beni', 'Kaderime sardım seni Memelerinin akasyası değer değmez dilime Yüzün düştü yüzüme Saçlarının kına kokusu kalbime keder kuyusu Cinnetin rengin...', ARRAY['Türk Edebiyatı','Şiir','Refik Durbaş']::text[], 8.5, '{"poet":"Refik Durbaş","poet_slug":"refik-durbas","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/akasya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sen bir de Ben', 'bir-sen-bir-de-ben-baris-yavuz-jo5z7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir bogazi izlerken gozlerim kamasir, 

bir de seni

bir kucuk kiz cocugu ile konusurken 

atar kalbim gum gum, 

bir de seninle

bir Bach''i dinlerken huzura erer ruhum, 

bir de senin kalp atisini

bir mavi gokyuzudur unutturan bana tum kederlerimi 

bir de senin o ceviz gozlerin

bir saraptir dudaklarimi oksayip canlandiran

bir de yemis tadindaki dudaklarin

bir olum korkutur beni, 

bir de senin yoklugun

bilmelisin ki can yoldasim 

bir asktir beni sana baglayan 

bir de sen.', 'Bir bogazi izlerken gozlerim kamasir,  bir de seni bir kucuk kiz cocugu ile konusurken  atar kalbim gum gum,  bir de seninle bir Bach''i dinl...', ARRAY['Türk Edebiyatı','Şiir','Barış Yavuz']::text[], 8.5, '{"poet":"Barış Yavuz","poet_slug":"baris-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-sen-bir-de-ben-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aracilar', 'aracilar-baris-yavuz-4o1ii', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Su dari dunyada

cok az seyi 

Su koca evrende

bir cok seyi sevdim

Sevdiklerimle arama

hicbirsey girmesin istedim	

gunesi, ayi ve yildizlari kendime dost bildim, 

aradaki bulutlari ise dusman! 

operayi cok ama cok sevdim, 

perde acilmadan calan uverturleri ise hic! 

sonbahar ile ilk bahar gozumde tuterken, 

araya kisin ve yazin girmesini hic istemedim

baris tutkunuydum... 

dunya barisi icin fikirler de urettim

savas ruzgarlari ile hepsini yitirdim

Tanri''yi ne kadar sevdiysem, 

aracilari, hocalari sevemedim birturlu.

yasam cok degerliydi benim icin

araya giren olum aglatti beni icin icin

seni ise ne kadar cok sevdigimi bilirsin

nefret edisim aradaki mesafelerden 

hep bunun icin', 'Su dari dunyada cok az seyi  Su koca evrende bir cok seyi sevdim Sevdiklerimle arama hicbirsey girmesin istedim	 gunesi, ayi ve yildizlari k...', ARRAY['Türk Edebiyatı','Şiir','Barış Yavuz']::text[], 8.5, '{"poet":"Barış Yavuz","poet_slug":"baris-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/aracilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Askin', 'askin-baris-yavuz-h8dql', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ask da soguk bir olum gibi

ilkin ayak parmaklarindan baslayarak

hissettirirmis o yuzunu, 

sonra tirmanirmis kalbine aheste beste, 

ve bitermis hersey gozlerinde insanin; 

hic bilmezdim! ! 

hic bilmezdim

askinda bir olum gibi basladigini

ve oyle bittigini, 

bilemezdim de

birgun gelecek askim icin

olebilecegimi...		

sen de hayatima iste bu sekilde, 

usulca suzuldun ve girdin

ya sonrasi.....

ilkin

ayaklarimi caldin, 

yolunu unuttum can ciger dostlarimin

sonra

ellerimi, 

dokunmak istemedim senin teninden gayrisina

daha sonra

dudaklarimi, 

annamin bile elini opmeyi unutturdun bana

ondan sonra

gozlerimi, 

bakamaz oldu senden gayrisina

				 

yetmezmis gibi birde hayallerimi caliyorsun simdi, 

oyle ki unutturdun bana

uzerinde gokkusaginin eksik olmadigi, 

kirmizi gelincikler, sapsari papatyalar arasindaki, 

rengarenk kuslarin hanimellerinde otustugu, 

o sekiz kucuk kiz cocuklu 

cennet bahcesindeki evimi.', 'Ask da soguk bir olum gibi ilkin ayak parmaklarindan baslayarak hissettirirmis o yuzunu,  sonra tirmanirmis kalbine aheste beste,  ve biterm...', ARRAY['Türk Edebiyatı','Şiir','Barış Yavuz']::text[], 8.5, '{"poet":"Barış Yavuz","poet_slug":"baris-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/askin-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yuregimin kadini', 'yuregimin-kadini-baris-yavuz-vl2zg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'demirci orsu gibi yuregim 

gohsumde....

sen gorundugunde

kus gibi cirpinir kafesinde

lav yatagi kadar kuru hayatim

onumde....

sen gorundugunde

pinar olur caglar gozelerde

Sair der ki; 

yuregine guveneceksin be kardesim 

su hayatta 

yuregine 

kadinini kesfetmeye 

o kadirdir 

o kadindir ki de 

hayatini senlendirmeye', 'demirci orsu gibi yuregim  gohsumde.... sen gorundugunde kus gibi cirpinir kafesinde lav yatagi kadar kuru hayatim onumde.... sen gorundugun...', ARRAY['Türk Edebiyatı','Şiir','Barış Yavuz']::text[], 8.5, '{"poet":"Barış Yavuz","poet_slug":"baris-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yuregimin-kadini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'evliya celebi ruhlu genc kizlar', 'evliya-celebi-ruhlu-genc-kizlar-baris-yavuz-cys59', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'heey evliya celebi ruhlu genc kizlar 

size sesleniyorum duyun 

dari Istanbul''u gezin gorun 

ola ki kar gibi teninize 

kip kizil saclariniza 

burcu burcu kokan gerdaniniza 

kondurursa kup kuru dudaklariyla opucugunu 

asiklar asigi Baris''i da hos gorun 

askinizla koca yuregine bir ag orun 

orun... 

gorun...', 'heey evliya celebi ruhlu genc kizlar  size sesleniyorum duyun  dari Istanbul''u gezin gorun  ola ki kar gibi teninize  kip kizil saclariniza ...', ARRAY['Türk Edebiyatı','Şiir','Barış Yavuz']::text[], 8.5, '{"poet":"Barış Yavuz","poet_slug":"baris-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/evliya-celebi-ruhlu-genc-kizlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nokta ve Cizgi', 'nokta-ve-cizgi-baris-yavuz-ijjj0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir nokta iken 

o var, ben yokum 

bir cizgi iken 

o vardi, ben vardim 

ama yoktu ondan haberim 

bir cizgi bir nokta iken 

ben ve o aradik birbirimizi 

bir cizgi bir nokta sonra 

reddettim onu uzaklarda 

iki cizgi arasinda bir nokta 

artik o. 

ben iki cizgi arasinda bir nokta iken 

dondum yine ona 

beni son yolculuguma ugurlayacak dostuma 

ben yokum, o var..', 'bir nokta iken  o var, ben yokum  bir cizgi iken  o vardi, ben vardim  ama yoktu ondan haberim  bir cizgi bir nokta iken  ben ve o aradik bi...', ARRAY['Türk Edebiyatı','Şiir','Barış Yavuz']::text[], 8.5, '{"poet":"Barış Yavuz","poet_slug":"baris-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/nokta-ve-cizgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Akasya Çiçeğinde An Beni', 'bir-akasya-ciceginde-an-beni-oktay-yivli-td1e4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Üzümler oldu mu

Bir akasya çiçeğinde an beni

Bir tomurcukta

Bir mavi renkte

Bir tatlı gülüşte an

Bir çocuk beşiğinde bekler

Mutluluğumuz

Bir eski fotoğrafta kalmamalı

Sevgi yaşandıkça güzel

İyi olan ne varsa

Bizim yelkenimize dolmalı

Bundan başka

Ne gemi ne deniz

Hepsi bir büyük yalan

Güz geldi mi

Bir göçmen kuşta an beni

Bir uçarı rüzgarda

-Sararan yapraklarda demeyeceğim-

Her bitiş bir başlangıçtır çoğu kez

Yeşeren ümitlerde an', 'Üzümler oldu mu Bir akasya çiçeğinde an beni Bir tomurcukta Bir mavi renkte Bir tatlı gülüşte an Bir çocuk beşiğinde bekler Mutluluğumuz Bir...', ARRAY['Türk Edebiyatı','Şiir','Oktay Yivli']::text[], 8.5, '{"poet":"Oktay Yivli","poet_slug":"oktay-yivli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bir-akasya-ciceginde-an-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Dalgakıranım Yıkılıyor Bağrımda...', 'dalgakiranim-yikiliyor-bagrimda-naime-erlacin-y94sm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'güneşi sevdim bu sabah

sarıya vurulup 

toprağa ana oldum 

şart oldu sevmek şiiri

dalgakıranım yıkılıyor bağrımda 

nöbete durmuş âşıkça

el değmedik 

vahşi bir harmanda

gözükara sevdalıca gürleyip

açmışım göğsümü dalgalara

değil mi ki şairin hayali 

kıyıdan enginlere açılmak

uçmak şahince sözcüklerle belleğinde

şart oldu o halde 

efkârdan olmalı harcım

sermayem 

yaşamışlığım:

ürpererek dikizlerim ufku 

yoktur silahım gayri 

kuşandığım dilden başka

sözcükler 

cilveli bakire

sözcükler 

sürtük birer fahişe

kırk kapıdan dönmüşlerse bile 

ürkerek dokunup okşamalı

hüzünlüdür kimisi

elemli 

duyarlı

Bâbil bahçeleri misali 

kadimdir bazıları

sözcükler var 

neylesin şair, cihana sığmaz! 

dillerin sultanı 

döşten damıtılır erk sözün baharında

biliriz tutulmaz çatlayan tohum 

en kalın 

en babayiğit kabuklarda

şart oldu o halde sevmek şiiri 

dalgakıranım yıkılıyor bağrımda! 

(15 Nisan 2003)  - Şiirle Monogamik Sevişmeler Dosyasından...', 'güneşi sevdim bu sabah sarıya vurulup  toprağa ana oldum  şart oldu sevmek şiiri dalgakıranım yıkılıyor bağrımda  nöbete durmuş âşıkça el de...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/dalgakiranim-yikiliyor-bagrimda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç', 'hic-elif-uygur-qb5fe', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir kalıntının gözleri olup 

Bakıp tanıyamadığın tarihi

Çığlıklara boğarsın

Kimse duymaz...', 'Bir kalıntının gözleri olup  Bakıp tanıyamadığın tarihi Çığlıklara boğarsın Kimse duymaz......', ARRAY['Türk Edebiyatı','Şiir','Elif Uygur']::text[], 8.5, '{"poet":"Elif Uygur","poet_slug":"elif-uygur","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hic-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Leke', 'leke-elif-uygur-ybebr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir gece ayininde dua olur korkularım

Yeni bir mum yakarım her sönüşte

Duvarda kirler ve gölge....

Saçımdaki elleri ve siyahları

Eskilerden kalma yitik dudakları

Yeniden öptüm bir şiir gibi

Ayin bitti

Karanlık hala havada

Mum lekeleri var beynimde', 'Bir gece ayininde dua olur korkularım Yeni bir mum yakarım her sönüşte Duvarda kirler ve gölge.... Saçımdaki elleri ve siyahları Eskilerden ...', ARRAY['Türk Edebiyatı','Şiir','Elif Uygur']::text[], 8.5, '{"poet":"Elif Uygur","poet_slug":"elif-uygur","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/leke-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzmir Kadınımın Gölgesidir', 'i-zmir-kadinimin-golgesidir-umut-ulbegi-uue17', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Saçların gecedir

bir İzmir gecesidir her salınışın

Deniz Karşıyaka''da iskeleyi okşarken

ellerimiz birleşir

Sıcaklığımızdan yanar koca şehir

Dudakların titrer

Gözlerin kısılır her gece ayrılırken

beni sevdiğini anlarım gözbebeklerinden

ve

sana kendimi adamak için engelsiz kalırım

her engel

senin ellerinde parçalanır birer birer

Benden kopman 

Munzur''un zirvesinde yapayalnız kalmak

senden kopmam 

bir daha hiç sevememem demek

Bu yüzdendir korkum, endişem

Bu yüzdendir her yalnızlıkta senden aşk dilenmem

Yokluğundan beri damarlarımda gezer acı

yokluğun yeni bir yüzyılın başlangıcı

acı yüzyılı

hüzün mevsimi

Anlamı değişiyor yaşamın bak

Anlamı senmişsin meğer

anlaşılmaz dünlerimin

Seni bulunca anladığım

seni tadınca anladığım

Mutluluğun tarifi senmişsin meğer

Sonsuz mutluluğumun.

13.11.2000

Erzincan', 'Saçların gecedir bir İzmir gecesidir her salınışın Deniz Karşıyaka''da iskeleyi okşarken ellerimiz birleşir Sıcaklığımızdan yanar koca şehir ...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/izmir-kadinimin-golgesidir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acı Denizi', 'aci-denizi-umut-ulbegi-qs9l0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yağmuru dinle

kulaklarını yıkasın

yüreğini yakan damlalar

Beni böyle bir günde aldatmıştın

Pişmanlık geçer

Sonun kalır

Herşey geçer

Hayat kalır

14.11.2000

Erzincan', 'Yağmuru dinle kulaklarını yıkasın yüreğini yakan damlalar Beni böyle bir günde aldatmıştın Pişmanlık geçer Sonun kalır Herşey geçer Hayat ka...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/aci-denizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DURMUŞUN TÜRKÜSÜ', 'durmusun-turkusu-osman-oztunc-u45nh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'O her sabah

Gün doğmadan horozlar ötmeden eller uyurken

Erken kalkar cigara yakar, dağlara düşer dağlara hey, 

Nedir kimdir kimseler bilmez, hiç yüzü gülmez

Hiç söz etmez... 

Sakin Durmuş derdik adına, 

Korkarım birgün giderde delmez... 

......Garip birşeyler olmuştu......

Bütün köylüler susmuştu, 

Durmuş erken indi dağdan

..Ve ilk defa konuşmuştu..; 

Eğilin Anadoluya ayak degil kulak verin, 

Neden ağlarmış ninem durun susun ve dinleyin....; 

-Adam şalvarım çarım emeğim terim nasırım kalemim kağıdım yazım, 

Oğlum kızım karım sazım, gaflet çekerken uyudum; 

Çoban kurt oluyor....; 

Tetik düşer can vuruşur can vuruşur.....

Bir yaralı aslanki yurdum devinir durur...

...Çakallar birden hürledi

Yamur yağdı gök gürledi

Üç gün üç gece yağıştan Durmuş gözükmedi 

Dedilerki kuşlar gider taşlar gider başlar gider

iki gözüm Durmuş gider

Gider diyar diyar gider...

Şimdi ürkek dudaklardan dökülürmüş masal masal

Uzun kış gecelerinde

Durmuşun Türküsü Çağlar...', 'O her sabah Gün doğmadan horozlar ötmeden eller uyurken Erken kalkar cigara yakar, dağlara düşer dağlara hey,  Nedir kimdir kimseler bilmez,...', ARRAY['Türk Edebiyatı','Şiir','Osman Öztunç']::text[], 8.5, '{"poet":"Osman Öztunç","poet_slug":"osman-oztunc","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/durmusun-turkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuz Bekleyişler', 'sonsuz-bekleyisler-umut-ulbegi-mpq41', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uçmak istiyorum

göçmek istiyorum sıcak yüreklerin

telaşlı çırpınışlarının duyulduğu

meltemli bir yaz akşamına

önümüz kış

ayazlı sonbaharın ardındaki ulaşılmaz zirve

lapa lapa yağacak kar damarlarıma

her dakikası yaşanarak yaklaşılacak ölüme

her saniye ruhlar kaçış peşinde

Yağmur damlasından kaçıyorum

kaçtıkça aklıma acı yağıyor

Bırakıyorum sırılsıklam bir bedende kupkuru

bir yürek

Yaşıyorum

ansızın gelecek ölümü bekleyerek

20.11.2000

Erzincan', 'Uçmak istiyorum göçmek istiyorum sıcak yüreklerin telaşlı çırpınışlarının duyulduğu meltemli bir yaz akşamına önümüz kış ayazlı sonbaharın a...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sonsuz-bekleyisler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ŞİMALYILDIZI', 'si-malyildizi-turhan-yilmaz-6f31g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ŞİMALYILDIZI

Hayallerim vuslatten yana

Asuman kadar büyük, umman kadar derin.

Ay ve güneş sizin olsun, saizn olsun aydınlık.

Bana Şimalyıldızımı verin.

Ay ve güneş kim? Şimalyıldızı kim? 

Kim kime karışmış, kimden anlayan kim? 

Önce Elif, sonra Lam, daha sonra Mim.

Ay ve güneş sizin olsun, sizin olsun aydınlık.

Bana Şimalyıldızımı verin.', 'ŞİMALYILDIZI Hayallerim vuslatten yana Asuman kadar büyük, umman kadar derin. Ay ve güneş sizin olsun, saizn olsun aydınlık. Bana Şimalyıldı...', ARRAY['Türk Edebiyatı','Şiir','Turhan Yılmaz']::text[], 8.5, '{"poet":"Turhan Yılmaz","poet_slug":"turhan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/simalyildizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmeye Başlayınca Birini', 'sevmeye-baslayinca-birini-metin-altiok-r3oin', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sevmeye başlayınca birini 

kendimi yıkıp yeniden kurarım 

çünkü; 

bu yeni bir aşktır 

ve temeldeki yerini mutlaka alacaktır. 

dikkat! .. 

yabancıların inşaat alanına girmesi tehlikeli ve yasaktır...', 'sevmeye başlayınca birini  kendimi yıkıp yeniden kurarım  çünkü;  bu yeni bir aşktır  ve temeldeki yerini mutlaka alacaktır.  dikkat! ..  ya...', ARRAY['Türk Edebiyatı','Şiir','Metin Altıok']::text[], 8.5, '{"poet":"Metin Altıok","poet_slug":"metin-altiok","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sevmeye-baslayinca-birini-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'seni hiç sevemedim ki', 'seni-hic-sevemedim-ki-baris-guzel-p9tfz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ben istanbulu resimlerden bilirdim, 

askı masallardan, 

derdi ızdırabı filmlerden

bir seni bilemedim, bir de kendimi, 

benim alın yazım, derdim, tasam

karlı dağım

senin için yaşamayı göze aldım.

ben seni hiç sevemedim ki! 

sana taptım...', 'ben istanbulu resimlerden bilirdim,  askı masallardan,  derdi ızdırabı filmlerden bir seni bilemedim, bir de kendimi,  benim alın yazım, der...', ARRAY['Türk Edebiyatı','Şiir','Barış Güzel']::text[], 8.5, '{"poet":"Barış Güzel","poet_slug":"baris-guzel","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/seni-hic-sevemedim-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaybediş', 'kaybedis-asuman-sari-y88op', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İşte yine güneş battı

Zifiri karanlık çöktü yakamozun üstüne

Ben güneşi özlerim karanlığımı aydınlatan

Ben yeşili severim ümitsizliğimi örten

doğayı sevdirsin diye.

İşte bir gün daha bitti

Ne dostluklar silindi istemeden yüreğimde

Mutluluğu özledim gözyaşlarımı sildiren

Gülümsemeye hasretim yıllardır gelmeyen

huzura kavuştursun diye.

Bazen umutsuzca kaybediyorum kendimi

Kime muhtaçlığım bellidir yüzümde 

Benim ayrıcalığım var el’lerden

Bu akşam da bekliyorum, sıkıldım bu evden

gelemicek olmanı bildiğim halde.

Kim yaşamıştır, hasretten ruhun yandığını

Yolu olmadan başka, çaresizce

Kim görmüştür, hiç durmaksızın kabusları

Güneşe eremeyen sonsuz gecelerde

Üstelik ard arda, haince, öldüresiye

Karanlıktayım yine, güneşin ardından gelen

Bir uğur böceği daha uçurdum elimden

Biliyorum

Kaybettiğim güneş çoktaan battı...', 'İşte yine güneş battı Zifiri karanlık çöktü yakamozun üstüne Ben güneşi özlerim karanlığımı aydınlatan Ben yeşili severim ümitsizliğimi örte...', ARRAY['Türk Edebiyatı','Şiir','Asuman Sarı']::text[], 8.5, '{"poet":"Asuman Sarı","poet_slug":"asuman-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kaybedis-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendimi Ağlarken Yakaladım', 'kendimi-aglarken-yakaladim-umut-ulbegi-h44yv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hiç ağlamadım

çok yaklaştım

toprağa bereket olacaktım

Aklımdan

keskin acılarımdan hep kaçtım

hiç ağlamadım

çok yaklaştım

ilk yağmura karıştım

Peşimden koşan rüzgar

içimde esen fırtınalar

ve yaşanamayanlar

sel oldu bedenimde

kendimi 

ağlarken

yakaladım.

15.11.2002

Erzincan', 'Hiç ağlamadım çok yaklaştım toprağa bereket olacaktım Aklımdan keskin acılarımdan hep kaçtım hiç ağlamadım çok yaklaştım ilk yağmura karıştı...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kendimi-aglarken-yakaladim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Demir Kes', 'demir-kes-i-hsan-uncuoglu-davp5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Demir Kes

Aklın yolu bir denmiş gel kes demiri

Hak kime kimlere vermiş böyle ilgi`yi

Sor yanlız sahib`ine günde bu han`a

Aklına gelenle gideni kaç bindi kaç indi, 

*

Kim neyle anılmış ne kalmışsa atadan

Ey fani sana dünyada nicesi arasından

Sorsalar elinde kimden neyin sahibisin

Bu hazır çatılmış mülk seninmi ne dersin, 

*

Haktan akıldan üretim yoksa ne yoldan

Toprağa suya faydan yeniliğin ne yandan

Nice aklın yolu var ki unutulmuş benzer yele

Hiç olmazsa geçmişinden bakarmısın kendine,', 'Demir Kes Aklın yolu bir denmiş gel kes demiri Hak kime kimlere vermiş böyle ilgi`yi Sor yanlız sahib`ine günde bu han`a Aklına gelenle gide...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/demir-kes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'AN OLUR! ...', 'an-olur-ersin-altioglu-5dcxf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'an olur, 

geçmişi hatırlarsın.

hayatın bir film şeridi gibi

geçer gözlerinin önünden.

bazen acıları, 

bazen sevinçleri hatırlarsın.

acılarla kederlenir, 

sevinçlerle hafif gülümsersin.

tam o sırada...

onun unutamadığın hayali gelir aklına.

sevinsem mi üzülsem mi diye düşünürsün.

onu değiştirmeye çalışırsın.

ama nafile...

çünkü onu asla değiştiremezsin.

seni terkedip gittiğini unutmak istersin.

o gurur - yok mu - o gurur...

alır seni o iğrenç kollarına 

engel olur senin ona koşmana...', 'an olur,  geçmişi hatırlarsın. hayatın bir film şeridi gibi geçer gözlerinin önünden. bazen acıları,  bazen sevinçleri hatırlarsın. acılarla...', ARRAY['Türk Edebiyatı','Şiir','Ersin Altıoğlu']::text[], 8.5, '{"poet":"Ersin Altıoğlu","poet_slug":"ersin-altioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/an-olur-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamansız Aşklar', 'zamansiz-asklar-mehmet-fatih-kahraman-8lw9m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir zaman dilimi belirler insan

Ölür, yaşar, yaşamak ister...

Aynı zaman diliminde aşık olur, aşık

Gözlerini kapatırken dünyaya, 

Birden aşklarını getirir gözlerinin önüne ecel.

Neden son bakışlar ölümü degilde aşkı andırır? 

Bir çocuk büyür düşe kalka, 

Hep düştügü günleri hatırlar son bakışlarında.

Son göz yaşı sevgilinin gönlüne akıp gider.

Hep onu düşünür.onu düşler düşlerinde

Ölüm bukadar agırken neden aşkı düşünür insan? 

Aşk dahamı agır sorar kendine, aşık

Agır olan son göz yaşımı acaba? sevgilinin yüregine akıp giden', 'Bir zaman dilimi belirler insan Ölür, yaşar, yaşamak ister... Aynı zaman diliminde aşık olur, aşık Gözlerini kapatırken dünyaya,  Birden aşk...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatih Kahraman']::text[], 8.5, '{"poet":"Mehmet Fatih Kahraman","poet_slug":"mehmet-fatih-kahraman","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/zamansiz-asklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PUSULA', 'pusula-suleyman-sami-cr6s2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İleride belli belirsiz bir ışık, 

Pervaneler üşüşmüş başına, 

Gonca güle dönüşmekte gecenin bu anında, 

Bir meltem esintisi yalar vadiyi, 

Yıldızlar göz kırpar pencereden bakınca. 

Titreyen ellerimle perdeyi araladım, 

Ve durgun bakışlar attım gecenin karanlığına.

Karanlık gecede bir yıldız olmak istedim, 

Yıldızlardan Kutup Yıldızı olmazsa Çoban Yıldızı, 

O zaman iz olurdum, yol olurdum, göz olurdum

Yönünü kaybetmiş insanlara, 

Diye düşündüm', 'İleride belli belirsiz bir ışık,  Pervaneler üşüşmüş başına,  Gonca güle dönüşmekte gecenin bu anında,  Bir meltem esintisi yalar vadiyi,  Y...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Sami']::text[], 8.5, '{"poet":"Süleyman Sami","poet_slug":"suleyman-sami","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/pusula-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'NAFTALİN KOKULU GECELER', 'naftali-n-kokulu-geceler-suleyman-sami-24otk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Naftalin kokulu geceler, rüyalarda dans eder 

Hatırası geçmişin, 

Yaprak yeşili gözlerin kuytularda gezerken

Kendimden geçmişim

Perdeler açıldı aheste, bir çift göz bakar mahzun

O gözleri sevmişim

Sen maşuk musun vuruldum, kanca takılı yüreğime 

Sana çekilmişim

Hesaplarım alt üst oldu, tekledi hayat benim için

Karıncaya ezilmişim

Fırtınalar eser başımda, savurur yaprak gibi

Yönümü şaşırmışım

Figan eder yürek, gökte arar sevdayı yıldızlarla

Hayale kapılmışım

Mecburiyet hayatın bir parçası, yaşamaksa ızdırap

Ruhuma asılmışım 

Yürekte kocaman bir kilit, ellerde çelikten kelepçe

Özgürlüğü satmışım

Öyle bir Leyla ki o, sevdası yakar yüreğimi acı acı 

Mecnuna dönmüşüm

Titrek bakışlar atarken ufuklara derinden

Sevdadan bezmişim

Savruk bir hayat, ardım sıra peşimden gelen 

Bu hayata küsmüşüm', 'Naftalin kokulu geceler, rüyalarda dans eder  Hatırası geçmişin,  Yaprak yeşili gözlerin kuytularda gezerken Kendimden geçmişim Perdeler açı...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Sami']::text[], 8.5, '{"poet":"Süleyman Sami","poet_slug":"suleyman-sami","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/naftalin-kokulu-geceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KAYBOLAN HAYALLER', 'kaybolan-hayaller-suleyman-sami-6fmhn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir düş kurdum, yüreğimde kopan fırtınalarla

Bir ateş yaktım ısınsın diye umutlar

Uzattım ellerimi taaa uzaklara 

Bir an mutlu olsun diye yüreğim. 

Bir an mutlu oldu solgun yüreğim

Bir anlık rüyaymış bu fasıl

Haydi uyan dedi mevsim

Gonca tomurcuğunda soldu, görmedi güneşi

Hayaller tek tek düştü bir yaprak gibi.

Sevdalara çiçek atmıştım, dostluğa ümit

Giden bir hayal değildi giden umutlardı 

Bakakaldım ardı sıra nemli gözlerle

Gerçekler bir sis gibi çöktü ruhuma

Teslimiyet, işte budur gerçek

Yine bohem hayat yine meczup hayaller

Budur bana ondan kalan son emanet

Ve oyun bitti, perdeler kapandı nihayet.

Ne bir yeni senaryo, ne de yeni bir oyun var artık

Ne oyuncu, ne de seyirci var sıralar bom boş

Bakar sahneye kurşun gözlerle umutsuzluk ve yalnızlık

Yıldızlarım gökte parlamıyor artık, ışıklar kayboldu

Uzun geceler ve zifiri karanlık bana dost oldu

Dost olan yalnız bunlar değil bir de ağustos böceği

Gecenin karanlığını yırtan o ince sesi

Bana ninni gibi geliyor kapadıkça gözlerimi. 

Yine bir gece daha bitti sonsuzlukta kaybolan

Büyütülmüş kocaman umutlardı nihayet bulan.', 'Bir düş kurdum, yüreğimde kopan fırtınalarla Bir ateş yaktım ısınsın diye umutlar Uzattım ellerimi taaa uzaklara  Bir an mutlu olsun diye yü...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Sami']::text[], 8.5, '{"poet":"Süleyman Sami","poet_slug":"suleyman-sami","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/kaybolan-hayaller-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umuda Yolculuk', 'umuda-yolculuk-birol-ozkan-fanac', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dertlerimi, hüzünlerimi bıraktım bu şehirde, 

arkama bile bakmadan giderken.

Hangi şehre gittiğimi bile bilmeden.

Kaçmak istedim sadece

mutluluğun olduğu şehirlere

yanımda sadece maviler...

Kalmasın onlar bu şehirde, 

bakmasın kötü gözler, 

bilmesinler seni ne kadar sevdiğimi, 

beni tanımasınlar.

Bırak kötü bilsinler, 

bırak ne derlerse desinler ardımdan.

Bırak yollar açılsın önümüze, 

deniz gelsin, 

deniz geçsin, 

denizi geçelim, 

bitsin artık bu şehir.

İstemiyorum artık tanıdık sahilleri, 

istemiyorum tanıdık yüzleri.

Yabancı bir el uzanmalı bana, 

yabancı bir el çağırmalı beni, 

ben de aşıp gitmeliyim denizi.

Sesi yakından duymalıyım, 

sımsıkı tutmalıyım o eli, 

sanki hiç bırakmakmayacakmış gibi, 

çünkü götürecek beni, belki de tekrar getirecek sana...

ve ilk defa bakıyormuş gibi bakacağım gözlerine, 

ve yine gözlerinde bir umut olacak mavi...

ve hiç bitmeyecek, 

artık umuda yazılacak şiirler.

Hadi tut elimi, 

vakit geldi, bu şehirden de gideceğim, 

ya da son bir kere bak gözlerime, 

ümitsiz yaşatma hüzünler şehrinde.

artık deniz gelsin, 

deniz geçsin, 

denizi geçelim umutlarla..', 'Dertlerimi, hüzünlerimi bıraktım bu şehirde,  arkama bile bakmadan giderken. Hangi şehre gittiğimi bile bilmeden. Kaçmak istedim sadece mutl...', ARRAY['Türk Edebiyatı','Şiir','Birol Özkan']::text[], 8.5, '{"poet":"Birol Özkan","poet_slug":"birol-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/umuda-yolculuk-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GERİDE KALAN...', 'geri-de-kalan-suleyman-sami-mjhj5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Namus kokan gecelerde uçurumun 

kenarında oynardık, 

Bilmezdik ayrılığın bu kadar acı ve 

bu kadar yalnız olduğunu, 

Serperdik umutlarımızı ellerimizle 

uçurumdan yağmur gibi

Bitmeyen umutlarımız ve 

boşalmayan ellerimiz vardı.

Ne de cömerttik ve ne de kaygısız, 

 amaan olsun derdik

Nasıl olsa zenginiz ya, 

hayal ve umut zengini 

O zamanlar her şey bambaşkaydı 

bir mevsim gibi.

Güneş yalnız bizim için doğar, 

 ay bize bakar, 

Yıldızlar bizim için parlar, nehirler 

bize akar sanırdık...

Arkalarından iz bırakarak ve göz

 kırparak.

Bilmezdik hayatın namert ve

 ekşi olduğunu., 

Bilmezdik adam olmanın parayla 

olduğunu, 

Bilmezdik aşkın paslanmış duyguya 

dönüştüğünü.

Her birimizin bir gemisi vardı, 

 devasa hayal gemisi

Neler taşımazdık o gemilerle 

limansız denizlerde

Hani liman arayan da olmadı ya, 

ama yine de 

Hepimizde bir kaptan onuru vardı. 

Sevdaya kurşun sıkmıştık, 

biz merttik, biz erkektik, 

Meçhule giderdik korkusuzca, 

o kadar da cesaretliydik

Günleri saymazdık, zamana meydan 

okurduk umursuzca

Kimin umurundaydı zaman önemli olan 

hayali yaşamaktı o an

Perdeler kapanmazdı, gözlerimiz 

uzaklardaydı parlak bakışlarla

Umudu yakalamak ve hayale

 ulaşmaktı bütün maksat.

Bir gün, bir gün her şeyin 

değişeceğini nerden bilebilirdik

Nerden bilebilirdik farklı bir 

dünyanın olduğunu

Nerden bilebilirdik gündüzün 

gecede kaybolduğunu

Ve nerden bilebilirdik badı sabahın

 artık esmediğini

Burda ne hayale yer var, ne umuda, 

 ne de çokluğa 

Burda gerçekler var kayıtsız ve 

çirkin, acımasız ve dandik

Sevgiler bile sahte, aşklar olmuş 

oyuncak. 

Kimin aldırışında bunlar önemli olan 

günü kurtarmak

Taksit taksit yaşamak, yani zamanla

 pazarlık edercesine, 

Budur burdaki gece ve gündüz, 

budur burdaki hayat

Gölgelere gizlendik yıldızlarda

 kaybolduk

Sinemiz makber oldu o masum 

hayalleri gömdük 

Ya da tenhalarda gezdirdik o saf

 duyguları.

Gemiler battı; batan sadece gemiler 

değildi ne yazık ki

Ufukta kaybolan bir güneşin 

ışıklarıydı 

Bir daha doğmamak üzere...

Artık ne deniz var ne de düş gemisi

Geride kalan, çıplak bir hayat ve 

toz kümesi', 'Namus kokan gecelerde uçurumun  kenarında oynardık,  Bilmezdik ayrılığın bu kadar acı ve  bu kadar yalnız olduğunu,  Serperdik umutlarımızı ...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Sami']::text[], 8.5, '{"poet":"Süleyman Sami","poet_slug":"suleyman-sami","theme":"Türk Şiiri","is_hero":false,"total_lines":79,"source_url":"https://www.antoloji.com/geride-kalan-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ŞAMDAN VE MUM IŞIĞI', 'samdan-ve-mum-isigi-suleyman-sami-1y4rv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaprak dökümü bir hayat 

Zindanlar esirini bekler namussuzca

Bir fırtına esmektedir avare ve sefil

Başlardan eksik olmayan bir poyraz

Meydanı boş buldu asi geceler

Cirit atmaktadır sağlı sollu kaygısızca

Sanki Nemrud’a nisbet yaparcasına

Beyaz ve siyah dans etmekte tezatlar sahnesinde

Hayasız geceler ıslık çalar sevinçle

Ey merhamet! yitirilen duygu neredesin çık ortaya

Patlat naranı kalplerde duyulsun heybetin açıkça

Ve titresin yürekler korksun köhnemiş zalimler...

Ey! asıl an’a uzak zaman! her şey tersyüz olmuş

Değişmeyen tek şey şamdan ve mum ışığı

Virane olmuş sevgiler sefilleşmiş aşklar

Yönünü kaybetmiş bir meczuba benzerler

Mecnun Leyla’sını kaybetti Leyla’da Mecnun’unu

Çölün ıssızlığında bir daha bulmamak üzere 

Ve mukavemet erimektedir günden güne

Bir yıldızın güneşin ışığında kaybolduğu gibi.

Yakamozlar yok artık, şarkı söyleyen dalga da

Beklemekte her şey sonsuzluğun başlangıcını

Yaprak rüzgarını bekler vuslata kavuşmak için

Bekleyen birisi daha var soğuk bir kış gecesi

Titrer zavallı biçare dişlerini birbirine vurarak

Neredesin ey! Fırat’ın kenarında kuzuyu kurt kaparsa

Müsebbibi benim diyen timsal kişi

Neredesin ey! ferahlatıcı ılık meltem

Ve neredesin ey kara bulutların arkasına gizlenen şefkat

Anka kuşuna binip Kafdağı’na mı göç ettiniz? 

Sessizlik ondan mıdır yoksa, bu zindan sessizliği! 

Hicret eden ey ulvi duygular, lala çevirdiniz hayatı

Gül bile açmaz oldu dalında, bülbüle sitem etmekte

Bülbülse beklemekte gülünü sabırla ve umutla

İnsanlık istifada, istifada insanlık kimin umurunda 

Çirkef hayat dost olmaktadır an be an bu insanlığa

Zaman koşmaktadır ardına bakmadan sonsuzluğa doğru

Nerede gören göz nerede muhakeme eden akıl

Ve nerede gözlerde yaşla semaya açılan avuçlar

Meçhule giden bir gemi gibi gözden kaybolmaktadır fısıltı

Sapır sapır dökülmektedir dutun dalından döküldüğü gibi', 'Yaprak dökümü bir hayat  Zindanlar esirini bekler namussuzca Bir fırtına esmektedir avare ve sefil Başlardan eksik olmayan bir poyraz Meydan...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Sami']::text[], 8.5, '{"poet":"Süleyman Sami","poet_slug":"suleyman-sami","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/samdan-ve-mum-isigi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TUFAN', 'tufan-suleyman-sami-1lnm7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bekliyorum seni infazımı bekler gibi

Sana mahkum oldum sense bir zindan 

Vuslata beş kala ayrılık rüzgarı esti

Her şeyi silip süpürdü insafsız bir tufan', 'Bekliyorum seni infazımı bekler gibi Sana mahkum oldum sense bir zindan  Vuslata beş kala ayrılık rüzgarı esti Her şeyi silip süpürdü insafs...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Sami']::text[], 8.5, '{"poet":"Süleyman Sami","poet_slug":"suleyman-sami","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/tufan-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KİBRİT VE MUM İŞIĞI', 'ki-bri-t-ve-mum-i-sigi-suleyman-sami-xc1ip', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gafil gecelerde kurulmuş pusu ve oyuncağı olmuştur nefsinin

Acımasız saldırılar art arda devri dönmüştür kalbinin 

Pişmanlık bulutları peşi sıra göz yaşı akıtmaktadır adına

Bir ışık var ki zulmeti nura döndüren parlamaktadır başına

Geceler uzun geceler sevdasına çullanmışlar yorgun yapraklar gibi

Yüreğinde volkan kaynar düşüncelerinde patlar sessizce her biri

Geçmişini arayan adamdır o, elinde kibrit, mum ışığına müptela

Karanlığı delmek ziyaya ulaşmaktır ve bembeyaz bir sayfaya

Hain gecelere av olmuştur her şey sefil, kalbinde katran karası

Bir ümit, bir terazi ve taşımaktadır borç defteri onun yürek kasası

Nedamet denizine kavuşmaktır tüm arzusu sakin ve sessizce

Son isteği vardır gönlünde açmak ister af dileyen bir pencere

Korku içinde ümitle yaşamaktadır hayatı an be an pervasızca 

Nedir bu hayat? nedir ki bu zaman? beyaz bir kuş kanadında

Akıp giden ömürdür bir sermaye ki talana mahal vermeyen

Ah! ne büyük iştiyak, bir adam olmak ister tövbe elbisesini giyen

Sonsuzluk kamçısı inmeden sırtına tutmak ister zamanı tövbesiyle

Sızlar geceler, göz yaşı akıtır saatlerce siler gözünü perçemiyle

Bir daha yapmamak üzere tövbe etmiştir o adam beyaza atmış kanca

Artık merhameti sonsuza sığınmıştır kapamıştır gözlerini açmazcasına', 'Gafil gecelerde kurulmuş pusu ve oyuncağı olmuştur nefsinin Acımasız saldırılar art arda devri dönmüştür kalbinin  Pişmanlık bulutları peşi ...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Sami']::text[], 8.5, '{"poet":"Süleyman Sami","poet_slug":"suleyman-sami","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kibrit-ve-mum-isigi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı Konul-a-mayan Şiir', 'adi-konul-a-mayan-siir-serdar-tuncer-k7zwf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güldüğün gün yaratıldı gülmeler

Kelime var oldu konuştuğun an

Yoktu ağlamasan göklerde keder

Yalnızlık bir hiçti yalnız kalmasan

Gönlüne borçludur aşk ahengini

Yaşadın diye var zaman ve mekan

Seninle tanıdı her şey kendini

Var bile bir yoktu sen var olmasan', 'Güldüğün gün yaratıldı gülmeler Kelime var oldu konuştuğun an Yoktu ağlamasan göklerde keder Yalnızlık bir hiçti yalnız kalmasan Gönlüne bor...', ARRAY['Türk Edebiyatı','Şiir','Serdar Tuncer']::text[], 8.5, '{"poet":"Serdar Tuncer","poet_slug":"serdar-tuncer","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/adi-konul-a-mayan-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'nedamet', 'nedamet-suleyman-sami-yw6sb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayatın mecazını yaşamaktayım ben kendim değilken

Gülistanı poyraza verdim sermaye gitti elden

Bir rüyaydı yaşadığım, renkli dünyalarda gezerken

Ararım kaybolan anahtarımı kilit elden gitmeden', 'Hayatın mecazını yaşamaktayım ben kendim değilken Gülistanı poyraza verdim sermaye gitti elden Bir rüyaydı yaşadığım, renkli dünyalarda geze...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Sami']::text[], 8.5, '{"poet":"Süleyman Sami","poet_slug":"suleyman-sami","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/nedamet-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HASBİHAL', 'hasbi-hal-demirel-ahmet-iiejw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dün gibi gelir bana, tanıştığımız o gün, 

şimdi kalbimde hüzün

gözlerimden okunur.

Aşkın baharında değilim, 

içindeyim; 

biliyorum artık güzün.

Beni kahreder bir tek sözün; 

seni sevmiyorum.

Benim sonum mu? 

Belli...

Hüzün... Hüzün...', 'Dün gibi gelir bana, tanıştığımız o gün,  şimdi kalbimde hüzün gözlerimden okunur. Aşkın baharında değilim,  içindeyim;  biliyorum artık güz...', ARRAY['Türk Edebiyatı','Şiir','Demirel Ahmet']::text[], 8.5, '{"poet":"Demirel Ahmet","poet_slug":"demirel-ahmet","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/hasbihal-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirim Özgürlük', 'siirim-ozgurluk-i-hsan-topcu-krckl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bu ne kuştur böyle her yeri kanat

gündüzleri uçururum gökyüzüne 

gök şenlenir

her gece döner yüreğime', 'bu ne kuştur böyle her yeri kanat gündüzleri uçururum gökyüzüne  gök şenlenir her gece döner yüreğime...', ARRAY['Türk Edebiyatı','Şiir','İhsan Topçu']::text[], 8.5, '{"poet":"İhsan Topçu","poet_slug":"i-hsan-topcu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/siirim-ozgurluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Uzun Bir Öykü-1-', 'cok-uzun-bir-oyku-1-atila-gunal-rq3yb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne zaman başladı bilen yok

Benim sana sevdam.

Ben doğmadan önce, 

Henüz bir cisim bile değilken yeryüzünde

Sevgim yeşermişti topraktan.

Biliyorum benden önce de vardı, 

Benden sonra da sürecek sana sevdam.

2003-04-15', 'Ne zaman başladı bilen yok Benim sana sevdam. Ben doğmadan önce,  Henüz bir cisim bile değilken yeryüzünde Sevgim yeşermişti topraktan. Bili...', ARRAY['Türk Edebiyatı','Şiir','Atila Günal']::text[], 8.5, '{"poet":"Atila Günal","poet_slug":"atila-gunal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/cok-uzun-bir-oyku-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
