INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşadınız', 'yasadiniz-yasar-karaman-62ona', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yıllarca güneşin doğuşunu gözlemekten

Bıkmadınız

Havanız hep ortakdı.

Bazen suyun tadının

Çiçeklerin ve iyiliklerin

Farkına varmadınız.

Kiminiz sefil, sokaklarda

Kiminiz zengin sofralarda

Elbette yaşadınız.', 'Yıllarca güneşin doğuşunu gözlemekten Bıkmadınız Havanız hep ortakdı. Bazen suyun tadının Çiçeklerin ve iyiliklerin Farkına varmadınız. Kimi...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Karaman']::text[], 8.5, '{"poet":"Yaşar Karaman","poet_slug":"yasar-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yasadiniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatıralarım', 'hatiralarim-semih-sevli-gewb8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerimdeki o parlayan ışıltıyı, 

