INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'icoşum', 'icosum-ferdi-cidan-sc3lx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevin sevmek şeker gibidir tatlıdır.Ama aldanmayın sevmeyene....', 'Sevin sevmek şeker gibidir tatlıdır.Ama aldanmayın sevmeyene.......', ARRAY['Türk Edebiyatı','Şiir','Ferdi Çidan']::text[], 8.5, '{"poet":"Ferdi Çidan","poet_slug":"ferdi-cidan","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/icosum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Affet Beni Anne (Bir Özürlü Şiir)', 'affet-beni-anne-bir-ozurlu-siir-hayrettin-turk-qbzyz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Affet beni anne

Ölmediğim için…

Ümitsiz hastalar için hani

Yazılmış türküler vardır

Kısa sürmüş acı öyküleri

Yarım kalmış aşkları anlatırlar

“hastane önünde incir ağacı

doktor bana bulamadı ilacı…”

Baharın beklide en güzel gününde doğmuşum

Sana yaşatabildiğim tek mutluluk

Ağlayan sesim olmuş annem

Sonrasını kimseler bilmez

Sen bilirsin

Ben bilirim annem…

Beklide en son bahar günüydü o

Ölümün kol gezdiği bir meydanda

Direkten dönmüş bir top gibi

Nasıl olduysa ölmemiştim

Biliyorum, 

Ben değildim beklediğin

Ve gene biliyorum annem

Gelmek isteyende ben değildim…

Ölür dedi doktorlar

Sen tıbbi terimleri ezberledin 

ben kuvözleri

Ben hep ölmeyi dilerken 

Sen dualar ettin  yaşamam için

Oysaki bilemezdin annem

Ölseydim 

Bir gün gene fark edecektin

Baharın güzelliğini…

Onca baharsız yıl geçti

Hep gözlerimde aradın

Baharın o en güzel günlerini

Benim gözlerimde bahar

Senin gözlerinde kırışıklar

Bahar ama

Sonbahar…

Biliyorum

Üf demedin bir gün

Sitem etmedin kaderine

El oldun, ayak oldun

Ağız oldun, dil oldun

Beklenmeyen misafirine…

Güneşin batmadığı bir yurtta

Sana hep aydınlık şiirleri yazmak isterdim

Biliyorum

Sen genede o şiirleri buluyorsun anlamsız gülüşlerimde

Her ne kadar yüreğinde ısınmakta olsada toprak

Cemreler baharı işaret etsede annem

Ben ya beklediğin kişi, 

Yada hiç yaşamamış olmak isterdim…

Affet beni anne

Ölmediğim için…

Şubat 2003', 'Affet beni anne Ölmediğim için… Ümitsiz hastalar için hani Yazılmış türküler vardır Kısa sürmüş acı öyküleri Yarım kalmış aşkları anlatırlar...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Türk']::text[], 8.5, '{"poet":"Hayrettin Türk","poet_slug":"hayrettin-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/affet-beni-anne-bir-ozurlu-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yiğidin Alın Teri', 'yigidin-alin-teri-cemal-safi-yee73', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Karnını doyurmuyor yiğidin alın teri! ...

Her ay yeni bir paye şekere de una da, 

Dokunulmaz olacak suya da sabuna da.

Kimi fazla göbeği atarken saunada, 

Kimi canlı cenaze, bir kemik bir de deri! 

Karnını doyurmuyor yiğidin alın teri! ...

Vergiye mecbur eden tanısaydı insafı, 

Bu kadar ezer miydi, üzer miydi esnafı? 

Baykuşun şenlik sesi çınlatıyor etrafı, 

Gelirine beş basar maaşlının gideri! 

Karnını doyurmuyor yiğidin alın teri! ...

Ekonomi atının jokeyi bile piyon, 

Gemi azıya almış koşuyor enflasyon! 

Kiminde yamalı don, kiminde Paris losyon, 

Hangi çağda yaşanmış bu tezattan beteri? 

Karnını doyurmuyor yiğidin alın teri! ...

Ya nüfus patlaması! Öyle dev bir alev ki! 

Yangını körüklüyor fukaranın tek zevki! 

Uykudan aziz gelir ne mukaddes görev ki! 

O kadar kaldıramaz yüz gramlık halteri! 

Karnını doyurmuyor yiğidin alın teri! ...

Vatanın imdadına koşarken çingenesi, 

Kanını sömürmekte binlerce kıç kenesi! 

Kınamaktan yoruldu Cemal’in saf çenesi, 

Bu kadar kara mıydı Türkiyemin kaderi...

Karnını doyurmuyor yiğidin alın teri! ...', 'Karnını doyurmuyor yiğidin alın teri! ... Her ay yeni bir paye şekere de una da,  Dokunulmaz olacak suya da sabuna da. Kimi fazla göbeği ata...', ARRAY['Türk Edebiyatı','Şiir','Cemal Safi']::text[], 8.5, '{"poet":"Cemal Safi","poet_slug":"cemal-safi","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yigidin-alin-teri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gizli Aşk', 'gizli-ask-hayrettin-turk-tfrm0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bulutsuzdur hep apaydın gözlerim

Tatlandırır yanakları sözlerim

Bilmez kimseler içimde gizliyi

Neşe içinde neşemi özlerim...

Gülmek bir alışkanlık çocukluktan

Hep tatlı kahkahalar içindeyim

Bilmez kimseler seni sevdiğimi

Kahkahalarımla hep peşindeyim...', 'Bulutsuzdur hep apaydın gözlerim Tatlandırır yanakları sözlerim Bilmez kimseler içimde gizliyi Neşe içinde neşemi özlerim... Gülmek bir alış...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Türk']::text[], 8.5, '{"poet":"Hayrettin Türk","poet_slug":"hayrettin-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gizli-ask-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canlıydı Dedemin Bastonu', 'canliydi-dedemin-bastonu-hayrettin-turk-p5056', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Eskimiş köhne evimizden dedem

İlk defa bastonu olmadan çıktı

Dedemin nurlu elinde o baston

Bilirim cami yoluna aşıktı...

Bazı bastonlar vardıki sahipsiz

Ezanlarda yürekleri sızlardı

İnanırım dedeminde bastonu

Dedemle güler dedemle ağlardı...

Namaz sonrası tatlı sabahlarda

Yaşlıların sohbetlerinde yaşardı

Karlı havalarda üşüse dedem

Yerin özünden sıcaklık toplardı...

Bir gün, bir sabah ezanında

Her zamanki gibi yola hazırdı

Gelmeyince dedem, çıldırdı birden

Gördüm bastonu, yerleri kazırdı....

Eskimiş köhne evimizden dedem

İlk defa bastonu olmadan çıktı

Öğle ezanında bahçe kapımız

bir bastona dayalı ve açıktı...

20.12.1986', 'Eskimiş köhne evimizden dedem İlk defa bastonu olmadan çıktı Dedemin nurlu elinde o baston Bilirim cami yoluna aşıktı... Bazı bastonlar vard...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Türk']::text[], 8.5, '{"poet":"Hayrettin Türk","poet_slug":"hayrettin-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/canliydi-dedemin-bastonu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Heyname', 'heyname-hayrettin-turk-e0ei3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hey insanlar, insanlar dinleyin hey

Yüreğimde sevdalı dinleyin hey

Tutulmuşum bir karlı fırtınaya

Dinleyip feryadımı inleyin hey

Dağlar, yüce dağlar hey

Üstüme gelmeyin hey...

Dağlar, başı dumanlı, karlı dağlar

Bırakın, yüreğim sevdalı dağlar

Gözüm kara, derdim belalı dağlar

Boyun eğip, aşkımı dinleyin hey

Rüzgarlar, rüzgarlar hey

Çılgınca esmeyin hey...

Rüzgarlar, alın götürün dertleri

Susturun şu beynimdeki cinleri

Söyleyin de aşk dolu türküleri

İsterseniz aşk nedir bilmeyin hey

Dinleyin, dinleyin hey

Aşk nedir dinleyin hey...

30.12.1986', 'Hey insanlar, insanlar dinleyin hey Yüreğimde sevdalı dinleyin hey Tutulmuşum bir karlı fırtınaya Dinleyip feryadımı inleyin hey Dağlar, yüc...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Türk']::text[], 8.5, '{"poet":"Hayrettin Türk","poet_slug":"hayrettin-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/heyname-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KORKUYORUM', 'korkuyorum-seref-kaya-6s9tu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Korkuyorum; bu gecelerden, 

Birakip, tek basima gidersen.

Ya! terk edersen beni sen.

Gün dogmamaya bilir gülüm.

Ya beni al, götür ya gitme! 

Korkularim; öldürüyor beni, 

Sensiz bir gece düsünemiyorum.

Gün dogmamaya bilir gülüm.

                                                       seref kaya', 'Korkuyorum; bu gecelerden,  Birakip, tek basima gidersen. Ya! terk edersen beni sen. Gün dogmamaya bilir gülüm. Ya beni al, götür ya gitme! ...', ARRAY['Türk Edebiyatı','Şiir','Şeref Kaya']::text[], 8.5, '{"poet":"Şeref Kaya","poet_slug":"seref-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/korkuyorum-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KÜÇÜK KIZ', 'kucuk-kiz-aysegul-sipahioglu-i8l8b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Elindeki şekerinle

Göz yaşların arasında kalan

Hayallerin bende 

Küçük kız.

Gök yüzünde uçurtmanla

Bulutlar arasında kalan

Düşlerin bende

Almaya gel küçük kız.

Seni tanımadığım için mi 

Benden kaçarsın, 

Yoksa adın gibi 

Sende mi bana yabancısın? 

Korkma benden, 

Senin gibi bende

Göz yaşlarımla erittim şekerimi

Ve takılı bıraktım hayallerimi

Hiç tanımadığım siyah bulutlara.

Hepsi gittiler artık

Bir tek sen ve ben kaldım.

Hadi uyan artık…..', 'Elindeki şekerinle Göz yaşların arasında kalan Hayallerin bende  Küçük kız. Gök yüzünde uçurtmanla Bulutlar arasında kalan Düşlerin bende Al...', ARRAY['Türk Edebiyatı','Şiir','Ayşegül Sipahioğlu']::text[], 8.5, '{"poet":"Ayşegül Sipahioğlu","poet_slug":"aysegul-sipahioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kucuk-kiz-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KÜÇÜK KIZ', 'kucuk-kiz-kudret-akpinar-6qtfg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Elindeki şekerinle

Göz yaşların arasında kalan

Hayallerin bende 

Küçük kız.

Gök yüzünde uçurtmanla

Bulutlar arasında kalan

Düşlerin bende

Almaya gel küçük kız.

Seni tanımadığım için mi 

Benden kaçarsın, 

Yoksa adın gibi 

Sende mi bana yabancısın? 

Korkma benden, 

Senin gibi bende

Göz yaşlarımla erittim şekerimi

Ve takılı bıraktım hayallerimi

Hiç tanımadığım siyah bulutlara.

Hepsi gittiler artık

