INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğüt', 'ogut-yusuf-canturk-2zx3b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Delikanlı çağında şeytana uyma, 

Kırk yılın sonunda pişmanlık duyma! 

Her şeyin yok olup giderse, elini koynuna koyma, 

Hayal ile gerçeği, sakın, karıştırıp durma! 

Güzele bakmayı, sakın, zararsız sanma. 

Ayıp mı, sevap mı diye kararsız kalma, 

Tutulma bir anda yıldırım aşkına! 

Hesapta yoktu böylesi diye dönme şaşkına! 

Varsa gençlik kudretin vade nedir bilemezsin, 

Yaş kemale erince, güne, gün eklersin, 

Az mı, çok mu zamanın, endişeyle beklersin. 

Yılların izlerini istesen de silemezsin! 



 Gülcüklerden  yılma,  olma  ümitsiz, 

Hız  sınırını  aşma,  olma  limitsiz.

Başarısız  oldum  diye  saçlarını  yolma,

Sağlık  gibisi  yok,  sakın  hastalanıp  solma.

^Yoksul isen ne sigortan olur, ne de güvence, 

Düşünmelisin geleceğini inceden ince! 

Eğer tembellik varsa yapında ve de başında, 

Çok çalışıp gayret göster genç yaşında. 



 her şeyi  birlim  diye  ortaya  çıkma,

Bilemezsen  eğer  utanma,  canını  sıkma.

Bilmediğin  şeyleri  bir  bilene  sor  anla,

Her  sorunun  cevabı  bilgi  dağarcığında  biriken  bir  damla.



 Sırrın  varsa  sakın  açma  dostuna,

Kurt  olurda  bürünür  kuzu  postuna.

Eş  ve arkadaş  seçiminde  hatalar  yapma,

Kötüler  örnek  olmaz, doğruluktan  şaşma! 



Bir   gayen  olsunda  elde  etmeye  çalış,

Kabul  etki  yaşam  büyük  bir  yarış.

Geç  yatsan  bile  erken  kalkmaya  alış,

Düşün  ki  kefenin  ebadı  sadece  beş  karış! 



Yaşlılara  saygı  göster,ananeyi  unutma,

Kolay  yola  sapıp  haram  lokma  yutma.

Cimri  değil,  tutumlu  ol,muhtaç  olma  namerde,

Yalnız  bırakma  eşini,  dostunu, bilghassa,kederde.

Kazancını  savurma,  harcama  kumara  içkiye,

Sigara  içme  sakın,  pek  de  zararsız  diye.

Sermayeyi  üfleme  havaya,  yükleme  kediye,

Öğüdüme  kulak  ver,naçizane,  benden  sana  hediye! 

   Yusuf  Cantürk(E.Hv.Kur.Alb.) Kadıköy-2003



Yusuf Cantürk









                              

                                                                       Kadıköy-2003', 'Delikanlı çağında şeytana uyma,  Kırk yılın sonunda pişmanlık duyma!  Her şeyin yok olup giderse, elini koynuna koyma,  Hayal ile gerçeği, s...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Cantürk']::text[], 8.5, '{"poet":"Yusuf Cantürk","poet_slug":"yusuf-canturk","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/ogut-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Getirmedin', 'getirmedin-mehmet-bor-dnifw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aklıma getirmeyeceğim, 

demiştim.

Ayrıldığımız o gün.

Başarmıştım.

Ya da öyle sanıyordum.

Ta ki karşılaştığımız, 

güne kadar.

Zaman fazla bir şey almamış.

Saçlarında oluşan kırlar..

Az da olsa kilon vardı.

Olgunluk ta yakışmış.

Gözlerin eskisi gibi canlı.

Ürkekliğin..

O değilmiy di, beni çeken

Senelerce..

Sürüm, sürüm süründüren.

Kızın, tıpkı sen.

Hani derler ya, 

Hık demişte burnundan düşmüş.

Oğlunu..benzetemedim kimselere

Oysa.yedi sülaleni tanırım.

Tek tanımadığım, Beyin.

Evlendiğinizde de kaçmıştım buralardan.

Sonradan öğrendim.

''Getirmeyeceğim'' diye söylediğini.

Sözünde durdun.

Her zaman ki gibi, 

Hiç bir zaman getirmedin o''nu.

Mehmet BOR

09.05.2003', 'Aklıma getirmeyeceğim,  demiştim. Ayrıldığımız o gün. Başarmıştım. Ya da öyle sanıyordum. Ta ki karşılaştığımız,  güne kadar. Zaman fazla bi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bor']::text[], 8.5, '{"poet":"Mehmet Bor","poet_slug":"mehmet-bor","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/getirmedin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Alem', 'ne-alem-mehmet-bor-nz4sf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kimbilir...

Alemde neler oluyor? 

Gecenin grileştiği, 

şuan da.

Bir çığlık atıyor, 

belki de bir kadın.

Belki de yüksek bir kaldırımdan.

Kayıyor bir yıldız.

Belki de bir genç kız, 

masumiyetini kaybediyor.

Belki de bir el, 

bir kapıyı zorluyor..

çalmak için.

Bir bebek feryatla, 

duyurmak istiyor kerdini.

Bir baba, gece vardiyasın da, 

düşünüyor evdekileri.

Bir mahpus.

Pazartesi''yi bekliyor..

özgürlük için.

Göçmen kuşlar...

Gecikenleri bekliyor sabırsızca.

Kimileri sadaka umuduyla, 

bekliyor..

Eğlenceden dönenleri.

Bekçiler sabahı.

Demiryolcular bir sonra ki, 

treni.

Gelen, gideni.

Giden, geleni.

Klakson sesleriyle, 

yuvaya uçan gelini.

Nöbetden dönen anayı.

Kavuşmak için günleri.

Kor düşen yürekleri.

Beklese de, nafile..

dönmeyecekleri.

Ey alem...

Nasıl bir alemsin.

Seni yazmak, 

Seni nitelemek..

Çok...ama çok zor.

Sana sevgi demek, 

Aşk demek.

Hepsinden öte, 

Sana, vuslat demek.

Mehmet BOR

03.05.2003', 'Kimbilir... Alemde neler oluyor?  Gecenin grileştiği,  şuan da. Bir çığlık atıyor,  belki de bir kadın. Belki de yüksek bir kaldırımdan. Kay...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bor']::text[], 8.5, '{"poet":"Mehmet Bor","poet_slug":"mehmet-bor","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/ne-alem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Var Olmalı', 'var-olmali-salim-solmazgul-u4vxm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gel kardeşim cahil olma

Dağ başında kar olmalı

Gerçeklerden kaçılır mı

Kaçanlar hep kör olmalı

Konuşalım peşin peşin

Kölelik mi senin işin

Sen insansın iyi düşün

İnsanoğlu hür olmalı

Ah ne olur bir uyansan

Bak halimiz çok perişan

Ezdirmez kendini insan

Gafil gezmek zor olmalı

Solmazgül üm dert ilacı

Dilim tatlı sözüm acı

Akıldır insanın tacı

Her kafada var olmalı', 'Gel kardeşim cahil olma Dağ başında kar olmalı Gerçeklerden kaçılır mı Kaçanlar hep kör olmalı Konuşalım peşin peşin Kölelik mi senin işin S...', ARRAY['Türk Edebiyatı','Şiir','Salim Solmazgül']::text[], 8.5, '{"poet":"Salim Solmazgül","poet_slug":"salim-solmazgul","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/var-olmali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan Sevgisiyle Doldum Erenler', 'i-nsan-sevgisiyle-doldum-erenler-salim-solmazgul-oyrwb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir hayal peşinde yıllarca koştum

Sonunda kendimi buldum erenler

Aşkın şarabından içince coştum

İnsan sevgisiyle doldum erenler

Bu koca dünyaya geldim geleli

Dertliyim kendimi bildim bileli

Cehalete düşman oldum olalı

Bir başıma yalnız kaldım erenler

Yüreğimi aşkın narıyla yakıp

Kibir kalesini temelden yıkıp

Aşkın aynasından kendime bakıp

Bir Salim Solmazgül oldum erenler', 'Bir hayal peşinde yıllarca koştum Sonunda kendimi buldum erenler Aşkın şarabından içince coştum İnsan sevgisiyle doldum erenler Bu koca düny...', ARRAY['Türk Edebiyatı','Şiir','Salim Solmazgül']::text[], 8.5, '{"poet":"Salim Solmazgül","poet_slug":"salim-solmazgul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/insan-sevgisiyle-doldum-erenler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çelik Yürek', 'celik-yurek-naime-erlacin-3ppc4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'düşünce üretmeli ıssızda 

düşler sancılandığında

çelikten dokunmalı yürek

eskimemeli kuytuda

suyla beslenir toprak

bilirim 

suyla oyulur kısırlığa

kendisiyle büyür insan 

kendi kurdudur zamanla

cezirsiz med olur mu? 

yitirir hükmünü nefret aşk silinince

ağunun ilacı zakkumda gizli

çelişki yaman! 

çelişki eşyanın özünde

pahası yüksektir kayrak taşının 

ne çare ekin vermez 

en has toprak bereketinde

kararı bozulursa çeliğin 

şaşırır terazi 

miyar tutmaz

kendine üşünür ruh yorgunluğunda

kendine susulur ancak

insan 

etten kemikten 

yürek çelikten olmalı

bilenmeli çelişkiden

çelişki olmasa 

çeliğe dönüşür müydü demir

böyle güçlü ve esnek 

bir kerameti vardır elbet

vardır bir hikmeti su ve ateşten 

(13 Mayıs 2003)', 'düşünce üretmeli ıssızda  düşler sancılandığında çelikten dokunmalı yürek eskimemeli kuytuda suyla beslenir toprak bilirim  suyla oyulur kıs...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/celik-yurek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günah', 'gunah-hakan-ak-ju96v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Eskiden kalma belli

Yeri yurdu belli

Yüzyıllardır kimbilir

Bu alemdendir ya

Neler oluyor

of be, ah be, vay be

Ey insan...

Kendikendime sanma

Bırakma onu

dokun biraz

hisset...

kendimsiziz birde', 'Eskiden kalma belli Yeri yurdu belli Yüzyıllardır kimbilir Bu alemdendir ya Neler oluyor of be, ah be, vay be Ey insan... Kendikendime sanma...', ARRAY['Türk Edebiyatı','Şiir','Hakan Ak']::text[], 8.5, '{"poet":"Hakan Ak","poet_slug":"hakan-ak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gunah-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostum', 'dostum-erdinc-asik-683li', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayat bir çicek bir yaprak misali

Kuruyup gider sevincin hayali 

Aldatma kendini biliyorsun dünya fani

Ya ağlarsın ya gülersin bunlar hep dünya hali

Öyle boş işlere darılıpta gücenme

Sevmesende bu hayatı yinede gülümse

Senide seven çıkacak elbette bu alemde

Ereceksin mutluluğa sakın ha dostum üzülme

Bir derdine binlerce ümidin olsun

Ecel senden çok düşmanında bulunsun

Sana ağlamak üzülmek haram olsun

Attığın her adım ise sevabın olsun', 'Hayat bir çicek bir yaprak misali Kuruyup gider sevincin hayali  Aldatma kendini biliyorsun dünya fani Ya ağlarsın ya gülersin bunlar hep dü...', ARRAY['Türk Edebiyatı','Şiir','Erdinç Aşık']::text[], 8.5, '{"poet":"Erdinç Aşık","poet_slug":"erdinc-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dostum-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret Acısı', 'hasret-acisi-erdinc-asik-6nj08', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Benim ömrüm hep böyle dertli mi olacak

Her günümün içinde göz yaşımı olacak

Çektiğim çilenin hesabı kimden sorulacak

Ha ölmüşüm ha gülmüşüm yeter artık

Ne olacaksa olacak...

Kapattım yaralı gönlümün  kapısını

Dindiremedim bu hasretin acısını

Mecalim yok bulun bana bu derdin dermanını

Ya getirin ölüm fermanımı yada verin  yıllarımı

İsyanım sana değil seni benden çalana

Benzetti beni leylasız bir mecnuna

Acımadı hiç bu zavallı kuluna

Aldığım her nefes haram oldu bana', 'Benim ömrüm hep böyle dertli mi olacak Her günümün içinde göz yaşımı olacak Çektiğim çilenin hesabı kimden sorulacak Ha ölmüşüm ha gülmüşüm ...', ARRAY['Türk Edebiyatı','Şiir','Erdinç Aşık']::text[], 8.5, '{"poet":"Erdinç Aşık","poet_slug":"erdinc-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hasret-acisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsmi Belli', 'i-smi-belli-erdinc-asik-8puke', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '(E) zilmişim üzülmüşüm ne fark eder

(R) uhum bedenimde değil bitsin bu keder

(D) eğmezse bu cana bir gün mutluluk eğer

(İ) stemezsin ama çekmekten bıktım yeter

(N) e fayda teselliler etkilemez beni öğütler 

(Ç) ile denilen batağa düştüm ya bu bana yeter

(A) lışamadım şu gurbetin kahrına

(Ş) aşırtıp vurdu felek sırtıma

(I) slak gözlerim döndü dert pınarına

(K) ıymayın geri verin gençliğimi bana', '(E) zilmişim üzülmüşüm ne fark eder (R) uhum bedenimde değil bitsin bu keder (D) eğmezse bu cana bir gün mutluluk eğer (İ) stemezsin ama çek...', ARRAY['Türk Edebiyatı','Şiir','Erdinç Aşık']::text[], 8.5, '{"poet":"Erdinç Aşık","poet_slug":"erdinc-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ismi-belli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik', 'sensizlik-erdinc-asik-q07tf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İstemem gülmek varken ağlamayı

Sensizliğe köle olup kıvranmayı

Bir göz yaşına yakarım bu dünyayı

İstemesinler benden sensiz yaşamayı

Kızarım beni dünyaya getirene

Can veripte hiç güldürmeyene

Ahım var sensiz gecen her günüme

Izdırap verdi şu yaralı gönlüme

Duymasa feryadımı uzak eller

Bilmese halimi sevip sevilenler

Kara yazıymış garip ne eyler

Fani dünya gelmez ya gidenler', 'İstemem gülmek varken ağlamayı Sensizliğe köle olup kıvranmayı Bir göz yaşına yakarım bu dünyayı İstemesinler benden sensiz yaşamayı Kızarım...', ARRAY['Türk Edebiyatı','Şiir','Erdinç Aşık']::text[], 8.5, '{"poet":"Erdinç Aşık","poet_slug":"erdinc-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sensizlik-74-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitmeyen Çile', 'bitmeyen-cile-erdinc-asik-90l17', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ensemde hissettim nefesini

Felek vurdu bana sillesini

Bilemedim bu derdin sebebini

Kapattım kalbimin ümit defterini

Yıllardır bitmedi çektiğim çile 

Ateşe attılar beni bile bile

Acımadan düşürdüler beni bu hale

Başbaşayım şu an kaderim ile

Tatmadım şu dünyanın sefasını

Taşıyamam artık hayatın kahrını

Akıttılar hep asil kanımı

Verdiği gibi alsın artık bu canımı', 'Ensemde hissettim nefesini Felek vurdu bana sillesini Bilemedim bu derdin sebebini Kapattım kalbimin ümit defterini Yıllardır bitmedi çektiğ...', ARRAY['Türk Edebiyatı','Şiir','Erdinç Aşık']::text[], 8.5, '{"poet":"Erdinç Aşık","poet_slug":"erdinc-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bitmeyen-cile-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüce Tanrım', 'yuce-tanrim-erdinc-asik-an13t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dağlardan büyük derdim kederim

Zindan oldu onsuz günlerim

Böyle yazıya sitem ederim

Yüce tanrım aldı sevdiğimi

Tüm hüzünler üstüme yüklendi

Gözlerime bahar yelleri esti

Sevinçim neşem beni terk etti

Yüce tanrım aldı sevdiğimi

Ağlamak ibadetim, yasım oldu

Bütün fırtınalar gönlümde koptu

Gülen yüzüm çicek gibi soldu

Yüce tanrım aldı sevdiğimi', 'Dağlardan büyük derdim kederim Zindan oldu onsuz günlerim Böyle yazıya sitem ederim Yüce tanrım aldı sevdiğimi Tüm hüzünler üstüme yüklendi ...', ARRAY['Türk Edebiyatı','Şiir','Erdinç Aşık']::text[], 8.5, '{"poet":"Erdinç Aşık","poet_slug":"erdinc-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yuce-tanrim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Hayat', 'sensiz-hayat-erdinc-asik-0phev', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dertler içinde çırpınır oldum

Hasretinden yıkık perişan oldum 

Kadere talihe isyankar oldum 

Sensiz hayat bu olsa gerek

Göz yaşlarım seller gibi çağladı

Kalbimin sesi feryad olup ağladı

Batan güneşim bir daha doğmadı

Sensiz hayat bu olsa gerek

Kurudu gençliğim bir yaprak gibi

Yandı bedenim kor alev gibi

Küller kaldı acı mazim gibi

Sensiz hayat bu olsa gerek', 'Dertler içinde çırpınır oldum Hasretinden yıkık perişan oldum  Kadere talihe isyankar oldum  Sensiz hayat bu olsa gerek Göz yaşlarım seller ...', ARRAY['Türk Edebiyatı','Şiir','Erdinç Aşık']::text[], 8.5, '{"poet":"Erdinç Aşık","poet_slug":"erdinc-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sensiz-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öldükçe Dirilen Militanlarız...', 'oldukce-dirilen-militanlariz-osman-oztunc-wmajm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bizde insandık çok canlar gibi 

Kürşatlar Sancarlar Yamtarlar gibi, 

Yumruklar sıkılı başlar yüksekte, 

GİTTİK SANMAYIN HİÇ DÖNMESEKTE. 

 İçinizdeyiz GÖRÜNMESEKTE. 

Ölümlere boş veren canlarız. 

ÖLDÜKÇE DİRİLEN MİLİTANLARIZ.!', 'Bizde insandık çok canlar gibi  Kürşatlar Sancarlar Yamtarlar gibi,  Yumruklar sıkılı başlar yüksekte,  GİTTİK SANMAYIN HİÇ DÖNMESEKTE.   İç...', ARRAY['Türk Edebiyatı','Şiir','Osman Öztunç']::text[], 8.5, '{"poet":"Osman Öztunç","poet_slug":"osman-oztunc","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/oldukce-dirilen-militanlariz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Çeşit BedDua', 'bir-cesit-beddua-sule-aydemir-mxqv9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gölgen olsun hüznüm

okşadığın dokunduğun

her kadında

bul beni

bir gülümsemesinde

tut beni mesela

fener alayı gibi

sevincinden gözyaşlarında

yakala beni

bir tebessüm intiharlardan 

döndürür gibi

aynı

ben gibi', 'gölgen olsun hüznüm okşadığın dokunduğun her kadında bul beni bir gülümsemesinde tut beni mesela fener alayı gibi sevincinden gözyaşlarında ...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-cesit-beddua-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık Kimdir', 'artik-kimdir-sule-aydemir-yxtw5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yine 

bir çelik dövülüyor tavında

yaşam usta 

yine alışkanlık

vuruyor çekiç darbelerini 

şekil bulacak mutlak

kırmızıda yangınken

sertleşir suya bulandığında

bir son demdir

yaşanmışlar

yükselen buharında

çeliktir

adı degişmiş

hangi nesnedir', 'yine  bir çelik dövülüyor tavında yaşam usta  yine alışkanlık vuruyor çekiç darbelerini  şekil bulacak mutlak kırmızıda yangınken sertleşir ...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/artik-kimdir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırak Kötüleri', 'birak-kotuleri-sule-aydemir-676zc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kötüler 

önce arkadaşlarını bırak dedi

içkiyi

sigarayı

gece hayatını bırak dedi

intiharlarını saçmalıklarını

yarımlarını

bir de -beni

diyemedi

demedi

beklendi

söylenmedi

yazık ki

ölemedi', 'kötüler  önce arkadaşlarını bırak dedi içkiyi sigarayı gece hayatını bırak dedi intiharlarını saçmalıklarını yarımlarını bir de -beni diyeme...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/birak-kotuleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'AyazSesi', 'ayazsesi-sule-aydemir-qppun', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sordu

- nereye kadar

sanki o an

vardı

-sonuna kadar

-çak şimdi 

dedi

madem vardı

ses niçin gelmedi

son neydi 

kim belirdi

hızlıymış

çabuk geldi', 'Sordu - nereye kadar sanki o an vardı -sonuna kadar -çak şimdi  dedi madem vardı ses niçin gelmedi son neydi  kim belirdi hızlıymış çabuk ge...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ayazsesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öbür Yüz', 'obur-yuz-sule-aydemir-nwv1z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'kalabalıkların öbür yüzü yalnızlık

acısında gülümseme olduğu kadar

birleşmenin öbür yüzü ayrılık

olacakları isterken

olması gerekenlere 

terki kadar', 'kalabalıkların öbür yüzü yalnızlık acısında gülümseme olduğu kadar birleşmenin öbür yüzü ayrılık olacakları isterken olması gerekenlere  ter...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/obur-yuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Hayat Ki', 'bir-hayat-ki-eymen-erdem-akca-kq7on', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'BİR HAYAT Kİ

Bir hayat ki, ey dost, hüzün yumağı

Çözsen kurtuluş yok, bağlanıyorsun

Unut huzur içre bir uyumağı

Fark etmesen bile dağlanıyorsun

Garip hem çok garip bir devirdir bu

Yıkmak, boğmak ister seni aldatıp

Karşı gelemezsin her bir şey tabu

Yapamazsın böyle kendinden kaçıp

Esrarlı bir anda çöker üstüne

Almak ister senin tek varlığını

Atacak öteye, gül çöplüğüne

Duyacaksın ah''ın duyarlığını

Çarmıha gererce harap ediyor

Yağmurlarda yıkar günahlarını

Anıları bir bir serap ediyor

Kırar özlemini ve ahlarını

Bir hayat ki ey dost hüzün yumağı

Dokunma, dokunma boğulacaksın

Unut huzur dolu bir uyumağı

En sevdiğin yerden koğulacaksın

En sevdiğin yerden koğulacaksın', 'BİR HAYAT Kİ Bir hayat ki, ey dost, hüzün yumağı Çözsen kurtuluş yok, bağlanıyorsun Unut huzur içre bir uyumağı Fark etmesen bile dağlanıyor...', ARRAY['Türk Edebiyatı','Şiir','Eymen Erdem Akça']::text[], 8.5, '{"poet":"Eymen Erdem Akça","poet_slug":"eymen-erdem-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bir-hayat-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yetinmek', 'yetinmek-hayrettin-turk-eozlp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aç kalkmışım nice sultanlar sofrasından

Davetkar davetlere midem bulanmış

iğrenmişim...

ekmek soğanla yetinmişim

utangaç davetlere alışmış

sevmeyi öğrenmişim...

yaşayıp okumadığım masalları

bir kuş olup kaf dağında

kanatlanmışım...

fazla uçmuşum sonra

çarpmış gerçekler yüzüme

yaralanmışım...

her yürekten bir iz yüreğimde

topladım, böldüm çarptım

hepsi sen, anlamışım...

anlar içinde bir an

anlar içinde her an

hep seni yaşamışım...

sen; adın sevda, yolun aydınlık

bitmesin diye hep büyün

aramakla yetinmişim...', 'Aç kalkmışım nice sultanlar sofrasından Davetkar davetlere midem bulanmış iğrenmişim... ekmek soğanla yetinmişim utangaç davetlere alışmış s...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Türk']::text[], 8.5, '{"poet":"Hayrettin Türk","poet_slug":"hayrettin-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yetinmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fidan-9', 'fidan-9-cemalettin-atalay-5qaux', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir gün ömrün senin gelip geçecek

Baharın giderse yazın gelecek

Boşuna ömrünü harcama gafil

O cansız bedenin bir gün gidecek

Ceddin gitti deden gitti kim kaldı

Malını mülkünü kime bıraktı

Onlar dünyada yaşasaydı eğer

Yoksula fakire her dem bakardı

Derken hayat şöyle böyle gidecek

Vakit ne çabuk da geldi diyerek

Yapacak işim var daha desende

Azrail yanına çoktan gelecek...

Ağlayanı görüp gülüp geçtiysen

Bir tekmede sen vurup gittiysen

Sonunda dönerek eyvah desende

Faydasız ne kadar tevbe ettiysen

Böyledir azizim böyle geçecek

Dünyanın halini kimler bilecek

Şu kara toprağa girdiğin zaman

Mezarın üstünde otlar bitecek

Bir gün ömrün senin gelip geçecek

Baharın giderse yazın gelecek

Boşuna ömrünü harcama gafil

O cansız bedenin bir gün gidecek

Ceddin gitti deden gitti kim kaldı

Malını mülkünü kime bıraktı

Onlar dünyada yaşasaydı eğer

Yoksula fakire her dem bakardı

Derken hayat şöyle böyle gidecek

Vakit ne çabuk da geldi diyerek

Yapacak işim var daha desende

Azrail yanına çoktan gelecek...

Ağlayanı görüp gülüp geçtiysen

Bir tekmede sen vurup gittiysen

Sonunda dönerek eyvah desende

Faydasız ne kadar tevbe ettiysen

Böyledir azizim böyle geçecek

Dünyanın halini kimler bilecek

Şu kara toprağa girdiğin zaman

Mezarın üstünde otlar bitecek

                                                 C.Atalay

                                                  Nisan-2003', 'Bir gün ömrün senin gelip geçecek Baharın giderse yazın gelecek Boşuna ömrünü harcama gafil O cansız bedenin bir gün gidecek Ceddin gitti de...', ARRAY['Türk Edebiyatı','Şiir','Cemalettin Atalay']::text[], 8.5, '{"poet":"Cemalettin Atalay","poet_slug":"cemalettin-atalay","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/fidan-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşününce seni', 'dusununce-seni-gencay-coskun-fso6o', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Düşününce seni 

Düşüyorum yeni diyarlara

Soluyorum Mutlulukları 

Bakıyorum 

Senli benli resimlere 

Çiziyorum gökyüzünü 

En baştan

Canımın renklerine

Enine boyuna boyuyorum 

Ufuklara büyük harflerle

Seni yazıyorum

Lambada bir ışık gibi

Uzanıp giden yolları

Aydınlatan 

Yandımının bakışların

Düşününce seni 

İçim bir tuhaf oluyor 

Seni istiyorum

Bir rüzgar

Bir ışık

Bir mesajla 

Sana ulaşacak 

Herhangi bir şey olmak 

İstiyorum

Düşünmesem 

Seni 

Bunalıyorum

Farkındamısın ama 

Seni 

Fena halde 

İstiyorum...', 'Düşününce seni  Düşüyorum yeni diyarlara Soluyorum Mutlulukları  Bakıyorum  Senli benli resimlere  Çiziyorum gökyüzünü  En baştan Canımın re...', ARRAY['Türk Edebiyatı','Şiir','Gencay Coşkun']::text[], 8.5, '{"poet":"Gencay Coşkun","poet_slug":"gencay-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/dusununce-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmuyor Sensiz', 'olmuyor-sensiz-taskin-demir-e69q4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'olmuyor iste sensiz

sensiz nekadar caresizim bir bilsen

elini tutmayinca

gözüne bakmayinca, sesini duymayinca

senden uzakta

olmuyor iste sensiz

hic bir seye uzanmiyor ellerim

hic bir seyi görmek istemiyor gözlerim

hic bir seyin tadi yok sensiz

yaz gelmis bahar gelmis

disarida hava alabildigine güzelmis

alabildigine güzel acmis cicekler

yada kara kara bulutlar varmis

yagmur yagacakmis

varsin olsun

varsin yagsin yagmurlar

bardaktan bosanircasina

varsin güzel olsun isterse hava

varsin acsin cicekler

ne cikar

sen olmayinca

her sey seninle güzel

her sey seninle tatli

aldigim hava ictigim su

yedigim lokma

isterse zehir olsun

yeterki sen ol yanimda

gülemiyorum, gülmekte gelmiyor icimden

hatta aglamak istiyorum zaman zaman

agliyamiyorum bile

olmuyor iste sensiz

sensiz agliyamiyorum bile

odamda dört duvar bana bakiyor ben onlara

lanet olsun böyle yanlizliga

mahkum ettirdiler beni

tüm güzelliklere kapattim kapilarimi

sen olmayinca

ne sarkilarin havası

ne yasamanin tadi var

yanlizlik var sadece

kahrolasi yanlizlik

aksam olup kapanmak yokmu odaya

o deli edici sesizligi yasamak yokmu

daha kapimi acmadan

anahtari elime almadan yapisiyor yakama

ayaklarim geri geri cekiyor

at sokaklara kendini diyor

at sokaklara...

sokak lambalari seni bekliyor diyor

vede

ayaklarinin altındaki

kaldirim taslari

ha sen, ha onlar

ne farkiniz var birbirinizden diyor

onlarda sende yanlizsiniz

ikinizde birbirinizi ezin

tükenene dek...

sonra dönüyorum tekrar odama

hangi saat, hangi zaman

gecenin bir vakti olmus

ne cikar

ne kiymeti var sensiz gecen zamanin hayatimda

ve sonra

bir kalem, bir kagit aliyorum

sana yazmak geliyor icimden

düsünüyorum, düsünüyorum

bilemiyorum ne yazacagimi, 

burusturup atiyorum bir köseye kagidi bir köseye kalemi

daliyorum yine, binlerce metre derinlerde gibi

cit yok etrafımda ama

kulaklarimda bir ugultu

kafamin ici kazan gibi

biri gidiyor düsüncelerin

biri geliyor

göz kapaklarimda kursun var sanki

agirmi agir

kapaniyor ama uyuyamiyorum

olmuyor iste

sensiz olmuyor

sensiz ne uyku var gözlerimde

nede gecelerimde rüya

karanliklar yanlizligima es gibi etrafimda

saat tittaklari ile

hangi saati vuruyor bilmem

ve bir zaman sonra

günese aciyorum gözlerimi

yeni bir gün basliyor belli

yine sensiz yine senden uzakta

biliyorum mutlaka bir gün kavusacagiz

evlilige dogru kosacagiz

ama

olmuyor iste

olmuyor sensiz

olmiyacakta!', 'olmuyor iste sensiz sensiz nekadar caresizim bir bilsen elini tutmayinca gözüne bakmayinca, sesini duymayinca senden uzakta olmuyor iste sen...', ARRAY['Türk Edebiyatı','Şiir','Taskin Demir']::text[], 8.5, '{"poet":"Taskin Demir","poet_slug":"taskin-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":94,"source_url":"https://www.antoloji.com/olmuyor-sensiz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Anlamimsin', 'sen-anlamimsin-taskin-demir-271my', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen anlamımsın 

gülüşlerinin gölgesinde yaşıyorum

hayatı...

gündüzleri içimi ısıtan güneşimsin 

ve ne zaman dineceğini bilmediğim 

yağmurumsun bazen....

ağladığım zaman gözyaşlarım üşüdüğüm zaman tenimsin sen...

sen herseyimsin benim

mutluluğun gölgesinde kalan gülücüklerimsin bazen ve bazende hasrete sarkı besteleyen bestekarım 

yureğimde sakladığım son insansın 

sen sen sen sevgilimsen sen anlamımsın...

ruhumda ve bedenimde ilelebet kalbimde yasarsın.... 

umuda yolculuk ettiğim saatlerde seninle yasarım dunyada....

ebedi bir yalnızlık çöker sonra üstüme..

ve bu yalnızlık oyle bir kördüğüm ederki beni...

yıldızlar vardı hani kaydıkça dilekler tuttumuz anlamsız gecelerde tek anlamımızdı onlar bizim...

soyle ne kadar daha sensizim...

biliyorsun bu anlamsız hayatta tek anlamımsın sen benim... 

bılırsın anlam yıtırılmez....

ve yıtırılmedikçe bu sevgimiz hiç bitmez...

dedim ya gülüm sen anlamımsın...', 'Sen anlamımsın  gülüşlerinin gölgesinde yaşıyorum hayatı... gündüzleri içimi ısıtan güneşimsin  ve ne zaman dineceğini bilmediğim  yağmurums...', ARRAY['Türk Edebiyatı','Şiir','Taskin Demir']::text[], 8.5, '{"poet":"Taskin Demir","poet_slug":"taskin-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sen-anlamimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye Sevgilerle', 'sevgiliye-sevgilerle-taskin-demir-8mvg2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kara gözlerinden muhabbet kaptim

Gönlümü ugruna köle yaptim

Sensin ask serbeti, kalbime aktin

Sensin günesim dünyami aydinlattin.', 'Kara gözlerinden muhabbet kaptim Gönlümü ugruna köle yaptim Sensin ask serbeti, kalbime aktin Sensin günesim dünyami aydinlattin....', ARRAY['Türk Edebiyatı','Şiir','Taskin Demir']::text[], 8.5, '{"poet":"Taskin Demir","poet_slug":"taskin-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sevgiliye-sevgilerle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Seni Öyle Seviyorum', 'ben-seni-oyle-seviyorum-taskin-demir-4wpnb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'nasıl doğuyorsa dağlara güneş

nasıl yakıyorsa ormanı ateş

nasıl lav püskürüyorsa yanardağ

işte ben seni öyle seviyorum

öyle zamanlarda yazıyorum şiirlerimi

nasıl çatıları uçuruyorsa rüzgar

nasıl yolları kapıyorsa kar

nasıl fırtınadan ıssız bir koya sığınıyorsa gemi

işte ben sana öyle sığınıyorum

öyle zamanlarda yazıyorum şiirlerimi

nasıl çiçekler baharda açıyorsa

nasıl uğur böcekleri sonsuza uçuyorsa

nasıl çöl yağmuru hasretle bekliyorsa

işte ben seni öyle bekliyorum

öyle zamanlarda yazıyorum şiirlerimi', 'nasıl doğuyorsa dağlara güneş nasıl yakıyorsa ormanı ateş nasıl lav püskürüyorsa yanardağ işte ben seni öyle seviyorum öyle zamanlarda yazıy...', ARRAY['Türk Edebiyatı','Şiir','Taskin Demir']::text[], 8.5, '{"poet":"Taskin Demir","poet_slug":"taskin-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ben-seni-oyle-seviyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mukavva Renkli Çocuk', 'mukavva-renkli-cocuk-hayati-yavuzer-8q04e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Taş Köprü’nün üstünde 

Yaz kış bir çocuk yatar

Esmerdir teni esmer

Bir mukavva üstünde

Gelen geçene bakar

Gözleri dinar dinar 

Mukavva renkli çocuk

Gece gündüz yaz ve kış

Bir bitmez tükenmez iş

Bazen yağmur bazen kar

Esmer rengini yıkar

Mukavva renkli çocuk

Vardar bir ninni söyler

Taş köprü beşik olur

Üstünde aynı giysi 

Geçer haftalar, aylar

Elleri küçük küçük

Büyümez esmer çocuk

Mukavva renkli çocuk

(20 Mayıs 2001 Üsküp)', 'Taş Köprü’nün üstünde  Yaz kış bir çocuk yatar Esmerdir teni esmer Bir mukavva üstünde Gelen geçene bakar Gözleri dinar dinar  Mukavva renkl...', ARRAY['Türk Edebiyatı','Şiir','Hayati Yavuzer']::text[], 8.5, '{"poet":"Hayati Yavuzer","poet_slug":"hayati-yavuzer","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/mukavva-renkli-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muştu', 'mustu-mustafa-ozturk-4eu3d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Muştusuyla avunurken bir kahpe yalancının, 

Buza kesen bir rüzgar yaladı suratımı, 

Etkisiyle kahroldu benliğim bu acının, 

Mor benekli dağlara dehlizledim atımı...', 'Muştusuyla avunurken bir kahpe yalancının,  Buza kesen bir rüzgar yaladı suratımı,  Etkisiyle kahroldu benliğim bu acının,  Mor benekli dağl...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Öztürk']::text[], 8.5, '{"poet":"Mustafa Öztürk","poet_slug":"mustafa-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/mustu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanlı Dere', 'kanli-dere-mustafa-ozturk-skuio', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kanlı dere kenarında açan kızıl çiçekler, 

Yanlızlığın siyah yüzü, 

       Derdime dertler ekler, 

Zaman zalim, zaman hain, zaman gaddar olsa da 

Umudu zaman olan bir garip seni bekler...', 'Kanlı dere kenarında açan kızıl çiçekler,  Yanlızlığın siyah yüzü,         Derdime dertler ekler,  Zaman zalim, zaman hain, zaman gaddar ols...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Öztürk']::text[], 8.5, '{"poet":"Mustafa Öztürk","poet_slug":"mustafa-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kanli-dere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin Elinde', 'gecenin-elinde-hakan-kose-kjnh8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu gece bana şiir yazdıracak

Kara gözlerini süzüşünden belli

Eski mezarları kazdıracak

Böyle dâvetkar bakışından belli...

Sürdükçe kalemi kağıtlara

Yağacağım yepyeni ağıtlara

Yeni sürgün vermiş söğütlere

O’nun adını yazdıracak besbelli..

Olmaz olmaz desem de

O artık gitti desem de

Gözlerim bitti desem de

Anlamayacak besbelli..

Rezil rüsvây edecek âleme

Gark edecek elemden eleme

Tam düşmüşken ellerime

Gene kaçıp gidecek besbelli...

Hemen her zaman böyle gelir

Kapıdan kovsam, bacadan gelir

Tam gözlerim uykuya giderken

Gelin olur gelir, duvaklı telli...', 'Bu gece bana şiir yazdıracak Kara gözlerini süzüşünden belli Eski mezarları kazdıracak Böyle dâvetkar bakışından belli... Sürdükçe kalemi ka...', ARRAY['Türk Edebiyatı','Şiir','Hakan Köse']::text[], 8.5, '{"poet":"Hakan Köse","poet_slug":"hakan-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gecenin-elinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çirkinde Naz Bile Gördüm', 'cirkinde-naz-bile-gordum-salim-solmazgul-i48ar', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çeyrek asırdır dünyada

Neşe degil çile gördüm

Bırak güzel olanları

Çirkinde naz bile gördüm

Gül yerinde çalı biter

Bülbül küsmüş karga öter

Bu dert hepsinden besbeter

Gülü karga ile gördüm

Kimse anlamıyor halden

Herkes çalar başka telden

Kötülük beklerken elden

Dost işinde hile gördüm

Solmazgül böyledir zaman

Merde bile demem aman

Dağ başında olur duman

Gurbet gördüm sıla gördüm', 'Çeyrek asırdır dünyada Neşe degil çile gördüm Bırak güzel olanları Çirkinde naz bile gördüm Gül yerinde çalı biter Bülbül küsmüş karga öter ...', ARRAY['Türk Edebiyatı','Şiir','Salim Solmazgül']::text[], 8.5, '{"poet":"Salim Solmazgül","poet_slug":"salim-solmazgul","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cirkinde-naz-bile-gordum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Leylakları Öperim', 'leylaklari-operim-bekir-mutlu-gokcesu-e9agd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kopartamam çiçeklerini

koklarım, severim hepsi.

Gözlerimle okşarım yollarını

fısıldayarak seni sorarım ağaçlarına.

Bir minik öpücük kondururum 

soluduğun havana.

Rüzgar olsam kıyamam

baharının dallarına.

Yağmur olsam yağamam

sel olup akamam yollarına.

Sahip değilim

alamam kollarıma,

aklımdan geçersin 

en çok da dudaklarınla

leylakları öperim hepsi...', 'Kopartamam çiçeklerini koklarım, severim hepsi. Gözlerimle okşarım yollarını fısıldayarak seni sorarım ağaçlarına. Bir minik öpücük kondurur...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/leylaklari-operim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Hatırla', 'beni-hatirla-yusuf-canturk-n5dgf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaşamak  ıstırap  sana  hasret  kaldıkça, 

                                Duvarlarda  resimlerin  bana  bakar  durdukça, 

                                Yaşamak   belki,  böylesi   hülya   kurdukça

                                Kalbim  her  an sızlayarak  ismin  ile  vurdukça.



..                              Her  mevsim  böylece  gelip  geçerken, 

                                Beni  hatırla  leylekler  gelirken  ve  de  göçerken.

                                Pencere  önünde, gelip  geçene, dalgın  bakarken, 

                                Beni  hatırla, akşam  ışıkları  yakarken! 



                                Makine  önüne  geçip,  dikiş  dikerken, 

                                Beni  hatırla   sigarandan  nefes  çekerken! 

                                Güller  açarken,  bülbüller  öterken, 

                                Ördüğün  örgüleri  tekrar, tekrar  sökerken, 

                                Beni  hatırla  ağaçlar  yapraklarını  dökerken

                             

                                   Sevdiğimiz  şarkıları  söylerken  ve  de  dinlerken,

                                    Hasret  çekip  ah  ederek  inlerken,

                                    Pencere  önünde  oturup  dalgın  bakarken,

                                    Beni  hatırla  yüreğin  tıp,  tıp  atarken.

                                   Gün  sonunda  rengarenk  gurup  batarken,

                                    Akşamları  ışıkları  bir, bir  yakarken,

                                    Bazen  uykun  gelip  erken  yatarken,

                                     Beni  hatırla  dua  edip  Tanrımıza  taparken.

                     Yusuf  Cantürk (E.Hv.Kur.Alb.)                                                                     mayıs 1987 kadıköy', 'Yaşamak  ıstırap  sana  hasret  kaldıkça,                                  Duvarlarda  resimlerin  bana  bakar  durdukça,                   ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Cantürk']::text[], 8.5, '{"poet":"Yusuf Cantürk","poet_slug":"yusuf-canturk","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/beni-hatirla-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sözüm Geçer mi?', 'sozum-gecer-mi-yusuf-canturk-6fwdc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Birdenbire  sanki  bir  rüyadan  uyandım, 

                                Yıllar  gelip  geçti,  artık  yokuşlara  dayandım, 

                                Gece,  gündüz  zora  koştum  bacaklarım,  kollarım, 

                                Uzun  geldi,  düz  de   olsa  şu   kısacık  yollarım.



                                Yalvarırım  bu  sevdayı  unut  ey  gönlüm! 

                                Artık  acılara  tahammülüm   kalmadı.

                                Nice  sevda  çektim, ama  böylesine  yanmadım.

                                Dikkat  et  ki  kaçıncı  baharı  yaşıyorsun  ey  ömrüm! 



                                Artık  başka  sevdalara  yer  yok  gönlümde, 

                                Desem  de  acep  gerçekten    sözüm  geçer  mi? 

                                Sonbahara  yaklaşırken  şu  ömrümde, 

                                Korkum  o  ki   bir  goncayı   seçer  mi? 



                                                        Kadıköy-2003', 'Birdenbire  sanki  bir  rüyadan  uyandım,                                  Yıllar  gelip  geçti,  artık  yokuşlara  dayandım,               ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Cantürk']::text[], 8.5, '{"poet":"Yusuf Cantürk","poet_slug":"yusuf-canturk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sozum-gecer-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazgeçmek', 'vazgecmek-engin-aybar-6kdm9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sana rastladım 

ve vazgeçmemek üzere

rastladım ve sevdim

istersen sende rastla ve sev beni', 'sana rastladım  ve vazgeçmemek üzere rastladım ve sevdim istersen sende rastla ve sev beni...', ARRAY['Türk Edebiyatı','Şiir','Engin Aybar']::text[], 8.5, '{"poet":"Engin Aybar","poet_slug":"engin-aybar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/vazgecmek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne Hasreti-2-*', 'anne-hasreti-2-bayram-tunca-gip5k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Varmış, yokluğunda onu sevmek

İsterdim, onu seninle tanıştırmak

İsterdim ki dünürcüm sen olasın

İsterdim, benimle gurur duyasın

Ama felek ayırdı bizleri ne edeyim

Yokluğunu ta iliklerimde hissettim

Kalabalıklar içinde tek başınaydım

En mutlu günümde bile gülmedim

Nasıl gülerdim ki, senin yokluğunda

Tüm benliğim, hep seni arıyordu ya

Bi de, anası nerede demeleri var ya

Döndürüyorlardı beni, deli divaneye

Sanma ki sadece düğünümde aradım

Hem acı, hem tatlı, günümde aradım

Gördüğüm her dosttan seni sorardım

Her seferinde, yaramı tuzla sarardım

Ahh görsen, sensiz ne çabuk sarardım

Ayaz vuran arpa/buğday gibi sarardım

Senden bahsedeni yanımdan kovardım

Çünkü, her defasında yaramı yolardım

Ne dikiş tutar/ne de kabuk bağlar yaram

Sensiz hayatta gülmek sanki bana haram

Yıllarca hasret acınla yatıp/kalkar Bayram

Yok ki; başka da bir kayıran, onu çağıram

12.05.2003/12.05', 'Varmış, yokluğunda onu sevmek İsterdim, onu seninle tanıştırmak İsterdim ki dünürcüm sen olasın İsterdim, benimle gurur duyasın Ama felek ay...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/anne-hasreti-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lâkin Hâlâ Sevgi', 'l-kin-h-l-sevgi-sule-aydemir-6askl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'nedir ki bu

basit 

karar kimin

kıyas neye

basit insanlar 

basit mi severler 

bilinir mi 

küçüğün yüreği 

basitliğinde büyüklüğü 

bakışı keskindi

hani kördün(!)   ya

belki kartal 

belki kuzgun

sevgi anası idi ya

o doğurmuştu onu

kuzgundu tamam

kim engel olacaktı 

-şahan demesine

kim bilir kim

kelimeleri şiir dizememiş diye

artık artıktır ya

ağrısında gözyaşı yolu bulamamış diye

kül olmuşken

yanmaktan korkmuş ya

dokunup koklamayı becerememiş diye

nedir ki bu

yargılayıp sevgide 

çırak diye

hakir görmek niye

yaşayan yaşasın 

yazan da yazsın

kime ne

basit diye insan

basit mi sever diye

inemez sadeye

düşünemesin ki

niye', 'nedir ki bu basit  karar kimin kıyas neye basit insanlar  basit mi severler  bilinir mi  küçüğün yüreği  basitliğinde büyüklüğü  bakışı kesk...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/lakin-hala-sevgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haram Olsun Bana', 'haram-olsun-bana-erdinc-asik-afa56', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Omuzumda dert yükü olsada

Gençliğim kana bulansada

Sensiz yaşamaktansa

Gülmek haram olsun bana...............', 'Omuzumda dert yükü olsada Gençliğim kana bulansada Sensiz yaşamaktansa Gülmek haram olsun bana..................', ARRAY['Türk Edebiyatı','Şiir','Erdinç Aşık']::text[], 8.5, '{"poet":"Erdinç Aşık","poet_slug":"erdinc-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/haram-olsun-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toplan Gidiyoruz Ey Kalbim', 'toplan-gidiyoruz-ey-kalbim-nuri-can-bduij', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Haydi toplan akşam oldu 

vakit doldu 

toplan gidiyoruz ey kalbim 

kırkikindi yağmurlarına kalamam 

kaldıramam bunca ağrıyı, ihaneti 

biliyorum kirlenmiş hiç bir bakışta, yer yok bana 

bu yüzdendir ceylanlara küsmüşlüğüm 

sevdalara küsmüşlüğüm bu yüzden 

bir gül yaprağı bulup sarmak için yaramı 

çekip gidiyorum buralardan 

içimdeki cesetleri çiğneyerek 

kalbimdeki mahşere 

bak akşam 

vakit tamam 

duruldu işte bulanık denizler 

dürüp ömrümün defterini 

toplan gidiyoruz ey kalbim 

yorgunum 

bir sonbahar ezgisi gibi bekleyemem son yaprakta 

sevgisi iğdiş edilmiş tarihlere koma beni ey kalbim 

bak güz yağmurları iniyor acılar ve ihanetler üstüne 

çırılçıplak ve sevgisiz kalmış bir şiirim

kimsesiz bir kış ortasında 

ne gülen gözleri ısıtıyor artık çocukların

ne de sevdalı bakışları yeniyetme aşıkların

bütün dinlerden kovuldum 

bütün ülkelerden 

bütün yüreklerden kovuldum 

(*)      ”Aliye gülümsesem Muaviye öldürür beni”

hangi tanrıya sığınsam yaramın merhemi yok 

biliyorum kirlenmiş hiç bir bakışta, yer yok bana 

bu yüzdendir ceylanlara küsmüşlüğüm 

sevdalara küsmüşlüğüm bu yüzden 

yeni bir gül yaprağı bulup sarmak için yaramı 

sevdalı bir kuş yükleyip kanatlarına acılarımı

alıp gitsin beni buralardan 

hamuru çürümüş dostluğun, vefanın, aşkın 

vefasız mevsimlere bırakma beni ey kalbim 

ağlatma beni sevda kapılarında 

kahpe kapılarında eğme boynumu 

kurşunlar sıkılsada canevime 

çiğnetme yoksulluğumu ayaklar altında 

bırak başım dik, içim ezik kalsın 

onurlulara mahsus bir makamda ağırla beni 

satılmışlığın, alçaklığın, ihanetin ortasında koma 

biliyorum bu düş sığmaz kirlenmiş sokaklara 

bu sevda sığmaz 

bakmayın gözlerime 

nasıl saklarım yüreğimdeki incinmişlikleri 

kınalı bir kelebek konunca saçlarıma 

ah! Benim de hayallerim vardı 

baharlarım vardı, yazlarım vardı 

kuşlar göçüp gitti yüreğimden 

gökyüzüm yaralı kaldı 

bir isyan giydirip gözlerime 

dipsiz uçurumlara yuvarladım umutlarımı 

aşk diyordum talan oldu, yalan oldu ömrüm 

tınısı kırık bir keman sızısıyım artık 

yok gideceğim başka bir liman 

bak duruldu işte bulanık denizler

haydi toplan vakit tamam 

toplan gidiyoruz ey kalbim 

boşalsın ince duygularımın sırtındaki yük 

paranın sevgiye ihanetini gördüm

insanın önünde diz çöküp ibadetini

dünler harabe yarınlar umut değil

hüznün neresinden dönsem, kırgınım

öpmeye uzandığım bütün dudaklar frengili

Nuri Can

www.nurican.com

(*)       “Nizar Kabbani”', 'Haydi toplan akşam oldu  vakit doldu  toplan gidiyoruz ey kalbim  kırkikindi yağmurlarına kalamam  kaldıramam bunca ağrıyı, ihaneti  biliyor...', ARRAY['Türk Edebiyatı','Şiir','Nuri Can']::text[], 8.5, '{"poet":"Nuri Can","poet_slug":"nuri-can","theme":"Türk Şiiri","is_hero":false,"total_lines":71,"source_url":"https://www.antoloji.com/toplan-gidiyoruz-ey-kalbim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Örtün Üstünü Pisliklerinizin', 'ortun-ustunu-pisliklerinizin-yusuf-gencal-ll3b0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Farklı sesleri ve renkleri

Dinleri mezhepleri

Ezan bayrak nutuklarıyıla

Vatanın bölünmez

Bütünlüğü diye diye

Halkları böldüler kışkırtılar

Ve yaşam buldular

Her dönem faşizan

Muhafazakar milliyetçi

Asker sivil cuntacı

Bazen de demokrat oldular

Sermaye düzeni adına

Egemenlikleri adına

Toplumu korkutmak adına

Hiddet şiddet işsizlik adına

Bireysellik soysuzlaştırma adına

Sindirmek teslim almak adına

Köşklerde yalılarda

Ve arpalıklarda

Yediler doymadılar

Her köşesine girdiler

Adına özelleşme dediler

Gurula sattılar borclandırdılar

Yabancıya talancıya 

Örtün üstünü pisliklerinizin

Gerçeklerini ülkenin 

Kediler gibi

Kanlı paranızla

Tankınızla topunuzla

İş birlikcisi emperyalistlerin

Kediler asaletinden örter

Ya sizler beyler

12.06.1995k', 'Farklı sesleri ve renkleri Dinleri mezhepleri Ezan bayrak nutuklarıyıla Vatanın bölünmez Bütünlüğü diye diye Halkları böldüler kışkırtılar V...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Gençal']::text[], 8.5, '{"poet":"Yusuf Gençal","poet_slug":"yusuf-gencal","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ortun-ustunu-pisliklerinizin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dedem Korkut', 'dedem-korkut-mustafa-angin-jbnfp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'DEDEM KORKUT SOY SOYLAMIŞ, BOY BOYLAMIŞ 

GÖRELİM NE SÖYLEMİŞ.

Ey yârân-ı memdühu safâ! 

Olasız gam hanesinden cudâ

Kimsenin yolunu yolsuza uğratmasın Hüda.

Diyeceğim şu; 

Güleryüz, tatlı dil, can gövdeye mülk değil, 

Kara sakaldan ak sakala erdim

Ne ki insanoğluyla başladı, hepsini gördüm.

Çisil çisil yağışlı bir sabah, dünyanın dörtyol ağzında durdum

Bir bir gördüm.

Yaşamak için ölenleri, ölmek için yaşayanları gördüm.

Yalanın baş köşeye oturtulduğunu, 

Gerçeğin kapı dışarı edildiğini gördüm.

Zalimin akıttığı kanı gördüm, 

Aldatılmış kadının gözyaşlarını gördüm, 

Birinin ötekine yaptığını gördüm, çok gördüm

Nankörlüğü ayan beyan gördüm.

İnilti dolu, pişmanlık dolu ümitsiz evler gördüm

Saraylar gördüm, harcı masumların kanından, 

Bu saraylarda sevişenleri gördüm, 

İpeklere sarılmış, sırmalar takınmış ihaneti gördüm.

Zindanlar gördüm, zindanlarda suçlunun yanıbaşında

Suçsuzu da gördüm.

Dost yüzlü hasedi gördüm

Acizin hırsını gördüm

İftirayı gördüm, giyimli kuşamlı.

Hilenin koştuğu atı, deştiği kuyuları

Açtığı kapıları gördüm.

Merhameti, yıkık bir duvar dibinde ağlar gördüm

Tapınağa koşan günahkârları gördüm

İyiyi ayak altında, kötüyü baş üstünde gördüm.

Güneşli havada gördüm, 

Yağışlı havada gördüm.

Çok gördüm.

Yarım gece, yarım gündüz

Gecemde gördüm, gündüzümde gördüm

Ne ki insanoğlu ile başladı 

Hepsini gördüm.

DEDE KORKUT

(PTT Dergisi Ağustos 2000)', 'DEDEM KORKUT SOY SOYLAMIŞ, BOY BOYLAMIŞ  GÖRELİM NE SÖYLEMİŞ. Ey yârân-ı memdühu safâ!  Olasız gam hanesinden cudâ Kimsenin yolunu yolsuza u...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Angın']::text[], 8.5, '{"poet":"Mustafa Angın","poet_slug":"mustafa-angin","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/dedem-korkut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baş Harfleriyle Anlattım Yokluğunu', 'bas-harfleriyle-anlattim-yoklugunu-aysun-acikalim-f8ksd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ağır ağır sarar yokluğun 

Nasıl dayanılır buna 

Nasıl yaşanır bilmem 

Ebediyetin boşluğunda.

Sana uzatsam ellerimi

Ellerim sarar yokluğunu 

Ne olursa olsun varsın 

İçimde hissediyorum seni.

Sen ki var olan en güzel duygu

Een aşılamaz sevgi seli

Varlığın kadar yokluğunda benim 

İnan bir an unutamam seni 

Yalnız kalbim şimdi bomboş

Omuzlarım çok daha ağır şimdi

Rüyalarım seninle dolmuş

Unutmak nasıl bir şey ki 

Mümkün mü unutmak seni.

(12/05/2003 - 22: 00)', 'Ağır ağır sarar yokluğun  Nasıl dayanılır buna  Nasıl yaşanır bilmem  Ebediyetin boşluğunda. Sana uzatsam ellerimi Ellerim sarar yokluğunu  ...', ARRAY['Türk Edebiyatı','Şiir','Aysun Açıkalım']::text[], 8.5, '{"poet":"Aysun Açıkalım","poet_slug":"aysun-acikalim","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bas-harfleriyle-anlattim-yoklugunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluğa Çağrı', 'mutluluga-cagri-mehmet-ali-cibikli-5tfkw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dedik ki bekarlıkta, 

                        Bir fayda bulamayız.

                        Artık bu son durakta, 

                        Daha çok kalamayız.

                        Ne bekarlık sultanlık, 

                        Ne de iyi bir şeymiş.

                        Bitsin artık yalnızlık, 

                        Çaresi evlenmekmiş.

                        Bu yüzden karar verdik, 

                        Sonunda evlenmeye.

                        Sizi de davet ettik, 

                        Bizimle eğlenmeye.

                              Mehmet Ali ÇIBIKLI

                             25.07.1977-Balıkesir', 'Dedik ki bekarlıkta,                          Bir fayda bulamayız.                         Artık bu son durakta,                          Da...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Çıbıklı']::text[], 8.5, '{"poet":"Mehmet Ali Çıbıklı","poet_slug":"mehmet-ali-cibikli","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/mutluluga-cagri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YabaniAşk', 'yabaniask-sule-aydemir-zndma', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'aşk 

sevgi tutku olmuş 

ateş sarmış

tutuşmuş alevler içinde

yürümüş patikalarda

bulmuş da kendini

nihayet kentte

dişi örümceğe

bulut dokutmuş 

ufukta bulut

dokunmuşta dokunmuş

ehlileşmiş yabani

sevmişte sevmiş

karnında kıpırtılı

muazzam 

o memnun mükemmel ağrı

sök hadi sökebilirsen 

ah ki

bunun adı beyhude

aşk

gidivermiş dağlara 

inivermiş denizlere

yalamış her engebeyi

dimağ ezberlemiş

sevgisinden kor kör

bilmemişte 

kumdan gelen sam yeliymiş

esmişte esmiş

bilmişte bilmiş

aşkta aşkmış

ayak-saç dibi

hissetmişte hissetmiş



sök hadi sök! 

heyecanda bu yabani', 'aşk  sevgi tutku olmuş  ateş sarmış tutuşmuş alevler içinde yürümüş patikalarda bulmuş da kendini nihayet kentte dişi örümceğe bulut dokutmu...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/yabaniask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taşlar', 'taslar-ali-atmaca-miv3c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kayan yıldızların ardından

Dualar ederken 

Kefenimin bir ucunu

Mezar taşlarına sardığım, 

Ve gizlice 

Utangaç şiirler yazdığım 

Gelir aklıma

Toprak damlarda ıslanırken

Dud ağacından düştüğüm

Ve saklanacak kadar uzak

Kaybolacak kadar yakın

Saklambaç oyunlarım 

sendelerken 

çocukluğumun dar sokaklarında 

kınalı parmaklarım üzerinden, 

ırmaklar dolusu düşlerim düşer

akşam olduğunda soframa

boğulacağım 

gelir aklıma

fırtınalı düğünlerin 

ağlamaklı gelinleri 

ardından 

oruçlu dudaklarının çatlağıyla annem

ağıtlarım, 

kefenim, 

bir ucu yırtık dualarım, 

çiçeklerim, 

baharım, 

sönmüş yangınlarım, 

aşklarım

ve de gençliğim

alaca karanlık sayfalarda 

gelir aklıma…', 'Kayan yıldızların ardından Dualar ederken  Kefenimin bir ucunu Mezar taşlarına sardığım,  Ve gizlice  Utangaç şiirler yazdığım  Gelir aklıma...', ARRAY['Türk Edebiyatı','Şiir','Ali Atmaca']::text[], 8.5, '{"poet":"Ali Atmaca","poet_slug":"ali-atmaca","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/taslar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tarifsiz Tarifim', 'tarifsiz-tarifim-sule-aydemir-zf6yw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'karmaşık gibi

ağlıyor muyum

gülüyor muyum

bilemiyorum

sen gibi

yaşamak gibi

ikisi de senden ki

var oluş gibi', 'karmaşık gibi ağlıyor muyum gülüyor muyum bilemiyorum sen gibi yaşamak gibi ikisi de senden ki var oluş gibi...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/tarifsiz-tarifim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KALP GÖZÜ', 'kalp-gozu-serdar-uzunoner-h37lw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'KALP GÖZÜMLE GÖRDÜM SENDE SEVGİYİ.

DÜNYA ÖTESİ BİR ALEMDEYİM.

AŞK DENİLEN O BÜYÜLÜ ÇİZGİYİ.

SENİNLE YENİDEN ÇİZMEKTEYİM.', 'KALP GÖZÜMLE GÖRDÜM SENDE SEVGİYİ. DÜNYA ÖTESİ BİR ALEMDEYİM. AŞK DENİLEN O BÜYÜLÜ ÇİZGİYİ. SENİNLE YENİDEN ÇİZMEKTEYİM....', ARRAY['Türk Edebiyatı','Şiir','Serdar Uzunöner']::text[], 8.5, '{"poet":"Serdar Uzunöner","poet_slug":"serdar-uzunoner","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kalp-gozu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Garip Mektup', 'bir-garip-mektup-serdar-akcer-35m6s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Acı verdi bir anda yalnızlık gülleri, 

Açınca yüreğimde

Solu verdi sevdamın krizantemi, 

Sen giderken yüreğimden

Ağlıyı verdi yıllardır suskun olan çocuk, 

Yüreğim kaybolurken

Sızısı vardı sevmeyi kaybetmenin, 

Ateşimi gösteremeden yüreğim

Bir garip mektup kaldı, 

Sen giderken ansızın.

Bir yudum çayı özledim, 

Sessizliğe karşı içmeyi

Özledim sevgiliye sarılmayı, 

Ben bunu hiç beceremedim.

İşte gelip çattı bir doğum günü daha, 

Ben büyüyorum, büyüdükçe ölüyorum

Ölüyor içimdeki canıma can katan çocuk

Ölüyor saflığım, doğallığım 

Ölüyor şehir.

Ben hiç bir zaman tutunamadım bir aşka, 

Sevdalandım ama bir başka

Ben yandım, mumlar yanmadı, duru verdi

Öyle boşlukta kalan bir şamdanda

Ben hiç bu kadar sevmedim bir kadını

Dudaklarını, ellerini, gözlerini, ayaklarını

Ben hiç bu kadar boşlukta kalmadım

Irzıma ve namusuma geçerlerken bile

Ben hiç bu kadar ağlamadım

Sorunlu çocukluğum, ateşler ve kadehler kan kırmızı

Kaç gece söndürdüm fenerleri fahişelerin kollarında

Hepsi sana benziyordu, hepsi yalandı, hepsi kahpe

Hiç biri bilmiyordu en sevdiğim beyazdı

Onlar siyah sanıyordu

Ve gülmüyordu hiç biri senin gibi.

Yıllardır satarken eskiciye hatıralarımı

Hatırlamıyordum.

Şimdi sen satarken beni, 

Yine hatırlamıyorum

En sevdiğin şair Ahmet Arif mi, Özdemir Asaf mı? 

Bir ben ağır geliyordum hayata 

Birde kamburum.

Serdar  AKÇER,2001 Haziran', 'Acı verdi bir anda yalnızlık gülleri,  Açınca yüreğimde Solu verdi sevdamın krizantemi,  Sen giderken yüreğimden Ağlıyı verdi yıllardır susk...', ARRAY['Türk Edebiyatı','Şiir','Serdar Akçer']::text[], 8.5, '{"poet":"Serdar Akçer","poet_slug":"serdar-akcer","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/bir-garip-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '^iirin Memeleri', 'iirin-memeleri-ali-develioglu-n1oqq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Benim için şiir

Daha göğün kucağında

Yıldız emdiğim sıralarda

Aydeden öğrendiğim

Bir dümenin öyküsüdür

Kırılmış sonsuz dönmelere

Ulaşmak özlemiyle

Samanyolu`nun memelerine.', 'Benim için şiir Daha göğün kucağında Yıldız emdiğim sıralarda Aydeden öğrendiğim Bir dümenin öyküsüdür Kırılmış sonsuz dönmelere Ulaşmak özl...', ARRAY['Türk Edebiyatı','Şiir','Ali Develioğlu']::text[], 8.5, '{"poet":"Ali Develioğlu","poet_slug":"ali-develioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/iirin-memeleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ki!', 'sen-ki-serdar-akcer-2c8en', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevdanı bir sözcüğe sığdırabilir misin? 

Hiç yüreğini yalnızlığın çıplak bedeninde uyandırdın mı sen? 

Sen ki ruhunu bedeninle eğdiren, ağlayabilir misin? 

Yoksa yalanlar mı dökülür gözlerinden

Bir gece acılarla gömülüp 

Kahkahaların ölümüne ''merhaba'' diyebilir misin? 

Sen hiç sevilmek nedir bilir misin? 

Dostluğun tadını yakaladın mı? 

Bir kahkaha ölüm çığlığı oldu mu kulaklarında? 

Güller nasıl yetişir bilir misin? 

Sen ki dostluğunu bir hiçliğe satan

Sen ki sevginin anlamını boşluğa atan

Sen ki kalleşliğin temsili

Sen mi bileceksin bütün bunların anlamını

Hayır! ben bileceğim.

Yalnızda olsam, kimsesizde

Bütün kapılar suratıma da kapansa

Yaramı saracak kimselerde olmasa

Sevgimin çiçekleri getirecek güzelliği

Bütün çıplaklığıyla.....

SERDAR AKÇER, Kasım 1999', 'Sevdanı bir sözcüğe sığdırabilir misin?  Hiç yüreğini yalnızlığın çıplak bedeninde uyandırdın mı sen?  Sen ki ruhunu bedeninle eğdiren, ağla...', ARRAY['Türk Edebiyatı','Şiir','Serdar Akçer']::text[], 8.5, '{"poet":"Serdar Akçer","poet_slug":"serdar-akcer","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sen-ki-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-serdar-akcer-ggozm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yalnızlık nedir bilir misin sen? ! 

Durgun denize bakıpta 

Devleşen dalgaları görmek

Aydınlık içinde karanlığı

Yıldızlara bakıpta 

Şimşeklerin çaktığını görmek

Boşlukta kalan kalbi dolu sanmak

Kırkında olup ta seksen yaşında olmak

Balıkçıların tekne seslerini dinleyipte

Sağır olduğunu düşünmek.

Buğulanmış gözlerde yarınları aramak

Yalnızlık nedir bilir misin sen? ! 

Seven kalbin atışının yavaş, yavaş yok oluşunu

Her şeyin sisler ötesine gidişini

Hayır! bilmezsin sen

Ben ne kadar kör 

Ne kadar sağır isem de

Kendi benliğimde yok oluşumda yine de kendimi arıyorum...

SERDAR AKÇER, Eylül 1995', 'Yalnızlık nedir bilir misin sen? !  Durgun denize bakıpta  Devleşen dalgaları görmek Aydınlık içinde karanlığı Yıldızlara bakıpta  Şimşekler...', ARRAY['Türk Edebiyatı','Şiir','Serdar Akçer']::text[], 8.5, '{"poet":"Serdar Akçer","poet_slug":"serdar-akcer","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yalnizlik-110-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönme Dolap', 'donme-dolap-naime-erlacin-09lhb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ne zaman sessizlik çökse

bilirim bir ses gelecek

öyle bir ses ki gümbür gümbür

ardından ortalık sessizliğe bürünecek

ne zaman bir ses gelse

bilirim sessizlik çökecek

öyle bir sessizlik ki sanki ölüm

ardından yer gök deprem

kafam karışık 

duygular dönme dolap

sessizlik çöküyor ruhuma

bir adaya çıkıyorum yüzerek

soruyorum

:

günbatımında yokladığım o eski uygarlık duruyor mu yerinde 

sessizliğe mi bürünecek

yine mi gürleyecek 

yaşamak 

tarih kadar eski 

uzakta bir ada kadar yalnız! 

dönüyor dolap…

(14 Mayıs 2003)', 'ne zaman sessizlik çökse bilirim bir ses gelecek öyle bir ses ki gümbür gümbür ardından ortalık sessizliğe bürünecek ne zaman bir ses gelse ...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/donme-dolap-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalleşlik', 'kalleslik-serdar-akcer-gixt1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kalleşlik üzerine kurulu

Hayatlarda kaybettim duygularımı

Bozdurdum gençliğimi

Bir çift yosmanın koynunda

Elleri nasırlı kadınlar yıkardı beni, 

Çocukluğumdan kalan 

Sigara ve duman kokusu

Birde çığlıkları martıların

Al yanaklı genç kızlar

Bırakıyorlar bakireliklerini

Kanlı çarşaflar üzerinde

Ağlamaları boşuna, devrandır bu böyle

Yıllardır süre gelen

İtler uluyor yine köşe başlarında

Caddelerde kan kokusu

Mezarlıklar bekliyorlar yeni sahiplerini

Musalla taşında tüm sevdiklerim

Terk ederlerken beni  yalnızlığıma...

Serdar AKÇER, Mayıs 2001', 'Kalleşlik üzerine kurulu Hayatlarda kaybettim duygularımı Bozdurdum gençliğimi Bir çift yosmanın koynunda Elleri nasırlı kadınlar yıkardı be...', ARRAY['Türk Edebiyatı','Şiir','Serdar Akçer']::text[], 8.5, '{"poet":"Serdar Akçer","poet_slug":"serdar-akcer","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kalleslik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Genç Kızın Bedeninde', 'bir-genc-kizin-bedeninde-serdar-akcer-tby6f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Zamanın içinden yaralı

Sevdası fırtına ile boyalı.

Körpe bedeninden geçer aşkın ateşi

Kısık gözleriyle gülen adamın

Amansız zamansız gidişi

Ateşli kırmızı yanakları

Gözlerinden saçıyor kinini

Kızın saçları sarı, kini kara

Öfkesiyle meydan okuyor yıllara

Bukleli tadında zamanın

Bir garip ahında adımın

Berrak teninde kadının

Ne aşklar yatıyor görünmez olmuş

Aşklar ki ne canlar yakıyor

Mızrap olup can telime vuruyor

Hep yaram kanıyor

Soluk benzimde çareler soluyor

Kızın teni soğuk

Sevdası hileli

Kini saklı, kalbi yaralı

Yosmalar ki peşimden koşuyor

Benim gönlüm yarim için atıyor

Kırmızı yanaklarını öpesim gelir

Sarı saçlarını sarasım gelir

Bir zaman sonra sandım geri gelir

Ne yosmalar duruyor

Ne de yarim geliyor.

Serdar AKÇER,2001 Mayıs', 'Zamanın içinden yaralı Sevdası fırtına ile boyalı. Körpe bedeninden geçer aşkın ateşi Kısık gözleriyle gülen adamın Amansız zamansız gidişi ...', ARRAY['Türk Edebiyatı','Şiir','Serdar Akçer']::text[], 8.5, '{"poet":"Serdar Akçer","poet_slug":"serdar-akcer","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bir-genc-kizin-bedeninde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıp Ceset', 'kayip-ceset-serdar-akcer-5xkqa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kayıpsa tüm duyguların 

Ağlayamazsın gidenin ardından 

Yitirmişsen özgürlüğünü, tutsaksan

Kelepçeler kesse de yüreğini

Bir adım yol, bir nefes bulamazsın

Düşmüşlerse tüm sevdiklerin

Derin kabuslar sarmışsa dört yanını

Aç yırtıcılar dolaşıyorsa başında

Dipsizse kuyular su çektiğin

Dostlar yoksa yanında geceleri

Yalnız, boş duvarlara akıtıyorsan gözyaşını 

Sessizce, içten içe ağlıyorsan

Ve acıtıyorsa gecenin yalnızlığı yüreğini

Kim diriltebilir ki artık seni! 

Hangi söz, hangi tavır, hangi düşünce

Bir sevdiğin bile yoksa yanında 

Son nefesinde kifayetsiz duruyorsan

Son kez haykıracak söz bulamazsan 

Yorgunsan ve bekliyorsa leş yiyicileri

Ki yoksa uğurlayan seni musalla taşından

Adsız yazılmışsan mezarlık siciline

Kaç yılı boşa harcamışsın dünyada

Kimleri sevmişsin, kimleri özlemiş

Kaç gece ölüp, kaç kez dirilmişsin

Kaç kez küllenmiş gönlünün ateşi

Hangi durumda canın çekmiş aşkı

Kimler ısıtmış içini, ciğerini 

Çektiğin cep kanyağından başka

Bir hiç uğruna heba edip ömrü

Hangi yosmanın peşinde harcamışsın hayalleri

Yoksa, hangi çılgın aşka feda olmuş ölümün

Bir duyan olur mu bu gece öldüğünü

Soğuk, ayaz vurmuş sokakta yatan kimin cesedi

Aşkın hangi sıcak yatakta yatarken

Kimin aşkıyla, nasıl ısınırken bilir mi? 

Seni bu tabuta kim koyar şimdi söyle

Dostların mı, yoksa yanından ayırmadığın sokak itleri mi? 



					Serdar AKÇER, Şubat 2003', 'Kayıpsa tüm duyguların  Ağlayamazsın gidenin ardından  Yitirmişsen özgürlüğünü, tutsaksan Kelepçeler kesse de yüreğini Bir adım yol, bir nef...', ARRAY['Türk Edebiyatı','Şiir','Serdar Akçer']::text[], 8.5, '{"poet":"Serdar Akçer","poet_slug":"serdar-akcer","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/kayip-ceset-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmek', 'bilmek-ali-ziya-camur-glvt9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bilmek, 

Zamanın burçlarında

Sabrın hurcunu çözmek.

Ezmek kuşkuların yedi başlı ifritini, 

Ay ışığında bulutları	  silmek.

Bilmek, 

Sevgilerin kavşağında

Kaldırımları ezen gizleri çözmek.

Gezmek yürek atlasında evreni

Çiçek çiçek yüreklere ekilmek.

Bilmek, 

Beynin kıvrımlarındaki fayda

Kitlelerin düşlerine sızmak.

Bozmak oyununu 

Kiralık konaktaki Ali Cengiz’in, 

Kara kanlı zalimlerin tepesine dikilmek.

Bilmek, 

Vazgeçilemeyen  sevdaların, 

Su katılmamış kıvamında

Destanını yazmak.

Kazmak düşünce ufkunun

Yedi katlı höyüğünü, 

Aymazlık düşlerinden apansızın irkilmek.

Bilmek, 

Karanlığa sıkılan  mermilerin

Çekirdeklerini belleğe dizmek.

Çizmek ölüm ormanında

Dirilenlerin halayını, 

Boyun bükmektense kudurmuşun dizginine, 

Dara çekilmek.

*2002 Hacıbektaş Şiir Yarışması Üçüncüsü', 'Bilmek,  Zamanın burçlarında Sabrın hurcunu çözmek. Ezmek kuşkuların yedi başlı ifritini,  Ay ışığında bulutları	  silmek. Bilmek,  Sevgiler...', ARRAY['Türk Edebiyatı','Şiir','Ali Ziya Çamur']::text[], 8.5, '{"poet":"Ali Ziya Çamur","poet_slug":"ali-ziya-camur","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/bilmek-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-serdar-akcer-h8pvj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bizim aşkımız dostluğumuzdu

Dostumuz değil! 

Yarınlara dair umudumuz

Dostluğumuzdu, aşk değil! 

Bizim dostluğumuz aşktı

Dost bize aşık değil! 

Umduğumuz dostluğumuz

Anladım ki bize alışık değil! ....

				Serdar AKÇER, Aralık 2001', 'Bizim aşkımız dostluğumuzdu Dostumuz değil!  Yarınlara dair umudumuz Dostluğumuzdu, aşk değil!  Bizim dostluğumuz aşktı Dost bize aşık değil...', ARRAY['Türk Edebiyatı','Şiir','Serdar Akçer']::text[], 8.5, '{"poet":"Serdar Akçer","poet_slug":"serdar-akcer","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ask-151-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatıralara Gömülen', 'hatiralara-gomulen-serdar-akcer-jtsjv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sahile vuran dalgalardı bizi yontan

Ateşlerin yaktığı çocukluğumuz

Atıkları kirlettiği sahilde.

Artık yok, simitçi Mustafa amca

İsmail efendi kapıyı çalmıyor ekmek bırakmaya

Yok eski dostlar, tatlı çekişmeler

Fener maçı tadında mahalle maçları yok

Dizlerimiz kanar 

Çamur içinde ayakkabılarla evlere giderdik

Azar sepetini takarak kolumuza

Hayat değişti, bizler gibi....

Bisiklete binemiyor, gönlümüzce gezemiyor

Aliye teyzenin değirmenden bozma evinin önünde 

Oturup dinlenemiyor, akan soğuk sudan içemiyoruz

Zaman neleri götürdü bizden

Eskiden saklambaç oynar, 

Küvetten bozma sandalla balığa çıkar, 

Kaya balıkları tutardık martılara çerezlik

Az mı seyrettik gün batımını bizim kumlu tepeden 

Bir kızı sevdim, o beni sevmedi

Ilık rüzgar esintisinde geçen çocukluk aşkımdı

Birkaç günlükte olsa

Biz bize yetiyorduk, bizler iyi dostlardık 

Dostluk dediğimiz şey, biz büyüdükçe uzaklaştı bizden

Önce bir telefon, sonra kartpostal oldu 

Şimdilerde ise ne haber var eski dostlardan, ne de gören

Yine ben olurum bu gece hatıralara gömülen...

Serdar AKÇER,1998 Mart', 'Sahile vuran dalgalardı bizi yontan Ateşlerin yaktığı çocukluğumuz Atıkları kirlettiği sahilde. Artık yok, simitçi Mustafa amca İsmail efend...', ARRAY['Türk Edebiyatı','Şiir','Serdar Akçer']::text[], 8.5, '{"poet":"Serdar Akçer","poet_slug":"serdar-akcer","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/hatiralara-gomulen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Geceleri Ağlardın', 'sen-geceleri-aglardin-serdar-akcer-a8p43', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen, geceleri ağlardın bana

Ben kaçarken kapından

Çakmaksı gözlerinle bakardın

Usulca yüreğim yanardı, anlamazdın.

Kaç gece yollarını gözledim ben, 

Kaç ayazda şafak bekledim.

Kapına sevda türküleri koyardım

Sen uyurken, gizliden ben.

Firari sevda şehirleri uzak

Tedirgin ele başları gecelerde

Mermisi ağzında karanlıklar mekan bulmuş

Buz tutmuş şehrin sokakları

İtler aç, itler perişan

Buz tutmuş dostun yüreği

Sevgiden uzak, benden kaçak

Zeytin yeşili gözlerini hangi sevda vurmuş

Söyle.....

Hangi alacalı karanlık çalmış beni senden

Gece karanlık, gece puslu

Kurt yürekler yer seni

Sen, geceleri ağlardın bana

Ben kaçarken kapından...

				Serdar AKÇER, Ocak 2002', 'Sen, geceleri ağlardın bana Ben kaçarken kapından Çakmaksı gözlerinle bakardın Usulca yüreğim yanardı, anlamazdın. Kaç gece yollarını gözled...', ARRAY['Türk Edebiyatı','Şiir','Serdar Akçer']::text[], 8.5, '{"poet":"Serdar Akçer","poet_slug":"serdar-akcer","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sen-geceleri-aglardin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalvaracaksın', 'yalvaracaksin-ersin-altioglu-3y2jf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Zehirli bir bıçak gibi girdin bedenime.Tatmadığım acıları tattırdın bana.Halden hale soktun beni...Sürüklendim ardınsıra.Dönüp birkez bile bakmadın ardına...Ama unuttuğun birşey var, bunu sakın unutma! Herzaman ardına bakmayan sen olamazsın.gün gelecek ki ardıma bakmam için bana yalvaracaksın...

                                             06.02.2003    02: 00', 'Zehirli bir bıçak gibi girdin bedenime.Tatmadığım acıları tattırdın bana.Halden hale soktun beni...Sürüklendim ardınsıra.Dönüp birkez bile b...', ARRAY['Türk Edebiyatı','Şiir','Ersin Altıoğlu']::text[], 8.5, '{"poet":"Ersin Altıoğlu","poet_slug":"ersin-altioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/yalvaracaksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tertemiz Yürek', 'tertemiz-yurek-serdar-akcer-5u8o0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tertemiz yüreğinle 

Umudu müjdeledin sevdiğine

Müjdelediğin umudu 

Unuttun birden bire

Anladığında bir gün hayatı

Koştuğun boş kulvarı

Dönüp bakarsın zamana

Giden gitmiştir senden

Elinde kalan yüreğin 

Bir kuru gül misali', 'Tertemiz yüreğinle  Umudu müjdeledin sevdiğine Müjdelediğin umudu  Unuttun birden bire Anladığında bir gün hayatı Koştuğun boş kulvarı Dönüp...', ARRAY['Türk Edebiyatı','Şiir','Serdar Akçer']::text[], 8.5, '{"poet":"Serdar Akçer","poet_slug":"serdar-akcer","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/tertemiz-yurek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Odamın Penceresi', 'odamin-penceresi-serdar-akcer-pl4wj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Odamın penceresinden 

Mavi gökyüzünü görmek gibi rüyam

Demir parmaklıklar kesse de güneşi

Kanatlanmışlar ya güvercinler bir kere

Bunca genç yaşıma rağmen

Yaşlılık tohumları ektiğimde yüreğime 

Zamana karşı koşturmam bundan 

Oysa sen daha gençliğinin deli çağında 

Cıvıl cıvıl sevinç yumağı', 'Odamın penceresinden  Mavi gökyüzünü görmek gibi rüyam Demir parmaklıklar kesse de güneşi Kanatlanmışlar ya güvercinler bir kere Bunca genç ...', ARRAY['Türk Edebiyatı','Şiir','Serdar Akçer']::text[], 8.5, '{"poet":"Serdar Akçer","poet_slug":"serdar-akcer","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/odamin-penceresi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırık Canlar', 'kirik-canlar-serdar-akcer-hjwx2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayata tutunamamak kenarından

Belki de kabullenmemek olanları

Hangimiz küsmedik hayata zaman zaman

Hangimiz bozdurmadık ümitleri

Yiten yaşamda kimimiz yalnız

Kimimiz kayıp bu garip deryada

Çoğumuz eksik kaldı 

Bu uçurumun kenarında

Terk edilmek gibi bir diyarda

Az mı sustuk az mı susturulduk

Çift dikiş hayatta

Karneler kırık

Kalpler kırık

Canlar kırık...', 'Hayata tutunamamak kenarından Belki de kabullenmemek olanları Hangimiz küsmedik hayata zaman zaman Hangimiz bozdurmadık ümitleri Yiten yaşam...', ARRAY['Türk Edebiyatı','Şiir','Serdar Akçer']::text[], 8.5, '{"poet":"Serdar Akçer","poet_slug":"serdar-akcer","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kirik-canlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Güzel Düşüm', 'en-guzel-dusum-serdar-akcer-5dhb0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gökyüzünden bulutlar yağar 

Ben hüzünle burada

Sen en güzel düşüm, en güzel rüyam

Keşke hiç uyanmasam

Yemyeşil gözlerinden

Hayatım gelir geçer

Dudaklarının soğukluğu

Bembeyaz saflığı yüreği

İçindeki canavarlar ki

Gitmeli...

Sen en güzel düşüm, en güzel rüyam

Keşke hiç uyanmasam

Sen ki sevmeyi hatırlattın

Unuttuğum duygularımdın

Yüreğimdeki kuş 

Kırar parmaklıkları

Sen en güzel düşüm, en güzel rüyam

Keşke hiç uyanmasam

Uzakta da olsan benden şimdi

Düşünüyorum seni

Kim bilir sen nerede

Kimlerle

Sen en güzel düşüm, en güzel rüyam

Keşke hiç uyanmasam

Günde kaç kez kovalar 

Yelkovanla akrep

Ben hasret sohbete

Şimdi gitmen lazım

Sen en güzel düşüm, en güzel rüyam

Keşke hiç uyanmasam

Uzaklaşmalısın ki benden

Sen hayata bağlanasın

Acılara alışık olan ben

Sensizliğe de alışırım zaten

Düşünüyorum seni

Hatalar nerede? 

Sen en güzel düşüm, en güzel rüyam

Keşke hiç uyanmasam', 'Gökyüzünden bulutlar yağar  Ben hüzünle burada Sen en güzel düşüm, en güzel rüyam Keşke hiç uyanmasam Yemyeşil gözlerinden Hayatım gelir geç...', ARRAY['Türk Edebiyatı','Şiir','Serdar Akçer']::text[], 8.5, '{"poet":"Serdar Akçer","poet_slug":"serdar-akcer","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/en-guzel-dusum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlıklar', 'karanliklar-ersin-altioglu-50ebs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gecenin en karanlık yerinde

Loş bir sokak lambasının aydınlattığı

Soğuk bir duvar kenarında 

Düşünüyorsan yalnızlığını...

Düşünüyorsan geçmişini...

Ve de geçmişini özlüyorsan 

Boşuna gülüm boşuna....

Çünkü; 

Ne yalnızlığın biter karanlıklarda

Ne de karanlıklar geri getirir

O özlediğin geçmişini sana

                                30.04.2003     00: 16', 'Gecenin en karanlık yerinde Loş bir sokak lambasının aydınlattığı Soğuk bir duvar kenarında  Düşünüyorsan yalnızlığını... Düşünüyorsan geçmi...', ARRAY['Türk Edebiyatı','Şiir','Ersin Altıoğlu']::text[], 8.5, '{"poet":"Ersin Altıoğlu","poet_slug":"ersin-altioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/karanliklar-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskiden', 'eskiden-serdar-akcer-oarve', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Eskiden, çocukken hayaller beslerdim yüreğimde 

Mahalle yollarında, su birikintilerinde barajlar kurardım

Umutlar sevgi denizlerine dönüşsün diye 

Ki kadınlar halılarını yıkardı orada

Oynardım çocukluğumdan kalan sevinçle 

Değmemişti kirli elleri zamanın yüreğime

Bazen kızardım olur olmaz şeylere

Sonrada ağlardım bilmeden gözyaşımın ağırlığını

Bir tatlı söze kanardım yalnızlığımla tanışırken

Susardım bağırırken yaşıtlarım sokaklarda

O anlarda dünyaları ben yaratmıştım', 'Eskiden, çocukken hayaller beslerdim yüreğimde  Mahalle yollarında, su birikintilerinde barajlar kurardım Umutlar sevgi denizlerine dönüşsün...', ARRAY['Türk Edebiyatı','Şiir','Serdar Akçer']::text[], 8.5, '{"poet":"Serdar Akçer","poet_slug":"serdar-akcer","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/eskiden-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deprem', 'deprem-serdar-akcer-0y7g3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Onlarca dostu gömüp toprağın altına

Bıraktım  doğduğum diyarları

Sonra tanıyıp bir güzeli

Hayatımı kurtardım kayıp zamanlarda

Ya onun elleri olmasa 

Hangi köşelerde sönecektim

Yine oynadı oyununu hayat

Ben yalnız diyarlarda 

O hangi yarinin yanında....', 'Onlarca dostu gömüp toprağın altına Bıraktım  doğduğum diyarları Sonra tanıyıp bir güzeli Hayatımı kurtardım kayıp zamanlarda Ya onun elleri...', ARRAY['Türk Edebiyatı','Şiir','Serdar Akçer']::text[], 8.5, '{"poet":"Serdar Akçer","poet_slug":"serdar-akcer","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/deprem-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Susmak Bilmiyorsa Yalnızlığın', 'susmak-bilmiyorsa-yalnizligin-ersin-altioglu-7eotr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Susmak bilmiyorsa yalnızlığın

Acıtmıyorsa özlemlerin

Bitmiyorsa kederlerin

hüzünlendirmiyorsa geçmişin

Varmışsın o zaman tadına

Sonu olmayan bu boş ama bomboş dünyanın...

                          30.04.2003       00.26', 'Susmak bilmiyorsa yalnızlığın Acıtmıyorsa özlemlerin Bitmiyorsa kederlerin hüzünlendirmiyorsa geçmişin Varmışsın o zaman tadına Sonu olmayan...', ARRAY['Türk Edebiyatı','Şiir','Ersin Altıoğlu']::text[], 8.5, '{"poet":"Ersin Altıoğlu","poet_slug":"ersin-altioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/susmak-bilmiyorsa-yalnizligin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Çiceği', 'sevda-cicegi-fikret-kizilok-9olkn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sessiz sedasiz açardın gecelerde

Kimse bilemez görez kuytularda

Sonsuz ve dipsiz sevdalarda duygularda

Sakin kimsesiz ve sahipsiz uykularımda

Şimdi artık seni koklar yanlızlığım 

Seni arar seni sorar sevda çiçeğim', 'Sessiz sedasiz açardın gecelerde Kimse bilemez görez kuytularda Sonsuz ve dipsiz sevdalarda duygularda Sakin kimsesiz ve sahipsiz uykularımd...', ARRAY['Türk Edebiyatı','Şiir','Fikret Kızılok']::text[], 8.5, '{"poet":"Fikret Kızılok","poet_slug":"fikret-kizilok","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sevda-cicegi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babaanne', 'babaanne-tulay-sustam-vvy0a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni aramızdan zamansız aldı zalim kara toprak

Yatağın bomboş, kokuna hasret bu avare çaylak

Yüreğimde tarifi imkansız o dayanılmaz sancıların

Dinmiyor bir türlü kulaklarım da çığlıkların babaanne...

Sen; bir ömür boyu yatağa mahkum olacak kadın mıydın? 

Karanlığı severdin, sen hep hava karardığın da ağlardın

Hiçbir ilaç merhem olmadı kanayan yaralarına

Bir hayal, bir hevesti senin için kalkıp yürümek

Elin ayağın tutmuyordu, derman yoktu dizlerinde

Ormanın o güzelim yeşilliğin de yürüyemedin dilediğince

Çıkmak istedin de çıkamadın bir türlü karşıda ki tepeye

İstediğin gibi gezip dolaşamadın bu caddelerde 

Gönlünce bir çay içemedin akşam serinliğinde

Gezip dolaşmanın özlemi tütüyordu buram buram gözlerin de

Her şeyin buruk bir tadı vardı dile gelmeyen sözlerinde

Eskisi gibi tarla biçmeni, hayvanları otlatmanı istedim

Ne bir daha tarla biçtin ne de hayvanları otlattın babaanne...

Her yanın binbir türlü acılar içindeyken 

Yine de bir umut vardı zavallı kocaman yüreğinde

Sönmeyen, sönmek bilmeyen bir ışık vardı gözbebeklerinde

Hiçbir zaman yenilmedin, umudunu yitirmedin babaanne...

Dolaşmanı istedim bu kahrolası dünyayı diyar diyar

Yanaşmadığın liman, geçmediğin sokak kalmasın istedim

Ne limana yanaştın ne de bu sokaktan bir kez olsun geçtin

Saçların beyazlamış, yüzün de yılların derin çizgileri olsa bile

Elin ayağın tutmasa bile sen yine de güzeldin babaanne...

Bir kez olsun koluma takıp gezdiremedim seni

İstedim ki sende ayakların üzerinde destek almadan dur

Yürü benim gibi, yürü yürümeye başlayan çoçuklar gibi

Ne ayakta durdun, ne de yürüdün babaanne...

Hatırlıyorum da; ilk maaşımla sana ilaç almıştım

Çok sevinmiştin bir o kadar da şaşırmıştın

Şimdi yoksun, ben o ilaçtan her ay yine alıyorum babaanne...

Hatırlıyorum da; her akşam işten eve dönmemi beklerdin

Biraz geç kalsam camdan yolumu gözlerdin

Beni görünce dünyalar senin olurdu, sevinirdin çoçuklar gibi

Unuturdun bir an o dayanılmaz sancılarını

Okumamı çok isterdin, diplamamı ilk sen görmek istedin

Sana söz vermiştim ilk sen görecektin diplomamı

Diplomayı alıp eve geldiğimde sen yoktun  babaanne...

Senden sonra da okumadım, çalışmaya başladım

Sözümde durdum kimseye göstermedim diplomayı babaanne...

En büyük hazine, insanın o küçük yüreğinde derdin

En büyük zafer, insanın kendi kendini yenmesinde derdin

Bu yüzden yıllarca verdiğin savaşta yenilmedin babaanne...

Kimsenin ruhu duymadan, sessiz sedasız çekip gittin

Bir veda bile etmedin, bir elveda bile demedin babaanne...

Duymadın çığlıklarımı, görmedin yüreğimde ki yangını

Seni çok özledim, beni yalnız bıraktın babaanne...

Bir çiçek gibi her bahar yeniden yeşereceksin yüreğimde

Her zaman senin için bir damla gözyaşı olacak gözbebeklerimde

Oralar da kendine iyi bak, gözün arka da kalmasın

Aklın biz de, aklın buralar da olmasın babaanne...

Sana söz veriyorum babaanne...

Akşam serinliğinde bir yudum çayı senin için içeçeğim

Çıkamadığın o tepeye senin heykeli dikeceğim

Senin yerine hayvanları otlatıp, tarla biçeceğim

Geçemediğin bu sokaktan kadere inat binlerce kez geçeceğim

Yanaşamadığın limanlara kendimi sonsuza dek demirleyeceğim

Okuyup büyük adam olamadım ama hiç pes etmeyeceğim

Seni çok özledim sende bu karakızı özledin mi babaanne...

Hani her gidişin bir dönüşü vardı 

Şimdi sen dönüşü olmayan bir yerdesin

Dönmeyeceğini bile bile yine de bekleyeceğim seni babaanne...

Bekle beni babaanne ne olursa olsun bekle 

Az kaldı yanına geleceğim babaanne...

Bir gün ansızın haber vermeden geleceğim

Haberin olmayacak gelişimden babaanne...

Unutmadım, unutamadım, unutmayacağım seni babaanne...

''Ölürsem gözlerim açık giderim'' demiştin.

Neden gözlerin açık gittin neden babaanne...

(08.06.1996 Cumartesi, İstanbul)', 'Seni aramızdan zamansız aldı zalim kara toprak Yatağın bomboş, kokuna hasret bu avare çaylak Yüreğimde tarifi imkansız o dayanılmaz sancılar...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":72,"source_url":"https://www.antoloji.com/babaanne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıkma Yollarıma Çıkma Serseri', 'cikma-yollarima-cikma-serseri-tulay-sustam-iy0bj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Boş bir hayal uğruna yazık yıllarımı harcadım

Bir zalimin yüzünden çıkmaza girdi yollarım

Farkına varmadan geçti o güzelim yıllarım

Köşe bucak heryerde şimdi mazimi ararım

Çıkma yollarıma çıkma artık serseri

Bir daha sevemem seni eskisi gibi

Hadi düş yakamdan bırak peşimi

Ben; ben değilim olamam eskisi gibi

Unuttum seni, unuttum buseni

Sayıklamıyorum adını artık geceleri

Sildim bir kalem de geçmişimi ve seni

Karşıma çıkma arama bir daha beni

Çıkma yollarıma çıkma artık serseri

Sevemem seni bir daha eskisi gibi

Hadi düş yakamdan unut artık beni

Ben; ben değilim olamam eskisi gibi', 'Boş bir hayal uğruna yazık yıllarımı harcadım Bir zalimin yüzünden çıkmaza girdi yollarım Farkına varmadan geçti o güzelim yıllarım Köşe buc...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cikma-yollarima-cikma-serseri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte Dünya', 'i-ste-dunya-harun-haliboro-2c8jt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yıllar bir rüya gibi

Tılsımlı hülya gibi

Anlamadık geçerken

Soldular fulya gibi

Saçlarımız kırlaştı

Hareket ağırlaştı

Ömrün sonu yaklaştı

Değişen dünya gibi.

23.05.2000

İstanbul', 'Yıllar bir rüya gibi Tılsımlı hülya gibi Anlamadık geçerken Soldular fulya gibi Saçlarımız kırlaştı Hareket ağırlaştı Ömrün sonu yaklaştı De...', ARRAY['Türk Edebiyatı','Şiir','Harun Haliboro']::text[], 8.5, '{"poet":"Harun Haliboro","poet_slug":"harun-haliboro","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/iste-dunya-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neye Sayarsan Say', 'neye-sayarsan-say-tulay-sustam-ehcm9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çaresiz iliklerime kadar işlemişti yokluğun

Güne seninle başlardım senden habersiz

Elimde değildi seni bir an bile anmamak

Geceler boyu gözyaşım vardı yanaklarımdan süzülen

Yağmur bile kıskanırdı her gece gözyaşlarımı

Yazık boşuna ağlamışım, boşuna yanmışım

Aldanmışlığıma say...

Seni sayıklamaktan görmedim çevremde olup biteni

Aslında biliyordum beni hiçbir zaman sevmeyeceğini

Oysa ben bıkmadan, usanmadan bekledim belki bir gün severdin diye

Görmeni, bilmeni istedim bende ki senli sevgi selini

Sevmedin, sevemedin, sevildiğini bilmedin

Susamışlığıma say...

Hiç bu kadar çaresiz hissetmedim kendimi

İlk defa yorgun düştüm bir insanı sevmekten

Çaresiz sana açılmakta buldum çözüm yolunu

Dedim ya; 

''Taze iken içimde dışa vurduğum da kuruyor güllerim''

Keşke bilmeseydin sevdiğimi, kabusa dönüştü gecelerim

Çaresizliğime say...

Şimdi kafam rahat düşünmüyorum artık gecelerce seni

Doğru olan da buydu hiç olmamalıydın hayatımda

Dilerim artık herkes mutlu olur gittiği yolda

Kalemi elime aldığım da yazamıyorum dizelere seni

Ne bir insan bu kadar sevmeli ne de sevilmeli

Cahilliğime say...

Sevdim seni bir kere çocuk neye sayarsan say...

(İstanbul, 06.06.2001)', 'Çaresiz iliklerime kadar işlemişti yokluğun Güne seninle başlardım senden habersiz Elimde değildi seni bir an bile anmamak Geceler boyu gözy...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/neye-sayarsan-say-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bravo', 'bravo-harun-haliboro-nfrq4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen kendi başına buyruk

Sen uçuktan daha uçuk...

Belli oldu bıktığın

Bu aşktan sıkıldığın...

Beynime balyoz gibi indi

Sözlerin.

Kalbime akıttığın zehir

Benliğimi bitirdi.

Ben, bensiz kalırdım da

Sensiz kalamazdım.

Bunu başardın

Bravo! 

11.05.2003

İstanbul', 'Sen kendi başına buyruk Sen uçuktan daha uçuk... Belli oldu bıktığın Bu aşktan sıkıldığın... Beynime balyoz gibi indi Sözlerin. Kalbime akıt...', ARRAY['Türk Edebiyatı','Şiir','Harun Haliboro']::text[], 8.5, '{"poet":"Harun Haliboro","poet_slug":"harun-haliboro","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bravo-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bende ki Sen', 'bende-ki-sen-tulay-sustam-r10yw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bitmedi bir türlü bende ki bu tepe sevdası

Deli ediyor beni işvesi, nazı ve edası

Ey kara dudaklım sensin benim başımın belası

Senden öncesi olabilir ama yok senden sonrası

Gözlerinle bakıp görürüm her şey kömür karası

Sensin benim efendim, sensin bedenimin ağası

Bir elmanın yarısı ben olur musun sen de diğer yarısı

Bitmedi gönlümün sana olan kara sevdası

Seni ölümüne sevdim yanında acı çekmek cabası

Hiçbir şeye benzemez bu bende ki gönül yarası

Dünyam ancak seninle yeşillenip olur çiçek tarlası

Uzaklarda arama işte karşında duruyor çocuğunun anası', 'Bitmedi bir türlü bende ki bu tepe sevdası Deli ediyor beni işvesi, nazı ve edası Ey kara dudaklım sensin benim başımın belası Senden öncesi...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bende-ki-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Durak', 'son-durak-harun-haliboro-n29p6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dilimi bağladı, 

Kalbimi

Dört yerinden dağladı

Senin vefasızlığın.

Nedir duygulara

Bu saygısızlığın...

Şimdi beni benle bırak

Git başka gönüllere ak

Senin için son durak

Kalpsizler olur ancak.

02.0402003

İstanbul', 'Dilimi bağladı,  Kalbimi Dört yerinden dağladı Senin vefasızlığın. Nedir duygulara Bu saygısızlığın... Şimdi beni benle bırak Git başka gönü...', ARRAY['Türk Edebiyatı','Şiir','Harun Haliboro']::text[], 8.5, '{"poet":"Harun Haliboro","poet_slug":"harun-haliboro","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/son-durak-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çoban Yıldızım', 'coban-yildizim-tulay-sustam-5ggyu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Azıcık saçlım, kirli sakallım

Kara dudaklım, asi bakışlım

Senin yüzünden, senin derdinden

Bir gece de bütün kahırları yazdım

Senin derdinden, senin yüzünden

Sabahlara kadar kadehimi sana kaldırdım

Bir senin için ağladım

Bir sana böylesi yandım

Neredesin çoban yıldızım? 

Neredesin? 

Kiminlesin? 

Hangi şehirde kimin koynunda...

Kimdesin? 

Kiminlesin? 

Söyle bana günahım artık boynuna...

Seni sevdim

Bir seni böylesi ölümüne sevdim

Gülüp geçme halime el gibi

Günün birinde seversin diye bekledim

Ben çaresiz yanmışım, ah ben yanılmışım

Senin beni seveceğin yok ben kendimi kandırmışım

Hiç ummadığım zamanlar da çıkma artık karşıma

Görmesin bu körolası gözler seni...

Yüreğim hiç bilmediğim dağların ardında

Gitme uzaklara özler bu yürek yine seni...

Kara dudaklım, asi bakışlım

Azıcık saçlım, kirli sakallım

(Tekirdağ, 12.08.2000)', 'Azıcık saçlım, kirli sakallım Kara dudaklım, asi bakışlım Senin yüzünden, senin derdinden Bir gece de bütün kahırları yazdım Senin derdinden...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/coban-yildizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksun', 'yoksun-tulay-sustam-4dshd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu kaçıncı bahar, sen yanımda yoksun

Bu kaçıncı akşam, sen koynum da yoksun

Ben sana hasret, sen bana hasret

Sen benden yoksun, ben senden yoksun

Yoksun, yoksun yine yanımda yoksun

Yoksun, yoksun yine kollarım da yoksun

Özledim seni, özledim buseni, özledim her şeyini

Yoksun, yoksun yokluğuna lânet olsun', 'Bu kaçıncı bahar, sen yanımda yoksun Bu kaçıncı akşam, sen koynum da yoksun Ben sana hasret, sen bana hasret Sen benden yoksun, ben senden y...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yoksun-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rozalya', 'rozalya-oktay-yivli-dxj2y', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çokluk kararan saatlerde

Penceremi

Akasya kokulu

Akşamlara açıyorum Rozalya

Akasyalar ki

Haziranlı ikindilerde

Gölgelerinde sevişmiştik

Akasyalar aynı yerde

Karanlıkla rüzgâra verir kendini

Fakat biz Rozalya

Fakat biz

Seviştiğimiz günlerin

Çok uzağındayız

Aynı zaman dilimlerinde

Başka şeyler düşünen kişileriz

Biliyorum bu akşam

Akasyalı anılar

Gönlümü benden çalıp

Başka ülkelere sürükleyecek

Ya sen peki...

Sen de biraz olsun

Düşünmez misin o günleri? 

Sanmam ki bu saatte

Uyanık olasın Rozalya

Ancak yatağında sere serpe

Renkli rüyalara

Yatmış olabilirsin belki

Fakat dikkat et Rozalya

Bilirsin ki rüyalar

Anılar kadar

İnsaflı olmayabilir', 'Çokluk kararan saatlerde Penceremi Akasya kokulu Akşamlara açıyorum Rozalya Akasyalar ki Haziranlı ikindilerde Gölgelerinde sevişmiştik Akas...', ARRAY['Türk Edebiyatı','Şiir','Oktay Yivli']::text[], 8.5, '{"poet":"Oktay Yivli","poet_slug":"oktay-yivli","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/rozalya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilim Söyleyemedi', 'dilim-soyleyemedi-sair-harputlu-m-qynks', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kalbimmi suskun yoksa dilimmi

Gözlerimmi şaşkın yoksa benmi 

Zaman ansızın gelip geçti

Dilim söyleyemedi seni sevdiğimi

Çiçekler açtı bir bahar daha geldi

Seni sevdiğim günleri ayları geçti

Sevdamı bilenler alay edipte geçti

Dilim söyleyemedi seni sevdiğimi

Günler bir bir ömrümden aldı

Seni ben değil Başkası aldı

Bak nikahına üç gün üç saat kaldı

Dilim söyleyemedi seni sevdiğimi

Sen şimdi beyaz gelinlik içinde

Bende beyazlar ama kefen içinde 

İmamlar toplanmış son nefesimde

Dilim söyleyemedi seni sevdiğimi

^^Biliyorum bir ömür boyu dilim söyleyemedi seni sevdiğimi.Senin o gözlerin ve kalbin beni anladığında ise çok geç olmuştu.Çünkü sen üç beş çocuklu bir anne ben ise yeryüzünde yaşayan bir ceset idim artık.Dilim söyleyemedi seni sevdiğimi ama bak şimdi mezar taşıma dağum tarihim senle ölüm günüm evlendiğin gün ve susmuyor haykırıyor artık

mezar taşım BEN SENİ SEVİYORUM kezban.....', 'Kalbimmi suskun yoksa dilimmi Gözlerimmi şaşkın yoksa benmi  Zaman ansızın gelip geçti Dilim söyleyemedi seni sevdiğimi Çiçekler açtı bir ba...', ARRAY['Türk Edebiyatı','Şiir','Şair Harputlu`m']::text[], 8.5, '{"poet":"Şair Harputlu`m","poet_slug":"sair-harputlu-m","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dilim-soyleyemedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Seni Bütünüyle Sevdim', 'ben-seni-butunuyle-sevdim-tulay-sustam-7gp0q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu şiiri yazmam da katkıda bulunan yüreğimin yarısı yağmur tanesine...)

Her gece sorardım kendime neyini sevdim ben senin diye.

Ben senin ne kaşını, ne gözünü, ne boyunu ne de duruşunu sevdim.

Hâlbuki sorsalar bana göz rengini bile bilmem.

Bilmem senin neyi sevip, neyi sevmediğini.

Bildiğim tek şey var o da beni hiç sevmediğin.

Ben senin aklımdan çıkaramadım kaçamak süzüşünü sevdim.

Bakışını, gülüşünü, yüreğinde ki çocuk sevgisi sevdim.

Ben seni hiç kimsenin sevemeyeceği kadar sevdim.

Ben seni senin kim olduğunu bilmeden sevdim.

Ben senin bilmediğim teninin kokusu sevdim.

Seni gördüğüm de elimin, ayağımın birbirine dolaşmasını sevdim.

Ben seni bir annenin yavrusunu sevdiği gibi sevdim.

Ben seni babama taptığım gibi, anamı sevdiğim gibi sevdim.

Ben senin bana deli demeni sevdim.

Oysa bir kere oturup düşündün mü neden deli olduğumu? 

Ben senin her halini, her şeyini sevdim ve öyle kabullendim.

Ben seni sevdim, senden sonra kendimi sevemedim.

Ben seni bütünüyle sevdim.

Ben seninle bir mayıs akşamın da, 

Kabataş İskelesi''nde içtiğim bir yudum çayı sevdim.

Bilmeden bana tatdırdığın hayatımın en büyük aşkını

Ve senden gelen o kahrolası acıları bile sevdim.

Hiç ummadığım zamanlar da karşıma çıkmanı sevdim.

Ben seninle kurduğum dünyayı sevdim.

Tek arzum, tek isteğim, tek sevdiğimdin benim.

Ben sana ruhumu, gözlerimi, yüreğimi teslim ettim.

Oysa sen düşünmeden beni geri çevirdin.

Dağ gibi bir yüreği küle çevirdin, yok ettin.

Benden eserim diye bahsettin, işte o gün sen kaybettin.

Sen bir elma ağacıydın, ben senin meyveni vermek istedim.

Bir ağacı kökünden baltaladın oysa sen meyve veremezdin.

Çünkü sen bir meyveyi dalından hiç yemedin.

Soğuk rüzgârlar estirip durdun yüreğim de.

Hep ecelim oldun, çarem olmayı denemedin.

Başka kollar da aradın mutluluğu, sana uzanan dalı da kestin.

Saldım seni yüreğimin kafesinden, sen başka şehirlere uçup gitmedin.

Bırakmadın beni kendi halime, bırakmadın beni bir başıma.

Sen dalıma konmadan önce ben mutluydum, aldırmadın gözyaşıma.

Senin derdinden gecemi, gündüzümü karıştırdım.

Senin yüzünden yüreğimin kapılarını sonsuza dek kapattım.

Ben bende ki seni kimseye anlatamadım, bunu sende anlamadın.

Yüreğimi sana açtım sen ise acımasızca sorguladın.

Unutmak istiyorum seni, çek git artık dünyamdan.

Haberini almıyorum artık martılardan.

Senden geriye bir tek o kahrolası gülüşün kaldı.

Senin kadar beni hiç kimse böyle yaralamadı.

Bu yürek böylesi hiç yanmadı.

Bir türküdür adın dilimde, nakaratını hiç bilmediğim.

Bir bilinmeyensin bende hiçbir zaman çözemediğim.

Rüzgârına kapıldım bilmiyorum şimdi nerdeyim.

Mecnun uğruna yollara düşmüş deli divaneyim.

Ben senin gökyüzün de bir yıldız olmanı sevdim.

Sana ulaşamamayı, sana dokunamamayı sevdim.

Ben senin varlığınla değil, hayalinle yaşamayı sevdim.

Kalemi elime her aldığım da seni satırlara yazmayı sevdim.

Küçücük bir yüreğe, kocaman bir sevgiyi sığdırmayı sevdim.

Her geçen gün senin karşında eriyip yok olmayı sevdim.

Ben seni günlerce, gecelerce sayıklamayı sevdim.

Ben sende ki gizemi, yalnızlığı sevdim.

Ben seni yüreğimde yaşatmayı sevdim.

Bir ömür boyu soğuk rüzgârlar estireceğini bilsem yüreğimde.

Boynumu eğmem önüme, bir kere olsun dönüp bakmam geçmişe.

Ben seni sevdim, senden sonra kimseyi sevemedim.

Ben seni bütünüyle sevdim.

(İstanbul, 30.10.2001)', 'Bu şiiri yazmam da katkıda bulunan yüreğimin yarısı yağmur tanesine...) Her gece sorardım kendime neyini sevdim ben senin diye. Ben senin ne...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":66,"source_url":"https://www.antoloji.com/ben-seni-butunuyle-sevdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine seni hatırlıyorum', 'yine-seni-hatirliyorum-suleyman-cakir-kndi8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '.....

ve işte, 

bir nisan akşamında

yağmurun ıslattığı 

toprağın kokusunda

bir özlem duygusu ile

yine seni hatırlıyorum 

1 nisan 2003', '..... ve işte,  bir nisan akşamında yağmurun ıslattığı  toprağın kokusunda bir özlem duygusu ile yine seni hatırlıyorum  1 nisan 2003...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Çakır']::text[], 8.5, '{"poet":"Süleyman Çakır","poet_slug":"suleyman-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yine-seni-hatirliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatılmıyor', 'anlatilmiyor-erdinc-asik-41391', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sensiz ilkbaharım kışa döndü

Aydınlık günlerim karanlığa büründü

Yağan yağmur başıma taş diye düştü

Yokluğun öyle zor ki anlatılmıyor

Dağı taşı yıkasım gelir

Mazimi silip atasım gelir

Sensizlik aldı beni esir

Yokluğun öyle zor ki anlatılmıyor

Yürüyorum adımlarım sana doğru

Hayalin önümde pusula oldu

Uzanan ellerin tutulmaz oldu 

Yokluğun öyle zor ki anlatılmıyor', 'Sensiz ilkbaharım kışa döndü Aydınlık günlerim karanlığa büründü Yağan yağmur başıma taş diye düştü Yokluğun öyle zor ki anlatılmıyor Dağı t...', ARRAY['Türk Edebiyatı','Şiir','Erdinç Aşık']::text[], 8.5, '{"poet":"Erdinç Aşık","poet_slug":"erdinc-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/anlatilmiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgilim', 'sevgilim-erdinc-asik-ty088', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Elimde kalan bir tek resmin

Dilimde ise yanlız senin ismin

Gece gündüz hep hayalimdesin

Unutamam çünkü sen kalbimdesin

Beni bana bırakan sensin 

Böyle yaşamaya hayat mı? dersin

Yetti çileler artık son versin

Unutamadım hala ALLAH kahretsin

Sözüm geçmez kendi kendime

İsyanım sensiz geçen günlere

Yinede dalarım o güzel mazimize

Sızı vursada şu yaralı kalbime', 'Elimde kalan bir tek resmin Dilimde ise yanlız senin ismin Gece gündüz hep hayalimdesin Unutamam çünkü sen kalbimdesin Beni bana bırakan sen...', ARRAY['Türk Edebiyatı','Şiir','Erdinç Aşık']::text[], 8.5, '{"poet":"Erdinç Aşık","poet_slug":"erdinc-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevgilim-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zalim Felek', 'zalim-felek-erdinc-asik-znl13', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bana değil sorun kara yazıma

Merhamet etsin şu genç yaşıma

Gün gelirde kıyarsam bu cana

Üzülemsin söyleyin dostlarıma

Suç bende değil beni bu hale getirende

Gülmedi hiç yüzüm şu koca alemde

Saplarım hanceri kendi kendime

Yinede vermem bu canı onun eline

Kalmadı gönlümde mutluluğun sevinci

Bir derdim vardı şimdi binler eklendi

Zalim feleğin oyunu sonunda benide yendi

Öyle vurdu ki beni rezil hale getirdi', 'Bana değil sorun kara yazıma Merhamet etsin şu genç yaşıma Gün gelirde kıyarsam bu cana Üzülemsin söyleyin dostlarıma Suç bende değil beni b...', ARRAY['Türk Edebiyatı','Şiir','Erdinç Aşık']::text[], 8.5, '{"poet":"Erdinç Aşık","poet_slug":"erdinc-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/zalim-felek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Kalbim', 'ah-kalbim-orhan-baran-sqx65', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ah kalbim

Dağ meltemlerinin dostu kalbim

Eser eser de

Durulmaz kalbim

Gün doğar, gün batar da

Bir sakin limana konmaz kalbim

Ah kalbim

Kurşunlar çarpar çarpar da

Erguvanlar açar kalbim

Talan edilmiş sevdaların

Uğrağı kalbim

Saçlarım uzar

Tırnaklarım uzar

Uzamaz kalbim

Ah kalbim

Kalbim

Ey ipek kanatlı Anka kuşu

Küllerini getir kalbime

Kalbini getir

ve yedi rengini ruhunun

O zaman

Yanık kalbim

Küllerinden yeniden doğar belki', 'Ah kalbim Dağ meltemlerinin dostu kalbim Eser eser de Durulmaz kalbim Gün doğar, gün batar da Bir sakin limana konmaz kalbim Ah kalbim Kurşu...', ARRAY['Türk Edebiyatı','Şiir','Orhan Baran']::text[], 8.5, '{"poet":"Orhan Baran","poet_slug":"orhan-baran","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ah-kalbim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nisan Yağmurları', 'nisan-yagmurlari-orhan-baran-0jqva', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Su ver kalbine 

Nisan yağmurlarından

Ki kalbin ürpersin bir gonca gibi

Su ver kalbine

Çeliğe su verir gibi

Ki kalbin delsin geceyi', 'Su ver kalbine  Nisan yağmurlarından Ki kalbin ürpersin bir gonca gibi Su ver kalbine Çeliğe su verir gibi Ki kalbin delsin geceyi...', ARRAY['Türk Edebiyatı','Şiir','Orhan Baran']::text[], 8.5, '{"poet":"Orhan Baran","poet_slug":"orhan-baran","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/nisan-yagmurlari-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar Şarkısı', 'bahar-sarkisi-orhan-baran-d3fsf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir kelebeğin gözleri ışıldarsa

ve kalbi çarparsa sevgi depremleriyle

Bil ki gün doğmuştur

ve bil ki 

Kulağına baharın şarkısı değmiştir kelebeğin', 'Bir kelebeğin gözleri ışıldarsa ve kalbi çarparsa sevgi depremleriyle Bil ki gün doğmuştur ve bil ki  Kulağına baharın şarkısı değmiştir kel...', ARRAY['Türk Edebiyatı','Şiir','Orhan Baran']::text[], 8.5, '{"poet":"Orhan Baran","poet_slug":"orhan-baran","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bahar-sarkisi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geriye Sen Kalırsın', 'geriye-sen-kalirsin-orhan-baran-moam0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ağrılardan sızılardan

Ard arda geçilen kapılardan

Bir sevdayı büyüten yağmurlardan

Taşla döşeli yollardan

Geceden, denizden ve aydan

Geriye 

Sen kalırsın

Ağlayan şarkılardan

Güneşin öptüğü sabahlardan

Yosun tutmuş sulardan

Hiç kalkılmayacak rüyalardan

Geceyi köpürten arzulardan

Sesten, nefesten ve yazdan

Geriye

Sen kalırsın', 'Ağrılardan sızılardan Ard arda geçilen kapılardan Bir sevdayı büyüten yağmurlardan Taşla döşeli yollardan Geceden, denizden ve aydan Geriye ...', ARRAY['Türk Edebiyatı','Şiir','Orhan Baran']::text[], 8.5, '{"poet":"Orhan Baran","poet_slug":"orhan-baran","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/geriye-sen-kalirsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uykuların', 'uykularin-orhan-baran-hemvh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uykuların seherden ağır

Bu rüyalar sabaha çıkarmaz seni

Çocuksu öyküleri taşımaz, düşlerin sağır

Bu uyku ağaçlar doğurmaz

Issız yataklarda kalabalık rüyalar görülmez

Bu uyku sana dayanmaz

Bu yatak dayanmaz

Uzun uykulardan kalkarsın

Yetişkin rüyalar içinden

Rüyaların toprak kokar

Yaz yağmurlarıyla yıkanmış gibi

Eğer bir gün rüya görmezsen

Gül goncası değildir artık yatağın

ve bulutlar da rüyalarından çıkmış demektir', 'Uykuların seherden ağır Bu rüyalar sabaha çıkarmaz seni Çocuksu öyküleri taşımaz, düşlerin sağır Bu uyku ağaçlar doğurmaz Issız yataklarda k...', ARRAY['Türk Edebiyatı','Şiir','Orhan Baran']::text[], 8.5, '{"poet":"Orhan Baran","poet_slug":"orhan-baran","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/uykularin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SevgiHüzün', 'sevgihuzun-sule-aydemir-fw76c', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yine gece yarısı

yine şeker karası 

sevgihüzün

uzaktasın ya

her ezan vakti ürperir içim

bir dalım daha sanki

kuruyacakmış gibi

ölüm ya 

sevdiğim de anmam adını

ne zor içindekilerin

becerememek tarifini

güneş görmemiş ya

sararan mutlu memnun

ortak

anılar mıyız

olmuş olacağımız

rahatsızlığımız

oturduğumuz yerden mi

duruş şeklimizden mi

senden mi

benden mi

güldürmedi

yürümedi gitti', 'yine gece yarısı yine şeker karası  sevgihüzün uzaktasın ya her ezan vakti ürperir içim bir dalım daha sanki kuruyacakmış gibi ölüm ya  sevd...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sevgihuzun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dinmişse Bütün Rüzgarlar', 'dinmisse-butun-ruzgarlar-melih-coskun-4yx2d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dinmişse tüm rüzgarlar 

Ve tükenmişse önünde tüm denizler

Vaktidir okyanuslara açılmanın 

Biten her umudu 

Yuvarlayıp yüksek uçurumlardan 

Başı dik 

Direne direne  

Yürümek yeni hayatlara 

Kaybedilmiş mutluluklara üzülürken 

Pişmanlığını duymamak için 

Uçup giden hayatın 

Gitmek çözüm değil

Beynini de beraberinde götürebilmek bütün mesele

Bu yara her şehirde sızlar 

Nerede olursan ol sızar damarlarından kan 

Belki kırılacaksın kuru bir dal gibi 

(Oysa kendin kaçmıştın bütün yağmurlardan kuruyana dek)

Başladığını sandığın anda tükenecek umut

Ayrılık hain bir bıçak gibi saplanacak sırtına 

Hiç ummadığın bir zamanda, 

Yalnız kalacaksın

Belki bekleyeceksin haftalar, aylar boyunca 

Beş dakika dökebilmek için içindekileri

Kendinden vazgeçercesine

Kimse seni anlayamayacak olsa bile

Aldanacaksın belki de 

Düşüneceksin 

Hayatın sana hak ettiğini vermeyeceğini hiçbir zaman 

Kırılan her hayal 

İnsan olduğunu hatırlatmalı sana her seferinde 

Hatırlatmalı

Üzüntüler olmazsa 

Hiçbir işe yaramayacağını mutluluğun 

Güçlü olmak 

Asırlık bir çınar gibi dimdik görünmek değildi düşmanına 

Güçlü olmak yüreğin kan ağlasa da 

Aynaya bakıp tüm içtenliğinle gülebilmekti 

Kendi kendine

Anlatmaya gerek olmadan 

Kendinden başka 

Hiç kimseye ve hiçbir şeye

Ve ağlamak 

Zor iş dedik yıllarca 

Kuytu bir köşe aradık hep 

Kimsenin uğramadığı bir yer 

Anlayamadık 

Tükenmek için değil bu gözyaşları

Tüketmek için bu tükenmişliğini 

Boşaltmak için bu iğrenç zehri damarlarından... 

Bu tükeniş varolmak için yeniden...

21 Mart 2003

21: 17', 'Dinmişse tüm rüzgarlar  Ve tükenmişse önünde tüm denizler Vaktidir okyanuslara açılmanın  Biten her umudu  Yuvarlayıp yüksek uçurumlardan  B...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/dinmisse-butun-ruzgarlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'affetmeyeceğim', 'affetmeyecegim-i-kbal-senturk-j6z2l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'pırıl, pırıl, 

gülen 

gözlerim vardı benim

kötülerden habersiz, yüzüm

umutla baktığım yarınlarım

birer, birer terketiler beni

şimdi anlıyorum

duru bir su gibi olanları

geçte olsa....

seni affetmeyeceğim

sarhoş masalarında

duyduğum hakaretleri sana

yoluyorum....

hiç benim olmadı onlar

birazı senin, coğu onlarındı

sen benim en degerli

hazinemi çaldın..

iyi olmaktan vazgeçtim ben

yaşadığım sürece hakımı

helal etmeyeceğim....

burda, yada orda 

nasıl istersen

ama ödemelesin

düşlerimin, 

kayıp giden yıllarımın

hesabını.....', 'pırıl, pırıl,  gülen  gözlerim vardı benim kötülerden habersiz, yüzüm umutla baktığım yarınlarım birer, birer terketiler beni şimdi anlıyoru...', ARRAY['Türk Edebiyatı','Şiir','İkbal Şentürk']::text[], 8.5, '{"poet":"İkbal Şentürk","poet_slug":"i-kbal-senturk","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/affetmeyecegim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Varya Sen', 'sen-varya-sen-ali-konuk-5zuae', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nazlı bebeğim sen var ya sen 

Benim için gökyüzündeki  güneşimsin 

Isınmak için sevgine muhtaç olduğumsun

Varlığınla var yüreğim özümsün tek sözümsün

Başımı çevirip sana bakamadığımsın

Parlaklığınla gözlerimi yakanımsın

Uzağımsın güneş gibi  yakınımsın sıcaklığımsın

Var olanımsın olduranımsın  yaşatanımsın



Sevgilim sen var ya sen..

Sahra çöllerinde ulaşmak için çırpındığım vahamsın

Dudaklarımın tek arzususun  mataramdaki susun

Kana, kana içmek için  pınarlarından yandığımsın

Gölgelerinde Ruhumu serinletmek için can attığımsın 

Senden sana kaçmak için içimde sana sığınanımsın



Bi tanem sen var ya sen

Sisli ve kasvetli okyanuslarımda ki kutup yıldızımsın 

Sana çevirmişim gözlerimi yolumu bulmak için

Karanlıklardan sıyrılmak için  baktığımsın

Dünya gemisinde sığınacak limanımsın 

Fırtınalardan kaçmak için ihtiyacım olanımsın 

Yüküm bir avuç nefes heybem ise yumak

Karşında yapabileceğim tek şey sevgimi sunmak



Can kuşum, şans meleğim sen var ya sen

Damarlarımda ılık, ılık akan kansın, 

Bu sebeple de zaten   her hücremde varsın

Dönüp dolaşanda her karışını vücudumu

Korkmam hiç ulaşacağın kalbimde atarsın



Gonca gülüm, dilberim sen var ya sen

Biliyor musun benim için nesin...

Sevgilimsin aşkımsın, bi tanemsin..

Nefes alışımsın, yanaklarımdan süzülen göz yaşımsın

Gözlerimdeki gülüş, rüyamdaki tatlı düşsün

Yiyecek yemeğimsin tabağımdaki aşımsın, 

Elimdeki  kalemimsin,  beynimdeki  resmimsin

İfade gücümsün, hızımsın,  haykırışımsın, 

Hırsımsın, tutkumsun, saplantılarımsın

Vaz geçemediğimsin, koşmak istediğimsin

Karşı koyamadığımsın, engel olamadığımsın

Aşkımı sunduğumsun sevgini umduğumsun

Ayaklarını kapanıp af dilediğimsin

Söylediğim şarkı sözlerimsin ismini her gece mırıldandığım

İlham kaynağımsın şiir yazdığımsın

Dokunmak istediğim ama dokunamadığımsın

Tutmak istediğimsin ama tutamadığımsın

Ulaşmak istediğimsin ama ulaşamadığımsın

Hep aradığımsın hep umduğumsun  geçte olsa bulduğumsun

Aynadaki aksimsin, görmek istediğimsin

Tatlı dilimsin, güzel bakışımsın, yüreğimdeki  sevgimsin

Sen benim için bensin...

Hep benim içimde var olan ise bir tek sensin...', 'Nazlı bebeğim sen var ya sen  Benim için gökyüzündeki  güneşimsin  Isınmak için sevgine muhtaç olduğumsun Varlığınla var yüreğim özümsün tek...', ARRAY['Türk Edebiyatı','Şiir','Ali Konuk']::text[], 8.5, '{"poet":"Ali Konuk","poet_slug":"ali-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/sen-varya-sen-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Görmeden Çok Özledim', 'seni-gormeden-cok-ozledim-ali-konuk-7yd1a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bebeğim seni görmeden çok özledim.....

Yüzündeki gülümsemeyi  çok özledim....

Tatlı tatlı  süzüşlerini çok özledim....

Bana bakışlarını var ya görmeden çok özledim.....

Hele görmediğim seni görmeyi  daha çok özledim....



Minik kuşum seni duymadan çok özledim.....

Kadife sesini dinlemeyi çok özledim.....

Şen kahkahanı işitmeyi çok özledim.....

Göğsüne yatıp kalbinin atışlarını duymayı çok özledim.....

Nefes alışlarını, bana kızışlarını bile çok özledim.....



Nar tanem sana dokunmayı çok özledim......

Sevemediğim saçlarını okşamayı çok özledim.....

Tutmadığım pamuk ellerini tutmayı çok özledim.....

Bedenindeki her kıvrımı, her santimi çok özledim.....

Öpmediğim dudaklarını öpmeyi çok çok özledim......



Sevgilim seni koklamayı çok özledim......

Sana henüz sarılmadan, sarılmayı çok özledim....

Gözlerinin içinde eriyip gitmeyi çok özledim.....

Kokunu ciğerlerime çekmeyi çok özledim....

Seni çok sevdiğim halde, daha çok sevmeyi çok özledim.....



Çiçeğim senin her şeyini  özledim......

Bilmiyorum bilmeden neden bu kadar çok özledim.....

Bildiğim tek şey seni çok özlediğim.....

Vücudumun her karesi her hücresi haykırıyor bana......

Çok özledim çok özledim çok özledim......', 'Bebeğim seni görmeden çok özledim..... Yüzündeki gülümsemeyi  çok özledim.... Tatlı tatlı  süzüşlerini çok özledim.... Bana bakışlarını var ...', ARRAY['Türk Edebiyatı','Şiir','Ali Konuk']::text[], 8.5, '{"poet":"Ali Konuk","poet_slug":"ali-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/seni-gormeden-cok-ozledim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İNSAN VE KARMAŞA (Düz Yazı)', 'i-nsan-ve-karmasa-duz-yazi-naime-erlacin-zz8ev', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Duygu ve düşünceler her zaman durgun bir nehirde seyretmiyor ne yazık ki. Karmaşa bizim içimizde, dışımızda, her yerde... Kimi zaman öyle bir kepçelenip  karıştırılıyoruz ki, kendimizi tanımakta güçlük çekiyoruz adeta. Zekâmız durumu kavramaya çalışırken, akıl isyan ediyor. Sezgiler yanılıyor, düşünce rotasından çıkıyor. Bilinçdışı bilinci istilâ ederken iplerin elimizden kurtulduğunu görüyor ve durumu yalnızca izlemekle kalıyoruz.

Sadece ukalâlar her etkeni denetim altında tuttuklarını iddia ederler. Mutlak denetim diye bir şey yoktur. Olsaydı eğer, hayat monotonlaşmaz mıydı? En azından pek çok ararengini yitirirdi. Karmaşaya yatkın olmak da bir tür meziyettir çünkü yaratıcılığın kaynağıdır o; aynı zamanda doğurganlığın ta kendisi ve sanatın süt annesi. Çözüm karmaşadan fayda çıkarmayı bilmekte yatar.

Son zamanlarda bir modadır gidiyor.''Ben seni seviyorum. Sen önce kendini, sonra dünyayı sev. Elini sevgiye uzat, sana uzanan eli tut'' falan feşmekan! Böyle şey olur mu hiç? Ben neden dört yaşındaki çocuğa tecavüz edip öldüren; kurban keseceğim diye bir canlının ayaklarını vahşice doğrayan adamı sevmek zorunda olayım ki? Öncelikle aklım, sonra da değerlerim isyan eder böylesi bir saçmalığa. Alın size binlerce karmaşa nedeninden bir tanesi. 

Kafam karışıyor ve huzursuz oluyorsam eğer, ilkel bir tepki gösterir ve isyan ederim; sözgelimi  kabalaşır, mesela adam dövmeye kalkışırım. Veya sorunu çözümleme yolları ararım. Bunları yapmamayı seçmişsem eğer, koyun gibi boynumu eğer, katlanır ve o zaman da karmaşadan uzak durmuş olurum. Bu son durumda yarar nedir peki? Kocaman bir ''sıfır'' sadece. Öteki seçeneklerin hiç değilse ''eksi'' ve ''artı''ları vardı.

Ne yapmalıyım o halde? 

Ne ''kötü çocuk'', ne ''uyumlu çocuk'', ne de ''tepkisiz çocuk'' uymadı bana diyorsanız eğer, huzursuzluğun kaynağı olan negatif enerjiyi olumluya çevirmeye ne dersiniz? Çatlatın tohumunuzu ve şarkınızı söylemeye başlayın derhal. Şiir mi yazıyorsunuz; resim mi yapıyor veya fotoğraf mı çekmekten hoşlanıyorsunuz; bir yerlere protesto yazıları mı gönderiyorsunuz, elinizden ne geliyorsa onu yapmaya koyulun hemen. Her çözüm yolunun toplumsal sorunlara yararı yoktur elbet ama sizin uğradığınız zararı asgariye indirir. Üretmek en iyi ilaçtır bazı durumlarda.Ve belki bir gün ürettiklerinizin güzelliği bilincinize bilinç katar ve başkalarına da yararlı olmayı öğrenirsiniz. Böylece gönül gözünüz ve gönül kapılarınız açılır, ufkunuz genişler. At gözlüklerinden kurtulmuş olursunuz sonuçta…

Karmaşayı hafifseme, küçümseme, görmezden gelme ve alaycı bir tavır takınma ise sizi dar koridorlara hapsedip bırakır sadece. O noktada manevra alanınızın küçüklüğü, sıkışmışlığınız görünmez olur artık gözünüze. Kaçışların en kolayıdır bu... Kaçanlar genellikle başkalarını aşağılamaktan kendilerini eleştirmeye vakit bulamazlar. Onlar en güçsüzlerdir daima. Kocaman bir evde uyku tulumunda büzülüp uyuyanlardır kaçanlar…

Sözlerim bir tür öğreti veya nasihat değil kuşkusuz. Ben kendi deneyimlerimi anlatıyordum sizlere. “Siz” derken “ben” demek istiyordum aslında. 

İnsan yanarak pişiyor dostlar. Musibetle yani…

Sevin karmaşayı ne olur.

Biraz ateşten zarar gelmez! 

(15 Mayıs 2003)   - ''Gençler İçin Denemeler'' dosyasından...', 'Duygu ve düşünceler her zaman durgun bir nehirde seyretmiyor ne yazık ki. Karmaşa bizim içimizde, dışımızda, her yerde... Kimi zaman öyle bi...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/insan-ve-karmasa-duz-yazi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serbest', 'serbest-i-rfan-cebeci-127vt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gelin bi bakın, ne olmuş...

Kim gibi bakmış, kim gibi yazmış

Meğer yazarken ölmüş, yazarken gülmüş.

Kim miymiş, bilmem kimmmiş

falancalardan...

Esmezsen yapraklar sararır

Güller dökülür, hicrana

Hasta canım, şifa ister 

Ruhumda şiir gibi...

Bir değil bin ok delse ruhumu 

Değse bana ecelin soğuk eli 

Rüzgar kadar hızlı gelirmisin 

Bitirmeden sensiz geceyi... 

Bu gece sonsuza uzanıp dalmak var derin uykulara

Kalbine dokunmadan sevmek var

Kırıp dökmek var heceleri, 

Öpüp kaçmak var geceleri, 

Hülyalı saatlerden yine gel demeden uyanmak var.

Rüyadan bakmak var dünyaya..Yaşamak var ya..

Belki rüyada yaşamak var.. 

Uyanınca uyumak..

Sonra hatırlamak var..

Rüyada...', 'Gelin bi bakın, ne olmuş... Kim gibi bakmış, kim gibi yazmış Meğer yazarken ölmüş, yazarken gülmüş. Kim miymiş, bilmem kimmmiş falancalardan...', ARRAY['Türk Edebiyatı','Şiir','İrfan Cebeci']::text[], 8.5, '{"poet":"İrfan Cebeci","poet_slug":"i-rfan-cebeci","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/serbest-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Bana Kırlangıçları Anlat...', 'bana-kirlangiclari-anlat-naime-erlacin-l3lp7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'anlat küçüğüm 

bana 

acıları anlat

çocukları anlat bana

sürünün kanatlarını

birer sırça köşk idiler

yenik düştüler zamana

en çok uçmayı istediler 

savaşta ölüp 

bir gecede büyüdüler 

bana çocukları anlat 

kadını anlat bana

kadın acayip bilmece

ebemkuşağı astı göklere 

bağrında göveren güle küstü 

hak aradı çıkmazlarda kendince 

istersen erkeği anlat

kulak ver yüreğindeki sese 

bana insanı anlat

aşkı anlat bana 

alacadan en karasına 

soluklaşmasını renklerin

nasıl da küs kalmıştın odalara

sokaklar yangın yerine dönmüştü hani

kalleşliği anlat bana

en iyi sen bilirsin vurulmayı

bana hayatı anlat 

“yüzyıllık evin avlusunda 

kuru dallarda 

dünya biriktiren asma”yı *anlat 

güneşe aldanan bademleri

nasıl bir şeydir 

kalbindeki menevişleri okşarken

kırlangıç kanadında özgürlük yakalamak

bana uçmayı anlat! 

(*)      Engin Kahraman

(Gün gelecek ve yüksekten uçan bir kartala dönüşeceksin! ... Mutlu yıllar Sevgili Engin...15 Mayıs 2003)', 'anlat küçüğüm  bana  acıları anlat çocukları anlat bana sürünün kanatlarını birer sırça köşk idiler yenik düştüler zamana en çok uçmayı iste...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/bana-kirlangiclari-anlat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıllar Geçti', 'yillar-gecti-halit-i-nce-ayqed', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yıllar geçti, sormadan

Hiç resmine bakmadan

Yıllar geçti, durmadan

Hiç sesini duymadan

Yıllar geçti, sormadan

Sen beni hiç sormadan

Yıllar geçti, durmadan

Ben seni hiç unutmadan

Gel gör şimdi sen beni

Tıpkı ayrıldığımız günde gibi

Sadece yıllar geçmiş 

Ben farkında olmadan...

Seni öyle sevdim ki! 

Kimse öyle sevilmedi...

Hiç resmine bakmadan

Hiç sesini duymadan

Sen beni hiç sormadan

Ben seni hiç unutmadan

Seni öyle sevdim ki! 

Kimse öyle sevilmedi...

Yıllar geçmiş sormadan

Yıllar geçmiş durmadan...', 'Yıllar geçti, sormadan Hiç resmine bakmadan Yıllar geçti, durmadan Hiç sesini duymadan Yıllar geçti, sormadan Sen beni hiç sormadan Yıllar g...', ARRAY['Türk Edebiyatı','Şiir','Halit İnce']::text[], 8.5, '{"poet":"Halit İnce","poet_slug":"halit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yillar-gecti-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir C(an) lık Yaşam', 'bir-c-an-lik-yasam-ali-ceyhan-9lwcc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kaygısına düştün, didindin durmadan

Büyüttükçe gözünde büyüsüne kapıldın

Kamçıladın ihtiraslarını tamahkar

Son''u göremedin, düştün boşluğuna yaşamın

Her gün neden doğar güneş

Sonra sırtını döner geceye kaybolur

Avuçlarında miladı dolmuş kelimeler

Mutluluk nutkunda yamalı gamzelerin

Ve kaç bahar sonrasına ısmarladığın 

İlikleri kurumuş beklentilerin

Kök salmalar derinliklerine dünyanın

Kaç binlercesi kabusla döndü o düşten

Ey bir c(an)  lık yaşam 

Nedir bu telaşın, bu boş endişen

Uykularından çalıp kurduğun dünyan

Koskoca yalan, aç gözlerini uyan

Eşikten girmek için sabırsızdır sonbahar', 'Kaygısına düştün, didindin durmadan Büyüttükçe gözünde büyüsüne kapıldın Kamçıladın ihtiraslarını tamahkar Son''u göremedin, düştün boşluğuna...', ARRAY['Türk Edebiyatı','Şiir','Ali Ceyhan']::text[], 8.5, '{"poet":"Ali Ceyhan","poet_slug":"ali-ceyhan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-c-an-lik-yasam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırakın', 'birakin-serdar-akcer-6muys', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bırakın iskarpinler dans etsinler özgürce

Deryalarda yüzsün mürekkep balıkları

Süzülsün martılar buz gibi mavilikte

Dokunmayın insanlar sevsinler delice

Susun bozulmasın büyüsü gecenin

Bakireler beklesin kaçak ihanetleri

Unutulsun yaşanan hüzünlü akşamlar

Yılmayın umutları ellerinden alınmış çocuklar

Karanlıklar aydınlansın gizemlerin içinde

Çalıntı yaşamlarda suskunluk izleri

Kaybolsun unutanlar zamanın yelinde', 'Bırakın iskarpinler dans etsinler özgürce Deryalarda yüzsün mürekkep balıkları Süzülsün martılar buz gibi mavilikte Dokunmayın insanlar sevs...', ARRAY['Türk Edebiyatı','Şiir','Serdar Akçer']::text[], 8.5, '{"poet":"Serdar Akçer","poet_slug":"serdar-akcer","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/birakin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Piç Dünya', 'pic-dunya-serdar-akcer-qxxpr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gökyüzünde ay

Yanımda bir dolu yalnızlık

Aldatılmış duygular gibi

Piç bu dünyaya inat

Susuyorum.

Dağların kızıl güneşini çaldım

Olympos’tan 

Zeusu kızdırırcasına...', 'Gökyüzünde ay Yanımda bir dolu yalnızlık Aldatılmış duygular gibi Piç bu dünyaya inat Susuyorum. Dağların kızıl güneşini çaldım Olympos’tan ...', ARRAY['Türk Edebiyatı','Şiir','Serdar Akçer']::text[], 8.5, '{"poet":"Serdar Akçer","poet_slug":"serdar-akcer","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/pic-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceler', 'geceler-serdar-akcer-dv2zp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ah geceler 

Buhranlıdır gözleri canavarların

Ah geceler

Canlandırır hatıralarımı

Geçmek bilmezler 

Bir dost sözüyle zamana giderler

Dostlar gider

Geceler ah geceler

Yine gelirler

Ruhumu alırlar

Acılarını bırakırlar

Ağlamaklı gözlere

İmzalar atarlar 

Geceler ah geceler

Buhranlıdır gözleri canavarların.', 'Ah geceler  Buhranlıdır gözleri canavarların Ah geceler Canlandırır hatıralarımı Geçmek bilmezler  Bir dost sözüyle zamana giderler Dostlar ...', ARRAY['Türk Edebiyatı','Şiir','Serdar Akçer']::text[], 8.5, '{"poet":"Serdar Akçer","poet_slug":"serdar-akcer","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/geceler-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Direniş', 'bir-direnis-serdar-akcer-wifgh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Duman kokusu sinmiş üzerime

Toprak kokan elleriyle siler

Alnın terini, tozlu yüzler

Kimseler bilmez, ne biçim bir yalnızlıktır

Her yanını kavuran cehennem ateşi

Tanrıyı kızdırmışçasına çekilen acı 

Sevmelerde yitirilen kimin hayatı

Salya sümük yüzümden gider

Bir direniştir bu, bir aşktır

İtler dalaşır tenhalarda

Bıçaklı travestiler mekanı

Otoban kenarları, yaltaklanırcasına bir adamın

Acizliği, sevmelerden dışarı

Bir geceliktir aşıkların masalı

Kaybeden tarafta ben 

Kazananı yok bu hikayenin

Gönüllü diye yazılır sevilmeyen işlere

Adlar kazınır kimlikleri belirsiz çocuklara

Sofistike olmayan ustanın hüznü

Yeni yetmelerin alaysı tavırlarına karışır

Ve çekip gitmiştir sevgilinin hatıraları...', 'Duman kokusu sinmiş üzerime Toprak kokan elleriyle siler Alnın terini, tozlu yüzler Kimseler bilmez, ne biçim bir yalnızlıktır Her yanını ka...', ARRAY['Türk Edebiyatı','Şiir','Serdar Akçer']::text[], 8.5, '{"poet":"Serdar Akçer","poet_slug":"serdar-akcer","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bir-direnis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Simit Çıtırtısı', 'simit-citirtisi-serdar-akcer-latd3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir simit çıtırtısında

Bir çay yudumunda 

Yaşadığım hayatım

Çağlayanların coştuğu

Çıyanlar ve yılanlar

Bir resim var

Gözümden gitmeyen

Anıları ısmarladım yine bu gece

Kapımdan geçen eskiciye

Sobamda odunların sesi

Çisil, çisil yağan yağmurum

Yaprakların karanlıktaki dansı

Çevresini zor aydınlatan sokak lambası

Altında titreyen sokak kedisi

Kaderime yorduğum hatalarım

Geldiler yine bu gece

Rüzgarı süpürür zamanın

Mumun aynadaki aksi

Çalmayan kapımın zili

Gündüzü olmayan bu gecede

Ben ağlayamam...', 'Bir simit çıtırtısında Bir çay yudumunda  Yaşadığım hayatım Çağlayanların coştuğu Çıyanlar ve yılanlar Bir resim var Gözümden gitmeyen Anıla...', ARRAY['Türk Edebiyatı','Şiir','Serdar Akçer']::text[], 8.5, '{"poet":"Serdar Akçer","poet_slug":"serdar-akcer","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/simit-citirtisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yankılanır', 'yankilanir-serdar-akcer-mkec9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yankılanır odalarda hıçkırıklar

Dertli söyleniyor bu gece şarkılar

Kadehlerde buzlu rakılar, kaç kadeh parçaladım

Duvarlarla tokuşturdum kadehleri yalnızlığımın şerefine

Senin şerefine...

Kan emici yarasalar dolaşıyorlar yine

Etrafım sorun yuvası

Yanlış nerede, nesi bozuk bu denklemin

Yeşili soluk gecenin

İçimden dilime düşen kelimeler

Bir hüzünlü gülümseme

Seviştim adını bilmediğim kadınlarla

Hep sen diye, sen olmadan

Oysa yine ben 

Yalansızdım yalanlar arasında', 'Yankılanır odalarda hıçkırıklar Dertli söyleniyor bu gece şarkılar Kadehlerde buzlu rakılar, kaç kadeh parçaladım Duvarlarla tokuşturdum kad...', ARRAY['Türk Edebiyatı','Şiir','Serdar Akçer']::text[], 8.5, '{"poet":"Serdar Akçer","poet_slug":"serdar-akcer","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yankilanir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garip Değil Ölüyorum', 'garip-degil-oluyorum-sule-aydemir-nbo3v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '-506'' ya 

bir şeyler ölüyor orada

uzakta

belki bir ormanda 

yeni günün doğuş

vakti

etten parçalar 

çentiklenir gibi 

rüzgarın ormandan

okşadıkları gibi

hissediyorum

bir şeyler ölüyor orada

uzakta

belki bir ormanda 

yeni günün doğuş

vakti

ölüyor ya hani

yavrusuna göçmen kuşun 

götüremeden kursağındakileri

yoldayken kırılması kanadının

kanadında yüreğin acıması hani

acıtıyor

biliyorum

bir şeyler ölüyor orada

uzakta

''ölüyorum''', '-506'' ya  bir şeyler ölüyor orada uzakta belki bir ormanda  yeni günün doğuş vakti etten parçalar  çentiklenir gibi  rüzgarın ormandan okşad...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/garip-degil-oluyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eflatun Med-Cezir', 'eflatun-med-cezir-sule-aydemir-tac4p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'O’ na

sevgim eflatundu benim

ne değişik ne hoştu

görmemişti

güneşi ama 

tutmamıştı küf

ne değişik ne hoştu

med-cezirleri çoktu

ya boğulurdum

ya kururdum kara kuru

eflatunda 

ne değişik ne hoştu

gözleri eflatundu

elleri eflatun

kokulu yüreği öyle

öyle ki sevgisi bile

eflatun da 

ne değişik ne hoştu

beyaz değil miydi oysa 

eflatun sahi

med-cezir ya hani

‘kimdi sahi’', 'O’ na sevgim eflatundu benim ne değişik ne hoştu görmemişti güneşi ama  tutmamıştı küf ne değişik ne hoştu med-cezirleri çoktu ya boğulurdum...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/eflatun-med-cezir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kedersiz Ölümler', 'kedersiz-olumler-mustafa-konuk-5qggg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'kedersiz ölümler kadar renksiz

kaldığı zaman bulutlar havada

takma adınla bekle umutları

içinde bir kayboluşun naraları...

saklambaç kareler yalnız başına

yıkılmış toprak üstünde evler

bir kere üstünkörü yaşam

sonu varmı unutluşun..', 'kedersiz ölümler kadar renksiz kaldığı zaman bulutlar havada takma adınla bekle umutları içinde bir kayboluşun naraları... saklambaç kareler...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Konuk']::text[], 8.5, '{"poet":"Mustafa Konuk","poet_slug":"mustafa-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kedersiz-olumler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çay Aşkı*', 'cay-aski-bayram-tunca-n6g50', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Rengi benzer kanıma

İçince karışır kanıma

Kokusu benzer hanıma

Dokusu benzer canıma

İki şekeri eritir, bir metal kaşık

Şekerler birbirlerine küllün âşık

Aşıklar olmuşlar sanki sarmaşık

Yalnız duyguları biraz karmaşık

Çay dediğin, buğu buğu tütmeli

İnsan, çay bardağını zor tutmalı

Çay da kahve misali iz bırakmalı

İkram eden, gözümüze bakmalı

Çay albenili ve göze hoş gelmeli

İçenin, içini ısıtmalı sevgili misali

Bellekte unutulmaz tat bırakmalı

Dokusu kokusuyla içimizi ısıtmalı

Şekeri ikram ettiği sıcak çay eritti

Sıcak kanlılığıyla kendini sevdirtti

Ateşli bakışıyla içimin yağını eritti

Aşk ateşiyle beni Kerem’e çevirtti

O yârin çook çayını içtim şekersiz

O gözlerini şeker yaptım habersiz

Aşktan çay şeker misali eridik biz

Kimine göre de sanki deliydik biz

15.05.2003-12.45', 'Rengi benzer kanıma İçince karışır kanıma Kokusu benzer hanıma Dokusu benzer canıma İki şekeri eritir, bir metal kaşık Şekerler birbirlerine...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/cay-aski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne gelir ki göze?', 'ne-gelir-ki-goze-yasin-ramazan-e30t3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dünya dönse dolaşsa

Düşse önüme, 

Hiç aldırmam billahi

Ne gelir ki göze? 

Boşuna arama

Çare yoktur ölüme

Benim canım feda

Birtanecik gülüme...', 'Dünya dönse dolaşsa Düşse önüme,  Hiç aldırmam billahi Ne gelir ki göze?  Boşuna arama Çare yoktur ölüme Benim canım feda Birtanecik gülüme....', ARRAY['Türk Edebiyatı','Şiir','Yasin Ramazan']::text[], 8.5, '{"poet":"Yasin Ramazan","poet_slug":"yasin-ramazan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ne-gelir-ki-goze-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Aşkına', 'sevda-askina-sule-aydemir-q7f8i', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'nasıl bir duygu bu

karanlığı parçalıyor ki

güneşin alnın da 

gece uyuyor koynumda

sürünürken uçuyorum

uçarken de yokum

sevda aşkına

-nedir bu', 'nasıl bir duygu bu karanlığı parçalıyor ki güneşin alnın da  gece uyuyor koynumda sürünürken uçuyorum uçarken de yokum sevda aşkına -nedir b...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevda-askina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akliman Zamanları 1', 'akliman-zamanlari-1-zeki-ergin-i6as2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '___aklimanlılara sevgilerimle

egenin kıyıcığında

ağacımın altındayım

buraya her oturuşumda

ciğerlerime dolan

onlarca çiçek

toprak

ve de deniz kokusu

alır beni 88lere götürür

katırtıknakları illa da

ben ilk kez burada gördüm 

kanarya

bülbül

ve de yalıçapkını

ve de bilemediklerimi

her şey tamam burda

şarap 

müzik

deniz

bir eksik var

içimdeki yalnızlık

_babakale may03

_sevgiliye isyan yt:haz04', '___aklimanlılara sevgilerimle egenin kıyıcığında ağacımın altındayım buraya her oturuşumda ciğerlerime dolan onlarca çiçek toprak ve de deni...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/akliman-zamanlari-1-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıcak Serzeniş', 'sicak-serzenis-kivanc-ergen-kra89', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yokluğun, varolmaz duyumsamalara gebe 

Ve sen sıcaklığın en kor saflığında 

Yitip gidiyorsun.. 

İmgeler diyarına bensiz, belki sensiz... 

Kavuş buralara, varol burada 

Hiçbir zaman gitmeyecekmiş gibi 

                           Derince,15-05-2003', 'Yokluğun, varolmaz duyumsamalara gebe  Ve sen sıcaklığın en kor saflığında  Yitip gidiyorsun..  İmgeler diyarına bensiz, belki sensiz...  Ka...', ARRAY['Türk Edebiyatı','Şiir','Kıvanç Ergen']::text[], 8.5, '{"poet":"Kıvanç Ergen","poet_slug":"kivanc-ergen","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sicak-serzenis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Bir Çocuğum Başkalarının Bisikletlerine Muhtaç', 'ben-bir-cocugum-baskalarinin-bisikletlerine-muhtac-can-duman-x0uwk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '25-11-2000 

Farklı dillerde yazılır yazılar 

Ve farklı tellerde çalınır 

evrende müzik 

Sızlatınca içimi o eski sancılar 

Ben bir çocuğum 

başkalarının bisikletlerine 

muhtaç olacak kadar 

Saatler mi geç oldu 

biz mi geciktik yoksa 

Bir bir üstümüze kapandı o kara kapılar 

Geride hüzün geride onca beyhudeliği ile 

kaybolan yıllar 

Ben bir çocuğum başkalarının bisikletlerine 

muhtaç olacak kadar 

Ara ara esti kavak yelleri başımızdan 

Bazen ucuz bazen pahalı atlatıldı 

vartalar 

Onca sevgililer onca Arzular 

Ben bir çocuğum 

başkalarının bisikletlerine 

muhtaç olacak kadar 

Haritaya baktım da 

uzaklaştıkça derinleşiyor sular 

Karadan açığa sürükler gibi bizi 

geçen zamanlar 

Ben üzgünüm ben yetim gibi 

bir başıma kaldım 

Ve bir de hatıralar var 

Ben öylesine mahrum bir çocuk 

başkalarının bisikletlerine 

muhtaç olacak kadar 

Acınırdı bazen bakarak 

ehveni şer halime 

Ben de hayıflanırdım bu duruma 

Öylecesine 

Nerede geçti zaman ve var mı 

kayda değer anılar 

Hele yaşanmadıysa 

bisiklet üstündeki güzelim yıllar 

Mutlu olduğum günleri saysam 

Elimin parmakları kadar 

Bilemezsin başkalarının bisikletleri 

bir çocuğu, ne kadar da yaralar 

Bir çocuktum ben kırılgan 

Kolayca yaralanacak kadar 

Bir şey yakar çocuğu 

ezer içini birden 

Ve buruklaşır kalınca bir başına 

yalnızken 

Herhalde o zaman hatırlanır 

Çocukluk, ilk gençlik ve 

bisiklet bazen 

Ve sanırım o zamandır 

kendine yetememe 

-hatta o zamandır ilk sitem yazıları 

ilk şiir ilk hikaye- 

Bir çocuk düşün 

ne kadar bedbahttır 

Başkalarının bisiklet hayali içinde 

Ne zaman yarılır yer 

ne zaman yıkılır gök 

Korkarım, gelse de 

kurtarıcı vasfıyla ölüm 

Ben yaşadım bunca zaman 

çaresiz sevgiye aç 

Ben bir çocuktum 

başkalarının bisikletlerine muhtaç', '25-11-2000  Farklı dillerde yazılır yazılar  Ve farklı tellerde çalınır  evrende müzik  Sızlatınca içimi o eski sancılar  Ben bir çocuğum  b...', ARRAY['Türk Edebiyatı','Şiir','Can Duman']::text[], 8.5, '{"poet":"Can Duman","poet_slug":"can-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":68,"source_url":"https://www.antoloji.com/ben-bir-cocugum-baskalarinin-bisikletlerine-muhtac-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O bir kadındı...', 'o-bir-kadindi-hazan-mandirali-drp8d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'O bir kadındı

Milyonlarca kadından biri

Yorgun, ezilmiş, çilekeş

Onun hakkı yoktu sevmeye

Değer verilmeye

Bilmiyordu bunlar kaderimiydi

Düşündü, insan kendi kaderini çizemez miydi? 

Denedi, başkaldırdıHer seferinde tokmaklar indi başına

Yüreğinede bir şeyler kanadı

Kararı kesindi artık

Bu Onun kaderiydi

Obir kadındı...', 'O bir kadındı Milyonlarca kadından biri Yorgun, ezilmiş, çilekeş Onun hakkı yoktu sevmeye Değer verilmeye Bilmiyordu bunlar kaderimiydi Düşü...', ARRAY['Türk Edebiyatı','Şiir','Hazan Mandıralı']::text[], 8.5, '{"poet":"Hazan Mandıralı","poet_slug":"hazan-mandirali","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/o-bir-kadindi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül*', 'gul-bayram-tunca-p0bua', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güller içinde gördüm bir gül

Yüzünde vardı, güzel bir nur

Göz imasıyla dedi, biraz dur

Durdum ama yaptı beni kül

Yaylalarda su akıyor gürül gürül

Davullar çalıyor gümbür gümbür

O gözleri, sanki de elmas kömür

Onun aşkından oldum, sanki kül

Güller içinde, gözüme ilişti bir gül

Yüzünde vardı, dolunay misali nur

O yıldızlı gözleriyle dedi, azcık dur

Durdum ama aşkından oldum kül

Takdim ettim kalp ambalajlı bir gül

Aşk ateşiyle yaptı bu şairi sanki kül

Oldum onun kafesinde öten bülbül

Aah gözleri zümrüt, saçları sümbül

15.05.2003-15.05', 'Güller içinde gördüm bir gül Yüzünde vardı, güzel bir nur Göz imasıyla dedi, biraz dur Durdum ama yaptı beni kül Yaylalarda su akıyor gürül ...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gul-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O ve Sen', 'o-ve-sen-turhan-yilmaz-xq4ld', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Onun hayalleri tozpembe, 

Seninkiler sütbeyazı.

Hele birde gördümmü ayazı, 

Umut olur rahmet olur yaparsın, 

İnan bana inan bana tam yirmidört ayarsın.

Onun saçları şampanya sarısı, 

Senikiler zeytin karası

Çare yok bu bir gönül yarası.

En acı tütünler merhemdir yarama.

Sakın ola sakın ola ilaç hekim arama.

O süslü masaların nazlı orkidesi, 

Sen bembeyaz dağların kardelen çiçeğisin.

Hiç düşünmeden rehin bıraktığım gençliğimin, 

Bana hayat veren tek gerçeğisin.

Umudun, hasretin, vuslatın taaa kendisisin.', 'Onun hayalleri tozpembe,  Seninkiler sütbeyazı. Hele birde gördümmü ayazı,  Umut olur rahmet olur yaparsın,  İnan bana inan bana tam yirmidö...', ARRAY['Türk Edebiyatı','Şiir','Turhan Yılmaz']::text[], 8.5, '{"poet":"Turhan Yılmaz","poet_slug":"turhan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/o-ve-sen-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Kim Attı', 'beni-kim-atti-huseyin-cayikli-jzxhw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bugun isteyerek ayrilmadim isimden

beni atmakla ozgurdurler

vicdan hurriyetiyle atildim...

mecmuada yazilan bir yazim

yasasin devrim diye yazmistim oysa anne

sosyalist oldugum icin beni yargiladilar...

ne mutlu ki dusunuyorum diye yazdim once 

buyuk insanligi

nazimi sigdiramadim daha yazilara...

beni vicdan hurruyetiyle attilar...

sonra sirasiyla yasadigim evin suyunu elektrigini 

ve sonra evin icinden de attilar beni...

Marksist oldugum icin sanirim yasamimdan da edecekler 

umut bende anne

gurbet birazda isyan 

oysa ben nazim gibi TKP yi 

icime yazdim...', 'bugun isteyerek ayrilmadim isimden beni atmakla ozgurdurler vicdan hurriyetiyle atildim... mecmuada yazilan bir yazim yasasin devrim diye ya...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/beni-kim-atti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yirmi Bir Yaş', 'yirmi-bir-yas-mustafa-ozturk-ckvi0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bedenim dünyanın üzerinde dolaşır, 

Lakin beni arama dünyanın dışındayım, 

Ateşlere ben attım viran olmuş gönlümü, 

Yandı kül oldu gönül ömrümün kışındayım, 

Kaçmak için ateşten düştüm uzun yollara, 

Sonunu bilmediğim yolların başındayım, 

Bahtsız bir ırmak gibi parçalandım kollara, 

Bitti tükendi ömrüm yirmi bir yaşındayım, 

Hicranınla kavruldum su görmemiş çöllerde, 

Suya hasret toprak gibi vuslatın düşündeyim, 

Eğer beni merak eder yerimi sorar isen, 

Ruhumu bulmak için kendini yorar isen, 

Sana şunu söylerim ki, bir mezar taşındayım, 

Sonunu bilmediğim bir yolun başındayım, 

Bitti tükendi ömrüm yirmibir yaşındayım...', 'Bedenim dünyanın üzerinde dolaşır,  Lakin beni arama dünyanın dışındayım,  Ateşlere ben attım viran olmuş gönlümü,  Yandı kül oldu gönül ömr...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Öztürk']::text[], 8.5, '{"poet":"Mustafa Öztürk","poet_slug":"mustafa-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yirmi-bir-yas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalanı Yok', 'yalani-yok-celal-hikmet-wyj91', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yalan yok

deliler gibi sevdim seni varlığın beyaz ateşinde

karanlıkta çırpınan mum ışığı gibi titriyordu yüreğim

yalan yok

hala seviyorum seni

bitmek tükenmek bilmiyor göğsümü çatlatan acının sancısı

ağlama diyorum gözlerime

gidenler dönmeyecekler diyorum

dinletemiyorum

yalan yok

beynimi titretiyor yokluğunda dinlediğim her şarkı

karanfil dalından süzülen her yağmur damlası

geceleyin uluyan köpek seslerine karışıp

kanatıyor alnımın bıçak yarasını

yalan yok

ürperiyor rüyalarımdan kalkan güvecinler adın her anıldığında

dağlardan kurşun sesleri geliyor

vuruluyor sevdam gökyüzünün koynunda

yalan yok

ey deli sevdamın huysuz kısrağı

ey kabaran yangınımın sönmez koru

ey yokluğunda binlerce kez öldüğüm

yık gel artık yokluğun zındanlarını

kopar al beni yüreğimin etinden

hasretin sancısı yedi bitirdi beni

yalan yok

deliler gibi özledim seni

ateşler yaktım yokluğunda

küllerini savurdum gözlerinle yaktığın her yerde

güneşler topladım

   türküler söyledim

       halaylar çektim

yalan yok

sen yokken de sevdim seni gülüm

varlığında anlamlanan yalanlar söyledim kendime

sen varmışsın gibi avuttum kendimi

dişlerinden kan damlıyordu kuduz kalbimin

yalan yok

yokluğunda acıdan yedim bitirdim gözbebeklerimi

savaştım gecenin karanlığında gölgelerle

aldattım sensizliğin çıldırtan karanlığını

yalan yok

karanlıkta da kovaladım gölgeni

aldırmadım arkamdan bağıranlara

aldırmadım gökyüzünün dökülmesine ilmek ilmek

ve söndürülmesine dağlarda yankılanan türkülerin

yalan yok

ey geceler boyu hasretiyle seviştiğim

ey kırılan kalemimin idamı

ey gül yanakları hicran kokan sevdiğim

gel atrık kül olan bağrımın virane çölüne

gel de gör sevdanın eserini

ey ak elleri kına kokan

ey perçemine yangın çökmüş

ey mavi gözlerine güneş düşmüş sevdiğim

kurtar beni hasretin koynundan

yalan yok

ne kadar kaçsam da ellerinden

ne kadar inkâ etsem de kalbimden akan kanı

ölesiye yaşattım sevdanı', 'yalan yok deliler gibi sevdim seni varlığın beyaz ateşinde karanlıkta çırpınan mum ışığı gibi titriyordu yüreğim yalan yok hala seviyorum se...', ARRAY['Türk Edebiyatı','Şiir','Celal Hikmet']::text[], 8.5, '{"poet":"Celal Hikmet","poet_slug":"celal-hikmet","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/yalani-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Aşk Yaşanmalı', 'bu-ask-yasanmali-ahmet-i-nce-io2vn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Üzülme sevdiceğim

Aldırma olan bitene 

Gitme gel 

Ben de gitmeyeceğim

Gözlerinin renginde öleceğim…

Yaşanacaksa bu aşk yaşanmalı

Korkular olmamalı engel

Yollar set çekemez bedene

Engelleri itiver…

İşte bak

Alev alev yanıyor karanfiller

Düşmana inat

Sevginin yoluna yat…

Sarılmalı

Öpüşmeli

Sevişmeli

Hadi gel

Mutsuzluk, ağlarını örmesin

Bırak, inceldiği yerden  kopsun...

27.02.2002', 'Üzülme sevdiceğim Aldırma olan bitene  Gitme gel  Ben de gitmeyeceğim Gözlerinin renginde öleceğim… Yaşanacaksa bu aşk yaşanmalı Korkular ol...', ARRAY['Türk Edebiyatı','Şiir','Ahmet İnce']::text[], 8.5, '{"poet":"Ahmet İnce","poet_slug":"ahmet-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bu-ask-yasanmali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte Bak', 'i-ste-bak-ahmet-i-nce-gh3gy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Üzülme sevdiceğim

Aldırma olan bitene 

Gitme gel 

Ben de gitmeyeceğim

Gözlerinin renginde öleceğim…

Yaşanacaksa bu aşk yaşanmalı

Korkular olmamalı engel

Yollar set çekemez bedene

Engelleri itiver…

İşte bak

Alev alev yanıyor karanfiller

Düşmana inat

Sevginin yoluna yat…

