INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost Özlemi', 'dost-ozlemi-muhsin-bukucu-u2m39', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dost özlemi yakarken yüreğimi

Ben bilemem yaşadığımı, bilemem neş''eyi

Tatsızdır hayat, yalandır gülüşler

Yalandır bahtıma doğan güneşler

Bir dost;  bağlasa beni

İnsanların göremediği zincirlerle

Çekse kendine, ellerim kelepçeli

Gitsem karlı dağların ötesine

Gitsem mutluluk ülkesine

Varsam kucaklasam özlemle

Sonsuz bir arzuyla erisem dostta

Eriyebilsem her sarılışta! 

Dost özlemi yakarken yüreğimi

Ben bilemem yaşadığımı, bilemem neş''eyi', 'Dost özlemi yakarken yüreğimi Ben bilemem yaşadığımı, bilemem neş''eyi Tatsızdır hayat, yalandır gülüşler Yalandır bahtıma doğan güneşler Bir...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Bükücü']::text[], 8.5, '{"poet":"Muhsin Bükücü","poet_slug":"muhsin-bukucu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/dost-ozlemi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost Merhabası', 'dost-merhabasi-muhsin-bukucu-1tz2a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne doyumsuz bir aşk dır beklediğim

Ne de  bir gül bahçesi özler yüreğim

Eksilmesin  benden hiç, “dost’tan merhaba”

Muhtaçtır; içten bir gülümsemeye gözlerim', 'Ne doyumsuz bir aşk dır beklediğim Ne de  bir gül bahçesi özler yüreğim Eksilmesin  benden hiç, “dost’tan merhaba” Muhtaçtır; içten bir gülü...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Bükücü']::text[], 8.5, '{"poet":"Muhsin Bükücü","poet_slug":"muhsin-bukucu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dost-merhabasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda', 'elveda-muhsin-bukucu-azvik', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bulutlar karardı, gökyüzü delindi sanki

Camları yumrukluyor yağmur taneleri

Ben ise yeni bir yalnızlığa mahkum

Hem de bir dostun vedasının ertesi

Güz bahçemde pembe güller açmıştı, zamansız

Bir dost çıkmıştı karşıma özlemle beklediğim, çıkarsız

Cama vuran her damla anlatsın istiyorum

Yaşadığım duyguları, çıkmaz sokağımı, yalansız

Fırlayıp çıkıp da sokaklara, çılgınca

Sokaklardan büyük yalnızlığıma

Bağırmak, haykırmak istiyorum

Gözyaşı akıtmak istiyorum doyasıya

Bu fırtına dinecekti elbet, elbet bitecekti rüya

Elbet dönecekti herkes, kendi gerçek dünyasına

Ama ben; yağmur taneleri ile yarışmak istiyorum

Bakalım içimdeki deniz mi büyük, yüz trilyon damla mı yoksa? 

Hoş geldin tutsaklık, güzel duygular elveda...

Hoş geldin karanlık, kahve gözler elveda...

Ne olur hiç durmasın, delicesine yağsın istiyorum

Hoş geldin yalnızlık, güzel dost elveda...', 'Bulutlar karardı, gökyüzü delindi sanki Camları yumrukluyor yağmur taneleri Ben ise yeni bir yalnızlığa mahkum Hem de bir dostun vedasının e...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Bükücü']::text[], 8.5, '{"poet":"Muhsin Bükücü","poet_slug":"muhsin-bukucu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/elveda-49-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşlerin Gölgesinde', 'duslerin-golgesinde-muhsin-bukucu-ohcav', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir yudum mutluluktu, tek ümidimiz, 

Hiç içilmemiş dünya zehiri tattık! .

Gerçekler zulüm dolu, gerçekler acımasız, 

Yaşamak, düşlerin gölgesinde artık! 

Bir gurbet, bir hasret şarkısı dolaşır dudaklarımızda, 

Gözyaşları, bir sevinç gibi süzülür yanaklarımızda.

Bak; can verdi, yakaladığımız mutluluk kollarımızda

Yaşamak düşlerin gölgesinde artık!', 'Bir yudum mutluluktu, tek ümidimiz,  Hiç içilmemiş dünya zehiri tattık! . Gerçekler zulüm dolu, gerçekler acımasız,  Yaşamak, düşlerin gölge...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Bükücü']::text[], 8.5, '{"poet":"Muhsin Bükücü","poet_slug":"muhsin-bukucu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/duslerin-golgesinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecelerin Güzelliği', 'gecelerin-guzelligi-muhsin-bukucu-7gk7j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevmezdim hiç geceleri...

Karanlıktı

Yalnızlıktı

Sessizdi

Gizemliydi

Ve... bitmezdi hiç

Sanırdım; 

Güneş hiç doğmayacak

Süzülmeyecek ışık

Pencerelerden içeri

Bu yüzden

Sevmezdim hiç geceleri...

Geceleri; 

Bir dost sevdirdi bana

Artık zaman dilimleri; 

Ondan önce

Ondan sonra, 

Ve...

Onunla...

Anlamayı

Anlaşılmayı

Ne kadar özlemişim meğer! 

Kalabalıklar arasındaki

Yalnızlıkları

Kahkahalar arasındaki

Hüzünleri, acıları...

Anlayabilmek

Anlatabilmek

Paylaşabilmek

Ne güzelmiş meğer

O'' nun geldiği saatlerde

Bir güneş sarıyor pencereleri

Yüreğimdeki yalnızlık

Korkup siniyor bir köşede.

O''nun çıkmasını bekliyor, 

Tekrar yerleşebilmek için yüreğime

Yüreğimde açan güller

Zamansız olsa bile

Ben gülü seviyorum 

Zamanı değil! 

Bana gülümseyen  gözler

Zamansız olsa bile

Ben gözleri seviyorum

Zamanı değil! 

Ve...

Artık

Çok seviyorum geceleri', 'Sevmezdim hiç geceleri... Karanlıktı Yalnızlıktı Sessizdi Gizemliydi Ve... bitmezdi hiç Sanırdım;  Güneş hiç doğmayacak Süzülmeyecek ışık Pe...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Bükücü']::text[], 8.5, '{"poet":"Muhsin Bükücü","poet_slug":"muhsin-bukucu","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/gecelerin-guzelligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar Örtüsü', 'kar-ortusu-muhsin-bukucu-dkqfe', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Penceremin önünde, düşünüyorum...

Yeni doğmuş bir bebeğin saflığında

Bembeyaz bir örtü toprakta

Sanki; 

Kötü duygular can çekişiyor kar altında

Korkuyorum... 

Yine güneş doğmakta

İşte ben; o zaman çok üşüyorum.', 'Penceremin önünde, düşünüyorum... Yeni doğmuş bir bebeğin saflığında Bembeyaz bir örtü toprakta Sanki;  Kötü duygular can çekişiyor kar altı...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Bükücü']::text[], 8.5, '{"poet":"Muhsin Bükücü","poet_slug":"muhsin-bukucu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kar-ortusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hamal', 'hamal-muhsin-bukucu-hpszx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayat oldukça yorsa gerek

Taşıyamıyor yükleri  artık Hamal 

Dağları taşırdı denizlerin ötesine

Denizleri taşırdı dağların ötesine

Yine de...

Yüksünmezdi hiç eskiden

Umutları vardı, 

Dizlerine can veren

Kışları taşırken baharlara.

Alnındaki terleri, 

Katık yapardı ekmeğine

Sevda nedir bilmezdi

Şefkat nedir bilmezdi

“Lan” ile bütünleşti kulakları

Yine de...

Umursamazdı hiç eskiden

Hayat oldukça yorsa gerek

Taşıyamıyor yükleri  artık hamal

Çileli yolun sonu görünse gerek

Gözlerde hayat ışıltısı yok artık

Dizler titrek, nasırlı eller titrek

Yürekte yaşama arzusu yok artık

Zor gelir oldu

Yok sayılmak

Zor gelir oldu

Hiç sayılmak

Anlayamadan

Anlatamadan

Anlaşılamadan

Gelse gerek yolun sonu

Hayat oldukça yorsa gerek

Taşıyamıyor yükleri  artık Hamal

Bir gün ıssız bir köşede

Azrail gelecek yorgun bedene

Karanlığı tırmalayacak elleri

Binecek ruhu sonsuzluk gemisine

Sırtında yüklenmiş dağı geçerken dost Hamal

Görecek cansız bedendeki geleceğini

Gözü yaşlı vuracak sırtındaki küfeye

Çilekeş Hamal''ın cansız bedenini

Ne adını hatırlayan çıkacak

Ne buruşuk çehresini

Ne de... donuk gözlerini...', 'Hayat oldukça yorsa gerek Taşıyamıyor yükleri  artık Hamal  Dağları taşırdı denizlerin ötesine Denizleri taşırdı dağların ötesine Yine de......', ARRAY['Türk Edebiyatı','Şiir','Muhsin Bükücü']::text[], 8.5, '{"poet":"Muhsin Bükücü","poet_slug":"muhsin-bukucu","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/hamal-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babam', 'babam-cemil-neseliler-9zym1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ellerinden boğazıma giden lokmaydı ilk tanıştığım

Yutarken, çocuk ruhuma işleyendi sevgi dolu bakışın

Hadi ye oğlum derken çarpan yüreğindi beni besleyen

Doydun mu Cemilim diyen sesindi beni büyüten Babam

Kısa pantolonumu, beli lastikli donumu sendin diken

Her düşüşümde yırtılan pantolonumu sendin yamayan

Onlarca paralansa da şefkatle sırtımı sıvazlayan

Gönlü yüce, ufku engin, düşüncesi hür, zengin Babam

Neşeyi, huzuru, mutluluğu, tevekkülü öğreten

Zorda, hastalıkta, musibette sabrı telkin eden

On lirayı, milyarlara değişmeyeceğini söyleyen

Rızkını iğneden iplikten helalinden çıkaran Babam

Gece ikide dönerken yorgundu bedenin

Huşu ile yatıyordu yatağa coşkun yüreğin

Of üf duymadım bir kerecik dilinden

Şikayet nedir bilmedin, öğretmedin Babam

Sohbetinle daima çevrene verdin ışık

Feyizlendi meclise giren her aşık

Derde deva, gönle şifa, ruha gıda oldun, 

Düşünüp de konuşan, konuşunca anlaşılan Sevgili Babam

Hastalıkta derdin hep, kusurlara kefaret

Yetmişbeş yıl düşmanın oldu cehalet

İlmi irfanı rehber ettin yolun selamet

Kabeyi tavaf değil, gönüllerde tavaf edenlere, 

Derdin hep kopar mı kıyamet

Vuslat trenine ayak basmıştı tenin

Hadi oğlum git çocukların bekliyor derken dilin

İki ocak gece yarısıydı Sevgiline kavuştuğun

Melekler alkış tutuyordu kutlu olsun yolculuğun

Güvercin gibi uçuyordu arşı alaya ruhun

Yaşıyorsun yaşayacaksın ey ulu şahsiyet

Hiçlik, ölüm yok, sana yakışır ebediyet

Bağışladığın emanet sönmeyecek, kopmayacak kıyamet

Kabrin nur, mekanın cennet olsun Sevgili Babam', 'Ellerinden boğazıma giden lokmaydı ilk tanıştığım Yutarken, çocuk ruhuma işleyendi sevgi dolu bakışın Hadi ye oğlum derken çarpan yüreğindi ...', ARRAY['Türk Edebiyatı','Şiir','Cemil Neşeliler']::text[], 8.5, '{"poet":"Cemil Neşeliler","poet_slug":"cemil-neseliler","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/babam-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yitiğim', 'yitigim-cemil-neseliler-hswya', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yitiğimi arar dururum avarece garip

Nefesi ulaştığında meltem esintisiyle

Sahile yaklaştığımı hissedip  ürperince

Ilıktan sıcağa daralma kaplanır içim sessizce

Günün aydınlığında sürükleniyorum perişan

Yıllar biçim verdi, takmadım hiçbir şan

Yol verir biliyorum menzilime nur efşan

Benliğimde varlığın, gönlümde sevgin  büyük nişan', 'Yitiğimi arar dururum avarece garip Nefesi ulaştığında meltem esintisiyle Sahile yaklaştığımı hissedip  ürperince Ilıktan sıcağa daralma kap...', ARRAY['Türk Edebiyatı','Şiir','Cemil Neşeliler']::text[], 8.5, '{"poet":"Cemil Neşeliler","poet_slug":"cemil-neseliler","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yitigim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güvercin', 'guvercin-cemil-neseliler-oyhgg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Penceremde içli  bir ses

Guguk guguk! 

Geceden pişirmiş  hevesleri

Dudakları kapalı, feryadda ufuklara

Kanatları  sarınmış

Tenine cepkenine

Nefeslendi derin

Söyleyeceği çok uyananlara: 

Ezelden uçuyorum  durak bilmeden

Odam yok, yuvam gökyüzü

Divanlar beğenmedim, döşeğim bulut

Yıkanırım sabah akşam, suyum yağmur

Sağarım günü ıslak mı ıslak

Gözümde toprak, ümidim berrak

İsteğim kalender; 

Ömürlük değil, bugünlük olsun', 'Penceremde içli  bir ses Guguk guguk!  Geceden pişirmiş  hevesleri Dudakları kapalı, feryadda ufuklara Kanatları  sarınmış Tenine cepkenine ...', ARRAY['Türk Edebiyatı','Şiir','Cemil Neşeliler']::text[], 8.5, '{"poet":"Cemil Neşeliler","poet_slug":"cemil-neseliler","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/guvercin-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayna', 'ayna-cemil-neseliler-y2kgc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Açılmış nilüfersin durgun sularda, 

Kırlarda nefes alan gelincik.

Diyarı gözlüyorum karanlık gecelerde

Özlemlerim, yıldızlı semada

Kah dalga oluyorum deryada, 

Kah yakamoz...

Kah samanyolunda pırlanta, 

Kah yeryüzünde papatya

Seviyorum sevmeyi sevilmeyi, 

Yaşamın baharında.

Filizlerim yemiş verse de, 

Arzuluyorum çocukluğu

Denizlere bakmayı, 

Martıları seyretmeyi, 

Fenerleri yakmayı

Dumanları üflemeyi

Zarif hüzün, kibar hasret

Ayrılık buğulu kelime

Yoldaşım ümit hep kendime

Candaşım, sırdaşım, arkadaşım

Soruyorum kendime, 

Buluyorum kendimce cevabı; 

Yürekler ak

Yürekler saf

Yürekler sevgi

Yürekler ayna', 'Açılmış nilüfersin durgun sularda,  Kırlarda nefes alan gelincik. Diyarı gözlüyorum karanlık gecelerde Özlemlerim, yıldızlı semada Kah dalga...', ARRAY['Türk Edebiyatı','Şiir','Cemil Neşeliler']::text[], 8.5, '{"poet":"Cemil Neşeliler","poet_slug":"cemil-neseliler","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ayna-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dalgalarla Dans', 'dalgalarla-dans-cemil-neseliler-jct5p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ufuktaki kızıllık umudum

Ardındaki güneş hevesim

Başımda kavak yelleri rüzgarım

Sinem püryan, gözüm canan

Mısralar feryadıyla yüreğime mızrab

İnlemezse figanıyla verir ızdırab

Güneş aleviyle sevgime mihrab

Yan ey gönül yan ey afitab

Dalgalara binmiş çalıyor gitarımın telleri

Güzel bir günü müjdeliyor kulağımın zilleri

Karşımda coşmuş esiyor kavak yelleri

Gönlüm şakıyor dinmiyor dilleri

Konfetiler oldu bana can

Aşksız neyleyim dünyada hakan

İsteyene olsun cihan meydan

Işığın olmazsa devran zindan', 'Ufuktaki kızıllık umudum Ardındaki güneş hevesim Başımda kavak yelleri rüzgarım Sinem püryan, gözüm canan Mısralar feryadıyla yüreğime mızra...', ARRAY['Türk Edebiyatı','Şiir','Cemil Neşeliler']::text[], 8.5, '{"poet":"Cemil Neşeliler","poet_slug":"cemil-neseliler","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dalgalarla-dans-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-cemil-neseliler-vifa5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Soluk olup bir nefeste soluyorum seni

Su olup bir yudumda içiyorum seni

Şarap olup bir kadehte çekiyorum seni

Sevda olup bir sarışta kaplıyorum seni

Yıldız olup saçlarını süslüyorum seni

Ateş olup bir kıvılcımda yakıyorum seni

Güneş olup bir pırıltıda ısıtıyorum seni

Sarmaşık olup bir filizde doluyorum seni

Salıncak olup kollarımla uçuruyorum seni

Papatya olup doyasıya kokluyorum seni

Şarkı olup  bir ömür  dinliyorum seni

Aşk olup nice aldanmacalarla sarıyorum seni...', 'Soluk olup bir nefeste soluyorum seni Su olup bir yudumda içiyorum seni Şarap olup bir kadehte çekiyorum seni Sevda olup bir sarışta kaplıyo...', ARRAY['Türk Edebiyatı','Şiir','Cemil Neşeliler']::text[], 8.5, '{"poet":"Cemil Neşeliler","poet_slug":"cemil-neseliler","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ozlem-103-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakamoz', 'yakamoz-cemil-neseliler-cyyc0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sözün esrarı mavide dansda

Gönül erleri yanan iştiyakda

Konuşan elmassa, ayinede pırlanta

Ruhlar hazda, coşkuysa hülyada

Yakamozdaki pırıltı güneşten mi acaba? 

Yüreğimdeki aşkı akıttım deryaya

Dalgaların yüzü döndü hicaba

Yıldızımın ışığı bu, umman geldi bahara...', 'Sözün esrarı mavide dansda Gönül erleri yanan iştiyakda Konuşan elmassa, ayinede pırlanta Ruhlar hazda, coşkuysa hülyada Yakamozdaki pırıltı...', ARRAY['Türk Edebiyatı','Şiir','Cemil Neşeliler']::text[], 8.5, '{"poet":"Cemil Neşeliler","poet_slug":"cemil-neseliler","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yakamoz-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eksiz', 'eksiz-cemil-neseliler-ipayf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yaşanan sevinçlerin nihayetinde

Gün çoğalıyor dinmeden

Yokların bitişiğinde, varların güzelliğinde, 

Sevinme zamanıydı,  arefesinde gecenin.

Rüzgar deli esintiyse, 

Akşam  yakalama ânı.

Gece, eklendi sonrasında sabahıma, 

Sabah, yaslandı günüme

Gün  devam ediyor hayatımla

Eki belirsiz...', 'Yaşanan sevinçlerin nihayetinde Gün çoğalıyor dinmeden Yokların bitişiğinde, varların güzelliğinde,  Sevinme zamanıydı,  arefesinde gecenin....', ARRAY['Türk Edebiyatı','Şiir','Cemil Neşeliler']::text[], 8.5, '{"poet":"Cemil Neşeliler","poet_slug":"cemil-neseliler","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/eksiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolculuk', 'yolculuk-cemil-neseliler-bljdu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Vakitler öğle olduğunda özlenir bir başka sevdiğim

Sıyrılmada gündelikten sıradanlıktan yüreğim

Halatla tutunmuşca bağlanır direğe yelkenim

Seferlere hazırdır essin olabildiğince hırçın yelim 

Uğradıkca her bir limana fasılalarla 

Nice şuh kızlar dolaşır çalkalamalarla

Kırmızı rujlar pembe allar yakar delikanlıları

Girmez gönlüme bakışları keskin okları

Tanrım ne büyük bir yolculuktur bu hiç bitmesin

Zamanı mekanı yok eden bu sevgi hiç dinmesin

Zihinler berrak, yürekler ayna, ateşimiz sönmesin

Kollarım nefes gibi girgin kenetlenmiş hiç çözülmesin', 'Vakitler öğle olduğunda özlenir bir başka sevdiğim Sıyrılmada gündelikten sıradanlıktan yüreğim Halatla tutunmuşca bağlanır direğe yelkenim ...', ARRAY['Türk Edebiyatı','Şiir','Cemil Neşeliler']::text[], 8.5, '{"poet":"Cemil Neşeliler","poet_slug":"cemil-neseliler","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yolculuk-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kinaye(Muzo''dan)', 'kinaye-muzo-dan-yusuf-canturk-3imw2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaşım  yetmiş  ise  de,  doksan  gibiyim.

                Mânevî  yönden,  hayli   noksan   gibiyim.

                Bir  mum  gibi  eriyor,  sağlam  bedenim.

                Giymiş  görür  gibiyim  sanki,  beyaz  kefenim.



                                                      Kadıköy-1996

                Karamsar  ettin  beni   kırk  yıl  boyunca, 

                Terk  etmiş  gibisin   sen,  bana   doyunca 

                Her  ne  kadar  görünsen  de  bana  çok  yakın.

                Bunun   altında   bir   maksat   olmasın  sakın? 



                MUZO’NUN  hissine   acep   oldum  mu  tercüman? 

                Öyle  çekmiş  ki  benden,  ‘ diyor  ki ‘’ el-aman ‘! 

                Nihayet   yetmiş   yaşına  bastığı  zaman, 

                Çıkardı  SULTAN’A  yaraşır,  katî  bir  ferman .', 'Yaşım  yetmiş  ise  de,  doksan  gibiyim.                 Mânevî  yönden,  hayli   noksan   gibiyim.                 Bir  mum  gibi  eriyor,...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Cantürk']::text[], 8.5, '{"poet":"Yusuf Cantürk","poet_slug":"yusuf-canturk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kinaye-muzo-dan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerim Söyler', 'gozlerim-soyler-yusuf-canturk-wbyeq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bazen  güneş  gibi   yakan,  yıldız  gibi  bakansın, 

                Bazen  gözlerinde  yaş,  yanaklara   akansın.

                Çoğu  kez  ceylan  gibi,  avcılardan  kaçansın.

                İstemem,   gönül  verip,  yüreğin  nafile  yansın! 



                Mahzun  etme  beni  büyük  bir  hazdan, 

                Lütfen  vazgeç,    öyle  cilve  ve  nazdan, 

                Kurtar  beni  artık  bu  tutku  ve  marazdan! 

                Vazgeçemem,  mevsimlerin  güzeli, bahar  ve yazdan.



                Aşkımı  terennüm  ediyor   sihirli  neyler, 

                Dilim  çekinse  de  bak,  gözlerim  söyler, 

                Felek  bir  değil,  bin  cefâ  eyler, 

                Benim  gibi  yanmayın  sakın,  hanımlar, beyler 

                                                   Kadıköy-1996', 'Bazen  güneş  gibi   yakan,  yıldız  gibi  bakansın,                  Bazen  gözlerinde  yaş,  yanaklara   akansın.                 Çoğu  ke...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Cantürk']::text[], 8.5, '{"poet":"Yusuf Cantürk","poet_slug":"yusuf-canturk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gozlerim-soyler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ateşin Külleri', 'bir-atesin-kulleri-yusuf-canturk-ge9bp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hem  anlattı,  hem  de  yaşla  doldu  gözleri.

                Acı  ve  keder  vardı,  gerçek  miydi  sözleri? 

                ‘Yılların  birikimi “ dedi,  açıkça  içini  döktü.

                Anlattıkça  ferahladı,  fakat  boynu  büküktü.

              

                Bakışları  hem  aşkımı,  hem  de  derdimi  tazeler.

                Bilmezsin  kâlbimden   neler  geçiyor,  neler! 

                Arzularla  duygularım   ilk  baharı  andırır, 

                Gözlerinden  çıkan   mânâ   yüreğimi  kandırır.



                Bir  sevgiyi  öldürdün,  acımasız,  hunharca, 

                Bu  ateşin  külleri,  sıcak  kalmış  yıllarca, 

                Kâlbimin  ıstırabı  birazcık   dinmiş  eken, 

                Bıraktığın  kokuların   üzerime  sinmiş  iken.



                 Sana  özür  borçluyum,  bir  tek  söz  için.

                Keder  içindeyim  bil  ki,  ağlar  yeşil  göz  için.

                Mevsimler  gelip,  geçse  de  beni  hatırla, 

                Halinden  haber  ver  bari,  bir  kaç  satırla! 



                Aşkınla   nefes  almak  öyle  zevk,  öyle  tat.

                Hayal  olsa  da  kâlbime,  gel  de  merâm  anlat! 

                Yokluğunu  içimde  duyarım,  acı  ile   karışık, 

                Bir  yıldızdın  kayan,  bırakmadan  bir  ışık.', 'Hem  anlattı,  hem  de  yaşla  doldu  gözleri.                 Acı  ve  keder  vardı,  gerçek  miydi  sözleri?                  ‘Yılların  b...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Cantürk']::text[], 8.5, '{"poet":"Yusuf Cantürk","poet_slug":"yusuf-canturk","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bir-atesin-kulleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DÜŞÜNCE TEYBİ (Düz Yazı)', 'dusunce-teybi-duz-yazi-naime-erlacin-qc1zm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Karışan beyin, parazit yapan sistem ve bozulan kimyayı düzeltmenin tek yolu düşünmektir. 

Ama nasıl düşünmek?

Çok becerikli ve “ehil kafa dağıtıcıları” vardır hani; sinemaya, maça, içmeye, dost muhabbetlerine ve bazen de “geyik” üzerine kurulu zaman öldürmecelere  pek meraklıdırlar. Bu konuda ustalaşmışlardır adeta. Onlara bir sözüm yok benim. Ne mutlu hepsine. Benimki biraz farklı. Baştan uyarmalıyım sizi, zira epeyce zor bir zanaattır bu. Önce kafayı kötü düşüncelerden arındıracak, aklayıp paklayacaksın ki azıcık yer açılsın; sonra öfkeni bastıracak ve dış dünya ile hafiften bir mesafe koyacaksın araya. Televizyonun, radyon, kapın hiç susmaz ve e-postaların birbiri ardına ekrana düşerse eğer, giriştiğin düşünme eyleminden de bir hayır gelmez açıkçası. Bu yüzden, benimkisi tenhalara kaçıp inzivaya sığınarak düşünme biçiminde oldu genellikle. Kafamda giderek büyüyen, şişen ve beni sıkıştırıp bunaltan lanet enerji toplarından kurtulmanın bildiğim yegane yoluydu bu. Beynimin her minik kıvrımından fışkırıyor; silahları ile üzerime üzerime gelirken dengemi bozuyor; kasırgaya duçar olmaktan beter ediyorlardı. “O halde düşünmeye devam” dedim…

Düşünmek yazmaktı bir anlamda; yazmak ise boşalmak…Amma ve lakin  bir sorun vardı. Uzayımsı bir boşluğa salınıveren düşüncelerim bu hayali yazım sürecinde o denli süratle akıyorlardı ki, onları bir daha asla yakalayamıyordum. Hızlarına yetişmek, kalem veya tuşlarla mümkün olmuyordu. Düşüncelerimi yitiriyor; düzelip doğrulmak uğruna bir yandan da eksiliyordum. Eksik kalıyordum yani! 

Düşünceyi yakalamak ve kaydetmek  insanoğlunun yaşamında gerçekleşebilecek en önemli evrim aşamasıdır. Görüntümüzü; görünür veya görünmez iken konuştuklarımızı kayıt altına alabiliyoruz. Ama bu yeterli mi? Beyin ve dil aynı hızda çalışmıyor ki. Beyin emir veriyor ve dil onları sıraya diziyor. O halde dili aradan çıkaran“düşünce teypleri” üretmeliyiz hiç vakit kaybetmeden. Hemen şimdi, bu andan başlayarak! 

Düşünce, bilgisayarda çöp kutusuna atılmış dosyaya benzemez. Orada çöpü geri yükleme şansınız (''Geri'' de ne demekse? ''Yeniden yükleme'' deseler kulağa daha hoş gelmez miydi sanki?)  daima vardır. Oysa belgelenmeyen düşünce, sonsuza kadar süren uzun bir yolculuğa çıkmış demektir. Sonsuz kavramı da irdelenmeli biraz. Sonsuz ortak bir mal olmayıp herkesin sonsuzu kendinedir. “Dar sonsuzlular”dan “engin sonsuzlular”a dek uzanan öznel ve geniş bir ıskaladan söz ediyorum burada. Ne denli “var” ve ne kadar “cogito ergo sum”* cu iseniz sonsuzunuz da o ölçüde büyük olur. Oysa matematikte ''sonsuz'' neredeyse tek ve mutlak bir kavramdır. Yaşamın her ögesinde harcı bulunan ve tutkuyla sevdalandığım bu bilim dalına yani matematiğe; matematikçi ve ayrıca felsefecilere, işlerine karışarak saygısızlık mı etmiş oluyorum acaba? Umarım öyle değildir… Ne yapalım ki, herkesin kavram anlayış ve tarifi de sonuçta kendine. Bazı konularda öznelleşmekten kurtulmanın yolu yok galiba…

Bugün yine ne çok düşünce yitirdim kendi sonsuzuma. Klavyenin tuşlarına bakıyorum. Onlar bana bakıyor. Düşük hızlarından dolayı adeta özür diliyorlar benden. Kaçanları yakalayamıyor ve burada oturmuş yalnızca durum tespiti yapıyorum. Ne yazık… 

Hey düşünce teypi, neredeysen çık gel artık! 

......................

                                                   

*”Cogito ergo sum”: ”Düşünüyorum, o halde varım”- Descartes

(17 Mayıs 2003)  - ''Gençler İçin Denemeler'' dosyasından...', 'Karışan beyin, parazit yapan sistem ve bozulan kimyayı düzeltmenin tek yolu düşünmektir.  Ama nasıl düşünmek? Çok becerikli ve “ehil kafa da...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/dusunce-teybi-duz-yazi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karamsar', 'karamsar-caglar-akarsu-53vxr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yılgınlıklarımı, savurdum bu gece, 

Alsınlar götürsünler uzak ülkelere, 

Gözlerim kör hiçbir şeyi göremiyorum, 

Orta yerde kalmış bir meczup gibi geziniyorum, 

Çevrem deki h er şey bir an da siliniyor, 

Silahlardan çıkan kurşunlar, anlamsız, 

Gecelerde dolaşan maskeli hırsızlar, 

Kapıma dayan mış, yüreğimi çalıyor, 

Demirden kepenkler, sonuna kadar açılıyor, 

..

Elleri boğazımda sıkıyor, hunharca  sıkıyor, 

Nefesiz kalmışım, kapkara önümü göremiyorum, 

Kare masalarda  iskambil kağıtlarını dağıtıyorlar, 

Asları savurmuşlar  köşelere dört tane, bin oluyor, 

Hep kaybetmişim kazanmayı, hiç bilmiyorum.

...

Önümdeki tüm kapılara kilit vurdum, 

Kimseyi görmek  ve duymak istemiyorum.

Yarınlarda ki umutlarımda insanları sildim.

Dönsem geriye, bağırsam, sesim çıkmıyor, 

Rüzgarlar almışlar, götürmüşler her telini, 

Yaşamı kapıdaki hurdacıya satmışlar, 

Bu şehirlerde haramiler geceleri dolanıyor, 

Renkli lambalar altındaki kadınlar fingirdemiş, 

Cinsellik arenasında boğaları koşturuyorlar, 

Kırmızı şarapların,     kirlerini hiç silemiyorum.

Karanlıktan kaçarken, ayaklarım tökezlemiş, 

Kaybolmuşum, hiç kendimi bulamıyorum.

........

17/mayıs/2003', 'Yılgınlıklarımı, savurdum bu gece,  Alsınlar götürsünler uzak ülkelere,  Gözlerim kör hiçbir şeyi göremiyorum,  Orta yerde kalmış bir meczup...', ARRAY['Türk Edebiyatı','Şiir','Cağlar Akarsu']::text[], 8.5, '{"poet":"Cağlar Akarsu","poet_slug":"caglar-akarsu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/karamsar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut', 'umut-askin-gungor-rk2i0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uyumak istiyorum gökyüzünün enginliklerinde; 

Bulutlar yatağım, yıldızlar yorganım olsun.

Mutlu bir ürperti hissedeyim kalbimin derinliklerinde; 

Kulaklarım yıldızların sevinç çığlığıyla dolsun.

Uyumak istiyorum kainatın derinliklerinde; 

Gezegenler uykum, esrarlı Halley rüyam olsun.

Görsün insanlar beni aşağılardan; 

Sönük bir yıldız sansınlar, ne çıkar, olsun.

Hep arzuluyorum, bir çocuğun sevinç çığlığında, 

Bir annenin umutla gülen yüzünde rüyalara dalmayı.

Mutluluğun sevinç gözyaşına dönüştüğü gecede

Bakarak gülen yıldızlara mutlu insan olmayı.

(1986)', 'Uyumak istiyorum gökyüzünün enginliklerinde;  Bulutlar yatağım, yıldızlar yorganım olsun. Mutlu bir ürperti hissedeyim kalbimin derinlikleri...', ARRAY['Türk Edebiyatı','Şiir','Aşkın Güngör']::text[], 8.5, '{"poet":"Aşkın Güngör","poet_slug":"askin-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/umut-67-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-deniz-gizem-8og93', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Zaman* çok yakınken ölümün kara kollarına, 

Beyaz elbisesine bürünür kadın.

Yüzyıllar öncesinde bıraktığı ruhuna kavuştuğu gün, 

Yüzyıllara sığmaz yaşamı boyunca, 

Bugüne sakladığı tacını takarlar zamanın kutsal başına

Pırlantadan zarif, beyazlar içinde, ölümün kara kollarında yatan kadın, 

Son kez derince nefes alır.

Bir el uzanmış da tutmasını bekliyormuş gibi uzatır kadın elini.

Dokunabilmiş miydi uzanan ele, 

Bu yüzyıla da armağan ettiği bedeninden ayrılırken...

*Zaman: Aragon''un kadını', 'Zaman* çok yakınken ölümün kara kollarına,  Beyaz elbisesine bürünür kadın. Yüzyıllar öncesinde bıraktığı ruhuna kavuştuğu gün,  Yüzyıllara ...', ARRAY['Türk Edebiyatı','Şiir','Deniz Gizem']::text[], 8.5, '{"poet":"Deniz Gizem","poet_slug":"deniz-gizem","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/zaman-68-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırmızı Dalgalarımın İçine Aldım Seni Sevgilim,', 'kirmizi-dalgalarimin-i-cine-aldim-seni-sevgilim-deniz-gizem-onyd0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kırmızı dalgalarımın içine aldım seni sevgilim, 

her yer kırmızı, her boşluk..

boşluğun rengi olmaz, ama bizimki kırmızı..

hissetmek için dokunmak gerekmez, 

Uzaklardayken, 

bakmadan gör beni, 

kulağında kırmızı şarkılar olsun, 

hissetmek için duy, 

dinlemek için değil...

sevgi sözcükleri ile değil, kırmızı cümlelerle seslen bana;         

şarap ya da kan gibi...

döküldükçe fazlası istenen...

kırmızı boşluğumuza kilitlediğim aşkımıza içelim sevgilim

döndüğümüzde kalıntılarına muhtaçlığımız ile hissedeceğimiz aşkımıza...', 'Kırmızı dalgalarımın içine aldım seni sevgilim,  her yer kırmızı, her boşluk.. boşluğun rengi olmaz, ama bizimki kırmızı.. hissetmek için do...', ARRAY['Türk Edebiyatı','Şiir','Deniz Gizem']::text[], 8.5, '{"poet":"Deniz Gizem","poet_slug":"deniz-gizem","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kirmizi-dalgalarimin-icine-aldim-seni-sevgilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Davet', 'davet-selim-eysioglu-vy9tv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kimselerin sözü artık,  derman olamaz bana

Seni nasıl sevdiğimi, artık bir anlasana

Bakmaya kıyamazken, yüzüne hasret kaldım

Bir çay içimi olsun, yanıma uğrasana

Hadi gel güzelim, ölüm gelmeden bana

Ya da bir selam gönder, can feda selamına

Yolunda ölsem derken, yolunu bilmez oldum

Madem gelmiyorsun yar, beni bir çağırsana', 'Kimselerin sözü artık,  derman olamaz bana Seni nasıl sevdiğimi, artık bir anlasana Bakmaya kıyamazken, yüzüne hasret kaldım Bir çay içimi o...', ARRAY['Türk Edebiyatı','Şiir','Selim Eyşioğlu']::text[], 8.5, '{"poet":"Selim Eyşioğlu","poet_slug":"selim-eysioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/davet-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Aşk', 'i-ki-ask-selim-eysioglu-6665m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '''Bir gönülde iki aşk yaşamaz'' derler,

Ama benim gönlümü gelip de bir görseler; 

Benim gönlüm iki aşkı yoğurur durur

Hem sana, hem ülkeme, yüreğim yanar durur

……..

Bir seni düşünürüm

Bir de ülkemi

Ne çok benziyorsunuz

Yakarsınız içimi

Ey esmer güzeli yar, 

Ey esmerler güzeli

Bir seni düşünürüm ben

Bir de güzel ülkemi

Yani bir sana düşkünüm kısaca

Bir de ülkeme

Ne çok benzersiniz birbirinize

Bir acı olup da saplandınız gönlüme

Ey esmer güzeli yar

Kulak versen sözüme

Bir hak versen sevgime

Ben bir sana yangınım

Bir de güzel ülkeme

Anla beni artık

Anla sen artık

Yüreğim yanar durur, gönlüm boş değil

Lakin iki aşkımla da başım hoş değil

Biri sensin o yarin

Biri de ülkem

Ah! sevdiğim kadar

Sevilebilsem', '''Bir gönülde iki aşk yaşamaz'' derler, Ama benim gönlümü gelip de bir görseler;  Benim gönlüm iki aşkı yoğurur durur Hem sana, hem ülkeme, yü...', ARRAY['Türk Edebiyatı','Şiir','Selim Eyşioğlu']::text[], 8.5, '{"poet":"Selim Eyşioğlu","poet_slug":"selim-eysioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/iki-ask-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Şair', 'deli-sair-selim-eysioglu-zybll', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne derlerse desin eller

Boş ver onları, boş ver! ! 

Sen benimsin, baş belamsın, 

Sen dünyalar güzeli,  benim karamsın

Boş ver sen beni, boş ver,  ben deli şair, 

Güzel şeyler söylerim, hep aşka dair

Ama aşkın kuralı var;  yasak, günah, vesair (e) 

Sen dünyalar güzeli,  bana haramsın', 'Ne derlerse desin eller Boş ver onları, boş ver! !  Sen benimsin, baş belamsın,  Sen dünyalar güzeli,  benim karamsın Boş ver sen beni, boş ...', ARRAY['Türk Edebiyatı','Şiir','Selim Eyşioğlu']::text[], 8.5, '{"poet":"Selim Eyşioğlu","poet_slug":"selim-eysioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/deli-sair-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akl-ı Selim', 'akl-i-selim-selim-eysioglu-016aa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Düşünce sen, düşünce sen, 

Bende ki tek düşünce sen, 

Kimseler olmaz yanında, 

Bir gün dara, düşünce sen

Gördüğümde, gör  düğümde

Gel boynumu, gör  düğümde

Bu derdimin sonu ancak, 

Gelir,  seni gördüğümde

Kanıyorum, kanıyorum, 

Hançer vurdun kanıyorum, 

Ne kadar kızsam bile, 

Bir gülüşe kanıyorum..

Aklı Selim, akl-ı selim, 

“Unut” diyor akl-ı selim, 

Zaten unutamaz ise; 

Kaybeder bu aklı, Selim..', 'Düşünce sen, düşünce sen,  Bende ki tek düşünce sen,  Kimseler olmaz yanında,  Bir gün dara, düşünce sen Gördüğümde, gör  düğümde Gel boynum...', ARRAY['Türk Edebiyatı','Şiir','Selim Eyşioğlu']::text[], 8.5, '{"poet":"Selim Eyşioğlu","poet_slug":"selim-eysioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/akl-i-selim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bende Bittim', 'bende-bittim-ali-tekinture-zf4g3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yalnız aşkımızmı kaybolup giden

bende bittim aşın bittiği yerde

gelecek günleri hayal ederken 

bende bittim aşkın bittiği yerde...

süzüldü gözyaşım yanaklarımdan

çaresizlik gezdi damarlarımda

dünya durdu sanki gittiğin anda

bende bittim aşkın bittiği yerde...

Eftalya', 'yalnız aşkımızmı kaybolup giden bende bittim aşın bittiği yerde gelecek günleri hayal ederken  bende bittim aşkın bittiği yerde... süzüldü g...', ARRAY['Türk Edebiyatı','Şiir','Ali Tekintüre']::text[], 8.5, '{"poet":"Ali Tekintüre","poet_slug":"ali-tekinture","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bende-bittim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimse Bilmez', 'kimse-bilmez-ali-tekinture-0ieja', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sarmaş dolaş geçtiğimiz yollardan

Bir başıma geçmek bana ar oldu

Utanırım halim soran kullardan

Yar dediğim gitti ele yar oldu...

Kimse görmez içimdeki yangını

Kimse bilmez hasretimi sancımı

Seve seve kaybettim aklımı

Yaşamakta ölmekte bana bir oldu...

Kırıldı dünyamı tutan direğim

Bedenim yaşarken öldü yüreğim

Şaşırmışım nerelere gideyim

Garip gönlüm bir zalime kul oldu...', 'Sarmaş dolaş geçtiğimiz yollardan Bir başıma geçmek bana ar oldu Utanırım halim soran kullardan Yar dediğim gitti ele yar oldu... Kimse görm...', ARRAY['Türk Edebiyatı','Şiir','Ali Tekintüre']::text[], 8.5, '{"poet":"Ali Tekintüre","poet_slug":"ali-tekinture","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kimse-bilmez-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızım', 'yalnizim-i-smail-ugur-vaxf3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yalnızım gecenin en kuytusunda

Ansızım kapını çalsam diyorum

Ağlayan şu garip bedenimi

Kollarına sarsam diyorum

Gece olunca ağlayan gözlerim

sular seller gibi akar durur

Kaldırımlarda yürüyen bedenim

Ardından bakar durur', 'Yalnızım gecenin en kuytusunda Ansızım kapını çalsam diyorum Ağlayan şu garip bedenimi Kollarına sarsam diyorum Gece olunca ağlayan gözlerim...', ARRAY['Türk Edebiyatı','Şiir','İsmail Ugur']::text[], 8.5, '{"poet":"İsmail Ugur","poet_slug":"i-smail-ugur","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yalnizim-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskiz', 'eskiz-mustafa-yilmaz-8-xneis', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'mü’mini kalmamış bir dinin

peygamberi olmak istemez kimse

doğrudur ve bekli de haklıdır

ama eskiz bir ayıklanma içindi

düşünmekle oluş arasında

sıkboğaz edilen a’raf

doğurgan bir bekleyişte ham

bir atılganlığa bel bağlamayı

yankılı bir susuştan arta kalan

modası geçmiş bir hayat diye

belki bir enver paşa inadıyla

yoklayıp doksan bin kere yok yere

doksan bin kere allâh-û ekber gibi

ey yakışıklı beyler

ve kibirli genç kızlar

gözlerinizi artık kapayın üzerime

ben belleğinde zakkum ninnisi

gövdesi acılarla iliklenmiş

infazı eskiz cenderesinde

şiir bekliyorum

artık herkes iyice bellesin

her hayatın bir kelimeyle

her kelimenin bir kekreyle

başladığını ve kökünden

zamansız budandıkça

dal veren dölün hikayesini

sustukça büyür eskiz gövdesinde

titreyişle çoğalan sancıların

akrep dönencesinde büyüyen benliği

eskimiş şehir kokuları arsında

duymayı bilmek istemeyişiyle

poetikaya tırmanan yokuşun kamburuna

yüklenilmiş bilmek ağrısı

aynı yoldan yürürken insancıklar

hayır bu değil içimde dolaşan

sûre-i mülk’ü arar gibi

necid çöllerinden gelen bedevi

toprak bir bâkiyedir ayaklarımız altında

zorlu ölümler taşıyan kırılganlığıyla

ve çocuklar büyüdükçe

yüzleşmeyi unutur kendi eskizleriyle

bedeli ödenmemiş bir şiir yazmaz

göbeği çatlamış fiyasko

rahmine tutunamadığı cenin gibi

şehrin şehrin şehrin

kurar saltanatını kavs-ı kuzahta

ihtilal artığı bir semender

yankının intiharıyla zehirlenmiştir hasan

hüseyin doğranmış

şeyh said asılmıştır

artık hoyrattır dağlarda rüzgar

yanar eskiz bedeninde

güne çalan muştusu kan lekesinden

15.05.2003

edirne', 'mü’mini kalmamış bir dinin peygamberi olmak istemez kimse doğrudur ve bekli de haklıdır ama eskiz bir ayıklanma içindi düşünmekle oluş arası...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yılmaz 8']::text[], 8.5, '{"poet":"Mustafa Yılmaz 8","poet_slug":"mustafa-yilmaz-8","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/eskiz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nesîm', 'nes-m-mustafa-yilmaz-8-fajvm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ilmek ilmek derilerimizin

kıvrımlarından çekilerek

sıyrılıp düşmüş bir harmaniye gibi

sırtımızdan kızıl bir halep kefeni

çerkes kölelerin elinde zındık ve facir

hurufun cem-i cümlesiyle yek vücut

şahken şahbaz olmuş adamlara

ser verip sır vermeden şah-ı şehid

aşkın imamesi 

ayrılığın nihayesi

ve ömrün kinayesi

ibret-i alem olsun diye

yedi gün yedi gece 

sessiz bir çığlık gibi

esip gitti nesimi

yukarıda gök gibi bir şey

bakarken gözlerine dalgın dalgın

08/04/2003

edirne', 'ilmek ilmek derilerimizin kıvrımlarından çekilerek sıyrılıp düşmüş bir harmaniye gibi sırtımızdan kızıl bir halep kefeni çerkes kölelerin el...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yılmaz 8']::text[], 8.5, '{"poet":"Mustafa Yılmaz 8","poet_slug":"mustafa-yilmaz-8","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/nesim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'tevarih-i osmanîye derkenar', 'tevarih-i-osman-ye-derkenar-mustafa-yilmaz-8-sxo8p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'tevarih-i osmanîye derkenar

ı/ gencosman

mervidir ki

bağdat’ın kapıları açılmadan önce

bir gencosman’ın önünde

kapanmış yedikule’nin kapıları

bir gencosman’ın üstüne

alaca karanlıkta

kişnemiş serâzad kahkahalar

yâr-u ağyar dilinde

yorgunu yokuşa sürmek için

düşmüş kanın namusu kızıllaşarak

on sekizinde bir osmancığın üstüne

günlerden cuma vakitse akşamdır

kara davut paşa ve avanesi

çullanmışlar ölümüne

sıkboğaz ederek kesmişler sesini

soluğu yedikule’de yorgunmuş

gençliği ise bir sürme gibi gözlerinde

nâm almış kâm almamış dünyadan

ne kadar da benziyor her şey

birbirine ne kadar benziyor

tarih bin altı yüz yirmi iki



ıı/ nef’î

beyitin iki ağızlı kılıcını

sararmış kağıtlarda bileyen

erzurum hasankale’den nef’î’yi

murat namında bir adam

ki sultanlığı da vardır

demiri kesen emriyle

ayyaşlığı yanında

önce boğdurur hicvin hokkasında

sonra attırır boğazın sarhoş sularına

nef’î ince bir sazdır

karışır gider martı çığlıklarına

ne kadar can sıkıcı

şâirin ölümü

böylesine tuhaf ne kadar

sarayda beslenip semirirken ûdeba

tarih bin altı yüz otuz beş



ııı/ selimi sâlis

sözler azmış gidiyor

sebeb-i vücûduna dair 

dilimde eski zamanların 

haremde cariyeler rakkâseler

garp nizamiyle nizam-ı cedid sokaklarda

nizam-ı cedid’in lâzımı irad-ı cedid

sultan’ın gizli komitasında kethüda ibrahim’in

mutfak masrafı yüz elli bin altın

saklanır yirmi yedi demir kasada

hüseyin paşa’nın serveti

şaraplar macar ve fransız mâmülü

ol vakit varolmuş derûn devlet mazimizde

kabak patlamış başına nihayet

karanlık bir şimşirlikte

re’fet hanımın gözleri önünde

çığlık çığlığa selimi sâlis

kılıcın namusu ile birlikte düşmüş

sûz-i dilara makamında

tarih bin sekiz yüz sekiz

ıv/ aziz sultan

sûret-i haktan görünerek

tuz ve ekmek hakkı için

kasem üstüne kasem

levanten yüzlü adamların dilinde

adamlar ki akılları üç otuzunda

şeyh’ül islam hayrullah efendi

serasker hüseyin avni paşa

başlarında sadrazam namında bir adam

ahirinde adliye nazırı

mütercim rüştü paşa kabinesinde

adı mithat ünvanı paşa

sultan aziz’in kanına susamış

önce katline ferman biçmişler

kancık bir tertiple ve

fail-i meçhule kurban edilmiş

dolmabahçe’de abdülaziz

sonra intihar süsü altında

nümâyişlerle

şayia vermişler halka

ağır ağır konuşmuşlar

dillerinin kemiği yokmuş lâkin

dillerini üstüpüyle siliyorlarmış

tarih bin sekiz yüz yetmiş altı

20/04/2003

edirne', 'tevarih-i osmanîye derkenar ı/ gencosman mervidir ki bağdat’ın kapıları açılmadan önce bir gencosman’ın önünde kapanmış yedikule’nin kapılar...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yılmaz 8']::text[], 8.5, '{"poet":"Mustafa Yılmaz 8","poet_slug":"mustafa-yilmaz-8","theme":"Türk Şiiri","is_hero":false,"total_lines":86,"source_url":"https://www.antoloji.com/tevarih-i-osmaniye-derkenar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostlara Benim Şikayetim', 'dostlara-benim-sikayetim-huseyin-unal-9vy19', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nedenini bilemezsin bazı ihanetlerin, 

alır gider saf, samimi duyguları, 

dost diye düşündüğün niceleri 

bilmezler karanlığa gözlerini kapatıp bakmanın ne olduğunu, 

bırak; yürüsün balıklar okyanus yerine kimsesiz sokaklarda, 

suya kirli yürekler atılsın: bilirim kan kanla temizlenir, olsun bu defalık

böyle olsun, ilk ve son olsun; 

eğer yine tekrarlanırsa ihanet 

onun  değil benim adım hain olsun...

13.05.2003 Hüseyin ÜNAL', 'Nedenini bilemezsin bazı ihanetlerin,  alır gider saf, samimi duyguları,  dost diye düşündüğün niceleri  bilmezler karanlığa gözlerini kapat...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Ünal']::text[], 8.5, '{"poet":"Hüseyin Ünal","poet_slug":"huseyin-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/dostlara-benim-sikayetim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kafadan gayri müsellah bir adam oturmuş mansur yazıyor', 'kafadan-gayri-musellah-bir-adam-oturmus-mansur-yaziyor-mustafa-yilmaz-8-ioh6l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kafadan gayri müsellah bir adam 

oturmuş mansur yazıyor

kırmızının peşrev faslında

toprağı kanıyla karmış

kan içmiş kızılcık şerbeti demiş

kafadan gayri müsellah bir adam 

ehl-i harabat yahut ehl-i dil 

oturmuş mansur yazıyor

mansur ki

sekerat halinde pîr-i mugan 

aşk şarabın nûş eylemiş 

dilinde kitâb-ı kerim’den ayetler

şeriat bazarını kesat kılmış

kanla alıyor abdestini

namazın selameti içün

kağşamış dökülüyor âzâları

şeyh-i ekber ihtiyar bir pirdir

diz çökmüş dizleri dibinde mansur’un

okuyup duruyor kendi meşrebince

elifi bâyı ve illâ lâ’yı

yazıyor himmeti ile hallâc’ın

füsûsu fütuhâtı

dadanmış darağacına azrail

mansur keçe küllah şahmaran

savurmuş gözlerini ebrûli

muhannete mihnetsiz merhamet içün

işlenir artık aşkın sûretine

bir zerefşan inceliğiyle

gül dikeni gibi sarhoştur

tutuşur şiblî’nin elllerinde

yanar dökülür dicleye

yanık bir yağ kokusu

küller serpilmiş gözlerinde diclenin

su âteş ceset âteş kefen âteş

bunca âteşle şehîd-i aşkı gasletmek

ne mümkün 

ne mümkün âteşi âteşe sarmak

sûretten azâd olmuş dicle

bakıyor musikâr kanatlı göklere

sırr-ı hakkı fâş eylemiş

bir şehîd-i aşkın arkasından

ağlayıp nâlan ederek

mansur mansur diye diye

işte vâridatım ağır bir yük eğnimde

ömrün biriktirdiği nadas

bir günü daha bırakıyorum nadasa

bir günü daha hayatımdan

nümayişsiz bir günü

günler ki savrulur hallaç pamuğu gibi

mansur mansur mansur diyerek

Mustafa YILMAZ

15/04/2003

edirne', 'kafadan gayri müsellah bir adam  oturmuş mansur yazıyor kırmızının peşrev faslında toprağı kanıyla karmış kan içmiş kızılcık şerbeti demiş k...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yılmaz 8']::text[], 8.5, '{"poet":"Mustafa Yılmaz 8","poet_slug":"mustafa-yilmaz-8","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/kafadan-gayri-musellah-bir-adam-oturmus-mansur-yaziyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir avuç eflatun bir tutam gül beyazı', 'bir-avuc-eflatun-bir-tutam-gul-beyazi-mustafa-yilmaz-8-p4to3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir avuç eflatun

bir tutam gül beyazı

kanla yıkanmış lengerlerde

közlenir alaca yüreğimiz

bir mahpushane türküsü gibi

miri malı değil alın terimiz

bir avuç eflatun

bir tutam gül beyazı

bozlaklarla göynüyen bir adam için 

aşk neyin künyesidir

bezirganlar hem muannid

hem de sahtegi

pıtrak gibi dolanırlar eteklerimize

yazılmıştır geceye çay ve tütün

tütün ve kahır

kahır ve gurbet

ekmeğimize kattığımız tuz gibi

acının tiryakisi olmuşuz biz

emeğin havalisinde şehsüvar

gaza niyetine yağız ve delikanlı

ölümü bir seccade gibi yayıp

kevser kokularında çil çil

gürgen dallarında gövermiş

getirip serdik alnımızı merdane

ağırlaşan yakamoz gecelerine

ırgat tarlalarında çilekeş

ölümün yumağını çözdük biz

bir köy çobanı gibi

yüreğimizi bir kavala bağlayıp

sırtımızda kepenek

ibrişim kaşlarından geçerek 

ay yüzlü sevgilinin

bir mengeneyi kırar gibi

bir tohumu çatlatır gibi

yüzümüz atlas hançeremiz bozlak

göğsünde gedik açtık dünyanın

hey dağlar hey ala dağlarım

koynunda yarim ağlar

huma kuşu uçmaz bizim göğümüzde

fetretine düşmüşüz insanlığın

hançerlenir eşgalimiz habire

sözlerimiz kalebent

gergefe çekilmiş erguvan

sel sebil olmuş akar kanımız

idil havası uğramaz şehirlere

çünkü şair sözleri çarmıhtadır

sokaklarda telsiz sesleri

hafta sonu haberlerinde bir kadın

ölü bulunmuştur palas otelde

harmaniyesi soğuk ve taşkındır

zümrüt yakut ve zeberced

sahtiyan bir çantadan dökülür

oysa görklüdür çocukların gözleri

geceye yazılan türküler gibi

gureba tekkesine sığınmıştır ayrılık

ne yana düşer hicabi

böğürtlen tadında gözler

alaca bir kıyamet gibi

gelüben mağrur ve kederli

taflan taflan yağarak

yanarak kerem gibi

tutup kabzasından şimdi

şair sözlerini kaldırmak vaktidir

yani vakit ikindidir

öyleyse eğer yaşamak gerek

yaşamak gerek tek atımlık da olsa

kanla yıkanmış lengerlerde

közlenir alaca yüreğimiz

bir mahpushane türküsü gibi

miri malı değil alın terimiz

bir avuç eflatun

bir tutam gül beyazı

bozlaklarla göynüyen bir adam için 

aşk neyin künyesidir

25/01/2003

edirne', 'bir avuç eflatun bir tutam gül beyazı kanla yıkanmış lengerlerde közlenir alaca yüreğimiz bir mahpushane türküsü gibi miri malı değil alın t...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yılmaz 8']::text[], 8.5, '{"poet":"Mustafa Yılmaz 8","poet_slug":"mustafa-yilmaz-8","theme":"Türk Şiiri","is_hero":false,"total_lines":76,"source_url":"https://www.antoloji.com/bir-avuc-eflatun-bir-tutam-gul-beyazi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-dilek-gumusay-xppmv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yalnızım bu yaban ellerde

Çaresizim ıssız bu köşelerde.

Kolum kırık kanadım kırık

Zehir içiyorum adeta her su şişesinde.

Korkuyorum, ürküyorum, 

Haykırıyorum kurtaran yok mu beni diye

Ama hiç kimse duymuyor

Hapsoluyor ruhumun en derinlerinde.', 'Yalnızım bu yaban ellerde Çaresizim ıssız bu köşelerde. Kolum kırık kanadım kırık Zehir içiyorum adeta her su şişesinde. Korkuyorum, ürküyor...', ARRAY['Türk Edebiyatı','Şiir','Dilek Gümüşay']::text[], 8.5, '{"poet":"Dilek Gümüşay","poet_slug":"dilek-gumusay","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yalnizlik-111-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Resim', 'resim-dilek-gumusay-16mkz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kalbim bir tuval

Üstüne resmin çizili

Altına ismin kazılı

Ressamı ben

İlhamı da sen...

Ağzım bir kapı

Artık kilit vurulu

Hayli zamandır kapalı

Anahtarı ben

Çilingiri de sen...', 'Kalbim bir tuval Üstüne resmin çizili Altına ismin kazılı Ressamı ben İlhamı da sen... Ağzım bir kapı Artık kilit vurulu Hayli zamandır kapa...', ARRAY['Türk Edebiyatı','Şiir','Dilek Gümüşay']::text[], 8.5, '{"poet":"Dilek Gümüşay","poet_slug":"dilek-gumusay","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/resim-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık Sevmiyorum', 'artik-sevmiyorum-dilek-gumusay-09vnm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yüzünü görmek istemiyorum

Sesini duymak hele hiç

Arama beni istemiyorum

Hele hiç adımı anma

Sorma neredeyim, ne yapıyorum

Karşıma çıkma bir daha

Ne seni görmek

Ne de sesini duymak istiyorum

Çünkü artık seni sevmiyorum

Hiçbir şeyim değilsin.', 'Yüzünü görmek istemiyorum Sesini duymak hele hiç Arama beni istemiyorum Hele hiç adımı anma Sorma neredeyim, ne yapıyorum Karşıma çıkma bir ...', ARRAY['Türk Edebiyatı','Şiir','Dilek Gümüşay']::text[], 8.5, '{"poet":"Dilek Gümüşay","poet_slug":"dilek-gumusay","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/artik-sevmiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üşümek ve Sen', 'usumek-ve-sen-dilek-gumusay-ifiks', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sonbahardan kışa doğru ilerlerken zaman

Üşümek bu soğuk akşamlarda 

Seni sevdiğimi hatırlatıyor

Yaşadığımı anlatıyor hala

Mutlu ediyor beni üşüyebilmek

Üşürken de seni düşünmek

İçim bir tuhaf oluyor

Ruhum mutlulukla dolup taşıyor

Seni düşünüyorum

Hem de üşüyorum

Üşüyorum ve seni düşünüyorum

Ben üşümeyi de seni de çok seviyorum.', 'Sonbahardan kışa doğru ilerlerken zaman Üşümek bu soğuk akşamlarda  Seni sevdiğimi hatırlatıyor Yaşadığımı anlatıyor hala Mutlu ediyor beni ...', ARRAY['Türk Edebiyatı','Şiir','Dilek Gümüşay']::text[], 8.5, '{"poet":"Dilek Gümüşay","poet_slug":"dilek-gumusay","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/usumek-ve-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin', 'gozlerin-dilek-gumusay-bggyh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Boğar beni gözlerin

Çıkamam girdabından

Kilitlenir ağzım

Hiç konuşamam

Belkide gururumdan', 'Boğar beni gözlerin Çıkamam girdabından Kilitlenir ağzım Hiç konuşamam Belkide gururumdan...', ARRAY['Türk Edebiyatı','Şiir','Dilek Gümüşay']::text[], 8.5, '{"poet":"Dilek Gümüşay","poet_slug":"dilek-gumusay","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gozlerin-73-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sordun mu?', 'sordun-mu-dilek-gumusay-pjjae', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hiç baktın mı uzun uzun kapılara

Her açılışında duydun mu yüreğimin çırpınışını meraktan

Kapanınca yavaşlattığını kanatlarını umutsuzluktan

Doldu mu gözlerin yaşlarla

Oldu mu boğazın düğüm düğüm

Ağlayabildin mi hıçkırıklara boğularak

Halsiz kaldın mı ağlamaktan

Uyuya kaldın mı hiç ağlayarak

Sordun mu sonra kendi kendine niye

Değer mi sevmeye böyle ölesiye?', 'Hiç baktın mı uzun uzun kapılara Her açılışında duydun mu yüreğimin çırpınışını meraktan Kapanınca yavaşlattığını kanatlarını umutsuzluktan ...', ARRAY['Türk Edebiyatı','Şiir','Dilek Gümüşay']::text[], 8.5, '{"poet":"Dilek Gümüşay","poet_slug":"dilek-gumusay","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sordun-mu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekle', 'bekle-dilek-gumusay-5n3s1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ayrılmak zor olsa da senden 

Senin yaşadığın bu şehirden

Ama mecburum ne yapayım

Erken dönerim eğer istersen

Kalamam oralarda daha

Aklım kaldıysa yanında

Bekle beni oradayım

Çarşamba''ya Ankara''da', 'Ayrılmak zor olsa da senden  Senin yaşadığın bu şehirden Ama mecburum ne yapayım Erken dönerim eğer istersen Kalamam oralarda daha Aklım kal...', ARRAY['Türk Edebiyatı','Şiir','Dilek Gümüşay']::text[], 8.5, '{"poet":"Dilek Gümüşay","poet_slug":"dilek-gumusay","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bekle-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-dilek-gumusay-kl117', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aylar geçse de sen gideli, 

Yıllar geçse de aradan, 

Bitmez bitmeyecek, 

Sana olan bu sevdam.

Mesafeler girse de aramıza, 

Ayırsa da seni benden, 

Birleştirir yine de, 

İster ise Yüce Mevlam.', 'Aylar geçse de sen gideli,  Yıllar geçse de aradan,  Bitmez bitmeyecek,  Sana olan bu sevdam. Mesafeler girse de aramıza,  Ayırsa da seni be...', ARRAY['Türk Edebiyatı','Şiir','Dilek Gümüşay']::text[], 8.5, '{"poet":"Dilek Gümüşay","poet_slug":"dilek-gumusay","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ayrilik-108-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Gitmemişsin Gibi', 'hic-gitmemissin-gibi-dilek-gumusay-mc928', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kalmadı mekana 

Sığmadı zamana

Sen gittin...

Şimdi hayaller kurmak kaldı bana.

Hayallerde bakışmak

Hayallerde konuşmak

Hayallerde buluşmak

Tıpkı sen benimmişsin gibi

Tıpkı hiç gitmemişsin gibi.', 'Kalmadı mekana  Sığmadı zamana Sen gittin... Şimdi hayaller kurmak kaldı bana. Hayallerde bakışmak Hayallerde konuşmak Hayallerde buluşmak T...', ARRAY['Türk Edebiyatı','Şiir','Dilek Gümüşay']::text[], 8.5, '{"poet":"Dilek Gümüşay","poet_slug":"dilek-gumusay","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hic-gitmemissin-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitmemiş Şiirin Közleri', 'bitmemis-siirin-kozleri-hasan-aktas-dyio1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çocuklar

Önce bitmemiş şiirin coğrafyasında silahlandılar

Sonra şiirin közlerinde açan çiçekleri tanıdılar

Hep sevilmekten korktular

Sözlerini küller ve közler arasında çoğalttılar

Mühürlü gülümseyişleriyle

Kanlı ihtilallerin ayak sesleridir

Camgüzeli metropol duyarlılıklarında

Çocuklar önlerinde silahlar. Arkalarında

Çiçekler ve kendi hüzünlerinde sürgün

Taşralı sonbahar melankolisidir

Yandım çavuş ayranlarında kendisini arayan

Hüzünler büyülü rüyalarda ölümsüzleşir

Ve görüntüler bestelenmiş hülyalarda depreşir

Sevişmelerin kırsallığı

Uçurumlardan doğurgan mahzenlere açılır

Şairler rüyalarını nedense hep gündüz görürler

Bir şiir çocuk gülüşlerinde başlar

Yetim ağlayışlarında biter

El yordamıyla düşlerin yalnızlığını aralayan onlardır

Şairler varlıklarını

Elbette çocuklara ve kadınlara borçludurlar

Bütün intiharları onlar önceden yüklenmişlerdir

Uzaklarda bir yerlerde  acıdan ve hüzünden

Kavgalardan sürgünden söz ediliyorsa

Bütün bu eylemlerin öznesi kadınlar ve çocuklardır

Hem sevdanın keremi hem aslıdır onlar

Aşkın boy aynasına yansıyan

İkindi cephelerinin gerisinden

Yüreğinde taşıdığı bin cehennemi

Gecelerine yorgan eden onlardır

El yazılarını kuşatan

Damarlarındaki hüzün haritasıdır

Bitmemiş şiirin közlerinde

Kıyam saatleri

Hasan AKTAŞ', 'Çocuklar Önce bitmemiş şiirin coğrafyasında silahlandılar Sonra şiirin közlerinde açan çiçekleri tanıdılar Hep sevilmekten korktular Sözleri...', ARRAY['Türk Edebiyatı','Şiir','Hasan Aktaş']::text[], 8.5, '{"poet":"Hasan Aktaş","poet_slug":"hasan-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/bitmemis-siirin-kozleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Filbahri Akşamlarında Yanan Bir Yanık Kerem''im Ben', 'filbahri-aksamlarinda-yanan-bir-yanik-kerem-im-ben-hasan-aktas-1dv5v', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'minyatür güzelliklerin karanlığında büyüyen ay

afrika menekşelerini mahşere hazırlayan

bir sevdalı gibidir

ressamlarca kundaklanan sarışınlıklar 

bir çağı bir çağdan kaçırır gibidir

noel çarklarının ışıklarında ölen İsa

havarilerine gazel okumuyor artık

ama ben

sihr-ü efsun ile dolan gönlümün karanlıklarında meşrebimce işret edip

güzel sevmeye ve şiir okumaya devam edeceğim

şiirin kıvılcımlarında tutuşan gönlüm 

filbahri akşamlarında kerem’in arpa tarlası gibi

yanan bir yanık kerem’im ben

şimdi tar-u mar olmuştur gönül bahçem

mevsim hep hazandır

hızır ve roza buluşurlar hayat bilgisi dersinde

beni yangınlara verirler

bir ilkyaz sessizliğinde ölümüme tarih düşürürler

mezarıma giren bakirelere bir damla hızır

bir damla roza iksiri sunarsam/belki

toptan dirilip insanlığı mahşere sürükleyecekler

fakat unutulan ben olacağım

oylumlu şarkıların orkinoslarında

kerem’in arpa tarlası gibi yanan ben olacağım

ben olacağım/ban olacak olan/ben olacağım

filbahri akşamlarında duman eksilmeyecek

küllerimi karıp göz yaşlarımla yoğurduğum

mürekkeple sevdiğime yazacağım mektup

bir adet matla-ı berceste olacak

bir adet makta-ı berceste yazacağım

altına tarih düşmeyeceğim

kanla ve göz yaşlarımla kül fallarımda

firari sözcükler fışkıracak

ya gidip bir şiirin

satır aralarını süsleyecekler

ya da benim gibi bir narın nuruna yanıp gidecekler

filbahri akşamlarından şairler sözcük

aşıklar ateş çalmak için canlarını feda edecekler', 'minyatür güzelliklerin karanlığında büyüyen ay afrika menekşelerini mahşere hazırlayan bir sevdalı gibidir ressamlarca kundaklanan sarışınlı...', ARRAY['Türk Edebiyatı','Şiir','Hasan Aktaş']::text[], 8.5, '{"poet":"Hasan Aktaş","poet_slug":"hasan-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/filbahri-aksamlarinda-yanan-bir-yanik-kerem-im-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapalı Çarşı Ve Şayet Aşk', 'kapali-carsi-ve-sayet-ask-hasan-aktas-eyi2j', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Toz pembe kapalı çarşı

İçinde kör düğümler kırk düğümler

Nineler sabaha çıkarlarsa

Şairler şayet aşk içindedir

Zor geçitler fark edilirse

Yenilikler gece yarılarına ertelenirse

Çevrede evler evcikler  ve yıkık duvar diplerinde

İthaf edilemeyen şiirler okunuyorsa

Fakirler şayet aşk içindedir

Gece yarılarından sonra fark edilen

Sizin hikayeniz hülyaların şiiridir

Uykusuz gece dörtlüklerini

Dağ başlarında  yanan ateşlere ulaştırırsa

Kar fırtınaları şayet aşk içindedir

Yeni yıla yeni cenazelerle

Eski yakarışlarla ara nağmelerle girilir

Buğulu camlardan kaydı silinen kış ayları

Değişen dünyaya bir bayram ziyareti gibi düşerse

Elifler şayet aşk içindedir

Oyun 3 Tablo 4

Maskeli baloda ölümün sırları açıklanırsa

Ateş yalımları üstünde bir toplantı kaçınılmazdır

Ve dünya aşk içinde yanmaktadır', 'Toz pembe kapalı çarşı İçinde kör düğümler kırk düğümler Nineler sabaha çıkarlarsa Şairler şayet aşk içindedir Zor geçitler fark edilirse Ye...', ARRAY['Türk Edebiyatı','Şiir','Hasan Aktaş']::text[], 8.5, '{"poet":"Hasan Aktaş","poet_slug":"hasan-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kapali-carsi-ve-sayet-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün Mevsiminde Acılara Karşı Direnen Bir Militan Yüreği', 'huzun-mevsiminde-acilara-karsi-direnen-bir-militan-yuregi-hasan-aktas-7k0na', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'işte geldim gidiyorum

şen olasın halep şehri

her yer kerbela

her gün aşura

ve gecenin ortasında kurşunlanan militanın yüreği

acılardan hüzünlere 

hüzünlerden sürgünlere açıldı ardınca

bütün mevziler kanla doldu 

ve mavzerler

zulme karşı kudurdular kıyasıya

zincirlerini kırasıya

yağmur başlarken alaturka şarkılar

alafranga şarkılarla özdeştiler

militanın yüreği yalım yalım kavruldu

öfkesini şehrin duvarlarına savurdu şiddetle

acılarını sarıp sarmalayıp 

beledi hüzün mevsimlerine

hüzün mevsimlerine demledi sabrını

sabrını küllenmiş mevsimlerden damıta damıta

kızgın tennurelerde kavurdu 

bütün acılarını ve hüzünlerini

ağlayışları şafağa uyanan çocukları emzirmeye hazırladı

kurumuş memelerini

yağmurlar kara dönüştü giderek

tabakasından tütün çıkarıp sardı altın sarısı

yüreğini çıkarıp saldı zamanın sonsuzluk denizine

bir daha dünyaya gelirse

şair ve militan olarak geleceğinden emindi

acılarla hüzünlerle sürgünlerle

yüreği çatılmış

Ve devingenliğin devrimcisi

hüzünlerin şairi

ŞiiRiN DERViŞi', 'işte geldim gidiyorum şen olasın halep şehri her yer kerbela her gün aşura ve gecenin ortasında kurşunlanan militanın yüreği acılardan hüzün...', ARRAY['Türk Edebiyatı','Şiir','Hasan Aktaş']::text[], 8.5, '{"poet":"Hasan Aktaş","poet_slug":"hasan-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/huzun-mevsiminde-acilara-karsi-direnen-bir-militan-yuregi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Bağımsın', 'hayat-bagimsin-i-zzet-selcuk-cumaoglu-s17z4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hoş sohbet sevdalar kalmadı artık, 

Nerede başladık nereye geldik, 

Beraber ağladık, beraber güldük, 

Sözlerin bağlıyor beni hayata.

Kurumuş bahçede yanmıyor ocak, 

Küskünüm kendime, imkansız kaçmak, 

Böylesi dünyada yaşanmaz, ancak

Gözlerin bağlıyor beni hayata.

Gül ağlıyor diye bülbüller suskun, 

Şarkılar ağlamaklı, sazende üzgün, 

Güfteler tükenmiş, notalar suskun, 

Sazların bağlıyor beni hayata.

Çekilmez bu ömrüm, dolmadı benim, 

Bunca zaman yüzüm gülmedi benim, 

Baş koyduğum yastık olmadı benim

Dizlerin bağlıyor beni hayata.

Sevmesem katlanmam böyle kaçışa, 

Yorgunu sürersin dik bir yokuşa, 

Hangi can dayanır böyle bakışa, 

Nazların bağlıyor beni hayata.', 'Hoş sohbet sevdalar kalmadı artık,  Nerede başladık nereye geldik,  Beraber ağladık, beraber güldük,  Sözlerin bağlıyor beni hayata. Kurumuş...', ARRAY['Türk Edebiyatı','Şiir','İzzet Selçuk Cumaoğlu']::text[], 8.5, '{"poet":"İzzet Selçuk Cumaoğlu","poet_slug":"i-zzet-selcuk-cumaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hayat-bagimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlıktır Her Şiir', 'yalnizliktir-her-siir-melih-coskun-3h5nq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Daha çok vakit olacak 

Yalnızlığı yazacak 

Kırılacaksın elbet donmuş yaprak gibi

Daha çok otobüs kaçarcasına gidecek bu şehirden 

Kaç çocuk ağlayacak daha 

Bu elveda son sanma 

Bu sevda ilk değil 

Ve bu ayrılık son olmayacak 

Sanma ki böyle sürer bu hikaye 

O da bir gün tükenip gider 

Ama ne olursa olsun

Adam gibi yaşamalı artık 

Yaşanacak ne olacaksa ömründe 

Yıkılan binalar yapılabilmeli yeniden 

Gülebilmeli bir gün ağlayan çocuk 

Daha çok vakit olacak 

Yalnızlığı yazacak 

Birazda umudu anlat bana

Hani balya balya Amerikan doları kimine göre

Kimine göre çıkabilmek yaşayarak 

Yeni bir güne! 

Kimine göre parıldayan gözleri sevgilinin

Daha çok vakitler olacak

Yalnızlığı yazacak 

Çünkü yalnızlıktır her şiir 

Her dize ayrılığı anlatır biraz...

20 Mart 2003

00: 54', 'Daha çok vakit olacak  Yalnızlığı yazacak  Kırılacaksın elbet donmuş yaprak gibi Daha çok otobüs kaçarcasına gidecek bu şehirden  Kaç çocuk ...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yalnizliktir-her-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ararım Seni', 'ararim-seni-i-zzet-selcuk-cumaoglu-aalsn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dokunduğumda içimi titreten

O yumuşak, o narin tenin gelir de aklıma

Kelebeklerin kanadında ararım seni.

Düşündükçe ilham veren sesini

Hatırladıkça dudaklarındaki lezzeti

Arının peteğinde ararım seni.

Nefesim sen olursun soludukça havayı

Kokunu duyarım uzakta da olsan

Orkideler gibi dik yamaçlarda

Dağların doruğunda ararım seni.

Uyuduğunu düşünürüm, büzülmüş yatağında

Yastığın olurum hayal de olsa

Beşiğin kollarında ararım seni.

Yakışmaz yanına en nadide çiçek

Benden başka kimler bilecek

Yoktur başka, senin gibi yetiştirilebilecek

Özel seralarda ararım seni.', 'Dokunduğumda içimi titreten O yumuşak, o narin tenin gelir de aklıma Kelebeklerin kanadında ararım seni. Düşündükçe ilham veren sesini Hatır...', ARRAY['Türk Edebiyatı','Şiir','İzzet Selçuk Cumaoğlu']::text[], 8.5, '{"poet":"İzzet Selçuk Cumaoğlu","poet_slug":"i-zzet-selcuk-cumaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ararim-seni-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökten Düştü Sevda', 'gokten-dustu-sevda-naime-erlacin-n1pjs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'labirentte geçti hayat

engebeli coğrafyalarda

koştum 

düştüm 

bilendim

rüzgarda havalandı  düşlerim

yüreğim lodostan azgın 

çok yoruldum 

az güçlendim

yaşamayı öğrendim

mekan tuttum okyanusu

limanlar dolaştım adsızdılar

kara gördüm denizde 

ve koylar 

korunaksızdılar

kah paramparçaydı yelkenim 

kah pusulasız 

tek kürekle ulaştım kıyıya 

korunmayı öğrendim

çıktım er meydanına

vuranlar gördüm kahpece

vurulup düşenler habersiz

kuşandım silahımı bir bilgeden

direndim direnebildiğimce

barış tuttum da özümle

düşünmeyi öğrendim

gökten düşmüştü sevda

öğrenilmedi 

yaşandı

sorarsan 

“değdi mi? ”

orasını bilemem

öğrenemedim ki! 

(13 Mayıs 2003)', 'labirentte geçti hayat engebeli coğrafyalarda koştum  düştüm  bilendim rüzgarda havalandı  düşlerim yüreğim lodostan azgın  çok yoruldum  az...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/gokten-dustu-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dinletemedim', 'dinletemedim-i-zzet-selcuk-cumaoglu-8p3yg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ağlamak yok dedim aşkın peşinden, 

Atıldım gönlünden, çıktım düşünden, 

İçime gir de gör, bakma dışımdan, 

Nefreti kalbime anlatamadım.

Akmasın istedim gözlerimden yaş, 

Kendime ne sözler verdim üstelik.

İçime doldu da acı bir telaş, 

Gözümdeki yaşa dinletemedim.

Zor geliyor böyle ilgisiz kalmak, 

Ne mümkün aşkını kalbimden atmak, 

Adını anmasam, unutsam bile, 

Düşlerimde seni unutamadım.', 'Ağlamak yok dedim aşkın peşinden,  Atıldım gönlünden, çıktım düşünden,  İçime gir de gör, bakma dışımdan,  Nefreti kalbime anlatamadım. Akma...', ARRAY['Türk Edebiyatı','Şiir','İzzet Selçuk Cumaoğlu']::text[], 8.5, '{"poet":"İzzet Selçuk Cumaoğlu","poet_slug":"i-zzet-selcuk-cumaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dinletemedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukları Kurtarın', 'cocuklari-kurtarin-oguzkan-bolukbasi-bj4zk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ateşler  yuvarlanıyordu

kimin yaktığı belirsiz

sessiz

ve sakin bir gecenin uykusundaki kentin üzerine

açılan kapılardan korkulu gözler fırlıyordu

açılmayan kapılardan ölümler

insanlar kendi hatalarını düzeltiyordu başka biryerlerde

bir başka kentte yeni hatalar yapılıyordu

çocuklara üzülürüm ben ne zaman bir karışıklık olsa

anlamadan korkarlar ve sevinirler ve ölürler

en çok çocuklara üzülürüm

sıcak bir çorba üzerine üşüşür gibi açlıklarda

bir çikolata paketinde sevgiye üşüşürler

hiçbir şey kalmadı aslında

ateşler yaktı suları

sular kaynamakta

insanlığın tedirgin uykuları

karabasanlardan karabasanlara yolculuk edecek

yine çocuklar ölecek

gülümseyen ruyalardan uyanmaksızın

ve gülümseyen sabahlara hasret kentlerde

bir acı yoğunluğu çekilmiş resimlerde

ateşler yuvarlanıyor

sular yanıyor

bir tufan ki yanmayan gemiler gerekiyor

alev denizlerinde bir kaptan dümensiz ve yelkensiz 

bulunur mu dersiniz

peygamberler devrinin bittiği zamanlarda

ateşler yuvarlanıyor

çocukları kurtarın', 'ateşler  yuvarlanıyordu kimin yaktığı belirsiz sessiz ve sakin bir gecenin uykusundaki kentin üzerine açılan kapılardan korkulu gözler fırlı...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/cocuklari-kurtarin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nigâr', 'nig-r-hakan-kose-rhgc1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gece, yıldızlı gece

Ay sarı ve sen Nigâr

Kapatma gözlerini

Bütün aşklar sana çıkar

Gözlerin câna değince

Olmaz olsun şarkılar

Kapatma gözlerini

Ağlıyor martılar

Sen kuş uykusu, sen yıldız

Sen mûtenâ baharsın

Sen gönüllerde yârsın

Nigâr, yâr Nigâr....', 'Gece, yıldızlı gece Ay sarı ve sen Nigâr Kapatma gözlerini Bütün aşklar sana çıkar Gözlerin câna değince Olmaz olsun şarkılar Kapatma gözler...', ARRAY['Türk Edebiyatı','Şiir','Hakan Köse']::text[], 8.5, '{"poet":"Hakan Köse","poet_slug":"hakan-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/nigar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Süveyda', 'suveyda-huseyin-unal-2pkjq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Saklanarak korkularının ardına,

Ürkerek, titreyerek işittiğin, 

Ve  ne olduğunu senin de bilmediğin: 

Ensene nefesiyle birlikte çarpan sesi, 

Yüreğini parçalayıp, gözlerini karartırken anlayacaksın; 

Dert yüklü sinelerin elinde parçalandığını görüp, 

Ağlayacaksın...', 'Saklanarak korkularının ardına, Ürkerek, titreyerek işittiğin,  Ve  ne olduğunu senin de bilmediğin:  Ensene nefesiyle birlikte çarpan sesi,...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Ünal']::text[], 8.5, '{"poet":"Hüseyin Ünal","poet_slug":"huseyin-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/suveyda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taptaze', 'taptaze-naime-erlacin-dpovz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'tarih kadar eskiydi

gelen gün kadar taze

“gönlüme sorsan, doğmadı bile” demişti 

taze bir cinayetti oysa gördüğü ellerinde

kadın efsane öldürdü 

kırılmalı kalem! 

tezi yok yaratmalı bir tane

taze taze

hayal tacirliği mi bu

önce yaratmak ve sonra

sonrası tehlike

kim kala kim öle! 

zordu kadınla baş etmek

“bütün elmalar kadına” demişti 

çürüttü kadın elmaları

yenisini yaratmakta şimdi

taze taze

kıyılar ses verir 

kuyular da

o halde dinlemeyi öğrenmeli 

kadın gibi kadınca

ölümü bekleyerek insan gibi

taptaze…

(18 Mayıs 2003)', 'tarih kadar eskiydi gelen gün kadar taze “gönlüme sorsan, doğmadı bile” demişti  taze bir cinayetti oysa gördüğü ellerinde kadın efsane öldü...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/taptaze-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Parmağımı Güz Kesti', 'parmagimi-guz-kesti-ozgur-hatem-22m5w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Parmağımı güz kesti, 

Senin suçun yok! 

Sarışın mevsimin hançeriydi

Azıcık serin, 

Alabildiğine derin

Ve keskindi! 

Aykırıydım belki.

(Ondan mı hırçınlığım?)

İlk elden yaralıydım

İstemedim kabuk bağlasın.

Şair amcalar

Önceden vurmuştu beni

Her yanımda imgelerden kıymıklar

Parmağım içime kanadı sessizce

Ilık, dingin ve gizliydi.

Önce yaram tanıdı seni

Gözlerin bildik bir resim.

Bir uyak daha saplandı usuma

Ellerinin bereketi tenime değdi

Ürkek, telaşlı ama iyice emindi.

Kumdan kalelere hapsolmuştum ben.

Ayık zamanların esiri

Senin esrikliğinin suçu yok

Parmağımı ben uzattım, 

Güz kesti.

17.05.2003

Mersin', 'Parmağımı güz kesti,  Senin suçun yok!  Sarışın mevsimin hançeriydi Azıcık serin,  Alabildiğine derin Ve keskindi!  Aykırıydım belki. (Ondan...', ARRAY['Türk Edebiyatı','Şiir','Özgür Hatem']::text[], 8.5, '{"poet":"Özgür Hatem","poet_slug":"ozgur-hatem","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/parmagimi-guz-kesti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göç', 'goc-ozgur-hatem-52n79', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Göçü durmaz ruhumun

Tek uçuşta gördüğüyle

Gönendim.

Hele devran

Hele hayat

Bir de yar...

Vay! çağımın 

Darda kalmış aşkları

Vay benim! 

Zorda tutsak adamım.

Dermansızlar

Kanatsızlar

Kentten kente göçemeyen

Ucu yanık mektuplar.

17.05.2003

Mersin', 'Göçü durmaz ruhumun Tek uçuşta gördüğüyle Gönendim. Hele devran Hele hayat Bir de yar... Vay! çağımın  Darda kalmış aşkları Vay benim!  Zord...', ARRAY['Türk Edebiyatı','Şiir','Özgür Hatem']::text[], 8.5, '{"poet":"Özgür Hatem","poet_slug":"ozgur-hatem","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/goc-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can''dan Can''a', 'can-dan-can-a-alaettin-isik-f63oi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bana gönderdiğin sevgi anahtarı, 

Sana da gelsin sevda baharları, 

Bana dağların uzun sarp yolları, 

Vız gelir önüme serseler karları..

Uçun kuşlar uçun Canan''a doğru, 

Umudu çağırmasın selam yollasın, 

Bir kor alev  el yakmaz, yürek yolu

Kalbimde ondan gelen aşk dolu.

18/05/2003

Neden çarpar kalbin, neyi hayaller, 

Can''dan Can''a ne istersin neler, 

Bitmez bu sevda, yaşanır geceler, 

Gelirse gelsin  benden sana, senden bana.', 'Bana gönderdiğin sevgi anahtarı,  Sana da gelsin sevda baharları,  Bana dağların uzun sarp yolları,  Vız gelir önüme serseler karları.. Uçun...', ARRAY['Türk Edebiyatı','Şiir','Alaettin Işık']::text[], 8.5, '{"poet":"Alaettin Işık","poet_slug":"alaettin-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/can-dan-can-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Bulduğum Zaman', 'seni-buldugum-zaman-alaettin-isik-w4edo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çöllerde açan çiçekler gibi, 

Gelene gidene gülümser oldum, 

Hazanda bahar, göklerde kuş gibi

Ahengi ve sevgiyi sende buldum.

Sert  esen rüzgarların dağıttığı, 

Gecelerin mateminde ağlattığı, 

Yılların acımasızca yıprattığı, 

Bir güz gününde ben seni buldum.

18/05/2003

Bilirim öksüz kalan ruh halinden, 

Ve sevgi dallarında bekleyen, 

Öfke, nefret ve kinden kaçarken, 

Sımsıcak sevginle ben seni buldum.

İnce, zarif ve şiir tadında ruhunla, 

Ürkek ama anlamlı çağrılarınla, 

Kendine has, benliğime  varışınla, 

Sevgiye hasret, ben seni buldum. 

(25/02/2003)', 'Çöllerde açan çiçekler gibi,  Gelene gidene gülümser oldum,  Hazanda bahar, göklerde kuş gibi Ahengi ve sevgiyi sende buldum. Sert  esen rüz...', ARRAY['Türk Edebiyatı','Şiir','Alaettin Işık']::text[], 8.5, '{"poet":"Alaettin Işık","poet_slug":"alaettin-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/seni-buldugum-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlamıyorum', 'anlamiyorum-yilmaz-sezgin-zjdfs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Anlamıyorum bu insanları

Kimi zaman

“Ben bu dünyada mı yaşıyorum”diye 

Soruyorum kendi kendime

Ahmet efendi düzenbazın biri

Efendilikle alakası yok ama efendi

Eskiden mazot yerine zeytinyağı

Benzin yerine su satılırdı

Şimdilerde zeytinyağı vitrinlik

Anadolu’nun has çocuğu

Şeffaflaştırıldı poşetlerde

Bizim beyler modern demokrat

Söz verdiler 

Halka inenceğiz dediler 

Halkın cebine indiler

Önce bir anahtar soruldu

Sonra iki anahtar uyduruldu

Bulmaca çözüldü 

Mertlik bozuldu

Ya şu gazeteciler

Ciltli, ciltsiz

Birinci kalite, ikinci hamur derken

Seninki, benimki kavgasında

Verdiler, eleştirdiler

Yumurtlayan tavuğun altına da girdiler





Bazan bir düğün kurulur

Karnaval mi belli değil

Birilerine ziyafet verilir 

Afrikalı açlara yardım görülmüş değil

Bunlar aç gözlü çağdaşlarımız

Çalsın sazlarımız

Oynasın kızlarımız

Belden uzun bacaklılarımız

Akşam defilelerde, geceleyin evlerde

Kim bilir nerelerde

Pırlanta kolyelerle, vizon kürklerle

Jaguarların kuytu köşelerinde

Anlamıyorum bu insanları

Bizim şair bozuntusu

Yazar kendi halinde

Birisi deneme, ikincisi derleme 

Üçüncüsü seneye

Nereden nereye 

Geldik gidiyoruz geriye

Bir madalyon takmışlar deliye

“Olmaz! ”demiş deli

Ben deli miyim ki

Teşhir ediyorsunuz beni

                    Nisan1993', 'Anlamıyorum bu insanları Kimi zaman “Ben bu dünyada mı yaşıyorum”diye  Soruyorum kendi kendime Ahmet efendi düzenbazın biri Efendilikle alak...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Sezgin']::text[], 8.5, '{"poet":"Yılmaz Sezgin","poet_slug":"yilmaz-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/anlamiyorum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boynuyoğun', 'boynuyogun-yilmaz-sezgin-3d491', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gün yine karanlık

İkinci günün ortasında

Ulaştık düşe kalka

Yeni görev için duyulan üzüntü

Beş günlük koşuşturmanın verdiği yorgunluk

Sıkıntılı yolculuğun enfes yeşiliyle

Yerini rahatlığa bırakıyor

Ta ki

Gerçeklerle yüzleşinceye kadar

Saat on altıya doğru 

Birkaç bisküviden oluşan öğle yemeği

Şükürler olsun

Bir hanın var mı arkadaş

Ya bir döşeğin

İçtenlikle duyulan tebessüm 

Koptuğu yere kadarHey! 

Bana neler oluyor

Kahvede oturmazdım

Başımın ağrısı açlıktan mı acaba

Firar mı etseydim ne

Çekip gitmekte vardı ya

Düşünceler teselli vermiyor 

Uyumak istiyorum

Hem de bir köy kahvesinde

Günün sonuna doğru 

Yalnızım yapayalnız

Bir aşım bile yok

Aş, döşek, han

İhtiyacım olan her şey

Hey gönül hey

Diğer meseleler avare

Uzak birer nokta gibi

        20Temmuz1994', 'Gün yine karanlık İkinci günün ortasında Ulaştık düşe kalka Yeni görev için duyulan üzüntü Beş günlük koşuşturmanın verdiği yorgunluk Sıkınt...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Sezgin']::text[], 8.5, '{"poet":"Yılmaz Sezgin","poet_slug":"yilmaz-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/boynuyogun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güle Güle Bebeğim', 'gule-gule-bebegim-yilmaz-sezgin-ul5o8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Haydı git güzelim

Yolun açık olsun

Beni terk ettin demeyeceğim 

Sana hiç sitem etmeyeceğim

Yaşadıklarımız mazide kaldı artık

Hayal edebildiğim kadar 

Hatırlayabildiklerimle beraberim şimdi 

Üç beş yaprakta olsa

Anlamı vardı bir şeylerin

Öyle ki

Kalbime gömdüğüm duyguların

Ağırlığı altında ezildim yıllarca

Ne uğruna

Elbette ki senin uğruna

Sevgimiz uğruna

Taşıyamayacağın beraberliğimiz adına

Seni yıllarca 

Peşimden sürüyemeyeceğimin farkındayım

Belki de ayrı dünyaların insanıyız

Kim bilir

Demek ki yalnızca duygular yetmiyormuş

Pembe dünyalar için

Beklentilerde önemli

Sonra eş dost 

Konu komşu 

Ne dersin

Farkında olmadan

Bir uçurum kenarına mı

İtildik beraberce

Kala kala 

Karşılıklı içilen iki bardak  soğuk su

Birde kuru kuruya bir hoşça kal

Güle güle bebeğim 

Beni aramak istersen 

Sen bilirsin

Ne olursa olsun

Bil ki kalbimin bir yerindesin

                 07.Ekim 1994

                 Saat: 19.00', 'Haydı git güzelim Yolun açık olsun Beni terk ettin demeyeceğim  Sana hiç sitem etmeyeceğim Yaşadıklarımız mazide kaldı artık Hayal edebildiğ...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Sezgin']::text[], 8.5, '{"poet":"Yılmaz Sezgin","poet_slug":"yilmaz-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/gule-gule-bebegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldızlar Ve Sen', 'yildizlar-ve-sen-yilmaz-sezgin-ywfke', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Soğuk bir kış akşamı

Yıldızların tek düze seçilebildiği

Karanlığın karla aydınlandığı gecede

Rüzgarın uğultusuyla

Uçuşan kar tanelerini seyrederken

Yalnızlığımla baş başa

Düşüncelere dalıyorum

Çevremdekilere aldırmayacak

Onları duymayacak kadar

Sensizliği böyle paylaşıyorum ancak

Beni kimse anlamıyor

Sende anlamadın

Ne istediğimi, nasıl sevdiğimi

Anlamadın çaresizliğimi

Artan kar fırtınasının etkisi ile

Düşüncelerimden sıyrılırken

Bedenimin hissetmeye başladığı soğukluğu

Ruhumun hissettiği an

Korkuyla ürperiyorum

Hayallerime ulaşabilecek miyim

Diye ürperiyorum 

Seninle yaşayamadığım zamanı

Bundan sonra yaşayabilecek miyim

Diye ürperiyorum

Ürperiyorum çünkü

Sonsuzluğun göbeğine savrulurken

Son kez seninle olabilecek miyim

Biliyorum ki hayır

Yıldızların karla 

Senin hayatla bütünleştiğin gibi

Bende yalnızlığınla bütünleşiyorum

                                      Aralık 1991', 'Soğuk bir kış akşamı Yıldızların tek düze seçilebildiği Karanlığın karla aydınlandığı gecede Rüzgarın uğultusuyla Uçuşan kar tanelerini seyr...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Sezgin']::text[], 8.5, '{"poet":"Yılmaz Sezgin","poet_slug":"yilmaz-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/yildizlar-ve-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmeyi Öğretmediler', 'sevmeyi-ogretmediler-yilmaz-sezgin-08x5g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ve bin bir gece masalları ile uyandı deniz

La Fontaine çevirileri ile uyuduk hepimiz

Kedi ile farenin farkına vardığımızda

Tilkinin kargaya oyununu anladığımızda 

Tüylerimizi ürperten peri hikayeleri 

Meraklandırdı benliğimizi

Karanlık köşelerdeki esrarlı kapılar 

İlgi alanımızın baş tacıydı

Yorulmazdık soru sormaktan 

Paylansak da vazgeçmedik huyumuzdan

Tatil umuduyla son baharda

Kar yağmasını beklerdik yıldız şafağında

Kızlar okulu özlerdi yatağında

Biz tatili özlerdik kitap kapağında

Kışın her taraf beyaza çaldığında

Kar topunu tutamaz bir hale ulaştığımızda

Sobayı tutardık,

Acı  öylesine bir  tat bırakırdı ki avuçlarımızda

Önceleri ideallerimiz vardı uzaya ayak basacak

Fikirlerimiz vardı ülkeyi kurtaracak

Gerçeklik vardı hayallerimizde her nasılsa

Sonra her birimiz dağıldık dört bir yana

Fakülteli olmuştuk ya

Kağıt oynadık sigara dumanı alacasında

İstanbul’u fetheden hükümdarın yaşında

Kendi el yazımızı okuyamadan

Mezun olduk milletin el yazması notlarıyla

Bürokrasiye alışamadan 

İdeallerimiz bitivermişti bir sabah uyandığımızda

Beklentiler edindik avunmak maksadıyla...

Şimdi aşk zamanıdır söylentisiyle

Puslu havalarda tutulduk sevda denen güle 

Bir bakışla başladığını anlatırdı şarkılar 

Defalarca bakıştıksa da açmadı manolyalar

Geleneksel olmayan bir moda tutkusuyla

Romantik olmayan kızlara

Platonik kurlar yaptık umutsuzca

Mavi gözlülerden sonra

Türbanlılarında çattık romansız olanlarına

Biz sevda ararken

Flört denen bir gerçeği öğrettiler bize

Kitap karıştırmaktansa kas çalıştırmayı öğretmediler

Akran çocukları boyumuz kadar olduğu dönemlerde 

Denedik tekvando figürlerini

Biz karanlığı severdik yıldızlar bizi

Gün geldi tuz biber ektik sevdalara

Sevdalar bize göz dikti

Kızılelma, ilk öğrendiğimiz şiirdi 

Gönül sultanı son beklentimizdi

Çok geç de olsa 

Birilerinin takmadığını anladık beklentimizi

Leo Buscaglıa  okuyunca

Bize asıl sevmeyi öğretmediler alacakaranlık kuşağında

Aralık1998', 'Ve bin bir gece masalları ile uyandı deniz La Fontaine çevirileri ile uyuduk hepimiz Kedi ile farenin farkına vardığımızda Tilkinin kargaya ...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Sezgin']::text[], 8.5, '{"poet":"Yılmaz Sezgin","poet_slug":"yilmaz-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/sevmeyi-ogretmediler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yukarı Boynuyoğun', 'yukari-boynuyogun-yilmaz-sezgin-sjemm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gün bitimine doğru

Hiç aydınlanmayan gündüzün üstüne

Karanlık çökmekte

İlacın olmadığı

Telefonun bulunmadığı

Postacının kapısını çalmadığı

Dağların arasında

Sanki gök kubbenin tam ortasında

Güneşin gün yarısında

Bir kaç saatliğine

Yıldızların mehtaplı gecelerde

Öylesine uğradığı bir köy

Evet burası Yukarı Boynuyoğun 















Ve şimdi çaresiz sıkıntılarımın depreştiği

Akşam saatleri yaklaşmakta

Bense hayal perdesinde koşmaktayım

Akşam olmasa

İnsanlar her an bir yerlere koşuştursa

Birileri kavga ederken

Birileri arabulucu olsa

Çocuklar top oynasa

Biri ağıt yakar gibi ağlasa

Bir diğeri avazı çıktığı kadar bağırsa

Sokaklar aydınlıkta canlılarla kaynaşsa

Ve ben hayal perdesinden inebilsem

                                   Temmuz1994', 'Gün bitimine doğru Hiç aydınlanmayan gündüzün üstüne Karanlık çökmekte İlacın olmadığı Telefonun bulunmadığı Postacının kapısını çalmadığı D...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Sezgin']::text[], 8.5, '{"poet":"Yılmaz Sezgin","poet_slug":"yilmaz-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yukari-boynuyogun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çekip Giderim', 'cekip-giderim-yilmaz-sezgin-57ivh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İnsanlar beni neden anlamaz

Neden sırt çevirir, neden dinlemez

Gönül dostlarım bile hicran eylemez

Maziyi unutur, çekip giderim

Ne geldiyse başıma bunlardan geldi

Bunları dinledim, gönüller soldu

Niceleri ise sevdaya güldü

Ateşi söndürür, çekip giderim

Dertliyim yoldaşlar, analar, gardaşlar

Dert kulun, kölen olur sarhoşlar 

Bakarsın bir zaman yanında nahoşlar

Kadehi parçalar, çekip giderim

                                  1996', 'İnsanlar beni neden anlamaz Neden sırt çevirir, neden dinlemez Gönül dostlarım bile hicran eylemez Maziyi unutur, çekip giderim Ne geldiyse ...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Sezgin']::text[], 8.5, '{"poet":"Yılmaz Sezgin","poet_slug":"yilmaz-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/cekip-giderim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bosna Dramı', 'bosna-drami-yilmaz-sezgin-72lqc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nineler el açmış ağlıyor

Vatan uğruna toprağa düşen evlatlarına mı

Aç, susuz yalnızlıklarına mı

Kurtuluş ümidi bulup ta kaybettiklerine mi

Hayır, asla 

Feda olsun vatana bütün yiğitler

Yine nicelerini doğurur  analar

Ağlıyor Bosnalı

Kovuldukları yurtlarına mı

Alçakça bir tavırla süngülendiklerine mi

Topsuz, tüfeksiz, silahsız bırakıldıklarına mı

Hayır, asla

Dirlik, birlik için vücutlarını siper ederek

Kol, bacak, kazma, kürek şükrederek

Var olma gayretindeler

Ağlıyor Bosnalı

İnsan kasaplarının parçaladığı mini mini bebelerine mi

Bütün dünyanın gözleri önünde tecavüze uğrayan

On binlerce kadınına, genç kızına, çocuğuna mı 

Hayır, asla













Bosnalı insanlığa ağlıyor

Sırp canilerinin hayvanlığına

İnsafsız zulüm mekanizmalarına ağlıyor

Batı denen medeniyet fukarası canavar bozuntusuna

İnsanlığı gömen cellatların akıbetine ağlıyor

Kardeş sandığı İslam dünyasının korkaklarına

Halkının haklı tepkisini göz ardı edip

Başka çöplüklerde eşelenen horozlarına ağlıyor

Hala kendi yorganında yılan arayan gafillerine

Öz benliğini dahi savunamayan

Basiretsiz, yüreksiz lider bozuntularına ağlıyor

Bosnalı

İnsanlığın; asiliğine, çirkefliğine, at gözlülüğüne

İkiyüzlülüğüne ve zavallılığına ağlıyor

                                                    1994', 'Nineler el açmış ağlıyor Vatan uğruna toprağa düşen evlatlarına mı Aç, susuz yalnızlıklarına mı Kurtuluş ümidi bulup ta kaybettiklerine mi H...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Sezgin']::text[], 8.5, '{"poet":"Yılmaz Sezgin","poet_slug":"yilmaz-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/bosna-drami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaybettiğim', 'kaybettigim-omer-sevim-1tslz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir sevda yaşamıştım

Yüreğimde iz bırakan

Bir hasret yaşamıştım

Özlemi hiç bitmeyen

Bir dostluk yaşamıştım

Arkadaşlığı bana sevdiren

Birde

Bir ayrılık yaşamıştım

Kaybetme korkusunu

İçimde filizlendiren

Bir hayat yaşadım

Hep savaş halinde

Gel-gitler arasında bocaladım

Kendim bile kendimi

Tanımadığım bir halde

Bocaladım yıllarca

Savaştım yüreğimle

Kendimi tanımak için

Ama ne fayda

Kaybetmişim 

Aklımı, fikrimi, yüreğimi', 'Bir sevda yaşamıştım Yüreğimde iz bırakan Bir hasret yaşamıştım Özlemi hiç bitmeyen Bir dostluk yaşamıştım Arkadaşlığı bana sevdiren Birde B...', ARRAY['Türk Edebiyatı','Şiir','Ömer Sevim']::text[], 8.5, '{"poet":"Ömer Sevim","poet_slug":"omer-sevim","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kaybettigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Paranoya', 'paranoya-yilmaz-sezgin-aocqp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kızdınız mı, 

canınız kavga mı çekiyor, 

bırakıp gidin! 

Gidin bir düğüne katılın.

Gelin bir hastanede, 

yeni doğan bir bebeğin ağlamasını dinleyin.

Huzurevindeki yaşlı birilerine çiçek götürün.

Bir sokak çocuğunu sevindirin, 

giyindirin.

Sonra kabristanı ziyaret edin.

İlla da kavga diyorsanız, 

kafanızda yapın! 

Düşüncelerinizde yakın, yıkın, 

insanlara zülüm edin, kırın, 

savaşın! 

Sonra dönüp bakın, 

arkanızda bıraktığınız harabeye! 

Eğer vicdanınız sızlamazsa, 

eğer pişmanlık duymazsanız; 

hadi, hiç durmayın! 

Hemen bir ruh hekimine koşun! 

                                                             Mart 2002', 'Kızdınız mı,  canınız kavga mı çekiyor,  bırakıp gidin!  Gidin bir düğüne katılın. Gelin bir hastanede,  yeni doğan bir bebeğin ağlamasını d...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Sezgin']::text[], 8.5, '{"poet":"Yılmaz Sezgin","poet_slug":"yilmaz-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/paranoya-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Süleyman''nın Devranı', 'suleyman-nin-devrani-yilmaz-sezgin-4r70i', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yoksullukla mücadele, 

Yolsuzlukla dalavere.

Üç yerine yel aldılar, 

Kerkük Bala, Saddam köle.

Dört nisanda, faylar koptu.

Her tarafa taylar uçtu.

İcraatlar, ranta çoktu.

Vatandaşa saygı yoktu. 

Aydın aklı; “Yay-sat haklı! ”

Şifreliler camda saklı.

Çiftçi eker, tüccar biçer.

Karda çocuk, ağlamaklı.

“Enflasyondur medeniyet! ”

Bu ne çirkef iyi niyet.

Milletindi hakimiyet.

Sözde kaldı samimiyet.

Sivil darbe sokağında! 

Çıtır ekmek, sarıldı ya.

Hop oturup, hop kalktılar.

Mikro canlı, helal kula.

Lirik, epik kavramından.

Sarı gelin avradından.

Deniz bitti, balık koktu.

Süleyman’ın devranından.

                                                      12 Mayıs 2000', 'Yoksullukla mücadele,  Yolsuzlukla dalavere. Üç yerine yel aldılar,  Kerkük Bala, Saddam köle. Dört nisanda, faylar koptu. Her tarafa taylar...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Sezgin']::text[], 8.5, '{"poet":"Yılmaz Sezgin","poet_slug":"yilmaz-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/suleyman-nin-devrani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutsuzum', 'umutsuzum-omer-sevim-4hmky', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu akşam yine hüzün çöktü geceme

Efkarlandım hiç çare bulmadım derdime

Süzüldü dertli dertli gözyaşlarım

Eyvahladım ve ağladım boşa geçen gençliğime

Bu akşam yine hüzün çöktü geceme

Yaşla dolan gözlerim daldı mazime

Sevgi, saygı, güzellik tohumları yerine

Şimdi kin, nefret tohumları ektim yüreğime

Oysa

Eskiden güler gülücükler satardım

Hüzün dolu geceleri bir kenara atardım

Kapkaranlık geceyi sevgi mumumla yakardım

Bitti eridi sevgi mumum

Karanlıkta yapayalnız kaldım

Oysa

Eskiden sevgi dağıtır aşkı anlatırdım

Sevgi ile yatar aşkla uyanırdım her sabah

Oysa

Şimdi o eski ben yokum

Şimdi ben kinle yatar

Nefretle uyanırım her sabah', 'Bu akşam yine hüzün çöktü geceme Efkarlandım hiç çare bulmadım derdime Süzüldü dertli dertli gözyaşlarım Eyvahladım ve ağladım boşa geçen ge...', ARRAY['Türk Edebiyatı','Şiir','Ömer Sevim']::text[], 8.5, '{"poet":"Ömer Sevim","poet_slug":"omer-sevim","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/umutsuzum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Azrail''im', 'azrail-im-omer-sevim-04caz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ölüm sessizliğine bürünmüş gece

Saatin akrep ve yelkovanıda eşlik etmekte

Tık yok

Zaman durmuş, ben durmuşum

Yatağımdayım

Sanki azrail''i bekliyorum

Yada

Azrail beni beklemekte

Günahlarımın cezasını yaşarken çekiyorum

Titriyor bedenim şuursuzca

Ruhum çıkmak için boğazıma dayandı

Azrail''i görünce artık irkilmiyorum

Gel artık nerdesin Azrail''im

Gelde

Kurtar beni bu azaptan', 'Ölüm sessizliğine bürünmüş gece Saatin akrep ve yelkovanıda eşlik etmekte Tık yok Zaman durmuş, ben durmuşum Yatağımdayım Sanki azrail''i bek...', ARRAY['Türk Edebiyatı','Şiir','Ömer Sevim']::text[], 8.5, '{"poet":"Ömer Sevim","poet_slug":"omer-sevim","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/azrail-im-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özleniliyorsun', 'ozleniliyorsun-omer-sevim-kojet', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güneş batmak üzere

Ufuk kıpkızıl bi renk

Bir gün daha yaklaştım ecele

Senin haberini aldığımda

Ölüm haberini aldığımda

Bedenimden bir parça koptu

Ağlayamadım

Hıçkırıklar düğümlendi boğazımda

Sen sanmaki unutulacaksın be dostum

Sana söz

Yürekte olacaksın

Kalpte taşınacaksın

Her gün, her yerde ve

                            Her daima

(bir dostun ardından)', 'Güneş batmak üzere Ufuk kıpkızıl bi renk Bir gün daha yaklaştım ecele Senin haberini aldığımda Ölüm haberini aldığımda Bedenimden bir parça ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Sevim']::text[], 8.5, '{"poet":"Ömer Sevim","poet_slug":"omer-sevim","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ozleniliyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dışa Dönüş', 'disa-donus-naime-erlacin-g9bdc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'dışarısı çağırıyor Mayıs sabahı

erik ağacıyla randevum var

minik serçeyle

-hani bülbülce bilmez demiştim ya- 

o işte! 

güneş çağırıyor 

buz eritiyorum yürekte

cemreler görmüştüm

yaprağı uzaktan 

ve çiçekler

çan sesleriyle dans ediyorum şimdi

ışık çağırıyor

sen köşede dur ey düşünce! 

bekle

dönerim elbet

güzellik karmaya gidiyorum karmaşadan

hatırla ikizler kadınıydım ben 

içe dönük 

dışa dönük

hem hüzünlü hem çılgın

hem küskün hem âşık

biraz zırdeliyim anla

öyleyim işte

bekle Mayıs 

geliyorum! 

deli gönül havalandı bir kez

tutulmaz gayrı

odalar kasvetli, gönlüme dar 

büyüyor yürek

çatırdıyor kabuk 

dışa dönüş bu

toparlandım 

gidiyorum

kanıma giriyor Mayıs 

(18 Mayıs 2003)', 'dışarısı çağırıyor Mayıs sabahı erik ağacıyla randevum var minik serçeyle -hani bülbülce bilmez demiştim ya-  o işte!  güneş çağırıyor  buz ...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/disa-donus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haram Oldu....', 'haram-oldu-seckin-i-nceel-hlctp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerimde özleminin yaşı, 

Ellerimde hasretin prangası, 

Kalbimde ''GÜLAY''''ın sevdası, 

Esen rüzgarda ''GÜLAY''''ın nefesi, 

Doğan güneşlerde ''GÜLAY''''ın çehresi, 

Geçtiğim bütün yollarda ''GÜLAY''''ın izi, 

İçtiğim her sigarada ''GÜLAY''''ın zehiri, 

Gökyüzündeki yıldızlarda ''GÜLAY''''ın parlaklığı, 

Elime aldığım bütün kitaplarda ''GÜLAY''''ın adı, 

Bitsin artık bu ''GÜLAY'' hastalığı, 

Bitiyorum artık, eriyorum ''GÜLAY'' diye diye...

Ne zaman biter bu ''GÜLAY'' sevdası, 

Ne zaman biter bu ''GÜLAY'' sayfası, 

İsyan eder oldum, 

Dayanacak, unutacak gücüm yok, 

Haram oldu artık herşey, 

Gözlerimdeki yaş...

Ellerimdeki pranga...

Kalbimdeki sevda...

Serinleten rüzgar...

Hergün doğan güneş...

Geçtiğim bütün yollar...

İçtiğim sigara...

O çok sevdiğim yıldızlar...

Elimdeki bütün kitaplar...

İsyan etmek, dayanmak, unutmak haram oldu, 

Hepsi artık haram oldu, 

Artık ''GÜLAY''''da haram....

      ^^YAŞAMAKTA^^', 'Gözlerimde özleminin yaşı,  Ellerimde hasretin prangası,  Kalbimde ''GÜLAY''''ın sevdası,  Esen rüzgarda ''GÜLAY''''ın nefesi,  Doğan güneşlerde ''...', ARRAY['Türk Edebiyatı','Şiir','Seckin İnceel']::text[], 8.5, '{"poet":"Seckin İnceel","poet_slug":"seckin-i-nceel","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/haram-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Severek Ayrılanlar Kervanı', 'severek-ayrilanlar-kervani-ensar-aktas-jr3wy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne de masum hayallerimiz vardı seninle

Tertemiz duygularımız, ölümüne sevgimiz

Kimse ayıramaz sanırdık, sevenler hep elele

Meğer Felek ile işbirliğindeymiş kaderimiz

Ne yaptıysak olmadı, kavuşturmuyor engeller

Daha ne kadar şelale gibi çağlayacak bu gözler

Çöl olsa geçerdik engeller, dağ olsa delerdik

Bizi ayıran yollar da değil, yıkılası köhne töreler

Hadi bırakalım bu aşkı burada tertemiz kalsın

Son sayfası hiç yazılmamış bir aşk romanı gibi

Mademki bir çift yüzüğe yazdıramadık isimlerimizi 

Bırakalım da şu cevizin gövdesinde kazılı kalsın

Daha başlamadan biten bir aşk hikayesi gibi

Bizde katılalım severek ayrılanlar kervanına

Belki bir gün kesişir yollarımız öteki dünyada

Rotterdam,18-05-2003', 'Ne de masum hayallerimiz vardı seninle Tertemiz duygularımız, ölümüne sevgimiz Kimse ayıramaz sanırdık, sevenler hep elele Meğer Felek ile i...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/severek-ayrilanlar-kervani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadın Milleti', 'kadin-milleti-ensar-aktas-5jojg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çözemedim şu kadın milletini

Bir türlü çözülmüyor

Her şeyi yalan her şeyi gizemli

İçi dışı hep sırlarla dolu

Ne sevmesini biliyor nede sevilmesini

Ne kıymet biliyor nede veriyor

Ne sözünde duruyor nede dinliyor

Sağ gösterip hep sol vuruyor

Elinden geleni ardına koymuyor

Gerekirse dişiliğini kullanıp

Seni kendisine körkütük aşık ediyor

Seviyor, kul köle oluyorsun

Bu kez de merhamet etmiyor, 

Sessiz sedasız çekip gidiyor

Melek mi şeytan mı belli olmuyor

Ne istediğini bilmiyor şu kadın milleti

Pes doğrusu artık aklım almıyor

Ne yaptıysam olmadı, olmuyor

Bir türlü çözülmüyor, çözemiyorum

Bilen varsa n’olur bana da söylesin 

Kulu kölesi olurum, erkek sözü veriyorum

Rotterdam,19.08.2002', 'Çözemedim şu kadın milletini Bir türlü çözülmüyor Her şeyi yalan her şeyi gizemli İçi dışı hep sırlarla dolu Ne sevmesini biliyor nede sevil...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kadin-milleti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanma Sakın!', 'sanma-sakin-fatih-malik-mimaroglu-7eo5b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşk mıdır gönül ilacı? 

Gözler mi, sözler mi yalancı? 

Elim elinden davacı

Neden diye sorma sakın! 

Eğer bir gün unutursan

Asıl ölüm bil ki o an

Acı tatlı hep beni an

Bilmem deyip geçme sakın! 

Bitir artık hasreti gel

Esti geçti ılık bir yel

Kaldır beni, uzat bir el

Olmaz deyip küsme sakın

Er geç duyarsın sesimi

En son kalan nefesimi

Kalbim bir kuş kafesi mi? 

Kilit vurup uçma sakın! 

Aşkın  dolaşır  kanımda

Ayrıklık ateşi bağrımda

Ömür boyu kal yanımda

Gitme desem kızma sakın! 

Çiçek bile ölür susuz

Ömrüm sensiz hep huzursuz

Gece de ne, hep uykusuz

Kaldım desem şaşma sakın! 

Gelme artık, görme beni

Sildim madem ben de seni

Deli gibi sevdim oysa seni

Pişman oldum sanma sakın', 'Aşk mıdır gönül ilacı?  Gözler mi, sözler mi yalancı?  Elim elinden davacı Neden diye sorma sakın!  Eğer bir gün unutursan Asıl ölüm bil ki ...', ARRAY['Türk Edebiyatı','Şiir','Fatih Malik Mimaroğlu']::text[], 8.5, '{"poet":"Fatih Malik Mimaroğlu","poet_slug":"fatih-malik-mimaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sanma-sakin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimdeki Bir Ses Diyor ki +', 'i-cimdeki-bir-ses-diyor-ki-bayram-tunca-ism25', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gönül diyor, al başını git bu diyardan

Belki de kurtulmuş olursun bu yardan

Anlamıyor bu yar ne halden ne dilden

Çekmedim ben ondan çektiğimi elden

Aah ben neler çektim o muhacir gelinden

Ben nasıl kurtulam onun elinden dilinden

Anlamıyor ki o yar ne halden ne de dilden

Çekmedim ki ondan çektiğim kadar elden

Denemediğim başka, hiçbir metot kalmadı

Düştüm kuvvetten artık eski mecal kalmadı

Her nedense, onunla fıtratlarımız uyuşmadı

Feryadım dağdan gayrisinde yankı bulmadı

Değmedi değmedi bu çileye bu aşk değmedi

Eğmedi eğmedi, şair kimseye boyun eğmedi

Yermedi yermedi, bir başkası böyle yermedi

Bu aşk, bana hayatımda hiç tat tuz vermedi

Yerilmekten/yere serilmekten, beter oldum

Sahralarda/meralarda deli gibi gezer oldum

Ben bu âlemde tatlı canımdan bezer oldum

Sanki sırtından vurulan Sezer misali oldum

18.05.2003-08:05

NOT:

Deli gömleği giydirildiğimde dilime gelenler

Ah şu yalan dünyada garip başıma gelenler

İş işten geçince, çook oldu nasihat edenler

Haktan bulsunlar beni bu hallere getirenlar

Aşk Ateşten Gömlek', 'Gönül diyor, al başını git bu diyardan Belki de kurtulmuş olursun bu yardan Anlamıyor bu yar ne halden ne dilden Çekmedim ben ondan çektiğim...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/icimdeki-bir-ses-diyor-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz Şimdi Koca Çocuklarız', 'biz-simdi-koca-cocuklariz-ensar-aktas-0rp28', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Biz eskiden annelerimizin küçük koçlarıydık

Şimdi ise eşlerimizin büyük çocuklarıyız

Eskiden kısa donla gezer bilya oynardık

Şimdi kravat takar savaş oyunları oynarız

Kimimiz katil oluruz namus uğruna

Kimimiz namus alır satarız para uğruna

Kimimiz parayla oynarız, taparız ona

Kimimiz ölürüz bir lokma uğruna

Kimimiz severiz, ne ümitlerle bekleriz

Kimimiz alırız sevdiğimizi sonra döveriz

Kimimiz dışarda kazak, evde kılıbık

Kimimiz atar tutar kendimizi överiz

Kimimiz eş değil babadır sanki eşine

Kimimiz aksine çocuktur sanki eşine

Kimimiz gerçekten sever taparız ama

Kimimiz dönektir, nasıl gelirse işine

Kimimiz yalancıyız verdiğimiz sözde durmayız

Kimimiz inatçıyız hemde vurdumduymazız

Kimimiz kaygısız, aşka, sevgiye kayıtsız kalırız 

Kimimiz cahiliz, halden, laftan anlamayız

Kimimiz aydınız, entellektüel takılırız

Kimimiz iki yüzlü bir maske takınırız

Kimimiz çoçuklarımızın rızkı için çalışırız

Kimimiz dünyayı çoçukların başına yıkarız

Kimimiz öğretmen, doktor, vesaire

Kimimiz bakan, başbakan, vesaire

Kimimiz haydut, eşkiya, vesaire

Kimimiz vesaire, vesaire, vesaire

Düşünüp durdum haftalarca, sabahlara dek

Dünyada ne kadar pis iş varsa arkasında bir erkek

Nedir şu kadınların bizden çektiği bilmem

Bir suçları varsa o da bizi dünyaya getirmek

Çekip alırız cenneti annelerin ayakları altından ama

Bilmeyiz ahirette bizim yerimiz neresidir acaba

Biz asarız, keseriz herşey mübahtır bu dünyada

Canımızı alın, ama dokunmayın şu gururumuza

Rotterdam,07.09.2002', 'Biz eskiden annelerimizin küçük koçlarıydık Şimdi ise eşlerimizin büyük çocuklarıyız Eskiden kısa donla gezer bilya oynardık Şimdi kravat ta...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/biz-simdi-koca-cocuklariz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorum İşte…', 'gidiyorum-i-ste-ensar-aktas-jdnb6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gidiyorum işte nerede başladı bu yolculuk bilmiyorum, beşikte mi

Gidiyorum işte nerede biter bu yolculuk bilmiyorum, mezarda mı

Gidiyorum işte damarımda dolaşan iki damla şey nedir bilmiyorum, sevgin mi

Gidiyorum işte yanağımda sararan iki damla şey nedir bilmiyorum, nefretin mi

Gidiyorum işte yoldaşım diye yanıma aldığım şey nedir bilmiyorum, şefkatin mi

Gidiyorum işte arkamdan bozbulanık seller gibi çağlayan şey nedir bilmiyorum, gözlerin mi

Gidiyorum işte seni gömdüm kalbime, kalbimi ise düşlerime, hayallerime

Gidiyorum işte bu yolculuk sende başladı yine sende biter mi bilmiyorum, nereye mi

Onu da bilmiyorum, gidiyorum işte…

Rotterdam,21.08.2002', 'Gidiyorum işte nerede başladı bu yolculuk bilmiyorum, beşikte mi Gidiyorum işte nerede biter bu yolculuk bilmiyorum, mezarda mı Gidiyorum iş...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gidiyorum-iste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kan Çekiyor', 'kan-cekiyor-ensar-aktas-ob32y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kaçmakta fayda etmiyor bize, çekip gitmekte

Küfürlerle kavgalar da yetmiyor ayırmaya ikimizi

Dillerimiz çek git diyor, sevmiyorum artık seni

Ellerimiz bırakmıyor, birbirine kelepçelenmiş sanki

Damarlarım uyuşuyor, sanki kan çekilmekte

Hangi eller yazmışsa, birlikte yazmış kaderimizi

Zaman aciz kalıyor, mesafeler de ayıramıyor bizi

İçtiğimiz su ayrı gitmiyor, kan çekiyor sanki ikimizi

Rotterdam,26.08.2002', 'Kaçmakta fayda etmiyor bize, çekip gitmekte Küfürlerle kavgalar da yetmiyor ayırmaya ikimizi Dillerimiz çek git diyor, sevmiyorum artık seni...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kan-cekiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalk Gidelim Aşkım', 'kalk-gidelim-askim-ensar-aktas-eiy12', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kalk gidelim aşkım bu diyarlardan

Bu diyarlar da bize göre değil

Vazgeç bu hayin sevdalardan

Bu sevdalar da bize göre değil

Ben ne altın kafesler bulurum sana

Bu saraylar da bize göre değil

Bu sessizlik hayra alamet değil

Rotterdam,25.08.2002', 'Kalk gidelim aşkım bu diyarlardan Bu diyarlar da bize göre değil Vazgeç bu hayin sevdalardan Bu sevdalar da bize göre değil Ben ne altın kaf...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kalk-gidelim-askim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahne-i Ömrümden Nefs-i Emmareye Hitabım', 'sahne-i-omrumden-nefs-i-emmareye-hitabim-neyzen-tevfik-y9ddp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Âlemin bağ-zârını...eyim

Sünbül ü verd ü nârını...eyim

Andelib-i nizârını...eyim

Hâsılı nev-baharını...eyim! 

Bana yoktur lüzumu gülşeninin, 

Şeb-i tarîk ü rûz-ı rûşeninin

Ne gulâmının ne de zenninin

Hepsinin tâ mezarını...eyim! 

Ağlamam ben, ben erkeğim erkek, 

Hayli güçtür bana cefâ etmek, 

Minnet etmem bu ömre de felek, 

Atını al, tımarını...eyim! 

Güççedir bu fakiri aldatmak, 

Yüzdürüp sonra kündeden atmak, 

Gözünü aç da sen bana bir bak, 

Ben senin i''tibarını...eyim! 

Saki-i mâh-rûyına...ayım, 

Gülünün reng ü bûyuna...ayım, 

Mutrîbin hâyâ-hûyuna...ayım, 

Sâgar-ı neşvedârını...eyim! 

Yok sâfâsı hezâr-ı dem-gerinin, 

Gül-sitanda şükûfe-i terinin, 

Bezm-i sahbâ-yı rûh-perverinin

Neşvesiyle hümârını...eyim! 

Feleğin uğradımsa vartasına, 

S..ayım ağzının ta ortasına, 

Bunu yazsın cihan da hartasına, 

Kıta''at ü bihârını...eyim', 'Âlemin bağ-zârını...eyim Sünbül ü verd ü nârını...eyim Andelib-i nizârını...eyim Hâsılı nev-baharını...eyim!  Bana yoktur lüzumu gülşeninin,...', ARRAY['Türk Edebiyatı','Şiir','Neyzen Tevfik']::text[], 8.5, '{"poet":"Neyzen Tevfik","poet_slug":"neyzen-tevfik","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sahne-i-omrumden-nefs-i-emmareye-hitabim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alıştırdılar', 'alistirdilar-erdinc-asik-u1w6v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güneşin ışığına değil

Gecenin karanlığına

Menfaatsiz yaşamaya değil

Dostların vefasızlığına 

Alıştırdılar

Sevinçten gülmeye değil

Çaresizlikten ağlamaya

Hayırsızları silip atmaya değil

Göz yaşlarımı silmeye

Alıştırdılar

Huzurlu yaşamaya değil

Yaşarken ölmeye

Dünyanın fani olmasına değil

Umutların fani olmasına

Alıştırdılar

İnsan gibi yürümeye değil

Sürünerek ilerlemeye

Mutluluğu yakalamaya değil

Sürünerek yetişilmeyeceğine

Alıştırdılar

Derdimi söylemeye değil

Dermanını bulamamaya

Oturupta dertleşmeye değil

Dertleşecek insanı bulamamaya

Alıştırdılar', 'Güneşin ışığına değil Gecenin karanlığına Menfaatsiz yaşamaya değil Dostların vefasızlığına  Alıştırdılar Sevinçten gülmeye değil Çaresizlik...', ARRAY['Türk Edebiyatı','Şiir','Erdinç Aşık']::text[], 8.5, '{"poet":"Erdinç Aşık","poet_slug":"erdinc-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/alistirdilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Bir Yara', 'eski-bir-yara-suleyman-yildirim-78prb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ölümün müreccah olup kader olmadığı anlar için...

mahzun sukutuma inat bu muhteris gülüşlerde

sanma aldanıp da sakın eskimeyen bir şeyler var

hala avutmayan beni uğradığın o düşlerde

sende sınırsız pişmanlık, bende ölüm korkusu var.

sorumsuzca yaşanılmış ömürlerin sermayesi

nice bin yıl geçtiyse de aynı Adem  hikayesi

her şeyi unutsam bile ihanetin azar azar

yaşı akarken göğsüme bir eski yaradır azar.', 'ölümün müreccah olup kader olmadığı anlar için... mahzun sukutuma inat bu muhteris gülüşlerde sanma aldanıp da sakın eskimeyen bir şeyler va...', ARRAY['Türk Edebiyatı','Şiir','süleyman yıldırım']::text[], 8.5, '{"poet":"süleyman yıldırım","poet_slug":"suleyman-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/eski-bir-yara-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deneme miydim ki', 'deneme-miydim-ki-sule-aydemir-pj9br', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'deneme yanılma hani

gariptir söz konusuyum

kışın ortasında 

çiçekler açmış ya

saflığında yüreğim

daha ne kadar denemelere

gider gelirim kim bilir

dener miyim denenirken 

belki

onca gidenler olur ki gönlümden

acısına adaklar adarım bazen

dumanı tüter oysa sevginin

hazanlarda son düşen yapraktır 

düşürür müyüm çağırır mıyım 

topraktır ya belki

gözleri üzüm ya

anlık şevk-mest uğruna 

şaraplık

bozar mıyım

yıkanırım ya akar sularda

bekler miyim aynı akar suda 

aynı yerde yıkanmayı

bilirim ki

istersem de bulurum çaresini

geçerim akarın gidecegi son yere

hem bil ki ondan çokta önce

bil aynı akar yine akar 

bil ki küçümseme

gökten düşüyor ya üç elma

demem ki 

elma ya kim elma demiş

bende adı armut ya

papatyalar sevgi çiçeği severim ya

bil ki can aldı

değişkenim duygu kaosunda

kes yargımı kesebilirsen

nedeni senin gibi düşünmeyeninden

basit değil ya sevgi

hani esas kız 

esas oğlan gibi

belki ben de esas kız olup 

bulurum şu esas oğlanı

kim bilir

denemede deneyim harcımdır 

harcamak değeri değerde

biçmek belki en pahalıya

ucuzunda sevgi

deneme yanılma ya hani

sevgiyi bilenim 

diyenlere mi vermeli

biliyorum ki kendimce

sadece hissetmeli

basitce sevmeli', 'deneme yanılma hani gariptir söz konusuyum kışın ortasında  çiçekler açmış ya saflığında yüreğim daha ne kadar denemelere gider gelirim kim ...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/deneme-miydim-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pencere', 'pencere-askin-gungor-oiic0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu pencerenin gökyüzü yok anne.

Bu pencerenin binaları var.

Bu pencereyi istemiyorum anne.

Bana ''gökyüzülü'' pencere al! 

(01.10.1993)', 'Bu pencerenin gökyüzü yok anne. Bu pencerenin binaları var. Bu pencereyi istemiyorum anne. Bana ''gökyüzülü'' pencere al!  (01.10.1993)...', ARRAY['Türk Edebiyatı','Şiir','Aşkın Güngör']::text[], 8.5, '{"poet":"Aşkın Güngör","poet_slug":"askin-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/pencere-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle Bir Hikaye', 'oyle-bir-hikaye-askin-gungor-98z6s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Biraz sonra eriyeceğim.

Bu katılıktan eser kalmayacak, biliyorum.

Biliyorum bu dumanı tüten

kırmızı cehennem

bedenimi yutuverecek.

Ben hayatımın en yalnızlık karşıtı yerinde

ve benim gibi yüzlercesinin

arasındayken...

Biraz sonra cellatım beni

uzatıverip de kocaman ellerini

tutup

bu sıcak cehenneme atacak.

Ve uzanıp

varlığımı erteleyen cehennemin

kıyısından bir yudumla

tadıma bakacak.

Az bulursa eğer erimemle

dumanlı cehenneme bulanan tadı, 

tutup bir başka arkadaşımı, 

yokedişlerini hızlandıracak.

Ve saydam duvarlar ardındaki cehennemi

kıvamını buluncaya değin

elindeki metalle karıştıracak.

Ah gidi, kavanoz dipli dünya! 

ne vardı sanki

bir kaç günlük hayatta

kesme şeker olacak! 

(26.11.1993)', 'Biraz sonra eriyeceğim. Bu katılıktan eser kalmayacak, biliyorum. Biliyorum bu dumanı tüten kırmızı cehennem bedenimi yutuverecek. Ben hayat...', ARRAY['Türk Edebiyatı','Şiir','Aşkın Güngör']::text[], 8.5, '{"poet":"Aşkın Güngör","poet_slug":"askin-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/oyle-bir-hikaye-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Demedim ki', 'demedim-ki-sule-aydemir-6krwu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'hani dedim ya sana

düşün algılama adına

sordum akabinde

var ki bir sarı

nasıl olacak kıyası

sen düşündün

ayçiçeği

ben düşündüm

limoni', 'hani dedim ya sana düşün algılama adına sordum akabinde var ki bir sarı nasıl olacak kıyası sen düşündün ayçiçeği ben düşündüm limoni...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/demedim-ki-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Demedim ki -2', 'demedim-ki-2-sule-aydemir-qvy1u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'hani sordun ya kimsin

dedim ya sıradan

ayrım; farkındalığım

sıradanlıktan çıkışım

sıradanlığımın farkındalığım', 'hani sordun ya kimsin dedim ya sıradan ayrım; farkındalığım sıradanlıktan çıkışım sıradanlığımın farkındalığım...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/demedim-ki-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-i-smail-ugur-82x46', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bana dünyanın hazinelerini verseler 

Senden asla vaz geçmeyecem

Elime dünyayı verseler 

sevgimden asla bir şey vermeyecem

seni arar bu yaşlı gözlerim

nerdesin ey güzel sevigilim

aşkın beni kül eyledi

seni arar bu cansız bedenim', 'Bana dünyanın hazinelerini verseler  Senden asla vaz geçmeyecem Elime dünyayı verseler  sevgimden asla bir şey vermeyecem seni arar bu yaşlı...', ARRAY['Türk Edebiyatı','Şiir','İsmail Ugur']::text[], 8.5, '{"poet":"İsmail Ugur","poet_slug":"i-smail-ugur","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ask-154-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herşey Bir Rüya', 'hersey-bir-ruya-sadik-orel-vev3h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sende benim gibi düşünüyorsun, biliyorum.

Sende seni sevdigim kadar sevdin beni birzamanlar. 

Sende benim uyuyamadıgım gibi uyuyamıyorsun geceleri.

Aklına yaşadıklarımız geliyor.

İşte o an gözünden iki damla yaş akıyor yatagına...

Haykırmak istiyorsun seni seviyorum diye...

Kalkıp yatagından bana koşmak istiyorsun...

Sarılıp cılgınlar gibi sevişmek istiyorsun benimle.

İşte sabah oldu...

Dünyanın en güzel uykusundan uyandım.

Rüyalarımda bile bunları düşünmek yetiyor bana

Ben senin yoklugunda seviyorum seni...', 'Sende benim gibi düşünüyorsun, biliyorum. Sende seni sevdigim kadar sevdin beni birzamanlar.  Sende benim uyuyamadıgım gibi uyuyamıyorsun ge...', ARRAY['Türk Edebiyatı','Şiir','Sadık Orel']::text[], 8.5, '{"poet":"Sadık Orel","poet_slug":"sadik-orel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hersey-bir-ruya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GENÇLERİMİZE', 'gencleri-mi-ze-ahmet-kurt-l4map', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Herkese verecek sevgin olmalı, 

Aç yüreğini kapama yavrum.

Gönüle muhabbet nuru dolmalı, 

Aç yüreğini kapama yavrum.

Kinden, husumetten arınsın yürek, 

Aracı koymayın ulaşın direk, 

Kaynaşın tek yumruk ve tek bilek

Aç yüreğini kapama yavrum.

Çirkinliği örtün, güzellik bulun, 

Güllerle donatın açılsın yolun, 

Fikir girdabında aranır olun, 

Aç yüreğini kapama yavrum.

Size bağlıyorum, gönül gözümü, 

Kulak verip dinle lütfen sözümü, 

Birlikte bulursun ancak çözümü, 

Aç yüreğini kapama yavrum.

Hoşgörü ve sevgi hayat kapısı, 

Uzat kollarını, tutsun birisi, 

Bu yoldan ayrılma yalan gerisi, 

Aç yüreğini kapama yavrum.

Geniş ol kimseye kin duyma sakın, 

Gönülden gönüle başlatın akın, 

Gözlerin içine şefkatle bakın, 

Aç yüreğini kapama yavrum.

Kurdoğlu sizlerden gülüşler bekler, 

Sizin olsun bütün iyi dilekler, 

Başınızda türlü türlü çiçekler, 

Aç yüreğini kapama yavrum.', 'Herkese verecek sevgin olmalı,  Aç yüreğini kapama yavrum. Gönüle muhabbet nuru dolmalı,  Aç yüreğini kapama yavrum. Kinden, husumetten arın...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kurt']::text[], 8.5, '{"poet":"Ahmet Kurt","poet_slug":"ahmet-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/genclerimize-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmeyeceğim', 'sevmeyecegim-sair-desperado-andmz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir daha sevmeyeceğim 

Sevip de terk edilmeyeceğim

Ağlamayacağım sabahlara kadar

Islanmayacağım kimse için sırılsıklam 

Şiirler yazmayacağım okunmayan

Bir daha sevmeyeceğim deli gibi 

Ve kimse için ağlamayacağım gecelerce

Son olsun bu gece 

Bir daha bakmayacağım 

Mavi gözlere 

Son kez bakacağım resmine bu gece

By  Desperado', 'Bir daha sevmeyeceğim  Sevip de terk edilmeyeceğim Ağlamayacağım sabahlara kadar Islanmayacağım kimse için sırılsıklam  Şiirler yazmayacağım...', ARRAY['Türk Edebiyatı','Şiir','Şair Desperado']::text[], 8.5, '{"poet":"Şair Desperado","poet_slug":"sair-desperado","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevmeyecegim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayaz', 'ayaz-sair-desperado-q7k8w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'SEN ve İSTANBL

Yine yağmur yağıyor İstanbul ‘a

Sanki ağlıyor İstanbul benim gibi, 

Sanki İstanbul da sevmiş seni

Sevmiş ve terkedilmiş benim gibi

Sen gittiğin den beri 

İstanbul daha bi karanlık

Sanki İstanbul da sevdiğini kaybetmiş 

benim gibi

Günler daha kısa sen gittiğinden beri

 İstanbul da kahroluyor sensiz günlere

Benim gibi

Ve geceleri ayaz İstanbul 

Sensiz üşüyor benim gibi

Kapkaranlık bu gecede İstanbul

Belli ki yasta yine 

Ağlıyor İstanbul

By Desperado', 'SEN ve İSTANBL Yine yağmur yağıyor İstanbul ‘a Sanki ağlıyor İstanbul benim gibi,  Sanki İstanbul da sevmiş seni Sevmiş ve terkedilmiş benim...', ARRAY['Türk Edebiyatı','Şiir','Şair Desperado']::text[], 8.5, '{"poet":"Şair Desperado","poet_slug":"sair-desperado","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ayaz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'El Sallayan Olsaydı', 'el-sallayan-olsaydi-yusuf-gencal-an2vp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hırçın

Asi ve karanlık                             

Okyanuslarda

Yanan fenerlerin

Sahillerde el sallayanın

Seni bekleyenin

Olsaydı

Olsaydı candan

Bu kadar yalnız 

Olmazdın, olmaz.

              21/07/1993', 'Hırçın Asi ve karanlık                              Okyanuslarda Yanan fenerlerin Sahillerde el sallayanın Seni bekleyenin Olsaydı Olsaydı c...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Gençal']::text[], 8.5, '{"poet":"Yusuf Gençal","poet_slug":"yusuf-gencal","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/el-sallayan-olsaydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Çağırır Koynuna Seni', 'cagirir-koynuna-seni-yusuf-gencal-uvkef', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tam ortasında okyanusun

Homurdanarak köpürür sular

Metrelerce dalgalarını göstererek

Çağırır koynuna seni

Sen ise sevdiklerini

06.07.1997 k', 'Tam ortasında okyanusun Homurdanarak köpürür sular Metrelerce dalgalarını göstererek Çağırır koynuna seni Sen ise sevdiklerini 06.07.1997 k...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Gençal']::text[], 8.5, '{"poet":"Yusuf Gençal","poet_slug":"yusuf-gencal","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/cagirir-koynuna-seni-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Gün O Yerde', 'o-gun-o-yerde-alaettin-isik-tiivd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sessiz bir ağacın altında, 

Sen ve ben sadece ikimiz, 

Gözlerine baktığımda, 

İçimizden akıyor sevgimiz.

Ellerin ellerimde, 

Gözlerin gözlerimde, 

Sarılıp sıkıca öptüğümde, 

Sanki uçuyordum göklere.

Bu bir rüya desem rüya değil, 

Olsa da uyanmak elde değil

Her anı bir eksikliğin, 

Özlemin, aşkın sadeliğin, 

Esiriydik muhteşemliğin.

İçimden sana akıyor bir şeyler, 

Senden gelense ılık nefesler

O yerde o gün bir bambaşka, 

Her şey bahar, çiçek, kuş gibi.

Doyamadım böylesi temiz aşka, 

Göremedim böyle hiç beni, 

Buram buram sırılsıklam

Olmuştuk her ikimizde.

Neden çabucak oluyor akşam, 

Kalmasın hevesler içimizde

Ama bilirim ne gece ne gündüz, 

Yaşayamayız hiç birbirimizsiz.

Gel sevdiğim yine gel, 

Buluşalım o yerde.', 'Sessiz bir ağacın altında,  Sen ve ben sadece ikimiz,  Gözlerine baktığımda,  İçimizden akıyor sevgimiz. Ellerin ellerimde,  Gözlerin gözler...', ARRAY['Türk Edebiyatı','Şiir','Alaettin Işık']::text[], 8.5, '{"poet":"Alaettin Işık","poet_slug":"alaettin-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/o-gun-o-yerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Hasret', 'sana-hasret-alaettin-isik-5rj1s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mutluluk denizinde pupa yelken, 

Sensiz sabahlarım oluyor erken, 

Ne gece ne de gündüz farketmez, 

Huzura dalarım seni anarken.

Bir ince sis dağılıyordu ufukta, 

Sana hasret duyuyorum şafakta, 

Sayılı günler çabucak geçer

Buluşacağız yine bir limanda.

Seslerimiz birbirine karışacak, 

Gözlerimiz inatla aranacak, 

Ellerimiz eşleşmeye niyetli, 

Bir gün orada,  o yerde ancak.', 'Mutluluk denizinde pupa yelken,  Sensiz sabahlarım oluyor erken,  Ne gece ne de gündüz farketmez,  Huzura dalarım seni anarken. Bir ince sis...', ARRAY['Türk Edebiyatı','Şiir','Alaettin Işık']::text[], 8.5, '{"poet":"Alaettin Işık","poet_slug":"alaettin-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sana-hasret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuklarım', 'cocuklarim-yusuf-gencal-qscto', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir gün bitecek,

Azgın dalgalarıyla,

Boğuştuğum, 

Bu okyanus.

Dönüp geleceğim, 

Kalleş sulara, gömeceğim,

Hasretlerin tümünü,

Valizim elimde, 

Öyle durup, 

Bakacağım, gözlerinize. 

Çocuklarım,

Sarılmam, sımsıkı olacak,

Gözlerim,güleçek kokunuzdan...

 24/08/1997', 'Bir gün bitecek, Azgın dalgalarıyla, Boğuştuğum,  Bu okyanus. Dönüp geleceğim,  Kalleş sulara, gömeceğim, Hasretlerin tümünü, Valizim elimde...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Gençal']::text[], 8.5, '{"poet":"Yusuf Gençal","poet_slug":"yusuf-gencal","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/cocuklarim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşlerim Yansıyor', 'duslerim-yansiyor-alaettin-isik-uvniz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yürüyorken sessizce, 

Başın eğik önünde

Bir ses gelir içinden, 

Hadi konuş

Mırıldanıyordun hani, 

Biraz önce, 

Neden şimdi sessizlik

Neden bu susuş.

Sen miydin, 

İçimde akan

Sıcak sıcak, 

Ya önümdeki

Bir çift ayak? 

Evet bu senin gölgen, 

Seninleyim yine

Ne var şaşacak? 

Nereye baksam, 

Değil resmin, 

 Sanki gerçeğin

Elimde tuttuğum 

El de senin, 

Sensiz olamıyorum anlaşılan, 

Yüreğimde türense

Ilık nefesin.', 'Yürüyorken sessizce,  Başın eğik önünde Bir ses gelir içinden,  Hadi konuş Mırıldanıyordun hani,  Biraz önce,  Neden şimdi sessizlik Neden b...', ARRAY['Türk Edebiyatı','Şiir','Alaettin Işık']::text[], 8.5, '{"poet":"Alaettin Işık","poet_slug":"alaettin-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/duslerim-yansiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşka Uyumak', 'aska-uyumak-ahmet-meydan-yeenx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'üçüncü yıldız boşluğunu tamamlıyor dünyam, 

gökte ipince üşüyen dört tane

başıboş ve romantik yıldız, 

gecenin nemli havası, 

ışığın bedenine değdiği yerlerde ayın şavkı; 

ipince nefes alıyorsun sen uyurken, 

sessizce soluyorsun, 

ürker gibi, kaçar gibi 

şarkı söyler gibi, 

kaş çatar gibi uyuyorsun sen

sevgilim; 

ay yüzlüm

gül dudaklım.

bir sonbahar hüznü taşıyordum gece sana

bir yalnızlık havası klarnetten taşan, 

ürkek bir bakışın ardına gizleyip kıstığım gözlerimden

biz türk''lere 

ve erkeklere ait korkuları

yanılgı ve yalnızlıkları

ve anlatamadığımız

gösteremediğimiz 

duyguları döküyordum.

sen lale oluyordun

sen lale kokuyordun

aşk sen oluyordun

ben dalında bülbül.

gül.

avlusuna bisikletlerimizi bırakıp

o meşe ağacının altında

şarap içtik ya senle

ben artık

beşinci yalnızlığımı tamamlamış sayılırım.

aşktan tatmış sayılırım.

bacaklarının kısrak tadında, 

gözlerinin ceylan bakışında

kalbindeki güvercinlere

dilimden çıkartıpta attığım o sözlerimle

ben artık aşık sayılırım.

hanımelleri ekerim kalbimin bahçelerine, 

kokun olur yanımda, 

kokun siner kokuma, 

bakışın siner bakışıma

kolunu dolarsın boynuma

şelaleden yağan ateşlerde

yıkarsın yıpranmış ruhumu.

sen lale olur açarsın

sen lale olur kokarsın.

ben dalında bülbül.

gül.

datça''da yarın sabah portakallar kokacak, 

gün yüzünü göstermeden açacaksın gözlerini

dudakların dudaklarıma değecek, 

üzerime çıkacaksın

ben ay

sen yıldız

gece gibi

olacak yanışımız.

altmışlara gideceğim öğlen üzeri uyandığında, 

ruj sürüyor olacaksın aynanın karşısında

kırmızı bir ruj, 

ingrid bergman gibi bakacak gözlerin

ben şaşkın oğlan çocuklarının

makyaj yapan annelerini izlemesini izler gibi izleyeceğim seni, 

sonra kahvaltıya kalkacağız, 

dolabı açacaksın

ve biliyorum

sevinçten havalara zıplayıp boynuma sarılacaksın.

buzdolabında güller olacak, 

çekmecelerinde güller, 

banyoda güller, 

küvetinde güller.

nasıl tarif edebilirimki seni kendime

sen lale kokan, 

sen lale bakan bir gülsün.

sarılacaksın bana.

güleceksin.

aşkla bakacak gözlerin, 

kısacaksın azıcık bakışlarını, 

boynunu koklayacağım, 

boynunu öpeceğim.

bütün hayatımı

sana adayacağım.

gül.

gamzelerine şiirler düzeceğim, 

benlerini sayacağım.

aşktan ben

bir yaz gecesi 

donacağım.

markiz''deymişiz gibi seninle

paris''in bütün bulvar kahvelerini dolaşacağım.

yalnızlığımdan

adına bir heykel yapacağım.

adını gül koyacağım.

sana ait olacağım

sensiz inan

bende olmayacağım.

sensizlikte

donan bir kelebek gibi

yokolacağım.

yokolacağım.

sen lalesin, 

belki biraz sümbül.

ben senin yolunda, 

ben gülün yolunda

bülbül.', 'üçüncü yıldız boşluğunu tamamlıyor dünyam,  gökte ipince üşüyen dört tane başıboş ve romantik yıldız,  gecenin nemli havası,  ışığın bedenin...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Meydan']::text[], 8.5, '{"poet":"Ahmet Meydan","poet_slug":"ahmet-meydan","theme":"Türk Şiiri","is_hero":false,"total_lines":105,"source_url":"https://www.antoloji.com/aska-uyumak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fırtına', 'firtina-ahmet-meydan-r1gu4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'louis armstrong biraz sus ne olur, 

tren daha yeni kalktı, 

beni ona götürecek, onu bana getirecek

dakar''da bir mayıs sabahı

öğrenciler kavga ediyorlar stanbul''da

ne kavgalara girmedikmi bizde

bu eksik yaşanmış

belkide biraz yarım

ömrü hayatımızda.

armstrong biraz sus ne olur, 

nil nehrinde değilim, 

boğaz burası

daha dün gibi

zagrep''te bir mavi gözlü kadın, 

gece uykularıma akan, 

bıçak ışıltılarında izini gördüğüm, 

stanbul''da sefillik, pespayelik

güneş o çağdaki gibi aydınlatmıyor sanki beni

bir bahar şarkısı dökülmüyor kulaklarıma, 

yollarda fayton sesleri

bir mart ayazında o atların burunlarından çıkan buğu, 

sevgilimin bedeninde bir telaş, heyecan, 

gecikmiş bir çağımı yaşıyorum yoksa, 

zaman başımdan aşağı dökülüyor.

ne olur sus dedim armstrong, 

parisien bir kadın yürüyor pera''da

mavi bir elbise üzerinde, 

bakışları üzerime geliyor, 

sanki peşinden kendimi yakacağım, 

cite de pera''da gramafon cızırtısı, 

bir akşam ayazı galata''da

madam burneo yine kızıyor kedisine, 

damlarda ucuz kadınlar, 

sırtımda onun tırnaklarının izi

ki bir önceki sevişmemizden kalan, 

bir madalya gibi taşıdığım, 

ondan sonra hiçbir kadınla sevişemediğim, 

bulvar kahvesi kalabalığına karışıyorum.

bu gecedede kendimi vuracağım, 

aysel beni soracak

celal arkamdan atacak, 

rakı içecek havamda değilim, 

başımda onun sarhoşluğu, 

parisien kadının gözlerine bile bakamıyorum, 

sanki dünyanın bütün yağmurları üzerime yağıyor, 

oysa ne kadarda mesuttum, 

şimdi neden böyle bir yalnızlık, 

bu yalnızlıkki

bin yılanla dolu bir kuyu gibi, 

her yerimden sokuyor beni, 

gözlerinde denizfenerleri, 

onlarda onunla gitti, 

batan gemilerim ondandır herhal, 

sırtımda tırnak izleri, 

mısır apartımanı''nda roman kadınları, 

arka sokaklarda fahişeler, 

celal kimbilir hangisinin koynunda, 

anadolu''da pırpır bahar telaşları, 

kuvayı milliye izi içimde, 

paşanın arkasındaki resim cebimde, 

saati, tokmağı

gömleği, 

celal kimbilir hangi kadınla, 

sarışınmı, kızılmı kimbilir, 

slovak soğukları gibi bir bakış gözümde, 

sırtımda onun tırnak izleri, 

hiçbir kavgada böyle bir bıçaklanma görmemiştim ben, 

hiç bir top atışı beni onun gözleri kadar korkutmamıştı, 

stanbul''da yaz hazırlığı, 

insanlarda kaçma telaşı

kimbilir o şimdi nerede.

içimde fırtınalı havalar, 

dağlarda açan çiçekler, 

yalnızlıktan donan bir adam, 

ki yalnızlığa o neyler.', 'louis armstrong biraz sus ne olur,  tren daha yeni kalktı,  beni ona götürecek, onu bana getirecek dakar''da bir mayıs sabahı öğrenciler kavg...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Meydan']::text[], 8.5, '{"poet":"Ahmet Meydan","poet_slug":"ahmet-meydan","theme":"Türk Şiiri","is_hero":false,"total_lines":75,"source_url":"https://www.antoloji.com/firtina-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökyüzü', 'gokyuzu-ahmet-meydan-uhvc6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sizin yüzünüz

benim gökyüzüm

ve 

ben 

her gece

yanan ateşler gibi

ışıldayan

gözlerinize bakıp

kendi gökyüzümde, 

güvercinler uçuracağım.

bedenimin ilacını, 

bir köyün tek çeşmesi

gibi duran, 

rivayete göre

yüz yıl önce sinan yapmış

padişaha lütfundan dolayı

teşekkür için sunmuş

adınada

isminizi

vermiş, 

o çeşme gibi, 

dudaklarınızdan alacağım, 

rujunuz

çeşmenin altın kurnaları 

gibi parlayacak, 

yanan ve yakan 

güneşte.

upuzun bir vadi, 

geçilmez gibi gözüken

sırtınız.

en büyük savaşlarımı

orada yapacağım.

sizin o boynunuz, 

bir köprü, 

bedeninizi yüzünüze, 

şehrimi gökyüzüne

bağlayan.

dudaklarımla ben

bir gemi gibi

her gece

boynunuza açılıp, 

dudaklarınızın

limanında

yaşlı bir kaptan gibi

sarhoş olacağım.

cananım.', 'sizin yüzünüz benim gökyüzüm ve  ben  her gece yanan ateşler gibi ışıldayan gözlerinize bakıp kendi gökyüzümde,  güvercinler uçuracağım. bed...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Meydan']::text[], 8.5, '{"poet":"Ahmet Meydan","poet_slug":"ahmet-meydan","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/gokyuzu-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşin Tutuşması', 'gunesin-tutusmasi-ahmet-meydan-26qgb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sen gözleriyle adamı delik deşik eden, 

dudaklarında darağıcı taşıyan, 

güldümü lale bahçesi, 

ağladımı dolu dizgin yağmurlar, 

aşkı çakan şimşekler, 

aklı bir göl kıyısı ayazı

bedeninde ateşler yangınlar, 

kaşlarında yabani ceylanlar, 

gamzeleri atlas okyanusu, 

göbeği pasifik denizi, 

beni yerle bir eden

aklımı çelen

bedenimi çıra gibi

bedeninde yakan.

beynimde depremler, 

yüreğimde göçükler

beni bu derin yalnızlık

vadisine atan.

sen, 

güneşin doğuşu

sağ yanağında başlayan

batışı

sol yanağında olan.

etna yanardağından çıkan lavlarda

yıkasam ruhumu

mercan kayalıklarında kurutsam

yüzüne yanaşabilirmiyim acaba.

gözlerine.

yemin ederim

bildiğim tek şey

bu hayatta, 

her sabah

doğan güneş var ya

işte o güneş

hem vallahi

hem billahi

seni aydınlatmak için doğuyor.

o güneş

senin için yanıyor.', 'sen gözleriyle adamı delik deşik eden,  dudaklarında darağıcı taşıyan,  güldümü lale bahçesi,  ağladımı dolu dizgin yağmurlar,  aşkı çakan ş...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Meydan']::text[], 8.5, '{"poet":"Ahmet Meydan","poet_slug":"ahmet-meydan","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/gunesin-tutusmasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lady Smyrna', 'lady-smyrna-ahmet-meydan-lc502', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ince dantelli perdelerin ardına saklama yüzünü. izmir yanıyor dışarda. 

yeşil kapının ardında sen, içimde sen, dışımda sen...

bir ben kaldım ortalarda, 

birde yalnızlıktan geberecek eylül.

bülbüller ötüyor uzaklarda, 

sitemin geliyor dost sohbetlerinde, 

unutmuş demişsin beni, 

unutmuş, 

kendimi unuttuğumdandır dedim.

kendimi unutup onu unutamadığımdandır dedim.

aklımı oynattığımdandır dedim.

suzidilara bir parça gibisin, 

ince biraz ürkek, 

yanan her kanun telinin ardında sen, 

bu şehrin her sokağında sen, 

gözlerimde bir perdesin sen.

sonbahar yağmurları gibi ıslattığın ve geçtiğin ben, 

ben şimdi, 

bir eylül sessizliği taşıyorum, 

gülüşümde yalnız senden izler taşıyorum, 

hoppalıklarım arttı, 

saçlarımı sevdiğin gibi tarıyorum.

şile bezi gömlekler bile kalın gelir oldu, 

seninle kenarında oturup

pasaportta

saatlerce izlediğimiz deniz bile

dar gelir oldu, 

bu sensizlikte

hangi kıtaya saklanacağım ben.

açılmayan telefonlarda hep sen, 

yazılmayan mektuplarda hep sen, 

gelmeyen telgraflarda, 

gidilmeyen şehirlerde.

sensizlikte bu kendimi

nerelere saklasam ben.

sonunda hep sen.

ince dantelli perdelerin ardına saklama yüzünü.

bu gece sabaha kadar resmini yapacağım, 

gözlerine ihtiyacım var, 

ver onları bana, 

ver bakışlarını...

sabaha kadar ışıtacağım bu eski yüz yıllık rum evini, 

gece sabaha karşı bir fincan rum kahvesi yapacağım, 

hızlı bir müzik çalacak setde, 

ben yine sana karşı

kimsesizleri oynayacağım.

gri kanepeme uzanacağım sabah karşı, 

camlar açık olacak, 

martı çığlıkları vuracak kulaklarıma, 

sabah araba kornaları, 

yarın bir davetden bir davete koşacağım, 

şık tuvaletli kadınlar, 

bende siyah smokin, 

yakasında ufak bir beyaz gül

sessizce aslında herkese seni anlatacağım

neşeli bir adam olacağım, 

sonra bu eve dönünce, 

karşımda

sensizliği bulacağım.

sensizlikte üç kadeh viski içeceğim, 

papyonu her zamanki gibi zor çıkaracağım, 

evin tüm ışıklarını yakacağım, 

spotların altında aynada yüzüme bakacağım.

sonra üzerimde

beyaz bir keten pantolan

ve mavi bir keten gömlek, 

körfezin tüm rüzgarını

içime doldurarak

uyuyacağım.', 'ince dantelli perdelerin ardına saklama yüzünü. izmir yanıyor dışarda.  yeşil kapının ardında sen, içimde sen, dışımda sen... bir ben kaldım...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Meydan']::text[], 8.5, '{"poet":"Ahmet Meydan","poet_slug":"ahmet-meydan","theme":"Türk Şiiri","is_hero":false,"total_lines":69,"source_url":"https://www.antoloji.com/lady-smyrna-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Şiiri Yazmak İçin', 'bu-siiri-yazmak-i-cin-melih-coskun-hkhfw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu şiiri yazmak için 

İzin almayacağım kendimden bile 

Adına ne dersen 

İster aşk 

İster ihanet 

Ama şunu bil ki 

Gecenin ikisinde 

Boşuna ıslanmaz hiçbir yastık...

23 Mart 2003

23: 29', 'Bu şiiri yazmak için  İzin almayacağım kendimden bile  Adına ne dersen  İster aşk  İster ihanet  Ama şunu bil ki  Gecenin ikisinde  Boşuna ı...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bu-siiri-yazmak-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşık Olduğu İçin Şiir Yazmaz Gerçek Şair', 'asik-oldugu-i-cin-siir-yazmaz-gercek-sair-melih-coskun-e1l3j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşık olduğu için şiir yazmaz hiçbir şair

Şiir yazdığı için aşık olur sadece...

Önceden çizilmiş bir resimdir 

O beyazlar içindeki düş 

Gece, kağıdına çizdiğin kadar siyahtır 

Ateş, yazdığın kadar sıcak

Ve bitti bitecek derken hayat 

Ufak bir kıvılcımla alevlenir yine 

Umulmadık bir zaman 

Bambaşka bir yürek çarpıntısı 

Coşar birden bire içinde nehirler

Kıra kıra yüreğinin duvarlarını 

Ve adının anılmadığı bütün coğrafyaları

Terk edip gidercesine

Yeniden başlarsın her şeye

Yazılsın diye hikayesi 

Bütün ayrılıkların                    

Düzmece bütün aldanışlar 

Bu gidiş; 

En güzeli için vedanın

Çünkü aşık olduğu için şiir yazmaz hiçbir şair 

Şiir yazdığı için aşık olur sadece...

25 Mart 2003

01: 15', 'Aşık olduğu için şiir yazmaz hiçbir şair Şiir yazdığı için aşık olur sadece... Önceden çizilmiş bir resimdir  O beyazlar içindeki düş  Gece,...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/asik-oldugu-icin-siir-yazmaz-gercek-sair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanlış Bir Şeyler', 'yanlis-bir-seyler-gunes-yagmur-4vqwx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir şeyler yanlış gidiyordu bizde

Sanki eksik olan bir şeyler vardı

Ya ben seni sen olduğun için seviyordum

Ya da sen beni ben olduğum için

Bazı şeyler zorlama olmuştu sanki

Ama ilk kez sevdiğimi söyleyen ben değildim ki! 

Seni telefonda sus pus eden de ben değildim

Şimdi geçmişe dönüp bakıyorum da

Olmaması gereken şeyler oldu

Gelmemesi gereken şeyler geldi başımıza

Belki fazla güzeldin benim gibi bir adama nazaran

Belki çok kıskançtım, seni zorda bıraktım zaman zaman

Seni sen olduğun için sevmişim şimdi iyi anlıyorum

Bana layık değilmişsin bunu da rahatlıkla söyleyebiliyorum

Evet, şimdi çok daha iyi anlayabiliyorum

Birçok şey yanlışmış bizde

Olmaması gereken şeyler olmuş

Gelmemesi gereken şeyler gelmiş başımıza…', 'Bir şeyler yanlış gidiyordu bizde Sanki eksik olan bir şeyler vardı Ya ben seni sen olduğun için seviyordum Ya da sen beni ben olduğum için ...', ARRAY['Türk Edebiyatı','Şiir','Güneş Yağmur']::text[], 8.5, '{"poet":"Güneş Yağmur","poet_slug":"gunes-yagmur","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yanlis-bir-seyler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vardır (Nazire)', 'vardir-nazire-mehmet-fatin-baki-1lohy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gönül dostum! Bizim New York’ta bir büstânımız vardır

Evet.  Büstanda âsûmânımız,  ummânımız  vardır

Bu gün büstanda Hürrem’den kalan sultâna köşkünde

Şekerden tatlı, mehtaptan güzel mihmânımız vardır

Doğal bir ses, ilâhî bir çeşit nağmeyle şâd olmuş

Muhabbet kuşlarından mutlu bir cânânımız vardır

Bizimçin sevgiler bâbında hiç bir lafzı yok derler

‘Belî,  söz bilmeziz ammâ biraz irfânımız vardır’ (1)

Vefâkâr dosta her gün verdiğin zorluk yetişmez mi? 

‘Behey zalim, sen insâf et, bizimde cânımız vardır’ (1)

Yaşarken bunca varlıklarla, Mehmet, sor ki eflâke

Neden hep muttasıl husrânımız, efgânımız vardır? 

(1)   Nedim’in gazelinden

Büstân = bahçe			Âsûmân = gök

Ummân = deniz			Mihmân = konuk

Şâd = sevinçli			Lafz = söz

Babında = mevzuunda, hakkında

Eflâk = dünya, talih, zaman

Muttasıl = devamlı, aralıksız

Husrân = zarar, ziyan, kayıp

Efgân = acı bir çığlık, feryad

Me fâ î lün       me fâ î lün      me fâ î lün       me fâ î lün

.    /    /   /          .    /    /   /         .    /    /   /        .    /    /   /        

GAZEL

Mürâdın anlarız ol gamzenin iz’ânımız vardır

Belî söz bilmeziz ammâ biraz irfânımız vardır

O şûhun sunduğu peymâneyi reddetmeziz elbet

Anınla böylece ahdetmişiz peymânımız vardır

Münâsiptir sana ey tıfl-ı nâzım hüccetin al gel

Beşiktâş’a yakın bir hâne-i vîrânemiz vardır

Güzel sevmekte zâhid müşkilin var ise bizden sor

Bizim ol fende çok tahkîkımız itkaanımız vardır

Kocup her şeb miyânın cânına can katmada ağyâr

Behey zalim sen insâf et bizim de cânımız vardır

Sıkılma bezme gel bîgâne yok da’vetlimiz ancak

Nedîmâ bendeniz var bir dahî sultanımız vardır.  

Nedim  (1730)', 'Gönül dostum! Bizim New York’ta bir büstânımız vardır Evet.  Büstanda âsûmânımız,  ummânımız  vardır Bu gün büstanda Hürrem’den kalan sultân...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/vardir-nazire-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup...', 'mektup-ugur-deniz-ulkegul-30ish', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne zaman oturup, sevdiklerime iki satır yazmaya kalksam, 

          Donar kalır bakışlarım o beyaz kağıt üzerinde....

          Ne zaman o ilk cümleyi yazmak için kaleme uzansam, 

          Titrer ellerim...

          Anamın yazdığı mektuplar gelir aklıma, 

          Her zaman okuduğum o ilk cümlesi çakılır beynimin duvarlarına, 

          Ezilirim....

          Canım Oğul! ! ! 

          Garip gelebilir sana ama, 

          Ne zaman O''nun yazdığı bu ilk cümleyi okuduysam, 

          Sonra ki yazdıklarına bakacak derman bulamam yüreğimde....

          Bu yüzden, yazdığım her mektubun ''İlk cümle''si, 

          Hayatımın en zor cümlesi olmuştur...

          Çünkü her mektup, 

          Kendi başlangıcının hikayesini bitirir son satırında...

          Ve her mektup, yeni bir başlangıçtır, okuyan için.........

          İnsanların bunu farketmemesi ne kötü değil mi? 

          Oysa çok değil, daha yedi sekiz yıl öncesine kadar, 

          İnsanlar yine bu kadar uzak; ama bu kadar kopuk değillerdi....

          Sanki daha bağlıydılar birbirlerine....

          Sanki bedenleri uzak, 

          Ama gönülleri daha yakın kılınmış gibiydiler.....

          Çünkü özlemeyi biliyorlardı, 

          Mektubu gelmedi diye ağlamayı da..............

          Ne yazık! ..

          Şimdi ''Çok yazmasın''lara feda ediyoruz sevgilerimizi...

          Daha çok haberleşiyor, 

          Ama daha az anlıyoruz birbirimizi.....

          Hızlı konuşup ''Genç''susmak, böyle bir şey olsa gerek....

          Anladın mı şimdi, neden ''kapsam alanı dışında'' olduğumu.......

          Gördüğün gibi işte, ben aynıyım....

          Bırakamadım sigarayı hala 

          Ve gecenin çoğunluğunu uykusuz geçirmeyi....

          Sakal bıraktım şimdilerde, ama çok değil, biraz.....

          Geçen gün farkettim, dikkatimi çekti aynada, 

          Yaklaşıp saydım, çenemde tam otuz sekiz beyaz....... 

          Ama merak etme, 

          Saçlarım hala sımsıkı tutunuyor gençliğime....

          Yüreğimi soruyorsan, 

          Yüreğine sor demekten başka yazacak bir cümle bulamadım henüz...

          Bulursan, sen bana yaz.....

          Çayı azalttım, bak buna sevinebilirsin, 

          Ama ne kadar sürer bilmem...

          Huylu huyundan kolay vazgeçmez, bilirsin....

          Hala aradığım şeyi baktığım en son cebimde buluyorum, 

          Alışamadım bu şehrin karmaşasına, 

          Arada bir gezerken kayboluyorum.....

          Aklıma gelmişken, 

          ''Komşuluk çelişkilerin''ne alemde? 

          Hani dört yıldan beridir karşılaşır durularda, 

          Hep tanıdık gelir yüzleri merdivende.....

          Bir türlü çözemem bende bunu...

          Herkes karşı komşusunu bilir de, 

          Üstü altı tanımaz, daha mı eşit bulur kendine ne? 

          Koca apartmanda ''Yatay''selamlar alınırda, 

          ''Dikey'' olanlar bir türlü duyulmaz.....

          Kalabalık yalnızlıklar sitesi, 

          Eksik ilişkiler apartmanı diye bir adres yazsak, 

          Pek de fena olmazdı hani......

          Ve sen......

          İyisin değil mi? 

          Hala kızıyormusun umursamazlığıma....

          Bu iyi...

          Hala kızabiliyorsan, hala sevebiliyorsun demektir... 

          Bilirim, merttir senin yüreğin, seni benden hiç saklamadın...

          Ayrılıktan şikayet ettin lakin, vuslatı hiç yasaklamadın....

          Senin bu şevkatin olmasaydı, 

          Hayatın bu merhametsizliğinde ne yapardık bilmiyorum....

          ''Rastlamak'' ne büyük nimet değil mi? 

          İşte böyle....

          Yazacaklarım şimdilik bunlardan ibaret....

          Zaman yol olup uzuyor aramızda, yol zaman alıyor bazen..

          Özlemek, tek teselli....

          Kendine de, bana da iyi bak...

          Rastladığın dost yüreklere, selam et bizlerden...

          Birde....

          Her gün, seni yaşamak telaşıdır benim için yaşamak....

          Bilesin.............', 'Ne zaman oturup, sevdiklerime iki satır yazmaya kalksam,            Donar kalır bakışlarım o beyaz kağıt üzerinde....           Ne zaman o i...', ARRAY['Türk Edebiyatı','Şiir','Uğur Deniz Ülkegül']::text[], 8.5, '{"poet":"Uğur Deniz Ülkegül","poet_slug":"ugur-deniz-ulkegul","theme":"Türk Şiiri","is_hero":false,"total_lines":78,"source_url":"https://www.antoloji.com/mektup-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dermek İsterim', 'dermek-i-sterim-mehmet-fatin-baki-divjz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bâğbân uyanmadan sana gül vermek isterim

Bir gonca gül yolunda gönül vermek isterim

Hasret, keder ve gam dolu gurbette inleyen

Kalbimde saklı  hisleri  göstermek isterim

Mâba’di gelmeyen geceler veche damlayan

Eşkimle yazdığım şiri göndermek isterim

Kısmetse vuslatınla, yol üstünde bastığın

Toprakla kaplı yerlere, gül sermek sterim

Gam, kaygı, dert değil de şu son gümlerimde ben

Gül koklayıp ta bağda, çiçek dermek  isterim

Bâğbân = bahçivan

Mâba’di = sonu, arkası

Vech = yüz 

Eşk = gözyaşı

Mef û lü   fâ i lâ tü   me fâ î lü   fâ i lün

/     /  .    / .   /.   .    /   / .    / .    /', 'Bâğbân uyanmadan sana gül vermek isterim Bir gonca gül yolunda gönül vermek isterim Hasret, keder ve gam dolu gurbette inleyen Kalbimde sakl...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dermek-isterim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dört Açarım', 'dort-acarim-mehmet-fatin-baki-enkqz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Manzum yazarak duygumu kalpten saçarım

Mecliste duraksız konuşandan kaçarım

Dünyâya dokuz kerre dahî gelsem eğer

Ağzım kapayıp gözlerimi dört açarım

Mefûlü     mefâîlü   mefâîlü   feül

/    / . .   /   /..   /   /..   /', 'Manzum yazarak duygumu kalpten saçarım Mecliste duraksız konuşandan kaçarım Dünyâya dokuz kerre dahî gelsem eğer Ağzım kapayıp gözlerimi dör...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/dort-acarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğren', 'ogren-mehmet-fatin-baki-8q6rh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Eğlenmek için yârını yârârını öğren

Çindeysede, lûtf ilmini irfânını öğren

Mahşerdeki menzilde hesap vermeden önce

Dünyâda iken diynini iymânını öğren

Mef  û lü   me fâ î lü   me fâ î lü   fe û lün

  /    /  .   .   /   /  .  .    /   / .  .   /    /', 'Eğlenmek için yârını yârârını öğren Çindeysede, lûtf ilmini irfânını öğren Mahşerdeki menzilde hesap vermeden önce Dünyâda iken diynini iymâ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ogren-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnanmam', 'i-nanmam-mehmet-fatin-baki-8umnm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Artık bana nâmus sözü versen de inanmam

Binlerce yemin teklif edersen de inanmam

Rüzgar gibi göğsümde esersen de inanmam

Binlerce yemin teklif edersen de inanmam

Ceylanla gazel bizden uzak dağda gezerken

Yaz mevsimi bülbülleri gül seyran ederken

Duysan da nedâmet gece gündüz sabah erken

Binlerce yemin teklif edersen de inanmam

Bir nebze dahî kan variken, ten kafesimde

Sös söyleyecek kudreti mevcutsa sesimde

Son demlerimin geldiği gün, son nefesimde

Binlerce yemin teklif edersen de inanmam

Mef û lü   me fâ î lü  me fâ î lü  fe û lün

  /    /. .    /   /. .   /   /. .   /   /', 'Artık bana nâmus sözü versen de inanmam Binlerce yemin teklif edersen de inanmam Rüzgar gibi göğsümde esersen de inanmam Binlerce yemin tekl...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/inanmam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilemem', 'bilemem-mehmet-fatin-baki-w63p0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu küçük şi’ri okurken yalınız tek başına

Göreceksin yürek ağrım dönecek göz yaşına

Yazarak söyleyecektim sana bildiklerimi

Nerelerden kırılıp nerde eğildiklerimi

Kuru bir yel gibi gurbetteki vakt oldu heder

Bozulan sıhhatı kaybetme dahî başka keder

Bu felâket başa her dem gelecek sanma sakın

Ama kâfir feleğin cilvesidir. Kanma sakın

Yaşadım ağlayarak her günü yetmiş sene ben

Şükür Allâhıma derken dökerim yaş gene ben

Eğer ukbâya gidiş varsa, kaderden  silemem

Yaşayıp dertleri çekmek midir ehven? Bilemem

Heder = boşa giden

Ukbâ = âhiret

Ehven = daha kolay

Fe i lâ tün  fe i lâ tün  fe i lâ tün  fe i lün

. .   /   /  . .   /   /  . .   /   /  . .   /', 'Bu küçük şi’ri okurken yalınız tek başına Göreceksin yürek ağrım dönecek göz yaşına Yazarak söyleyecektim sana bildiklerimi Nerelerden kırıl...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bilemem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızıma Mektup', 'kizima-mektup-mehmet-fatin-baki-n6p2e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevginin meâlini luğatlar tarif eder

Anneler bebeğini daha görmeden sever

Az sonra samimiyet duygularla birleşir

Anne çocuk arası muhabbet perçinleşir

İşte böyle babalar da sever evladını

Kız, oğlan, büyük, küçük duyar duymaz adını 

Konuşurken beliren sesindeki ihtizaz

Kararımı vermekte yardımcı oldu biraz

Babaların arzusu  iç güzellik yanında

Nezaket, dürüst ahlak en yüksek ayarında

Yardımseverlik gibi inanış ve terbiye

Meziyetlerin hepsi sinende vardır diye

Seni sevdim görmeden benim sevgili kızın

Yerde yürüyen melek, gökte uçan yıldızım

Bu ölümlü dünyada seni görmezsem eğer

Bu baba da kızını bir kez görmeden sever.', 'Sevginin meâlini luğatlar tarif eder Anneler bebeğini daha görmeden sever Az sonra samimiyet duygularla birleşir Anne çocuk arası muhabbet p...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kizima-mektup-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanlar', 'i-nsanlar-caglar-akarsu-ysqxi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '...

Her  düşünce bir muamma, 

Çözemiyoruz, yıllar uzanmış

Bizler içine dolaşmışız  günlerle

Geceler akıp, giderken sarıyorlar

 Yokluğunda  bir  şey sorguluyorum.

Bulamıyorum.

....

Fabrikaların  yorgun düdükleri 

Kulaklarımda ki çığlıklara karışıyor

Yollar adımlarında, uzayıp gidiyor.

Bir elimde, sefer tasımdaki aşlar, 

Diğerinde bir torba ekmek

Duraklara yığılmış kuyruklar

Ter kokulu otobüslerde bekliyorum

....

Kapılar açılıyor, itilerek yürüyorum, 

Her yeni  günün arkasından, çileleri, 

Bedenime umutsuzlukları sarıyor.

Sokaklardaki lambalar sararmış, 

Mumlar bu gece bitmek üzere

Cılız ışıklarını saçıyorlar, 

Bir taş sıcak çorbanın  içinde

Kayboluyorum

....

Dükkanların tüm kepenklerini  indiriyorlar

Sahipleri buruk günün arkasında, 

Köşe başlarına doğru yürüyorlar.

Anlatamıyorum, yaşadıklarımı

Birinci sigaramdaki dumanlar gibi, 

Nefesimdeki soluklarıma karışıyor

Ahlarım içinde, yaşarken gidiyorum.

...

Akşam gazetelerini satıyor bir çocuk

Sesi karışıyor  haberlerin hüznüne, 

Geçmişte ihtilalleri yaşamış, 

Sokaklarda telaşla koşuyorlar, 

Duvarlara  asılmış afişleri yırtıyorlar

Çekilen  romantik filmlerin, 

Sabah on bir  seansında, 

Kadınlar çekirdeklerini çıtlatıyor, 

Luna park da,  dönme dolaplar

Dönerken, aradıklarımı hiç bulamıyorum.

....

mayıs/2003', '... Her  düşünce bir muamma,  Çözemiyoruz, yıllar uzanmış Bizler içine dolaşmışız  günlerle Geceler akıp, giderken sarıyorlar  Yokluğunda  b...', ARRAY['Türk Edebiyatı','Şiir','Cağlar Akarsu']::text[], 8.5, '{"poet":"Cağlar Akarsu","poet_slug":"caglar-akarsu","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/insanlar-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ebe!', 'ebe-sule-aydemir-9k4wz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'önüm yalan 

arkam yalan

sağım yalan 

solum yalan

gördüğümdür ebe

tam da yakaladım birini

el verdim baktım 

KİM

heyhat ne acı ki

YALANCI! 

sakin sessizlik tehlikeli

şeytan detaylarda kilitli', 'önüm yalan  arkam yalan sağım yalan  solum yalan gördüğümdür ebe tam da yakaladım birini el verdim baktım  KİM heyhat ne acı ki YALANCI!  sa...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ebe-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dumanı Tüten Sevgi', 'dumani-tuten-sevgi-sule-aydemir-fxent', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'terkediş

kurak bir yürek

çamurlaşan bir sevgi

yüreğin toprağı ki 

en hasından

kar gitsin 

acıyı sevgiyle ihanetle terkle

yoğur da ver hani 

mayalansın en sıcak yerlerde

kabart en güzelinden 

puf puf şöyle

kızart hafifte çıtırdak

ilk bölen kazansın ortadan

dumanı tüterken hani

herkes yanında getirsin has tereyağını 

tat için azık çilek kokulu rüyalarını', 'terkediş kurak bir yürek çamurlaşan bir sevgi yüreğin toprağı ki  en hasından kar gitsin  acıyı sevgiyle ihanetle terkle yoğur da ver hani  ...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dumani-tuten-sevgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İt Gibi Ölsem', 'i-t-gibi-olsem-gurcan-gunay-6wo4w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir sokak köpeği gibi son bulsun hayatım

Ya bir çöplükte karnım içine çökmüş

Ya da bir otomobilin lastiklerinde

İt gibi yaşadığımı bir ben bileyim

Leşim defalarca çiğnensin

Yapışsın kızgın asfalta büsbütün

Kimsem olmadan yaşadım

Kimsesiz bir ölüm olsun sonu da

Ne bir kabrim ne bir mezar taşım

İstemem dualar okuyanım olmasın

Bir şehir çöplüğünde son bulsun 

Şu iğrenç sefil yaşantım

Yaşadığımı öldüğümü bir ben bileyim...', 'Bir sokak köpeği gibi son bulsun hayatım Ya bir çöplükte karnım içine çökmüş Ya da bir otomobilin lastiklerinde İt gibi yaşadığımı bir ben b...', ARRAY['Türk Edebiyatı','Şiir','Gürcan Günay']::text[], 8.5, '{"poet":"Gürcan Günay","poet_slug":"gurcan-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/it-gibi-olsem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul''dur bilirim', 'i-stanbul-dur-bilirim-sule-aydemir-bwwnk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İstanbul''dur bilirim

hem batı hem doğu

hem de orta Anadolu

sevgileri ihanetleri aldanışları

ve binlerce güzellikleri

şiirlerin en güzeli 

O''nadır bilirim

bende de en güzeli O’dur

her yıkılmışlıkta kaçmak isterim ya yine ondan

yaralarımı saran yine İstanbul''dur bilirim

kozmopolit yaşamlar insanlar

ve bir o kadar da Anadolu kokar hani

burada ağlarken gülen insanlar

aşkların bile en güzeli

bir başka bakar bir başka dokunur

bir İstanbul dinlenir

bir İstanbul öper gelir

deniz ya O’nun gözleri

mavidir duygularda sessiz ve sakin

yeşilse hırcındır bilinir

hani terk edilişler de gri de olur ya bazen

İstanbul''dur bilirim

gece şıkır şıkır yıkanır ya hani

yapılır boğaz turları sevgi kaçamakları

git git bitmez bir yığın pembelikleri morlukları

bir günde zengin olur bir günde yok olursun hani

şaşırtır sevindirir ağlatır kahkaha attırır

ve her şey mümkündür hani

İstanbul''dur bilirim

bir başkadır sevdaları ayrılıkları

mevsimleri insan kokulu yağmurları

yaşayanları yaşananları

bir değişik bir hoştur

belki 

burada doğdum ondandır 

bir kış günü hani sabahın körü

zatürreye giderken menenjitten dönmüşüm

İstanbul ciğerlerime yapışmış belli

kesiyorum yaşamı ve bölüyorum

dilim dilim İstanbul hani

gidiyorum-geliyorum  tüketiyorum

ve yine kokuyorum ten ten

İstanbul İstanbul hani

sonu yok bende

büyütüyor ya beni

İstanbul İstanbul hani

İstanbul''umdur artık

bilirim

başka şehir almaz beni

herkesin içinde bir istanbul''da var hani!', 'İstanbul''dur bilirim hem batı hem doğu hem de orta Anadolu sevgileri ihanetleri aldanışları ve binlerce güzellikleri şiirlerin en güzeli  O''...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/istanbul-dur-bilirim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gece', 'bu-gece-orhan-durmus-l7f4w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni andım, coştu yine hasretim bu gece, 

Sitemkâr sözleri, kadere anlattım bu gece, 

Hayalini gördüm, yine ağladım bu gece, 

Akan yaşlara, ümidimi kattım bu gece.

Mektuplar yazdım, beğenmedim attım bu gece, 

Bilmediğin bir çok acıyı tattım bu gece, 

Sana ulaşmaya çare aradım bu gece, 

Rabbime yalvardım, derdimi açtım bu gece.

(10 Temmuz 2000/Eskişehir)', 'Seni andım, coştu yine hasretim bu gece,  Sitemkâr sözleri, kadere anlattım bu gece,  Hayalini gördüm, yine ağladım bu gece,  Akan yaşlara, ...', ARRAY['Türk Edebiyatı','Şiir','Orhan Durmuş']::text[], 8.5, '{"poet":"Orhan Durmuş","poet_slug":"orhan-durmus","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bu-gece-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıp Zaman', 'kayip-zaman-sair-uney-fdlhj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir direkte asılı kaldı zaman

Şafaklar sökmez oldu artık

Rakamlar toz bulanık ve isyankar

Bitmiyor, bitmiyor

Takvimlere adanmış bu ayrılıklar

Günler çok uzak şehirler gibi

Sarı solgun, yanık tenli ve kirli

Eriyen karlardan geriye kalan

Dağlarda sarı otlar ve yaban dikenleri

Günler nerdeyse bir tez konusu

Tartışmalar, görüşler, iddialar

Oysa ne bilirdik eskiden

Baharı, kuşları, çiçeği

Güneşin doğuşunu, şafağı, seheri

Biz kör uykularda yatarken

Hayat tüm güzellikleri eskitip geçerdi

Sararıp dökülürdü ömrümüzden yapraklar

Ya şimdi günler, nedendir geçmiyor

Bu isyan bu sitem hep neden

Çok mu gerekliydi diye sormazmıyım

Gençliğimin orta yerinde

Bu ayrılık, bu kayboluş neden

Oysa çok yakın geçmişte

Umutlu ve neşeliydim

Sevda şiirleri yazardı kalemim

Türkülerim vardı dilimde

Şimdi türkülerin tadı bile zehir

Beste yapmıyor arık Haşim

Ah Haşim! çalsana benim için

''Bir ay doğar'' benim için

Bir güneş doğsa benim için

Bir bilsen burda bana dair herşey

Yabancı dudaklar arasından çıkacak

Sevimsiz ve hain sözcüklere bağlı

Bilmem bedava mı hava, su, istirahat

Daha ne kadar boğazımı sıkar

Şu kahrolası kayıtsız şartsız itaat

Düşüncelerimi, aklımı girerken kapıda bıraktım

Acaba çıkarken bulurmuyum yerinde

Beş ay oldu ve kalan iki ay daha

Nice fırtınalar kopacak zavallı yüreğimde

Korkarım yüreğim bu isyana dayanmayacak

Bu kahır, bu sitem ne zaman son bulacak

Sevdiğim iki gözüm

Kır çiçeğim, bahar çiçeğim

Bari sen unutma beni! 

Kavuşmaya hasrettir günler

Öpüp koklamaya hasret

Ve bu günler...

Bu günler elbette geçecek.', 'Bir direkte asılı kaldı zaman Şafaklar sökmez oldu artık Rakamlar toz bulanık ve isyankar Bitmiyor, bitmiyor Takvimlere adanmış bu ayrılıkla...', ARRAY['Türk Edebiyatı','Şiir','Şair Üney']::text[], 8.5, '{"poet":"Şair Üney","poet_slug":"sair-uney","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/kayip-zaman-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Genetik Şifre', 'genetik-sifre-kenan-taskin-ob9xh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Budur aşkımızın matematiksel fomülü

Hiç dik açıyla giden kurşun adres sorarmı ve bilinmeyen bilinirmi

budur aşkımızın kimyasal formülü gözlerindeki bakır ne kadar ışıltılı ve kromozomlarımız ne kadar eş 

budur aşkımızın biyolojik formülü', 'Budur aşkımızın matematiksel fomülü Hiç dik açıyla giden kurşun adres sorarmı ve bilinmeyen bilinirmi budur aşkımızın kimyasal formülü gözle...', ARRAY['Türk Edebiyatı','Şiir','Kenan Taşkın']::text[], 8.5, '{"poet":"Kenan Taşkın","poet_slug":"kenan-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/genetik-sifre-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hisseden', 'hisseden-sule-aydemir-7hiac', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'hisseden yürek, 

yaşayan insandır

hissetmektir ya 

ağıtlı ağlamar da öl

ölmek ki insanca

bakarken görmek

öteye geçmek 

ruha inmek mesela

öyle ince ki ruh

bir ney ezgisine 

insana insan sesinde

nefesinde tirtir titrerken

yuvarlanıp duygu girdabına

sıkıca sarılmak mesela

ölüp ölüp dirilmek

hesaplaşmalara gidip gelmek

tutturmak ya yaşam mizanında

uğraşıp durmak bir liralarla

ve yeminli gelir öder kefareti

hisseden yürek

yaşayan insandır

var ki herşeyin bir değeri

istemesek de

yaşanmışın da ödenmeli bedeli', 'hisseden yürek,  yaşayan insandır hissetmektir ya  ağıtlı ağlamar da öl ölmek ki insanca bakarken görmek öteye geçmek  ruha inmek mesela öyl...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/hisseden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgarlar Çalmış', 'ruzgarlar-calmis-sule-aydemir-85ubg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'can

caniçi kızdır ney''im

üflüyorum ya

küsmüş mü ne 

çıkmıyor sesi

yok yok

rüzgarlar çalmış gönül nefesimi', 'can caniçi kızdır ney''im üflüyorum ya küsmüş mü ne  çıkmıyor sesi yok yok rüzgarlar çalmış gönül nefesimi...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ruzgarlar-calmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz', 'sensiz-hakki-yalcin-aq0iw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Emanet bir canla direniyorum

Geceler sabahsız, umutlar yanık

Bir hayal peşinde can veriyorum

Dokunamam sana, sevemem artık

Kaybettiğin aşkın değeri büyük

Anlarsın hatanı zaman içinde

Seni bilmem ama ben çok yıkıldım

Sensiz akşamlarım duman içinde', 'Emanet bir canla direniyorum Geceler sabahsız, umutlar yanık Bir hayal peşinde can veriyorum Dokunamam sana, sevemem artık Kaybettiğin aşkın...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Yalçın']::text[], 8.5, '{"poet":"Hakkı Yalçın","poet_slug":"hakki-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sensiz-53-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzülmedimki', 'uzulmedimki-senol-boruk-kafva', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sanma sen gidince ben hep agladim

Ne yas tuttum ne de kara bagladim 

Bir gercegi gec de olsa anladim

Kaderimdir dedim üzülmedim ki

Ask gülümü sulamadan kuruttun 

Ben gönlümü anilar ile avuttum 

Inan ki ismini bile unuttum 

Kaderimdir dedim üzülmedim ki', 'Sanma sen gidince ben hep agladim Ne yas tuttum ne de kara bagladim  Bir gercegi gec de olsa anladim Kaderimdir dedim üzülmedim ki Ask gülüm...', ARRAY['Türk Edebiyatı','Şiir','Senol Boruk']::text[], 8.5, '{"poet":"Senol Boruk","poet_slug":"senol-boruk","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/uzulmedimki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sivas ilinde', 'sivas-ilinde-huseyin-demir-8p0sj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Madımak''ta  canlar  semah  dönüyor

Yobaz  ateş  atmış gül''ler  kanıyor

Otuz  yedi canım  birden  yanıyor

Yine  yandık  yandık  Sivas  ilinde

                            Şu  kanlı ellerde  gonca  güllerim

                            Dört duvariçinde kırık  bellerim

                            Yakılmış  Hasret''im susmaz  dillerim

                             Yine  yandık  yandık  Sivas  ilinde

Emir  çıkmış molların  dilinden

Kibrit çakan  Hınzır Paşa  soyundan

Dönmeyiz biz yine  hakkın  yolundan

Yine   yandık yandık  Sivas   ilinde

                              Köy  aydınlar  bakıp  yardım  etmiyor

                              Soysuzların  aldığı  can  yetmiyor

                              Güllerim yakıldı bülbül ötmüyor

                              Yine  yandık  yandık  Sivas  ilinde

Hüseyin  dederki  Abdal''dır  dedem

Yandı    kanlı  Sivas  nereye  gidem

Yobaz  çemberinden ben  nasıl  edem

Yine  yandık  yandık  Sivas  ilinde', 'Madımak''ta  canlar  semah  dönüyor Yobaz  ateş  atmış gül''ler  kanıyor Otuz  yedi canım  birden  yanıyor Yine  yandık  yandık  Sivas  ilinde...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Demir']::text[], 8.5, '{"poet":"Hüseyin Demir","poet_slug":"huseyin-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sivas-ilinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlatan Biziz', 'aglatan-biziz-huseyin-demir-0hyg6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gülüişledik  halıyla

Dalını  koyduk  yalıya

Bülbül  konmuyor  çalıya

Bülbülü  ağlatan  biziz

                       Gülü  dalında  biz  kırdık

                       Bülbülü  evinde  biz vurduk 

                       Tuzak  kurup  tele  sardık

                       Bülbülü  ağlatan  biziz

Bülbül  ağlıyor   haline

Bağda  kesilen  gülüne

Söver insan  temeline

Bülbülü   ağlatan   biziz', 'Gülüişledik  halıyla Dalını  koyduk  yalıya Bülbül  konmuyor  çalıya Bülbülü  ağlatan  biziz                        Gülü  dalında  biz  kırd...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Demir']::text[], 8.5, '{"poet":"Hüseyin Demir","poet_slug":"huseyin-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aglatan-biziz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürek Görsene', 'yurek-gorsene-huseyin-demir-o71fc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gönül   sevdan   ile  dağlara   düştü

Bülbül   cevreyledi  gülüne küstü

Cümle  alem  bakıp  haline   şaştı

Gelsene  de  deli  gönül  gelsene

Senin  için   yanar  yürek   görsene

                         Aşk  acısı   çeken  dağları  aştı

                         Aşk  şarabı  içen  kederden  içti

                         Yoluna  gidenler  çöllere düştü

                         Gelsenede  deli  gönül gelsene

                         Senin  için   yanar  yürek  görsene

Hüseyin  der  gönül  senin  elinden

Göğse  indi   darbe  sazın telinden

Söyleniyor  aşkım  aşık  dilinden                                              Gelsenede  deli  gönül gelsene                                               Senin  için   yanar  yürek  görsene', 'Gönül   sevdan   ile  dağlara   düştü Bülbül   cevreyledi  gülüne küstü Cümle  alem  bakıp  haline   şaştı Gelsene  de  deli  gönül  gelsene...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Demir']::text[], 8.5, '{"poet":"Hüseyin Demir","poet_slug":"huseyin-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yurek-gorsene-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yar Seni Seni', 'yar-seni-seni-huseyin-demir-wmy6w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yollarına  baka  baka   kör   oldum   yar  yar

Sen   gittin  amma  izleri  bendedir   yar  yar

Talan   ettin  benim  bütün  dünyamı  yar  yar

Görem  dedim  göremiyom  yar  seni seni

                     Bir  insanın  sermayesi  gözüdür  yar  yar

                     Aklı   ile   konuştuğu  sözüdür  yar  yar

                     Akla  yatan  yalanların  azıdır   yar  yar

                     Görem  dedimgöremiyom  yar  yar

Beni  bırakıpta   gittin  ellere  yar  yar

Hiç  hesapta   yoktu   düştüm  ellere   yar  yar

Sen   beni bağladın   paslı  tellere   yar  yar

Görem  dedim   göremiyom  yar  yar', 'Yollarına  baka  baka   kör   oldum   yar  yar Sen   gittin  amma  izleri  bendedir   yar  yar Talan   ettin  benim  bütün  dünyamı  yar  ya...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Demir']::text[], 8.5, '{"poet":"Hüseyin Demir","poet_slug":"huseyin-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yar-seni-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdiğim', 'sevdigim-huseyin-demir-2x8da', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Viran    bülbül çıkmış  öter  dağlarda

Çakal''lar  beslenir  bizim  dağlarda

Kimileri  öldü  sıra  sağlarda

Gel  gidelim  bu  dağlardan  sevdiğim

                         Kara   bulut  sarmış  Güneş''i  burada

                         Yakıldı  evimiz kalmışız  darda

                         Kendi  köyümüzde soğukta  karda

                         Gel   gidelim  bu   ellerden   sevdiğim

Kendi  köyümüzde    duramaz  olduk

Zoraki  sürüldük  kent''lere dolduk

Kime   ne  ettik   ki  şaşırıp  kaldık

Gel   gidelim  bu   ellerden  sevdiğim

                          Buralarda  insan   fazla sevilmez

                          Gökyüzü''nde  uçan   kuşlar   kovulmaz

                          Dil  olmayan yerde  bize sövülmez

                          Gel   gidelim  bu   ellerden  sevdiğim', 'Viran    bülbül çıkmış  öter  dağlarda Çakal''lar  beslenir  bizim  dağlarda Kimileri  öldü  sıra  sağlarda Gel  gidelim  bu  dağlardan  sevd...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Demir']::text[], 8.5, '{"poet":"Hüseyin Demir","poet_slug":"huseyin-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevdigim-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerim', 'gozlerim-huseyin-demir-esf1r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaralarım   yaralarım

Gün   batınca  sızlar  oy

Geceleri  yatamıyorum

Uyku  tutmaz  gözlerim  oy

                             Yaram derin   saran   yoktur

                             İlaç   fayda  etmez doktor

                             Kalarım  geceler  mağdur

                             Uyku  tutmaz gözlerim  oy

Sabah''larım çığlık  çığlık

Sevinçlerim  birer  anlık

Akşam''larım  yalnız artık

Uyku  tutmaz  gözlerim  oy', 'Yaralarım   yaralarım Gün   batınca  sızlar  oy Geceleri  yatamıyorum Uyku  tutmaz  gözlerim  oy                              Yaram derin   ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Demir']::text[], 8.5, '{"poet":"Hüseyin Demir","poet_slug":"huseyin-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gozlerim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir Kendini Yazdı', 'siir-kendini-yazdi-naime-erlacin-yud4g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'şiir kendine 

şair kendine

vardı bir sebebi buluşmanın

uzak bir ada 

bazen okyanus, kıyı batık

bazen delice bir dağ tutkusu

dinledi şair

cennetten kovuldu şiir ve göklerden

vazgeçti özgürlükten

düştü şair

geride kalan sağdı ölse bile 

öldü bile! 

kanıydı şiire sıçrayan

kendini yazdı şiir firarda

kaç cenneti var şiirin, kaç gökyüzü

hangi kucakta kundaklandı

hangi hamakta uykulandı yola düşmeden önce

şiir kendini yazdı firarda şairin kanıyla

sor ki anlatsın

sor ki anlatayım

firardayım! 

(19 Mayıs 2003)', 'şiir kendine  şair kendine vardı bir sebebi buluşmanın uzak bir ada  bazen okyanus, kıyı batık bazen delice bir dağ tutkusu dinledi şair cen...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/siir-kendini-yazdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadınlarım', 'kadinlarim-i-syan-toprak-f2wck', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uykularım yine firarda 

Kim bilir belki Gabarda belki Ziganada belki Ağrıda 

Beklide yurdumun diğer bir dağında eşkıya

Saat yine ikiyi geçti 

Gecenin tam ortasındayım 

Hem ölenin hem öldürenin ben olduğum 

Kendi savaşlarımın kucağındayım

Kül tablası çoktan doldu 

Kahrolası çay daha bardak yarılanmadan yine soğumuş 

Hayatımı renklendirir umuduyla resimlerle donattığım 

Küçük odamın duvarları üzerime üzerime geliyor 

Her zamanki gibi yine şiirlerimin ana temasını

Kadınları düşünüyorum 

Dipdiri göğüslerini, oynak kalçalarını ve korkunç ateşli dudaklarını 

Bir yanı masum, melek bir yanı vahşi şeytani kadınları 

Sonra annem geliyor aklıma 

Başımı dizine koyduğumda 

Saçlarımı okşadığında 

Kendimi Moskovaya giren Lenin gibi 

Evreka evreka diye bağıran Arşimet gibi

His ettiğim anları düşünüyorum 

Hani unutulmaz denir ya 

İlk aşkım düşüyor aklıma 

Coğrafya öğretmenimiz Esin hanım 

Elinde kalın bir sopa 

Haritanın önünde bir şeyler anlatmaya çalışıyor 

Ders umurumda değil ben onu izliyorum 

Farkına varıyor 

Yüzündeki ciddiyet gidiyor 

Her kadının ruhundaki gizli fahişelik

Gözlerinde uyanıyor 

Şehvetle bana bakıyor 

Gülümsüyor 

Kaçınılmaz olarak ilk seviştiğim kadın geliyor aklıma 

İstanbuldan Karsa uzanan uzun ve sıkıcı bir yolculuğun 

Nasılda inanılmaz zevkli bir halle geldiğini hatırlıyorum 

Şehirler arası otobüste 

Şehvetli gözlerle beni günaha davet eden 

Yarım saatlik bir molada O ilk defa tattığım şehveti bana yaşatan 

Adını bilmediğim 

Ve bir daha hiç göremeyeceğim o kadını hatırlıyorum 

Kendi savaşlarımı yaşıyorum 

Kadınları düşünüyorum 

Eteklerini karınlarına kadar çekip 

Şehvetle hadi diyen kadınları 

Hayatımdaki ilk kadını annemi özlüyorum

Nasırlı elerini, şefkatini, gücünü, güçsüzlüğünü, emeğini 

Üzerime titremesini düşünüyorum 

Kül tablasında unuttuğum sigarayı hatırlıyorum 

Tekrar unutacağımı ve kendi kendine biteceğini bildiğim halde 

Yeni bir sigara daha yakıyorum 

Vakit gece yarısını çoktan geçti 

Sabaha yaklaşıyoruz 

Horozlar ötmeye başlıyor 

Fukaralar işçi kahvesinde kuyruğa girmek için yine erkenci 

Gözüm duvardaki fotoğrafa takılıyor 

Minnacık ellerini açmış dilenen o çocuğun annesini düşünüyorum 

Sol gözümden bir damla yaş akıyor

Ağladığımı sanmayın sakın 

Erkekler ağlamaz 

Çoktan sönmüş sigaranın dumanı kaçıyor gözlerime 

Anlamazsınız belki ama ben göz yaşlarımdan bile korkuyorum 

Kendi savaşlarımı yaşıyorum 

Kadınları İri göğüslerini, ateşli dudaklarını 

Ve şehvetle bakan gözlerini düşünüyorum

İçki kokusunun alın teri kokusuna karıştığı

Bir otel odasında beş kişinin yatağını dolaştıktan sonra

Yatağıma gelen kadının yüzüne tükürdüğümde

Salaksın sen deyişini hatırlıyorum 

Buna halen bir anlam veremiyorum

Adı özgürlükle adı isyanla adı başkaldırı ile anılan o meydanda

Dün yediğim copun ağrısını hissediyorum sırtımda

Sonra yaşayamadığım çocukluğuma dönüyorum ansızın 

On yaşıma

Her gün çalıların arkasında gizlenip beklediğim

Susamış bir ceylan gibi sırtında keleşle dereye inen

Su içen aynı hızla kaybolan

Bir gün benim farkıma vardığında

Bir ceylanken aslana dönen

Beni yakaladığında korktuğumu anlayıp anlımdan öpen

Bana uğrunda savaşılması gereken yaşanılası bir dünya olduğunu öğreten

Ben senin yaşaman için bu dağlara ölmeye geldim diyen

Her ne kadar ben kadın gibi kadın desem de 

Babamın erkek gibi kadın dediği kadını hatırlıyorum

Bazen tanrılar kadar kutsal 

Ve uğruna ölünecek kadar değerli

Bazen bir kağıt mendil kadar basit

Ve kullanılıp atılacak kadar değersiz olabilen kadınları

Beş yaşlarındaki çocuğunun gözleri önünde 

Benimle sevişen kadın gözlerimin önüne geliyor

İniltilerinden acı çektiğini düşünen çocuğunun ağlamasına aldırmadan 

Boş ver devam et diyen kadın

Onu düşündükçe

İnsanlığımdan utanıyorum

Ve o çocuğun bir gün büyüdüğümde ve bunu hatırladığında 

Neler his edeceğini düşünüyorum

Tüylerim diken diken oluyor

Her zaman ölüm seçeneğini hatırlamam için 

Odamda asılı duran ipe doğru yürüyorum

Ama her zamanki gibi ölmeyi bile başaramıyorum

Sonra adına adımı verdiğim

Şiirlerimden çok sevdiğim

Kıskanırlar diye şiirlerimden sakladığım

Bana ihanet eden kadını hatırlıyorum

İntikam ateşi sarıyor bedenimi

Bunun aslında hayatın bana karşı bir intikamı olduğunu anlıyorum

Farkında olmadan dibini bulduğum içki şişeleri çarpıyor gözlerime

Neden her sarhoşluğumda

Kendimi Havva ana ile sevişir his ettiğimi anlamaya çalışıyorum

Allahtan başka kimseden korkmam demiştim ya 

Yalandı ben aslında kadınlardan daha çok korkuyorum

Annemi hatırlıyorum 

Sokakta dillenen çocuğun annesini

İlk aşkımı 

Esin öğretmeni 

Ve şehirler arası otobüste 

Uyuyan kocasını aldatan kadını 

Otel odasını

Bir ceylanın nasıl bir aslana döndüğünü bana öğreten kadını

Bir gün büyüyecek olan beş yaşındaki çocuğu

Ve bana en büyük korkumu ihaneti yaşatan kadını

Beni ben yapan

Bir yanı masum bir yanı günahkar kadınları düşünüyorum 

Tüm kadınlarda aradığım ama bulamadığım kadını özlüyorum

Kendi savaşlarımı yaşıyorum

Güneş ışınları yavaş yavaş odama konuk olmaya başlıyor

Benim gündüzüm burada bitiyor 

Ve ben kendi savaşlarımda ölüyorum', 'Uykularım yine firarda  Kim bilir belki Gabarda belki Ziganada belki Ağrıda  Beklide yurdumun diğer bir dağında eşkıya Saat yine ikiyi geçti...', ARRAY['Türk Edebiyatı','Şiir','İsyan Toprak']::text[], 8.5, '{"poet":"İsyan Toprak","poet_slug":"i-syan-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":128,"source_url":"https://www.antoloji.com/kadinlarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meczup', 'meczup-aysenur-yazici-dq6ky', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Biz hiç ayrılmadık ki

herşey bir şakaydı

bir film arası gibi

nefes alıp, böldük öyküyü

eteklerim zil çalarak 

geçiyorum yine köprüyü

     kapıyı sen açıyorsun dışarıda kar, 

     Beykoz''un tüm martıları

     sarılmamıza bağırıyorlar

     gün girdap olup 

     gecemize karışıyor

     senin için sürme çekip

     tütünüme kahkaha sarıyorum

Şarkıları elbise yapıp

bedenimize sarıyoruz yine

Bogaz '' ben buradayım '' diye bağırırken

gözlerim çivili kalıyor ellerine..

    biz hiç ayrılmadık ki

    herşey bir şakaydı

    gecenin içinden 

    sadece bir yıldız kaydı 

    hop etti yüreğimiz

   kimimiz  geçene ağladı..

   ...geleceğe ağladı  kimi...

 ...dellenmelerin hepsi

   bir mezar toprağında kaldı

                   30.09.2006', 'Biz hiç ayrılmadık ki herşey bir şakaydı bir film arası gibi nefes alıp, böldük öyküyü eteklerim zil çalarak  geçiyorum yine köprüyü      ka...', ARRAY['Türk Edebiyatı','Şiir','Ayşenur Yazıcı']::text[], 8.5, '{"poet":"Ayşenur Yazıcı","poet_slug":"aysenur-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/meczup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Yaşamamak', 'hic-yasamamak-i-syan-toprak-wu20f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Savaş ülkesinde yaşamak

Ninni diye uçak sesleri ile uyumak

Tank sesleri ile uyanmaktır çoğu zaman.

Ve çoğu zaman sabahları helalaşmak ölüme gider gibi uğurlanmaktır 

Zaman zaman sevginin anlamsızlaşması, nefretin anlam kazanmasıdır.

Bir taze gelinin gelinliğine sarılıp yatmasıdır kimi zaman

Ve kimi zaman bir erkeğin karısına gözlerinin önünde tecavüz edilmesidir 

Birileri patlamış mısır yerken televizyon karşısında

Birilerinin mevzide tüm hayatının bir film gibi gözlerinin önünden geçmesidir.

Bir çocuğun baban gelecek diye kandırılmasıdır belki de

Ve belki de bir babanın oğlunun cesedini siper etmesidir kendisine

Dünyanın tüm renklerini kaybetmesi 

Hayatın siyah beyaz görünmesidir insana 

Bir annenin oğlunun kopan ayağını aramasıdır mayın tarlasında umutsuzca

Bir oğullun başını koymak için anasının dizini aramasıdır çatışma ortasında

Savaş ülkesinde yaşamak dostlar

İnadına yaşamaktır aslında

Güneşin batışının doğuşuna tercih edilmesidir bir anlamda 

Ve bir anlamda insanlarla beraber inanlığında tükenişidir

Sevdalarda tükenir insanlıkla beraber

Dostlukların yitirilmesi arkadaşlıkların kaybedilmesi 

Kahramanların doğuşu, direnişi, duruşudur savaş ülkesinde yaşamak

Cesaret korkuyla kardeştir artık

Ve kardeşliklerin güvensizlikle tükenişidir

Yetmiş yaşında olsan da daha çocuk olduğunu anlamandır

Ölümlerin acı vermemesidir bir yerde 

Ve bir yerde ölümün kurtuluş olarak görülmesidir insana

Çocuklar açtır, kadınlar açtır, insanlar bir dilim ekmeğe muhtaçtır

Savaş ülkesinde yaşamak

Bir askerin yanı başında vurulan arkadaşının etini yemek zorunda kalmasıdır.

Bir babanın kurşun bedeniyle kucaklaşıp

Son bir kez elveda der gibi ellerini havada sallayıp yere bir tohum gibi düşüşünde

Oğlunun dönüp bakmamasıdır arkasına

Ve belki de bir annenin uyandığında bebeğini ölü bulmasıdır kucağında 

Göz yaşlarının tükenişi değil 

Acıma duygusunun yitirilmesi ve belki de unutulmasıdır

Savaş ülkesinde yaşamak özgürlük için yanmak 

Barışa aşık olmak

Ama ölümün soğuk kollarına düşmektir bir yerde

Ve bir yerde savaş ülkesinde yaşamak dostlar hiç yaşamamaktır', 'Savaş ülkesinde yaşamak Ninni diye uçak sesleri ile uyumak Tank sesleri ile uyanmaktır çoğu zaman. Ve çoğu zaman sabahları helalaşmak ölüme ...', ARRAY['Türk Edebiyatı','Şiir','İsyan Toprak']::text[], 8.5, '{"poet":"İsyan Toprak","poet_slug":"i-syan-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/hic-yasamamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baş Ağrısı', 'bas-agrisi-huseyin-demir-sxrhm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şu  başımda  bir  ağrı  var

Beni  halden  hale  koyar

İğne  ilaç  fayda  etmez

Bana  ölümü  yaşatır

Kasılır  bütün  bedenim

Kan  dolar  iki  gözlerim

Sararıp  solan  yüzlerim

Bana  ölümü  yaşatır

Morarır  hepten  damarlar

Sanki beynimi yararlar

Yaşadığım  bu dramlar

Bana ölümü yaşatır

Bir an dişler kilit''lenir

Bir  biriyle çekiç''lenir

Göz ışık''tan etkilenir

O an ölümü yaşarım

Doktor hekim''lere gittim

Başım duvar''lara vurdum

Yılan''dan bin beter oldum

O an ölümü yaşarım

Bana dünya''lar verilse

Yahut tüm dünya yıkılsa

Hiç bir şeyi gözüm görmez

O an ölümü yaşarım', 'Şu  başımda  bir  ağrı  var Beni  halden  hale  koyar İğne  ilaç  fayda  etmez Bana  ölümü  yaşatır Kasılır  bütün  bedenim Kan  dolar  iki ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Demir']::text[], 8.5, '{"poet":"Hüseyin Demir","poet_slug":"huseyin-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bas-agrisi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kondu', 'kondu-i-syan-toprak-01922', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gece kondu mahallesindeyim

Gece kondular üzerime yürür

Gece kondu mahallesindeyim 

Acılar üzerime yürür

Bu acıyı bu çileyi

Ancak bir gecekondulu bilir

Gece kondu mahallesindeyim

Kanalizasyon kokusu burnumda

Çamurlu yolarda yürüyorum 

Çocuklar oynuyor çamurda 

Ben deliriyorum 

Gece kondu mahallesindeyim

Komşu kızı Suzan her zamanki gibi yine pencerede

Tedirgin 

Bir gözü arkasında babasının gelmesinden korkuyor, 

Bir gözü yolda gönlünü kaptırdığı gencin geçmesini bekliyor 

Yine top peşinde koşarken camını kırmış hergeleler

Şakir amca saçını başını yoluyor

Kendi kendini yiyiyor

Mahallemizin şen dulu Nebahat abla 

Göğüslerini dışarıda bırakan geceliğiyle kapıda

Daha bıyığı terlememiş bir delikanlıyı süzüyor

Muhtemelen uygun bir zamanda eve atmayı düşünüyor

Ayşe teyze balkonda

Utana sıkıla dün akşam pazardan topladığı artıkları ayıklıyor

Mahalenin kadınları halk ekmek kuyruğunda 

yine dedi kodu ediyor

Erkekler ise kahvede 

Bir taraftan

Ne olacak bu memleketin hali diyor 

Diğer taraftan okey oynuyor

Gençler ellerinde fırçalar

Duvarlara yasak yazılar yazıyor

İsyankar sloganlar atıyor

Kore gazisi Ahmet amca 

Vatan hainleri, komünistler, anarşistler diye söyleniyor

Kimsenin duymamasına dikkat ediyor

Beli ki çekiniyor

Hey gidi Koreli 

Yad ellerde ölüme yürüyor

Kendi ana yurdunda olan biten karşısında korkuyor

Bizim gece kondu mahallesinde 

Günler bir birini tekrarlarcasına işte böyle geçiyor

Gece kondu mahallesindeyim

Gece kondular üzerime yürür

Gece kondu mahallesindeyim 

Acılar üzerime yürür

Bu acıyı bu çileyi

Ancak bir gecekondulu bilir', 'Gece kondu mahallesindeyim Gece kondular üzerime yürür Gece kondu mahallesindeyim  Acılar üzerime yürür Bu acıyı bu çileyi Ancak bir gecekon...', ARRAY['Türk Edebiyatı','Şiir','İsyan Toprak']::text[], 8.5, '{"poet":"İsyan Toprak","poet_slug":"i-syan-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/kondu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanı', 'tani-i-syan-toprak-cpezc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mahpus duvarı değildir aramızdaki

Töre duvarıdır

Polis ablukası değildir bizi ayıran

Yaşamın inadıdır

Dağlar değildir yol vermeyen

Kıyıcı gururundur

Ölüm değildir ayrılığa sebep 

Kahrolası paradır para', 'Mahpus duvarı değildir aramızdaki Töre duvarıdır Polis ablukası değildir bizi ayıran Yaşamın inadıdır Dağlar değildir yol vermeyen Kıyıcı gu...', ARRAY['Türk Edebiyatı','Şiir','İsyan Toprak']::text[], 8.5, '{"poet":"İsyan Toprak","poet_slug":"i-syan-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/tani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başa Bela', 'basa-bela-i-syan-toprak-6uada', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yokluk Yokluk Yokluk

Çaresizliktir

Başa beladır

İnsanlar parayı bulunca kudurur

Dinini Allahını unutur

Düşene acımadan vurur

Düşenin çilesi ölünce son bulur

Bir düştüm ki adı düşüş ola

Bir düştüm ki kalkışı olmaya

Bir düştüm ki başa bela

Yokluk Yokluk Yokluk

Çaresizliktir

Başa beladır', 'Yokluk Yokluk Yokluk Çaresizliktir Başa beladır İnsanlar parayı bulunca kudurur Dinini Allahını unutur Düşene acımadan vurur Düşenin çilesi ...', ARRAY['Türk Edebiyatı','Şiir','İsyan Toprak']::text[], 8.5, '{"poet":"İsyan Toprak","poet_slug":"i-syan-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/basa-bela-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ötekiler', 'otekiler-i-syan-toprak-p8cdp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ah be yiğidim

Ölüm üzerime yürür

Cesetler gelir

Kimine şehit, 

Kimine öldü denir

Toprak uğruna insanlar ölür

Ve toprağa insanlar gömülür

Sınırlar çizilir

Sınırları çizen ressamın fırçasından kanlar dökülür

Dünya bölünür

Yürekler parçalanır

Beyinler bölünür

Dikenli teller örülür

Yüreğim bölünür

İnsanlar bölünür

Bizler ve ötekiler

Görmediğimiz dikenli tellerin arkasındaki ötekiler

Birlikte oyun oynamanın

Aşık olmanın, sevmenin

Ve vahşice sevişmenin yasak olduğu ötekiler

Atalarımızın, dedelerimizin sebebini bilmeden düşman oldukları

İnsanların torunları olan ötekiler

İlkokul kitaplarında düşman olduğumuz

Denizlere döktüğümüz

Çin setinin arkasına sığınan

Şanlı tarihimizde kılıçlardan geçirdiğimiz ötekiler

Atalarımızın düşmanlarının torunları olan ötekiler

Konuştuğumuz dilden başka hiçbir farkımız olmayan ötekiler

Bizim gibi üzülen, sevinen, acıkan, susayan, sevişen, ağlayan ve ölen ötekiler

Çırılçıplak kaldıklarında utanan ötekiler

Kadınların gözleriyle yaralanan 

Ve kadınların dipdiri göğüslerinde kanayan

Ve ab-ı hayatı kadınların nar çatlağı dudaklarından yudumlayan ötekiler

Ah be yiğidim

Ölüm üzerime gelir

Dikenli teller örülür 

Dikenli teller yüreğime batar

Yüreğim parçalanır

Yüreğim bölünür', 'Ah be yiğidim Ölüm üzerime yürür Cesetler gelir Kimine şehit,  Kimine öldü denir Toprak uğruna insanlar ölür Ve toprağa insanlar gömülür Sın...', ARRAY['Türk Edebiyatı','Şiir','İsyan Toprak']::text[], 8.5, '{"poet":"İsyan Toprak","poet_slug":"i-syan-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/otekiler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat sürecek', 'hayat-surecek-aysenur-yazici-9uy1s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hayat, sensiz de 

öyle ya da böyle sürecek işte

kalkıp işe gideceğim

sofralarım da olacak gecelerde

kaşığı, elim ağzıma götürecek

dönmemden sıkılacak döşek

gün ağaracak kırmızı gözlerimle

''dayanamam''  dediğim herşeye 

dayanacağım hayretle...

yılbaşı geceleri geçecek

tanışma yıdönümleri, ardından...

beni bıçakladığın günler.

inatla sevdiğimi hatırlatacak

filmlerde sevgililerin oturduğu sedirler

 her otoyolda ''sen'' olacaksın

her karşı yöndeki ''ben''

iki yabancı gibi geçeceğiz

gişelerden...

dedim ya, sürecek işte hayat

sen kimi uyutsan da koynunda

kimse yanında duramayacak

ben, ölmüş prensleri beklerken

ya da göğsündeki taşın ''kalbe'' dönüşmesini

ya film kopacak 

ya da saat duracak...

ömrüme bir seccade sererken

hatırlayacağım hep öldüren sözlerini

söyle, ölürsem eğer

unutur  muyum ellerini?', 'Hayat, sensiz de  öyle ya da böyle sürecek işte kalkıp işe gideceğim sofralarım da olacak gecelerde kaşığı, elim ağzıma götürecek dönmemden ...', ARRAY['Türk Edebiyatı','Şiir','Ayşenur Yazıcı']::text[], 8.5, '{"poet":"Ayşenur Yazıcı","poet_slug":"aysenur-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/hayat-surecek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapına çiçek', 'kapina-cicek-i-syan-toprak-bgcev', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir çiçek bıraktım kapına 

Cami avlusuna 

Yasak aşkın tohumu bir çocuk bırakır gibi

Bitmiş tükenmiş umutlarımı

Ama bitmeyen aşkımı bıraktım kapına

Yüreğimi bırakır gibi

Bir çiçek bıraktım kapına

Kurşun bedeniyle kucaklaşınca

Son bir kez elveda der gibi

Ellerini havada sallayıp 

Toprağa bir tohum gibi düşen

Can dostumu yoldaşımı 

Orada öylece kurda kuşa yem bırakıp gider gibi

Bir çiçek bıraktım kapına

Bir uçurumun kenarında 

Beklediğimin bir daha hiç dönmeyeceğini öğrendiğimde

Tüm umutlarımı o uçuruma bırakır gibi

Bir çiçek bıraktım kapına

O uçuruma umutlarımla birlikte 

Kendimi bırakır gibi', 'Bir çiçek bıraktım kapına  Cami avlusuna  Yasak aşkın tohumu bir çocuk bırakır gibi Bitmiş tükenmiş umutlarımı Ama bitmeyen aşkımı bıraktım ...', ARRAY['Türk Edebiyatı','Şiir','İsyan Toprak']::text[], 8.5, '{"poet":"İsyan Toprak","poet_slug":"i-syan-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kapina-cicek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ferman (Her Gece)', 'ferman-her-gece-huseyin-demir-a4whv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kapı baca aradılar

Dağı taşı taradılar

Yollarını kapadılar

Ay ışığında her gece

Ay ışığı seyre durmuş

Seni sarp kayada görmüş

Çakal''lar izini sürmüş

Ay ışığında her gece

Namert kusmuş seslerini

Tanır diye yüzlerini

Bağlamışlar gözlerini

Ay ışığında her gece

Serrine ceryan salmışlar

Sır almayıp ser almışlar

Yaşadığından korkmuşlar

Ay ışığında her gece', 'Kapı baca aradılar Dağı taşı taradılar Yollarını kapadılar Ay ışığında her gece Ay ışığı seyre durmuş Seni sarp kayada görmüş Çakal''lar izin...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Demir']::text[], 8.5, '{"poet":"Hüseyin Demir","poet_slug":"huseyin-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ferman-her-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öldürdüğüm Yarim', 'oldurdugum-yarim-i-syan-toprak-lc8so', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dün yine seni gördüm

Simsiyah bir elbise içindeydin

Ve anlatabileceklerimin çok ötesinde güzel yüzünü bir Perçem kapatıyordu

Ellini uzatın 

Ellimi tutun

Göğsüne götürdün ellimi

Yüreğinin üstüne 

Bak kurşun yarası geçti

Ama bir yara varki içeride 

Bir acı varki yüreğimde

Geçmek bilmiyor dedin

Sırtını döndün ansızın

Hani beni çok sevmiştin

Kendin yatırdın ya başkasının koynuna

Hani bana dokunan elleri kırardın

Şimdi her yerimi başkası sarmalamakta

Söyle isyan toprak 

Nasıl dayanır yüreğin

Beni kara toprakla paylaşmaya dedin

Uyandığımda yatağım bomboştu

Seni çok özledim öldürdüğüm yarim', 'Dün yine seni gördüm Simsiyah bir elbise içindeydin Ve anlatabileceklerimin çok ötesinde güzel yüzünü bir Perçem kapatıyordu Ellini uzatın  ...', ARRAY['Türk Edebiyatı','Şiir','İsyan Toprak']::text[], 8.5, '{"poet":"İsyan Toprak","poet_slug":"i-syan-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/oldurdugum-yarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akıl sağlığı', 'akil-sagligi-aysenur-yazici-osaq6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir Hıdır ellezde dilemiştim seni ben

ellerini çizmiştim

boyunu posunu

çenendeki çukuru...

yüzümü gömeceğim göğsünün

sol yanını

avuçlarının kalıbını

düğmesi açık bağrını

kağıtlara çizdim

gül ağacının toprağına koydum

gözgöze eriyelim dedim

çok sevelim diledim

kabul oldu

sen düştün ömrüme birden! 

bir kadir gecesi sevdiğimi

bıraktım gül ağacı dibine öksüz öksüz

ne kadar sevdim bir bilsen

ne kadar çok seni

hıdır elleze söylemeyi unutmuşum

''hiç ayrılmayalım'' demeyi

bu hıdırellezde 

aynı gül ağacının dibine

cismini hiç çizmeden

''ismini''yazdım bıraktım 

bir de yüreğimdeki ağrıyı

tek bir dilek diledim: 

'' sana akıl sağlığı''....', 'Bir Hıdır ellezde dilemiştim seni ben ellerini çizmiştim boyunu posunu çenendeki çukuru... yüzümü gömeceğim göğsünün sol yanını avuçlarının ...', ARRAY['Türk Edebiyatı','Şiir','Ayşenur Yazıcı']::text[], 8.5, '{"poet":"Ayşenur Yazıcı","poet_slug":"aysenur-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/akil-sagligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kadın İçin', 'bir-kadin-i-cin-i-syan-toprak-qgoqw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir sonbahar akşamında aylardan eylül 

Yürüyordum İstanbulun tenha sokaklarında

Usulca yanıma yaklaşı verdi 

Gencecik biriydi

Bir kadın için ölmeye değer mi dedi

Beynim durdu 

Yüreğim konuştu

Değer değer 

Hemde bin kere değer dedim

Ellini attı beline 

Çekti silahını

Dayadı şakağına 

Engel olamadım

Bir kadın için kıydı canına...', 'Bir sonbahar akşamında aylardan eylül  Yürüyordum İstanbulun tenha sokaklarında Usulca yanıma yaklaşı verdi  Gencecik biriydi Bir kadın için...', ARRAY['Türk Edebiyatı','Şiir','İsyan Toprak']::text[], 8.5, '{"poet":"İsyan Toprak","poet_slug":"i-syan-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bir-kadin-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seval''e', 'seval-e-sair-evindar-bhyws', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'tenınde yak benı ey nazlı dılber

gozlerın ufuksuz bagrımda hancer

aynalara beles gulen dudaklarından; 

ruhuma bır tebessum, 

dudagıma bır buse ver', 'tenınde yak benı ey nazlı dılber gozlerın ufuksuz bagrımda hancer aynalara beles gulen dudaklarından;  ruhuma bır tebessum,  dudagıma bır bu...', ARRAY['Türk Edebiyatı','Şiir','Şair Evindar']::text[], 8.5, '{"poet":"Şair Evindar","poet_slug":"sair-evindar","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/seval-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Savaş', 'savas-gok-tengri-mahyb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben, sen, o, onlar

Herkes bir savaş halinde

Kimi ekmek için savaşır

Kimi yüzmek için petrol denizlerinde...', 'Ben, sen, o, onlar Herkes bir savaş halinde Kimi ekmek için savaşır Kimi yüzmek için petrol denizlerinde......', ARRAY['Türk Edebiyatı','Şiir','Gök Tengri']::text[], 8.5, '{"poet":"Gök Tengri","poet_slug":"gok-tengri","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/savas-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çekirdek, Sigara, Aşk', 'cekirdek-sigara-ask-alper-tunga-alp-v1i9p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çekirdek, sigara, aşk

Sen, ben, biz

Bu dünya

Hayır bu zaman

Belki de her an

Zor olan güzeldir 

Güzel olan bitmeden bırakıp gitmektir

Gitmektir zor olan

Ya başlamadan gitmek

Ya da bırakıp gitmek

Asıl gitmektir zor olan

Zor olanı başarmak

Başarı mıdır bitirip gitmek

Ya da gitmek ortasındayken

Ya da başlamışken

Ya da ölmek zor mudur

Yaşam dururken

Yaşamak mı zordur

Ölüm dururken

Ya sevgiye

Ya aşka

Ya dostluğa

Sigarasız bir dünyada

Çekirdeksiz yaşanır mı

Sigara gibidir aşk 

Tek farkı

Bitmemesi

Ölünceye kadar

Yüreğinin bir tarafında

Ya da 

Her tarafında

Her hücresinde

Her atomunda 

Her çekirdeğinde

Her noktasında 

Kısacası

Vücudunun

Ölünceye kadar 

Toprakla gerdeğe girinceye kadar

Söküp atamazsın

Çekirdeği

Vücudundan 

İlk geceden sonra biter mi dersin

Vücudun her parcası toprak oluncaya dek

Toprakta biten kardelen olur

Sigara

Bir kuşun kanadı

Bir ağacın yaprağı

Suyun damlası

Aşkı

Söküp atamazsın

Kıvrandırır seni

Acıtır

Öfkelendirir

Güldürür

Ağlatır

Ama söküp atamazsın

En iyisi hiç alışmamak

Sigaraya', 'Çekirdek, sigara, aşk Sen, ben, biz Bu dünya Hayır bu zaman Belki de her an Zor olan güzeldir  Güzel olan bitmeden bırakıp gitmektir Gitmekt...', ARRAY['Türk Edebiyatı','Şiir','Alper Tunga Alp']::text[], 8.5, '{"poet":"Alper Tunga Alp","poet_slug":"alper-tunga-alp","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/cekirdek-sigara-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serinlik', 'serinlik-umit-calik-s4f5l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'isteğimiz aşkın billur ırmaklarındaki serinlikse 

bir koşu bolunun çam kokulu dağlarından dolduralım ceplerimize..

bizi bir ömür serin tutsun diye

ikimiz aynı anda baktığımızda göğe yanyana gibi hissederiz gök oradada gök buradada 

bazan hüzünlü olur orada veya burada

 bizim hüznümüzü taşıyordur biliriz

 ama ürkütmesin 

nede sevgini eksiltsin 

yine berraklığına kavuşur 

yeterki beklemesini bil...', 'isteğimiz aşkın billur ırmaklarındaki serinlikse  bir koşu bolunun çam kokulu dağlarından dolduralım ceplerimize.. bizi bir ömür serin tutsu...', ARRAY['Türk Edebiyatı','Şiir','Ümit Çalık']::text[], 8.5, '{"poet":"Ümit Çalık","poet_slug":"umit-calik","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/serinlik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdayı taşıyan serinlik', 'sevdayi-tasiyan-serinlik-umit-calik-af8cr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'isteğimiz aşkın billur ırmaklarındaki serinlikse 

bir koşu bolunun çam kokulu dağlarından dolduralım ceplerimize..

bizi bir ömür serin tutsun diye

ikimiz aynı anda baktığımızda göğe yanyana gibi hissederiz gök oradada gök buradada 

bazan hüzünlü olur orada veya burada

 bizim hüznümüzü taşıyordur biliriz

 ama ürkütmesin 

nede sevgini eksiltsin 

yine berraklığına kavuşur 

yeterki beklemesini bil...', 'isteğimiz aşkın billur ırmaklarındaki serinlikse  bir koşu bolunun çam kokulu dağlarından dolduralım ceplerimize.. bizi bir ömür serin tutsu...', ARRAY['Türk Edebiyatı','Şiir','Ümit Çalık']::text[], 8.5, '{"poet":"Ümit Çalık","poet_slug":"umit-calik","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sevdayi-tasiyan-serinlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağlar', 'daglar-alper-tunga-alp-577is', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dağlar

Dünya dururdu sana sarıldığımda

Ve engel yokken tenlerimiz arasında

Bitmesinden korkardım 

Sende kaybolmak isterken

Ve Munzur’da

Ve Alpler’de

Gördüm seni

Bembeyazdı engel olan tenlerimize

Kaybolmak istedim dağların arasına

Ya da derinlik sarhoşluğuna

Ölümün, yok oluşun manzarasında', 'Dağlar Dünya dururdu sana sarıldığımda Ve engel yokken tenlerimiz arasında Bitmesinden korkardım  Sende kaybolmak isterken Ve Munzur’da Ve A...', ARRAY['Türk Edebiyatı','Şiir','Alper Tunga Alp']::text[], 8.5, '{"poet":"Alper Tunga Alp","poet_slug":"alper-tunga-alp","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/daglar-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kır çiçeği düşmüş yanaklarına', 'kir-cicegi-dusmus-yanaklarina-alper-tunga-alp-fqs52', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kır çiçeği düşmüş yanaklarına

Bahar kokmuşsun

Alev topu düşmüş yüreğime

Gözlerin güneş açmış

Bahar açmışsınız bende

O sende

Sen onda

Siz İstanbul’da

Siz İstanbul oldununuz bende

Ben siz oldum

İstanbul sizle

Ben İstanbulsuz

Biter mi bilmiyorum

Bu özlem

Biter mi

Tenin tene değmesiyle

O yatmış

Çukurova’nın sıcağında

Benden uzak

Sen kendinde

Kollarımdan uzak

İnmiş yüzüne

Dağların büyüsü

Küçücük gemiler yaparım

Batmamak için

İçine oturamam

Korkarım

Balık olmak isterim

Balıkadam oluveririm

Beceremem

Balıklar gibi özgürlüğü

İçiçe geçmiş iki ağaçtan biri olmak isterim

Diğeri sen

İçerim o yüzden gündüzleyin geceleyin

Leyin leyin

Ayık gezipte ne olacak

Hiç işte

Sevmek isterim seni kavgamın içinde

Kavgam yokki

Gün bahar açar gözlerine

Sabah sabah

Bir duble rakı

Bir şişe bira

Ya da kahve 

İçinde sen', 'Kır çiçeği düşmüş yanaklarına Bahar kokmuşsun Alev topu düşmüş yüreğime Gözlerin güneş açmış Bahar açmışsınız bende O sende Sen onda Siz İst...', ARRAY['Türk Edebiyatı','Şiir','Alper Tunga Alp']::text[], 8.5, '{"poet":"Alper Tunga Alp","poet_slug":"alper-tunga-alp","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/kir-cicegi-dusmus-yanaklarina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümüne Dair', 'olumune-dair-alper-tunga-alp-lktxh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gün ölür, 

	Gece ölür, 

		  Çiçek ölür

Yıldızlar görünmez, 

		   Ölür

Martılar konuşmaz, 	

		  Ölür

Sen susar

		  O ölür

Lanet olası ölüm', 'Gün ölür,  	Gece ölür,  		  Çiçek ölür Yıldızlar görünmez,  		   Ölür Martılar konuşmaz, 	 		  Ölür Sen susar 		  O ölür Lanet olası ölüm...', ARRAY['Türk Edebiyatı','Şiir','Alper Tunga Alp']::text[], 8.5, '{"poet":"Alper Tunga Alp","poet_slug":"alper-tunga-alp","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/olumune-dair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerim titriyor', 'ellerim-titriyor-alper-tunga-alp-ohrkd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ellerim titriyor

Sinirden, öfkeden

Okuduğum her kitap ve yazının içindeki cümlelerin, kelimelerin arasına giriyorsun

Seyrettiğim siyah-beyaz filimlerde sen de oynuyorsun

Bazen güzel, narin, sıcak, şirinlerin şirinesi bir hanımefendi

…

Dinlediğim müziklerin içinde bir nota oluveriyorsun birdenbire

inceden bir do

Çektiğim her nefeste sen de içime giriveriyorsun 

sigara dumanı ile birlikte.

Cigerlerime isleniyor nefesin

Ve her öksürükte seni atmaya çalışıyor benliğim

Fakat öyle bir yer etmissin ki ben de, çıkartamıyorum 

Ve çıkıveriyorsun birdenbire karşıma 

Bu günlerde şiir yazmadan önce

Aldığım her bir yudum rakı boğazımdan kayarak yemek borusundan aşağıya mideme dogru yol alırken yolda uğradığı her bir hücereye bir parça kendinden, bir parça senden bırakıyor

Ve sen bu günlerde bir başkasını seviyorsun

“Mey içmişim bilir misin 

İlahi aşk renginde.”

Ve ben günlerdir uykusuz

Ve ben günlerdir sebebsiz 

bekler oldum telefonunu

Gözlerim kan kırmızı.

Şarap nasıl içilir, bilirsin 

Önce alırsın bir yudum

Gözlerini kapatır

Ağzının içinde yuvarlarsın sonra

Her bir noktasında gezdirirsin

Her bir noktası duysun diye sıcaklığını

Ama sen son günlerde verdin bana 

Ekşimtrak sarımtrak kırımtrak

“Uzun sürdükçe süren beni götüren o imgen 

Taşıyacak şiirle uzun sürecek o imgem”

Bu şiir uzun sürecek sanırım

Olsun sürsün, o uzun sürdükçe 

Sana halen duyduğum hali vaktim  de uzayacak

Dalgıçların en büyük düşmanı vurgun yemektir

Bilir misin? 

Bir de derinliğe kapılmaktır aniden

Aniden uçrumdan düşmüşe dönersin.

Oksijenin biterse son umut A’ lamaya baslarsın bütün ağırlığını bırakıp başlarsın güneşi görebildiğin yere doğru yüzmeye

Eğer kalmamıssa ciğerlerinde bir parçacık umut patlayıverir ciğerlerin

Bom diye

Sigara en iyi dostumdur bilirsin

Rakıyı da çok severim bunu da bilirsin

ve sen bilmezsin ki çektiğim sigaradan

içtiğim rakıdan haz almaz ettin bugün beni

ve sen 

ve sen içimde yeniden doğmakta olan ikinci yıldızı daha gün yüzü göstermeden öldürdün 

öldürdün onu

ve sen seni bende yok ettin

çirkin gözlü güzel kız 

çirkin gözlü güzel kız 

sana kıyamam 

kızamam sana

ama ellerim titriyor

sinirden, öfkeden

ve sen bir başkasını seviyorsun bu günlerde', 'Ellerim titriyor Sinirden, öfkeden Okuduğum her kitap ve yazının içindeki cümlelerin, kelimelerin arasına giriyorsun Seyrettiğim siyah-beyaz...', ARRAY['Türk Edebiyatı','Şiir','Alper Tunga Alp']::text[], 8.5, '{"poet":"Alper Tunga Alp","poet_slug":"alper-tunga-alp","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/ellerim-titriyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim ne derse desin', 'kim-ne-derse-desin-alper-tunga-alp-emfny', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kim ne derse desin

Sen ne dersen de	

O ne derse desin

Ben ne dersem diyeyim

Bizler

Onlar

Ve digerleri ne derse desinler

Ve kantlar

Ve platolar

Ve marks

Ne derse desin

Ben seni seviyorum.

Ve ben soylerken seni sevdigimi, 

Seni severken

Ve seni seviyorum derken

Seni sevdigimi duyuyorum, seni sevmekten.

Ve seni sevmek bana aci verirken

Yazmak istiyor, bu el

Ve bu kalem

Ve bu kagit

Bu seni seviyorum diye bitecek bu kotu siiri.

Ve sen kizsanda bana

Ve sana

Ve ona 

Ve bizlere sizlere

Ve onlara

Ve digerlerine 

Yazdiriyor bu seni sevmek olayi

 bu lanet igrenc 

Bu seni seviyorumla bitecek siiri.

Ve sen su ise bak ki 

Gececek dedigin ‘seni seviyorum” meselesi son gunlerde iki uc dort siir

Ve bu seni seviyorumla bitecek olan

Seni seviyorum siiri

Ve sen verirsen bana izin

Daha cok yazmak isterim seni sevmekle ilgili siirler.

20.02.2003', 'Kim ne derse desin Sen ne dersen de	 O ne derse desin Ben ne dersem diyeyim Bizler Onlar Ve digerleri ne derse desinler Ve kantlar Ve platol...', ARRAY['Türk Edebiyatı','Şiir','Alper Tunga Alp']::text[], 8.5, '{"poet":"Alper Tunga Alp","poet_slug":"alper-tunga-alp","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/kim-ne-derse-desin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Orada sen', 'orada-sen-alper-tunga-alp-761h6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Orada sen

Burada ben

Orada sen ve ben

Burada ben ve sen

Orada hiç

Burada birimiz

Orada birimiz

Burada hiç

Aslında ben ve sen

Sen ve ben

Aslında hiç ve birimiz

Birimiz ve hiç

Aslında hiçbirimiz

Aslında orasıda burası da

Burasıda orası da

Sen de ben de 

Birimiz ve hiç 

Piç

İç

Hiç', 'Orada sen Burada ben Orada sen ve ben Burada ben ve sen Orada hiç Burada birimiz Orada birimiz Burada hiç Aslında ben ve sen Sen ve ben Aslı...', ARRAY['Türk Edebiyatı','Şiir','Alper Tunga Alp']::text[], 8.5, '{"poet":"Alper Tunga Alp","poet_slug":"alper-tunga-alp","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/orada-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uçuşuyor kelimeler etrafımda', 'ucusuyor-kelimeler-etrafimda-alper-tunga-alp-djfeb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uçuşuyor kelimeler etrafımda

Ben kör dilsiz

Uzanmış bir kadın 

Çıplak

Etrafımda dönen parmaklar

Şunu yap

Bunu etler

Etten bir duvar

Yapıyorlar felsefesini aşkın

Kafamın içinde parmaklar kelimeler

Kadınlar

Karanlık yıldızlar

Yolda

Kapanmış tüm ışıklar

İbre 80 i gösteriyor

Daha hızlı

Issız yollar sensiz

Beni çağırıyorlar

80 le 90 la dönüyor virajı

Yol vermiyor karanlıklar

Aydınlatmıyor ışıklar

Artık 

Kelimeler parmaklar

Beynimde dolanıyorlar

Ben sana

Beni de kat diyorlar

Kelimeler parmaklar

Sana yazılan bu şiire', 'Uçuşuyor kelimeler etrafımda Ben kör dilsiz Uzanmış bir kadın  Çıplak Etrafımda dönen parmaklar Şunu yap Bunu etler Etten bir duvar Yapıyorl...', ARRAY['Türk Edebiyatı','Şiir','Alper Tunga Alp']::text[], 8.5, '{"poet":"Alper Tunga Alp","poet_slug":"alper-tunga-alp","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ucusuyor-kelimeler-etrafimda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yollar', 'yollar-alper-tunga-alp-uw9gj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yollar 

Ağaçlar

Güzel kuşlar

Evlerde

Işıklar

Bekleşiyorlar

Bu savaş 

Ne zaman

Bitecek

Diyorlar

Bu savaş 

Ne zaman

Bitecek bekleşiyorlar

Kuşlar

Ağaçlar

Güzel yollar

Ölüm 

Geldi

Baharda

Üşüyorlar

Çocuklar

İnsanlar', 'Yollar  Ağaçlar Güzel kuşlar Evlerde Işıklar Bekleşiyorlar Bu savaş  Ne zaman Bitecek Diyorlar Bu savaş  Ne zaman Bitecek bekleşiyorlar Kuşl...', ARRAY['Türk Edebiyatı','Şiir','Alper Tunga Alp']::text[], 8.5, '{"poet":"Alper Tunga Alp","poet_slug":"alper-tunga-alp","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yollar-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yoktun', 'sen-yoktun-mehmet-polat-ew6kp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yalnızlık ve ben 

Şehri dolaştık bütün gün

Sevgili

Sen yoktun...

Konak''ta sinemaya girdik 

İki bilet alıp

Yanımdaki koltukta 

Sen yoktun...

Sinemadan çıkıp

İskelede aldık soluğu

Kimi yorgun

Kimi dalgın

Kimi neşeli insanlar gördük

Sen yoktun...

Vapurla Karşıyaka''ya geçtik

Denizde balıklar

Havada martılar

Gözlerde sevdalar gördük

Sen yoktun...

Vapurdan inip Çarşı''ya daldık

Kalabalığa karıştık

Sokaklarda açlığı gördük

Sahilden Bostanlı''ya yürürken

Ağaçlar gördük 

Dallarına kuşlar konmuştu

Sokaklar gördük 

Bomboştu

Sen yoktun...

Bostanlı''dan ver elini Göztepe''ye

Parkta gördük onları

İki kişiydiler

Yetmiş yaşlarında

Adam; 

Felç, tekerlekli sandalyede

Kadın; 

Arabayı itekliyor

Gözlerinde sevgiyle...

Sen yoktun

Göztepe''den Kordon''a yürüdük

Ayaklarımıza inat

Gülmeyen gözlere 

Boşa geçen günlere

İnsanlığın haline inat 

Ne kadar inat varsa 

Hepsine inat

Yürüdük! 

Ve 

Kordon''da cinayeti gördük

Ay, 

Güneşi vurmuş

Denize gömüyordu

Sevgili

Sen yoktun...', 'Yalnızlık ve ben  Şehri dolaştık bütün gün Sevgili Sen yoktun... Konak''ta sinemaya girdik  İki bilet alıp Yanımdaki koltukta  Sen yoktun... ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Polat']::text[], 8.5, '{"poet":"Mehmet Polat","poet_slug":"mehmet-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/sen-yoktun-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik Yıkar Beni', 'sensizlik-yikar-beni-gonul-ozdemir-cy4t5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gel güneşim ol ısıt beni, 

Yağmurum ol ıslat bu teni, 

Yarınlarıma umut ol yaşat beni, 

Biliyorsun aşk yorgunuyum ama

Ne aşk şarabı yıkar, ne kan şrabı, 

Sensizlik sensizlik, yıkar beni, yıkar beni...

6.4.2003      Gönül Özdemir    Bergkamen.', 'Gel güneşim ol ısıt beni,  Yağmurum ol ıslat bu teni,  Yarınlarıma umut ol yaşat beni,  Biliyorsun aşk yorgunuyum ama Ne aşk şarabı yıkar, n...', ARRAY['Türk Edebiyatı','Şiir','Gönül Özdemir']::text[], 8.5, '{"poet":"Gönül Özdemir","poet_slug":"gonul-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sensizlik-yikar-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmiyorum', 'bilmiyorum-ahmet-gafur-sahin-vh707', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hayat yolunda yorgun bir yolcuyum, Acılarla çilelerle doluyum.Yıkılıp kalacağım bir gün, Nerede ve nasıl, İşte onu bilmiyorum.', 'Hayat yolunda yorgun bir yolcuyum, Acılarla çilelerle doluyum.Yıkılıp kalacağım bir gün, Nerede ve nasıl, İşte onu bilmiyorum....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Gafur Şahin']::text[], 8.5, '{"poet":"Ahmet Gafur Şahin","poet_slug":"ahmet-gafur-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/bilmiyorum-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
