		aşkımızı', 'yalnız odamda yalnızca sen varsın hayalin büsbütün çıldırtıyor oysa burada olsan oysa  sesin sesime değse oysa bir kuş havalansa kalbimin uc...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Oğuz']::text[], 8.5, '{"poet":"Mehmet Ali Oğuz","poet_slug":"mehmet-ali-oguz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yalniz-odamda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'düşlerimdesin', 'duslerimdesin-mehmet-ali-oguz-njt2d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'düşlerimdesin

