INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevipde', 'sevipde-kopuk-yasar-p7f84', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevip de Terk Etmek İçin Değil, Ömür Boyu Sevmek İçin, 

Gülüp de Üzmek Değil, Hep Mutlu etmek İçin, 

Menfaatim İçin Değil, Uğrunda Ölmek İçin Varım..........', 'Sevip de Terk Etmek İçin Değil, Ömür Boyu Sevmek İçin,  Gülüp de Üzmek Değil, Hep Mutlu etmek İçin,  Menfaatim İçin Değil, Uğrunda Ölmek İçi...', ARRAY['Türk Edebiyatı','Şiir','Kopuk Yaşar']::text[], 8.5, '{"poet":"Kopuk Yaşar","poet_slug":"kopuk-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/sevipde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aksam Ayazı', 'aksam-ayazi-kopuk-yasar-r3l3i', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dudakların Kurursa Okyanusu Getiririm Sana

Akşam Ayazında Titrersen Güneşi Getiririm Sana

Kalbin Sevgi İsterse Beni Ara; 

Kalbimi Getiririm Sana........!', 'Dudakların Kurursa Okyanusu Getiririm Sana Akşam Ayazında Titrersen Güneşi Getiririm Sana Kalbin Sevgi İsterse Beni Ara;  Kalbimi Getiririm ...', ARRAY['Türk Edebiyatı','Şiir','Kopuk Yaşar']::text[], 8.5, '{"poet":"Kopuk Yaşar","poet_slug":"kopuk-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/aksam-ayazi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bak Bu Gunde', 'bak-bu-gunde-kopuk-yasar-kac6j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bak Bu Günde Akşam Oldu Sevgilim, 

İçimdeki Sızı Gittikçe Artıyor 

Sen Bunu Bilmezsin....... 

Gözüm Dalıyor Seni Düşünüyordum

Tam O Anda Seni Özlerken

Bir Yağmur Başladı Gözlerimde 

Önce Şaşırdım, Sonra Anladım

Sevgi Tanecikleriydi Onlar

Şimdi Biliyorum........

Gök Yüzünün Neden Ağladığını

Çünkü Oda Benim

Sana Olan Aşkım Gibi 

Yeryüzüne Aşıktı......', 'Bak Bu Günde Akşam Oldu Sevgilim,  İçimdeki Sızı Gittikçe Artıyor  Sen Bunu Bilmezsin.......  Gözüm Dalıyor Seni Düşünüyordum Tam O Anda Sen...', ARRAY['Türk Edebiyatı','Şiir','Kopuk Yaşar']::text[], 8.5, '{"poet":"Kopuk Yaşar","poet_slug":"kopuk-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bak-bu-gunde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Sevda', 'kara-sevda-kopuk-yasar-lyaey', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben Yarime Canım Derim

Gözüm Kırpmam Can veririm

Ben Seversem candan Sever

Ömür Boyu Yar Bilirim

Sen Hayatımsın, Tek varlığımsın 

Sen Benim Gül Kokulum, 

Vazgeçemem ki Canıma Cansın

Sen Kara Sevdamsın........!', 'Ben Yarime Canım Derim Gözüm Kırpmam Can veririm Ben Seversem candan Sever Ömür Boyu Yar Bilirim Sen Hayatımsın, Tek varlığımsın  Sen Benim ...', ARRAY['Türk Edebiyatı','Şiir','Kopuk Yaşar']::text[], 8.5, '{"poet":"Kopuk Yaşar","poet_slug":"kopuk-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kara-sevda-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Aldı Goturdu', 'hayat-aldi-goturdu-kopuk-yasar-rijei', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Zaman Her Şeyi Öğretir, Alışmayı da

Ama Ben Katlanamıyorum Bu Yokluğuna

Günler, Haftalar, Aylar Geçti; 

Alışamadım İnan Bana........

Hasret Ateşi Yaktı Kavurdu  Beni, 

Sensizlik Taaaa... derinden Vurdu Beni

Bende Çaresizim Gel Gör Beni

Hayat Aldı Götürdü

Başka Diyarlara Seni......!', 'Zaman Her Şeyi Öğretir, Alışmayı da Ama Ben Katlanamıyorum Bu Yokluğuna Günler, Haftalar, Aylar Geçti;  Alışamadım İnan Bana........ Hasret ...', ARRAY['Türk Edebiyatı','Şiir','Kopuk Yaşar']::text[], 8.5, '{"poet":"Kopuk Yaşar","poet_slug":"kopuk-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hayat-aldi-goturdu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Şeyımsın', 'her-seyimsin-kopuk-yasar-bxpus', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hayta En Çok Sevgiyi Hak Edecek Kadar Mükemmel 

Ama Herkesin Seni Sevmeyi Hak Edemeyeceği Kadar Özelsin....

Çünkü Sen Benim her şeyimsin.......!', 'Hayta En Çok Sevgiyi Hak Edecek Kadar Mükemmel  Ama Herkesin Seni Sevmeyi Hak Edemeyeceği Kadar Özelsin.... Çünkü Sen Benim her şeyimsin.......', ARRAY['Türk Edebiyatı','Şiir','Kopuk Yaşar']::text[], 8.5, '{"poet":"Kopuk Yaşar","poet_slug":"kopuk-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/her-seyimsin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin İçin Ölürüm', 'senin-i-cin-olurum-kopuk-yasar-5rwon', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dünyanın En Tatlı İnsanı, 

Sana İhtiyacım Olduğunu, 

Seni Çok Sevdiğimi Sakın Ama sakın Unutma........

Beni Unuttuğun Gün Ben Ölürüm! 

Senin Uğrunda Senin İçir Ölürüm...........!', 'Dünyanın En Tatlı İnsanı,  Sana İhtiyacım Olduğunu,  Seni Çok Sevdiğimi Sakın Ama sakın Unutma........ Beni Unuttuğun Gün Ben Ölürüm!  Senin...', ARRAY['Türk Edebiyatı','Şiir','Kopuk Yaşar']::text[], 8.5, '{"poet":"Kopuk Yaşar","poet_slug":"kopuk-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/senin-icin-olurum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Birisi Dokundu Sanki Bana', 'gece-birisi-dokundu-sanki-bana-kopuk-yasar-v8e4h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gece Birisi Dokundu Sanki Bana 

Telaşla Yataktan kalktım

Odamın Penceresine Doğru Yöneldim

Çisil Çisil Yağan Bir Yağmur Vardı.

Anladım ki  Göz yaşlarımdı Bu Yağmur, 

Ve Sen Yine Bana Ağlıyordun.....

Sakın Ağlama Sil Göz Yaşlarını

Bak Beni de Ağlatacaksın Sonunda, 

Durma Öyle Masum Masum, 

Gül Haydi Gururlan

Çünkü Tüm Duyguların Karşılıklı, 

Haydi Uyan Aç Gözlerini

Bak gecedeki Ses Ne Diyor; 

Seni çok Özledim.......

Hiç Hesapsız Çılgınca Özledim..

Seni Seviyorum Biriciğim...........!', 'Gece Birisi Dokundu Sanki Bana  Telaşla Yataktan kalktım Odamın Penceresine Doğru Yöneldim Çisil Çisil Yağan Bir Yağmur Vardı. Anladım ki  G...', ARRAY['Türk Edebiyatı','Şiir','Kopuk Yaşar']::text[], 8.5, '{"poet":"Kopuk Yaşar","poet_slug":"kopuk-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gece-birisi-dokundu-sanki-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Kadar Çılgınca Vursam dalgalara,', 'ne-kadar-cilginca-vursam-dalgalara-kopuk-yasar-mdi53', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne Kadar Çılgınca Vursam dalgalara, 

Sonuçta Ben Bir Rüzgarım.....

Oralara Esmeye Gücüm Olmasa da, 

Varlığımla Senin Yanındayım.....', 'Ne Kadar Çılgınca Vursam dalgalara,  Sonuçta Ben Bir Rüzgarım..... Oralara Esmeye Gücüm Olmasa da,  Varlığımla Senin Yanındayım........', ARRAY['Türk Edebiyatı','Şiir','Kopuk Yaşar']::text[], 8.5, '{"poet":"Kopuk Yaşar","poet_slug":"kopuk-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ne-kadar-cilginca-vursam-dalgalara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tenim Toprak Olsa da', 'tenim-toprak-olsa-da-kopuk-yasar-gukgv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tenim Toprak Olsa da 

Ruhum Seni Sevecek.....

İnan Mahşerde Bile

Gözyaşım Hiç Dinmeyecek......

Gözümü seninle Açtım 

Başkasını Göremem.....

Senden Başka Birine 

Sevgilim Diyemem........! !', 'Tenim Toprak Olsa da  Ruhum Seni Sevecek..... İnan Mahşerde Bile Gözyaşım Hiç Dinmeyecek...... Gözümü seninle Açtım  Başkasını Göremem..... ...', ARRAY['Türk Edebiyatı','Şiir','Kopuk Yaşar']::text[], 8.5, '{"poet":"Kopuk Yaşar","poet_slug":"kopuk-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/tenim-toprak-olsa-da-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya Adın Aklımda, Ya Aklım Adında....', 'ya-adin-aklimda-ya-aklim-adinda-kopuk-yasar-4zhk4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ya Adın Aklımda, Ya Aklım Adında....

Ya Sesin Kulağımda Ya Hayalin Karşımda...

Ya Çıldırıyorum, Ya Yaşarım’mı Çok Özlüyorum..

Ya Özlemek Güzel Yada Özlenen Güzel....', 'Ya Adın Aklımda, Ya Aklım Adında.... Ya Sesin Kulağımda Ya Hayalin Karşımda... Ya Çıldırıyorum, Ya Yaşarım’mı Çok Özlüyorum.. Ya Özlemek Güz...', ARRAY['Türk Edebiyatı','Şiir','Kopuk Yaşar']::text[], 8.5, '{"poet":"Kopuk Yaşar","poet_slug":"kopuk-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ya-adin-aklimda-ya-aklim-adinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günün Işığındasın Gecenin karanlığında....', 'gunun-isigindasin-gecenin-karanliginda-kopuk-yasar-kstkj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Günün Işığındasın Gecenin karanlığında....

Suyun Damlasında Selin Coşkusunda...

Bazen Yanımdasın, Bazen Rüyamda

Ama Hep Aklımdasın Bunu Sakın Unutma.......! 

Tek Yol Var Koştuğum Senin Uğruna

Tek Bir Şey Var Yaşadığım

Oda Senin Hasretin

Tek Bir Şey Var Söylediğim

Seni Çok Özledim Kara böceğim.....!', 'Günün Işığındasın Gecenin karanlığında.... Suyun Damlasında Selin Coşkusunda... Bazen Yanımdasın, Bazen Rüyamda Ama Hep Aklımdasın Bunu Sakı...', ARRAY['Türk Edebiyatı','Şiir','Kopuk Yaşar']::text[], 8.5, '{"poet":"Kopuk Yaşar","poet_slug":"kopuk-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gunun-isigindasin-gecenin-karanliginda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün Daha Geçti Acımasızca', 'bir-gun-daha-gecti-acimasizca-kopuk-yasar-adpuv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir Gün Daha Geçti Acımasızca

Senden Habersiz çok Uzaklarda

Ama Ben Biliyorum

Mesafelerde Olsa arada

Beni Arayacak Beni Unutmayacaksın

Günler Ay, Aylar Yıl Oluyor

İçimdeki Özlem Dinmek Bilmiyor

Duy Sesimi Ey Sevgili

Burada Bir Kız Bekliyor Seni

Ne Vakit Gelsen Aklıma

Hep ağlamaklı Oluyorum

İşte O An Seni Arıyor

Seni Özlüyorum

Ne Kadar da Yanımda Olmasan da 

Yine de Seni Seviyorum.....!', 'Bir Gün Daha Geçti Acımasızca Senden Habersiz çok Uzaklarda Ama Ben Biliyorum Mesafelerde Olsa arada Beni Arayacak Beni Unutmayacaksın Günle...', ARRAY['Türk Edebiyatı','Şiir','Kopuk Yaşar']::text[], 8.5, '{"poet":"Kopuk Yaşar","poet_slug":"kopuk-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bir-gun-daha-gecti-acimasizca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Seni Sensizde Yaşarım Sevdiğim...', 'ben-seni-sensizde-yasarim-sevdigim-kopuk-yasar-n5dg2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben Seni Sensizde Yaşarım Sevdiğim...

Bedeli Gözlerimde ki Yaşlardadır

Seni Düşlerim Hep, 

Aynı Yakarsın Tenimi

Ve Karşımda Hayalin

Gülümseyip Bana gelen......! 

Akşam Ağır Ağır Gecenin Koynuna İterken Beni....

Çok Zaman Ellerini ararım, 

Sarsın Diye Bedenimi.

Alıştığım Sıcaklığıyla Yüzünü Ararım, 

Başlayınca Kahrı Sensizliklerin......! 

				Biriciğim.........', 'Ben Seni Sensizde Yaşarım Sevdiğim... Bedeli Gözlerimde ki Yaşlardadır Seni Düşlerim Hep,  Aynı Yakarsın Tenimi Ve Karşımda Hayalin Gülümsey...', ARRAY['Türk Edebiyatı','Şiir','Kopuk Yaşar']::text[], 8.5, '{"poet":"Kopuk Yaşar","poet_slug":"kopuk-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ben-seni-sensizde-yasarim-sevdigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanımda Değilsin Biliyorum,', 'yanimda-degilsin-biliyorum-kopuk-yasar-4oodx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yanımda Değilsin Biliyorum, 

Ama Yanımdaki Hayalinden Vazgeçemiyorum....

Sen korkmasan da ben çok korkuyorum..

Seni kaybetmekte korkuyorum....! 

Senin Gözlerinde Sabahı Bulmak, 

Senin Kollarında Uyumak İstiyorum.

Senin İçin Yaşamak, 

Senin İçin Ölmek İstiyorum Bebeğim...

Eğer Ayrılık Denizde Tek Başına Kalmaksa

Ben Bir deniz Erkeğiyim..

Ve Gözlerin Kadar Güzel Bir Deniz de Yaşamak, 

Gözlerinin İçinde Boğulup Ölmek İstiyorum Bebeğim.....

Ya Sen Bir Meleksen

Ve Bende Bir Günahkar, 

Günahlarımın Hepsi Benim, 

Sevaplarımın Hepsi Senin Olsun

Çünkü Senin İçin Cehennemde Yanarak Ölmek İstiyorum Bebeğim...............!', 'Yanımda Değilsin Biliyorum,  Ama Yanımdaki Hayalinden Vazgeçemiyorum.... Sen korkmasan da ben çok korkuyorum.. Seni kaybetmekte korkuyorum.....', ARRAY['Türk Edebiyatı','Şiir','Kopuk Yaşar']::text[], 8.5, '{"poet":"Kopuk Yaşar","poet_slug":"kopuk-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yanimda-degilsin-biliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kader', 'kader-gunay-aktag-gr49l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dünya boş boş dönüyor 

Kalbim boş seni arıyor 

Ne fırtına dolduruyor yerini

Nede esen rüziğar avutuyor beni 

Yoklugunda seni arıyorum

Hasretinle aşkımı bağlamışım

Bitmiyor  gözümden iki damla yaşım

Bi çare gönlümü sana bağlamışım

Yokluğun  avutmuyor beni

seni arıyorum seni

Sensiz doğan günü sevmiyorum 

Senli günlerimi özlüyorum

iki gözüm iki çeşme (gülüm)

Ben bahtıma, 

Ben bahtıma ağlıyorum (kader) 

Günay Aktağ', 'Dünya boş boş dönüyor  Kalbim boş seni arıyor  Ne fırtına dolduruyor yerini Nede esen rüziğar avutuyor beni  Yoklugunda seni arıyorum Hasret...', ARRAY['Türk Edebiyatı','Şiir','Günay Aktağ']::text[], 8.5, '{"poet":"Günay Aktağ","poet_slug":"gunay-aktag","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kader-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamı Seyretmek', 'yasami-seyretmek-riza-aslan-0oy3q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'biz

yaşamayı becerememişiz

yaşamak sanmışız 

etrafımızda 

yaşamı, yaşayanları

seyretmeyi

el sallamışız hep

dolu giden vagonlara

akıp gitmiş geçmişimiz

paslı raylarda

düşünmemişiz hiç

o trene binmeyi

kolay olanı seçmişiz

yaşamı yamaktansa

seyretmişiz

hayalimizde elde ettiğimiz

sevgililerimizle

sevişmiş

onlarla tatmin olmuşuz

hep kendimizi düşünmüşüz

gemimizi kurtardığımız zaman 

kaptan

batırdığımız zamanlarda ise

tayfa olmuşuz

kendimiz için yaşamış

kendimiz için sevişmişiz

zevkin doruklarına çıktığımız

o güzel anlarda bile

tek kazanımımız

içimizdeki hayvanı doyurmak olmuş

yanıbaşımızda yatan

adına kimi zamanlar eş

kimi zamanlar karı-koca 

dediğmiz  varlıklar

egolarımızı tatmin etmek için

kullandığımız birer metaya 

dönmüşler

sevişirken eşimizle 

başkalarını hayal etmişiz

o da bir başkasını...

başkalarının kayıplarına sevinmiş

sevinçlerine üzülmüşüz

içimizdeki çocukla

hiç barışık olmamışız

onu beynimizin kıvrımlarına hapsetmiş

yok saymışız

anı

bu günü yaşayamamışız

aklımız ya geçmişimizde kalmış

ya da hayalini kurduğumuz

geleceğimizde

biz

yaşamayı becerememişiz

yaşamak sanmışız 

etrafımızda 

yaşamı, yaşayanları

seyretmeyi

08 Haziran 2003 

Bergama /İzmir', 'biz yaşamayı becerememişiz yaşamak sanmışız  etrafımızda  yaşamı, yaşayanları seyretmeyi el sallamışız hep dolu giden vagonlara akıp gitmiş ...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/yasami-seyretmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bence', 'bence-bora-alagoz-n7jup', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'şafağın soluğudur bu, gün yüzüne akan

elbette ki görebilir, hatta tüm sefiller...

hele ufukta beliren şu kızıllığa bir bakın...

ebediyen sürer

yanlarına kalır mı sanılır

ettikleri bunca zulüm, 

döktükleri  bunca kan, 

yaptıkları yağma/ talan

gün ışıyıp karanlığa deyince

buharlaşacak tüm karabasanlar

saf tutacaklar meydanlarda elbet

halaya duracaklar hakkın çocukları', 'şafağın soluğudur bu, gün yüzüne akan elbette ki görebilir, hatta tüm sefiller... hele ufukta beliren şu kızıllığa bir bakın... ebediyen sür...', ARRAY['Türk Edebiyatı','Şiir','Bora Alagöz']::text[], 8.5, '{"poet":"Bora Alagöz","poet_slug":"bora-alagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bence-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Önce Bir Kahve Yapsan', 'once-bir-kahve-yapsan-bora-alagoz-ann6y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ama önce bana bir kahve yapsan

ben ıslık çalsam

bu savaş gününde

derlenip toparlansam

boyacı ayakkabılarımı mavi getirse

yollar önümde açılır belki

belki tırmanırım bu defa

	akbabalar kayalığına.

Bir oyun tutturmuş cinler

bak, ta aşağılarda

                puslu vadinin dibinde

	               dönüp dururlar

		           kendi etrafında

	     - hop trilam da 

		 hop, hop trilam - 

Beklerler ki ayağım kaysın

düşüp yuvarlanayım 

	ayaklarının dibine.

Henüz dumanı üstünde

                bir sözle

	        gelen doğru bir kahve

ve lacivert bir ayakkabın olursa

en pörsü ruh bile

             doğrulabilir

                       devleşebilir 

         cüce bir bedende', 'Ama önce bana bir kahve yapsan ben ıslık çalsam bu savaş gününde derlenip toparlansam boyacı ayakkabılarımı mavi getirse yollar önümde açılı...', ARRAY['Türk Edebiyatı','Şiir','Bora Alagöz']::text[], 8.5, '{"poet":"Bora Alagöz","poet_slug":"bora-alagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/once-bir-kahve-yapsan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pis Bir Günün Suyunu İçtim', 'pis-bir-gunun-suyunu-i-ctim-bora-alagoz-ks2dy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çekimine kapıldım

	Fır dönüyorum yörüngesinde

Pis bir günün suyunu içtim

Ruhumda met-cezir 

Hangi kıyıyı basacak

Nereye kadar çekilecek

		Belli değil

Pis bir günün suyunu içtim

Mavi değil rüzgar

Tüm renkler kırmızı

Kanatlarım yağmur yemiş

	Bedenim hantal

		Uçamıyorum

Fasit bir dairedir çizdiğim

Şu dağı bu dağla buluştursam

Bu ovayı o ova ile konuştursam

Hep bir araya gelsek

Orman ile su ile tanıştırsam

Bu sis dağılır

Pussak kalkar

Güneş yeniden doğar belki

Belki ay aydınlık olur geceleri

Yıldızlar döner gökyüzüne yeniden

Ey rüzgar sarmalı

Gecede yürüyen kızıl korku

Düşlerimin yağmacısı

Bedensiz düşman

Yüreğimin aynasında görüyorum

Kara cahil suratın

 Nanik yapıyorsun bana

Elinde cehlin tuzakları

Kestim diyorsun yollarını

Sağın solun çevrili

Teslim ol diyorsun bana

Hayır

Dehşetle bağırıyorum hayır

Sesim yutuluyor mayalanmış havada

Soluyor bedenim

Sol elimin ayasına çarpıyor sesin

İğrenç bir kokuya dönüşüyor

	Geriye yansıyor nefesin

Bir daha hayır diyorum

Bin daha

Birleşip çoğalıyor

Gök gürültüsüne dönüşüyor sesim

Doğruluyorum dizlerimin üstünden

Yumruğum sıkılmış

Ayaklarım yana açık

Gözlerim hedefe kilitli', 'Çekimine kapıldım 	Fır dönüyorum yörüngesinde Pis bir günün suyunu içtim Ruhumda met-cezir  Hangi kıyıyı basacak Nereye kadar çekilecek 		Be...', ARRAY['Türk Edebiyatı','Şiir','Bora Alagöz']::text[], 8.5, '{"poet":"Bora Alagöz","poet_slug":"bora-alagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/pis-bir-gunun-suyunu-ictim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'At ile Mezar', 'at-ile-mezar-bora-alagoz-hcago', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'başını kaldırıp baktı uzaklara

yelelerinde mavi bir rüzgar

eşeledi toynaklarıyla titreyen toprağı

inatla susuyordu önündeki mezar', 'başını kaldırıp baktı uzaklara yelelerinde mavi bir rüzgar eşeledi toynaklarıyla titreyen toprağı inatla susuyordu önündeki mezar...', ARRAY['Türk Edebiyatı','Şiir','Bora Alagöz']::text[], 8.5, '{"poet":"Bora Alagöz","poet_slug":"bora-alagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/at-ile-mezar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülün Ömrü', 'gulun-omru-mehmet-sari-sy74u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ve açtı küçük gözlerini tomurcuk, 

Çevirdi yüzünü güneşe karşı

                                 gülümsedi.

Ve onu korumak için diken, 

Sardı ayak ucuna kadar gövdesini, 

                                  çevreledi.

Ve bir çift el uzandı üzerine, 

Biri boynunu tuttu, 

Diğeri bir makas sapladı böğrüne, 

                                        kesti.

İşte insanların dünyası, 

Dün toprağa sevgiyle dikti, 

Bugün elleriyle yok etti.', 'Ve açtı küçük gözlerini tomurcuk,  Çevirdi yüzünü güneşe karşı                                  gülümsedi. Ve onu korumak için diken,  Sardı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sarı']::text[], 8.5, '{"poet":"Mehmet Sarı","poet_slug":"mehmet-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gulun-omru-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Şiir', 'son-siir-nilgun-polat-84i6v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu nasıl bir üşüme kalbim

Hızla çekiliyorum senden

Son şiiri beklemeyeceğim', 'Bu nasıl bir üşüme kalbim Hızla çekiliyorum senden Son şiiri beklemeyeceğim...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Polat']::text[], 8.5, '{"poet":"Nilgün Polat","poet_slug":"nilgun-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/son-siir-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Seni Seveceğim', 'ben-seni-sevecegim-mehmet-altintas-t75nj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İlk Ben Öğrettim Sana Aşkı

İlk Ben Yaşattım Sana Mutluluğu

Nerelerdesin Şimdi? 

Yaralı Gönlümün Taze Tomurcuğu.

Gözümün İlk Ağrısısın

Başımın Tatlı Belası

AsLan_YuReK''imin Deli Sevdası

Ömrümün Diğer Yarısı

Olmayacak Benim İçin Artık Senden Sonrası.

Ben Seni Seveceğim

Sen İstersen Beni Sevme

Adını Dilimden Düşürmeyeceğim

Sen İstersen Beni Bilme.

Ben Ölürsem Sakın Benim İçin Üzülme

Ben Zaten ölüyüm

Yaşıyorsam Bilki, 

Sana Olan Sevgimin Yüzüne...', 'İlk Ben Öğrettim Sana Aşkı İlk Ben Yaşattım Sana Mutluluğu Nerelerdesin Şimdi?  Yaralı Gönlümün Taze Tomurcuğu. Gözümün İlk Ağrısısın Başımı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Altıntaş']::text[], 8.5, '{"poet":"Mehmet Altıntaş","poet_slug":"mehmet-altintas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ben-seni-sevecegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçe Kapanış Saatleri', 'i-ce-kapanis-saatleri-nilgun-polat-3ou7y', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'saçlarında pas kokuyor yağmur

az sevilmiş taşralı kızlar gibi

herkes kendine kırılıyor, kırılsın

şimdi sen

bu şiirden kaç kere geçtiğini bilmeden

ıssız bir dağ gibi ağla istersen

düşler için geç kalmışım sözüm yok

her şeyi yanıltan ellerinmiş aslında

köhne bir gemi yalnızlığı benimki

üstünde değil hüznün altında', 'saçlarında pas kokuyor yağmur az sevilmiş taşralı kızlar gibi herkes kendine kırılıyor, kırılsın şimdi sen bu şiirden kaç kere geçtiğini bil...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Polat']::text[], 8.5, '{"poet":"Nilgün Polat","poet_slug":"nilgun-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ice-kapanis-saatleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Liselim', 'liselim-mehmet-altintas-edtcu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ömrümün En Güzel yıllarını Alıpta Gittin

Yaktın Beni, Yıktın, Mecnun! a Çevirdin

Güzelim Dünya''yı Bana Zindan Ettin

Çok Zalimsin, Vefasız Liselim.

Ben Sana Mutluluk, Sen Bana Acı Verdin

En Güzel Duygularımı Acımadan yok Ettin

Şu Masum Kalbime Şeytan Gibi Nerden''de girdin? 

Çok Zalimsin Vefasız Liselim.

Anladım Sen Aşk Nedir Bilmezsin

Seni Seveni Daima Üzersin

Zaten Sende Kalp Yokki

Sevmesinide Bilmezsin.

Çok Zalimsin Vefasız Liselim.

Siyahtır Saçların Eladır Gözlerin

Yoktur Bu Dünya''da İnanki Bir Benzerin

Bu Şiir''im yanlızca Sana Olan Sitemim

Çok Zalimsin Vefasız Liselim.', 'Ömrümün En Güzel yıllarını Alıpta Gittin Yaktın Beni, Yıktın, Mecnun! a Çevirdin Güzelim Dünya''yı Bana Zindan Ettin Çok Zalimsin, Vefasız Li...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Altıntaş']::text[], 8.5, '{"poet":"Mehmet Altıntaş","poet_slug":"mehmet-altintas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/liselim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaz Ortasında Esen Ilık Rüzgar', 'yaz-ortasinda-esen-ilik-ruzgar-melih-coskun-2z2dl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yaz ortasında esen 

Ilık bir rüzgardın sen 

Islak yüzümde izini bırakan

Bütün ayrılıkların özetiydin sen 

Tüm ömrümü sığdırdığım 

Birkaç satırına

İçimi kavuran bu sıcaklık 

Güneşten değil 

Yanlış zamanlarda sevdik hep biz 

Girdiğimiz bütün sokaklar çıkmazdı 

Yine de titreten bir şey vardı içimizi, 

Acıtsa da

Kanatsa da 

Yürü bu yolda 

Usanmadan, yorulmadan 

Diyen bir ses vardı kulaklarımızda 

Bir şey vardı

Kaçsak bile

Bizi acıların koynuna çeken... 

Korkuyorum 

Bu sıcak 

Yakacak yakınlarda içimde bir yerleri 

Ve kaçsam da izi hep kalacak 

Islak yüzümde rüzgarının...

21 Nisan 2003

16:26', 'Yaz ortasında esen  Ilık bir rüzgardın sen  Islak yüzümde izini bırakan Bütün ayrılıkların özetiydin sen  Tüm ömrümü sığdırdığım  Birkaç sat...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yaz-ortasinda-esen-ilik-ruzgar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ŞEREFE', 'serefe-nadir-akgun-45btd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir duble viski istedi

arkadaşlarıda yanında

muhabbetleri koyu

çokta kalabalık masa

yapacakları işleri anlatıyorlar

ne kanun dinliyorlar ne yasa...

biri

ortaya çıkmaz dedi

ben yakalanmam

ben yakalarım diyor diğeri 

                                          gülerek

zaten benim işim bu

bütün masa gülüyor

                                          içkileri içerek

kadehler boşalıyor 

tekrar doluyor hemen 

ve işte yine havadalar

ŞEREFE! 

diyor biri

belliki milletvekili

kadehi tutuşundan belli

sıkı sıkı sarılmış

diğeri atladı hemen 

bu da neyin şerefi

buda mafya olmalı

en rahatı masada

masanında sahibi

bağırdılar hep bir ağızdan

ŞEREFE! 

tokuşsun kadehler yine

şerefsizliğin şerefine', 'bir duble viski istedi arkadaşlarıda yanında muhabbetleri koyu çokta kalabalık masa yapacakları işleri anlatıyorlar ne kanun dinliyorlar ne ...', ARRAY['Türk Edebiyatı','Şiir','Nadir Akgün']::text[], 8.5, '{"poet":"Nadir Akgün","poet_slug":"nadir-akgun","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/serefe-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Care', 'ne-care-selahattin-yaz-ku23i', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu dünyada hatır gönül bilmedik, 

Eğriyi doğruyu hesap etmedik, 

Haybeye harcadık ömrü tükettik, 

Üzülsek ağlasak şimdi NE ÇARE.

Sen dedin ben dedim kavgalarından 

Yıllarca yapılan yanlışlıklardan, 

Bozuldu dengeler sağlık kayboldu, 

Olmayınca merhem varmı BİR ÇARE.

Talih kuşu başa hep konar sandık, 

Hayalle yaşadık çok şeyler umduk, 

Koymadık kenara ne varsa yuttuk, 

Kafayı taşlara vursak NE ÇARE.

Anaya babaya saygı duymadık, 

Söylenen sözlere kulak asmadık, 

Yaşarken ağlattık haya etmedik, 

Mezarı mermerden etsek NE ÇARE

Akraba hatrını benimsemedik, 

Kardeşin hakkını bilerek yedik, 

Komşular aç iken görmezden geldik, 

Nafile naz, mazı kılsak NE ÇARE

Makamın şöhretin biteceğini, 

Malında pulunda kalacağını, 

AZRAİL''in bir gün alacağını, 

Düşündük geç kaldık şimdi NE ÇARE.

Okunan selaya kulak verilir, 

Bitince arkadan isim söylenir, 

Ah denir vah denir rahmet okunur, 

TABUT''a girersin yoktur BİR ÇARE.

Huzurda diz bağı mutlak çözülür, 

Haklılar haksızlar ayırt edilir, 

Orası MAHŞERDİR hesap görülür, 

Treni kaçırdık şimdi NE ÇARE.', 'Bu dünyada hatır gönül bilmedik,  Eğriyi doğruyu hesap etmedik,  Haybeye harcadık ömrü tükettik,  Üzülsek ağlasak şimdi NE ÇARE. Sen dedin b...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Yaz']::text[], 8.5, '{"poet":"Selahattin Yaz","poet_slug":"selahattin-yaz","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ne-care-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırmızı Gül', 'kirmizi-gul-engin-namli-fm97n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir akşam şöyle uzandım hayallere daldım

Çarsı çarsı dolaştım bir kırmızı gül aldım 

Damıttım gönlümde yarin ellerine çaldım

Hazdan bir hal oldu içim gönül kervanında 

Sabaha dek dalgalandı üfledigim teller 

İki elimde dondu kınaladığım eller 

Yorgun düştü iltifatlarım lal oldu diller 

Hazdan bir hal oldu içim gönül kervanında 

Gün doğana kadar ısındı kanım,kanında 

Sanki yüreğim nefes buldu tatlı canında

Bu kadar mutlu olmadım kimsenin yanında 

Hazdan bir hal oldu içim gönül kervanında 

 ENGİN NAMLI', 'Bir akşam şöyle uzandım hayallere daldım Çarsı çarsı dolaştım bir kırmızı gül aldım  Damıttım gönlümde yarin ellerine çaldım Hazdan bir hal ...', ARRAY['Türk Edebiyatı','Şiir','Engin Namlı']::text[], 8.5, '{"poet":"Engin Namlı","poet_slug":"engin-namli","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kirmizi-gul-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-wilhelm-reich-hlt4r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Binlerce yılın bakış açısından

görebiliyorum seni, 

binlerce yıl geçmişten ve  binlerce yıl gelecekten 

bakıyorum sana.

Kendinden korkma duygundan 

kurtulmanı istiyorum

Daha mutlu 

ve daha insana yaraşır 

bir yaşam sürmeni istiyorum.

Kasılmış bir beden yerine, 

canlı, yaşayan bir bedenin olsun istiyorum; 

çocuklarından nefret etmek yerine 

onları sevmeni, karına, 

evlilik gereği, 

işkence yapmak yerine 

onu

mutlu etmeni istiyorum.', 'Binlerce yılın bakış açısından görebiliyorum seni,  binlerce yıl geçmişten ve  binlerce yıl gelecekten  bakıyorum sana. Kendinden korkma duy...', ARRAY['Türk Edebiyatı','Şiir','Wilhelm Reich']::text[], 8.5, '{"poet":"Wilhelm Reich","poet_slug":"wilhelm-reich","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hayat-89-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canışığım', 'canisigim-oguzkan-bolukbasi-7ead9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'canışığım

ben sana aşığım

bir hançer gibi saplısın yüreğimde

çıkarmak istemediğim

seni ıssız bir gecede

sokak lambalarının altına

terketmeye çalışıyorum

kıyamıyorum

sensiz de olsa

seni yaşamaya doyamıyorum

sabah bir renkken gözlerin

akşam başka renklere dönüyor

sen açtın mı gözlerini canışığım

şehrin ışıkları sönüyor

saçlarını tarıyorum usuldan

gözlerinde baharlar açıyor

güvercinler su içerken ellerimden

haberler bekliyorum

yagmur kokulu seher yellerinden

gelmiyor

hüznümü gülüşlerimde gizliyorum

kaç bahar kaldı ömrümüzde

kaç gece düş görebileceğimiz

hasrete katmışız günlerimizi

gün diyebileceğimiz

canışığım

bu akdeniz ikliminde

rüzgara verdim ömrümün yelkenini

o yüzden dalgalı

o yüzden karışığım

her yönden geliyor kokun, sesin, nefesin

ne tarafa gideceğim

karar veremiyorum

gökkuşağının arkasındasın

ufuk çizgisindesin

gemiler yaklaştıkça uzaklaşan limanlardasın

biliyor musun

aslında yalnızca benim söylediğim şarkılardasın

bir anlasam

kaç ışık yılı uzaktasın

bu yollar hiç bitmiyor

ben sana hiç ulaşamıyorum

ben hep başındayım yolların

hep sarılmaya açık kollarım

sabah bir renkken gözlerin

akşam başka renklere dönüyor

sen açtınmı gözlerini canışığım

gökte yıldızlar sönüyor

canışığım

bu yaşadığım

bitmesidir kocaman bir kalabalık yalnızlığın

çiçeklerin açması

yağmurların yağmasıdır

ve yansıyan sulardan, pırıl pırıl

senin aydınlığın

ellerini uzat al beni, götür

nereye diye sormayacağım

sen durmadan

ben durmayacağım

sabah bir renkken gözlerin

akşam başka renge çalıyor

hüzün varsa gözlerinde canışığım

aklım sende kalıyor

sesini duymaya koşuyorum

şarkılar çalıyor sanki

sanki düğün var, coşuyorum

geceyi içmiş bir sarhoşun yorgunluğunda

son sigaramı yakıyorum gün doğarken

karşımda kızıl bir tanyeri

yakamozlar çekilmiş sulardan

düşüyor toprağa yavaşça

güneşin renkleri

canışığım

sen uykudasındır şimdi

öperek çıktığımı hissettin mi odadan

bin yıllık geleneği hiç bozmadan

bu masalı kim taşıyacak yarına

bu güzelliği kim anlatacak çocuklarına

bu şiirlerde kim anacak beni

sabah bir renkte açarken gözlerini

akşam bir başka renkte görüyorum

sen güldün mü gözlerini canışığım

bir derviş gibi etrafında dönüyorum

kolay mı sanıyorsun

gecede yıldız, yürekte ateş olmak

kolay mı sanıyorsun

çiçeği soldurmadan, 

ateşi söndürmeden yaşamak

kolay mı karanlıkta yol bulmak

canışığında saklanmak

gözyaşı dökmeden ağlamak

hayatın manasını bir su damlasında bulmak

bir su damlasında

ruhunu yıkamak

tertemiz kalmak

inanki meleğim

sakındığım, esirgediğim

sevdiğim, gözbebeğim

en güzel baharlarda hep seninleyim

sabah renklerini ışıtırken gözlerin

akşam yıldızları yansıtıyor

sen yumdun mu gözlerini canışığım

karanlık beni korkutuyor

içimden hazanları silip de atıyorum

hayatın akışına kendimi bırakıyorum

bir mahcup duyguydun bende

bir dışa çıkmaz sevgi

patlamaz volkan gibi gizli gizli yanarak

yağmayan yağmur gibi bulutlarda kıvranarak

geçen zamana ah edip de dağılarak

yaşamak pek anlamsız

yaşamayı yok edip

elimde kalan ömrüm nerde bitecek bilmem

mutluluk varsa eğer

bil ki artık kaçırmam

alev alev yanacak içimde canışığım

hayat ne kadar güzel

ben hayata aşığım

sabah tenime değince gözlerin

akşam ruhumu coşturuyor

sen baktın mı gözlerinle canışığım

içimi sevdan dolduruyor', 'canışığım ben sana aşığım bir hançer gibi saplısın yüreğimde çıkarmak istemediğim seni ıssız bir gecede sokak lambalarının altına terketmeye...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":122,"source_url":"https://www.antoloji.com/canisigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Manşet Rüyası', 'manset-ruyasi-nuri-ozlu-aagmi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '...yerde uzanan bir cesedin 

üzerine örtülmüş gazetenin üstündeki

deniz resmi kadar huzur veriyorsun bana..

agzımda kesici bir cisim varken gülemiyorum(özür)

sen bana emir vermeden asamam kendimi unutma! ...

unutma beni sadece uyu, 

uyu ve beni bekle

beni bekle ve uyu...

....', '...yerde uzanan bir cesedin  üzerine örtülmüş gazetenin üstündeki deniz resmi kadar huzur veriyorsun bana.. agzımda kesici bir cisim varken ...', ARRAY['Türk Edebiyatı','Şiir','Nuri Özlü']::text[], 8.5, '{"poet":"Nuri Özlü","poet_slug":"nuri-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/manset-ruyasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dizdize', 'dizdize-fatma-ful-ozok-3pm5e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gelmişler yetmişlerine

Hala gözgöze, dizdize

Sevgiyle bakıyorlar

Birbirlerine..

Titriyor elleri, 

Hemde yürekleri..

Bekliyorlar özlemle

Bayramda sevdiklerini.

Tutunuyorlar birbirlerine

Elele, dizdize..

Hala sevgi sözcükleri 

Dökülüyor dillerinden, 

Suskunken de gözlerinden..

Aşk bu olsa gerek

Ezelden ebede giden...', 'Gelmişler yetmişlerine Hala gözgöze, dizdize Sevgiyle bakıyorlar Birbirlerine.. Titriyor elleri,  Hemde yürekleri.. Bekliyorlar özlemle Bayr...', ARRAY['Türk Edebiyatı','Şiir','Fatma Ful Özok']::text[], 8.5, '{"poet":"Fatma Ful Özok","poet_slug":"fatma-ful-ozok","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/dizdize-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alışamadım', 'alisamadim-yasar-aslan-ulnef', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Rüzgar gözüme toz atar,

Yağmur üstüme üstüme akar, 

Eğilip suyu sevmesine alıştım,

Nemlenmeye alıştım,

Sensiz göz dökmeye alışamadım.

Nefesim kesildi her sevgi sözcüğünü duyduğumda,

savrulmalara alıştım,

kokunsuz rüzgarlara alışamadım.

aşk yaktı her  yanımı her deminde zamanın

diri diri yanmalara alıştım

sensiz ateşlere alışamadım

Dağların kar suyundan çay demledim her gece,

çiçeksiz mevsimde kaldım,

Ben ayazlara alıştım.

Seni sensiz yaşamaya, 

Bir de yokluğuna alışamadım.

seni saklayan bulutlara 

sen kokmayan çiçeklere

seni bana getirmeyen güneşe 

alışamadım

alışamadım

E-kart', 'Rüzgar gözüme toz atar, Yağmur üstüme üstüme akar,  Eğilip suyu sevmesine alıştım, Nemlenmeye alıştım, Sensiz göz dökmeye alışamadım. Nefesi...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Aslan']::text[], 8.5, '{"poet":"Yaşar Aslan","poet_slug":"yasar-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/alisamadim-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kal', 'kal-ozcan-ozkan-r0ur1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yazın sıcak günlerinde

Saçlarımın serin ormanlarına dal

Kışın karlı gecelerinde

Dudaklarımda kal

      

(1972)', 'Yazın sıcak günlerinde Saçlarımın serin ormanlarına dal Kışın karlı gecelerinde Dudaklarımda kal        (1972)...', ARRAY['Türk Edebiyatı','Şiir','Özcan Özkan']::text[], 8.5, '{"poet":"Özcan Özkan","poet_slug":"ozcan-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kal-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ISTIYORUM', 'istiyorum-seref-kaya-rgh82', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben aglarken agliyan

Ben gülerken gülen, 

Ben söylemeden.beni bilen

Beni yalniz, beni seven bir sevgili istiyorum.

Duygulari ucsuz bucaksiz

Düsünceleri denizlerden derin

Sevgisi erisilmiyen evren

Rüyalarimdaki bir melek, bir sevgili istiyorum.

Kisileri, kisi olarak tanimliyan

Yalanla dogruyu ayirabilen

Bos seyleri kiskanmiyan

Kendine daima güven duyan, bir sevgili istiyorum.

Varligimla.yoklugumla bir olan

Dünyayi bir göz olarak paylasan

Benim kadar cocuklarla kaynasan

Benim sevgimi hic bir sevgiyle paylasmayan, bir sevgili istiyorum...

                                                                         seref kaya  Frankfurt', 'Ben aglarken agliyan Ben gülerken gülen,  Ben söylemeden.beni bilen Beni yalniz, beni seven bir sevgili istiyorum. Duygulari ucsuz bucaksiz ...', ARRAY['Türk Edebiyatı','Şiir','Şeref Kaya']::text[], 8.5, '{"poet":"Şeref Kaya","poet_slug":"seref-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/istiyorum-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TERK EDINCE BENI!', 'terk-edince-beni-seref-kaya-q69wh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir gün anliyacaksin beni

Kiskaninca aptallastigimi

Kiskandirilinca cildirdigimi

Sevince beni duruldugumu

Anliyacaksin bir gün

Nelerin bos oldugunu

Hele terk edince beni

Ne kadar sevdigini.....

                                              seref kaya  frankfurt', 'Bir gün anliyacaksin beni Kiskaninca aptallastigimi Kiskandirilinca cildirdigimi Sevince beni duruldugumu Anliyacaksin bir gün Nelerin bos o...', ARRAY['Türk Edebiyatı','Şiir','Şeref Kaya']::text[], 8.5, '{"poet":"Şeref Kaya","poet_slug":"seref-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/terk-edince-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GerçekYalan', 'gercekyalan-sule-aydemir-0aepw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yalan hangi tarafta 

söyleyene mi dinleyene mi

söylendi

söyleyen yalanın yalan 

olduğunu bildi

dinleyen kilitli kaldı gerçekte

ta ki 

bir gerçeğin kırılışına kadar

yalanda takılı kalıp mutluluğu sahte olana

belki bu yüzden kızmadı hiç kilitli olan

ki 

yalangerçekte güzeli yakalamıştı

yalan söyleyende kaldı kabuslar

hiç olmamıştı söyledikleri kadar

yalangerçeğe dönüşte

olamadıkları

terk vardı

ağladı ağladı

gözyaşları kadar yalandı', 'yalan hangi tarafta  söyleyene mi dinleyene mi söylendi söyleyen yalanın yalan  olduğunu bildi dinleyen kilitli kaldı gerçekte ta ki  bir ge...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gercekyalan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmenin Anlamı', 'sevmenin-anlami-sule-aydemir-deff5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir kuş kadar özgür 

kanatları kırılmış 

bir kuş ne kadar özgürse! 

kelebek kadar ömrü 

ömrü sevdaları kadar 

biri söylemişti; 

köpek bile tekmelenerek sevilmez! 

ya 

köpek için sevgi 

tekmelenmekse! 

o zaman 

hiç sevilmek istemezse! 

temmuz 2002', 'bir kuş kadar özgür  kanatları kırılmış  bir kuş ne kadar özgürse!  kelebek kadar ömrü  ömrü sevdaları kadar  biri söylemişti;  köpek bile t...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevmenin-anlami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-agah-ozbek-gva2i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Arama sen düşmanlığı

Kendin yarattın

Onu öldürdün ama

Sen ölemeyeceksin! 

                          09-06-03', 'Arama sen düşmanlığı Kendin yarattın Onu öldürdün ama Sen ölemeyeceksin!                            09-06-03...', ARRAY['Türk Edebiyatı','Şiir','Agah Özbek']::text[], 8.5, '{"poet":"Agah Özbek","poet_slug":"agah-ozbek","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sen-261-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeşil-Mavi', 'yesil-mavi-naime-erlacin-y90j3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir ütopya lazım Taormina! *

- dileğin sakin bir limansa 

bana gel -

demiştin de 

kuytuda sakladım seni 

kıyametsi ayazlar 

derin uykularda

yüreğim avuçlarında

severim kıyıları

sessizliği

uzak durmayı denizden

bilmezdim oysa 

yaşamak tutsaklıkmış

ıpıssız bir adada

gün gelir

yaşam eskici dükkânı

al…sat 

al….sat

kapanır dükkân

hani saçımın her teli dünyaydı benim

dünya şimdi sırtımda! 

yeşil-mavi''yi arıyorum 

mavi-yeşil

yemyeşil

Taormina

*Taormina: Okura pek çok çağrışımlar yaptırmaya müsait olan bu isim, (Sicilya’da bir kent; Etna’nın kızgın külleri; Robert Kitson’un “Sicilya’daki Ev- Casa Cuseni” adlı kitabı; Hilmi Yavuz’un postmodern bir anlatısı; Taormina Film Festivali, vs., gibi…)   benim için yalnızca yeşil-mavi ütopik bir sığınaktır.

(09 Haziran 2003)', 'bir ütopya lazım Taormina! * - dileğin sakin bir limansa  bana gel - demiştin de  kuytuda sakladım seni  kıyametsi ayazlar  derin uykularda ...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/yesil-mavi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senli Benli', 'senli-benli-sair-fluka-k5s7b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen öyle bir sensin ki; 

Seninleyken yada sensiz, 

Sendeyim.

(Antalya,08.06.2003)', 'Sen öyle bir sensin ki;  Seninleyken yada sensiz,  Sendeyim. (Antalya,08.06.2003)...', ARRAY['Türk Edebiyatı','Şiir','Şair Fluka']::text[], 8.5, '{"poet":"Şair Fluka","poet_slug":"sair-fluka","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/senli-benli-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlasa Derd-i Derûnum Çeşm-i Giryânım Sana', 'aglasa-derd-i-der-num-cesm-i-giry-nim-sana-avni-fatih-sultan-mehmed-ihnie', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ağlasa derd-i derûnum çeşm-i giryânım sana

Âşikâr olurdu gâlib râz-ı pinhânım sana

      (Sevgili!)   İçimdeki dertler ile, yaş dolu gözlerim senin için ağlayacak olsa, (gönlümdeki)   gizli sırlarım (gözyaşlarıma)   gâlip gelir ve (sırlar)   sana aşikâr olurdu.

Mesned-i hüsn üzre sen ben hâk-i rehde pâymâl

Mûr hâlin nice arz ede Süleyman''ım sana

      Sen güzellik tahtında (oturuyorsun) : bense yolunun toprağında pâymâl (ayaklar altında)   kalmışım. Hâl bu iken a Süleyman''ım, sana bir karınca (denli âciz olan)   durumumu nasıl arz edeyim?         '' Divân edebiyatında Süleyman ihtişâmı; karınca da acziyet ve zayıflığı temsil ettiği için şair de kendini karınca; sevgilisini Süleyman olarak nitelendirmiştir.''

Şem''i gör kim meclisinde ağlayıp başdan çıkar

Hoş yanar yıkılır ey şem''-i şebistânım sana

      Muma da bak! Senin (bulunduğun)   meclisinde ağlayıp baştan çıkmakta. Ey odamı aydınlatan! O mum senin için ne de hoş yanıp yıkılıyor. ''Mum yanarken, baştaki fitilin kenarlarından ağlıyormuş gibi akar. Şair buna gıpta ediyor ve onu sevgilinin aşkı ile baştan çıkmış veya o uğurda başını vermiş olarak gösteriyor.''

Subh gibi sâdık olduğum gam-ı aşkında ben

Gün gibi rûşen durur ey mâh-ı tâbânım sana

      Ey ay gibi parlayan sevgilim! Benin sana karşı, aşkının yolunda sabah kadar sâdık olduğum, (doğrusu)   gün gibi âşikârdır.

Dün rakîbin cevrini men'' eyledin ben hastadan

Eyledi te''sir gûyâ âh u efgânım sana

      Dün rakiplerimin, aşkının hastası olan bana yaptıkları eziyetleri meneyledin. Galiba âh ve feryatlarım sana tesir etmiş! 

Zahm-ı hicrân şerhi çün mümkün değildir dostum

Sîne-çâkinden haber versin girîbânım sana

      Dostum! Anlaşılan o ki (bağrımdaki)   ayrılık yarasının şerh etmek mümkün görünmüyor. (Bari)   açık duran şu yakam, (aşkından dolayı)   göğsümdeki (şerha şerha olmuş)   yarıkları sana göstersin (de insafa gel!)

Eyleme gönlün gözün cevr ile Avnî''nin harâb

Dürr ü gevherler verir bu bahr ile kânım sana

      (Sevgilim!)   Eziyetlerinle Avnî''nin gözlerini ve gönlünü harap etme! Zira bu deniz (gibi coşkun gözlerim) , sana inciler; bu maden ocağı (gibi gönlüm)   de mücevherler sunar.

 Avni (Fatih Sultan Mehmed)', 'Ağlasa derd-i derûnum çeşm-i giryânım sana Âşikâr olurdu gâlib râz-ı pinhânım sana       (Sevgili!)   İçimdeki dertler ile, yaş dolu gözleri...', ARRAY['Türk Edebiyatı','Şiir','Avni (Fatih Sultan Mehmed)']::text[], 8.5, '{"poet":"Avni (Fatih Sultan Mehmed)","poet_slug":"avni-fatih-sultan-mehmed","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/aglasa-derd-i-derunum-cesm-i-giryanim-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DİKENİMİN SERÇESİ', 'di-keni-mi-n-sercesi-kenan-soyalp-wtqtk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kırmızı gül, 

mor soldu..

dudaklarım gibi..

yalnızlığıma dokundu, 

kanatan dikenleri..

sararmış gözlerim, 

sonbahara tutuldu..

bir serçe gülün dikenlerine kondu, 

gözlerin, 

uçtu…', 'kırmızı gül,  mor soldu.. dudaklarım gibi.. yalnızlığıma dokundu,  kanatan dikenleri.. sararmış gözlerim,  sonbahara tutuldu.. bir serçe gül...', ARRAY['Türk Edebiyatı','Şiir','Kenan Soyalp']::text[], 8.5, '{"poet":"Kenan Soyalp","poet_slug":"kenan-soyalp","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/dikenimin-sercesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüzünü Göreyim', 'yuzunu-goreyim-halil-gokkaya-wusjt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Anam babam fedâ, cânımda fedâ,

Ravzana varayım Ya Râsulallah…

Senden merhem nasip eylesin Hüdâ,

Gönlümü sarayım Ya Râsulallah…

Müjdeci rüzgârlar; müjdeci, serin, 

Şu muazzez ümmet aşkınla mü''min.

Ebûbekir,Ömer,Osman,Ali''nin,

Hatrını sorayım yâ Râsulallah...

Hevesim yok mala, şöhrete, şana, 

Bir tek tebessümün kâfidir bana, 

Sen''i seyredecek kadar yakına, 

Bir çadır kurayım yâ Râsulallah...

Dağlar taşlar hasretini der gibi,

Uzak olmak şu kalbimi yer gibi.

Yeşil kubben duldasında er gibi,

Nöbette durayım Ya Râsulallah…

Rabbim bilir her gizlimi, saklımı,

Hep O yana doğrulturum şeklimi.

Şu dünyayla uğraş veren aklımı,

Yolunda yorayım Ya Râsulallah…

Hamza’ları kundaklayan çöllere,

Eyyüp’leri kucaklayan illere,

Hoş terindenyaratılan güllere, 

Yüzümü süreyim Ya Râsulallah…

Sen''i bilmeyenler kör ve şaşkındır,

Oysa bütün varlık Sen''in meşkindir.

Âb''ı hayatımız,en''in aşkındır,

Canımı vereyim Ya Râsulallah…

Seni görmek en güzeli görmekmiş,

Sana varmak en doğruya varmakmış.

Sana ermek en doğruya ermekmiş,

Kabul et ereyim Ya Râsulallah…

Senin hasretindir Halil’i yakan,

Sensin damla damla gözümden akan.

Açılsın kapılar, açılsın mekân,

Yüzünü göreyim Ya Râsulallah...', 'Anam babam fedâ, cânımda fedâ, Ravzana varayım Ya Râsulallah… Senden merhem nasip eylesin Hüdâ, Gönlümü sarayım Ya Râsulallah… Müjdeci rüzgâ...', ARRAY['Türk Edebiyatı','Şiir','Halil Gökkaya']::text[], 8.5, '{"poet":"Halil Gökkaya","poet_slug":"halil-gokkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/yuzunu-goreyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dingin Düşünceler', 'dingin-dusunceler-sule-aydemir-p9snm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'üstünden bakmak ufuklara

çarpışmalar benliğinde

yenilgiler de ona kazançlarında

hesaplaşmalar kendi kendiyle

zirvelerde teninde ter başarmışlığın

toprak dibinde teninde ter darboğaz yıkıntıların

dere kenarı bakıyorsun yüzünün aksine 

değil mi 

akıyor su

sen kalıyorsun 

simyası belki düşüncelerin

bomboş beyaz sayfaların dolmaması

iç korkuların

boşa yaşanması hayatın

sığ heyecanları içindeki tabuların

yağmur yağar en güzel bestesi

kar yağar mükemmel resmi

keşfet gizemi armağanı sanatcı doğanın

örtersin düşüncelerini deliksiz uykularla

deniz kıyısı oluverir aklın

bir dalga yalar

silinir kumlara yazdığın hüzünsevdalar

dinginleşir

kor söner döner küle

çağlayan su seviyesini bulur

sıfırlanır durulur', 'üstünden bakmak ufuklara çarpışmalar benliğinde yenilgiler de ona kazançlarında hesaplaşmalar kendi kendiyle zirvelerde teninde ter başarmış...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/dingin-dusunceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anladım yaşadığımı', 'anladim-yasadigimi-haci-ozturk-f2gud', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Senden  önce  hiç  yaşamamışım, 

Yaşadığımı  hissetmeycek  kadar, 

Yavan  bir  hayatın  içindeymişim, 

karşıma çıkınca anladım yaşadığımı.

Derin  bir  uykudan  uyanırcasına, 

Hisettim  varlığını  yaşanırcasına, 

Hayatı  sevmekle  kazanırcasına, 

Seni  görünce anladım  yaşadığımı.

Yaşantımın her  anını doldurmaya, 

Bir  düş  misali gir  duygularıma, 

Senden  başka düşünce gelmez aklıma, 

Seni  görünce  anladım  yaşadığımı.

Sana  değer verdiğimi bir bilseydin, 

Seni  sevdiğimi bir anlayabilseydin, 

Hayatın  baharında  teşerbilseydin, 

Sende anlardın''Hacı, gibi  yaşadığını.

Hacı  Öztürk                       06/09/1979

                                            İZMİR

KAYDEDEN                     Hacı  Öztürk', 'Senden  önce  hiç  yaşamamışım,  Yaşadığımı  hissetmeycek  kadar,  Yavan  bir  hayatın  içindeymişim,  karşıma çıkınca anladım yaşadığımı. D...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/anladim-yasadigimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Perişan', 'perisan-murat-demir-mqjt6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gariban insanlar bitmiş yok derman

Yokları bırakın varlar perişan

Zalımın zulmüyle yazılmış ferman

Ölüyü bırakın sağlar perişan

Yakalar yıpranmış çıplak bacağı

Bacak derisinde kıllar perişan

Boşanmış kazanı sönmüş ocağı

Sahipsiz ocakta küller perişan

Verdim bir tenhada garibe selam

Gördümki bağında güller perişan

Unutmak günahtır edin söz kelam

Kuru ağızlarda diller perişan

Murat der mevlaya sığındım naciz

Çok basit nedeni yaşam perişan

Gel tanrım bahtıma sen koyma haciz

Zaten çok çekmişim, paşam perişan', 'Gariban insanlar bitmiş yok derman Yokları bırakın varlar perişan Zalımın zulmüyle yazılmış ferman Ölüyü bırakın sağlar perişan Yakalar yıpr...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/perisan-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceyi Gördüm Ağlarken!', 'geceyi-gordum-aglarken-abdusselam-bugur-voncy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Geceler benim için göz yaşı döker, 

Eğilir önümde karanlık boynunu büker, 

şafaklar sabahtan verince haber, 

Ağlayan duygularla bir hal olmuşum.

Sessizliğinde bakışımın her ifadesi kanar, 

Önümde kağıdım birde kalemim var, 

Sözlerim yayılır bak diyar diyar, 

Bir gül uğruna bülbül olmuşum.

Sevdasına düşünce uzaktaki yarın, 

Derledim çiçeklerini en güzel baharın, 

Hedefi olmak uğruna o  hoş bakışların, 

Kanayan düşlerimle heder olmuşum.

Bilmez mi dostlarım ben ne haldeyim? 

Kurumuş bir dal gibi, dökülmüş yapraklarım

Kalbimle, yüreğimle ben hep sizdeyim

Gönlümü parçalara bölen ben olmuşum.', 'Geceler benim için göz yaşı döker,  Eğilir önümde karanlık boynunu büker,  şafaklar sabahtan verince haber,  Ağlayan duygularla bir hal olmu...', ARRAY['Türk Edebiyatı','Şiir','Abdüsselam Bügür']::text[], 8.5, '{"poet":"Abdüsselam Bügür","poet_slug":"abdusselam-bugur","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/geceyi-gordum-aglarken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derdi güldemi', 'derdi-guldemi-haci-ozturk-0m3cj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben  gerçeklerle  ağlayanlardanım, 

Hep  son  yaprağın düşmesini  beklerim.

Bir  kez  tebessüm edebilmek için, 

Ölüme  susamış  topraklardan geliyorum.

Simsiyah  bir  perde çekilir  gözlerime, 

Tatmadım bu güne  dek  mutluluğu, 

Sonra  bir halsizlik  çöker  dizlerime, 

Dayanmak  için  umutlarımı  toplarım.

Anlattım  az buçuk  kendimi  sana, 

Umutsuzluğa kapıldığını söyleme bana, 

Dilimin  döndüğü, elimin yazdığınca, 

Desene bir  tanem  ölmemek  eldemi.

Geceler karanlık geceler sislimi  sisli, 

Bir  şarkı  dinlerim  sensiz hislimi  hisli, 

Adını  haykırmak  isterim seslimi, sesli, 

Bübül aman vermez ''Hacım. derdi güldemi.

Hacı  Öztürk                           06/09/1979

                                                 İZMİR

KAYDEDEN                            Hacı  Öztürk', 'Ben  gerçeklerle  ağlayanlardanım,  Hep  son  yaprağın düşmesini  beklerim. Bir  kez  tebessüm edebilmek için,  Ölüme  susamış  topraklardan...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/derdi-guldemi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşayacağım', 'yasayacagim-murat-demir-5zbvp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hayat seni artık anlamıyorum

Ut çaldım dünyaya ağlamıyorum

Beni anla diye yalvarmıyorum

Ölünceye kadar yaşayacağım

Kölen ettin beni yıllardan beri

Tapuladın bana emsiz dertleri

Daha bundan sonra tanımam seni

Ölünceye kadar yaşayacağım

Üzülsem derdime çare olmuyor

Çekeceğim varsa çilem dolmuyor

Gitmek istesemde felek koymuyor

Ölünceye kadar yaşayacağım

Ne olursa olsun aldırmam artık

Yıllardır üzülen yüreğim yırtık

Olsada gözümde hayat karanlık

Ölünceye kadar yaşayacağım', 'Hayat seni artık anlamıyorum Ut çaldım dünyaya ağlamıyorum Beni anla diye yalvarmıyorum Ölünceye kadar yaşayacağım Kölen ettin beni yıllarda...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yasayacagim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ülkemin Kızları 1', 'ulkemin-kizlari-1-kamil-aydemir-lmmhv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'demli çaylarda buharlanır alınterleri

karadenizin yollarına döner fındık toplayan elleri

kaçkarlardan doğan dereler gibi 

           temiz akar yürekleri

bakarlar mavi mavi

yeşildir gülüşleri

kekik kokulu dağlar gibi güzeldir düşleri

yüreklerde kıpırdarlar hamsi gibi

ve şişenin içindeki raki gibi

karadenizin kızları', 'demli çaylarda buharlanır alınterleri karadenizin yollarına döner fındık toplayan elleri kaçkarlardan doğan dereler gibi             temiz a...', ARRAY['Türk Edebiyatı','Şiir','Kamil Aydemir']::text[], 8.5, '{"poet":"Kamil Aydemir","poet_slug":"kamil-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ulkemin-kizlari-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ülkemin Kızları 2', 'ulkemin-kizlari-2-kamil-aydemir-0xt0c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'biraz fırat kokar

   biraz da munzur hasretleri

dillerinde bir başka güzeldir türküleri

en çok da kilim yürekli kızlarına üzülüyordur

    boşatılan kürt köyleri

kumalığa serpilir bazıları

pis pis güler babasının gözleri

söylerken paraları

onbeşinde olur karı

çoğunun yoktur sevmeye hakları

bir erkeğin nefesi bile değemez nefesine

    gölgesi de gölgesine

töreleri kuşundur

doğulu kızın sevmesine

yürek bu dinlemez kurşunu da

yaınında zor günlere hep umudun olsun

yaşamın uçurum kapısı hep kilili dursun

dalından koparılmış gül tomurcuğu gibi

fıratın üstünde yüzmesin ölü bir kız cesedi

aslında her biri nevroz yürekli

ve toprak gibi bereketli

törelerinde solar

doğunun kızları', 'biraz fırat kokar    biraz da munzur hasretleri dillerinde bir başka güzeldir türküleri en çok da kilim yürekli kızlarına üzülüyordur     bo...', ARRAY['Türk Edebiyatı','Şiir','Kamil Aydemir']::text[], 8.5, '{"poet":"Kamil Aydemir","poet_slug":"kamil-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ulkemin-kizlari-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkak Kadın', 'korkak-kadin-fatma-ful-ozok-lz5g1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Saat akşamüzeri beş

Yavaş yavaş geliyorlar

Herbirinin hikayesi ayrı

Yaşamlarıysa aynı olan kadınlar..

Takıyorlar acılı yüzlerine

Gülümseyen maskelerini

İçki masalarına meze taşıyorlar..

Ardından kendileri meze oluyorlar..

Beyler, yedikleri mezenin

Görüntüsüne aldanıp

İçindeki acılı harmanı 

Farkına bile varmıyorlar..

Hepsinin adı ayrı

Ayşe..Fatma..Didem.. Ayla..

Oysa hepsinin adı ‘kadın’..

Seyrediyorum bir süre 

Onları orada..

Ve kaçıyorum hızla..

Benimse adım

‘Korkak kadın’....', 'Saat akşamüzeri beş Yavaş yavaş geliyorlar Herbirinin hikayesi ayrı Yaşamlarıysa aynı olan kadınlar.. Takıyorlar acılı yüzlerine Gülümseyen ...', ARRAY['Türk Edebiyatı','Şiir','Fatma Ful Özok']::text[], 8.5, '{"poet":"Fatma Ful Özok","poet_slug":"fatma-ful-ozok","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/korkak-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karışmaya Gelmez; Şiirdir Sözün Hükümdarı...', 'karismaya-gelmez-siirdir-sozun-hukumdari-bir-mim-kemal-ertugrul-hhnv6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '______________________Değil sana! Şi’re sevdalı bu yürek...! 

Sanma ki aşığım sana! 

Hem nasıl vazgeçebilirim 

._.__________senin uğruna 

Bir çırpıda basarak 

Nasıl elveda derim 

Kırklanmış sevdama? 

Şiire aşığım ben

Kırk yıldan beri

Bir yangın artığından...

Ben olamam sevdalın 

Olsa olsa; 

Şiirim aşıktır sana...

........ 

Ona da karışamam asla...! 

9.06.2003/14:10', '______________________Değil sana! Şi’re sevdalı bu yürek...!  Sanma ki aşığım sana!  Hem nasıl vazgeçebilirim  ._.__________senin uğruna  Bi...', ARRAY['Türk Edebiyatı','Şiir','Bir Mim Kemal Ertuğrul']::text[], 8.5, '{"poet":"Bir Mim Kemal Ertuğrul","poet_slug":"bir-mim-kemal-ertugrul","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/karismaya-gelmez-siirdir-sozun-hukumdari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıp Cennet', 'kayip-cennet-mustafa-kemal-sen-gnuy5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her yanım boşluğu tüm sensizliğin, 

Ayrılık ruhumu çökerten deprem, 

Yaralar kapanmaz sonsuz değin, 

Kaybetmek ya Mecnun eder, ya Kerem...

İçim parça parça, ruh paramparça, 

Birden imkansızı kavrıyor içim, 

Senden bir damla his neden koparsa, 

Koskoca yokluğum ben, bir de hiçim...

22.11.2002', 'Her yanım boşluğu tüm sensizliğin,  Ayrılık ruhumu çökerten deprem,  Yaralar kapanmaz sonsuz değin,  Kaybetmek ya Mecnun eder, ya Kerem... İ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Kemal ŞEN']::text[], 8.5, '{"poet":"Mustafa Kemal ŞEN","poet_slug":"mustafa-kemal-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kayip-cennet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birtanem', 'birtanem-mehmet-altintas-hblal', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir Gün Soracağım Kendime

İçimdeki Bu Büyük Sevinç Neden Diye

Rüzgarların Usul Usul Estiği Gönlümde

Tarifini Arayacağım Aşkımın

Arzularla, İsteklerle neden Bağlıyım Sana

Neden Seni Görmezsem Duramıyorum Neden

En Sonunda Anladım Birtanem

Meğerse Ben Sen Seviyorum İşte Bu Yüzden...', 'Bir Gün Soracağım Kendime İçimdeki Bu Büyük Sevinç Neden Diye Rüzgarların Usul Usul Estiği Gönlümde Tarifini Arayacağım Aşkımın Arzularla, İ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Altıntaş']::text[], 8.5, '{"poet":"Mehmet Altıntaş","poet_slug":"mehmet-altintas","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/birtanem-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alda Başına Çal', 'alda-basina-cal-mehmet-altintas-4ig43', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kimselere Diyemedim Derdimi

Senin Sevgin Yüzünden Unuttum Kendimi

Artık İstemiyorum Gönlümde Seni

Alda Başına Çal O Lanet Sevgini

Güzelim Diye Beğenirsin Kendini

Aslında Hak Etmezsin Benim Sevgimi

Askınla Olsamda Ben Deli

Alda Başına Çal O Lanet Sevgini

Dönde Bak, İyi Gör Eserini

Bir Zamanlar Bu Zavallı Çok Sevdi Seni

Kendine Sakla Artık Yalan Sözlerini

Alda Başına Çal O Lanet Sevgini...', 'Kimselere Diyemedim Derdimi Senin Sevgin Yüzünden Unuttum Kendimi Artık İstemiyorum Gönlümde Seni Alda Başına Çal O Lanet Sevgini Güzelim Di...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Altıntaş']::text[], 8.5, '{"poet":"Mehmet Altıntaş","poet_slug":"mehmet-altintas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/alda-basina-cal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soracak Olurlarsa', 'soracak-olurlarsa-mehmet-altintas-dgcjl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bana Geceyi Soracak Olurlarsa

Karanlık yanlızlık Vede Korku Derim

Bana Şiir''leri Soracak Olurlarsa

Sadece Sana Sebep Yazılan Güzel Sözler Derim

Bana Hayatı Soracak Olurlarsa

Yalanlarla Vede İhanetle Geçen Zaman Derim

Bana Hayatımın gerçeğini Soracak Olurlarsa

Tek GerçeğimSevdiğim Derim

Bana Aşk''ı Soracak Olurlarsa

Hasret, Acı Vede Keder Derim

Bana Seni (Aşkımı)  Soracak Olurlarsa

Sevgi, Sevda, Umut Vede Mutluluk Derim...

_-_ Kısacası Yaşam Kaynağım Derim _-_', 'Bana Geceyi Soracak Olurlarsa Karanlık yanlızlık Vede Korku Derim Bana Şiir''leri Soracak Olurlarsa Sadece Sana Sebep Yazılan Güzel Sözler De...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Altıntaş']::text[], 8.5, '{"poet":"Mehmet Altıntaş","poet_slug":"mehmet-altintas","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/soracak-olurlarsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-mehmet-altintas-ccllb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gecenin Gündüze, Toprağın Suya, Bir Çocuğun Şefkate

Ne Kadar İhtiyacı Varsa 

Benimde Sana O Kadar İhtiyacım Var.

Sen Benim İçin...

Hayatta Ulaşabileceğim Son Nokta 

Sevgide Durabileceğim Son Durak

Sonbahar''larımda Bile Yeşil Kanal Tek Yapraksın.

Sen...

Sen Benim İçin Vazgeçilmez Birisin

Çünki Sen...

Sen Benim Tek Sevgilimsin.', 'Gecenin Gündüze, Toprağın Suya, Bir Çocuğun Şefkate Ne Kadar İhtiyacı Varsa  Benimde Sana O Kadar İhtiyacım Var. Sen Benim İçin... Hayatta U...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Altıntaş']::text[], 8.5, '{"poet":"Mehmet Altıntaş","poet_slug":"mehmet-altintas","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sen-262-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ekspres Aşk', 'ekspres-ask-hakki-hakan-kaya-ihbof', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yıllarca bekledim hep, 

Bir gün gelecek diye, 

Gönlümün durağından, 

Bir otobüs geçti.

Açtı kapılarını, 

Duracak sandım, 

Ekspres aşkmış, 

Durmadan gitti.', 'Yıllarca bekledim hep,  Bir gün gelecek diye,  Gönlümün durağından,  Bir otobüs geçti. Açtı kapılarını,  Duracak sandım,  Ekspres aşkmış,  D...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ekspres-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-mehmet-altintas-sk6qr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu Akşam Yine Yağmur Yağıyor

Gökyüzü''nü Simsiyah Bulutlar Kaplamış

Tıpkı Sen Gittiğin Gün 

Benim İçimi Kaplayan Karanlıklar Gibi

Biliyormusun Aslında Yağan O Yağmur, 

Bulutlardan Dökülen Su Damlaları Değil

Beni Bırakıp Gittiğin Günden Bu Yana

Göz Kapaklarıma Biriken Gözyaşlarımdır

Yokluğun Beni Bir Ecel Gibi Saracak

İçimdeki Hasret Beni Daha Çok Yakacak

Sana Kavuşmadan Ölürsem Eğer

Son Sözümde Tıpkı İlk Sözüm Gibi 

Seni Seviyorum Olacak', 'Bu Akşam Yine Yağmur Yağıyor Gökyüzü''nü Simsiyah Bulutlar Kaplamış Tıpkı Sen Gittiğin Gün  Benim İçimi Kaplayan Karanlıklar Gibi Biliyormusu...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Altıntaş']::text[], 8.5, '{"poet":"Mehmet Altıntaş","poet_slug":"mehmet-altintas","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/seni-seviyorum-140-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bazı Umutlarım Vardı', 'bazi-umutlarim-vardi-mehmet-altintas-nw0i2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bazı Umutlarım Vardı Yarınlara Ait

Mutlu Ve Huzurlu Bir Hayat Sürmek

Bazı Korkularımda Vardı Yarınlara Ait

Çok Sevdiğim Seni Kayıp Etmek

Ama Kader Acımasız Çıktı

Tüm Hayallerimi Yaktı, Yıktı

Beni Bu Dünya''da Kimsesiz Bıraktı

Seni bir Yana, Beni Bir Yana Fırlattı

Yinede Küsmedim Ben Hayata

Çünki Bir Umudum Vardı Daha

Belki Sen Yoktun Ama Yanımda

Güzel Günlerimiz Vardı Anılarda

Bir Gün Yemin Ettim Kendi Kendime

Alacağım İntikamımı Bu Hayattan Diye

Benim Sitemim Hayata Değil Aslında Sevgiliye

Beni Bırakıp Gittin Ya Asıl Şimdi Döndüm Deliye', 'Bazı Umutlarım Vardı Yarınlara Ait Mutlu Ve Huzurlu Bir Hayat Sürmek Bazı Korkularımda Vardı Yarınlara Ait Çok Sevdiğim Seni Kayıp Etmek Ama...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Altıntaş']::text[], 8.5, '{"poet":"Mehmet Altıntaş","poet_slug":"mehmet-altintas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bazi-umutlarim-vardi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soğuk Ölüm', 'soguk-olum-gurkan-cengiz-421vd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Buzlardan da soğuksun dedi ruhum, 

Ve solmuşsun.

Emin değilim, 

ölüm bu kadar soğuk mudur gerçekten? 

Bilmiyorum...

Ama üşüyorum.

Söyle, söyle ruhum! 

Neden bıraktın beni, 

Terkettin.

Üşüyorum.

Bir buz gibi kaskatı kesilmeden vücudum, 

Gel, dön geri, 

Bekliyorum.', 'Buzlardan da soğuksun dedi ruhum,  Ve solmuşsun. Emin değilim,  ölüm bu kadar soğuk mudur gerçekten?  Bilmiyorum... Ama üşüyorum. Söyle, söy...', ARRAY['Türk Edebiyatı','Şiir','Gürkan Cengiz']::text[], 8.5, '{"poet":"Gürkan Cengiz","poet_slug":"gurkan-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/soguk-olum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uykuda', 'uykuda-murat-tali-33c2v', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'uykusunda 

büyür mü çocuklar

uykusunda 

sevinir mi acı çekenler

uykusunda 

yitirir mi kederlerini sarhoşlar

uykusunda 

ölür mü ölümü bekleyenler

uykusundan

uyanır mı uyku

oysa ben

uyanırım kan revan düşler içinde

sakalım kalır bir yarıda 

bir yanım gece diğer yanım gündüz olur.

gözlerim karanlığından çıkar odanın

kapının penceresinden içeri giren ışığa takılır kalır

uykusunda

korkar mı yaşamı yüreğine sığdıranlar

uykusunda 

sarınır mı yatanlar

ayaz gecelerde yitmemek adına 

yorganına

uykusunda

bitermi şiirler

bitmeyen duygular adına...', 'uykusunda  büyür mü çocuklar uykusunda  sevinir mi acı çekenler uykusunda  yitirir mi kederlerini sarhoşlar uykusunda  ölür mü ölümü bekleye...', ARRAY['Türk Edebiyatı','Şiir','Murat Tali']::text[], 8.5, '{"poet":"Murat Tali","poet_slug":"murat-tali","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/uykuda-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GİTMEK GİBİ GELMELER', 'gi-tmek-gi-bi-gelmeler-kenan-soyalp-qy5ju', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'eskitmek sana uzak 

özenle eskitmek, 

gözlerin bana tuzak

eskiye geri dönmek..

çok şey değişti, 

bir o kadarıda aynı..

değişmeyenler, 

gözlerimin arkasında kaldı…

hadi git..

gözümün önüne git..', 'eskitmek sana uzak  özenle eskitmek,  gözlerin bana tuzak eskiye geri dönmek.. çok şey değişti,  bir o kadarıda aynı.. değişmeyenler,  gözle...', ARRAY['Türk Edebiyatı','Şiir','Kenan Soyalp']::text[], 8.5, '{"poet":"Kenan Soyalp","poet_slug":"kenan-soyalp","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gitmek-gibi-gelmeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgilime', 'sevgilime-alparslan-aydin-cmx9k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerin ki öğretti yüreğime sevmeyi

Ve yüreğin, gözlerime gülmeyi.

Bil ki bitanem dünyalara değişmem, 

Gözyaşlarını dudağımla silmeyi...', 'Gözlerin ki öğretti yüreğime sevmeyi Ve yüreğin, gözlerime gülmeyi. Bil ki bitanem dünyalara değişmem,  Gözyaşlarını dudağımla silmeyi......', ARRAY['Türk Edebiyatı','Şiir','Alparslan Aydın']::text[], 8.5, '{"poet":"Alparslan Aydın","poet_slug":"alparslan-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sevgilime-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçten Değilse Bunca şey', 'i-cten-degilse-bunca-sey-ozgen-seckin-wy8yt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir kül yığınıdır içten değilse söz

içten değilse, sırsız bir aynadır dostluk

sevgi değilse içten, bir yüzüdür ölümün

renk içten değilse, ezgi içten değilse

karanlığıdır huzursuz bir aydınlığın

içten değilse şiir

çarpar bir tezgah gürültüsüyle

yüzümüze bir şamar yankılanır.

Yaşamak içten olmaktır her uyanışa

acılar kaygılıdır ve korkak

sevinçler kaygılıdır ve kaypak

nedensiz değildir barışla başlamak güne

her yorgunluk, dilimize varmayan dilek

her kargış, her feryat

nedensiz değildir içerde

ve dışarda akan bir hayat.

İçten değilse saat, kapı tokmağı

balarısı, köpüren kahve, savrulan sağnak

intiharlar, esriklik, bir tutam başak

susturulan rotatif, konuşan bu kız; 

yaşamaki sevmek ve acı çekmek

bir günde bin parçaya bölünmek

bir boşlukta sallanmaktır 

o zaman...', 'Bir kül yığınıdır içten değilse söz içten değilse, sırsız bir aynadır dostluk sevgi değilse içten, bir yüzüdür ölümün renk içten değilse, ez...', ARRAY['Türk Edebiyatı','Şiir','Özgen Seçkin']::text[], 8.5, '{"poet":"Özgen Seçkin","poet_slug":"ozgen-seckin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/icten-degilse-bunca-sey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Dünya', 'mavi-dunya-harun-aslan-5k2x2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Buz mavisine çalar dağlar 

Güneyin geceleri 

Savrula savrula dağılır 

Gençliğim 

kaçar benden 

Karanlıkta kuytulaşır 

sevdalarım 

Çocukluğum düşer gözlerime 

Yaşam dün-bugün... 

Bir bakmışım bıyıklarım terlemiş 

yaşam 

yıpranmış, bir kanepe 

boyası atmış bir duvar 

verimsiz bir toprak 

ve bir dal çırılçıplak 

Memleket özlemi bir yana 

Bir de bu şehirden gitmek 

havasından 

toprağından 

suyundan 

ve ıramak beyaz sesli dostlardan 

Kaldı ki 

dünya hala dipdiri 

gül güleç 

ve yeni doğan gün 

ne çok seviyorum seni 

sana günaydın', 'Buz mavisine çalar dağlar  Güneyin geceleri  Savrula savrula dağılır  Gençliğim  kaçar benden  Karanlıkta kuytulaşır  sevdalarım  Çocukluğum...', ARRAY['Türk Edebiyatı','Şiir','Harun Aslan']::text[], 8.5, '{"poet":"Harun Aslan","poet_slug":"harun-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/mavi-dunya-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giden sevgilinin Ardından', 'giden-sevgilinin-ardindan-gunay-aktag-1htqf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Denizin hiç tadı yok

Boğuyor  dalgalar sahili

Gözler boş boş arıyor 

O giden sevgiliyi

Güneşin hiç tadı yok 

Rüzğar almış rengini

Gidenden  hiç haber yok

Kimler aldı  kendini

Sahilde oturmak yanlız

Gayri sensiz  işkence

Ya gel görün bana

yada girme düşünceme

ya hiç görmeseydim   seni

yada gitmeseydin benden     SERSERİ..', 'Denizin hiç tadı yok Boğuyor  dalgalar sahili Gözler boş boş arıyor  O giden sevgiliyi Güneşin hiç tadı yok  Rüzğar almış rengini Gidenden  ...', ARRAY['Türk Edebiyatı','Şiir','Günay Aktağ']::text[], 8.5, '{"poet":"Günay Aktağ","poet_slug":"gunay-aktag","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/giden-sevgilinin-ardindan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Can Var Bende...', 'bir-can-var-bende-alaettin-isik-gm6ig', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözlerin kuşatır

Akşamlarımı

Her gece kapımı

Çalıyor hasret

Seven yüreğimde

Ateşin yanar

 Bir Can vardı hala

 Sana emanet

         *****

Hasretin gönlüme

Yaylım ateşte

Anlarsın halimden

Derdime düş de

Eksilmiyor sevdan

Bu bekleyişte

Bir Can vardır bende

Sana emanet

(07/06/2003)', 'Gözlerin kuşatır Akşamlarımı Her gece kapımı Çalıyor hasret Seven yüreğimde Ateşin yanar  Bir Can vardı hala  Sana emanet          ***** Has...', ARRAY['Türk Edebiyatı','Şiir','Alaettin Işık']::text[], 8.5, '{"poet":"Alaettin Işık","poet_slug":"alaettin-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-can-var-bende-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşün', 'dusun-mehmet-sari-ml24u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güneşi avuçlarına sıkıştırdığımı düşün, 

Avuçlarını başının üzerinde taşıdığını, 

Ve dağı, 

             başının üstünde taşıdığını, 

Sonra beni düşün bir tanem; 

Beni eteklerine yapışmış bir buz parçası, 

Beni yüzüne tırmanan 

                          bir su damlası gibi düşün. 

Şimdi uzanıp yatağına 

                          yavaşça kapa gözlerini.

                          ama unutma sakın düşün.

Uzat, uzat ellerini, tutunacak dalım olsun.

Şimdi bırak bu dizeleri okumayı, 

Açtığında gözlerini

                    beni yanında bulacağını düşün.

                                                     17.12.1992', 'Güneşi avuçlarına sıkıştırdığımı düşün,  Avuçlarını başının üzerinde taşıdığını,  Ve dağı,               başının üstünde taşıdığını,  Sonra ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sarı']::text[], 8.5, '{"poet":"Mehmet Sarı","poet_slug":"mehmet-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dusun-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Güzel Uzun Şiir', 'bir-guzel-uzun-siir-oguzkan-bolukbasi-jg89m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Beni sen akşamcı ettin 

Hayal sevgilim 

Elde kadeh 

Dilde sen 

Her akşam bu sofrada bir rüzgardır esen 

Yıldızlara isimler verdim kendimce 

Biri hayal 

Biri gurbet 

Biri hasret 

Biri hep o güzel memlekettir memleket 

Sokaklarında büyüdüğüm seninle 

Buluştuğum gözlerinle 

O güzel memleket bir yıldıza adını verdi 

Akşamları göğe kaldır başını seyret 

Belki geçmişin ışıkları henüz sönmemiştir 

Belki resimler kaybolmamıştır 

Belki isimler unutulmamıştır 

Belki batmayı unutmuş güneşler vardır gökte 

Seyret aynaya bakmadan seyret gökyüzünü 

Bir yıldız göz kırpıyorsa 

Veya bir ışık kayıyorsa 

Benim kadehimdir şerefine kalkan 

Işıklara doğru 

Sana doğru 

Şiirler geliyor gökyüzünden 

Bu bilinmeyen hayal meyhanesinden 

Beni kimse görmedi 

Ben kimseye el sallamadım 

Seninle meşguldum 

Tanıdıklar görmüşse de ben onları tanımadım 

İnanır mısın senden başkasını da pek sallamadım 

Baharlar açıyor toprakla birlikte ben de canlanıyorum 

Hayallerimi uçurtma yaptım 

Gökyüzünde yalpa yalpa yalpalanıyorum 

Birşey göremiyorum uzaktan sana uzanamıyorum 

Adını çağıracağım bir kimse de yok 

Hep yalnız yürümüşüm sokaklarda demek ki 

Sana bakayım derken kimse kalmamış yanımda 

Bir senin adın var aklımda 

Onu da söyleyemem 

Onu bağıramam özgürce 

Adını tutukladım beynimde salıvermek yok 

Havalandırma bile yasak 

Voltayı hayallerimde atacaksın 

Sen kimseye görünmeyeceksin 

Gel be dünya, evinden atma beni hayata çok alıştım 

Azraile satma beni 

Sana söylerim beni vermezsen ellere 

İsimleri itiraf ederim 

Bir konuşsam sarsılırsın 

Beni sen akşamcı ettin hayal sevgilim 

Elde kadeh 

Dilde sen 

Meyhane beğen meyhanelerden 

Küfürlere karıştı gecenin çığlıkları 

Sesim sesine ulaşmaz 

Aşk buna mı derler 

Kavuşulmazsa büyür 

Kavuşulursa erir 

Ben seni seyrederdim 

Köşeden 

Arkana takılırdım anlamazdın akşam üstleriydi 

Bizlerle pek oynamazdın 

Bir yakan toptu son oyunumuz 

Ellerin ellerimi yaktı 

Gözlerin gözbebeklerimi 

Bisikletimde kaldı sıcaklığın 

Bisikletim yok şimdi 

Beni sen akşamcı ettin 

Hayal sevgilim 

Elde kadeh 

Dilde sen 

Bir de o zümrüt gözlerinde öpüşen 

Mutlu çocuk 

Nereye yolculuk bile demeden 

Gittin evlendin 

Seslenemedim 

Seni hiç görmedim 

Ben ölmedim 

Sen ölmedin 

Neredeydin bilemedim 

Bir tebrik de edemedim 

Şimdi eski dostlara rastlıyorum 

Herbiri bir yerde 

Kimi okumuş kimi zengin 

Kimi mutlu 

Kimi bezgin 

Ben bir dünya tatlısı ile evliyim şimdi 

Dünyaya bunca bağlanmam onun eseriydi 

Şiirler yazdım ona şarkılar oldu 

Bu kadeh onunla doldu 

Seni inattan soruyorum herkese 

Daha neler var bu şiir devam ederse 

Bırakma hayallerimi 

Hayal güzelim 

Ben akşamcıyım 

Sen akşamsın 

Bir güzel bestede şarkısın dinlediğim 

Bir özlemsin bitiremediğim 

Dün gibi herşey oysa 

Dün gibi ama 

Zamana şehir de dayanamamış 

Yıkılmış 

Sokaklar süklüm püklüm 

Ağaçlar büyümüş ve çürümüş 

Bizse yaşamadıklarımıza inat saçlarımızda beyazlar 

Sokaklarda maziyi arıyoruz 

Yanılıyoruz dostum 

Yanılıyoruz 

Zaman geldi biz ayrılıyoruz 

Ben sana alıştım hayat 

Darılırım gidersen 

Bir daha yüzüne bakmam 

Şerefsizim yanına bile gelmem 

Bu şiir uzayacak 

Hayal güzelim 

Yorulduysan git 

Laf lafı 

Laf mısrayı açıyor 

Bende uyku yok 

Zaman azaldıkça 

Uykum kaçıyor 

Daha uzun kalmak ayakta 

Sanki daha uzun yaşamak gibi 

Hiç uyumasam ömrüm iki katına çıkar mı 

Aldanmak mı yoksa hayallerim 

Ömür nedir 

Hayat nedir hayal nedir 

İşte şu oturduğum sedir nelere şahittir 

Ben bilmem o da dünyada ben de 

Belki o sedir daha bir kıymetlidir 

Herşey izafi hayal sevgilim 

Güzel 

Çirkin 

İyi 

Kötü 

Uzun 

Kısa 

Ve daha neler neler 

Adına sıfat dediğin ya da nitelik 

Asıl olan 

Mutlakla birliktelik 

Sazlıklarda bir kamış 

O kamış neye yaramış 

Diye sorma 

Kamış kamış olmuşsa mutlaka 

Birşeye yaramıştır 

Hani insan insan olmuşsa da aynısıdır 

Palavra gayrısıdır 

Ben bıkmadım yaşamaktan 

Yaratan bıktırmasın 

Aşk ile yansın yüreğim 

Ayakkabım sıktırmasın 

Haşim adam bıçaklıyor mu sokaklarda 

Yüksel’i dövdüler mi kapıda 

Vay anam ne kıymetliymiş gözlerin sen hala kaçır onları 

Mahallenin bebeleri birbirine girsin senin için 

Elyüz kan içinde elin oğlu şenli 

Bizi bize kırdırttın 

Güzeller güzeli 

Hayal şehrin hayal kızı 

Helal olsun sana 

Akan kanlar yoluna şerbettir senin 

Beni sen akşamcı ettin hayal güzelim 

Ötekiler ne oldu bilmem 

Biri emekli olmuş 

Öbürü elini tornaya kaptırmış 

Biri de terörist dediler 

En akıllısı manifaturacı, müteahhit 

Kapatmış hayal şehrin arsalarını 

Sonra önüne gelene satmış 

Ben kiraladım yanındaki meyhaneyi 

Parasız mey satarım karşılığında muhabbet 

Ben sana hapsoldum müebbet 

Yine de diyorum kendime be adam haline şükret 

Ya idam olsaydı cezan 

Af da etmezdi devlet 

Bu şiir ah bu şiir seni bana getirsin 

Ne işim varsa beni alıp bitirsin 

Sesler uzakta kaldı 

Yaşlar yaş olmaktan çıkmak üzere 

Bu şiir seni bana getirecek mi bilemem 

Ama ben kalkıp gideceğim uzaklara 

Aklımı bırakıp 

Aşkımı bırakıp 

Bir de yakamı bıraksam 

Kurtulacağım 

Sana bir sepet çiçek yollayacağım 

İsimsiz 

Bir kucak şiir 

Bitimsiz 

Ellerimde güller açmış 

Sabah çiğleri üzerinde 

Fırından sıcak ekmek kokusu yayılır 

Çocukluğumun istüne 

Uyanmak ne de zordur okul varsa 

Sen uykularımı bölerdin 

Buğdaylı rüzgar kokusuyla 

Büyüdük herşeyi büyüttük 

Aşkı 

Hasreti 

Milleti 

Sen neredesin ey sevgili', 'Beni sen akşamcı ettin  Hayal sevgilim  Elde kadeh  Dilde sen  Her akşam bu sofrada bir rüzgardır esen  Yıldızlara isimler verdim kendimce  ...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":203,"source_url":"https://www.antoloji.com/bir-guzel-uzun-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul Yolunda', 'i-stanbul-yolunda-mehmet-sari-lst3i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir garip şey şu tren yolculuğu

İnsanlar öyle telaşlı ki sorma

Çamurlar içinde trene koşanlar

Trenin boylu boyunca 

                           simit satanlar.

Bir de düdük sesi....

Ve demir yolun üzerine 

                            abandı bütün gücüyle

                            peş peşe odalar.

Ben pencerenin kenarındayım, 

Gözüm pencerenin camında

                                  camda su damlacığında

Kulağım içeride 

                         gürültüde

Aklım İstanbul''da

           İstanbul''dan başka sende.

İstanbul a-ha şu ötede

Koca elli, koca şehir.

Neden bilmem seni orda düşünüyorum

                     (gerçek sen gibi) 

Ve, şimdiden seviyorum İstanbul''u

Seni seviyor gibi.

                                                          17.12.1992', 'Bir garip şey şu tren yolculuğu İnsanlar öyle telaşlı ki sorma Çamurlar içinde trene koşanlar Trenin boylu boyunca                          ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sarı']::text[], 8.5, '{"poet":"Mehmet Sarı","poet_slug":"mehmet-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/istanbul-yolunda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beddua', 'beddua-atila-gunal-47uss', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni yüreğimin en güzel yerine

Ne büyük özenle yerleştirmiştim

Kılına zarar gelmesin diye

Çelik zırhlarla bezemiştim

O zırhın içinde havasızlıktan

Ciğerlerin patlasın

Bakmaya kıyamazdım gözlerine.

Nazar değecek diye; 

Gözlerden sakınırdım.

O gözler şimdi kimlere bakıyor, 

Hangi saf yüreklere ne ateşler salıyor, 

Gözlerin kızgın millerle oyulsun 

Kara topraklar dolsun yerine

Dokunmaya kıyamazdım ellerine

İncinecekler diye avuçlarımda

Parmak uçlarımla severdim

Minicik bir serçe gibi

Şimdi kimlerin ellerini tırmalıyor

Nankör bir kedi gibi

En paslı, kör mıhlar çakılsın ellerine

Öpmeye kıyamaz da 

Küçücük buseler kondururdum

Bal sandığım dudaklarına

Yılan gibi sokmuşsun da

Anlayamamışım zehrini

En zehirli yılanlar aksın

O dudaklardan içine

Ellerimle beselerdim her gün

Her yuttuğun lokmada 

Gözlerinin hazdan kapanışıyla

Dünyanın en büyük mutluluğunu yaşardım

Her yediğin, her yuttuğun

Şimdi içinde cam kırıkları olsun

İçin parçalansın, 

Ağzından oluk oluk kanlar gelsin

Dizlerimde yatırıp

Saçlarını okşardım gün batımlarında

Parmaklarımı saçlarından yanaklarına 

Alnından burnundan dudaklarına indirirken

Aşk şarkıları fısıldardım kulaklarına

Taş olsun şimdi yattığın yerler

Ellerimi dokunduğum her ten parçan

En onmaz yaralarla kaplansın

İçinde kurtlar kaynasın

Lime lime dökülsün

Bu sana son duamdır

Bedduaya dilim varmıyor nedense

2003-06-09', 'Seni yüreğimin en güzel yerine Ne büyük özenle yerleştirmiştim Kılına zarar gelmesin diye Çelik zırhlarla bezemiştim O zırhın içinde havasız...', ARRAY['Türk Edebiyatı','Şiir','Atila Günal']::text[], 8.5, '{"poet":"Atila Günal","poet_slug":"atila-gunal","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/beddua-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadece', 'sadece-tolga-onur-tedci', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '''desdemona''ya'' 

Bembeyaz bir nur, 

çiçeksiz bir masada oturmuş, duruyordu.

Masanın çiçeği olabilmekti gönlümün istediği

Gönül de oturuverdi masaya, 

o zaman anladı ki, 

çiçek olmak değildi asıl erdemi

çiçek değildi gönül.

Sadece çiçeği sulamak için orada olan

Bir sürahiydi, dolusundan..

        

          Nisan-2003/ankara', '''desdemona''ya''  Bembeyaz bir nur,  çiçeksiz bir masada oturmuş, duruyordu. Masanın çiçeği olabilmekti gönlümün istediği Gönül de oturuverdi ...', ARRAY['Türk Edebiyatı','Şiir','Tolga Onur']::text[], 8.5, '{"poet":"Tolga Onur","poet_slug":"tolga-onur","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sadece-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Döne döne', 'done-done-ozcan-ozkan-hdk5q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Böyle sensiz

Ben 

Kendimi

Senin yerine

Ellerin diye

Döne döne

Döne döne

Bir kibrit çaksam

Üstüm başım

Kaşım gözüm

Alev

Böyle

Durduraksız

Böyle

Düşüne düşüne

Döne döne

Döne döne

Tütüyor bedenim

Ellerim çakmak

Işıkları yakmıyorum

İçimde

İnsafsız bir kıvılcım

Tetikte

Böyle

Her gece

Döne döne

Döne döne

(2002)', 'Böyle sensiz Ben  Kendimi Senin yerine Ellerin diye Döne döne Döne döne Bir kibrit çaksam Üstüm başım Kaşım gözüm Alev Böyle Durduraksız Böy...', ARRAY['Türk Edebiyatı','Şiir','Özcan Özkan']::text[], 8.5, '{"poet":"Özcan Özkan","poet_slug":"ozcan-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/done-done-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Gözyaşımdan Mektuplar Yaz', 'bana-gozyasimdan-mektuplar-yaz-derin-oger-gvw0q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevdam

Gurbete düşer

Treni beyaz

Yolu kalbimin üstünden geçer

Dağları ayaz...

Sevdam sımsıkı sarıl bana

Gidenin dönüşü olmaz

Dilim susar adını anmaz

Kalbim yokluğu kolay anlamaz

Dayanamaz

Ararsam dünleri

Hatıralarım da birikmiş gözyaşlarım var

Avuç avuç doldurdum vagonlara

Bana gözyaşımdan 

Mektuplar yaz............', 'Sevdam Gurbete düşer Treni beyaz Yolu kalbimin üstünden geçer Dağları ayaz... Sevdam sımsıkı sarıl bana Gidenin dönüşü olmaz Dilim susar adı...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bana-gozyasimdan-mektuplar-yaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölge', 'golge-hakan-karci-ccdyu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu gece 

Bir gölge bekledi kapında 

sabaha dek 

Tek bir bakış ve tebessüm 

Aydınlık dilendi mehtabından 

Bir gölge dizlerine kapandı 

Yalvardı boğuluncaya dek 

gözyaşıyla 

Kıvrandı hummalı bir beklemenin sonunda 

Gece gölgeyle dağladı yüreğini 

Ürperdi ürpermesiyle 

Sabaha dek yediler fakirin ekmeğini 

Umut fakirin ekmeği 

Gece bitmedi gölge mıhlandı 

Sabaha dek bekledi kapında 

Hiç gelmeyecek sabaha dek 

Ağladı ağladı 

Sabah olmadı 

Hakan Karcı', 'Bu gece  Bir gölge bekledi kapında  sabaha dek  Tek bir bakış ve tebessüm  Aydınlık dilendi mehtabından  Bir gölge dizlerine kapandı  Yalvar...', ARRAY['Türk Edebiyatı','Şiir','Hakan Karcı']::text[], 8.5, '{"poet":"Hakan Karcı","poet_slug":"hakan-karci","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/golge-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabaha Çok Var Ama', 'sabaha-cok-var-ama-bekir-mutlu-gokcesu-2mtw9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sabaha çok var ama

sabahlarım uyandı sana.

Sabah da sabah bana bu gece

sabaha var daha nice...

Açılıp düşlerimin penceresi

hayalin içeri gelince

başlar sevişmelerimiz şiirlerle...', 'Sabaha çok var ama sabahlarım uyandı sana. Sabah da sabah bana bu gece sabaha var daha nice... Açılıp düşlerimin penceresi hayalin içeri gel...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sabaha-cok-var-ama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak', 'yasamak-rahmi-nalbantoglu-zfdhs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yaşamak.

Yaşamak sevgi değilse, 

Ruhumun iyanı, boş.

Ya ben hiç, yaşamadım, 

Ya Tüm insanlar, ölmüş.', 'Yaşamak. Yaşamak sevgi değilse,  Ruhumun iyanı, boş. Ya ben hiç, yaşamadım,  Ya Tüm insanlar, ölmüş....', ARRAY['Türk Edebiyatı','Şiir','Rahmi Nalbantoğlu']::text[], 8.5, '{"poet":"Rahmi Nalbantoğlu","poet_slug":"rahmi-nalbantoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yasamak-57-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kerkük ve Ben', 'kerkuk-ve-ben-haci-verdi-kankilic-uiem0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kerkük bende bir ümit Kerkük gözümde yaşım

Onda ölen ecdadım Onda doğan kardaşım 

Karanlık ufuklardan parıldayan bir haber

kerkük''üme ağlarım her akşam ve her seher

Bütün şarkılar uzun Kerkük dilde çift hece

Kerkük''ün bahtı kara Kerkük''ün şanı yüce

Yad eldeyim ben Onsuz O bensiz elemdedir

Kerkük yanan her canda dildedir kalemdedir

Bende bilmem ki neyin böyle mestanesiyim

Kerkük benim timsalim ben Kerkük''ün sesiyim 

Bu sırrımı istersen bütün cihana duyur

Türk''ün kalbi Türkiye ruhu Kerkük''te uyur

Ey bitmeyen uzun yol al beni yara götür

Şark''ta Kerkük denilen bizim diyara götür', 'Kerkük bende bir ümit Kerkük gözümde yaşım Onda ölen ecdadım Onda doğan kardaşım  Karanlık ufuklardan parıldayan bir haber kerkük''üme ağları...', ARRAY['Türk Edebiyatı','Şiir','Hacı Verdi Kankılıç']::text[], 8.5, '{"poet":"Hacı Verdi Kankılıç","poet_slug":"haci-verdi-kankilic","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kerkuk-ve-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Metafizik düşünceler', 'metafizik-dusunceler-ensar-cevval-48t9m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Telepati nedir bilirmisin

bir ses duyarsın kulaklarından evvel

birini görmüşündür ya gözlerinden evvel

birine sevdiğini söylemişsindir ya

ve duymuş, görmüş gibi yanıbaşında

bir his çağlayanı, melekedir aslında

Sempati nedir bilir misin

kulaklara yaygın bir terennüm

dudaklardan uçuşan tebessüm

bir çift zeytin karası

bir tutam zülüf aslında

Empati ise karşındaki sendir

bir beddua aslında

benim çektiklerimi sende çek

söyler ya yüreği yanan

benim gözlerimle bak yaşadıklarıma

benim gibi yan demek aslında', 'Telepati nedir bilirmisin bir ses duyarsın kulaklarından evvel birini görmüşündür ya gözlerinden evvel birine sevdiğini söylemişsindir ya ve...', ARRAY['Türk Edebiyatı','Şiir','Ensar Cevval']::text[], 8.5, '{"poet":"Ensar Cevval","poet_slug":"ensar-cevval","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/metafizik-dusunceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Titreyenler', 'titreyenler-sule-aydemir-o13xn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kalemimin uçunda titreyen 

isme gelmez duygular

resmi yapılmalı kolayından 

gülen ayva ağlayan nar

tüm dünya rüyalarını sığdırmalı

bir yağmur damlasına

akıtmalı ruhun toprağına hissetmeyi

teninden iliklerine ve son durak yalansız gözler

tapınaktan çıkmış deri değiştirmiş huzurlar

taksın suratıma

gülümseyen yarınlar dudaklara

parmak uçlarında tutkunun şerbetleri

ibrişim saç telleri sevgi alev bulutları 

kalemimin uçunda titreyen isme gelmez duygular

belki resmi yapılmalı kolayından

açan son çiçeği yakalamalı

herkesin kılıfı gönlün yakasına takmalı

parçalar bütün olmalı

ayıklanıp aşılanmalı 

kırılan kuruyan duygunun dalları

gizem parçalarda tek tek toplanmalı

zafer tamamlamak adına

vazgeçmek terk etmek için

sürünmek ise yeni kalkışlara

cennet cehennemdir düşünceler

yan kavrul ve don durmadan

yaşam mı düşündükçe var olan

zihnin güçlü olduğu yerde 

yaşlı duygular var gönülde

yenilenmek genç hisselere 

oluru olmazı beklemek ki

yetişmek nefes almak hücrelerinle 

kalemimin uçunda titreyen 

isme gelmez duygular

doğur-öldür

ağlat-güldür

ister yaz ister yazma', 'kalemimin uçunda titreyen  isme gelmez duygular resmi yapılmalı kolayından  gülen ayva ağlayan nar tüm dünya rüyalarını sığdırmalı bir yağmu...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/titreyenler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söylesem bir türlü, sussam bir türlü', 'soylesem-bir-turlu-sussam-bir-turlu-haci-ozturk-md3pv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ela  gözlüm  seni  sevdiğimi....

Söylesem bir türlü, sussam bir türlü.

Senin  sevginle  vuslata  erdiğimi, 

Söylesem bir  türlü, sussam bir türlü.

Dal gibi boyu var, alımlıdır endamı, 

Kardan da bembyaz durur  gerdanı, 

Gördüğüm bir hayal yoksa  rüyamı, 

Söylesem bir türlü, sussam bir türlü.

Bakarken bile yakar  insanı gözleri, 

Baldan da şekerde de tatlıdır sözleri, 

Ay parçası mı, yoksa nur mu yüzler, ? 

Söylesem bir türlü, sussam bir  türlü.

Çöllere, kumlara yazdım ben bu sevdayı, 

''Hacı''ya  geniş ettin şu  dar  dünyayı, 

Seninle içtiğim suyu, soluduğum havayı, 

Söylesem bir türlü, sussam bir türlü.

Hacı  Öztürk                        03/04/2003

                                             LİBYA

KAYDEDEN                   Hacı  Öztürk', 'Ela  gözlüm  seni  sevdiğimi.... Söylesem bir türlü, sussam bir türlü. Senin  sevginle  vuslata  erdiğimi,  Söylesem bir  türlü, sussam bir ...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/soylesem-bir-turlu-sussam-bir-turlu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl anlatayım sana sevgimi', 'nasil-anlatayim-sana-sevgimi-haci-ozturk-3vk3t', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seviyorum diyorum seviyorum derinden, 

Daha nasıl anlatayım  sana  sevgimi.

Atamıyom, atamıyom seni düşümden, 

Daha  nasıl anlatayım  sana  sevgimi.

Bahar  gelir  çiçek  açar  yaz  olur, 

Dökülür yapraklar hazan olur güz olur, 

Ağustosta   erimeyen  buz  olur, 

Daha nasıl anlatayım  sana  sevgimi.

Bu  can  senle  olsa  candan usanmaz, 

Sevginle  yaşayan bu beden  yaşlanmaz, 

Bu  sevgiye ızdıraba  yürek  dayanmaz, 

Daha  nasıl  anlatayım  sana  sevgimi.

Hacı   Öztürk                          05/05/1986

                                                 İZMİR

KAYDEDEN                         Hacı   Öztürk', 'Seviyorum diyorum seviyorum derinden,  Daha nasıl anlatayım  sana  sevgimi. Atamıyom, atamıyom seni düşümden,  Daha  nasıl anlatayım  sana  ...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/nasil-anlatayim-sana-sevgimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdam sana nettim neyledim', 'sevdam-sana-nettim-neyledim-haci-ozturk-8qevx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Askerden  geldim  yirmi iki  yaşım, 

Doğuştan  akar  durmaz  gözyaşım, 

Zehir  zebberek oldu yenilmez  aşım, 

Söyle  sevdam sana nettim, neyledim.

Yüreğim  sevgi  bahçesine  dönmüştü, 

Pırıl, pırıl  hayallerle  dolmuştu, 

Mutluluk  benim için  mazi  olmuştu, 

Söyle  sevdam sana nettim, neyledim.

Aşktan  yüreğim yanmış  diyorlar, 

Senin  şansın  bağlanmış  diyorlar, 

Sevgi  zorla yaratılmaz diyorlar, 

Söyle  sevdam sana nettim, neyledim.

Kavuşmak  hevesiyle  aldım  teskere, 

Kapına  geldim, gittim kaç  kere, 

''Hacım  her gün  öldü, öldü  bin  kere, 

Söyle  sevdam sana  nettim, neyledim.

Hacı  Öztürk                         06/010/1976

                                               İZMİR

KAYDEDEN                        Hacı  Öztürk', 'Askerden  geldim  yirmi iki  yaşım,  Doğuştan  akar  durmaz  gözyaşım,  Zehir  zebberek oldu yenilmez  aşım,  Söyle  sevdam sana nettim, ney...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sevdam-sana-nettim-neyledim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tükeniyorum....', 'tukeniyorum-haci-ozturk-lah8i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Üşüyorum  sevdalım  hemde  öylesine, 

Çok  üşüyorum ki  ellerim  bum buz.....! 

Gözlerim  yinede  seni  arıyor, 

İçimde  yanıp sönmeyen hasretinle.

Ben  bittimde bitmedi senin hasretin, 

Yaşamaz  diye  umut  kesmişsin benden, 

Ölüm  döşeğinde bile  seninleyim, 

Sayıklarım adını  umut  kesmadim.

Belki  ihtimal gelirsin diye bekliyorum, 

İstemesende içimdeki bu son umut, 

Biliyorum yetti, bitti, solmak  üzere, 

Seni  görmeden  ölmek  istemiyorum.

''Hacım kaderinle kaldın kucak kucağa, 

Gel son nefesimi vermeden tut ellerimi, 

Son arzum, son  umudum  bu ne olur, 

Seni  görmek  için  çırpınıp  TÜKENİYORUM.....! 

Hacı  Öztürk                             05/06/1978

                                                  İZMİR

KAYDEDEN                         Hacı  Öztürk', 'Üşüyorum  sevdalım  hemde  öylesine,  Çok  üşüyorum ki  ellerim  bum buz.....!  Gözlerim  yinede  seni  arıyor,  İçimde  yanıp sönmeyen hasr...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/tukeniyorum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittin....', 'gittin-haci-ozturk-rwwc6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Onsekiz  yaşımda bir  rüzğar  esti, 

Tomurcuk  gülümü  saçtı da gitti.

Kör  etti  gözlerimi  göremez  oldum, 

Bu  genç  yaşta  aklımı  aldıda gitti.

''KIYMET''im   esmerdi  çokta  güzeldi, 

Bir  an  sevindirse  bir an  üzerdi, 

Ben   her  sözüne   inanamış  iken, 

Beni kaderimle  başbaşa bıraktı  gitti.

Aşk  dediysem  sakın  ateş  sanmayın, 

Her  sevgiye  gönülden bağlanmayın, 

Yel  dediysem  sakın  rüzğar  sanmayın, 

Onu  bir  el  oğlu  aldıda  gitti.

Çok mu gördün bu  sevgiyi  be zalim, 

Seni  severdim  ben  ne idi  derdin, 

Baş  başa  iken bana hep ''Hacım  derdin, 

Ne  diye  sözünden   cayıpta   gittin.

Hacı   Öztürk                        06/08/1979

                                               İZMİR

KAYDEDEN                        Hacı  Öztürk', 'Onsekiz  yaşımda bir  rüzğar  esti,  Tomurcuk  gülümü  saçtı da gitti. Kör  etti  gözlerimi  göremez  oldum,  Bu  genç  yaşta  aklımı  aldıd...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gittin-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Düşünüyorum', 'seni-dusunuyorum-orhan-durmus-ypz1u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni düşünüyorum bu akşam yine 

Yollara bakıyorum belki gelirsin diye

Beni hiç özlemesen sevmesen bile

Yollara bakıyorum belki gelirsin diye

