INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatamıyorum', 'anlatamiyorum-hikmet-karakus-ny5u9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yakamozlar kıpır kıpır

      içsel titreşimler gibi

Ve güneş kıpkızıl

       bir yürek gibi, 

Dinleniyorum sevgi denizinde; 

      bir dalga sesi, 

      bir martı sesi, 

      ılık bir meltem..

Ama ben anlatamıyorum

     doğanın yüreğimdeki iz düşümlerini

     bir kemanın yüreğimdeki depremini

     bir boya ustasının fırçasına

             estetiğin yansıyışını...

Ben ben miyim? 

Geleceğim geçmişim nerede? 

Nerede kaybettim yaşadıklarımı? 

Anlatamıyorum yine...

(İst.1980)', 'Yakamozlar kıpır kıpır       içsel titreşimler gibi Ve güneş kıpkızıl        bir yürek gibi,  Dinleniyorum sevgi denizinde;        bir dalga...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Karakuş']::text[], 8.5, '{"poet":"Hikmet Karakuş","poet_slug":"hikmet-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/anlatamiyorum-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-hikmet-karakus-ccu65', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu ne biçim gece, 

Bitmiyor karanlık, 

İnsan sevince, 

Sıkıyor yalnızlık.

Kendimi çölde sandım, 

Yalnız yürek sesi var, 

Çaresizliğe daldım, 

Sanki ayrılık acısı var.

(İst.1972-İlk şiir)', 'Bu ne biçim gece,  Bitmiyor karanlık,  İnsan sevince,  Sıkıyor yalnızlık. Kendimi çölde sandım,  Yalnız yürek sesi var,  Çaresizliğe daldım,...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Karakuş']::text[], 8.5, '{"poet":"Hikmet Karakuş","poet_slug":"hikmet-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yalnizlik-112-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giderim Bile Bile', 'giderim-bile-bile-derin-oger-utr4l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Giderim

Yar diye yanmayan

Bulanık gönülden

Gürül gürül çağlamıyorsa sevda

Giderim iç çekişlerimle

Günün aklığından alacakaranlığına

Tek tek toplarım bakışlarımı 

Giderim usul usul

Rüzgarın açtığı pencereden

İzler kalır ardımda

Bıraktığım sokaklarda

Ve içimde birikmiş tortular

Solar ümitler 

Bir güz akşamı aniden

Yıldızlar dağılır ardımdan

Gülücük olsa bile yüzünde 

Sormam artık gönlüme

Uçar giderim kırlangıç yüreğimle

Düşlerini fethedemediğim yürekten......', 'Giderim Yar diye yanmayan Bulanık gönülden Gürül gürül çağlamıyorsa sevda Giderim iç çekişlerimle Günün aklığından alacakaranlığına Tek tek ...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/giderim-bile-bile-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Benimdin', 'sen-benimdin-ozcan-ozkan-1gx3u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen benimdin.

Kimbilir şimdi nerede, kiminle, 

Nefes nefese, kan ter içinde.

Kendini nasıl verirsin? 

Küçücük tomurcuktun.

Yıl yıl, mevsim mevsim yeşerdin ellerime.

Boy attın izledim.

Büyüdün sevdim.

Sen benimdin.

Kiminle, nereye, nasıl gidersin? 

Tükeneceksin...

Umut umut çoğalmalar adına.

Kim seni benim kadar sarar sarmalar? 

Sanma sevdadır yaşadığın.

Ayaklarına dolanır anılar.

Gidemezsin...

(1993)', 'Sen benimdin. Kimbilir şimdi nerede, kiminle,  Nefes nefese, kan ter içinde. Kendini nasıl verirsin?  Küçücük tomurcuktun. Yıl yıl, mevsim m...', ARRAY['Türk Edebiyatı','Şiir','Özcan Özkan']::text[], 8.5, '{"poet":"Özcan Özkan","poet_slug":"ozcan-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sen-benimdin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pusu', 'pusu-gokay-balci-4bplr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir bahar günüydü, akşam üstüydü

Adam köşeyi henüz döndüydü

O daracık sokak, bir infaz evi

Üç kurşunda yıktılar koca bir devi

Dört kişiydi köşede pusuya yatanlar

İkisi seyretti, iki kişiydi vuranlar

İki tanık bıraktılar geride

Ben gördüm olayı, yağmur gördü bir de...

İlk kurşunda düşmedi, sarsıldı önce

Hırsla doldu gözleri vuranı görünce

Ayakları kıpırdasa gidip tuttacaktı

Yumruğunu beynine kurşun gibi sokacaktı

İkinci kurşun çöktürdü yere

Sonra titredi inceden bir kere

Yırtılmış gömleğinden kan akıyordu

O mavi gözler artık boş bakıyordu

Son bir hırsla başını kaldırdı

Göğsüne üçüncü kurşunu sığdırdı

Artık tutamadı saldı kendini

Önce elindeki file düştü, sonra bedeni

Filesinde bir ekmek vardı, bir de şişe

Mezar oldu ona hergün döndüğü bu köşe

Tek ekmek...Demek yalnız yaşıyormuş barakasında

Yetim, yahut dul bırakmadı arkasında

Bir yerden gözüm ısırıyor bu herifi

Tamam tamam! Bu Biroğulları''nın Arif''i

Birkaç kez konuşmuşluğum var onunla

Memleket meselesi işte, tartışmıştık sonunda

Belli bir işi yoktu, çulsuzdu o da

Bazı akşamlar saz çalardı gazinoda

Tehlikeliydi şarkıları, aşkım derdi ''kavgam''...

Alıp götürmüştü polisler bir akşam

Birkaç ay gözükmedi ortalarda

Anladık ki içerde hala, voltalarda

Konuşamadık çıkınca, soramadım ''kolun niye kırık''

Eh! Öteki tarafta sorarım artık...

Öğrendim aslını, niye vurulduğunu

Kimin bu aşkı, bu gülü soldurduğunu

Anladım kavganı da, seni de, koyuldum yoluna

Fazla geç kalmam Arif, bugün yarın gelirim yanına...', 'Bir bahar günüydü, akşam üstüydü Adam köşeyi henüz döndüydü O daracık sokak, bir infaz evi Üç kurşunda yıktılar koca bir devi Dört kişiydi k...', ARRAY['Türk Edebiyatı','Şiir','Gökay Balcı']::text[], 8.5, '{"poet":"Gökay Balcı","poet_slug":"gokay-balci","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/pusu-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yok ki Senden Bir Tane Daha', 'yok-ki-senden-bir-tane-daha-derin-oger-dipqj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kolay işti sevmek 

Düş ne demek acı ne demek 

Hep senin için dalardım denizlere 

Hüzünle dolardı gözlerim 

Koşup bana geldiğinde 

Oyundu itip kakmaların 

Anlattığım masalları dinlerdin 

İçimi kendime saklamayı bilmezdim 

Dayanılmaz yokluğunu çıkadığında karşıma 

Korkmadım yarım kalan tebessümlerimden 

Korkmadım yalnızlığımdan hüzünlerimden 

Korku neydi bana sen kalbimdeysen 

Sen kalbini göğsünden sökmedin ki 

Sen acı hapları şeker diye yemedin ki 

Sen sevgiyi göğsünde muhabbet sanıp 

Sarhoşluğuyla ölümlere gitmedin ki 

Tanrı bile bir şeyleri vurmazken yüzüme 

Sen kalbimi kalbinden vurdun yerlere 

Aldandım ama 

Aldırmadım yüreğin acısına 

Yoktu ki senden bir tane daha 

Yoktu................', 'Kolay işti sevmek  Düş ne demek acı ne demek  Hep senin için dalardım denizlere  Hüzünle dolardı gözlerim  Koşup bana geldiğinde  Oyundu iti...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yok-ki-senden-bir-tane-daha-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüşümün İzini Bulurlarsa Aynada Gözlerimden Vurularak Öldürüleceğim', 'gulusumun-i-zini-bulurlarsa-aynada-gozlerimden-vurularak-oldurulecegim-namik-kuyumcu-npwhc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '(kör oldu kuyu. alındı gözlerim.

gitmek dedin. yelkenlerin vardı.

kaburgalarımı istedin... ödünç

dedin. sadece ödünç...)

zaten ödünçtür yaşamak

çığlıklar kendisine kırgın seslerden alınmıştır

gözyaşları gözlerden ve ipek inceliklerden

varsın ağlarımda aldatsın beni

sevmeyi kahanet saydığım günlerim

iflah olmaz bir aldanış olarak yazılabilir

yine de gökyüzündeki bütün yıldızları 

armağan ediyorum

eski zaman satıcısı eski sözlere

yüreğimin yelkenini aşk rüzgarlarıyla açarak

günahlar işliyorum

ve yanlışıma secde ediyorum

sevmeyi kahanet saydığım günlere 

soruyorum

''uçurumları sevenlerin hep kanatları mı olmalı''

2.

zaten ödünçtür yaşamak

bütün avcılar biraz da avdır sürekte

3.

yasak sevişmelerin şehvetiyle ağardı gün

yağmur dindi

bahar gücenik

gücenik bütün sular

cinnet geçiren cinsellikleri tanımlıyor bir tanrı tanımaz

bileklerini kesmeyi kendine yediremeyen çocuk

yine kör jiletle traş ediyor yüzünü

ülkem biraz daha esmerleşiyor

sarışın bir kadın kaçırıyorum masamdaki atlastan

çay sunup harmandalı oynarken karşısında

yenilip yerçekimine ve gözlerine düşüyorum

kekemeliğiyle güzelleşen dostum geliyor aklıma

aşkların da tanrıtanımazlığı

4.

zaten ödünçtür yaşamak

aşk için damarlarımızı terkedebilir kan ve kırmızı

5.

aşk ve ihtiras

kine ve küfre dönüşünce

hançerin kınıyla ilişkisi tanımlandı yeniden

anladım neden demirini inkar ediyordu demirci çarşılar

çanların ses vermediği zamanın hesabı

neden çekiçlerden soruluyordu/yanılsamayı öğrendim

kendimi avutmak için

dokunmak ve gülüş

ve tenlerin ihtilalini edindim

gücenik sular kör çeşmelere akıyordu

gücenik bahar ve gözyaşları kör kuyulara

siz hep kaçak ve çerçevesini terkeden resimdiniz

6.

gitmenin vakti gelmedikçe

her ayrılık bir şakadır biliyorum

''kalmak'' fiilleri yeniden çekimlenir

şarap rengindeki hicran sayfalarında

bütün denizleri terkeden gemilerin

karaya oturmuş kaburgası gibidir aşk

yalnızca kendi kıyısında eskir

aşk da ödünçtür aslında', '(kör oldu kuyu. alındı gözlerim. gitmek dedin. yelkenlerin vardı. kaburgalarımı istedin... ödünç dedin. sadece ödünç...) zaten ödünçtür yaşa...', ARRAY['Türk Edebiyatı','Şiir','Namık Kuyumcu']::text[], 8.5, '{"poet":"Namık Kuyumcu","poet_slug":"namik-kuyumcu","theme":"Türk Şiiri","is_hero":false,"total_lines":61,"source_url":"https://www.antoloji.com/gulusumun-izini-bulurlarsa-aynada-gozlerimden-vurularak-oldurulecegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasadışı Düşlerde Ansıdığım', 'yasadisi-duslerde-ansidigim-namik-kuyumcu-cuuoa', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yalnızlığın demirini kırdı

yasadışı düşlerim 

beynimin sahiline vurdu

teninin rengi

gözlerimde voltalıyor gülüşün

ürkütme

sessizce bağdaş kur sevincime 

söyleşelim

bekleyişin ustura keskinliğiyle kıyılmış

buruk bir sigara sarayım sana

yüz hatlarımda gezinerek tüttür

hüznün dumanını

kopartmadan kavuşmanın çiçeklerini

avuçlarıma doldur

bırak kulaçlasın erinç çizgilerini

nicedir ansıdığım sevmelerin

vaktidir şimdi

yemini var 

tütün acısı dudaklarımın yemini

ceylan gözlerinden korkuyu atıp

pınarlarından içeçeğiz dağların', 'yalnızlığın demirini kırdı yasadışı düşlerim  beynimin sahiline vurdu teninin rengi gözlerimde voltalıyor gülüşün ürkütme sessizce bağdaş ku...', ARRAY['Türk Edebiyatı','Şiir','Namık Kuyumcu']::text[], 8.5, '{"poet":"Namık Kuyumcu","poet_slug":"namik-kuyumcu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yasadisi-duslerde-ansidigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mecnun', 'mecnun-zeki-muren-dn9tt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir gün mecnun çalarsa kapını

Gözlerine iyi bak:

Kendini göreceksin bebeklerinde.

Dağınık saçlarında duman duman kendini.

Çatlak dudaklarında eski aşkını yol yol...

Dilenirse boşlama, 

Gönlünden bir dilim at.

Sevap işlersin

Aşkımın zekatını gönlümün sahibine verdim dersin...', 'Bir gün mecnun çalarsa kapını Gözlerine iyi bak: Kendini göreceksin bebeklerinde. Dağınık saçlarında duman duman kendini. Çatlak dudaklarınd...', ARRAY['Türk Edebiyatı','Şiir','Zeki Müren']::text[], 8.5, '{"poet":"Zeki Müren","poet_slug":"zeki-muren","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/mecnun-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Terziler', 'terziler-caglar-akarsu-wuhh1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '.

Nice ciddiyetsiz insanlar gördük, 

Bazı köşe başlarında bekleşen, 

Üzerlerinde ki libasları dar geldi, 

Sıkışmış kalmışsa kişilikleri, 

Boyunlarında tasma oldu töreleri, 

İnsan bu değil mi? ? 

Şehirlerde taş yığınları, 

Yaşanırken değişik kültürler, 

Bir yörenin insanı, diğerine özendi, 

Giysileri üzerlerinden döküldü, 

Diktirecek kumaşları kaybettiler.

.....

“Her taş yerin de ağırdır” diye, 

Gelmiş –geçmiş tüm atalarımız söz etti, 

.....

Terzi elinden, çıkmış elbise uyarsa, 

Kumaşın görünüşünde zarafet vardır, 

Konfeksiyon işi, çizgili “daltonlar”

İkiz kardeşlere benzedi de, durdu.

.....

Rumeli türküsü, okursa  eğer Antep’li

Şivenin altında kalmış çıkrık gibi, 

Dönerken bin bir ses çıkarır, durur.

Ciyak ve gıdak ederken saz inledi, 

....

Ciddiyet bir gömlek, olsa, 

Yunus gibi mısralardan çıkararak, 

Üzerimize değil! ruhumuza kazısak, 

İnsan bu, daha güzel görünür.', '. Nice ciddiyetsiz insanlar gördük,  Bazı köşe başlarında bekleşen,  Üzerlerinde ki libasları dar geldi,  Sıkışmış kalmışsa kişilikleri,  Bo...', ARRAY['Türk Edebiyatı','Şiir','Cağlar Akarsu']::text[], 8.5, '{"poet":"Cağlar Akarsu","poet_slug":"caglar-akarsu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/terziler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasan Dayı', 'hasan-dayi-caglar-akarsu-tkxhp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '....

Vadilerin içinde uzanırdı ovalar, 

Her ağacın altı ayrı bir gölge olurdu, 

Bir sabah gün doğarken başladı, 

Yaşam kavgası, 

Güneş gibi sıcak sevgilerle, 

Köklü fidanlar, birden yeşillendi, 

Bizlere doğru koşup da geldi, 

Doğumun  yeni müjdeleri, 

Kadın ve erkek, 

Her sonun, yeniden başlangıcı gibiler, 

.....

Yıllar akıp giderken, 

Ekinler tarlalarda boy attı, saçak-saçak, 

Buğdaylar topraktan fışkırarak, 

Doğanın  ve çiftçinin alın teri, 

Kızgın Ağustos güneşi kavurdu her şeyi, 

Haramda binlerce ekin  tohum-tohum, 

Eylül ayının son çağrışımlarında, 

Haykırdı gitti, 

Hasan Dayı, 

....

“ Ey toprak ! ! ”

“Ey çiftçi    ! ! ”

...

Gazan mübarek olsun, 

Ekmek kavgasının ter ile karıldığı, 

Ellerindeki tek silah buğdaydı, 

Doğrulttu gökyüzüne doğru, 

Gür sesi yankılandı, dağların tepesinde, 

....

Utanmaz insanlar, koltuklarda yan geldiler, 

Zannettiler ki hiçbir zaman devrilmeyecek, 

....

Hasan Dayı, 

Nasırlı ellerini yüreğine bastırdı, 

Bir nara attı. Tüm toprak ağalarına, 

“ Gazan mübarek olsun, 

Alın terin emeğin olsun”

Çarıkları ayaklarını sıktı bir anda, 

Yollar toprak kokusunu taşıdı, 

Üzerindeki tozlu elbiseleri savurdular, 

O gece vakti ekti, tarlasını bir çift öküzle, 

Sırtında bir ekin çuvalı saçtı her köşesine, 

Yüreği ağzında başını, kaldırdı, 

Çağırdı yağmur damlalarını, 

Hasan Dayı, 

Memiş komşusuna seslendi, 

“Ekinin bol olsun, rahmetin çok olsun”

Şöyle bir efkarlandı, sevdasından, 

Toprak diye iç geçirdi, 

Çorak, 

Verimli olduğu yıl bereket doğurdu, 

Şölen kazanlarının altını yaktılar, 

Töreler içinde bir yarı kutladılar, 

...

“ Gazan mübarek olsun, 

Alın terin, emeğin olsun”...

Hasan Dayı...

19/haz/03', '.... Vadilerin içinde uzanırdı ovalar,  Her ağacın altı ayrı bir gölge olurdu,  Bir sabah gün doğarken başladı,  Yaşam kavgası,  Güneş gibi ...', ARRAY['Türk Edebiyatı','Şiir','Cağlar Akarsu']::text[], 8.5, '{"poet":"Cağlar Akarsu","poet_slug":"caglar-akarsu","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/hasan-dayi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluğun Benim Elimde', 'mutlulugun-benim-elimde-ensar-aktas-r3c29', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni hiç kimse ne benim kadar anlayabilir

Ne de benim gibi sevebilir

Gör bak hiç bir erkek seni mutlu edemeyecek

Gelen gideni aratıp gidecek

- Ya sen? diyeceksin

- Sende onlardan biri değil misin? 

Hayır, ben onlardan biri değilim

Çünkü ben hiç gitmedim

Biliyorum hâlâ kalbindeyim

Nasıl benim kaderim senin elindeyse

Senin mutluluğun da benim elimde

Ve ölene dek.............! 

Rotterdam, 29.09.2002', 'Seni hiç kimse ne benim kadar anlayabilir Ne de benim gibi sevebilir Gör bak hiç bir erkek seni mutlu edemeyecek Gelen gideni aratıp gidecek...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/mutlulugun-benim-elimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tombaladan Çıkan Aşk', 'tombaladan-cikan-ask-ensar-aktas-mrg8c', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerime bakıp durma öyle manalı manasız

Başka gözlerden izler bulursun anlamlı anlamsız

Gönlüm sürprizlerle doludur faydalı faydasız

Sende daldır elini, tombalaya daldırır gibi

Belki aradığın aşk çıkar şansına zamanlı zamansız

Unutma ki bu tombala yasak bir aşk oyunu, ruhsatsız

Tombaladan çıkan aşkta yasak aşktır, ama zararsız

Woerden,08.10.2002', 'Gözlerime bakıp durma öyle manalı manasız Başka gözlerden izler bulursun anlamlı anlamsız Gönlüm sürprizlerle doludur faydalı faydasız Sende...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/tombaladan-cikan-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilemedim be gurban bilemedim...!', 'bilemedim-be-gurban-bilemedim-haci-ozturk-kcu90', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aylardan  eylül, 

Yine  hazan  geldi

Yapraklarımız  dökülüyor

Sevdik, sevdik, sevdik

Sevmek  suçmuş  bilemedik

Niye  be  gurban  niye.............! 

Sevgiyi  onur  bildik, 

Sevgiyi   gurur  bildik, 

Sevgiyi   sevgi  bildik

Ne  idi  suçumuz  ne  idi, 

Ne  idi  be  gurban...................! 

Ayrılık mı  oda  ne.....? 

Bilemezdim, bilmedim, ayrılığı, 

Bilemedim, hasreti, özlemi, 

Bilemedim be  gurban............! 

Hazan  yağmurlarını  severdim, 

Hazanda  savrulan  yaprakları, 

Meğer  yağan  hazan  yağmuru  değilmiş, 

Kömürkarası  gözlerinden  akan  yaşlarmış, 

Gözyaşlarından  nefret  ederim, 

Nefret  derim be  gurban...............! .

Mehtaplı  gecelerde

Yıldızları  seyrederdim

O, yıldızlar ki   senin

Kömürkarası  gözlerine  benzerdi

Onlar  şimdi  parlamıyor, 

Parlamıyor  artık  yıldızlarda

Onlardamı  küstü  ne...? 

Küstümü  söyle  be  gurban...............! 

Bak  dinle  beni, 

İzmir’in  sıcağı  yakmaz  insanı, 

İzmir’in   yağmuru  ıslatmaz

İzmir’in  kızları  varya  izmir’in, 

Adamı  yakar,  yıkar,  çürütür, 

Çürütür  be  gurban...................! 

Ölüm mü, dedin  hah, hah, hah...! 

Gülerim  be gurban  gülerim, 

Ölüm  dediğin..

Bir  nefestir, bir  nefes, 

Aldığı  soluk, içtiğin  su kadar, 

Ölümü  özledim  be gurban  özledim.

Yıllardır  bu  sevda  ölümmüş  bilmedim.

Bilemedim  be  gurban   bilemedim.........! 

Hacı   Öztürk                      28/05/2003

                                              LİBYA

KAYDEDEN                       Hacı  Öztürk', 'Aylardan  eylül,  Yine  hazan  geldi Yapraklarımız  dökülüyor Sevdik, sevdik, sevdik Sevmek  suçmuş  bilemedik Niye  be  gurban  niye..........', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/bilemedim-be-gurban-bilemedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gurbette Tam Kırk Yıl', 'bir-gurbette-tam-kirk-yil-ensar-aktas-mwotd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dile kolay tam kırk yıl

Kırık dökük, kırk yılık yıl

Ağlattılar anamızı

Ağarttılar saçımızı

Büktüler belimizi

Yediler hakkımızı

Acımız içimizde 

Sancımız dilimizde

Canımız dizimizde

Sıktılar suyumuzu

Vatanda Alamancı

Alaman’da yabancı

Kim yolcu, kim hancı

Kim mefta, kim mezarcı

Sürgünde sürgün

Hapiste mahpus

Öldünse öldün

Kaldınsa sürün

Hasretse hasret

Tüterse tütsün

Biraz daha sabret

Ocağın sönsün

Ne mantık kaldırır bunu, ne akıl

Kılı kırk yardılar tam kırk yıl

Bir lokma uğruna evcil hayvanlar gibi

Taktılar boynumuza tasmağı velhasıl

Rotterdam,16-06-2003', 'Dile kolay tam kırk yıl Kırık dökük, kırk yılık yıl Ağlattılar anamızı Ağarttılar saçımızı Büktüler belimizi Yediler hakkımızı Acımız içimiz...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/bir-gurbette-tam-kirk-yil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak Ağır Geliyor', 'yasamak-agir-geliyor-metin-usengec-i8s9z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çok zormuş kalpten sevmek

Ağır geldi böyle terk edilmek

Bir bedeli olacak bunun muhakkak

Zamanla payıma düşeni öderim elbet

Gecen zaman ne iyiye ne güzele

İçimde daha derine daha da kötüye

Bir karanlık ki yakınlaşıyor

Yaşamak çok ağır geliyor çok

Düşündükçe yaşadıklarımı

İçime bir ağırlık çöküyor

Bir özlem bir ayrılık değil

Nerden baksan tek taraflı olanlar

Ya diğer tarafa kalanlar 

Anladım ki bu acıyla yaşamam zor

İnancım güvencim kalmadı kimseye

Sevmek sevilmek herşey yalan

Sevince kaybetmek var hep geriye kalan

Bir can içinde başka bir can

Her an her saniye aranan

Arandıkça bulunamayan uzaklara kaçan

Karşılığını bulamayan ama hep seven

Sevgisi altında herşeyi ile ezilen

İçten içe yaşadıklarım çektiklerim

Dayanılacak gibi değil

Her nefesimde içime çektiğim

Sanki bildiğimiz hava değil

Yaşamaktan yan dertliyim

Ateş düştüğü yeri yakar

Beni ancak gerçekten sevip terk edilenler anlar..

19-Haziran-2003  12:00

Sende Bir Gün Seversin Sözün Geçmez Kendine..', 'Çok zormuş kalpten sevmek Ağır geldi böyle terk edilmek Bir bedeli olacak bunun muhakkak Zamanla payıma düşeni öderim elbet Gecen zaman ne i...', ARRAY['Türk Edebiyatı','Şiir','Metin Üşengeç']::text[], 8.5, '{"poet":"Metin Üşengeç","poet_slug":"metin-usengec","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/yasamak-agir-geliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni aradım....', 'seni-aradim-haci-ozturk-j322f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaşaran  gözlerimin, 

Islak  perdelerinden, 

Deryada  martılar gibi, , 

Seni  aradım.

Bazende  gecenin, 

Tek  yıldızı gibi, 

İsmini  haykırdım, 

Yalvardım  ağladım.

Kaldırım  taşlarına..

Seni  sordum, 

Dar ağacına  astım, 

Çaresizliğimi.

Saçlarım  tarumar, 

Bedenim  harap, 

Ak  pak  kağıtlara seni, 

Seni  yazıpta, 

Seni  aradım  hep  seni.

Hacı   Öztürk           Libya

KAYDEDEN           Hacı  Öztürk', 'Yaşaran  gözlerimin,  Islak  perdelerinden,  Deryada  martılar gibi, ,  Seni  aradım. Bazende  gecenin,  Tek  yıldızı gibi,  İsmini  haykırd...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/seni-aradim-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SENİNDE KULAKLARIN ÇINLIYORMU..?', 'seni-nde-kulaklarin-cinliyormu-haci-ozturk-1vbs8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yine  kördüğüm  duygulara  büründüm, 

Şu  gün  batımlarında.

Çaresiz  umutlarla, 

Dolaşıyorum  sensiz, 

Ve  erkekliğimden  uyanmadan, 

YUTKUNUYORUM.......

Sen  doğan  çoçuklarımın  anası, 

Evimin  direği, yuvamın  bereketi, 

Sana  öyle  özlem  doluyum ki, 

SORMA......

Her  an  her saat......

Senli  düşler  sarıyor  benliğimi, 

Öylesine  anıyorum, anıyorum ki, 

Seninde  kulakların  çınlıyor mu...? 

Hacı   Öztürk                 20/06/2003

                                       LİBYA

KAYDEDEN                 Hacı  Öztürk', 'Yine  kördüğüm  duygulara  büründüm,  Şu  gün  batımlarında. Çaresiz  umutlarla,  Dolaşıyorum  sensiz,  Ve  erkekliğimden  uyanmadan,  YUTKU...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/seninde-kulaklarin-cinliyormu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suç ve Ceza', 'suc-ve-ceza-bekir-gedikoglu-sia2e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yıl bin dokuz yüz elli yediydi

Benim yaşımda yedi

Günler günleri kovalıyordu

Babam nafakasını, silah kaçakçılığı yaparak sağlıyordu

Bugün Cuma...günler durdu

Sivil polisler o gün, dükkanın önünde durdu

Onlar bugüne kadar bir açığımızı kolluyordu

Bu dükkanda polisler, altlık ve üstlük gibi tabanca imalat parçalarını buldu

Vurdular Babama, vurdular Amcama, kelepçeyi kollarına

Götürdüler onları Yaraş köyünden, Tirebolu daki mahpushanaya

Hukuk dilinde buna derler “tutuklama”

Amma ben diyorum ki

Bu Şahinleri kafese koyma

Yavruları kaldı dışarıda

Onların gönülleri kaldı mahpushana’da

Tırnak etten ayrılmazdı burada

Akılları, fikirleri kaldı bu damda

Her şeyde olduğu gibi

Zikirleri kaldı, sabırları kaldı

Allaha...

Tutuklamanın ardından, mahkeme ilamı asıldı kapıya

Nafakasını demirden çıkaran adamlara

Tam iki buçuk yıllık bir ceza

Yaraş köyünden indik...Tirebolu’ya

... Köyümdeki hayat bitti

Yeni yaşama merhaba

Ankara,22.06.2003', 'Yıl bin dokuz yüz elli yediydi Benim yaşımda yedi Günler günleri kovalıyordu Babam nafakasını, silah kaçakçılığı yaparak sağlıyordu Bugün Cu...', ARRAY['Türk Edebiyatı','Şiir','Bekir Gedikoğlu']::text[], 8.5, '{"poet":"Bekir Gedikoğlu","poet_slug":"bekir-gedikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/suc-ve-ceza-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklım Mavide Kaldı', 'aklim-mavide-kaldi-ensar-cevval-jc3ik', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bugün maviyi seyrettim Çamlıcadan

kırışmıştı her yanı, balıkçı teknelerinin-

önünden kaçan balık sürülerinden

koca bir gemi, ütüler gibi geçince üzerinden

yaşlı yalıların çığlıklarını duydum bu yükseklikten

İki adi kolye takılmıştı boynuna mavinin

yaralanmıştı ceylani boynu iki kenarından tarihin

omuzlarına attığı bizans işlemeli yeşil hırkayı

içten içe kemirmişti soluk yüzlü güveler

açılan boşluğa hakimdi, hantal taba renkler

Yanıma gelsin demiş, martılar kulağıma değdirdi

hoş martı mıydı bilemedim ya gri renkli kuşlar? 

İndim, Beylerbeyinden selamlayarak tarihi

eğildim, diz çöktü ben gibi, benimle gelen kuşlar

yosun tutmuş kenarlı mavi patiskanın ucuna.

Yamacından geçen araçları gösterirken

Gözlerim takıldı ellerine; yeşile kaçmıştı

hiddetimi içimde dedi; çünkü bir söz aldım/verdim 

sana sırrımı anlatayım mı deyip gözlerini kapattı

bekledim avuçları ellerimde; ama, mavi gözleri uykuya daldı.', 'Bugün maviyi seyrettim Çamlıcadan kırışmıştı her yanı, balıkçı teknelerinin- önünden kaçan balık sürülerinden koca bir gemi, ütüler gibi geç...', ARRAY['Türk Edebiyatı','Şiir','Ensar Cevval']::text[], 8.5, '{"poet":"Ensar Cevval","poet_slug":"ensar-cevval","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/aklim-mavide-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ötesi Boş Küp', 'otesi-bos-kup-sule-aydemir-9vr3f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kan-ter yıkanır tensel düşünceler

sen ve ben ötesi boş bir küp

tutarsın ellerimi ve silinir gökler

değmez zeminlere yükselir beden 

aşktır ki bu kını yok kırışığı yok gençtir

para tanımaz yıl zaman tanımaz

kılıfı yok bendeni yok fiziği yok

her şey inanılmaz güzeldir 

içe dönüş keşiftir 

nadirin bir armağanı 

teslimi yok adresi yok

hormondan hisler

yola çıkan düşüncelerdir

kanın tersine akışı

ateşin tavan yapması

olmaz ayıbı utanması 

aşk varoluş mükemmeliği

ağaran bir saç teli daha eklenen sevgiden

parlak ışıkların kucaklamasıdır

ve bir çıkış iniştir en güzelinden

yaşamak özgürce iliklerinde

pişmanlık olmadan yaşayamamışlıkta

adım adım ilerlemek 

yudum yudum özümsemek

duyguların sivri kenarlarında 

aşk yakarda geçer

dokunmak sekizinci harikaya

düşerken turbulans uçurumlara

gülümsemek yüreğinle

ve çıldırtmak kimliğini umarsızca çığlık çığlığa

çakılmadan yürümek

yarını olmadan söküp almak 

hep bu güne  doldurmak anı 

ah aşk! 

dokunmak parmaklarınla yıldızlara

ayı çiçek yapıp takmak saçlarına

güneşe kırpmadan bakmak gözlerini

silmek herkesi ve her şeyi

sessizliğe dans ettirmek sevgiyle

hiçken ve anlam bulmak aşkında aşkta

kör sağır ve kütürüm kalmak 

ruhu uçurtmak sevdadan bulutlara

gönüllüce sevincinde 

engellenemez 

sevimli bir sırıtış 

belki de olmayacak yarınlara', 'kan-ter yıkanır tensel düşünceler sen ve ben ötesi boş bir küp tutarsın ellerimi ve silinir gökler değmez zeminlere yükselir beden  aşktır k...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/otesi-bos-kup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerinin Hapsindeyim', 'gozlerinin-hapsindeyim-hikmet-yakisir-a0he8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerinin hapsindeyim, 

Bedenin koğuşum, 

Kalbin ranzam, 

Bitmesini istemediğim, 

Müebbettir cezam.

Ranza iki kişilik, 

Üstte biri var, 

İdam mahkumu.

Ben alttayım, 

Eziliyorum, canım yanıyor.

Koğuş dar, 

Ranza yıpranmış, 

Yılların izleri var.

İki kişiyi taşıyamıyor.

Birimizi sal.

Tercihini yapma zamanı, 

Ey gardiyan.

Ya idamlığı seçersin, 

Ya da müeebbet mahkumu, 

Karar vakti.

Hakim de sensin, savcı da, 

İdamlığı seçersen, ölüme mahkum.

Beni seçersen, 

Yaşıyorum hiç değilse.

Gözlerinin hapsinde.

Belki bir gün af çıkar, 

Azad edersin beni.

Kalbinde inşa ettiğin, 

Yeni hapishaneye

Başgardiyan olurum.

(21 Haziran 2003)', 'Gözlerinin hapsindeyim,  Bedenin koğuşum,  Kalbin ranzam,  Bitmesini istemediğim,  Müebbettir cezam. Ranza iki kişilik,  Üstte biri var,  İd...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Yakışır']::text[], 8.5, '{"poet":"Hikmet Yakışır","poet_slug":"hikmet-yakisir","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/gozlerinin-hapsindeyim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sen Vardı', 'bir-sen-vardi-hikmet-yakisir-et7e2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerin vardı derin.

Severek baktığında etkileyici, 

Kızgın baktığında hançer gibi delici, 

Seyrine doyamadığım okyanuslar gibi, 

Okşarcasına bakan, rahatlatıcı serinletici.

Tenin vardı yumuşak.

Yağmur yağdığında toprak gibi kokan.

Ana gibi, yar gibi mis kokular salan.

Başımı göğsüne koyduğumda derin sevdalara dalan

Kalp hırsızı seni, beni benden çalan.

Kalbin vardı, tertemiz

Kapısı sevdalara aralık.

Sen varken gecelerim aydınlık, 

Gidince gündüzlerim oldu karanlık.

Aşkımı ettin beş paralık.

Bir sen vardın güzel, 

Dikkatli ol sevdiğim bu aralar, 

Gözlerine başka gözlerin bakması zarar, 

Herkes benim gibi bakamaz, tırmalar, 

Kimi hırpalar seni, kimi kalbini yaralar.

Sen oldun giden, 

Giderken bende unuttuğun, 

Hançer bakışlı gözlerini

Toprak kokan tenini

Gecelerimi aydınlatan kalbini, 

Lazım olur sevdalarına, gel al sevgili.

(23 Haziran 2003)', 'Gözlerin vardı derin. Severek baktığında etkileyici,  Kızgın baktığında hançer gibi delici,  Seyrine doyamadığım okyanuslar gibi,  Okşarcası...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Yakışır']::text[], 8.5, '{"poet":"Hikmet Yakışır","poet_slug":"hikmet-yakisir","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/bir-sen-vardi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vurur Da Geçer Ayrılık', 'vurur-da-gecer-ayrilik-naime-erlacin-zgq1s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'hüzünlü bir şarkı bu

nağmeleri 

beynimde savrulan

mutlaka yazmalı son şiiri

o mahur bestede ağlamalı 

“bizimkisi bir aşk hikâyesi” 

der gibi

asmalı dizeleri gök kuşağına

hançer gibi vurarak heyhat 

geldi ve geçti ayrılık! 

düşlerimdir ağlayan 

paramparça

canhıraş 

sonsuz bir haykırışta

biliyorum artık

vurup da geçermiş ayrılık 

(22 Haziran 2003)', 'hüzünlü bir şarkı bu nağmeleri  beynimde savrulan mutlaka yazmalı son şiiri o mahur bestede ağlamalı  “bizimkisi bir aşk hikâyesi”  der gibi...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/vurur-da-gecer-ayrilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Gönlüm', 'deli-gonlum-melek-midikoglu-mfz71', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerindeki o ışıltı varya 

Deli etti beni dün gece hatırlayınca 

Hani umutsuz olduğun günler olur ya 

Sil baştan canım sen çiz dünyaya 

Benim deli gönlüm başaramadı ya 

Seni belki sever bu huysuz dünya 

Olurda birgün hiçbirşey hissetmezsem 

Zil çalıp oynarım içten içten 

Belki sen sevince ben de severim 

Belki ben de gülerim içten seninle 

Güllerim solmaz, kuşlarım susmaz 

Ve gözlerim gülümsemekten hiç bıkmaz 

Senin gözlerin misali...', 'Gözlerindeki o ışıltı varya  Deli etti beni dün gece hatırlayınca  Hani umutsuz olduğun günler olur ya  Sil baştan canım sen çiz dünyaya  Be...', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/deli-gonlum-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özel', 'ozel-melek-midikoglu-k293x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şiir yazayım

Kimseler okumasın

Bir sen...

Şarkı söyleyeyim

Kimseler duymasın

Bir sen...

Resmini çizeyim

Kimseler olmasın

Bir sen...

Dansedeyim

Kimseler görmesin

Bir sen...

Öleyim

Herkesler duysun

Sakın ha sen...', 'Şiir yazayım Kimseler okumasın Bir sen... Şarkı söyleyeyim Kimseler duymasın Bir sen... Resmini çizeyim Kimseler olmasın Bir sen... Dansedey...', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ozel-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çelişki', 'celiski-melek-midikoglu-6vly5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Korkak! 

Ne olacak biraz batsa taşlar

Ayakların çıplak

İlerde pamuklarda yüzecektin

dayansan

Yürü! 

Çok sevdim seni

Selam ver

gerisi muhtemel', 'Korkak!  Ne olacak biraz batsa taşlar Ayakların çıplak İlerde pamuklarda yüzecektin dayansan Yürü!  Çok sevdim seni Selam ver gerisi muhteme...', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/celiski-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgarlar Prensi', 'ruzgarlar-prensi-melek-midikoglu-md02i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'rüzgârın sesiyle gel

göreceksin yıldızları

güneşle birlikte..

gülün üzerindeki

ılık yağmur damlası

değecek yanağına

buhar olup yerleşecek

tenine..

sen rüzgârlar prensi

sereceksin kendini

tüm benliğinle

sesin kahkaha renginde..', 'rüzgârın sesiyle gel göreceksin yıldızları güneşle birlikte.. gülün üzerindeki ılık yağmur damlası değecek yanağına buhar olup yerleşecek te...', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ruzgarlar-prensi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğum Günü', 'dogum-gunu-murat-tali-zgvx4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sana sorduk mu dünyaya getirirken

gelmek istermisin diye

sanırım hayır

bana da sormamışlardı

şimdi sen 10 yaşına giriyorsun

ben ise 32ye doğru yol alıyorum

şunun şurasında iki ay kaldı sonra yolun yarısı

çocuğum

çocukluğumun eksikliği

belkide yarınlarımın

bugünü

derler ya

insanlar yaşlanınca çocuklaşırmış diye

ben yarın olmadan da çocuğum

beni arkadaş eyle

salıncağında, bisikletinde, evciliğinde

hatırlıyormusun

benimle nöbetime gelişini

boyun boyuma denk gelmişti birden

büyümüştün

ama daha dün beşikteydin

sen

doğduğun günü hatırladım

babalar günüydü

yemyeşil bir yaz günü

saat 14.50 

günlerden pazardı

kırmızı bir suratın vardı

küçücüktü ellerin ve ayakların

hayallerin yoktu o zaman yarına dair

nede güne 

güneş çığlıklarınla batmıştı

seni doğuran ebe 

Nezaket takın demişti adını

kendi adıymış

gülmüştük

en demokratik ortamda belirledik adını

CANSU

torbaya koyduğumuz 

kağıtlara

kim yazıp koymuştu adını 

hatırlamıyorum

sonra bir gün

''Bende bu evde yaşıyorsam benimde söz hakkım var demiştin''

sanırım yedi yaşındaydın 

evet 

canım yaşadığın heryerde söz hakkın var

bu yüzden susma

ilk hüzünlü bakışlarını gördüğümde 

yıkılmıştım

çünkü üç yaşında bile değildin 

boynunu büktüğün o an

rüzgarın tenimi kesmesi gibi

kesmişti benliğimi

öptüğümde seni

geri isterdin öpücüklerimi

ağlardın

çoraplarını yıkamıştın bir gün

maşrapada 

boyun kadardı maşrapa

resim çekmeyi severdin

annenle ben yanyanaysak bir resimde

bilesinki denklanşörde sen vardın

yıldızlar altında da biz 

türküler söylerdik çığlık çığlığa 

en çokta senin sesin çıkardı

bütün türküleri bilirdin neredeyse

Ankara''da öğretmenler gününde

Ahmet Telli dinlemişti 

sen türkülerini söylemiştin

“Ver elini ver bana Eftelya''

tüm öğretmenler seni dinlemişti

yollar seni bana getirmişti

bende yollara kapılıp sana gelmiştim

işte böyle yavrucağım.

bir doğum gününü daha kutladık

11 diyorsun yaşına 

büyümeyi bu kadar isteme

bebeğim

çocukluğunu yaşa

en güzel resimleri çekerek

en güzel türküleri söyleyerek

en güzel kemanı çalarak

ve 

en güzel resimi çizerek

doğum günün kutlu olsun aşkım

Hoşgeldin 

DÜNYAMIZA

Bir daha', 'Sana sorduk mu dünyaya getirirken gelmek istermisin diye sanırım hayır bana da sormamışlardı şimdi sen 10 yaşına giriyorsun ben ise 32ye doğ...', ARRAY['Türk Edebiyatı','Şiir','Murat Tali']::text[], 8.5, '{"poet":"Murat Tali","poet_slug":"murat-tali","theme":"Türk Şiiri","is_hero":false,"total_lines":89,"source_url":"https://www.antoloji.com/dogum-gunu-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiçek', 'cicek-melek-midikoglu-azqch', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gün gelecek diye açtı çiçek

Geldiyse kaldı güneşsiz tek

Yağmurlar yağdı yapraklarına

Köklerini kopardılar 

Toprakla birbaşına

Ağla çiçeğim ağla

Akar gider umutların 

açılırsın.', 'Gün gelecek diye açtı çiçek Geldiyse kaldı güneşsiz tek Yağmurlar yağdı yapraklarına Köklerini kopardılar  Toprakla birbaşına Ağla çiçeğim a...', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/cicek-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Duyurabilsem Şiirimi (Öğretmen Aziz Sivaslıoğlu''na)', 'bir-duyurabilsem-siirimi-ogretmen-aziz-sivaslioglu-na-melek-midikoglu-u479a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevgili öğretmenim 

ilkokul öğretmenim

(Seni ben pek çok pek çok severim) 

Sen Kartal''a gitmiştin

Biz Şirintepe''de kaldık

Sen gittin diye

Sınıfta çok ağladık

O güneşli günde

Gözlerimi görüpte

''Ne güzel'' deyişin

Hep hatırımda

Ve o hikayelerin..

Seni bulmak isterim

Elini öpmek, nafile

Bir duyurabilsem şiirimi

Bir öpebilsem elini

Dünyalar benimdi

Bayramlardaki gibi..', 'Sevgili öğretmenim  ilkokul öğretmenim (Seni ben pek çok pek çok severim)  Sen Kartal''a gitmiştin Biz Şirintepe''de kaldık Sen gittin diye Sı...', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-duyurabilsem-siirimi-ogretmen-aziz-sivaslioglu-na-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Benimle*', 'gel-benimle-melek-midikoglu-s5uon', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bugün mutlu değilim

Sende benim gibisin

Biliyorum canım...

Sende benim gibisin

O halde gel benimle! 

Mutluluklar bizim olsun

Dağıtalım dünyayı karış karış

Deliler gibi gülelim, ağlayalım

Sevelim canım doyasıya

Sevilelim canım ölesiye

Hadi benimle gel canım

Korkma yaklaş yalnızlığınla

Unut bütün kederleri, mesafeleri

Bitirelim bu yalnızlıkları

Hayat acı diyenlere

Oturup kederlenenlere

Tadını gösterelim canım

Kıskansınlar, istesinler

Onlarda yaşama gülümsesinler

Tıpkı ikimiz gibi...', 'Bugün mutlu değilim Sende benim gibisin Biliyorum canım... Sende benim gibisin O halde gel benimle!  Mutluluklar bizim olsun Dağıtalım dünya...', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gel-benimle-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alnıma Yaz (Güfte)', 'alnima-yaz-gufte-melek-midikoglu-s3hcx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Öyle bir duygu içindeyim ki, yanıyorum

Seviyorum diyemedim eriyorum

Kaderimden seni dileniyorum, istiyorum

Allahım ne olur onu alnıma yaz

Herşeyim sensin, sevgilimsin

İçtiğim bu gibi sular gibisin

Dünyamı aydınlatan güneş gibisin

Karanlığa bırakıpta nasıl gidersin 

Gözlerime bakıpta seviyorum demeden

Yüreğimi yakıpta gidiyorum demeden

Bırakıp gidemezsin canımı almadan

Canım canına kurban olsun...', 'Öyle bir duygu içindeyim ki, yanıyorum Seviyorum diyemedim eriyorum Kaderimden seni dileniyorum, istiyorum Allahım ne olur onu alnıma yaz He...', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/alnima-yaz-gufte-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '.anneciğim', 'annecigim-melek-midikoglu-z5ewn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İçimde bir korku var anneciğim

Gitme bırakma ayrılma benden

Dünya denilen bu yerde uyumuş kalmışım

Ne olur uyandır, uyandır beni anneciğim

Hasretinle dalgalarım çarpışıyor

Sakın bırakma beni kal kal anneciğim

Dünya denilen bu yerde uyumuş kalmışım

Ne olur uyandır, uyandır beni anneciğim

Ben kimim, nerdeyim, ne için buradayım bilmem

Ben seni bilirim, sensizliğe yanarım

Dünya denilen bu yerde uyumuş kalmışım

Ne olur uyandır, uyandır beni anneciğim', 'İçimde bir korku var anneciğim Gitme bırakma ayrılma benden Dünya denilen bu yerde uyumuş kalmışım Ne olur uyandır, uyandır beni anneciğim H...', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/annecigim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Yüzlüm (Düet/Güfte)', 'guzel-yuzlum-duet-gufte-melek-midikoglu-xwb0b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen benim en güzel şarkımsın

Sende benim kara sevdalımsın

Damarımda dolaşan kanımsın

Biricik sevdiğim sevdalımsın

Gül çiçeğim melek yüzlüm

Selvi boylum elâ gözlüm

Sen benimsin, bende senin

En güzel şarkı bu bizim olsun

Yudum yudum tek sevdamsın

Sen gönlümde ilk baharsın

Hiç solmayan tek goncasın

Biricik sevdiğim sevdalımsın', 'Sen benim en güzel şarkımsın Sende benim kara sevdalımsın Damarımda dolaşan kanımsın Biricik sevdiğim sevdalımsın Gül çiçeğim melek yüzlüm S...', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/guzel-yuzlum-duet-gufte-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karınca', 'karinca-melek-midikoglu-ohn0g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu ne telaş? 

Ne bu çaba

Bu dünya 

Ölümlü dünya

Karınca! 

Bu ne telaş

Ne bu çaba', 'Bu ne telaş?  Ne bu çaba Bu dünya  Ölümlü dünya Karınca!  Bu ne telaş Ne bu çaba...', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/karinca-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara', 'kara-melek-midikoglu-2eln8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözün kara

Saçın kara

Gönlün kara

...Hadi bırak bütün bunları

Hiç değilse dünyamı karartma!', 'Gözün kara Saçın kara Gönlün kara ...Hadi bırak bütün bunları Hiç değilse dünyamı karartma!...', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kara-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Telkin', 'telkin-melek-midikoglu-eh57j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşık olmadın ki sen! 

Öyle sanıyorsun o kadar! 

Hem sen hiç 

Aşık olmazdın zaten! 

Gördüğün bir hayaldi! 

İçin gitti... 

Özlediydin... 

Sevdiydin... 

Unut gitsin!', 'Aşık olmadın ki sen!  Öyle sanıyorsun o kadar!  Hem sen hiç  Aşık olmazdın zaten!  Gördüğün bir hayaldi!  İçin gitti...  Özlediydin...  Sevd...', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/telkin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eksi-Ma', 'eksi-ma-melek-midikoglu-dsuyw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dur yaklaşma

Volkanlar türedi ovalarda bugün

Köylüler dedi yoktu önceki gün

Dur yaklaşma 

Irmaklar taştı çayırlara bugün

Kuşlar dedi yoktu önceki gün

Dur yaklaşma

Karın olduğum gün

Kalbim dedi boştum tüm önceki gün

Dur 

Yaklaş', 'Dur yaklaşma Volkanlar türedi ovalarda bugün Köylüler dedi yoktu önceki gün Dur yaklaşma  Irmaklar taştı çayırlara bugün Kuşlar dedi yoktu ö...', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/eksi-ma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün', 'bugun-melek-midikoglu-skn1r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bugün ölmek var

Dönülmek var

Katran karanlığında

ruhu teslim edip

kuru aş''ı kemirmek var

Bugün içimde

Yılmak var

Yılmanın o acısını

Baharat keyfinde 

almak var

Bugün ne var ki

dünden tatlı', 'Bugün ölmek var Dönülmek var Katran karanlığında ruhu teslim edip kuru aş''ı kemirmek var Bugün içimde Yılmak var Yılmanın o acısını Baharat ...', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bugun-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fıttırık''tan', 'fittirik-tan-melek-midikoglu-8q6cc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sana bugün şiir yazmadım mı

Okyanuslara aşkımı sermedim mi

Rüzgârla boynuna sarılmadım mı

Olmadı mı

Sağır sultan bile duydu

Hala anlamadın mı

Ne dersem diyeyim inanma

Kalbim açılmamış bir gonca', 'Sana bugün şiir yazmadım mı Okyanuslara aşkımı sermedim mi Rüzgârla boynuna sarılmadım mı Olmadı mı Sağır sultan bile duydu Hala anlamadın m...', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/fittirik-tan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Daha Çok', 'daha-cok-melek-midikoglu-9sulb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bugün dünden daha güzelsin 

Saçların ipek gözlerin parlak 

Bugün dünden daha tatlısın 

Dilin şeker gönlün çeker 

Bugün dünden daha sevimlisin 

Beni de daha da çok seversin', 'Bugün dünden daha güzelsin  Saçların ipek gözlerin parlak  Bugün dünden daha tatlısın  Dilin şeker gönlün çeker  Bugün dünden daha sevimlisi...', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/daha-cok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yudum', 'bir-yudum-melek-midikoglu-wtn65', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Toprak mı geldi gözüne yolcu 

Bura tarla ürün verecek ama 

Sen tozlu yollardan gelip 

Çimenlerde temizlendin 

O çimenler nereden geldi 

bilemedin 

Kızarmısın toprağa 

Yeme ekmek o zaman, Su da içme 

Su başında bekleyen kızı 

Ve eşekçi amcayı 

Tekmeleme 

Susuz kalırsın 

Kurur kurur 

Bir yudum sevgi bulamazsın', 'Toprak mı geldi gözüne yolcu  Bura tarla ürün verecek ama  Sen tozlu yollardan gelip  Çimenlerde temizlendin  O çimenler nereden geldi  bile...', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bir-yudum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Güzel', 'ne-guzel-melek-midikoglu-w0nij', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Pencereden bir rüzgar

Ilık sesli bir ezan

Gecenin rengi ne güzel

Dualarım sana Rabbim

Varlığını bilmek

Ve yönelmek ne güzel

İnsan olmak ne güzel

Aşk ne güzel', 'Pencereden bir rüzgar Ilık sesli bir ezan Gecenin rengi ne güzel Dualarım sana Rabbim Varlığını bilmek Ve yönelmek ne güzel İnsan olmak ne g...', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ne-guzel-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tık''la', 'tik-la-melek-midikoglu-glbvm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tık tık tık

Sesin gelir, 

yol uzak...

İşler tımtıkır

lakin yüregin, 

bakır.

Neredesin? 

Mesafeleri kır', 'Tık tık tık Sesin gelir,  yol uzak... İşler tımtıkır lakin yüregin,  bakır. Neredesin?  Mesafeleri kır...', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/tik-la-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecekere', 'gecekere-melek-midikoglu-fdqrm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gecekere gel... 

Yağmurların sesi seni müjdeler, 

Yollar bekler bekler, yolculara kükrer. 

Işığın ötesini sorma, orada sen varsın. 

Ohh be.. 

Dostlarla toplanıp iki çift lafı huzurla konuşabilmek 

ve sevdiğini gecekere sevebilmek... 

Yeni sevgili aramamak; 

Cennet ne diye sorma, 

yalnız bırakmamak yalnız kalmamak, 

değer bilmek ve bilinmesi, 

işte sevgi işte cennet. 

Hür konuşmak da bir cennet öyle değil mi. 

Sen onu bunu küp''e at ama esas gecekere gel, 

Ömürkere kal...

göreceksin yıldızları çok yakınında...', 'Gecekere gel...  Yağmurların sesi seni müjdeler,  Yollar bekler bekler, yolculara kükrer.  Işığın ötesini sorma, orada sen varsın.  Ohh be.....', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gecekere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Getireceğim', 'getirecegim-melek-midikoglu-4f0f8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kış geldi

Kış geldi baharlara salkımlar yerlere düştü

Gözyaşları akmaz, diller konuşmaz oldu

Kış geldi çiçeklere ovalara yazlara

Üzülme

Üzülme çiçek ruhlu güzel kelebek

Üzülme bahar rüzgarlarını getireceğim

Getireceğim kalbimle sana güneşler

Orman kokusunda dans ile...

Akşamlar

Akşamlar gelecek 

Akşamlar günlerimize bal şeker ekecek

Sesler

Sesler yakında, can çeker amaaa

Tutmak istersin tutulmaz, 

Tutulmaz da hasrete hançer olur ah

Az bekle	

Az bekle sana baharları getireceğim, sana yazları

Deliler gibi öfkeyi bağırmayı, kahkahayı

Sana sevdayı getireceğim

	

Geldim

Aç kapını', 'Kış geldi Kış geldi baharlara salkımlar yerlere düştü Gözyaşları akmaz, diller konuşmaz oldu Kış geldi çiçeklere ovalara yazlara Üzülme Üzül...', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/getirecegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel', 'gel-melek-midikoglu-wzbnn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Turuncular senin olsun

Ver bana şekerimi

Limon sarısı düşlerimi

Kalbine sorarım

Turuncular bizim olsun

Gönlümde bir taht kuruldu

Üzerinde 

Kalbim vuruldu

Gel...

Sana turuncular vereceğim', 'Turuncular senin olsun Ver bana şekerimi Limon sarısı düşlerimi Kalbine sorarım Turuncular bizim olsun Gönlümde bir taht kuruldu Üzerinde  K...', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gel-56-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanki Sendi', 'sanki-sendi-melek-midikoglu-c8pmq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Penceremden mavimsi ışık

Sanki seni getirdi

Gülümsedi kalbim

Gökyüzünde hilal ay

Bir göründü bir kaçtı

Öptüm onu sanki sendi

Yaramaz ay gülümsedi...', 'Penceremden mavimsi ışık Sanki seni getirdi Gülümsedi kalbim Gökyüzünde hilal ay Bir göründü bir kaçtı Öptüm onu sanki sendi Yaramaz ay gülü...', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sanki-sendi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklemesen', 'beklemesen-melek-midikoglu-86d2s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Akşamüstü yağmur yağınca 

Leylaklar sürünüp sahile gel 

Suyun şiddetinde bir nefes al 

Bir nefes ver 

Göreceksin kendi canını 

Canlanmayı 

Sen hiç sarıldın mı, sardunyalar gibi 

Sarılmadın.. 

Onlar sarılmaz ki sarmaşıklar gibi 

Hemen inandın 

Düşünme sen, yine gel sahile 

Dalgaları ellerinle sev 

Denize girmek mi bu havada? 

Yüzüne dökülürcesine çarpsa sular 

oh ne ala 

Ya da ben dalsam 

Sesini duysan suların 

Çekirdeksiz nar gibi tatsan akşamı 

Beklemesen...', 'Akşamüstü yağmur yağınca  Leylaklar sürünüp sahile gel  Suyun şiddetinde bir nefes al  Bir nefes ver  Göreceksin kendi canını  Canlanmayı  S...', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/beklemesen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Susuzluktan', 'susuzluktan-melek-midikoglu-tf8gg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'SUSUZLUKTAN YAZAMADIYDIM, 

Akıyorum yağmurla sana, kalbi gül''üm 

Gözlerindeki nemi sakla rüzgardan 

İçerinde kalayım 

CANIM... 



Rüzgar vursun seni bana

Ben toprağa... 

Duysun evren en melodik çığlığını 

Duysun da 

Bahanesiyle ben de duyayım 

SANA YANDIYDIM!', 'SUSUZLUKTAN YAZAMADIYDIM,  Akıyorum yağmurla sana, kalbi gül''üm  Gözlerindeki nemi sakla rüzgardan  İçerinde kalayım  CANIM...  Rüzgar vursu...', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/susuzluktan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vur Yüreğime', 'vur-yuregime-melek-midikoglu-3uo2a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yağ hadi yağ gölgeme 

Vur yüreğime sesinle 

Vur 

Dolunaylı geceden daha tatlısın 

Renginle 

Verdiğinle 

Cesaret et gel 

Bağır öfkelen, Hadi bağır 

Sana doyamadım, sesini duyamadım 

...Sesine doyayım 

Vur yüreğime sesinle vur', 'Yağ hadi yağ gölgeme  Vur yüreğime sesinle  Vur  Dolunaylı geceden daha tatlısın  Renginle  Verdiğinle  Cesaret et gel  Bağır öfkelen, Hadi ...', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/vur-yuregime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Takılma', 'takilma-melek-midikoglu-dhfa9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bugün ağladım sana

Şarkı sözleri sevdi, 

öptü kalbimi ve seni anlattı

Nafile yoktun... 

Ellere sordum

Gözlere sordum

Yürekler bekle dedi; 

''Gitme çakıl taşlarına,

Dalga yakında gelecek'' 

Hey dalga! 

Salınma denizde

Ya o balıklar 

Oyalamasın seni.', 'Bugün ağladım sana Şarkı sözleri sevdi,  öptü kalbimi ve seni anlattı Nafile yoktun...  Ellere sordum Gözlere sordum Yürekler bekle dedi;  ''...', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/takilma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adını Bilseydim', 'adini-bilseydim-melek-midikoglu-rdhut', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Rüzgarın deniz kabuğundaki seslenişine

Bir de vişne reçeli kattım

Kulağınla duy, dilinle tat diye..

Adını bilseydim adını

Yüreğine yazardım aşkımı

Sağır Sultanım özledim seni

Neredesin', 'Rüzgarın deniz kabuğundaki seslenişine Bir de vişne reçeli kattım Kulağınla duy, dilinle tat diye.. Adını bilseydim adını Yüreğine yazardım ...', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/adini-bilseydim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karakalem Dostluklar', 'karakalem-dostluklar-i-brahim-bayraktar-aqad7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kaldı mı o eski dostluklar? 

Eski aşklar.

Satır aralarına sıkıştırılmış, 

Menfaatleri düşünmeden; 

Olabildiğince özgür, 

Alabildiğince içten.

Şimdiki dostluklar

yapmacık, 

Şimdiki dostluklar, 

Çalakalem, 

Karakalem...

Aşklar da öyle...

Neymiş? Mantık evliliği; 

Mantıksızsa, 

Evlenme kardeşim...

Açıkça söyleseler ya, 

Menfaat evliliği, 

Menfaat evliliği...

23.06.2003', 'Kaldı mı o eski dostluklar?  Eski aşklar. Satır aralarına sıkıştırılmış,  Menfaatleri düşünmeden;  Olabildiğince özgür,  Alabildiğince içten...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Bayraktar']::text[], 8.5, '{"poet":"İbrahim Bayraktar","poet_slug":"i-brahim-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/karakalem-dostluklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biricik', 'biricik-melek-midikoglu-na7cu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen bir çiçek gibisin

pembe bir gelincik

ve en güzel en güzel

biricik

kaybolduğum yollarda

yol gösteren pırıltı

küçük suskun bir yıldız

biricik

gözlerin gözlerimde

kulağımda pembe sesin

kuşlar uçardı gönlümde

sevinirdim

biricik

gözlerinde hüzünü okurdum

birşey diyemezdim bilirsin

donuk bir gülümseyişten başka

yıldızlar kayardı kalbimde

her şey yapraklar gibi dökülürdü

suskun gizli ağlardım

biricik

istemezdim gözlerin kızarsın

ağlayasın

sen pembe kartanesisin

sıcak kalbimde eriyen

saçlarımda kirpiklerimde

ellerimde eriyen

sevgilimsin

biricik

sana mavi çiçekler verseydim

yakalarına papatyalar taksaydım

hayır hayır bütün yıldızları

yetmezdi

biricik

...', 'Sen bir çiçek gibisin pembe bir gelincik ve en güzel en güzel biricik kaybolduğum yollarda yol gösteren pırıltı küçük suskun bir yıldız biri...', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/biricik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HAYAL- GERÇEK- DOST', 'hayal-gercek-dost-fatma-ful-ozok-q1oj3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir dost istedim yukarıdan

Pek çok verdi yaradan..

Sevindim, uzattım yüreğimi

Farkettim sonra, yıpratmışlar..

Yüzlerine baktım, 

Maske takmışlar..

Çıkarmak istedim, 

Yüzlerine yapıştırmışlar..

Bir dost buldum görünmeyen, 

Varlığını hissettiren..

Uzanıp tuttum elini, 

Isıttı ellerimi..

Baktım hayal yüzüne, 

MASKESİZDİ..

Dokundum yüreğine, 

‘O’ gerçekti..

(Dostların en gerçeğine....)', 'Bir dost istedim yukarıdan Pek çok verdi yaradan.. Sevindim, uzattım yüreğimi Farkettim sonra, yıpratmışlar.. Yüzlerine baktım,  Maske takmı...', ARRAY['Türk Edebiyatı','Şiir','Fatma Ful Özok']::text[], 8.5, '{"poet":"Fatma Ful Özok","poet_slug":"fatma-ful-ozok","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hayal-gercek-dost-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Halikarnas''ta Bir Sabah', 'halikarnas-ta-bir-sabah-naime-erlacin-kky0k', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'günışığı düşerken uyku kaçkını saatlere

yabansı aşklar izledim

ellerimdeydi dünya keşişhane tepesinde

koyları gözledim

terk edilmişlerdi yapayalnız 

yıldızlı gecelerden karanlığa geçtiler

tez solardı erken açan çiçek

nereye gitti kovuğunda güller açan kent

dirim suyu çekildi yaşamsal kanalların 

uğraksız dağ yollarında

yavaş yavaş indi ışıklar 

uykuda bir yanardağ misali sessiz

akşamdan yorgun

Halikarnas’ta bir sabah yaz fırtınası kadar hızla sustu gün

(23 Haziran 2003)', 'günışığı düşerken uyku kaçkını saatlere yabansı aşklar izledim ellerimdeydi dünya keşişhane tepesinde koyları gözledim terk edilmişlerdi yap...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/halikarnas-ta-bir-sabah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamaya Bak', 'yasamaya-bak-murat-demir-2911a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Pişman olmak neye yarar, olan olmuşsa

Üzülmekle ne deyişir, kaderin buysa

Senin için bir güzellik, oluşmuyorsa

Bırak gitsin, oluruna, yaşamaya bak

Nasıl olsa, bu hayatın sonu gelecek

Her gün, her an, olmazsada, gönül gülecek

Ama senle, ama sensiz, yaşam sürecek

Fırsat varken, bulduğunla, yaşamaya bak

Bazen güler, bazen ağlar, insan dediğin

Bir bakarsın elin olmuş, candan sevdiğin

Bu hayatın cilvesidir, hiç bilmediğin

Bildiğinle yetinerek, yaşamaya bak

Eller elden üstün olur, bunu bil yeter

Farklı, farklı, bu evrende, herkes dert çeker

Bu acılar, bazen hafif, bazende beter

Olsa bile acılarla, yaşamaya bak', 'Pişman olmak neye yarar, olan olmuşsa Üzülmekle ne deyişir, kaderin buysa Senin için bir güzellik, oluşmuyorsa Bırak gitsin, oluruna, yaşama...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yasamaya-bak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstisna', 'i-stisna-ali-ayyildiz-7fpmg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben hariç herkes tanıyor beni

Tanımadım bunca yıl; bir ben kendimi...', 'Ben hariç herkes tanıyor beni Tanımadım bunca yıl; bir ben kendimi......', ARRAY['Türk Edebiyatı','Şiir','Ali Ayyıldız']::text[], 8.5, '{"poet":"Ali Ayyıldız","poet_slug":"ali-ayyildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/istisna-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutuldum', 'unutuldum-abdulkadir-karaman-14f6p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne arayan var, ne soran? 

Bir köşede unutuldum.

Seven kâlbim oldu vîran

Bir köşede unutuldum! 

Derdim azar yavaş yavaş

Gözlerime dizilir yaş

Ne bir dost var, ne arkadaş

Bir köşede unutuldum! 

Umularla biter ömür

Canım özlemlerle çürür

Her âzamı hüzün bürür

Bir köşede unutuldum! 

Yalnızlığa duçâr oldum

Hasret ile nâçar oldum

Kendimden de kaçar oldum

Bir köşede unutuldum! 

Küle döndüm yana, yana

Gelmez, bittim ana, ana

Sevemedim kana, kana

Bir köşede unutuldum! 

Ne bir haber, ne selam var

Har ân figan, her an gam var

Bir yâr demedi bana yâr

Bir köşede unutuldum! 

İçim harâbeye döndü

Sevdâmın alevi söndü

Canım hüzünle büründü

Bir köşede unutuldum! 

Belirsiz derdimin nevî

Vîrâne muhabbet evi

İçimde vuslat alevi

Bir köşede unutuldum! 

1984 Elazığ', 'Ne arayan var, ne soran?  Bir köşede unutuldum. Seven kâlbim oldu vîran Bir köşede unutuldum!  Derdim azar yavaş yavaş Gözlerime dizilir yaş...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir Karaman']::text[], 8.5, '{"poet":"Abdulkadir Karaman","poet_slug":"abdulkadir-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/unutuldum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Divana Kalsın', 'divana-kalsin-emin-cebe-67ax1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Henüz gençliğine doymadan daha, 

Yeşillendi sevda ovamız bizim.

Ellerimi açıp yalvarmadan Allah’a

Islandı, puslandı havamız bizim.

Ülkü gençliğimin gönül sancısı.

Yürekte küllenmiş ölüm acısı.

Yüzü ak duvaklı gelin bacısı; 

Dedi ki: “Nerede yuvamız bizim? ”

Ülkü yolunda çağlayıp çoşanlar; 

Kabına sığmayıp, nefsini aşanlar; 

Uçmağa vardı en önde koşanlar.

Ruhuna Fatiha duamız bizim.

Ülküdaş girince kara yerlere, 

Bittim bıyığından akan  terlere.

Ölüm yakışmasa da bu erlere, 

Şehittir oğlumuz, paşamız bizim.

Ülkü serap olmuş, aldatır kaçar. 

Yaklaştıkça...uzaklaşır el açar.

Uzaklaştıkça yaklaşır gül saçar

Hayalle koşar sevdamız bizim.

Ülkü gelin olmuş, ellere tutsak, 

Ilgıt ılgıt esen  yellere tutsak, 

Pelesenk vurulmuş dillere tutsak.

Esarete isyan kavgamız bizim.

Başbuğun ömrü menzile yetmedi.

Sabrı yüklendi, zevki dert etmedi.

Yeni yetmelerle  ocak tütmedi.

Bozuldu töremiz, yasamız bizim.

Harikler erkek kesilirse başa; 

Başını vurursun taşlardan taşa.

Bu yolda harcanan genç yaşa.

Karalar bağlasın anamız bizim.

Emin ol, kader kısmet belli oldu.

Yıllar geçip gitti, yaş elli oldu

Tuğrul yetişti, tek teselli oldu.

Ol divana kalsın davamız bizim.

23 Nisan 2002- Bahçelievler/Ankara', 'Henüz gençliğine doymadan daha,  Yeşillendi sevda ovamız bizim. Ellerimi açıp yalvarmadan Allah’a Islandı, puslandı havamız bizim. Ülkü genç...', ARRAY['Türk Edebiyatı','Şiir','Emin Cebe']::text[], 8.5, '{"poet":"Emin Cebe","poet_slug":"emin-cebe","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/divana-kalsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Okumayacaksın', 'okumayacaksin-sair-khan-jw9v4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Evet gidiyorum bu sefer kararım kesin, ne gözlerimdeki yaş engel olabilecek, 

Ne de gitmemekte direnen ayaklarım...

Sana ve sevdama dair yalnızca bir şiir, bir mektup yazıyorum

Okunup okunmayacağı meçhul ardımdan, 

Ve birde tükenmeyen sevdamı...............

Bilmiyorum okunmayacak belki de bu şiir ya da mektup, 

Ama yine de yazıyorum. Herhalde okunmayacak, çünkü göndermeyi düşünmüyorum, 

Belki masamın çekmecesinde, Belki giymediğim gömleğin cebinde, belki yastığımın kılıfında

Belki bir sandığın diplerinde bulacaklar yıllar sonra.

Kimi bu bir aşk şiiri diyecek, kimi mutlulukla acı karışımıyla dopdolu bir şiir... 

Kimi cümlelerin içtenliğine bağlanacak, 

Kimi beynimde yüreğimdeki fırtınaların acımasızlığında hoyratlığından irkilecek...

Eski  sararmış kâğıt olacak şu an elimde tuttuğum kâğıt şüphesiz.

Bazı harfler okunmayacak, Silik ifadeler, bazı soru işaretleri ve noktalar

Kimi sorgularım yargı, kimileri infaz gibi anlaşılacak. 

Bazı  noktalarım da silinecek benim gibi, Bitmemiş cümleler kalacak yıllar sonraya, 

Bugün bitirdiğimi sandığım pek çok hatıradan geriye... Eğer okunursa bu yazdıklarım

Tek anlayacakları sana olan aşkım limitsiz sevdam olacak.

En çok da seni, mutlaka seni merak edecekler.Seni ve sana olan aşkımı.. 

Benim kendimi suçlayan ifadelerimden dolayı belki bana acıyanlar çıkacak.

Ama Senin ne denli güzel olduğuna hükmedecekler.

Seni nasıl sevdiğimi tartışmayacaklar bile. 

Nasıl yandığımı, nedenli büyük olduğunu sevdamın tartışma konuları olacak...

Ama senin beni sevip sevmediğin konusunda birbirlerine girecekler.

Kimi o daha çok seviyor diyecek kimi azımsayacak anlayamayacaklar anlamayacaklar, 

Tıpkı her insan gibi..Belki Sen de  okuyamayacaksın, ama okuyacakmışsın gibi yazıyorum 

Yok ama sen  Okuyamayacaksın, çünkü göndermeyeceğim ki.

Yazdıktan sonra yırtıp atmayı da düşünmüyor değilim. 

Yakmak, aklımdaki bir başka çözüm. Ama hayır, saklayacağım. 

Okumayacak olsan da kelimelerimi sevdiğini biliyorum. 

Sevdiğin için, benim sana bir şeyler yazdığımı hissedeceğini biliyorum. 

Ben yazarken içinin ürperdiğini, gülen yüzünün hüzünlendiğini, 

Kalbinin nasıl sertçe, durmaksızın attığını hissediyorum. 

Belki sırf bu yüzden yazıyorum. Yazmıyorum da sanki sana dokunuyorum. 

Sanki kâğıdı katlamıyor, sana sarılıyorum. 

Mektubu saklamıyorum da sanki senin efsaneni senin türkünü söylüyorum.

Seni seviyorum; Hayır göndermeyeceğim. Bu mektubu okuyamayacaksın.

Çünkü ben ne istediğini artık bilemeyen biriyim. Ayaklarım yere sağlam basmıyor  Kararlılıklarım çoktur, asla ama asla diyeceğim prensiplerim de kalmadı. 

Bu mektubu göndermeyeceğim. Çünkü ben yokum. Ben benliğim içerisinde kayboldum Arda kalan sadece sen ve efsanen... 

Efsanen...Sana yollamayarak  haksızlık ettiğim düşüncesi kafamda oluşmaya başladı, 

Haksızlık mı gerçekten? Evet zannederim öyle yollamalıyım ve okumalısın okunmalı

Göndereceğim galiba..Sende herkes gibi okuyacaksın... 

Böyle bir efsane asla saklı kalmamalı bence, Belki de ait oldukları dillere masallara yerleşmeli..

Tüm büyük aşk literatürlerine girmeli, ders olarak okutulmalı, 

Herkes bilmeli esmer gecelerin gülünün yüzünde açan goncaların güzelliğini..

Herkes beş yıldızın ne anlama geldiğini duymalı, 

Bir gözün nasıl kamaştıran parlaklığa sahip olduğunu duymalılar, 

Böyle bir güzellikten haberleri olmalı, 

Bilmeli herkes o gecelere aşık olan, maşukuna her salise yanan insanın sevdasını..

Bilmeliler ve öğrenmeliler kaybolan benliklerin sevda için çektiği acıları, 

Bilmeliler yoğruldukları un ufak oldukları hayat teknesini..', 'Evet gidiyorum bu sefer kararım kesin, ne gözlerimdeki yaş engel olabilecek,  Ne de gitmemekte direnen ayaklarım... Sana ve sevdama dair yal...', ARRAY['Türk Edebiyatı','Şiir','Şair Khan']::text[], 8.5, '{"poet":"Şair Khan","poet_slug":"sair-khan","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/okumayacaksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kız Delirdim', 'kiz-delirdim-murat-demir-m8ab9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ağlamakla geçti ömrüm

Yar sensiz diye

Gece gündüz hayallerle

Döndüm deliye

Kız delirdim, delirdim

Seni benim bilirdim

Ellerimden tutsaydın

Çok sevinirdim

Şu gökteki yıldızlardan

Daha güzelsin

Gündüz, güneş, geceleri

Aya benzersin

Ben gariban biriyim

Sensiz gülemem

Göz yaşlarım sel olmuş

Sensiz silemem

Kız delirdim, delirdim

Seni benim bilirdim

Ellerimden tutsaydın

Çok sevinirdim', 'Ağlamakla geçti ömrüm Yar sensiz diye Gece gündüz hayallerle Döndüm deliye Kız delirdim, delirdim Seni benim bilirdim Ellerimden tutsaydın Ç...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kiz-delirdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acılar', 'acilar-sadik-altinkaynak-1x0fa', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her yürekte yan yanadır 

Sevinçler ve acılar

Büyük doğumların habercisidir

Büyük sancılar

Acıların en beteri

İçi yanarken susmakmış

Acı çekebilmenin şartı

Cesur olmakmış

Büyük iş yapanlar

Büyük acı çekerler

Acılar davetsiz gelirler

Acı çekenin halini

Acı çekenler bilirler

Acı bazen ustadır eğitir insanı

Bazen değirmendir öğütür insanı

Tatlı bir yanı da var bazı acının

Genelde korkutur ürkütür insanı

Çeşit çeşittir acılar

Acıların en tatlısı isot acısıdır

En acısı –Allah vermesin- Evlat acısı

En unutulmazı kuyruk acısı

En asili aşk acısı

En yakıcısı hasret acısı

En zora gideni ihanet acısı...

Acının zevali lezzet

Lezzetin zevali acıdır

Sevmek tüm acıların ilacıdır.', 'Her yürekte yan yanadır  Sevinçler ve acılar Büyük doğumların habercisidir Büyük sancılar Acıların en beteri İçi yanarken susmakmış Acı çeke...', ARRAY['Türk Edebiyatı','Şiir','Sadık Altınkaynak']::text[], 8.5, '{"poet":"Sadık Altınkaynak","poet_slug":"sadik-altinkaynak","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/acilar-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Koşusu', 'hayat-kosusu-sadik-altinkaynak-1fdd0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her sabah yeni bir güneş doğar

Afrika’da

Bir ceylan koşmaya başlar

Aslana yem olmamak için

Her sabah yeni bir güneş doğar

Afrika’da

Bir aslan koşmaya başlar

Ceylanı yakalamak için

İster ceylan ol ister aslan

Herhangi bir canlı ya da insan

Sürekli koşman gerek yaşamak için

Her gün güneş yeniden doğar 

Dünyada

Bir koşuşturma başlar

Bütün canlılar böyle yaşar

Yanlış anlama

“Hayat cidal değil muavenettir”

Aksini düşünmek Yaradan’a ihanettir

Bazen sen rızkına koşarsın

Bazen rızık sana koşar

Ceylan bir aslandan kaçar

Diğerinin sofrasına konar.', 'Her sabah yeni bir güneş doğar Afrika’da Bir ceylan koşmaya başlar Aslana yem olmamak için Her sabah yeni bir güneş doğar Afrika’da Bir asla...', ARRAY['Türk Edebiyatı','Şiir','Sadık Altınkaynak']::text[], 8.5, '{"poet":"Sadık Altınkaynak","poet_slug":"sadik-altinkaynak","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/hayat-kosusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Katil Zaman', 'katil-zaman-kenan-soyalp-1egf5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'uyumaya korkuyordum, 

geceleri. 

rüyamda, 

bir daha seni rüyamda göremiyeceğimi, 

görüyordum. 

ve uyanıyordum sensizliğe, 

tüm sesimle. 

zamana açılan savaştı sensizlik, 

tek başınayken cephede. 

kolumdaki zaman, 

senin kalp atışlarınla çalışıyordu. 

bir trapezcinin dengesini kaybetmesi gibiydi 

zaman,

düştü düşecek altındaki yırtık ağa.. 

ölücek zaman, 

atmayacak kalbin artık. 

yeni bir zaman doğdu. 

ölümünden hemen sonra. 

ağı yırtan, 

doğan zaman.', 'uyumaya korkuyordum,  geceleri.  rüyamda,  bir daha seni rüyamda göremiyeceğimi,  görüyordum.  ve uyanıyordum sensizliğe,  tüm sesimle.  zam...', ARRAY['Türk Edebiyatı','Şiir','Kenan Soyalp']::text[], 8.5, '{"poet":"Kenan Soyalp","poet_slug":"kenan-soyalp","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/katil-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acemi', 'acemi-seyit-ahmet-duzen-ndrs6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Alfabe denizinde 

Harfler en derinde yüzer 

Usta denizcilerdir 

Sevda sözcüklerini yakalayan 

Oltamı salarım 

'''' haydi rast gele...'''' 

Oysa 

Çoktan yazmıştır *Sunay Akın 

Sevgiliye en güzel şiirleri 

Kız kulesinde... 

Bense; 

İçi su dolu kovamda 

Islak harflerimle 

Adını kekelerim sadece 

Denizceler kahvesinde, 

Adını sandalıma yazdığım 

Usta balıkçı; okşayarak saçımı 

İçi kelime dolu 

Kova verir elime 

Der ''''al götür sevgiliye''''', 'Alfabe denizinde  Harfler en derinde yüzer  Usta denizcilerdir  Sevda sözcüklerini yakalayan  Oltamı salarım  '''' haydi rast gele...''''  Oysa ...', ARRAY['Türk Edebiyatı','Şiir','Seyit Ahmet Düzen']::text[], 8.5, '{"poet":"Seyit Ahmet Düzen","poet_slug":"seyit-ahmet-duzen","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/acemi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yetmezmi', 'yetmezmi-murat-demir-kyyze', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Akşam oldu bugün yine

Hasret oldum gözlerine

İnanırım sözlerine

Gel bu kadar yetmezmi

Gelki bıktım beklemekten

Sevdim seni hep yürekten

Bekliyorum çekerekten

Gel bu kadar yetmezmi

Her akşamın sabahında

Her mevsimin baharında

Çektirirsin genç çağımda

Gel bu kadar yetmezmi

Bülbül konmaz viran bağlar

Ne uzundur bitmez anlar

Seni seven gözler ağlar

Gel bu kadar yetmezmi

Vardır belki bir çaresi

Kapanırmı kalp yarası

Bu gönlümün bir tanesi

Gel bu kadar yetmezmi

Feda olsun canım sana

Yakınlaştı ölüm bana 

Hep ağlattın yana, yana

Gel bu kadar yetmezmi', 'Akşam oldu bugün yine Hasret oldum gözlerine İnanırım sözlerine Gel bu kadar yetmezmi Gelki bıktım beklemekten Sevdim seni hep yürekten Bekl...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yetmezmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garip Türküsü', 'garip-turkusu-mehmet-soylemez-py4qr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Düşmüşüm garip bir derde; 

Neyleyim sefayı zan ile; 

Leyle Mecnun''u bilmese bile; 

Garip her daim emre amade...', 'Düşmüşüm garip bir derde;  Neyleyim sefayı zan ile;  Leyle Mecnun''u bilmese bile;  Garip her daim emre amade......', ARRAY['Türk Edebiyatı','Şiir','Mehmet Söylemez']::text[], 8.5, '{"poet":"Mehmet Söylemez","poet_slug":"mehmet-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/garip-turkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mevsim Sen', 'mevsim-sen-filiz-kurun-ueino', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'mevsim kış

sen benimsin

benim için

inci inci inen  kar

mevsim güz

sen benimsin

benim için

sarı sarı dökülen yaprak

mevsim yaz

sen benimsin

benim için

pırıl pırıl parlayan güneş

mevsim bahar

sen benimsin

benim için

yeşil yeşil oluşan  çiçek

mevsim SEN

sen benimsin

benim için

usul usul büyüyen sevgi.

(06.06.2003) Denizli', 'mevsim kış sen benimsin benim için inci inci inen  kar mevsim güz sen benimsin benim için sarı sarı dökülen yaprak mevsim yaz sen benimsin b...', ARRAY['Türk Edebiyatı','Şiir','Filiz Kurun']::text[], 8.5, '{"poet":"Filiz Kurun","poet_slug":"filiz-kurun","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/mevsim-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayalci', 'hayalci-ahmet-gumustekin-610jo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Koca bir hayalciyim ben, 

kaç yaşına gelirsem geleyim, 

hiç farketmez benim için.

Yaşamdaki amacımdır, 

hayallerim! 

Peşine düşmezsem 

yaşayamamki, 

hayallerin!', 'Koca bir hayalciyim ben,  kaç yaşına gelirsem geleyim,  hiç farketmez benim için. Yaşamdaki amacımdır,  hayallerim!  Peşine düşmezsem  yaşay...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Gümüştekin']::text[], 8.5, '{"poet":"Ahmet Gümüştekin","poet_slug":"ahmet-gumustekin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hayalci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alışmak Zor', 'alismak-zor-mehmet-bor-qc1nu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dost, 

Dağlar bir başka bu gün.

Ağaçlar esen hoyrata mahkum.

Kuşlar, darmadağın gökyüzün de, 

Dağların başı dumanlı bu gün.

Dost, 

Bu gün beklesin.

Acışmasın yüreğimiz.

Kor düşmesin yuvaya.

Daha.. kaç gün oldu.? 

Bak.

Küçük Ahmet gideli, 

Ailesi hala yasta.

Dost, 

Alışacaksın.

Yenisin buralarda.

Yola koyulmak, 

Çılgınlık.

Çok zor bu kar da.

Allah var, 

ne diyem.

Yarın, açılır belkim.

Acışmasın yüreğimiz.

Kor düşmesin yuvaya.

Daha kaç gün oldu.? 

Bak.

Küçük Ahmet gideli, 

Ailesi hala yasta.

10.06.2003

Mehmet BOR', 'Dost,  Dağlar bir başka bu gün. Ağaçlar esen hoyrata mahkum. Kuşlar, darmadağın gökyüzün de,  Dağların başı dumanlı bu gün. Dost,  Bu gün be...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bor']::text[], 8.5, '{"poet":"Mehmet Bor","poet_slug":"mehmet-bor","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/alismak-zor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boşluğun Adresi', 'boslugun-adresi-sule-aydemir-ebxnc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'boydan boya bir boşluk 

bırakılmış ruhuma 

yazılmış çizilmiş bir evren 

ve koparılmışlıklar var daha doğarken 

adına aşk demişler 

ben daha bilmeden

ellerimle boşluğu çizmişim 

bilmediğim boşlukta

sızıntısız eksiksiz 

sessizce bir uyum halindeyim

sen

tıpa tıp boşluğuma oturttuğum

hiçe adres verip anlam bulduğum

hiçtim sen oldum

hiçtin ben oldun

hiçtik artık var adresimiz 

hey çıkmaz sokak aşk  biziz', 'boydan boya bir boşluk  bırakılmış ruhuma  yazılmış çizilmiş bir evren  ve koparılmışlıklar var daha doğarken  adına aşk demişler  ben daha ...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/boslugun-adresi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme', 'gitme-birol-ozkan-8em6x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gitme, 

daha güneş doğmadı üzerimizde, 

denize vurmadı ışıklarını.

İlk ışıkla sahil seni bekler, 

seni çağırır martılar

gitme ışıklar sönmesin, 

güneş batmasın üzerimizde.

Gitme, 

en çok martılar üzülür

ve aralarında seni en çok seveni, 

o dayanamaz.

Hatırlar mısın hep o beklerdi sahilde seni? 

sen hiç gelmesen de...

Ona veda etme, 

o da gelir arkandan

denizi olmayan şehire gideceğini bilse de, 

gittiği şehirde yaşayamayacağını bilse de.

Gitme, 

Ayrılma bu şehirden, 

bırakma onca insanı arkanda sensiz, 

sensizliğe en çok o dayanamaz, 

sen varken kimse yoktu onun için, 

kimsesizliği yaşatma ona, 

paylaşamazdı seni kimseyle bilirsin....

ona veda etme..

bilmesin gideceğini, 

arar seni günlerce, aylarca, yıllarca

ayrılığı sevmez bilirsin, 

ayrılmaya dayanamaz, 

ve ayrılamaz da bilirsin....

Gitme, 

bari dostuna söyleme gideceksen, 

onu görmeden git, 

veda etme

sıkıca tut ellerini, 

ama bakma gözlerine, 

ağlamadan git gideceksen....

Gitme, 

en son ben bileyim gideceğini, 

ve bu sonu hiç görmeyeyim

biliyorum ne kadar zor gitmek, 

gidememek

ben sana veda edemedim, 

ben sensiz gidemedim, 

hayatı iki ucundan tutmak zor biliyorum, 

ben tutamadım, 

ben veda edemedim

ben gidemedim, 

ne olur sen de 

Gitme..........', 'Gitme,  daha güneş doğmadı üzerimizde,  denize vurmadı ışıklarını. İlk ışıkla sahil seni bekler,  seni çağırır martılar gitme ışıklar sönmes...', ARRAY['Türk Edebiyatı','Şiir','Birol Özkan']::text[], 8.5, '{"poet":"Birol Özkan","poet_slug":"birol-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/gitme-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
